    </div>    <!-- ======================================================== -->
    <!-- JAVASCRIPT APP LOGIC                                     -->
    <!-- ======================================================== -->
    <script>
        // ========================================================
        // ANDROID 8+ (CHROMIUM 58+) & ES2015 COMPATIBILITY HELPERS
        // ========================================================
        function _el(id) {
            return document.getElementById(id);
        }
        function _val(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value !== undefined) ? el.value : (fallback !== undefined ? fallback : '');
        }
        function _chk(id) {
            var el = document.getElementById(id);
            return el ? Boolean(el.checked) : false;
        }
        function _cls(id, action, clsName) {
            var el = document.getElementById(id);
            if (el && el.classList) {
                if (action === 'add') el.classList.add(clsName);
                else if (action === 'remove') el.classList.remove(clsName);
            }
        }
        function _nn(val, fallback) {
            return (val !== undefined && val !== null) ? val : fallback;
        }
        // IndexedDB Vendor Prefix Fallback for Android 8 WebView
        window.indexedDB = window.indexedDB || window.webkitIndexedDB || window.mozIndexedDB || window.msIndexedDB;

        const state = {
            currentTab: 'pos',
            sidebarCollapsed: (function() {
                try {
                    return localStorage.getItem('esbas_sidebar_collapsed') === 'true';
                } catch(e) {
                    return false;
                }
            })(),
            loggedInUser: null,
            sessionInfo: null,
            sessionTimerInterval: null,
            branches: [],
            currentBranch: null,
            users: [],
            currentUser: null,
            activeShift: null,
            products: [],
            allProducts: [],
            categories: [],
            recipesData: { finished_goods: [], raw_materials: [] },
            selectedCategory: 'ALL',
            searchKeyword: '',
            cart: [],
            paymentMethod: 'CASH',
            cashReceived: 0,
            cashDenominations: [],
            simulatedInsideShop: true,
            // CRM & Pricing Tier Properties
            customers: [],
            selectedCustomer: null,
            selectedCustomerCategory: 'REGULER',
            mitraPrices: [],
            custCategoryFilter: 'ALL',
            custSearchKeyword: '',
            customerActiveSubtab: 'list',
            appliedDiscount: null,
            manualPromoSelected: false,
            discountRulesCache: [],
            discountRuleModeFilter: 'ALL',
            // Expenses & Operating Costs Properties
            expenseSubtab: 'ledger',
            expenseCategories: [],
            // Logistics, Delivery & Courier Fleet Properties
            vehicles: [],
            fuelLogs: [],
            serviceLogs: [],
            currentDeliverySetting: null,
            allDeliverySettings: [],
            currentDeliveryFee: 0,
            currentDeliveryDistance: 0,
            logisticsActiveSubtab: 'vehicles',
            logisticsMap: null,
            mapMarkers: [],
            mapRoutePolyline: null,
            // Customer Geospatial Map Properties
            customerMap: null,
            customerMapMarkers: [],
            customerMapPolyline: null,
            customerSelectedOnMap: null,
            customerPickerMap: null,
            customerPickerMarker: null,
            // Branch Geospatial Map Properties
            branchActiveSubtab: 'table',
            branchMap: null,
            branchMapMarkers: [],
            branchMapCircles: [],
            branchSelectedOnMap: null,
            branchPickerMap: null,
            branchPickerMarker: null,
            branchPickerCircle: null,
            // Executive Dashboard & Real-Time Monitoring Properties
            execSelectedBranchId: 0,
            execStartDate: new Date().toISOString().split('T')[0],
            execEndDate: new Date().toISOString().split('T')[0],
            execAutoRefreshEnabled: true,
            execSoundEnabled: true,
            execAutoRefreshTimer: null,
            execLastMaxSaleId: 0,
            // PWA & Offline-First State Properties
            isOfflineMode: !navigator.onLine,
            offlineSalesPendingCount: 0
        };

        // ========================================================
        // PWA SERVICE WORKER REGISTRATION & INSTALL PROMPT (Android 8+ Compatible)
        // ========================================================
        let deferredPwaPrompt = null;

        function checkPwaInstallVisibility() {
            try {
                const isStandalone = (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) || window.navigator.standalone === true;
                const isMobileOrTablet = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
                const pwaBtn = document.getElementById('btn-pwa-install');
                const sidePwaBtn = document.getElementById('sidebar-btn-pwa-install');
                if (!isStandalone) {
                    if (deferredPwaPrompt || isMobileOrTablet) {
                        if (pwaBtn) {
                            pwaBtn.classList.remove('hidden');
                            pwaBtn.style.display = 'inline-flex';
                        }
                        if (sidePwaBtn) {
                            sidePwaBtn.classList.remove('hidden');
                            sidePwaBtn.style.display = 'flex';
                        }
                    }
                }
            } catch(e) {
                console.warn('Error checkPwaInstallVisibility:', e);
            }
        }

        if ('serviceWorker' in navigator) {
            window.addEventListener('load', () => {
                navigator.serviceWorker.register('sw.js')
                    .then(reg => {
                        console.log('KAD Tech ServiceWorker terdaftar:', reg.scope);
                    })
                    .catch(err => {
                        console.warn('Gagal mendaftarkan ServiceWorker:', err);
                    });
                checkPwaInstallVisibility();
            });
        }

        window.addEventListener('beforeinstallprompt', (e) => {
            e.preventDefault();
            deferredPwaPrompt = e;
            const pwaBtn = document.getElementById('btn-pwa-install');
            if (pwaBtn) {
                pwaBtn.classList.remove('hidden');
                pwaBtn.style.display = 'inline-flex';
            }
            const sidePwaBtn = document.getElementById('sidebar-btn-pwa-install');
            if (sidePwaBtn) {
                sidePwaBtn.classList.remove('hidden');
                sidePwaBtn.style.display = 'flex';
            }
        });

        window.promptPWAInstall = function() {
            if (deferredPwaPrompt) {
                deferredPwaPrompt.prompt();
                deferredPwaPrompt.userChoice.then((choice) => {
                    if (choice.outcome === 'accepted') {
                        const pwaBtn = document.getElementById('btn-pwa-install');
                        if (pwaBtn) pwaBtn.style.display = 'none';
                        const sidePwaBtn = document.getElementById('sidebar-btn-pwa-install');
                        if (sidePwaBtn) sidePwaBtn.style.display = 'none';
                    }
                    deferredPwaPrompt = null;
                });
            } else {
                alert("Petunjuk Pemasangan Web App di Layar Utama (Android 8+ / Tablet):\n\n1. Ketuk ikon menu titik tiga (⋮) di pojok kanan atas browser Chrome / Samsung Internet.\n2. Pilih 'Tambahkan ke Layar Utama' (Add to Home Screen) atau 'Instal Aplikasi'.\n3. Beri nama 'KAD Tech' lalu ketuk 'Tambah' / 'Add'.\n4. Buka aplikasi KAD Tech langsung dari ikon layar utama tablet Anda untuk tampilan penuh mandiri (Standalone) tanpa bilah alamat browser.");
            }
        };

        // ========================================================
        // CLIENT-SIDE INDEXEDDB OFFLINE STORAGE ENGINE (OfflineDB)
        // ========================================================
        // OFFLINE INDEXEDDB & STORAGE PERSISTENCE ENGINE
        // ========================================================
        const OfflineDB = {
            dbName: 'EsbasRetailPosOfflineDB',
            dbVersion: 2,
            dbInstance: null,

            async init() {
                if (this.dbInstance) return this.dbInstance;
                return new Promise((resolve, reject) => {
                    if (!window.indexedDB) {
                        reject(new Error('IndexedDB tidak didukung pada peramban ini'));
                        return;
                    }
                    const req = indexedDB.open(this.dbName, this.dbVersion);
                    req.onupgradeneeded = (e) => {
                        const db = e.target.result;
                        if (!db.objectStoreNames.contains('master_cache')) {
                            db.createObjectStore('master_cache', { keyPath: 'key' });
                        }
                        if (!db.objectStoreNames.contains('offline_users')) {
                            db.createObjectStore('offline_users', { keyPath: 'id' });
                        }
                        if (!db.objectStoreNames.contains('offline_sales')) {
                            db.createObjectStore('offline_sales', { keyPath: 'offline_ref' });
                        }
                        if (!db.objectStoreNames.contains('offline_shifts')) {
                            db.createObjectStore('offline_shifts', { keyPath: 'offline_ref' });
                        }
                    };
                    req.onsuccess = (e) => {
                        this.dbInstance = e.target.result;
                        resolve(this.dbInstance);
                    };
                    req.onerror = (e) => {
                        console.error('IndexedDB open error:', e);
                        reject(e);
                    };
                });
            },

            async setItem(storeName, item) {
                try {
                    const db = await this.init();
                    if (!db.objectStoreNames.contains(storeName)) return false;
                    return new Promise((resolve, reject) => {
                        const tx = db.transaction([storeName], 'readwrite');
                        const store = tx.objectStore(storeName);
                        const req = store.put(item);
                        req.onsuccess = () => resolve(true);
                        req.onerror = (err) => reject(err);
                    });
                } catch (e) {
                    console.warn('OfflineDB setItem error (' + storeName + '):', e);
                    return false;
                }
            },

            async getItem(storeName, key) {
                try {
                    const db = await this.init();
                    if (!db.objectStoreNames.contains(storeName)) return null;
                    return new Promise((resolve, reject) => {
                        const tx = db.transaction([storeName], 'readonly');
                        const store = tx.objectStore(storeName);
                        const req = store.get(key);
                        req.onsuccess = () => resolve(req.result || null);
                        req.onerror = (err) => reject(err);
                    });
                } catch (e) {
                    console.warn('OfflineDB getItem error (' + storeName + '):', e);
                    return null;
                }
            },

            async getAll(storeName) {
                try {
                    const db = await this.init();
                    if (!db.objectStoreNames.contains(storeName)) return [];
                    return new Promise((resolve, reject) => {
                        const tx = db.transaction([storeName], 'readonly');
                        const store = tx.objectStore(storeName);
                        const req = store.getAll();
                        req.onsuccess = () => resolve(req.result || []);
                        req.onerror = (err) => reject(err);
                    });
                } catch (e) {
                    console.warn('OfflineDB getAll error (' + storeName + '):', e);
                    return [];
                }
            },

            async removeItem(storeName, key) {
                try {
                    const db = await this.init();
                    if (!db.objectStoreNames.contains(storeName)) return true;
                    return new Promise((resolve, reject) => {
                        const tx = db.transaction([storeName], 'readwrite');
                        const store = tx.objectStore(storeName);
                        const req = store.delete(key);
                        req.onsuccess = () => resolve(true);
                        req.onerror = (err) => reject(err);
                    });
                } catch (e) {
                    console.warn('OfflineDB removeItem error (' + storeName + '):', e);
                    return true;
                }
            },

            async saveMasterBootstrap(data) {
                if (!data) return;
                try {
                    await this.setItem('master_cache', { key: 'bootstrap_data', data: data, cached_at: Date.now() });
                } catch(e) {
                    console.warn('Gagal menyimpan master bootstrap ke IndexedDB:', e);
                }
                try {
                    localStorage.setItem('esbas_master_bootstrap', JSON.stringify(data));
                } catch(e) {
                    console.warn('Gagal menyimpan master bootstrap ke localStorage:', e);
                }
                if (data.offline_auth_pack && Array.isArray(data.offline_auth_pack)) {
                    for (const u of data.offline_auth_pack) {
                        try {
                            await this.setItem('offline_users', u);
                        } catch(e){}
                    }
                }
            },

            async getMasterBootstrap() {
                try {
                    const row = await this.getItem('master_cache', 'bootstrap_data');
                    if (row && row.data) return row.data;
                } catch(e) {
                    console.warn('Gagal mengambil master bootstrap dari IndexedDB:', e);
                }
                try {
                    const cachedStr = localStorage.getItem('esbas_master_bootstrap');
                    if (cachedStr) {
                        const parsed = JSON.parse(cachedStr);
                        if (parsed && typeof parsed === 'object') return parsed;
                    }
                } catch(e) {
                    console.warn('Gagal mengambil master bootstrap dari localStorage:', e);
                }
                return null;
            }
        };

        // Pure JavaScript SHA-256 (NIST FIPS 180-4) Fallback untuk Android 8 & Konteks Non-HTTPS (HTTP)
        function jsSha256(ascii) {
            function rightRotate(value, amount) {
                return (value >>> amount) | (value << (32 - amount));
            }
            var mathPow = Math.pow;
            var maxWord = mathPow(2, 32);
            var lengthProperty = 'length';
            var i, j;
            var result = '';
            var words = [];
            var asciiBitLength = ascii[lengthProperty] * 8;
            var hash = jsSha256.h = jsSha256.h || [];
            var k = jsSha256.k = jsSha256.k || [];
            var primeCounter = k[lengthProperty];
            var isComposite = {};
            for (var candidate = 2; primeCounter < 64; candidate++) {
                if (!isComposite[candidate]) {
                    for (i = 0; i < 313; i += candidate) {
                        isComposite[i] = candidate;
                    }
                    hash[primeCounter] = (mathPow(candidate, .5) * maxWord) | 0;
                    k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
                }
            }
            hash = hash.slice(0);
            ascii += '\x80';
            while (ascii[lengthProperty] % 64 - 56) ascii += '\x00';
            for (i = 0; i < ascii[lengthProperty]; i++) {
                j = ascii.charCodeAt(i);
                if (j >> 8) return '';
                words[i >> 2] |= j << ((3 - i) % 4) * 8;
            }
            words[words[lengthProperty]] = ((asciiBitLength / maxWord) | 0);
            words[words[lengthProperty]] = (asciiBitLength) | 0;
            for (j = 0; j < words[lengthProperty];) {
                var w = words.slice(j, j += 16);
                var oldHash = hash;
                hash = hash.slice(0, 8);
                for (i = 0; i < 64; i++) {
                    var i2 = i + j;
                    var w15 = w[i - 15], w2 = w[i - 2];
                    var a = hash[0], e = hash[4];
                    var temp1 = hash[7]
                        + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))
                        + ((e & hash[5]) ^ ((~e) & hash[6]))
                        + k[i]
                        + (w[i] = (i < 16) ? w[i] : (
                            w[i - 16]
                            + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))
                            + w[i - 7]
                            + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
                        ) | 0);
                    var temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22))
                        + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
                    hash = [(temp1 + temp2) | 0].concat(hash);
                    hash[4] = (hash[4] + temp1) | 0;
                }
                for (i = 0; i < 8; i++) {
                    hash[i] = (hash[i] + oldHash[i]) | 0;
                }
            }
            for (i = 0; i < 8; i++) {
                for (j = 3; j + 1; j--) {
                    var b = (hash[i] >> (j * 8)) & 255;
                    result += ((b < 16) ? '0' : '') + b.toString(16);
                }
            }
            return result;
        }

        // SHA-256 Salted Hash Helper (Mendukung WebCrypto & Fallback JS Murni untuk HTTP / Android 8)
        async function sha256Salted(input) {
            const salt = 'esbas_salt_2026';
            const text = (input || '') + ':' + salt;
            if (window.crypto && window.crypto.subtle && typeof window.crypto.subtle.digest === 'function') {
                try {
                    const msgBuffer = new TextEncoder().encode(text);
                    const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
                    const hashArray = Array.from(new Uint8Array(hashBuffer));
                    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
                } catch (e) {
                    console.warn('WebCrypto gagal, fallback ke JS SHA-256:', e);
                }
            }
            return jsSha256(text);
        }

        // Otentikasi Pengguna Offline Menggunakan Data Cache IndexedDB
        async function authenticateOfflineUser(username, password) {
            try {
                const inputHash = await sha256Salted(password);
                const users = await OfflineDB.getAll('offline_users');
                const target = users.find(u => 
                    (u.nik && u.nik.toLowerCase() === username.toLowerCase()) ||
                    (u.email && u.email.toLowerCase() === username.toLowerCase()) ||
                    (u.phone && u.phone === username) ||
                    (u.name && u.name.toLowerCase() === username.toLowerCase())
                );

                if (!target) {
                    return { success: false, error: 'Akun ' + username + ' belum tersimpan di cache offline perangkat ini. Silakan login online minimal satu kali terlebih dahulu.' };
                }

                const isPinMatch = target.pin_hash && (target.pin_hash === inputHash);
                const isPassMatch = target.pass_hash && (target.pass_hash === inputHash);

                if (isPinMatch || isPassMatch) {
                    return { success: true, user: target };
                } else {
                    return { success: false, error: 'Kata sandi atau PIN offline tidak sesuai!' };
                }
            } catch (err) {
                console.error('Error saat verifikasi login offline:', err);
                return { success: false, error: 'Gagal memproses otentikasi offline: ' + err.message };
            }
        }

        // ========================================================
        // BACKGROUND AUTO-SYNC & STATUS UI CONTROLLER
        // ========================================================
        let isSyncingData = false;

        async function updateOfflineSyncStatusUI() {
            try {
                const pendingSales = await OfflineDB.getAll('offline_sales');
                const count = pendingSales.length;
                state.offlineSalesPendingCount = count;
                const pill = document.getElementById('topbar-offline-sync-pill');
                const text = document.getElementById('topbar-offline-sync-text');
                if (!pill || !text) return;

                if (!navigator.onLine || state.isOfflineMode || count > 0) {
                    pill.classList.remove('hidden');
                    pill.style.display = 'inline-flex';
                    if (count > 0) {
                        text.innerText = `⚡ Offline (${count} Transaksi) • Sinkronkan`;
                        pill.className = 'cursor-pointer inline-flex items-center space-x-1.5 bg-amber-500 hover:bg-amber-600 text-white font-bold text-[11px] sm:text-xs px-2.5 py-1 sm:py-1.5 rounded-xl shadow-xs transition-colors shrink-0 animate-pulse';
                    } else {
                        text.innerText = `⚡ Mode Offline`;
                        pill.className = 'cursor-pointer inline-flex items-center space-x-1.5 bg-slate-700 hover:bg-slate-800 text-white font-bold text-[11px] sm:text-xs px-2.5 py-1 sm:py-1.5 rounded-xl shadow-xs transition-colors shrink-0';
                    }
                } else {
                    pill.classList.add('hidden');
                    pill.style.display = 'none';
                }
            } catch (e) {
                console.error('Error update sync UI:', e);
            }
        }

        async function triggerAutoSync(silent = true) {
            if (isSyncingData) return;
            if (!navigator.onLine) {
                if (!silent) alert('Tidak ada sambungan internet. Pastikan perangkat Anda terhubung ke jaringan Wi-Fi atau seluler.');
                await updateOfflineSyncStatusUI();
                return;
            }

            try {
                isSyncingData = true;
                const textEl = document.getElementById('topbar-offline-sync-text');
                if (textEl) textEl.innerText = '⚡ Memeriksa Server...';

                // 1. Ping Server Probe (Pemeriksaan respons server tangguh)
                let isServerOnline = false;
                try {
                    const pingRes = await fetch('api.php?action=ping', { cache: 'no-store' });
                    const pingData = await pingRes.json();
                    if (pingData && (pingData.online === true || pingData.status === 'online' || pingData.success === true)) {
                        isServerOnline = true;
                    }
                } catch (pe) {
                    console.warn('Ping probe server gagal:', pe);
                    isServerOnline = false;
                }

                if (!isServerOnline) {
                    isSyncingData = false;
                    if (!silent) {
                        alert('Server pusat belum dapat dihubungi. Periksa sambungan internet Anda atau coba sesaat lagi.');
                    }
                    await updateOfflineSyncStatusUI();
                    return;
                }

                // Terhubung ke server!
                state.isOfflineMode = false;

                // 2. Sinkronkan Shift Offline terlebih dahulu (jika ada)
                const pendingShifts = await OfflineDB.getAll('offline_shifts');
                for (const shift of pendingShifts) {
                    try {
                        const sRes = await fetch('api.php?action=sync_offline_shift', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify(shift)
                        });
                        const sData = await sRes.json();
                        if (sData && sData.success) {
                            await OfflineDB.removeItem('offline_shifts', shift.offline_ref);
                        }
                    } catch (e) {
                        console.warn('Gagal menyinkronkan shift offline:', e);
                    }
                }

                // 3. Sinkronkan Antrean Transaksi Penjualan Offline
                const pendingSales = await OfflineDB.getAll('offline_sales');
                const unsyncedSales = (pendingSales || []).filter(s => !s.synced);

                if (unsyncedSales.length > 0) {
                    if (textEl) textEl.innerText = '⚡ Menyinkronkan (' + unsyncedSales.length + ')...';

                    const res = await fetch('api.php?action=sync_offline_sales', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ offline_sales: unsyncedSales, sales: unsyncedSales })
                    });
                    const data = await res.json();

                    if (data && data.success) {
                        const successRefs = new Set();
                        if (Array.isArray(data.results)) {
                            data.results.forEach(r => {
                                if (r.status === 'SYNCED_SUCCESS' || r.status === 'ALREADY_EXISTS') {
                                    if (r.offline_id) successRefs.add(r.offline_id);
                                    if (r.invoice_number) successRefs.add(r.invoice_number);
                                }
                            });
                        }

                        for (const s of unsyncedSales) {
                            if (successRefs.size === 0 || successRefs.has(s.offline_ref) || successRefs.has(s.invoice_number)) {
                                await OfflineDB.removeItem('offline_sales', s.offline_ref);
                            }
                        }

                        const count = unsyncedSales.length;
                        if (!silent) {
                            alert('✅ Sinkronisasi Berhasil: ' + count + ' transaksi penjualan offline telah sukses diunggah ke server pusat! Stok dan laporan telah diperbarui.');
                        }
                        // Muat ulang data terbaru dari server
                        try {
                            await initApp();
                            if (state.currentTab === 'reports') {
                                loadSalesReports();
                            }
                        } catch(e){}
                    } else {
                        const errMsg = (data && (data.message || data.error)) || 'Respon tidak valid dari server.';
                        if (!silent) alert('Sinkronisasi sebagian atau gagal: ' + errMsg);
                    }
                } else {
                    if (!silent) alert('Semua data sudah tersinkronkan dengan server (0 transaksi tertunda).');
                }
            } catch (err) {
                console.warn('Gagal proses sinkronisasi:', err);
                if (!silent) alert('Gagal menyinkronkan data: ' + (err && err.message ? err.message : 'Kesalahan jaringan'));
            } finally {
                isSyncingData = false;
                await updateOfflineSyncStatusUI();
            }
        }

        window.triggerManualSync = async function() {
            const textEl = document.getElementById('topbar-offline-sync-text');
            if (textEl) textEl.innerText = '⚡ Menghubungkan...';
            await triggerAutoSync(false);
        };

        // Event listener deteksi online / offline browser
        window.addEventListener('online', () => {
            console.log('Jaringan online terdeteksi.');
            triggerAutoSync(true);
        });

