        function clearLogoImage() {
            const urlInput = document.getElementById('set-app-logo-url');
            const fileInput = document.getElementById('set-app-logo-file');
            if (urlInput) urlInput.value = '';
            if (fileInput) fileInput.value = '';
            updateLogoPreviewUI();
        }

        function handleLogoFileUpload(event) {
            const file = event.target.files && event.target.files[0];
            if (!file) return;

            if (!file.type.startsWith('image/')) {
                alert('File yang dipilih bukan merupakan berkas gambar!');
                return;
            }

            if (file.size > 5 * 1024 * 1024) {
                alert('Ukuran file gambar terlalu besar! Maksimal 5MB.');
                return;
            }

            const reader = new FileReader();
            reader.onload = function(e) {
                const rawDataUrl = e.target.result;
                
                // Kompres gambar otomatis jika ukuran > 150KB menggunakan HTML5 Canvas
                if (file.size > 150 * 1024 && !file.type.includes('svg')) {
                    const img = new Image();
                    img.onload = function() {
                        const maxDim = 320;
                        let w = img.width;
                        let h = img.height;
                        if (w > maxDim || h > maxDim) {
                            if (w > h) {
                                h = Math.round((h * maxDim) / w);
                                w = maxDim;
                            } else {
                                w = Math.round((w * maxDim) / h);
                                h = maxDim;
                            }
                        }
                        const canvas = document.createElement('canvas');
                        canvas.width = w;
                        canvas.height = h;
                        const ctx = canvas.getContext('2d');
                        ctx.drawImage(img, 0, 0, w, h);
                        const compressedDataUrl = canvas.toDataURL('image/png', 0.9);
                        const urlInput = document.getElementById('set-app-logo-url');
                        if (urlInput) urlInput.value = compressedDataUrl;
                        updateLogoPreviewUI();
                    };
                    img.src = rawDataUrl;
                } else {
                    const urlInput = document.getElementById('set-app-logo-url');
                    if (urlInput) urlInput.value = rawDataUrl;
                    updateLogoPreviewUI();
                }
            };
            reader.readAsDataURL(file);
        }

        function updateLogoPreviewUI() {
            const urlInput = document.getElementById('set-app-logo-url');
            const emojiInput = document.getElementById('set-app-logo-emoji');
            const previewImg = document.getElementById('set-logo-preview-img');
            const previewEmoji = document.getElementById('set-logo-preview-emoji');
            const statusText = document.getElementById('set-logo-status-text');

            const logoUrl = urlInput ? urlInput.value.trim() : '';
            const logoEmoji = emojiInput ? (emojiInput.value.trim() || '🛍️') : '🛍️';

            if (previewEmoji) previewEmoji.innerText = logoEmoji;

            if (logoUrl) {
                if (previewImg) {
                    previewImg.src = logoUrl;
                    previewImg.classList.remove('hidden');
                    previewImg.onerror = function() {
                        previewImg.classList.add('hidden');
                        if (previewEmoji) previewEmoji.classList.remove('hidden');
                        if (statusText) statusText.innerText = 'Gambar gagal dimuat (cek URL)';
                    };
                    previewImg.onload = function() {
                        previewImg.classList.remove('hidden');
                        if (previewEmoji) previewEmoji.classList.add('hidden');
                        if (statusText) statusText.innerText = 'Gambar logo aktif (tersedia)';
                    };
                }
                if (previewEmoji) previewEmoji.classList.add('hidden');
            } else {
                if (previewImg) {
                    previewImg.classList.add('hidden');
                    previewImg.src = '';
                }
                if (previewEmoji) previewEmoji.classList.remove('hidden');
                if (statusText) statusText.innerText = 'Menggunakan ikon emoji';
            }
        }

        // ==========================================
        // AUTHENTICATION LOGIC (12-HOUR SESSION & PASSWORD MANDATORY)
        // ==========================================
        async function checkAuthSession() {
            try {
                const res = await fetch('api.php?action=check_session');
                const data = await res.json();
                if (data.session_expired) {
                    try { localStorage.removeItem('esbas_logged_in_user'); localStorage.removeItem('esbas_session_info'); } catch(e){}
                    showLoginScreen(data.message || 'Sesi login 12 jam harian telah berakhir. Silakan isi kata sandi ulang.');
                    return;
                }
                if (data.success && data.logged_in) {
                    state.loggedInUser = data.user;
                    try { localStorage.setItem('esbas_logged_in_user', JSON.stringify(data.user)); } catch(e){}
                    // Keterkaitan Lokasi: setel cabang aktif ke cabang penempatan karyawan
                    if (data.user && data.user.branch_id) {
                        const targetBranch = (state.branches || []).find(b => b.id == data.user.branch_id);
                        if (targetBranch) {
                            state.currentBranch = targetBranch;
                        }
                    }
                    if (data.session_info) {
                        state.sessionInfo = data.session_info;
                        startSessionCountdownTimer();
                    }
                    hideLoginScreen();
                    initApp();
                    return;
                }
            } catch (err) {
                console.warn('Check session fetch error:', err);
            }

            // Client-side backup fallback
            try {
                const cachedUserStr = localStorage.getItem('esbas_logged_in_user');
                if (cachedUserStr) {
                    const cachedUser = JSON.parse(cachedUserStr);
                    if (cachedUser && cachedUser.id) {
                        state.loggedInUser = cachedUser;
                        startSessionCountdownTimer();
                        hideLoginScreen();
                        initApp();
                        return;
                    }
                }
            } catch (e) {
                try { localStorage.removeItem('esbas_logged_in_user'); } catch(ex){}
            }

            showLoginScreen();
        }

        function showLoginScreen(message = null) {
            const screen = document.getElementById('login-screen');
            if (screen) {
                screen.style.setProperty('display', 'flex', 'important');
                screen.classList.remove('hidden');
            }
            // Selalu hapus password dari input setiap kali layar login ditampilkan
            const pInput = document.getElementById('login-password');
            if (pInput) {
                pInput.value = '';
                pInput.focus();
            }
            const errAlert = document.getElementById('login-error-alert');
            const errText = document.getElementById('login-error-text');
            if (message && errAlert && errText) {
                errText.innerText = message;
                errAlert.className = 'p-3 bg-purple-950/60 border border-purple-500/50 text-purple-200 text-xs rounded-xl flex items-center space-x-2 shadow-lg shadow-purple-950/50';
                errAlert.style.display = 'flex';
                if (window.lucide) lucide.createIcons();
            } else if (errAlert && !message) {
                errAlert.style.display = 'none';
            }
            if (state.sessionTimerInterval) {
                clearInterval(state.sessionTimerInterval);
                state.sessionTimerInterval = null;
            }
            updateSessionBadgeUI(null);
            if (typeof loadQuickLoginAccounts === 'function') {
                loadQuickLoginAccounts();
            }
            if (typeof startVoid3DCanvas === 'function') {
                startVoid3DCanvas();
            }
        }

        async function loadQuickLoginAccounts() {
            try {
                const res = await fetch('api.php?action=get_quick_login_users');
                const data = await res.json();
                if (!data.success || !Array.isArray(data.users) || data.users.length === 0) return;
                
                const grid = document.getElementById('quick-accounts-grid');
                if (!grid) return;
                
                grid.innerHTML = data.users.slice(0, 6).map(u => {
                    const badge = (typeof getRoleBadgeEmoji === 'function') ? getRoleBadgeEmoji(u.role) : '🛡️';
                    const c = (u.role || '').toUpperCase().replace(/_/g, '');
                    let roleLabel = u.role || 'Karyawan';
                    if (c.includes('SUPERADMIN')) roleLabel = 'Super Admin';
                    else if (c.includes('BRANCHMANAGER') || c.includes('MANAGER')) roleLabel = 'Manager';
                    else if (c.includes('CASHIER') || c.includes('KASIR')) roleLabel = 'Kasir';
                    else if (c.includes('STAFF') || c.includes('STAF')) roleLabel = 'Staf Gudang';
                    else if (c.includes('KURIR') || c.includes('DRIVER')) roleLabel = 'Kurir';

                    const safeName = (u.name || '').replace(/'/g, "\\'");
                    const safeNik = (u.nik || '').replace(/'/g, "\\'");
                    const branchText = u.branch_name ? `<span class="text-[9px] text-slate-500 group-hover:text-purple-400 truncate max-w-[60px] ml-1 shrink-0">${escapeHtml(u.branch_name)}</span>` : '';

                    return `
                        <button type="button" onclick="selectQuickAccount('${safeNik}', '${safeName}')" class="p-2.5 bg-black/40 hover:bg-purple-950/40 border border-white/5 hover:border-purple-500/40 rounded-xl text-left transition-all group shadow-xs cursor-pointer">
                            <div class="flex items-center justify-between">
                                <p class="font-bold text-slate-200 group-hover:text-purple-300 text-[11px] truncate">${badge} ${escapeHtml(roleLabel)}</p>
                                ${branchText}
                            </div>
                            <div class="flex items-center justify-between mt-1">
                                <p class="text-[10px] text-slate-400 group-hover:text-slate-200 font-medium truncate">${escapeHtml(u.name)}</p>
                            </div>
                        </button>
                    `;
                }).join('');
            } catch (err) {
                // Silently fallback to server rendered accounts
            }
        }

        function hideLoginScreen() {
            const screen = document.getElementById('login-screen');
            if (screen) {
                screen.style.setProperty('display', 'none', 'important');
                screen.classList.add('hidden');
            }
            if (typeof stopVoid3DCanvas === 'function') {
                stopVoid3DCanvas();
            }
        }

        function startSessionCountdownTimer() {
            if (state.sessionTimerInterval) {
                clearInterval(state.sessionTimerInterval);
                state.sessionTimerInterval = null;
            }

            state.sessionClientExpiresAt = Date.now() + (12 * 3600 * 1000);

            function tick() {
                const remaining = Math.max(0, Math.floor((state.sessionClientExpiresAt - Date.now()) / 1000));
                updateSessionBadgeUI(remaining);

                if (remaining <= 0) {
                    clearInterval(state.sessionTimerInterval);
                    state.sessionTimerInterval = null;
                    state.loggedInUser = null;
                    try { localStorage.removeItem('esbas_logged_in_user'); localStorage.removeItem('esbas_session_info'); } catch(e){}
                    showLoginScreen('Sesi login harian (12 jam) telah berakhir. Demi keamanan, silakan masukkan kembali kata sandi Anda.');
                }
            }

            tick();
            state.sessionTimerInterval = setInterval(tick, 10000); // perbarui badge tiap 10 detik
        }

        function updateSessionBadgeUI(remainingSec) {
            const badgeText = document.getElementById('topbar-session-text');
            const badgeEl = document.getElementById('topbar-session-badge');
            const sideSessionText = document.getElementById('sidebar-session-text');

            if (remainingSec === null || remainingSec === undefined) {
                if (badgeText) badgeText.innerText = 'Sesi: 12j 00m';
                if (sideSessionText) sideSessionText.innerText = 'Sesi: 12j 00m';
                return;
            }

            const hours = Math.floor(remainingSec / 3600);
            const minutes = Math.floor((remainingSec % 3600) / 60);
            const formatted = `${hours}j ${minutes < 10 ? '0' : ''}${minutes}m`;

            if (badgeText) badgeText.innerText = `Sesi: ${formatted}`;
            if (sideSessionText) sideSessionText.innerText = `Sesi: ${formatted}`;

            if (badgeEl) {
                if (remainingSec < 1800) { // kurang dari 30 menit
                    badgeEl.className = 'hidden md:flex items-center space-x-1.5 bg-rose-50 dark:bg-rose-950/60 border border-rose-300 dark:border-rose-800 text-rose-800 dark:text-rose-300 px-2 py-1 sm:px-2.5 sm:py-1.5 rounded-xl shrink-0 animate-pulse';
                } else if (remainingSec < 7200) { // kurang dari 2 jam
                    badgeEl.className = 'hidden md:flex items-center space-x-1.5 bg-amber-50 dark:bg-amber-950/60 border border-amber-300 dark:border-amber-800 text-amber-800 dark:text-amber-300 px-2 py-1 sm:px-2.5 sm:py-1.5 rounded-xl shrink-0';
                } else {
                    badgeEl.className = 'hidden md:flex items-center space-x-1.5 bg-indigo-50 dark:bg-indigo-950/60 border border-indigo-200 dark:border-indigo-800/80 text-indigo-800 dark:text-indigo-300 px-2 py-1 sm:px-2.5 sm:py-1.5 rounded-xl shrink-0';
                }
            }
        }

        async function handleLogin(e) {
            if (e && e.preventDefault) e.preventDefault();
            const usernameInput = document.getElementById('login-username');
            const passwordInput = document.getElementById('login-password');
            const username = usernameInput ? usernameInput.value.trim() : '';
            const password = passwordInput ? passwordInput.value.trim() : '';
            const errAlert = document.getElementById('login-error-alert');
            const errText = document.getElementById('login-error-text');
            const btnSubmit = document.getElementById('btn-login-submit');

            const setSubmitDefault = function() {
                if (btnSubmit) {
                    btnSubmit.disabled = false;
                    btnSubmit.className = 'w-full py-3.5 px-5 bg-gradient-to-r from-indigo-500 via-purple-600 to-indigo-500 bg-[length:200%_auto] hover:bg-right text-white font-extrabold rounded-xl shadow-[0_0_30px_rgba(99,102,241,0.35)] hover:shadow-[0_0_40px_rgba(168,85,247,0.55)] transition-all duration-300 flex items-center justify-center space-x-2 text-sm tracking-wider cursor-pointer active:scale-[0.98]';
                    btnSubmit.innerHTML = '<span>CONTINUE</span><span class="text-base">&rarr;</span>';
                }
            };

            const setSubmitLoading = function() {
                if (btnSubmit) {
                    btnSubmit.disabled = true;
                    btnSubmit.className = 'w-full py-3.5 px-5 bg-purple-900/80 text-purple-200 font-extrabold rounded-xl shadow-inner transition-all flex items-center justify-center space-x-2 text-sm tracking-wider opacity-90 cursor-wait';
                    btnSubmit.innerHTML = '<span class="inline-flex items-center gap-2"><svg class="animate-spin w-4 h-4 text-purple-300" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>VERIFYING...</span>';
                }
            };

            const setSubmitSuccess = function() {
                if (btnSubmit) {
                    btnSubmit.className = 'w-full py-3.5 px-5 bg-gradient-to-r from-emerald-500 to-teal-500 text-white font-black rounded-xl shadow-[0_0_40px_rgba(16,185,129,0.7)] transition-all flex items-center justify-center space-x-2 text-sm tracking-wider animate-pulse';
                    btnSubmit.innerHTML = '<span class="inline-flex items-center gap-2"><svg class="w-4 h-4 text-white shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"></path></svg>ACCESS GRANTED &rarr;</span>';
                }
            };

            if (!username) {
                const msg = 'Silakan isi NIK atau Email login.';
                if (errAlert && errText) {
                    errText.innerText = msg;
                    errAlert.className = 'p-3 bg-rose-950/60 border border-rose-500/50 text-rose-300 text-xs rounded-xl flex items-center space-x-2 shadow-lg shadow-rose-950/50';
                    errAlert.style.display = 'flex';
                }
                if (usernameInput) usernameInput.focus();
                return;
            }

            if (!password) {
                const msg = 'Kata sandi / PIN wajib diisi ulang untuk masuk ke sistem.';
                if (errAlert && errText) {
                    errText.innerText = msg;
                    errAlert.className = 'p-3 bg-rose-950/60 border border-rose-500/50 text-rose-300 text-xs rounded-xl flex items-center space-x-2 shadow-lg shadow-rose-950/50';
                    errAlert.style.display = 'flex';
                }
                if (passwordInput) passwordInput.focus();
                return;
            }

            setSubmitLoading();
            if (errAlert) {
                errAlert.style.display = 'none';
            }

            try {
                const res = await fetch('api.php?action=login', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ username, password })
                });
                const data = await res.json();

                if (data.success) {
                    setSubmitSuccess();
                    await new Promise(function(resolve) { setTimeout(resolve, 450); });

                    state.loggedInUser = data.user;
                    state.isOfflineMode = false;
                    try { localStorage.setItem('esbas_logged_in_user', JSON.stringify(data.user)); } catch(e){}
                    if (data.offline_user_pack) {
                        try {
                            await OfflineDB.setItem('offline_users', data.offline_user_pack);
                        } catch(e){}
                    }
                    if (data.active_shift) {
                        state.activeShift = data.active_shift;
                    }
                    if (data.has_closed_shift !== undefined) {
                        state.currentUserHasClosedShift = (data.has_closed_shift === true);
                        window.userHasClosedShift = (data.has_closed_shift === true);
                    }
                    if (data.branch_closed_today !== undefined) {
                        state.branchClosedToday = (data.branch_closed_today === true);
                    }
                    if (data.final_closed_shift !== undefined) {
                        state.finalClosedShift = data.final_closed_shift || null;
                    }
                    if (typeof updateShiftReportSubtabVisibility === 'function') {
                        updateShiftReportSubtabVisibility();
                    }
                    // Keterkaitan Lokasi: setel cabang aktif ke cabang penempatan karyawan
                    if (data.user && data.user.branch_id) {
                        const targetBranch = (state.branches || []).find(b => b.id == data.user.branch_id);
                        if (targetBranch) {
                            state.currentBranch = targetBranch;
                        }
                    }
                    if (data.session_info) {
                        state.sessionInfo = data.session_info;
                        startSessionCountdownTimer();
                    }
                    if (passwordInput) passwordInput.value = ''; // Selalu kosongkan password setelah berhasil
                    hideLoginScreen();
                    setSubmitDefault();
                    try {
                        await initApp();
                    } catch (initErr) {
                        console.error('Error saat inisialisasi aplikasi:', initErr);
                    }
                } else {
                    setSubmitDefault();
                    const errorMsg = data.message || data.error || 'Kredensial login tidak valid.';
                    if (errAlert && errText) {
                        errText.innerText = errorMsg;
                        errAlert.className = 'p-3 bg-rose-950/60 border border-rose-500/50 text-rose-300 text-xs rounded-xl flex items-center space-x-2 shadow-lg shadow-rose-950/50';
                        errAlert.style.display = 'flex';
                    }
                    alert('Login Gagal: ' + errorMsg);
                    if (passwordInput) {
                        passwordInput.value = '';
                        passwordInput.focus();
                    }
                    if (window.lucide) lucide.createIcons();
                }
            } catch (err) {
                // FALLBACK OFFLINE LOGIN: Otentikasi terhadap hash akun tersimpan di IndexedDB
                console.warn('Jaringan server tidak terjangkau, menguji login offline...', err);
                const offlineAuth = await authenticateOfflineUser(username, password);
                if (offlineAuth.success) {
                    setSubmitSuccess();
                    await new Promise(function(resolve) { setTimeout(resolve, 450); });
                    if (passwordInput) passwordInput.value = '';
                    state.loggedInUser = offlineAuth.user;
                    state.isOfflineMode = true;
                    try { localStorage.setItem('esbas_logged_in_user', JSON.stringify(offlineAuth.user)); } catch(e){}
                    hideLoginScreen();
                    setSubmitDefault();
                    try {
                        await initApp();
                    } catch (initErr) {
                        console.error('Error inisialisasi aplikasi offline:', initErr);
                    }
                    await updateOfflineSyncStatusUI();
                    return;
                }

                setSubmitDefault();
                const errorMsg = offlineAuth.error || ('Koneksi ke server gagal: ' + (err.message || 'Periksa koneksi jaringan'));
                if (errAlert && errText) {
                    errText.innerText = errorMsg;
                    errAlert.className = 'p-3 bg-rose-950/60 border border-rose-500/50 text-rose-300 text-xs rounded-xl flex items-center space-x-2 shadow-lg shadow-rose-950/50';
                    errAlert.style.display = 'flex';
                }
                alert('Gagal Masuk (Mode Offline): ' + errorMsg);
                if (window.lucide) lucide.createIcons();
            }
        }

        function selectQuickAccount(username, roleLabel) {
            const uInput = document.getElementById('login-username');
            const pInput = document.getElementById('login-password');
            if (uInput) uInput.value = username;
            if (pInput) {
                pInput.value = '';
                pInput.focus();
            }

            const errAlert = document.getElementById('login-error-alert');
            const errText = document.getElementById('login-error-text');
            if (errAlert && errText) {
                errText.innerHTML = `Akun <strong>${escapeHtml(roleLabel)}</strong> (${escapeHtml(username)}) dipilih. Masukkan kata sandi / PIN Anda.`;
                errAlert.className = 'p-2.5 bg-purple-950/60 border border-purple-500/40 text-purple-300 text-xs rounded-xl flex items-center space-x-2 shadow-md';
                errAlert.style.display = 'flex';
                if (window.lucide) lucide.createIcons();
            }
        }

        function quickLogin(username, password) {
            // Pengalihan ramah: tidak melakukan login otomatis bypass sandi, arahkan ke pengisian kata sandi
            selectQuickAccount(username, 'Pengguna');
        }

        async function handleLogout() {
            if (!confirm('Apakah Anda yakin ingin keluar dari sistem?')) return;
            try { localStorage.removeItem('esbas_logged_in_user'); localStorage.removeItem('esbas_session_info'); } catch(e){}
            await fetch('api.php?action=logout');
            state.loggedInUser = null;
            state.sessionInfo = null;
            if (state.sessionTimerInterval) {
                clearInterval(state.sessionTimerInterval);
                state.sessionTimerInterval = null;
            }
            showLoginScreen('Anda telah keluar dari akun. Silakan masukkan kata sandi untuk login kembali.');
        }

        // ==========================================
        // INITIALIZE APPLICATION
        // ==========================================
        async function initApp() {
            try {
                const bId = (state.currentBranch && state.currentBranch.id) 
                            || (state.loggedInUser && state.loggedInUser.branch_id) 
                            || 1;
                const uId = (state.loggedInUser && state.loggedInUser.id) || 1;

                let data = null;
                let isOffline = state.isOfflineMode || !navigator.onLine;

                if (!isOffline) {
                    try {
                        const res = await fetch(`api.php?action=bootstrap&branch_id=${bId}&user_id=${uId}`);
                        const resData = await res.json();
                        if (resData && resData.success) {
                            data = resData;
                            state.isOfflineMode = false;
                            await OfflineDB.saveMasterBootstrap(data);
                        } else {
                            data = null;
                        }
                    } catch (netErr) {
                        console.warn('Gagal bootstrap dari server, beralih ke cache OfflineDB:', netErr);
                        isOffline = true;
                        state.isOfflineMode = true;
                    }
                }

                if (isOffline || !data) {
                    state.isOfflineMode = true;
                    data = await OfflineDB.getMasterBootstrap();
                    if (!data) {
                        if (state.products && state.products.length > 0) {
                            console.log('Mempertahankan katalog produk dan menu yang sudah aktif di memori.');
                            renderProducts();
                            renderCategoryPills();
                            await updateOfflineSyncStatusUI();
                            return;
                        }
                        alert('Aplikasi sedang dalam Mode Offline dan belum memiliki cache master data menu/produk. Silakan hubungkan internet minimal 1 kali.');
                        return;
                    }
                }

                state.branches = data.branches || [];
                state.currentBranch = data.current_branch || (state.branches[0] || { id: bId, name: 'Cabang Utama' });
                state.users = data.users || [];
                state.currentUser = state.loggedInUser || data.current_user || { id: uId, name: 'Kasir', role: 'CASHIER' };
                state.activeShift = data.active_shift || state.activeShift;
                if (!state.activeShift && state.isOfflineMode) {
                    state.activeShift = {
                        id: 'OFF-SHIFT-' + (state.currentUser.id || 1),
                        branch_id: state.currentBranch.id,
                        user_id: state.currentUser.id,
                        cashier_name: state.currentUser.name || 'Kasir Offline',
                        status: 'OPEN',
                        shift_number: 1,
                        shift_name: 'Shift Offline Kasir',
                        initial_cash: 0,
                        is_offline: true
                    };
                }
                state.currentUserHasClosedShift = (data.has_closed_shift === true);
                window.userHasClosedShift = (data.has_closed_shift === true);
                state.branchClosedToday = (data.branch_closed_today === true);
                state.finalClosedShift = data.final_closed_shift || null;
                state.userRoles = data.user_roles || [];
                const seenPids = new Set();
                state.products = (data.products || []).filter(p => {
                    if (seenPids.has(p.id)) return false;
                    seenPids.add(p.id);
                    return true;
                });
                state.categories = Array.isArray(data.categories) ? data.categories : (state.categories || []);
                state.productTypes = data.product_types || [];
                state.productUnits = data.product_units || [];
                state.taxes = data.taxes || [];
                state.paymentMethods = data.payment_methods || [];
                state.customers = data.customers || [];
                state.customerCategories = data.customer_categories || [];
                state.mitraPrices = data.mitra_prices || [];
                state.currentDeliverySetting = data.current_delivery_setting || null;
                state.allDeliverySettings = data.all_delivery_settings || [];
                state.vehicles = data.all_vehicles || [];
                state.expenseCategories = data.expense_categories || [];
                populateReimburseCategoryDropdown(state.expenseCategories);
                state.discountRules = Array.isArray(data.discount_rules) ? data.discount_rules : (state.discountRules || []);
                if (!state.discountRules || state.discountRules.length === 0) {
                    loadDiscountRules();
                }

                // Pastikan tier yang aktif terpilih adalah kategori yang berstatus aktif
                const activeCats = (state.customerCategories || []).filter(c => c.is_active == 1);
                const activeCodes = activeCats.map(c => c.code);

                if (!state.selectedCustomerCategory || (activeCodes.length > 0 && !activeCodes.includes(state.selectedCustomerCategory))) {
                    state.selectedCustomerCategory = activeCodes.includes('REGULER') ? 'REGULER' : (activeCodes[0] || 'REGULER');
                }

                // Default pencarian pelanggan dibuat kosong (tidak ada pelanggan default terpilih)
                state.selectedCustomer = null;

                // Simpan App Settings & Role Permissions
                state.appSettings = data.app_settings || {};
                state.rolePermissions = data.role_permissions || [];
                state.userPermissions = data.user_permissions || {};

                // Update Branding Aplikasi (Logo & Nama)
                applyAppSettingsToUI();

                // Update Sidebar Profile
                if (document.getElementById('sidebar-user-name')) {
                    document.getElementById('sidebar-user-name').innerText = state.currentUser.name;
                }
                if (document.getElementById('sidebar-user-role')) {
                    document.getElementById('sidebar-user-role').innerText = state.currentUser.role;
                }
                updateUserAvatarUI(state.currentUser);

                // Terapkan filter hak akses menu sidebar berdasarkan role login
                applyRolePermissionsToSidebar();
                updateShiftReportSubtabVisibility();

                renderBranchOptions();
                initStockBranchSelector();
                renderCategoryPills();
                renderPosTierButtons();
                renderPosCustomerSelect();
                renderPosCourierSelect();
                renderPosPaymentButtons();
                loadCashDenominations();
                renderReportPaymentFilterOptions();
                renderProducts();
                renderShiftBanner();
                loadBranches();

                const now = new Date();
                const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
                const today = now.toISOString().split('T')[0];
                document.getElementById('report-start-date').value = firstDay;
                document.getElementById('report-end-date').value = today;

                await updateOfflineSyncStatusUI();
                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function switchTab(tab) {
            state.currentTab = tab;
            const tabIds = ['dashboard', 'pos', 'reports', 'ess', 'employees', 'payroll', 'products', 'bom', 'stocks', 'stock-in', 'pnl', 'partner-sales', 'expenses', 'customers', 'logistics', 'branches', 'payments', 'discounts', 'sale-cancellations', 'settings'];
            tabIds.forEach(t => {
                const el = document.getElementById(`tab-${t}`);
                const btn = document.getElementById(`tab-btn-${t}`);
                if (t === tab) {
                    if (el) el.classList.remove('hidden');
                    if (btn) btn.classList.add('sidebar-item-active');
                } else {
                    if (el) el.classList.add('hidden');
                    if (btn) btn.classList.remove('sidebar-item-active');
                }
            });

            // Update Topbar Title & Subtitle
            const meta = tabTitles[tab] || { title: tab, sub: '' };
            const titleEl = document.getElementById('topbar-view-title');
            if (titleEl) {
                titleEl.innerText = meta.title;
                titleEl.title = meta.title;
            }
            document.getElementById('topbar-view-subtitle').innerHTML = meta.sub;

            // Close mobile drawer on navigation
            const sidebar = document.getElementById('app-sidebar');
            const backdrop = document.getElementById('sidebar-backdrop');
            if (!backdrop.classList.contains('hidden')) {
                sidebar.classList.add('-translate-x-full');
                backdrop.classList.add('hidden');
            }

            if (tab === 'dashboard') {
                const curUser = state.currentUser || state.loggedInUser;
                const role = String((curUser ? curUser.role : '') || '').toUpperCase().replace(/[^A-Z]/g, '');
                const isAllowed = ['SUPERADMIN', 'BRANCHMANAGER', 'MANAGER'].includes(role);
                if (!isAllowed) {
                    alert('Akses Ditolak: Halaman Dashboard Eksekutif hanya dapat diakses oleh Superadmin dan Branch Manager.');
                    switchTab('pos');
                    return;
                }
                loadExecutiveDashboard();
                startExecAutoRefresh();
            } else {
                stopExecAutoRefresh();
            }

            if (tab === 'reports') {
                updateShiftReportSubtabVisibility();
                if (state.reportActiveSubtab === 'receivables') {
                    loadReceivablesReport();
                } else if (state.reportActiveSubtab === 'shifts') {
                    const curUser = state.currentUser || state.loggedInUser;
                    const userRole = String((curUser ? curUser.role : '') || '').toUpperCase().replace(/[^A-Z]/g, '');
                    const isManagerOrAdmin = ['SUPERADMIN', 'BRANCHMANAGER', 'MANAGER'].includes(userRole);
                    const hasClosed = (state.currentUserHasClosedShift === true) 
                                   || (window.userHasClosedShift === true)
                                   || (state.branchClosedToday === true)
                                   || (state.finalClosedShift !== null);
                    if (isManagerOrAdmin || hasClosed) {
                        loadShiftReports();
                    } else {
                        setReportSubtab('sales');
                    }
                } else if (state.reportActiveSubtab === 'bom') {
                    loadBomUsageReport();
                } else {
                    loadSalesReports();
                }
            }
            if (tab === 'ess') loadEssData();
            if (tab === 'employees') loadEmployees();
            if (tab === 'payroll') loadPayrollModule();
            if (tab === 'products') loadAllProducts();
            if (tab === 'bom') loadBOMRecipes();
            if (tab === 'stocks') loadStockInventory();
            if (tab === 'stock-in') {
                if (!hasUserPerm('stock-in', 'view') && !hasUserPerm('stock-in:manual', 'view') && !hasUserPerm('stock-in:transfer', 'view')) {
                    alert('Akses Ditolak: Role Anda tidak memiliki izin untuk mengakses menu Input Penambahan Stok.');
                    switchTab('pos');
                    return;
                }
                loadStockInModule();
            }
            if (tab === 'pnl') loadProfitLoss();
            if (tab === 'partner-sales') loadPartnerSalesReport();
            if (tab === 'expenses') loadBranchExpensesModule();
            if (tab === 'customers') {
                loadCustomers();
                if (state.customerActiveSubtab === 'maps') {
                    setTimeout(() => { initCustomerMap(); }, 150);
                }
            }
            if (tab === 'logistics') loadLogisticsData();
            if (tab === 'branches') {
                loadBranches();
                if (state.branchActiveSubtab === 'maps') {
                    setTimeout(() => { initBranchMap(); }, 150);
                }
            }
            if (tab === 'payments') {
                loadPaymentMethods();
                loadCashDenominations();
            }
            if (tab === 'discounts') {
                loadDiscountRules();
            }
            if (tab === 'sale-cancellations') loadSaleCancellations();
            if (tab === 'settings') loadAppSettingsModule();

            lucide.createIcons();
        }

                function canUserAccessAllBranches() {
            const curUser = state.currentUser || state.loggedInUser;
            if (!curUser) return false;
            if (Number(curUser.can_access_all_branches) === 1) return true;
            const r = (curUser.role || '').toUpperCase().replace(/_/g, '');
            return (r === 'SUPERADMIN');
        }

        function canUserResetStoreData() {
            const curUser = state.currentUser || state.loggedInUser;
            if (!curUser) return false;
            const userRole = String(curUser.role || '').toUpperCase().replace(/[^A-Z]/g, '');
            // Blokir mutlak untuk Kasir, Staff, Kurir, dan level operasional cabang
            if (!userRole || userRole.includes('CASHIER') || userRole.includes('KASIR') || userRole.includes('STAFF') || userRole.includes('STAF') || userRole.includes('KURIR') || userRole.includes('COURIER') || userRole.includes('GUDANG')) {
                return false;
            }
            return (userRole === 'SUPERADMIN');
        }

        function updateStoreResetButtonsVisibility() {
            const canReset = canUserResetStoreData();
            const resetBtnIds = [
                'btn-sales-report-reset',
                'btn-shift-report-reset',
                'btn-bom-report-reset',
                'btn-bom-reset-all-base',
                'btn-stock-reset-master',
                'exp-btn-purge',
                'exp-btn-purge-inline',
                'btn-void-purge-sales',
                'btn-settings-reset-store'
            ];
            resetBtnIds.forEach(id => {
                const el = document.getElementById(id);
                if (!el) return;
                if (canReset) {
                    el.classList.remove('hidden');
                    el.style.display = 'flex';
                } else {
                    el.classList.add('hidden');
                    el.style.display = 'none';
                }
            });
        }

        function getUserAssignedBranchId() {
            const curUser = state.currentUser || state.loggedInUser;
            if (curUser && curUser.branch_id) return parseInt(curUser.branch_id);
            if (state.currentBranch && state.currentBranch.id) return parseInt(state.currentBranch.id);
            return 1;
        }

        function getUserAssignedBranch() {
            const uBId = getUserAssignedBranchId();
            return (state.branches || []).find(b => b.id == uBId) || state.currentBranch || { id: uBId, name: 'Cabang Penugasan' };
        }

        function renderBranchOptions() {
            const select = document.getElementById('branch-select');
            const sideSelect = document.getElementById('sidebar-branch-select');
            const sideLockBadge = document.getElementById('sidebar-branch-lock-badge');
            if (!select && !sideSelect) return;
            const curUser = state.currentUser || state.loggedInUser;
            const isSuper = canUserAccessAllBranches();
            const userRole = String((curUser ? curUser.role : '') || '').toUpperCase().replace(/[^A-Z]/g, '');
            const isManager = ['BRANCHMANAGER', 'MANAGER'].includes(userRole);

            // Tentukan cabang yang diizinkan untuk diakses user ini
            let allowedBranches = state.branches || [];
            if (!isSuper) {
                if (isManager && Array.isArray((curUser && curUser.assigned_branch_ids)) && curUser.assigned_branch_ids.length > 0) {
                    const assignedSet = new Set(curUser.assigned_branch_ids.map(Number));
                    allowedBranches = (state.branches || []).filter(b => assignedSet.has(Number(b.id)));
                } else if (isManager && Array.isArray((curUser && curUser.assigned_branches)) && curUser.assigned_branches.length > 0) {
                    allowedBranches = curUser.assigned_branches;
                } else {
                    const userBranch = getUserAssignedBranch();
                    allowedBranches = userBranch ? [userBranch] : [];
                }
            }

            if (allowedBranches.length <= 1) {
                const b = allowedBranches[0] || getUserAssignedBranch();
                if (select) {
                    select.innerHTML = `<option value="${b.id}" selected>🔒 ${b.name} (Terkunci)</option>`;
                    select.disabled = true;
                    select.title = "Lokasi operasional Anda terkunci pada cabang penugasan.";
                }
                if (sideSelect) {
                    sideSelect.innerHTML = `<option value="${b.id}" selected>${b.name}</option>`;
                    sideSelect.disabled = true;
                }
                if (sideLockBadge) sideLockBadge.classList.remove('hidden');
                if (state.currentBranch && state.currentBranch.id !== b.id) {
                    state.currentBranch = b;
                }
            } else {
                if (select) {
                    select.disabled = false;
                    select.title = isSuper ? "Pilih cabang untuk memantau/mengelola operasional (Akses Global)" : "Pilih cabang tugas Anda (Multi-Cabang Manager)";
                }
                if (sideSelect) {
                    sideSelect.disabled = false;
                }
                if (sideLockBadge) sideLockBadge.classList.add('hidden');
                const activeBId = state.currentBranch ? state.currentBranch.id : (allowedBranches[0] ? allowedBranches[0].id : 1);
                const optsHtml = allowedBranches.map(b => 
                    `<option value="${b.id}" ${b.id === activeBId ? 'selected' : ''}>${b.name}</option>`
                ).join('');
                if (select) select.innerHTML = optsHtml;
                if (sideSelect) sideSelect.innerHTML = optsHtml;
            }
        }

        async function onSidebarBranchChange() {
            const sideSelect = document.getElementById('sidebar-branch-select');
            const topSelect = document.getElementById('branch-select');
            if (sideSelect && topSelect) {
                topSelect.value = sideSelect.value;
            }
            await onBranchChange();
        }

        async function onBranchChange() {
            const topSelect = document.getElementById('branch-select');
            const sideSelect = document.getElementById('sidebar-branch-select');
            const bId = (topSelect && topSelect.value) ? topSelect.value : (sideSelect ? sideSelect.value : null);
            if (sideSelect && topSelect && sideSelect.value !== topSelect.value) {
                sideSelect.value = topSelect.value;
            }
            state.currentBranch = (state.branches || []).find(b => b.id == bId) || state.currentBranch;
            initApp();
            if (state.currentTab === 'stocks') loadStockInventory();
            if (state.currentTab === 'reports') {
                if (state.reportActiveSubtab === 'receivables') loadReceivablesReport();
                else loadSalesReports();
            }
            if (state.currentTab === 'pnl') loadProfitLoss();
            if (state.currentTab === 'sale-cancellations') loadSaleCancellations();
        }

        // ==========================================
        // 1. POS LOGIC
        // ==========================================
        function isRawMaterialCategory(cat) {
            if (!cat) return false;
            var code = String(cat.code || '').toUpperCase().trim();
            var name = String(cat.name || '').toLowerCase().trim();
            if (code === 'CAT-RAW' || code === 'RAW_MATERIAL' || code.indexOf('RAW') !== -1) {
                return true;
            }
            if (name.indexOf('bahan baku') !== -1 || name.indexOf('raw material') !== -1) {
                return true;
            }
            return false;
        }

        function renderCategoryPills() {
            const container = document.getElementById('category-pills');
            if (!container) return;
            const cats = (Array.isArray(state.categories) ? state.categories : []).filter(function(cat) {
                return !isRawMaterialCategory(cat);
            });
            if (state.selectedCategory && state.selectedCategory !== 'ALL' && isRawMaterialCategory({ name: state.selectedCategory })) {
                state.selectedCategory = 'ALL';
            }
            const pillsHtml = cats.map(function(cat) {
                var isSelected = (state.selectedCategory === cat.name);
                var activeCls = isSelected 
                    ? 'cat-pill px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white transition-colors'
                    : 'cat-pill px-3 py-1.5 rounded-xl text-xs font-semibold bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 transition-colors';
                return `<button onclick="setCategoryFilter('${escapeHtml(cat.name)}')" class="${activeCls}">${cat.icon_emoji ? cat.icon_emoji + ' ' : ''}${cat.name}</button>`;
            }).join('');
            var allActiveCls = (state.selectedCategory === 'ALL' || !state.selectedCategory)
                ? 'cat-pill px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white transition-colors'
                : 'cat-pill px-3 py-1.5 rounded-xl text-xs font-semibold bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 transition-colors';
            container.innerHTML = `<button onclick="setCategoryFilter('ALL')" class="${allActiveCls}">Semua</button>` + pillsHtml;
        }

        function setCategoryFilter(cat) {
            state.selectedCategory = cat;
            document.querySelectorAll('.cat-pill').forEach(function(btn) {
                if ((cat === 'ALL' && btn.innerText.trim() === 'Semua') || (cat !== 'ALL' && btn.innerText.includes(cat))) {
                    btn.className = 'cat-pill px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white transition-colors';
                } else {
                    btn.className = 'cat-pill px-3 py-1.5 rounded-xl text-xs font-semibold bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 transition-colors';
                }
            });
            renderProducts();
        }

        var _filterProductsTimer = null;
        function filterProducts() {
            if (_filterProductsTimer) clearTimeout(_filterProductsTimer);
            _filterProductsTimer = setTimeout(function() {
                var searchInput = document.getElementById('product-search');
                state.searchKeyword = searchInput ? searchInput.value.toLowerCase().trim() : '';
                renderProducts();
            }, 120);
        }

        function renderProducts() {
            const grid = document.getElementById('products-grid');
            if (!grid) return;
            const activeCust = state.selectedCustomer;
            const activeCat = state.selectedCustomerCategory || (activeCust ? activeCust.category : 'REGULER');
            const catObj = (state.customerCategories || []).find(c => c.code === activeCat || c.name === activeCat || c.id == activeCat);
            const tier = (catObj && catObj.default_tier) ? catObj.default_tier : activeCat;
            const isMitraTier = (tier === 'MITRA');

            const filtered = state.products.filter(function(p) {
                if (p.product_type === 'RAW_MATERIAL') return false;
                var pCat = String(p.category || '').toLowerCase();
                if (pCat.indexOf('bahan baku') !== -1 || pCat.indexOf('raw material') !== -1) return false;

                // ATURAN PRODUK MITRA: Hanya menampilkan produk yang diset kontrak aktif. Jika tidak diset maka produk tidak dimunculkan di menu pos penjualan
                if (isMitraTier) {
                    if (!activeCust || !activeCust.id) {
                        return false; // Mitra belum dipilih, sembunyikan katalog sampai mitra dipilih
                    }
                    const customContract = (state.mitraPrices || []).find(function(mp) {
                        return (String(mp.customer_id) === String(activeCust.id)) && (String(mp.product_id) === String(p.id));
                    });
                    const isContractActive = customContract && Number(customContract.custom_price) > 0;
                    if (!isContractActive) {
                        return false; // Produk tidak diset kontrak aktif -> jangan munculkan di menu POS
                    }
                }

                const matchCat = (state.selectedCategory === 'ALL' || (p.category || '').toLowerCase() === (state.selectedCategory || '').toLowerCase());
                const matchKeyword = (!state.searchKeyword || p.name.toLowerCase().includes(state.searchKeyword) || p.sku.toLowerCase().includes(state.searchKeyword));
                return matchCat && matchKeyword;
            });

            if (filtered.length === 0) {
                if (isMitraTier) {
                    if (!activeCust || !activeCust.id) {
                        grid.innerHTML = `
                            <div class="col-span-full text-center py-12 text-slate-400 dark:text-slate-500 text-sm">
                                <div class="text-3xl mb-2">🤝</div>
                                <div class="font-bold text-slate-700 dark:text-slate-300">Pilih Mitra Terlebih Dahulu</div>
                                <div class="text-xs text-slate-400 mt-1">Hanya produk yang diset kontrak aktif untuk mitra tersebut yang akan dimunculkan di menu POS penjualan.</div>
                            </div>
                        `;
                    } else {
                        grid.innerHTML = `
                            <div class="col-span-full text-center py-12 text-slate-400 dark:text-slate-500 text-sm">
                                <div class="text-3xl mb-2">📋</div>
                                <div class="font-bold text-slate-700 dark:text-slate-300">Tidak Ada Produk Kontrak Aktif</div>
                                <div class="text-xs text-slate-400 mt-1">Mitra <b>${escapeHtml(activeCust.name)}</b> belum memiliki produk yang diset kontrak aktif.<br>Silakan atur kontrak harga di menu <b>Pelanggan &gt; Kontrak Khusus Mitra</b>.</div>
                            </div>
                        `;
                    }
                } else {
                    grid.innerHTML = `<div class="col-span-3 text-center py-12 text-slate-400 dark:text-slate-500 text-sm">Tidak ada produk jadi ditemukan</div>`;
                }
                return;
            }

            // Performa Tinggi untuk Android RAM 2GB: Lazy slicing jika produk sangat banyak tanpa filter
            const maxInitial = 48;
            const needSlice = (!state.showAllProducts && !state.searchKeyword && state.selectedCategory === 'ALL' && filtered.length > maxInitial);
            const displayList = needSlice ? filtered.slice(0, maxInitial) : filtered;

            let html = displayList.map(p => {
                const priceInfo = getEffectiveProductPrice(p);
                const hasVariants = (p.variants && p.variants.length > 0);
                return `
                    <div onclick="onProductClick(${p.id})" class="bg-white dark:bg-slate-900 p-3.5 rounded-2xl border border-slate-200 dark:border-slate-800 hover:border-indigo-400 dark:hover:border-indigo-500 hover:shadow-md cursor-pointer transition-all flex flex-col justify-between group">
                        <div>
                            <div class="flex items-center justify-between mb-1.5">
                                <span class="text-3xl">${p.image_emoji || '📦'}</span>
                                <div class="flex flex-col items-end">
                                    ${(Number(p.is_stockable) === 2)
                                        ? `<span class="text-[10px] px-2 py-0.5 rounded-full font-bold bg-amber-100 dark:bg-amber-950/80 text-amber-800 dark:text-amber-300 border border-amber-300 dark:border-amber-700" title="Mode Hibrida: Fisik dihitung dan bebas jual On-Demand">🔄 Hibrida (Stok: ${formatDecimal(p.stock)})</span>`
                                        : ((p.requires_stock === 0 || p.is_stockable === 0 || p.cat_is_stockable === 0)
                                            ? '<span class="text-[10px] px-2 py-0.5 rounded-full font-bold bg-violet-100 dark:bg-violet-950/80 text-violet-800 dark:text-violet-300 border border-violet-200 dark:border-violet-800">⚡ Tanpa Stok (BOM)</span>'
                                            : `<span class="text-[10px] px-2 py-0.5 rounded-full font-bold ${p.stock > 10 ? 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300' : 'bg-rose-100 dark:bg-rose-950/80 text-rose-600 dark:text-rose-300'}">Stok: ${formatDecimal(p.stock)}</span>`)}
                                    ${p.has_bom ? '<span class="text-[9px] text-indigo-600 dark:text-indigo-400 font-bold mt-0.5">🧪 Pakai Resep</span>' : ''}
                                </div>
                            </div>
                            <h4 class="font-bold text-xs sm:text-sm text-slate-800 dark:text-slate-100 line-clamp-2 group-hover:text-indigo-600 dark:group-hover:text-indigo-400 transition-colors leading-snug">${p.name}</h4>
                            <p class="text-[10px] text-slate-400 dark:text-slate-500 mt-0.5">${p.sku}</p>
                        </div>
                        <div class="mt-3 flex items-center justify-between border-t border-slate-100 dark:border-slate-800 pt-2">
                            <span class="font-black text-xs sm:text-sm text-indigo-700 dark:text-indigo-400">${formatRupiah(priceInfo.price)}</span>
                            <span class="px-2 py-1 rounded-lg bg-indigo-50 dark:bg-indigo-950/70 text-indigo-600 dark:text-indigo-400 flex items-center justify-center text-xs font-bold group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                                ${hasVariants ? 'Pilih Varian' : '+'}
                            </span>
                        </div>
                    </div>
                `;
            }).join('');

            if (needSlice) {
                html += `
                    <div class="col-span-full text-center py-2">
                        <button type="button" onclick="state.showAllProducts=true; renderProducts();" class="w-full py-2.5 px-4 bg-indigo-50 dark:bg-slate-800 hover:bg-indigo-100 dark:hover:bg-slate-700 text-indigo-700 dark:text-indigo-300 font-bold text-xs rounded-xl border border-indigo-200 dark:border-slate-700 transition-colors cursor-pointer shadow-2xs">
                            Muat Seluruh Produk (+${filtered.length - maxInitial} produk lagi)
                        </button>
                    </div>
                `;
            }

            grid.innerHTML = html;
        }

        function onProductClick(productId) {
            // Validasi Cross-Day Shift (Konfirmasi Pergantian Hari & End Day Shift Kemarin)
            if (checkCrossDayShiftBeforeAction(function() { onProductClick(productId); })) {
                return;
            }

            const product = state.products.find(p => p.id === productId);
            if (!product) return;

            // Validasi: Wajib pilih pelanggan terlebih dahulu untuk menentukan tier harga & jarak kirim
            if (!state.selectedCustomer) {
                openSelectCustomerModal(productId, null);
                return;
            }

            // ATURAN PRODUK MITRA: Hanya produk dengan Kontrak Aktif yang dapat dipilih
            const cust = state.selectedCustomer;
            const cat = state.selectedCustomerCategory || (cust ? cust.category : 'REGULER');
            const catObj = (state.customerCategories || []).find(c => c.code === cat || c.name === cat || c.id == cat);
            const tier = (catObj && catObj.default_tier) ? catObj.default_tier : cat;
            if (tier === 'MITRA') {
                const customContract = (state.mitraPrices || []).find(function(mp) {
                    return (String(mp.customer_id) === String(cust.id)) && (String(mp.product_id) === String(product.id));
                });
                const isContractActive = customContract && Number(customContract.custom_price) > 0;
                if (!isContractActive) {
                    alert("Produk '" + product.name + "' tidak dapat dipilih karena belum diset Kontrak Aktif untuk mitra '" + (cust.name || '') + "'.\n\nHanya produk yang diset kontrak aktif yang dapat ditransaksikan di POS.");
                    return;
                }
            }

            const isProductStrictStock = (Number(_nn(product.is_stockable, 1)) === 1 && Number(_nn(product.cat_is_stockable, 1)) === 1 && product.requires_stock !== 0);
            if (isProductStrictStock && product.stock <= 0) {
                alert(`Stok '${product.name}' habis di cabang ini!`);
                return;
            }

            if (product.variants && product.variants.length > 0) {
                openVariantSelectModal(product);
            } else {
                addToCart(product.id, null);
            }
        }

        function openVariantSelectModal(product) {
            document.getElementById('vsm-product-emoji').innerText = product.image_emoji || '📦';
            document.getElementById('vsm-product-name').innerText = product.name;
            document.getElementById('vsm-product-sku').innerText = `${product.sku} • Stok: ${formatDecimal(product.stock)} ${product.unit}`;

            const basePriceInfo = getEffectiveProductPrice(product);

            const optionsContainer = document.getElementById('vsm-options-list');
            optionsContainer.innerHTML = product.variants.map(v => {
                const addPrice = Number(v.additional_price || 0);
                const finalVarPrice = basePriceInfo.price + addPrice;
                const hasVarBOM = v.ingredients && v.ingredients.length > 0;
                const bomDeductionSummary = hasVarBOM 
                    ? v.ingredients.map(ing => `<span class="inline-block bg-rose-50 text-rose-700 border border-rose-200 px-1.5 py-0.5 rounded text-[10px] mr-1 mt-0.5 font-bold">🔻 Potong Stok: ${formatDecimal(ing.qty_needed)} ${ing.unit} ${ing.ingredient_name}</span>`).join('')
                    : `<span class="inline-block bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700 px-1.5 py-0.5 rounded text-[10px] mr-1 mt-0.5 font-medium">🛡️ Tanpa potong stok bahan baku</span>`;

                const priceBadge = addPrice > 0
                    ? `<span class="inline-block px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-300">+${formatRupiah(addPrice)} (Ada Tambahan Harga)</span>`
                    : `<span class="inline-block px-2 py-0.5 rounded-full text-[10px] font-black bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 border border-slate-300">+Rp 0 (Tanpa Tambahan Biaya / Normal)</span>`;

                return `
                    <div onclick="selectProductVariant(${product.id}, ${v.id})" class="p-3 bg-slate-50 dark:bg-slate-800/60 hover:bg-indigo-50/70 border border-slate-200 dark:border-slate-700 hover:border-indigo-400 rounded-2xl cursor-pointer transition-all flex flex-col justify-between group">
                        <div class="flex items-center justify-between">
                            <div>
                                <h4 class="font-black text-xs text-slate-800 group-hover:text-indigo-900">${v.variant_name}</h4>
                                <span class="text-[10px] text-slate-400 font-mono">${v.sku_variant || ''}</span>
                            </div>
                            <div class="text-right">
                                <span class="font-black text-sm text-indigo-700 font-mono">${formatRupiah(finalVarPrice)}</span>
                                <div class="mt-0.5">
                                    ${priceBadge}
                                </div>
                            </div>
                        </div>
                        <div class="mt-2 pt-2 border-t border-slate-200/60">
                            ${bomDeductionSummary}
                        </div>
                    </div>
                `;
            }).join('');

            document.getElementById('variant-select-modal').classList.remove('hidden');
        }

        function closeVariantSelectModal() {
            document.getElementById('variant-select-modal').classList.add('hidden');
        }

        function selectProductVariant(productId, variantId) {
            closeVariantSelectModal();
            addToCart(productId, variantId);
        }

        function addToCart(productId, variantId = null) {
            // Validasi: Wajib pilih pelanggan terlebih dahulu untuk menentukan tier harga & jarak kirim
            if (!state.selectedCustomer) {
                openSelectCustomerModal(productId, variantId);
                return;
            }

            const product = state.products.find(p => p.id === productId);
            if (!product) return;

            // ATURAN PRODUK MITRA: Hanya produk dengan Kontrak Aktif yang dapat dimasukkan ke keranjang
            const cust = state.selectedCustomer;
            const cat = state.selectedCustomerCategory || (cust ? cust.category : 'REGULER');
            const catObj = (state.customerCategories || []).find(c => c.code === cat || c.name === cat || c.id == cat);
            const tier = (catObj && catObj.default_tier) ? catObj.default_tier : cat;
            if (tier === 'MITRA') {
                const customContract = (state.mitraPrices || []).find(function(mp) {
                    return (String(mp.customer_id) === String(cust.id)) && (String(mp.product_id) === String(product.id));
                });
                const isContractActive = customContract && Number(customContract.custom_price) > 0;
                if (!isContractActive) {
                    alert("Produk '" + product.name + "' tidak dapat dimasukkan ke keranjang karena belum diset Kontrak Aktif untuk mitra '" + (cust.name || '') + "'.\n\nHanya produk yang diset kontrak aktif yang dapat ditransaksikan di POS.");
                    return;
                }
            }

            const isProductStrictStock = (Number(_nn(product.is_stockable, 1)) === 1 && Number(_nn(product.cat_is_stockable, 1)) === 1 && product.requires_stock !== 0);
            if (isProductStrictStock && product.stock <= 0) {
                alert(`Stok '${product.name}' habis di cabang ini!`);
                return;
            }

            const basePriceInfo = getEffectiveProductPrice(product);
            let finalPrice = basePriceInfo.price;
            let finalCogs = product.cogs;
            let variantObj = null;

            if (variantId && product.variants) {
                variantObj = product.variants.find(v => v.id === variantId);
                if (variantObj) {
                    finalPrice += Number(variantObj.additional_price || 0);
                    finalCogs += Number(variantObj.additional_cogs || 0);
                }
            }

            // Unik item key di keranjang
            const itemKey = `${productId}_${variantId || 'novar'}`;
            const existing = state.cart.find(c => c.item_key === itemKey);

            if (existing) {
                if (existing.requires_stock && existing.qty + 1 > product.stock) {
                    alert(`Tidak dapat melebihi stok yang tersedia (${product.stock} pcs).`);
                    return;
                }
                existing.qty += 1;
                // Pindahkan ke urutan pertama agar produk terakhir diinput selalu berada di paling atas (FR-POS-33)
                const existingIdx = state.cart.indexOf(existing);
                if (existingIdx > 0) {
                    state.cart.splice(existingIdx, 1);
                    state.cart.unshift(existing);
                }
            } else {
                state.cart.unshift({
                    item_key: itemKey,
                    product_id: product.id,
                    variant_id: variantId,
                    variant_name: variantObj ? variantObj.variant_name : null,
                    name: product.name,
                    price: finalPrice,
                    cogs: finalCogs,
                    qty: 1,
                    max_stock: isProductStrictStock ? product.stock : 999999,
                    requires_stock: isProductStrictStock,
                    price_tag: basePriceInfo.tag,
                    is_taxable: (product.is_taxable !== undefined) ? Number(product.is_taxable) : 1,
                    tax_percent: (product.tax_percent !== undefined) ? Number(product.tax_percent) : 11.0,
                    has_variant_bom: variantObj ? (variantObj.ingredients && variantObj.ingredients.length > 0) : false,
                    is_delivery_required: (product.is_delivery_required !== undefined) ? Number(product.is_delivery_required) : 0,
                    is_delivery_included: (product.is_delivery_included !== undefined) ? Number(product.is_delivery_included) : (Number(product.is_delivery_required) === 2 ? 1 : 0)
                });
            }
            renderCart();
            checkMandatoryDeliveryOnCart();
        }

        function toggleDeliveryCollapse(forceState = null) {
            if (forceState !== null) {
                state.isDeliveryCollapsed = forceState;
            } else {
                state.isDeliveryCollapsed = !state.isDeliveryCollapsed;
            }

            const box = document.getElementById('pos-delivery-box');
            const toggleText = document.getElementById('pos-delivery-collapse-text');
            const toggleIcon = document.getElementById('pos-delivery-collapse-icon');

            if (!box) return;

            if (state.isDeliveryCollapsed) {
                box.classList.add('hidden');
                if (toggleText) toggleText.innerText = 'Detail';
                if (toggleIcon) toggleIcon.setAttribute('data-lucide', 'chevron-down');
            } else {
                box.classList.remove('hidden');
                if (toggleText) toggleText.innerText = 'Tutup';
                if (toggleIcon) toggleIcon.setAttribute('data-lucide', 'chevron-up');
            }
            lucide.createIcons();
        }

        function resetPosDelivery(skipTotalsRecalc = false) {
            const delivCheckbox = document.getElementById('check-delivery-mode');
            if (delivCheckbox) delivCheckbox.checked = false;

            const badge = document.getElementById('pos-delivery-badge');
            if (badge) badge.classList.add('hidden');

            const actions = document.getElementById('pos-delivery-header-actions');
            if (actions) actions.classList.add('hidden');

            const box = document.getElementById('pos-delivery-box');
            if (box) box.classList.add('hidden');

            state.isDeliveryCollapsed = true;
            state.currentDeliveryFee = 0;
            state.currentDeliveryDistance = 0;
            state.currentPosDriverUserId = null;
            state.currentPosDriverName = null;
            state.currentPosVehicleId = null;

            const pill = document.getElementById('pos-delivery-summary-pill');
            if (pill) pill.innerText = '0 km • GRATIS';

            const noteEl = document.getElementById('pos-delivery-note');
            if (noteEl) {
                noteEl.innerHTML = '';
                noteEl.classList.add('hidden');
            }

            const distEl = document.getElementById('pos-delivery-distance');
            if (distEl) distEl.innerText = '-';

            const feeEl = document.getElementById('pos-delivery-fee-display');
            if (feeEl) {
                feeEl.innerText = 'Rp 0';
                feeEl.className = 'font-black text-amber-700 font-mono text-xs';
            }

            if (!skipTotalsRecalc) {
                calculateCartTotals();
            }
        }

        function checkMandatoryDeliveryOnCart() {
            const delivCheckbox = document.getElementById('check-delivery-mode');
            if (!delivCheckbox) return;

            if (!state.cart || state.cart.length === 0) {
                resetPosDelivery(false);
                return;
            }

            const isFreeItem = (c) => Number(c.is_delivery_included) === 1 || Number(c.is_delivery_required) === 2;
            const freeDeliveryItems = (state.cart || []).filter(isFreeItem);
            const chargeableItems = (state.cart || []).filter(c => !isFreeItem(c));
            const mandatoryItems = (state.cart || []).filter(c => Number(c.is_delivery_required) === 1);

            const needsDelivery = (mandatoryItems.length > 0 || freeDeliveryItems.length > 0);

            if (needsDelivery && !delivCheckbox.checked) {
                delivCheckbox.checked = true;
                onDeliveryToggleChange();
            } else if (delivCheckbox.checked) {
                calculateDeliveryFeeForPOS();
            }
        }

        function updateCartQty(itemKey, delta) {
            const item = (state.cart || []).find(c => c.item_key === itemKey);
            if (!item) return;
            item.qty += delta;
            if (item.qty <= 0) {
                removeFromCart(itemKey);
                return;
            }
            if (item.requires_stock && item.qty > item.max_stock) {
                alert(`Maksimal stok tersedia adalah ${item.max_stock}.`);
                item.qty = item.max_stock;
            }
            renderCart();
            checkMandatoryDeliveryOnCart();
        }

        function removeFromCart(itemKey) {
            state.cart = (state.cart || []).filter(c => c.item_key !== itemKey);
            if (state.cart.length === 0) {
                resetPosDelivery(true);
            }
            renderCart();
            checkMandatoryDeliveryOnCart();
        }

        function clearCart() {
            state.cart = [];
            resetPosDelivery(true);
            const discEl = document.getElementById('input-discount');
            if (discEl) discEl.value = 0;
            state.appliedDiscount = null;
            state.manualPromoSelected = false;
            const apb = document.getElementById('pos-active-promo-banner');
            if (apb) apb.classList.add('hidden');
            const cashEl = document.getElementById('input-cash-received');
            if (cashEl) cashEl.value = '';
            renderCart();
        }

        function renderCart() {
            const container = document.getElementById('cart-items');
            const countBadge = document.getElementById('cart-item-count-badge');
            if (countBadge) {
                const totalQty = (state.cart || []).reduce((sum, item) => sum + item.qty, 0);
                countBadge.innerText = `${totalQty} Item`;
            }

            if (!state.cart || state.cart.length === 0) {
                state.cart = [];
                resetPosDelivery(true);
                container.innerHTML = `
                    <div class="h-full flex flex-col items-center justify-center text-slate-400 dark:text-slate-500 text-sm py-12">
                        <i data-lucide="shopping-cart" class="w-12 h-12 mb-2 stroke-1"></i>
                        <p class="font-medium">Keranjang masih kosong</p>
                        <p class="text-xs text-slate-400 dark:text-slate-500 mt-0.5">Pilih produk di katalog sebelah kiri</p>
                    </div>
                `;
                calculateCartTotals();
                lucide.createIcons();
                return;
            }

            container.innerHTML = state.cart.map((item, index) => {
                const isLatest = (index === 0 && state.cart.length > 1);
                return `
                <div class="py-2.5 flex items-center justify-between text-xs border-b border-slate-100 dark:border-slate-800 last:border-b-0 ${isLatest ? 'bg-indigo-50/50 dark:bg-indigo-950/40 -mx-1.5 px-2 rounded-xl border border-indigo-100/90 dark:border-indigo-800/60 shadow-2xs' : ''}">
                    <div class="flex-1 pr-2">
                        <div class="flex items-center space-x-1.5">
                            <h4 class="font-bold text-slate-800 dark:text-slate-100 line-clamp-1">${item.name}</h4>
                            ${isLatest ? `<span class="inline-flex items-center text-[9px] px-1.5 py-0.2 bg-indigo-600 text-white rounded font-black shadow-2xs shrink-0">✨ Terbaru</span>` : ''}
                        </div>
                        ${item.variant_name ? `<div class="mt-0.5"><span class="inline-block text-[10px] px-2 py-0.5 bg-purple-100 dark:bg-purple-950/70 text-purple-800 dark:text-purple-300 rounded font-black">🏷️ ${item.variant_name}</span></div>` : ''}
                        <div class="flex items-center space-x-1.5 mt-0.5">
                            <span class="text-[11px] text-slate-400 dark:text-slate-500 font-mono">${formatRupiah(item.price)} x ${item.qty}</span>
                        </div>
                    </div>
                    <div class="flex items-center space-x-2 shrink-0">
                        <div class="flex items-center border border-slate-200 dark:border-slate-700 rounded-lg bg-slate-50 dark:bg-slate-800">
                            <button onclick="updateCartQty('${item.item_key}', -1)" class="w-6 h-6 flex items-center justify-center text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-l font-bold cursor-pointer">-</button>
                            <span class="w-7 text-center font-bold text-slate-800 dark:text-slate-100">${item.qty}</span>
                            <button onclick="updateCartQty('${item.item_key}', 1)" class="w-6 h-6 flex items-center justify-center text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-r font-bold cursor-pointer">+</button>
                        </div>
                        <span class="font-bold text-slate-800 dark:text-slate-100 w-20 text-right font-mono">${formatRupiah(item.price * item.qty)}</span>
                        <button onclick="removeFromCart('${item.item_key}')" class="text-slate-400 hover:text-rose-500 dark:hover:text-rose-400 p-0.5 cursor-pointer">
                            <i data-lucide="x" class="w-4 h-4"></i>
                        </button>
                    </div>
                </div>
            `;
            }).join('');

            container.scrollTop = 0;
            calculateCartTotals();
            lucide.createIcons();
        }

        function renderPosCourierSelect() {
            const vehicleSelect = document.getElementById('pos-courier-select');
            const driverSelect = document.getElementById('pos-driver-employee-select');
            const driverLabel = document.getElementById('pos-driver-label');
            const vehicleLabel = document.getElementById('pos-vehicle-label');
            const noteEl = document.getElementById('pos-delivery-note');
            const branchId = state.currentBranch ? state.currentBranch.id : 1;

            // 1. Ambil data armada aktif di cabang
            const branchVehicles = (state.vehicles || []).filter(v => (!v.branch_id || v.branch_id === branchId) && v.status === 'ACTIVE');

            // 2. Filter staf operasional di cabang (Kecualikan level manajerial: Super Admin & Branch Manager)
            const operationalEmployees = (state.users || []).filter(u => 
                (!u.branch_id || u.branch_id === branchId) && 
                u.is_active != 0 &&
                !['SUPER_ADMIN', 'SUPERADMIN', 'BRANCH_MANAGER', 'MANAGER'].includes(u.role)
            );

            // 3. Identifikasi pengguna aktif yang login
            const currentUser = state.loggedInUser || state.currentUser;
            const isStaffOrCashier = currentUser && ['CASHIER', 'STAFF', 'OPERATOR'].includes(currentUser.role);

            // Cari armada yang terhubung dengan akun kasir/staf ini
            let linkedVehicle = null;
            if (currentUser) {
                // Prioritas 1: Penugasan eksplisit assigned_vehicle_id pada akun kasir
                if (currentUser.assigned_vehicle_id) {
                    linkedVehicle = branchVehicles.find(v => v.id === currentUser.assigned_vehicle_id) || (state.vehicles || []).find(v => v.id === currentUser.assigned_vehicle_id);
                }
                // Prioritas 2: Penugasan driver_user_id pada armada kendaraan
                if (!linkedVehicle) {
                    linkedVehicle = branchVehicles.find(v => v.driver_user_id === currentUser.id);
                }
            }

            // Cari kurir resmi yang terhubung
            let linkedDriver = null;
            if (linkedVehicle && linkedVehicle.driver_user_id) {
                linkedDriver = (state.users || []).find(u => u.id === linkedVehicle.driver_user_id);
            }
            if (!linkedDriver && currentUser && (linkedVehicle || isStaffOrCashier)) {
                linkedDriver = currentUser;
            }

            // KASUS A: KASIR / STAF OPERASIONAL YANG TERHUBUNG KE KURIR & ARMADA
            // Sesuai aturan: Kurir & armada dikunci secara mutlak (kasir tidak bisa memilih kurir atau kendaraan lainnya)
            if (isStaffOrCashier && (linkedVehicle || linkedDriver)) {
                const driverObj = linkedDriver || currentUser;
                const driverName = driverObj.name;
                const driverId = driverObj.id;

                let vehPlate = '';
                if (linkedVehicle) {
                    vehPlate = linkedVehicle.plate_number;
                } else if (branchVehicles.length > 0) {
                    vehPlate = branchVehicles[0].plate_number;
                }

                // Kunci Driver Select
                if (driverSelect) {
                    driverSelect.innerHTML = `<option value="${driverId}">${driverName}</option>`;
                    driverSelect.value = driverId;
                    driverSelect.disabled = true;
                }

                // Kunci Vehicle Select
                if (vehicleSelect) {
                    if (linkedVehicle) {
                        vehicleSelect.innerHTML = `<option value="${linkedVehicle.id}">${linkedVehicle.plate_number}</option>`;
                        vehicleSelect.value = linkedVehicle.id;
                    } else if (branchVehicles.length > 0) {
                        const fallbackVeh = branchVehicles[0];
                        vehicleSelect.innerHTML = `<option value="${fallbackVeh.id}">${fallbackVeh.plate_number}</option>`;
                        vehicleSelect.value = fallbackVeh.id;
                    } else {
                        vehicleSelect.innerHTML = `<option value="">-</option>`;
                    }
                    vehicleSelect.disabled = true;
                }

                // Simpan parameter aktif di state agar saat submit checkout selalu akurat
                state.currentPosDriverUserId = driverId;
                state.currentPosDriverName = driverName;
                state.currentPosVehicleId = linkedVehicle ? linkedVehicle.id : ((vehicleSelect ? vehicleSelect.value : '') ? parseInt(vehicleSelect.value) : null);

                // Tampilan Ringkas & Bersih
                const lockedView = document.getElementById('pos-driver-locked-view');
                const selectGrid = document.getElementById('pos-driver-select-grid');
                const nameDisplay = document.getElementById('pos-driver-display-name');
                const vehDisplay = document.getElementById('pos-driver-display-vehicle');

                if (lockedView) lockedView.classList.remove('hidden');
                if (selectGrid) selectGrid.classList.add('hidden');

                if (nameDisplay) nameDisplay.innerText = driverName;
                if (vehDisplay) vehDisplay.innerText = vehPlate ? `(${vehPlate})` : '';

                if (noteEl) {
                    noteEl.innerHTML = '';
                    noteEl.classList.add('hidden');
                }
                return;
            }

            // KASUS B: SUPER ADMIN / BRANCH MANAGER (Dapat memilih kurir & armada fleksibel)
            const lockedView = document.getElementById('pos-driver-locked-view');
            const selectGrid = document.getElementById('pos-driver-select-grid');
            if (lockedView) lockedView.classList.add('hidden');
            if (selectGrid) selectGrid.classList.remove('hidden');

            if (driverSelect) {
                driverSelect.disabled = false;
                driverSelect.className = "bg-white border border-indigo-300 rounded-lg px-2 py-0.5 text-xs font-semibold text-slate-800";
                const candidateDrivers = operationalEmployees.length > 0 ? operationalEmployees : (state.users || []).filter(u => (!u.branch_id || u.branch_id === branchId) && u.is_active != 0);
                if (candidateDrivers.length === 0) {
                    driverSelect.innerHTML = '<option value="">(Belum ada staf)</option>';
                } else {
                    driverSelect.innerHTML = candidateDrivers.map(u => 
                        `<option value="${u.id}">${u.name}</option>`
                    ).join('');
                }
            }

            if (vehicleSelect) {
                vehicleSelect.disabled = false;
                vehicleSelect.className = "bg-white border border-indigo-300 rounded-lg px-2 py-0.5 text-xs font-semibold text-slate-800";
                if (branchVehicles.length === 0) {
                    vehicleSelect.innerHTML = '<option value="">(Tanpa armada)</option>';
                } else {
                    vehicleSelect.innerHTML = branchVehicles.map(v => 
                        `<option value="${v.id}">${v.plate_number}</option>`
                    ).join('');
                }
            }

            // Sinkronkan kendaraan yang cocok jika driver dipilih
            onPosDriverEmployeeChange();

            if (noteEl) {
                noteEl.innerHTML = '';
                noteEl.classList.add('hidden');
            }
        }

        function onPosDriverEmployeeChange() {
            const driverSelect = document.getElementById('pos-driver-employee-select');
            const vehicleSelect = document.getElementById('pos-courier-select');
            if (!driverSelect || !vehicleSelect) return;

            const selectedDriverId = parseInt(driverSelect.value);
            if (!selectedDriverId) return;

            // Jika ada kendaraan yang diasosiasikan dengan driver ini, otomatis pilih kendaraan tersebut
            const matchedVehicle = (state.vehicles || []).find(v => v.driver_user_id === selectedDriverId && v.status === 'ACTIVE');
            if (matchedVehicle) {
                vehicleSelect.value = matchedVehicle.id;
            }
        }

        async function onDeliveryToggleChange() {
            const isChecked = _chk('check-delivery-mode') || false;
            const badge = document.getElementById('pos-delivery-badge');
            const box = document.getElementById('pos-delivery-box');

            // Proteksi agar kasir tidak sengaja menonaktifkan delivery saat produk pengiriman ada di keranjang
            const isFreeItem = (c) => Number(c.is_delivery_included) === 1 || Number(c.is_delivery_required) === 2;
            const freeDeliveryItems = (state.cart || []).filter(isFreeItem);
            const chargeableItems = (state.cart || []).filter(c => !isFreeItem(c));
            const mandatoryItems = (state.cart || []).filter(c => Number(c.is_delivery_required) === 1);

            if (!isChecked && (mandatoryItems.length > 0 || freeDeliveryItems.length > 0)) {
                let alertMsg = '';
                if (freeDeliveryItems.length > 0 && chargeableItems.length > 0) {
                    const freeNames = freeDeliveryItems.map(i => i.name).join(', ');
                    const chargeNames = chargeableItems.map(i => i.name).join(', ');
                    alertMsg = `PERINGATAN PESANAN CAMPURAN:\nKeranjang memuat produk gratis ongkir (${freeNames}) dan produk yang dikenakan ongkir (${chargeNames}).\n\nJika layanan antar dimatikan, pesanan ini akan dicatat sebagai ambil di toko (tanpa kurir & tanpa ongkir).\nApakah kasir tetap ingin menonaktifkan layanan antar?`;
                } else if (mandatoryItems.length > 0) {
                    const names = mandatoryItems.map(i => i.name).join(', ');
                    alertMsg = `PERINGATAN ONGKIR:\nKeranjang memuat produk yang wajib dikenakan ongkos kirim (${names}).\n\nJika layanan antar dimatikan, pesanan ini tidak akan memiliki biaya ongkir.\nApakah kasir tetap ingin menonaktifkan layanan antar?`;
                } else {
                    const names = freeDeliveryItems.map(i => i.name).join(', ');
                    alertMsg = `PERINGATAN PENGIRIMAN:\nKeranjang memuat produk yang sudah termasuk biaya kirim (${names}) dan memerlukan pencatatan kurir pengantar.\n\nApakah kasir yakin ingin menonaktifkan layanan antar (ambil di toko)?`;
                }
                const confirmOff = confirm(alertMsg);
                if (!confirmOff) {
                    document.getElementById('check-delivery-mode').checked = true;
                    return;
                }
            }

            if (isChecked) {
                const actions = document.getElementById('pos-delivery-header-actions');
                if (actions) actions.classList.remove('hidden');
                if (badge) badge.classList.add('hidden');
                // Standar tampilan: Default Collapse (FR-POS-33)
                state.isDeliveryCollapsed = true;
                toggleDeliveryCollapse(true);
                renderPosCourierSelect();
                await calculateDeliveryFeeForPOS();
                lucide.createIcons();
            } else {
                const actions = document.getElementById('pos-delivery-header-actions');
                if (actions) actions.classList.add('hidden');
                if (badge) badge.classList.add('hidden');
                if (box) box.classList.add('hidden');
                state.currentDeliveryFee = 0;
                state.currentDeliveryDistance = 0;
                calculateCartTotals();
            }
        }

        async function calculateDeliveryFeeForPOS() {
            const isChecked = _chk('check-delivery-mode') || false;
            if (!isChecked) return;

            const feeEl = document.getElementById('pos-delivery-fee-display');
            const noteEl = document.getElementById('pos-delivery-note');
            const distEl = document.getElementById('pos-delivery-distance');

            const isFreeItem = (c) => Number(c.is_delivery_included) === 1 || Number(c.is_delivery_required) === 2;
            const freeDeliveryItems = (state.cart || []).filter(isFreeItem);
            const chargeableItems = (state.cart || []).filter(c => !isFreeItem(c));
            const isEntirelyFreeDelivery = (freeDeliveryItems.length > 0 && chargeableItems.length === 0);

            const subtotal = (state.cart || []).reduce((acc, c) => acc + (c.price * c.qty), 0);
            const branch = state.currentBranch;
            const branchId = branch ? branch.id : 1;
            const cust = state.selectedCustomer;

            // 1. Hitung estimasi jarak lokal seketika (Client-side Haversine) jika koordinat tersedia
            let branchLat = branch ? parseFloat(branch.latitude) : null;
            let branchLon = branch ? parseFloat(branch.longitude) : null;
            let custLat = cust ? parseFloat(cust.latitude) : null;
            let custLon = cust ? parseFloat(cust.longitude) : null;

            let localDistKm = null;
            if (branchLat && branchLon && custLat && custLon && 
                !isNaN(branchLat) && !isNaN(branchLon) && !isNaN(custLat) && !isNaN(custLon) && 
                !(custLat === 0 && custLon === 0) && !(branchLat === 0 && branchLon === 0)) {
                localDistKm = getHaversineDistanceKm(branchLat, branchLon, custLat, custLon);
                state.currentDeliveryDistance = localDistKm;
                if (distEl) distEl.innerText = `${formatDecimal(localDistKm)} km`;
            } else {
                state.currentDeliveryDistance = 0;
                if (distEl) distEl.innerText = '-';
            }

            // 2. Hubungi endpoint API untuk kalkulasi dinamis tarif dan jarak presisi
            let url = `api.php?action=calculate_delivery_fee&branch_id=${branchId}&subtotal=${subtotal}`;
            if (cust && cust.id) {
                url += `&customer_id=${cust.id}`;
            }

            try {
                const res = await fetch(url);
                const data = await res.json();
                
                let distKm = localDistKm;
                if (data.success && data.has_coordinates && data.distance_km !== undefined) {
                    distKm = parseFloat(data.distance_km);
                    state.currentDeliveryDistance = distKm;
                    if (distEl) distEl.innerText = `${formatDecimal(distKm)} km`;
                }

                if (isEntirelyFreeDelivery) {
                    // Kasus 1: Seluruh item dalam keranjang adalah produk GRATIS ONGKIR
                    state.currentDeliveryFee = 0;
                    if (feeEl) {
                        feeEl.innerText = 'GRATIS';
                        feeEl.className = 'font-black text-emerald-600 font-mono text-xs';
                    }
                    if (noteEl) {
                        noteEl.innerHTML = '';
                        noteEl.classList.add('hidden');
                    }
                } else if (data.success) {
                    // Kasus 2: Berhasil kalkulasi tarif dinamis berdasarkan jarak
                    state.currentDeliveryFee = data.delivery_fee;
                    const isPromoFree = Boolean(data.is_free || data.is_free_delivery);
                    if (feeEl) {
                        feeEl.innerText = isPromoFree ? 'GRATIS' : formatRupiah(data.delivery_fee);
                        feeEl.className = isPromoFree ? 'font-black text-emerald-600 font-mono text-xs' : 'font-black text-amber-700 font-mono text-xs';
                    }
                    if (noteEl) {
                        noteEl.innerHTML = '';
                        noteEl.classList.add('hidden');
                    }
                } else {
                    // Kasus 3: Titik koordinat pelanggan belum diatur di CRM
                    const baseFee = (state.currentDeliverySetting ? state.currentDeliverySetting.base_fee : 10000) || 10000;
                    state.currentDeliveryFee = baseFee;
                    if (distEl && (localDistKm === null || localDistKm === 0)) distEl.innerText = '-';
                    if (feeEl) {
                        feeEl.innerText = formatRupiah(baseFee);
                        feeEl.className = 'font-black text-amber-700 font-mono text-xs';
                    }
                    if (noteEl) {
                        noteEl.innerHTML = `⚠️ Koordinat belum diatur (Tarif flat)`;
                        noteEl.classList.remove('hidden');
                    }
                }
            } catch (err) {
                console.error('Gagal kalkulasi ongkir:', err);
                if (isEntirelyFreeDelivery) {
                    state.currentDeliveryFee = 0;
                    if (feeEl) {
                        feeEl.innerText = 'GRATIS';
                        feeEl.className = 'font-black text-emerald-600 font-mono text-xs';
                    }
                } else {
                    state.currentDeliveryFee = 10000;
                    if (feeEl) {
                        feeEl.innerText = formatRupiah(10000);
                        feeEl.className = 'font-black text-amber-700 font-mono text-xs';
                    }
                }
                if (noteEl) {
                    noteEl.innerHTML = '';
                    noteEl.classList.add('hidden');
                }
            }

            // Sinkronkan ringkasan 1-baris pada mode delivery collapse
            const summaryPill = document.getElementById('pos-delivery-summary-pill');
            if (summaryPill) {
                const distKmStr = (state.currentDeliveryDistance && state.currentDeliveryDistance > 0) ? `${formatDecimal(state.currentDeliveryDistance)} km` : '0 km';
                const feeStr = (state.currentDeliveryFee === 0) ? 'GRATIS' : formatRupiah(state.currentDeliveryFee);
                summaryPill.innerText = `${distKmStr} • ${feeStr}`;
            }

            calculateCartTotals();
        }

        function calculateCartTotals(skipDiscountEval) {
            if (!skipDiscountEval && typeof evaluatePosAutoDiscounts === 'function') {
                evaluatePosAutoDiscounts(true);
            }

            const subtotal = (state.cart || []).reduce(function(acc, c) { return acc + (c.price * c.qty); }, 0);
            const discountInput = parseFloat(document.getElementById('input-discount') ? document.getElementById('input-discount').value : 0) || 0;
            const discount = Math.min(subtotal, Math.max(0, discountInput));

            // Sinkronkan tampilan nominal diskon di keranjang POS kasir
            const discDisplayEl = document.getElementById('pos-discount-display');
            if (discDisplayEl) {
                if (discount > 0) {
                    discDisplayEl.innerText = '- ' + formatRupiah(discount);
                    discDisplayEl.className = 'font-bold font-mono text-xs text-rose-600 dark:text-rose-400';
                } else {
                    discDisplayEl.innerText = 'Rp 0';
                    discDisplayEl.className = 'font-bold font-mono text-xs text-slate-400 dark:text-slate-500';
                }
            }
            
            // Hitung Pajak per Item Produk
            let totalTax = 0;
            let hasTaxableItem = false;

            (state.cart || []).forEach(item => {
                const isTaxable = (item.is_taxable !== undefined) ? Number(item.is_taxable) : 1;
                const taxRate = (item.tax_percent !== undefined) ? Number(item.tax_percent) : 11.0;
                if (isTaxable === 1 && taxRate > 0) {
                    hasTaxableItem = true;
                    const itemShare = subtotal > 0 ? ((item.price * item.qty) / subtotal) : 0;
                    const itemDiscount = discount * itemShare;
                    const itemTaxableVal = Math.max(0, (item.price * item.qty) - itemDiscount);
                    totalTax += Math.round((itemTaxableVal * taxRate) / 100);
                }
            });

            const tax = totalTax;
            const isDelivery = _chk('check-delivery-mode') || false;
            const deliveryFee = isDelivery ? (state.currentDeliveryFee || 0) : 0;
            const grandTotal = Math.max(0, subtotal - discount) + tax + deliveryFee;

            // Kontrol Tampilan Baris Pajak di POS Kasir
            const taxRowEl = document.getElementById('row-summary-tax');
            if (taxRowEl) {
                if (hasTaxableItem && tax > 0) {
                    taxRowEl.classList.remove('hidden');
                } else {
                    taxRowEl.classList.add('hidden');
                }
            }

            document.getElementById('summary-subtotal').innerText = formatRupiah(subtotal);
            document.getElementById('summary-tax').innerText = formatRupiah(tax);
            document.getElementById('summary-grand-total').innerText = formatRupiah(grandTotal);
            calculateChange();
        }

        function renderPosPaymentButtons() {
            const container = document.getElementById('pos-payment-methods-grid');
            if (!container) return;

            const methods = (state.paymentMethods || []).filter(pm => pm.is_active == 1);
            if (methods.length === 0) {
                container.innerHTML = `<button type="button" onclick="setPaymentMethod('CASH')" id="pay-btn-CASH" class="pay-btn py-1.5 text-xs font-bold rounded-lg border text-center border-indigo-600 bg-indigo-50 dark:bg-indigo-950/70 text-indigo-700 dark:text-indigo-300 cursor-pointer">Tunai</button>`;
                return;
            }

            // Atur jumlah kolom grid sesuai banyaknya metode aktif
            const colCount = Math.min(4, Math.max(2, methods.length));
            container.className = `grid grid-cols-${colCount} gap-1.5`;

            // Cek apakah paymentMethod aktif saat ini masih ada di list
            const currentExists = methods.some(m => m.code === state.paymentMethod);
            if (!currentExists && methods.length > 0) {
                state.paymentMethod = methods[0].code;
            }

            container.innerHTML = methods.map(m => {
                const isSelected = m.code === state.paymentMethod;
                const cls = isSelected 
                    ? 'pay-btn py-1.5 text-xs font-bold rounded-lg border text-center border-indigo-600 bg-indigo-50 dark:bg-indigo-950/70 text-indigo-700 dark:text-indigo-300 shadow-sm cursor-pointer'
                    : 'pay-btn py-1.5 text-xs font-semibold rounded-lg border text-center border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer';
                return `<button type="button" onclick="setPaymentMethod('${m.code}')" id="pay-btn-${m.code}" class="${cls}" title="${m.name}">${m.name}</button>`;
            }).join('');

            setPaymentMethod(state.paymentMethod);
        }

        function renderPosCashDenominations() {
            const container = document.getElementById('pos-cash-denominations-grid');
            if (!container) return;

            let denoms = (state.cashDenominations || []).filter(cd => cd.is_active != 0);
            if (denoms.length === 0) {
                denoms = [
                    { id: 1, label: 'Uang Pas', amount: 0, action_type: 'EXACT' },
                    { id: 2, label: '10K', amount: 10000, action_type: 'SET' },
                    { id: 3, label: '20K', amount: 20000, action_type: 'SET' },
                    { id: 4, label: '50K', amount: 50000, action_type: 'SET' },
                    { id: 5, label: '100K', amount: 100000, action_type: 'SET' }
                ];
            }

            const colCount = Math.min(6, Math.max(2, denoms.length));
            container.className = `grid grid-cols-${colCount} gap-1.5 pt-0.5`;

            container.innerHTML = denoms.map((d, idx) => {
                const title = d.action_type === 'EXACT' ? 'Uang Pas sesuai total tagihan belanja' : (d.action_type === 'ADD' ? `Tambah ${formatRupiah(d.amount)} ke uang diterima` : `Set uang diterima ${formatRupiah(d.amount)}`);
                return `
                    <button type="button" 
                            onclick="applyCashDenomination(${idx})" 
                            id="cash-denom-btn-${d.id || idx}" 
                            title="${title}"
                            class="cash-denom-btn py-1.5 px-1 text-xs font-bold rounded-lg border text-center transition-all bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700 hover:border-indigo-400 dark:hover:border-indigo-500 active:scale-95 shadow-sm cursor-pointer">
                        ${d.label}
                    </button>
                `;
            }).join('');
        }

        function applyCashDenomination(idx) {
            let denoms = (state.cashDenominations || []).filter(cd => cd.is_active != 0);
            if (denoms.length === 0) {
                denoms = [
                    { id: 1, label: 'Uang Pas', amount: 0, action_type: 'EXACT' },
                    { id: 2, label: '10K', amount: 10000, action_type: 'SET' },
                    { id: 3, label: '20K', amount: 20000, action_type: 'SET' },
                    { id: 4, label: '50K', amount: 50000, action_type: 'SET' },
                    { id: 5, label: '100K', amount: 100000, action_type: 'SET' }
                ];
            }

            const d = denoms[idx];
            if (!d) return;

            const inputEl = document.getElementById('input-cash-received');
            if (d.action_type === 'EXACT') {
                setExactCash();
            } else if (d.action_type === 'ADD') {
                const currentVal = parseFloat(inputEl.value) || 0;
                inputEl.value = Math.round(currentVal + Number(d.amount));
                calculateChange();
            } else {
                // SET
                inputEl.value = Math.round(Number(d.amount));
                calculateChange();
            }

            // Visual feedback - temporary active highlight
            const btn = document.getElementById(`cash-denom-btn-${d.id || idx}`);
            if (btn) {
                btn.classList.add('border-indigo-600', 'bg-indigo-50', 'text-indigo-700');
                setTimeout(() => {
                    btn.classList.remove('border-indigo-600', 'bg-indigo-50', 'text-indigo-700');
                }, 200);
            }
        }

        function renderReportPaymentFilterOptions() {
            const select = document.getElementById('report-payment-filter');
            if (!select) return;

            const methods = state.paymentMethods || [];
            let html = `<option value="ALL">Semua Metode</option>`;
            methods.forEach(m => {
                html += `<option value="${m.code}">${m.name}</option>`;
            });
            select.innerHTML = html;
        }

        function openPaymentModal() {
            // Validasi Cross-Day Shift (Konfirmasi Pergantian Hari & End Day Shift Kemarin)
            if (checkCrossDayShiftBeforeAction(function() { openPaymentModal(); })) {
                return;
            }

            // Validasi: Wajib pilih pelanggan terlebih dahulu
            if (!state.selectedCustomer) {
                alert('Silakan pilih pelanggan terlebih dahulu sebelum melanjutkan pembayaran!');
                openSelectCustomerModal();
                return;
            }

            if (!state.cart || state.cart.length === 0) {
                alert('Keranjang belanja masih kosong! Silakan pilih produk di katalog terlebih dahulu.');
                return;
            }

            // Validasi Opening Shift
            if (!state.activeShift || state.activeShift.status !== 'OPEN') {
                alert('PERINGATAN OPENING SHIFT:\nTransaksi penjualan tidak dapat dilakukan karena shift kasir (Opening Sales) belum dibuka!\n\nSilakan isi formulir Opening Shift (uang modal pangkal & verifikasi stok awal) untuk membuka penjualan.');
                openShiftModal();
                return;
            }

            // Hitung ulang kalkulasi total
            calculateCartTotals();

            // 1. Isi Metadata Pelanggan & Cabang
            const cust = state.selectedCustomer;
            const custNameEl = document.getElementById('pos-modal-customer-name');
            if (custNameEl) custNameEl.innerText = cust ? cust.name : 'Pelanggan Umum (Walk-in)';

            const custCatEl = document.getElementById('pos-modal-customer-cat');
            if (custCatEl) custCatEl.innerText = state.selectedCustomerCategory || (cust ? cust.category : 'REGULER');

            const branchEl = document.getElementById('pos-modal-branch-name');
            if (branchEl) branchEl.innerText = state.currentBranch ? state.currentBranch.name : 'Cabang Utama';

            const totalQty = state.cart.reduce((sum, item) => sum + item.qty, 0);
            const countEl = document.getElementById('pos-modal-summary-items-count');
            if (countEl) countEl.innerText = `${state.cart.length} Produk (${totalQty} Pcs)`;

            // 2. Tampilkan Rincian Item Keranjang
            const itemsContainer = document.getElementById('pos-modal-items-list');
            if (itemsContainer) {
                itemsContainer.innerHTML = state.cart.map(item => `
                    <div class="py-1.5 flex justify-between items-center text-xs">
                        <div class="flex-1 pr-2">
                            <span class="font-bold text-slate-800 dark:text-slate-100 line-clamp-1">${item.name}</span>
                            <div class="flex items-center space-x-1.5 text-[10px] text-slate-500 dark:text-slate-400">
                                ${item.variant_name ? `<span class="text-purple-700 dark:text-purple-400 font-bold">[${item.variant_name}]</span>` : ''}
                                <span>${item.qty} x ${formatRupiah(item.price)}</span>
                            </div>
                        </div>
                        <span class="font-mono font-bold text-slate-800 dark:text-slate-200">${formatRupiah(item.price * item.qty)}</span>
                    </div>
                `).join('');
            }

            // 3. Tampilkan Subtotal, Diskon, Ongkir, Pajak, Grand Total
            const subtotal = state.cart.reduce((acc, c) => acc + (c.price * c.qty), 0);
            const discountInput = parseFloat(_val('input-discount')) || 0;
            const discount = Math.min(subtotal, Math.max(0, discountInput));

            let totalTax = 0;
            let hasTaxableItem = false;
            state.cart.forEach(item => {
                const isTaxable = (item.is_taxable !== undefined) ? Number(item.is_taxable) : 1;
                const taxRate = (item.tax_percent !== undefined) ? Number(item.tax_percent) : 11.0;
                if (isTaxable === 1 && taxRate > 0) {
                    hasTaxableItem = true;
                    const itemShare = subtotal > 0 ? ((item.price * item.qty) / subtotal) : 0;
                    const itemDiscount = discount * itemShare;
                    const itemTaxableVal = Math.max(0, (item.price * item.qty) - itemDiscount);
                    totalTax += Math.round((itemTaxableVal * taxRate) / 100);
                }
            });

            const isDelivery = _chk('check-delivery-mode') || false;
            const deliveryFee = isDelivery ? (state.currentDeliveryFee || 0) : 0;
            const grandTotal = Math.max(0, subtotal - discount) + totalTax + deliveryFee;

            if (document.getElementById('pos-modal-subtotal')) {
                document.getElementById('pos-modal-subtotal').innerText = formatRupiah(subtotal);
            }
            if (document.getElementById('pos-modal-discount')) {
                const discLbl = document.getElementById('pos-modal-discount-label');
                const promoLbl = (state.appliedDiscount && state.appliedDiscount.name) ? ` (${state.appliedDiscount.name})` : '';
                if (discLbl) discLbl.innerText = `Diskon Faktur${promoLbl}:`;
                document.getElementById('pos-modal-discount').innerText = discount > 0 ? `- ${formatRupiah(discount)}` : 'Rp 0';
            }

            const delivRow = document.getElementById('pos-modal-delivery-row');
            if (delivRow) {
                if (isDelivery) {
                    delivRow.classList.remove('hidden');
                    const distText = (state.currentDeliveryDistance && state.currentDeliveryDistance > 0) ? `(${formatDecimal(state.currentDeliveryDistance)} km)` : '';
                    const labelEl = document.getElementById('pos-modal-delivery-label');
                    if (labelEl) labelEl.innerText = `🛵 Antar Kurir ${distText}:`;
                    const feeEl = document.getElementById('pos-modal-delivery-fee');
                    if (feeEl) feeEl.innerText = deliveryFee === 0 ? 'GRATIS' : formatRupiah(deliveryFee);
                } else {
                    delivRow.classList.add('hidden');
                }
            }

            const taxRow = document.getElementById('pos-modal-tax-row');
            if (taxRow) {
                if (hasTaxableItem && totalTax > 0) {
                    taxRow.classList.remove('hidden');
                    const taxEl = document.getElementById('pos-modal-tax');
                    if (taxEl) taxEl.innerText = formatRupiah(totalTax);
                } else {
                    taxRow.classList.add('hidden');
                }
            }

            if (document.getElementById('pos-modal-grand-total')) {
                document.getElementById('pos-modal-grand-total').innerText = formatRupiah(grandTotal);
            }

            // 4. Render Tombol Metode Pembayaran & Denominasi
            renderPosPaymentButtons();
            renderPosCashDenominations();

            const cashInput = document.getElementById('input-cash-received');
            if (cashInput && (!cashInput.value || parseFloat(cashInput.value) <= 0)) {
                cashInput.value = '';
            }
            calculateChange();

            // 5. Buka Popup Modal & Fokus Input
            const modal = document.getElementById('pos-payment-modal');
            if (modal) {
                modal.classList.remove('hidden');
                lucide.createIcons();
                setTimeout(() => {
                    const targetPm = (state.paymentMethods || []).find(m => m.code === state.paymentMethod);
                    const isCash = targetPm ? (Number(targetPm.is_cash) === 1) : (state.paymentMethod === 'CASH');
                    if (isCash && cashInput) {
                        cashInput.focus();
                        cashInput.select();
                    }
                }, 100);
            }
        }

        function closePaymentModal() {
            const modal = document.getElementById('pos-payment-modal');
            if (modal) modal.classList.add('hidden');
        }

        function setPaymentMethod(method) {
            state.paymentMethod = method;
            document.querySelectorAll('.pay-btn').forEach(btn => {
                if (btn.id === `pay-btn-${method}`) {
                    btn.className = 'pay-btn py-1.5 sm:py-2 text-xs font-bold rounded-xl border text-center border-indigo-600 bg-indigo-50 dark:bg-indigo-950/70 text-indigo-700 dark:text-indigo-300 shadow-2xs cursor-pointer';
                } else {
                    btn.className = 'pay-btn py-1.5 sm:py-2 text-xs font-semibold rounded-xl border text-center border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer';
                }
            });

            const cashSection = document.getElementById('cash-payment-section');
            const nonCashSection = document.getElementById('non-cash-payment-info');
            const targetPm = (state.paymentMethods || []).find(m => m.code === method);
            const isCash = targetPm ? (Number(targetPm.is_cash) === 1) : (method === 'CASH');

            if (cashSection) {
                if (isCash) cashSection.classList.remove('hidden');
                else cashSection.classList.add('hidden');
            }

            if (nonCashSection) {
                if (!isCash) {
                    nonCashSection.classList.remove('hidden');
                    const titleEl = document.getElementById('non-cash-info-title');
                    const descEl = document.getElementById('non-cash-info-desc');
                    if (method === 'PIUTANG') {
                        if (titleEl) titleEl.innerText = 'Pencatatan Piutang Pelanggan';
                        if (descEl) descEl.innerText = 'Transaksi ini akan dicatat ke dalam buku piutang pelanggan dan saldo piutang akan otomatis bertambah.';
                    } else {
                        if (titleEl) titleEl.innerText = `Pembayaran via ${targetPm ? targetPm.name : method}`;
                        if (descEl) descEl.innerText = `Pastikan dana sudah diverifikasi masuk pada EDC / QRIS / mutasi rekening sebelum menyelesaikan transaksi.`;
                    }
                } else {
                    nonCashSection.classList.add('hidden');
                }
            }

            // Adaptasi Teks & Gaya Tombol Checkout jika PIUTANG
            const btnCheckout = document.getElementById('btn-checkout');
            if (btnCheckout) {
                if (method === 'PIUTANG') {
                    btnCheckout.innerHTML = `<i data-lucide="book-open-check" class="w-5 h-5"></i><span>Catat Piutang & Selesaikan (Enter)</span>`;
                    btnCheckout.className = 'flex-1 py-3 bg-amber-600 hover:bg-amber-700 text-white font-black rounded-xl shadow-md transition-all flex items-center justify-center space-x-2 text-xs sm:text-sm active:scale-[0.99] cursor-pointer';
                } else {
                    btnCheckout.innerHTML = `<i data-lucide="check-circle" class="w-5 h-5"></i><span>Selesaikan Pembayaran (Enter)</span>`;
                    btnCheckout.className = 'flex-1 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-xl shadow-md transition-all flex items-center justify-center space-x-2 text-xs sm:text-sm active:scale-[0.99] cursor-pointer';
                }
                lucide.createIcons();
            }
            if (typeof evaluatePosAutoDiscounts === 'function') {
                evaluatePosAutoDiscounts();
            }
        }

        function calculateChange() {
            if (state.paymentMethod !== 'CASH') return;
            const subtotal = state.cart.reduce((acc, c) => acc + (c.price * c.qty), 0);
            const discount = parseFloat(document.getElementById('input-discount').value) || 0;
            const isDelivery = _chk('check-delivery-mode') || false;
            const deliveryFee = isDelivery ? (state.currentDeliveryFee || 0) : 0;
            
            let totalTax = 0;
            state.cart.forEach(item => {
                const isTaxable = (item.is_taxable !== undefined) ? Number(item.is_taxable) : 1;
                const taxRate = (item.tax_percent !== undefined) ? Number(item.tax_percent) : 11.0;
                if (isTaxable === 1 && taxRate > 0) {
                    const itemShare = subtotal > 0 ? ((item.price * item.qty) / subtotal) : 0;
                    const itemDiscount = discount * itemShare;
                    const itemTaxableVal = Math.max(0, (item.price * item.qty) - itemDiscount);
                    totalTax += Math.round((itemTaxableVal * taxRate) / 100);
                }
            });

            const grandTotal = Math.max(0, subtotal - discount) + totalTax + deliveryFee;
            const received = parseFloat(document.getElementById('input-cash-received').value) || 0;
            state.cashReceived = received;
            const change = Math.max(0, received - Math.round(grandTotal));
            document.getElementById('summary-cash-change').innerText = formatRupiah(change);
        }

        function setExactCash() {
            const subtotal = state.cart.reduce((acc, c) => acc + (c.price * c.qty), 0);
            const discount = parseFloat(document.getElementById('input-discount').value) || 0;
            const isDelivery = _chk('check-delivery-mode') || false;
            const deliveryFee = isDelivery ? (state.currentDeliveryFee || 0) : 0;

            let totalTax = 0;
            state.cart.forEach(item => {
                const isTaxable = (item.is_taxable !== undefined) ? Number(item.is_taxable) : 1;
                const taxRate = (item.tax_percent !== undefined) ? Number(item.tax_percent) : 11.0;
                if (isTaxable === 1 && taxRate > 0) {
                    const itemShare = subtotal > 0 ? ((item.price * item.qty) / subtotal) : 0;
                    const itemDiscount = discount * itemShare;
                    const itemTaxableVal = Math.max(0, (item.price * item.qty) - itemDiscount);
                    totalTax += Math.round((itemTaxableVal * taxRate) / 100);
                }
            });

            const grandTotal = Math.max(0, subtotal - discount) + totalTax + deliveryFee;
            document.getElementById('input-cash-received').value = Math.round(grandTotal);
            calculateChange();
        }

        function addCash(amount) {
            const cur = parseFloat(document.getElementById('input-cash-received').value) || 0;
            document.getElementById('input-cash-received').value = cur + amount;
            calculateChange();
        }

        async function processCheckout() {
            // Validasi Cross-Day Shift (Konfirmasi Pergantian Hari & End Day Shift Kemarin)
            if (checkCrossDayShiftBeforeAction(function() { processCheckout(); })) {
                return;
            }

            if (state.cart.length === 0) {
                alert('Keranjang belanja masih kosong!');
                return;
            }

            // ATURAN BISNIS MUTLAK: Jika tidak buka opening sales / shift kasir maka transaksi penjualan tidak bisa dilakukan!
            if (!state.activeShift || state.activeShift.status !== 'OPEN') {
                alert('PERINGATAN OPENING SHIFT:\nTransaksi penjualan tidak dapat dilakukan karena shift kasir (Opening Sales) belum dibuka!\n\nSilakan isi formulir Opening Shift (uang modal pangkal & verifikasi stok awal) untuk membuka penjualan.');
                openShiftModal();
                return;
            }

            const subtotal = state.cart.reduce((acc, c) => acc + (c.price * c.qty), 0);
            const discount = parseFloat(document.getElementById('input-discount').value) || 0;
            const isDelivery = _chk('check-delivery-mode') || false;
            const deliveryFee = isDelivery ? (state.currentDeliveryFee || 0) : 0;
            const deliveryDistance = isDelivery ? (state.currentDeliveryDistance || 0) : 0;
            const courierVehicleId = isDelivery ? (parseInt(_val('pos-courier-select')) || state.currentPosVehicleId || null) : null;
            const driverSelect = document.getElementById('pos-driver-employee-select');
            const driverUserId = isDelivery ? (parseInt((driverSelect ? driverSelect.value : '')) || state.currentPosDriverUserId || null) : null;
            let driverName = null;
            if (isDelivery) {
                if (driverSelect && driverSelect.selectedIndex >= 0 && driverSelect.options[driverSelect.selectedIndex]) {
                    driverName = driverSelect.options[driverSelect.selectedIndex].text.replace(/^[🔒\s]+/, '').replace(/\s*\([^)]*\)\s*$/, '').trim();
                }
                if (!driverName && state.currentPosDriverName) {
                    driverName = state.currentPosDriverName;
                }
            }
            const isFreeItem = (c) => Number(c.is_delivery_included) === 1 || Number(c.is_delivery_required) === 2;
            const freeDeliveryItems = (state.cart || []).filter(isFreeItem);
            const chargeableItems = (state.cart || []).filter(c => !isFreeItem(c));
            const isEntirelyFreeDelivery = isDelivery && (freeDeliveryItems.length > 0 && chargeableItems.length === 0);
            
            // Hitung grand total berdasarkan per-item tax
            let currentTaxTotal = 0;
            state.cart.forEach(item => {
                const isTaxable = (item.is_taxable !== undefined) ? Number(item.is_taxable) : 1;
                const taxRate = (item.tax_percent !== undefined) ? Number(item.tax_percent) : 11.0;
                if (isTaxable === 1 && taxRate > 0) {
                    const itemShare = subtotal > 0 ? ((item.price * item.qty) / subtotal) : 0;
                    const itemDiscount = discount * itemShare;
                    const itemTaxableVal = Math.max(0, (item.price * item.qty) - itemDiscount);
                    currentTaxTotal += Math.round((itemTaxableVal * taxRate) / 100);
                }
            });

            const grandTotal = Math.max(0, subtotal - discount) + currentTaxTotal + deliveryFee;

            if (state.paymentMethod === 'CASH' && state.cashReceived < grandTotal) {
                alert('Uang tunai kurang dari total belanja (termasuk ongkir).');
                return;
            }

            const custId = state.selectedCustomer ? state.selectedCustomer.id : 1;
            const custName = state.selectedCustomer ? state.selectedCustomer.name : 'Pelanggan Umum';
            const custCategory = state.selectedCustomerCategory || 'REGULER';
            const salesType = (custCategory === 'MITRA') ? 'B2B_PARTNER' : (custCategory || 'RETAIL');

            if (state.paymentMethod === 'PIUTANG' && custId === 1) {
                if (!confirm("Perhatian: Transaksi piutang akan dicatat atas nama 'Pelanggan Umum (Walk-in)'. Disarankan memilih data Pelanggan / Reseller / Mitra agar riwayat buku piutang tercatat rapi. Tetap lanjutkan pencatatan piutang?")) {
                    return;
                }
            }

            const payload = {
                branch_id: state.currentBranch.id,
                user_id: state.currentUser.id,
                shift_id: state.activeShift ? state.activeShift.id : null,
                customer_id: custId,
                customer_name: custName,
                customer_category: custCategory,
                sales_type: salesType,
                items: state.cart.map(c => ({
                    product_id: c.product_id,
                    variant_id: c.variant_id || null,
                    variant_name: c.variant_name || null,
                    qty: c.qty
                })),
                payment_method: state.paymentMethod,
                cash_received: (state.paymentMethod === 'PIUTANG') ? 0 : state.cashReceived,
                discount: discount,
                discount_rule_id: (state.appliedDiscount && state.appliedDiscount.id) ? state.appliedDiscount.id : null,
                discount_name: (state.appliedDiscount && state.appliedDiscount.name) ? state.appliedDiscount.name : (discount > 0 ? 'Diskon Manual Kasir' : null),
                delivery_fee: deliveryFee,
                delivery_distance_km: deliveryDistance,
                courier_vehicle_id: courierVehicleId,
                driver_user_id: driverUserId,
                driver_name: driverName,
                is_delivery_included: isEntirelyFreeDelivery ? 1 : 0,
                delivery_status: isDelivery ? 'ASSIGNED' : 'NONE'
            };

            const btn = document.getElementById('btn-checkout');
            btn.disabled = true;
            btn.innerHTML = `Memproses Transaksi & Pembukuan...`;

            try {
                if (state.isOfflineMode || !navigator.onLine) {
                    throw new Error('OFFLINE_MODE');
                }

                const res = await fetch('api.php?action=checkout_sale', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                btn.disabled = false;
                setPaymentMethod(state.paymentMethod);

                if (data.success) {
                    closePaymentModal();
                    showReceiptModal(data.sale);
                    clearCart();
                    document.getElementById('input-cash-received').value = '';
                    // Reset delivery checkbox
                    const chk = document.getElementById('check-delivery-mode');
                    if (chk) { chk.checked = false; onDeliveryToggleChange(); }
                    initApp();
                } else {
                    alert('Gagal Checkout: ' + (data.message || data.error));
                }
            } catch (err) {
                // OFFLINE CHECKOUT INTERCEPT
                console.warn('Checkout offline fallback activated:', err);
                btn.disabled = false;
                setPaymentMethod(state.paymentMethod);

                const nowTs = Date.now();
                const offlineRef = 'INV-OFF-' + ((state.currentBranch ? state.currentBranch.id : 1) || 1) + '-' + ((state.currentUser ? state.currentUser.id : 1) || 1) + '-' + nowTs.toString(36).toUpperCase();

                const offlineSale = {
                    id: offlineRef,
                    offline_ref: offlineRef,
                    invoice_number: offlineRef,
                    branch_id: (state.currentBranch ? state.currentBranch.id : 1) || 1,
                    user_id: (state.currentUser ? state.currentUser.id : 1) || 1,
                    shift_id: state.activeShift ? state.activeShift.id : null,
                    customer_id: custId,
                    customer_name: custName,
                    customer_phone: (state.selectedCustomer ? state.selectedCustomer.phone : null) || '-',
                    customer_category: custCategory,
                    sales_type: salesType,
                    subtotal: subtotal,
                    discount: discount,
                    tax: currentTaxTotal,
                    delivery_fee: deliveryFee,
                    delivery_distance_km: deliveryDistance,
                    courier_vehicle_id: courierVehicleId,
                    driver_user_id: driverUserId,
                    driver_name: driverName,
                    is_delivery_included: isEntirelyFreeDelivery ? 1 : 0,
                    delivery_status: isDelivery ? 'ASSIGNED' : 'NONE',
                    grand_total: grandTotal,
                    payment_method: state.paymentMethod,
                    payment_status: (state.paymentMethod === 'PIUTANG') ? 'UNPAID' : 'PAID',
                    cash_received: (state.paymentMethod === 'PIUTANG') ? 0 : state.cashReceived,
                    cash_change: (state.paymentMethod === 'CASH') ? Math.max(0, state.cashReceived - grandTotal) : 0,
                    created_at: getDeviceLocalDateTimeString(),
                    is_offline: 1,
                    synced: 0,
                    items: state.cart.map(c => ({
                        product_id: c.product_id,
                        product_name: c.name || c.product_name,
                        variant_id: c.variant_id || null,
                        variant_name: c.variant_name || null,
                        qty: c.qty,
                        price: c.price,
                        unit_price: c.price,
                        subtotal: c.price * c.qty,
                        subtotal_price: c.price * c.qty
                    }))
                };

                // 1. Kurangi stok lokal di memory state
                (state.cart || []).forEach(cartItem => {
                    const prod = (state.products || []).find(p => p.id == cartItem.product_id);
                    if (prod) {
                        prod.stock = Math.max(0, (Number(prod.stock) || 0) - Number(cartItem.qty));
                    }
                });

                // 2. Simpan transaksi ke IndexedDB offline_sales
                await OfflineDB.setItem('offline_sales', offlineSale);

                // 3. Tampilkan struk nota & bersihkan keranjang
                closePaymentModal();
                showReceiptModal(offlineSale);
                clearCart();
                document.getElementById('input-cash-received').value = '';
                const chk = document.getElementById('check-delivery-mode');
                if (chk) { chk.checked = false; onDeliveryToggleChange(); }
                renderProducts();

                // 4. Update UI Status Pill
                state.isOfflineMode = true;
                await updateOfflineSyncStatusUI();

                // 5. Coba sinkronkan di latar belakang jika koneksi pulih
                if (navigator.onLine) {
                    triggerAutoSync();
                }
            }
        }

        function showReceiptModal(sale) {
            if (!sale.customer_phone && state.selectedCustomer && state.selectedCustomer.phone && state.selectedCustomer.phone !== '-') {
                sale.customer_phone = state.selectedCustomer.phone;
            }
            state.lastProcessedSale = sale;
            const s = state.appSettings || {};

            // Dynamic Header Struk
            const rLogo = document.getElementById('receipt-logo-icon');
            if (rLogo) {
                if (s.receipt_show_logo === '0') {
                    rLogo.classList.add('hidden');
                } else {
                    rLogo.classList.remove('hidden');
                    if (s.app_logo_url && s.app_logo_url.trim()) {
                        rLogo.innerHTML = `<img src="${s.app_logo_url.trim()}" class="max-h-12 max-w-28 mx-auto object-contain mb-1" alt="Logo" onerror="this.onerror=null; this.parentElement.innerText='${s.app_logo_emoji || '🛍️'}';">`;
                    } else {
                        rLogo.innerText = s.app_logo_emoji || '🛍️';
                    }
                }
            }
            if (document.getElementById('receipt-store-title')) {
                document.getElementById('receipt-store-title').innerText = s.receipt_header_title || (s.app_name || 'ESBAS RETAIL TOKO');
            }
            if (document.getElementById('receipt-store-subtitle')) {
                document.getElementById('receipt-store-subtitle').innerText = s.receipt_header_subtitle || (s.app_subtitle || 'Pusat Belanja & Grosir');
            }
            if (document.getElementById('receipt-header-custom')) {
                document.getElementById('receipt-header-custom').innerText = s.receipt_header_custom_text || '';
            }

            document.getElementById('receipt-branch-name').innerText = state.currentBranch.name;
            document.getElementById('receipt-branch-address').innerText = state.currentBranch.address || '';
            document.getElementById('receipt-invoice-no').innerText = sale.invoice_number;
            document.getElementById('receipt-time').innerText = sale.created_at;
            document.getElementById('receipt-cashier-name').innerText = state.currentUser.name;
            document.getElementById('receipt-customer-name').innerText = sale.customer_name || 'Pelanggan Umum';
            document.getElementById('receipt-sales-type').innerText = sale.customer_category || 'REGULER';
            
            const showSku = s.receipt_body_show_sku === '1';
            let itemsHtml = sale.items.map(it => `
                <div class="flex justify-between">
                    <span>${it.product_name}${showSku && it.sku ? ` <span class="text-[9px] text-slate-400 font-mono">(${it.sku})</span>` : ''} x${it.qty}</span>
                    <span>${formatRupiah(it.subtotal_price)}</span>
                </div>
            `).join('');

            const effectiveDriver = sale.driver_name || (sale.effective_driver_name ? sale.effective_driver_name : '');
            if (sale.delivery_fee && Number(sale.delivery_fee) > 0) {
                itemsHtml += `
                    <div class="flex justify-between text-amber-800 font-bold border-t border-dashed border-amber-200 pt-1 mt-1">
                        <span>🛵 Biaya Kirim Kurir (${sale.delivery_distance_km || 0} km)${effectiveDriver ? ` • ${effectiveDriver}` : ''}</span>
                        <span>${formatRupiah(sale.delivery_fee)}</span>
                    </div>
                `;
            } else if (sale.delivery_status && sale.delivery_status !== 'NONE') {
                itemsHtml += `
                    <div class="flex justify-between text-emerald-800 font-bold border-t border-dashed border-emerald-200 pt-1 mt-1">
                        <span>🛵 Layanan Antar${sale.delivery_distance_km && Number(sale.delivery_distance_km) > 0 ? ` (${sale.delivery_distance_km} km)` : ''}: Termasuk Biaya Kirim${effectiveDriver ? ` • Kurir: ${effectiveDriver}` : ''}</span>
                        <span>Rp 0</span>
                    </div>
                `;
            }

            document.getElementById('receipt-items-list').innerHTML = itemsHtml;
            document.getElementById('receipt-subtotal').innerText = formatRupiah(sale.subtotal);
            document.getElementById('receipt-discount').innerText = formatRupiah(sale.discount);
            
            // Kontrol Tampilan Pajak di Struk: Muncul hanya jika ada pajak > 0
            const receiptTaxRow = document.getElementById('receipt-tax-row');
            if (receiptTaxRow) {
                if (sale.tax && Number(sale.tax) > 0) {
                    receiptTaxRow.classList.remove('hidden');
                    document.getElementById('receipt-tax').innerText = formatRupiah(sale.tax);
                } else {
                    receiptTaxRow.classList.add('hidden');
                }
            }

            document.getElementById('receipt-grand-total').innerText = formatRupiah(sale.grand_total);
            document.getElementById('receipt-payment-method').innerText = sale.payment_method;
            document.getElementById('receipt-cash-received').innerText = formatRupiah(sale.cash_received);
            document.getElementById('receipt-cash-change').innerText = formatRupiah(sale.cash_change);

            // Dynamic Footers
            if (document.getElementById('receipt-footer-1')) {
                document.getElementById('receipt-footer-1').innerText = s.receipt_footer_line1 || 'Terima Kasih Atas Kunjungan Anda!';
            }
            if (document.getElementById('receipt-footer-2')) {
                document.getElementById('receipt-footer-2').innerText = s.receipt_footer_line2 || 'Barang yang sudah dibeli tidak dapat ditukar/dikembalikan.';
            }
            if (document.getElementById('receipt-footer-3')) {
                document.getElementById('receipt-footer-3').innerText = s.receipt_footer_line3 || 'Simpan struk ini sebagai bukti pembayaran yang sah.';
            }

            document.getElementById('receipt-modal').classList.remove('hidden');
        }

        function closeReceiptModal() {
            document.getElementById('receipt-modal').classList.add('hidden');
        }

        // =========================================================================
        // CROSS-DAY SHIFT & END DAY RESOLUTION ENGINE (FR-POS-50)
        // =========================================================================
        var _crossDayPendingCallback = null;
        window._isResolvingYesterdayShiftEndDay = false;

        function getShiftBusinessDate(shift) {
            if (!shift || !shift.start_time) return null;
            return String(shift.start_time).substring(0, 10);
        }

        function isCrossDayShiftPending() {
            if (!state.activeShift || state.activeShift.status !== 'OPEN') return false;
            var shiftDate = getShiftBusinessDate(state.activeShift);
            var todayDate = getDeviceLocalDateString();
            if (!shiftDate || !todayDate) return false;

            if (shiftDate < todayDate) {
                var shiftId = String(state.activeShift.id);
                var isConfirmed = false;
                if (state.crossDayConfirmedShiftId && String(state.crossDayConfirmedShiftId) === shiftId) {
                    isConfirmed = true;
                }
                try {
                    if (localStorage.getItem('kad_cross_day_confirmed_shift_' + shiftId) === '1') {
                        isConfirmed = true;
                    }
                } catch (e) {}

                return !isConfirmed;
            }
            return false;
        }

        function checkCrossDayShiftBeforeAction(onApprovedCallback) {
            if (isCrossDayShiftPending()) {
                _crossDayPendingCallback = onApprovedCallback || null;
                openCrossDayShiftModal();
                return true;
            }
            return false;
        }

        function openCrossDayShiftModal() {
            var modal = document.getElementById('cross-day-shift-modal');
            if (!modal) return;

            var shiftOpenedTimeEl = document.getElementById('cross-day-shift-opened-time');
            var todayDateEl = document.getElementById('cross-day-today-date');
            var shiftNameEl = document.getElementById('cross-day-shift-name');
            var cashierEl = document.getElementById('cross-day-shift-cashier');

            if (state.activeShift) {
                if (shiftOpenedTimeEl) shiftOpenedTimeEl.innerText = state.activeShift.start_time || '-';
                if (shiftNameEl) shiftNameEl.innerText = state.activeShift.shift_name || ('Shift ' + (state.activeShift.shift_number || 1));
                if (cashierEl) cashierEl.innerText = state.activeShift.opener_name || (state.currentUser ? state.currentUser.name : 'Kasir') || 'Kasir';
            }
            if (todayDateEl) todayDateEl.innerText = getDeviceLocalDateString();

            modal.classList.remove('hidden');
        }

        function closeCrossDayShiftModal() {
            var modal = document.getElementById('cross-day-shift-modal');
            if (modal) modal.classList.add('hidden');
        }

        function confirmContinueAsYesterdayBusinessDate() {
            if (state.activeShift && state.activeShift.id) {
                var shiftId = String(state.activeShift.id);
                state.crossDayConfirmedShiftId = shiftId;
                try {
                    localStorage.setItem('kad_cross_day_confirmed_shift_' + shiftId, '1');
                } catch (e) {}
            }
            closeCrossDayShiftModal();
            renderShiftBanner();
            if (typeof _crossDayPendingCallback === 'function') {
                var cb = _crossDayPendingCallback;
                _crossDayPendingCallback = null;
                cb();
            }
        }

        function confirmCloseEndDayForYesterdayShift() {
            closeCrossDayShiftModal();
            _crossDayPendingCallback = null;
            window._isResolvingYesterdayShiftEndDay = true;
            openShiftModal(true);
        }

        // Shift Handling
        function renderShiftBanner() {
            const isShiftOpen = state.activeShift && state.activeShift.status === 'OPEN';
            const indicator = document.getElementById('shift-status-indicator');
            const statusText = document.getElementById('shift-status-text');
            const detailsText = document.getElementById('shift-details-text');
            const btnLabel = document.getElementById('btn-shift-label');
            const topbarShiftBadge = document.getElementById('topbar-shift-badge');
            const topbarShiftText = document.getElementById('topbar-shift-text');
            const btnToggleShift = document.getElementById('btn-toggle-shift');
            const sideShiftDot = document.getElementById('sidebar-shift-dot');
            const sideShiftTitle = document.getElementById('sidebar-shift-status-title');
            const sideBtnShift = document.getElementById('sidebar-btn-shift');
            const sideBtnShiftLabel = document.getElementById('sidebar-btn-shift-label');

            if (isShiftOpen) {
                const shiftTitle = state.activeShift.shift_name || ('Shift ' + (state.activeShift.shift_number || 1));
                const shiftDate = getShiftBusinessDate(state.activeShift);
                const todayDate = getDeviceLocalDateString();
                const isCrossDay = shiftDate && todayDate && (shiftDate < todayDate);

                if (indicator) {
                    indicator.className = isCrossDay ? 'w-3.5 h-3.5 rounded-full bg-amber-500 animate-pulse' : 'w-3.5 h-3.5 rounded-full bg-emerald-500 animate-pulse';
                }
                if (statusText) {
                    if (isCrossDay) {
                        statusText.innerText = `SESI KEMARIN (${shiftDate}) - BELUM TUTUP END DAY ⚠️`;
                        statusText.className = 'text-sm font-bold text-amber-700';
                    } else {
                        statusText.innerText = 'TOKO BUKA (PENJUALAN AKTIF) 🏪';
                        statusText.className = 'text-sm font-bold text-emerald-700';
                    }
                }
                const openerInfo = (state.activeShift.opener_name && state.activeShift.opener_name !== (state.currentUser ? state.currentUser.name : 'Kasir')) ? ` (dibuka oleh ${state.activeShift.opener_name})` : '';
                const crossDayInfo = isCrossDay ? ` • [TANGGAL BISNIS KEMARIN: ${shiftDate}]` : '';
                if (detailsText) detailsText.innerText = `Sesi Toko Buka${openerInfo} • Kasir Bertugas: ${(state.currentUser ? state.currentUser.name : 'Kasir') || 'Kasir'} • Mulai: ${state.activeShift.start_time}${crossDayInfo}`;
                if (btnLabel) btnLabel.innerText = isCrossDay ? `Tutup End Day Kemarin 🌙` : `Tutup Toko (End Day) 🌙`;

                if (btnToggleShift) {
                    btnToggleShift.className = 'cursor-pointer hidden md:flex items-center space-x-1.5 bg-rose-50 hover:bg-rose-100 dark:bg-rose-950/60 dark:hover:bg-rose-900/50 border border-rose-200 dark:border-rose-800/80 px-2.5 py-1.5 rounded-xl text-rose-700 dark:text-rose-300 font-bold text-xs transition-colors shrink-0 shadow-2xs';
                    btnToggleShift.title = isCrossDay ? `Tutup End Day Kemarin (${shiftTitle})` : 'Tutup Toko (End Day Closing)';
                }

                if (topbarShiftBadge) {
                    if (isCrossDay) {
                        topbarShiftBadge.className = 'cursor-pointer hidden md:flex items-center space-x-1.5 bg-amber-50 dark:bg-amber-950/60 border border-amber-300 dark:border-amber-800/80 px-2.5 py-1.5 rounded-xl hover:bg-amber-100 dark:hover:bg-amber-900/50 transition-colors shrink-0 max-w-[170px] sm:max-w-none';
                    } else {
                        topbarShiftBadge.className = 'cursor-pointer hidden md:flex items-center space-x-1.5 bg-emerald-50 dark:bg-emerald-950/60 border border-emerald-200 dark:border-emerald-800/80 px-2.5 py-1.5 rounded-xl hover:bg-emerald-100 dark:hover:bg-emerald-900/50 transition-colors shrink-0 max-w-[150px] sm:max-w-none';
                    }
                }
                if (topbarShiftText) {
                    if (isCrossDay) {
                        topbarShiftText.innerText = `Kemarin (${shiftDate}): ${(state.currentUser ? state.currentUser.name : 'Kasir') || 'Kasir'}`;
                        topbarShiftText.className = 'text-xs font-bold text-amber-800 dark:text-amber-300 truncate whitespace-nowrap';
                    } else {
                        topbarShiftText.innerText = `Toko Buka: ${(state.currentUser ? state.currentUser.name : 'Kasir') || 'Kasir'}`;
                        topbarShiftText.className = 'text-xs font-bold text-emerald-800 dark:text-emerald-300 truncate whitespace-nowrap';
                    }
                }

                // Update Sidebar Operational Card
                if (sideShiftDot) sideShiftDot.className = isCrossDay ? 'w-2.5 h-2.5 rounded-full bg-amber-400 animate-pulse shrink-0' : 'w-2.5 h-2.5 rounded-full bg-emerald-400 animate-pulse shrink-0';
                if (sideShiftTitle) sideShiftTitle.innerText = isCrossDay ? 'Sesi Kemarin (Belum End Day ⚠️)' : 'Toko Buka (Aktif)';
                if (sideBtnShift) {
                    sideBtnShift.className = 'w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg font-bold text-xs bg-rose-600 hover:bg-rose-700 text-white shadow-sm transition-all cursor-pointer';
                    sideBtnShift.title = isCrossDay ? `Tutup End Day Kemarin (${shiftTitle})` : 'Tutup Toko (End Day Closing)';
                }
                if (sideBtnShiftLabel) sideBtnShiftLabel.innerText = isCrossDay ? `Tutup End Day Kemarin 🌙` : `Tutup Toko (End Day) 🌙`;
            } else {
                if (state.branchClosedToday) {
                    const closerName = escapeHtml((state.finalClosedShift ? state.finalClosedShift.closer_name : '') || (state.finalClosedShift ? state.finalClosedShift.cashier_name : '') || 'Kasir');
                    const closeTime = escapeHtml((state.finalClosedShift ? state.finalClosedShift.end_time : '') || '');
                    if (indicator) indicator.className = 'w-3.5 h-3.5 rounded-full bg-slate-500';
                    if (statusText) {
                        statusText.innerText = 'TOKO TUTUP (CLOSING HARIAN SELESAI) 🌙';
                        statusText.className = 'text-sm font-bold text-slate-700';
                    }
                    if (detailsText) detailsText.innerText = `Operasional hari ini telah ditutup oleh ${closerName}${closeTime ? ' (' + closeTime + ')' : ''}. Buka shift kembali esok hari sebagai Shift 1 (Pagi).`;
                    if (btnLabel) btnLabel.innerText = 'Toko Tutup 🌙';

                    if (btnToggleShift) {
                        btnToggleShift.className = 'cursor-pointer hidden md:flex items-center space-x-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 border border-slate-300 dark:border-slate-700 px-2.5 py-1.5 rounded-xl text-slate-700 dark:text-slate-300 font-bold text-xs transition-colors shrink-0 shadow-2xs';
                        btnToggleShift.title = 'Toko Tutup (Closing Harian Selesai)';
                    }

                    if (topbarShiftBadge) {
                        topbarShiftBadge.className = 'cursor-pointer hidden md:flex items-center space-x-1.5 bg-slate-100 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 px-2.5 py-1.5 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors shrink-0 max-w-[150px] sm:max-w-none';
                    }
                    if (topbarShiftText) {
                        topbarShiftText.innerText = 'Toko Tutup 🌙';
                        topbarShiftText.className = 'text-xs font-bold text-slate-700 dark:text-slate-300 truncate whitespace-nowrap';
                    }

                    // Update Sidebar Operational Card
                    if (sideShiftDot) sideShiftDot.className = 'w-2.5 h-2.5 rounded-full bg-slate-500 shrink-0';
                    if (sideShiftTitle) sideShiftTitle.innerText = 'Toko Tutup 🌙';
                    if (sideBtnShift) {
                        sideBtnShift.className = 'w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg font-bold text-xs bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700 transition-all cursor-pointer';
                        sideBtnShift.title = 'Toko Tutup (Closing Harian Selesai)';
                    }
                    if (sideBtnShiftLabel) sideBtnShiftLabel.innerText = 'Toko Tutup 🌙';
                } else {
                    if (indicator) indicator.className = 'w-3.5 h-3.5 rounded-full bg-rose-500';
                    if (statusText) {
                        statusText.innerText = 'TOKO / SHIFT BELUM DIBUKA';
                        statusText.className = 'text-sm font-bold text-rose-700';
                    }
                    if (detailsText) detailsText.innerText = 'Buka sesi toko harian (Opening Shift) untuk mencatat modal kas & verifikasi stok awal.';
                    if (btnLabel) btnLabel.innerText = 'Buka Toko (Opening)';

                    if (btnToggleShift) {
                        btnToggleShift.className = 'cursor-pointer hidden md:flex items-center space-x-1.5 bg-emerald-600 hover:bg-emerald-700 text-white border border-emerald-600 px-2.5 py-1.5 rounded-xl font-bold text-xs transition-colors shrink-0 shadow-xs';
                        btnToggleShift.title = 'Buka Toko / Opening Harian';
                    }

                    if (topbarShiftBadge) {
                        topbarShiftBadge.className = 'cursor-pointer hidden md:flex items-center space-x-1.5 bg-rose-50 dark:bg-rose-950/60 border border-rose-200 dark:border-rose-800/80 px-2.5 py-1.5 rounded-xl hover:bg-rose-100 dark:hover:bg-rose-900/50 transition-colors shrink-0 max-w-[150px] sm:max-w-none';
                    }
                    if (topbarShiftText) {
                        topbarShiftText.innerText = 'Toko Belum Buka';
                        topbarShiftText.className = 'text-xs font-bold text-rose-800 dark:text-rose-300 truncate whitespace-nowrap';
                    }

                    // Update Sidebar Operational Card
                    if (sideShiftDot) sideShiftDot.className = 'w-2.5 h-2.5 rounded-full bg-rose-500 shrink-0';
                    if (sideShiftTitle) sideShiftTitle.innerText = 'Toko Belum Buka';
                    if (sideBtnShift) {
                        sideBtnShift.className = 'w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg font-bold text-xs bg-emerald-600 hover:bg-emerald-700 text-white shadow-sm transition-all cursor-pointer';
                        sideBtnShift.title = 'Buka Toko / Opening Harian';
                    }
                    if (sideBtnShiftLabel) sideBtnShiftLabel.innerText = 'Buka Toko (Opening)';
                }
            }
            if (window.lucide && typeof lucide.createIcons === 'function') {
                lucide.createIcons();
            }
        }

        async function openShiftModal(forceOverride = false) {
            const isShiftOpen = state.activeShift && state.activeShift.status === 'OPEN';
            const title = document.getElementById('shift-modal-title');
            const desc = document.getElementById('shift-modal-desc');
            const body = document.getElementById('shift-modal-body');
            const btn = document.getElementById('shift-modal-action-btn');
            const branchId = state.currentBranch ? state.currentBranch.id : 1;

            if (forceOverride) {
                window._forceShiftOverride = true;
            }

            if (isShiftOpen) {
                // ==========================================
                // CLOSING SHIFT (TUTUP TOKO / END DAY CLOSING HARIAN)
                // ==========================================
                const isFinalCandidate = true; // Penutupan operasional selalu Tutup Toko (End Day Closing)

                title.innerHTML = `
                    <div class="flex items-center space-x-2 flex-wrap">
                        <span>Tutup Toko (End Day Closing)</span>
                        <span id="closing-shift-mode-badge" class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-rose-100 text-rose-800 uppercase tracking-wider">
                            ${window._isResolvingYesterdayShiftEndDay ? 'End Day Kemarin 🌙' : 'End Day / Closing Malam 🌙'}
                        </span>
                    </div>
                `;
                desc.innerText = `Cabang: ${(state.currentBranch ? state.currentBranch.name : 'Cabang') || 'Cabang'} • Kasir: ${(state.currentUser ? state.currentUser.name : 'Kasir') || 'Kasir'} • Mulai Buka: ${state.activeShift.start_time || '-'}${window._isResolvingYesterdayShiftEndDay ? ' • (RESOLUSI END DAY KEMARIN)' : ''}`;
                btn.innerText = 'TUTUP TOKO (END DAY CLOSING) & SIMPAN REKAP MALAM';
                btn.className = 'py-3.5 px-5 bg-rose-600 hover:bg-rose-700 rounded-2xl text-xs font-black text-white shadow-lg shadow-rose-200 transition-all uppercase tracking-wider cursor-pointer';

                body.innerHTML = `
                    <div class="flex items-center justify-center py-12 text-slate-400">
                        <div class="w-7 h-7 border-3 border-rose-600 border-t-transparent rounded-full animate-spin mr-3"></div>
                        <span class="text-xs font-bold">Memuat data rekonsiliasi kas & laporan closing malam...</span>
                    </div>
                `;
                document.getElementById('shift-modal').classList.remove('hidden');

                let closingData = null;
                try {
                    const res = await fetch(`api.php?action=get_closing_shift_data&shift_id=${state.activeShift.id}&branch_id=${branchId}`);
                    closingData = await res.json();
                } catch (e) {
                    console.error("Gagal load closing shift data:", e);
                }

                try {
                    const initCash = (closingData && closingData.initial_cash !== undefined && closingData.initial_cash !== null ? closingData.initial_cash : (parseFloat(state.activeShift.initial_cash) || 0));
                    const cashSales = (closingData && closingData.cash_sales !== undefined ? closingData.cash_sales : 0);
                    const expectedCash = (closingData && closingData.expected_cash !== undefined && closingData.expected_cash !== null ? closingData.expected_cash : (initCash + cashSales));
                    const txCount = (closingData && closingData.total_transactions !== undefined ? closingData.total_transactions : 0);
                    let items = (closingData && Array.isArray(closingData.items) && closingData.items.length > 0) ? closingData.items : [];

                    // Fail-safe jika response backend kosong: gunakan state.products yang distok (is_stockable = 1) di cabang ini
                    if (items.length === 0 && Array.isArray(state.products) && state.products.length > 0) {
                        items = state.products.filter(p => {
                            const isStockable = p.is_stockable === undefined || p.is_stockable === null || p.is_stockable == 1;
                            const isBranchActive = p.branch_is_active === undefined || p.branch_is_active === null || p.branch_is_active == 1;
                            return isStockable && p.is_active != 0 && isBranchActive;
                        }).map(p => ({
                            product_id: p.id,
                            sku: p.sku,
                            name: p.name,
                            unit: p.unit || 'pcs',
                            category: p.category,
                            product_type: p.product_type,
                            image_emoji: p.image_emoji || '📦',
                            opening_qty: p.stock || 0,
                            current_branch_stock: p.stock || 0,
                            closing_qty: p.stock || 0
                        }));
                    }
                    const waterMeter = (closingData ? closingData.water_meter : {}) || {};
                    const meterYesterday = _nn(waterMeter.meter_yesterday, 0);
                    const meterYesterdayDate = _nn(waterMeter.last_log_date, null);

                    window.closingShiftState = {
                        initialCash: initCash,
                        cashSales: cashSales,
                        expectedCash: expectedCash,
                        categories: (closingData ? closingData.expense_categories : []) || [],
                        employees: (closingData ? closingData.branch_employees : []) || [],
                        vehicles: (closingData && Array.isArray(closingData.branch_vehicles) && closingData.branch_vehicles.length > 0) ? closingData.branch_vehicles : ((state.vehicles || []).filter(v => (!v.branch_id || v.branch_id == branchId))),
                        waterMeter: waterMeter,
                        totalGalonSold: (closingData ? closingData.total_galon_sold : 0) || 0
                    };

                    const totalGalonSold = (closingData ? closingData.total_galon_sold : 0) || 0;

                    let closingItemsRows = '';
                    if (items.length > 0) {
                        closingItemsRows = items.map(item => {
                            let legacyId = '';
                            if (item.sku === 'RAW-089') legacyId = 'id="closing-raw-mineral"';
                            else if (item.sku === 'RAW-020') legacyId = 'id="closing-raw-ro"';
                            else if (item.sku === 'RAW-00092') legacyId = 'id="closing-raw-plastik"';

                            const itemName = escapeHtml(item.name || item.sku);
                            const itemUnit = escapeHtml(item.unit || 'pcs');
                            const isGalonFg = (item.unit === 'galon' || (item.name || '').toLowerCase().includes('galon')) && item.product_type === 'FINISHED_GOODS';
                            const isCapRaw = (item.sku === 'RAW-089' || item.sku === 'RAW-020' || (item.name || '').toLowerCase().includes('tutup galon'));

                            let sopBadge = '';
                            if (isGalonFg) {
                                sopBadge = `<span class="inline-flex items-center px-1.5 py-0.5 rounded text-[9px] font-black bg-emerald-100 text-emerald-800 border border-emerald-300">🎯 Standar Closing: 10 Galon (Wajib Standby)</span>`;
                            } else if (isCapRaw) {
                                sopBadge = `<span class="inline-flex items-center px-1.5 py-0.5 rounded text-[9px] font-bold bg-amber-100 text-amber-800 border border-amber-300">🔄 Sisa Fisik Diretur ke Gudang</span>`;
                            }

                            const initQtyVal = (item.initial_qty !== undefined && item.initial_qty !== null) ? Number(item.initial_qty) : Number(item.opening_qty || 0);
                            const openAddQtyVal = (item.opening_added_qty !== undefined && item.opening_added_qty !== null) ? Number(item.opening_added_qty) : 0;
                            const extraAddQtyVal = (item.extra_added_qty !== undefined && item.extra_added_qty !== null) ? Number(item.extra_added_qty) : 0;
                            const extraShiftBadge = (extraAddQtyVal !== 0)
                                ? `<span class="inline-block mt-0.5 px-1.5 py-0.5 rounded bg-sky-50 text-sky-700 border border-sky-200 text-[9px] font-bold">Tambahan Shift: ${extraAddQtyVal > 0 ? '+' : ''}${formatDecimal(extraAddQtyVal)} ${itemUnit}</span>`
                                : '';

                            return `
                                <div class="bg-white/90 dark:bg-slate-800/90 p-2.5 sm:p-3 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-2xs grid grid-cols-1 sm:grid-cols-12 gap-2.5 items-center">
                                    <div class="sm:col-span-5 min-w-0 pr-1">
                                        <div class="flex items-center gap-1.5 flex-wrap">
                                            <span class="text-xs font-black text-slate-800 dark:text-slate-100 uppercase leading-snug break-words">${itemName}</span>
                                            <span class="text-[9px] px-1.5 py-0.5 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 rounded font-bold shrink-0">${itemUnit}</span>
                                            ${sopBadge}
                                        </div>
                                        <span class="block text-[10px] text-slate-400 font-mono mt-0.5">${item.sku}</span>
                                        <span class="block text-[10px] text-indigo-700 dark:text-indigo-300 font-semibold mt-0.5">Stok Awal: <b>${formatDecimal(initQtyVal)}</b>${openAddQtyVal > 0 ? ` • +Opening: <b>+${formatDecimal(openAddQtyVal)}</b>` : ''} ${itemUnit}</span>
                                        ${extraShiftBadge}
                                    </div>
                                    <div class="sm:col-span-3 text-left sm:text-center">
                                        <span class="text-[10px] text-slate-400 uppercase font-bold block sm:hidden">Total Pagi</span>
                                        <span class="inline-block px-2.5 py-1 bg-indigo-50 dark:bg-indigo-950/80 text-indigo-900 dark:text-indigo-300 border border-indigo-100 dark:border-indigo-800/80 rounded-xl text-xs font-black">
                                            ${formatDecimal(item.opening_qty)} <span class="text-[9px] font-normal text-indigo-500 dark:text-indigo-400">${itemUnit}</span>
                                        </span>
                                    </div>
                                    <div class="sm:col-span-4">
                                        <div class="relative">
                                            <input type="number" step="any" ${legacyId} data-product-id="${item.product_id}" data-product-name="${itemName}" data-unit="${itemUnit}" data-opening-qty="${item.opening_qty}" min="0" value="" placeholder="" class="shift-closing-item-input w-full text-center py-2 px-3 bg-white dark:bg-slate-900 border border-rose-200 dark:border-rose-900/60 rounded-xl font-black text-slate-900 dark:text-slate-100 text-sm focus:ring-2 focus:ring-rose-500 shadow-inner">
                                        </div>
                                    </div>
                                </div>
                            `;
                        }).join('');
                    } else {
                        closingItemsRows = `
                            <div class="p-4 text-center text-xs text-slate-500 dark:text-slate-400 bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800">
                                Tidak ada produk pelacakan stok yang terdaftar untuk dilaporkan.
                            </div>
                        `;
                    }

                body.innerHTML = `
                    <!-- 1. Rekonsiliasi Kas di Laci Kasir -->
                    <div class="bg-gradient-to-br from-rose-50/80 via-white to-amber-50/60 dark:from-slate-800/90 dark:via-slate-800/80 dark:to-slate-900 p-4 sm:p-5 rounded-2xl sm:rounded-3xl border border-rose-200/80 dark:border-slate-700/80 shadow-sm space-y-3.5">
                        <div class="flex items-center justify-between border-b border-rose-100 dark:border-slate-700/80 pb-2">
                            <div class="flex items-center space-x-2">
                                <span class="text-xs sm:text-sm font-black text-rose-950 dark:text-rose-300 uppercase tracking-wider">Rekonsiliasi Kas Laci Kasir</span>
                                <span class="px-2 py-0.5 rounded-full text-[10px] font-black bg-rose-100 dark:bg-rose-950/80 text-rose-800 dark:text-rose-300 border border-rose-200 dark:border-rose-800/80">Cash Audit</span>
                            </div>
                            <span class="text-[10px] sm:text-[11px] font-bold text-slate-500 dark:text-slate-400">${txCount} Transaksi Penjualan Tunai</span>
                        </div>

                        <!-- Opsi Pengeluaran Kas Laci Kasir (Beban, Kasbon, Uang Makan) -->
                        <div class="bg-white dark:bg-slate-900 p-3 sm:p-4 rounded-2xl border border-rose-200 dark:border-rose-900/50 shadow-2xs space-y-3">
                            <div class="flex items-center justify-between border-b border-slate-100 dark:border-slate-800 pb-2 flex-wrap gap-2">
                                <div>
                                    <div class="flex items-center space-x-1.5">
                                        <span class="text-xs sm:text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-wide">💸 Pengeluaran Kas Laci Kasir</span>
                                        <span class="px-1.5 py-0.5 rounded text-[9px] font-bold bg-rose-50 dark:bg-rose-950/80 text-rose-700 dark:text-rose-300 border border-rose-200 dark:border-rose-800/80">Petty Cash</span>
                                    </div>
                                    <span class="text-[10px] text-slate-400 dark:text-slate-500 block mt-0.5">Catat uang tunai yang dikeluarkan dari laci kasir (Beban Toko, Kasbon, atau Uang Makan).</span>
                                </div>
                                <div class="flex items-center space-x-2">
