        function updateClosingCashSummary() {
            const initCash = (window.closingShiftState ? window.closingShiftState.initialCash : 0) || 0;
            const cashSales = (window.closingShiftState ? window.closingShiftState.cashSales : 0) || 0;

            let totExp = 0;
            document.querySelectorAll('.closing-expense-row .expense-amount-input').forEach(el => {
                totExp += parseFloat(el.value) || 0;
            });

            let totLoan = 0;
            document.querySelectorAll('.closing-loan-row .loan-amount-input').forEach(el => {
                totLoan += parseFloat(el.value) || 0;
            });

            let totMeal = 0;
            document.querySelectorAll('.closing-meal-row .meal-amount-input').forEach(el => {
                totMeal += parseFloat(el.value) || 0;
            });

            const totalDisb = totExp + totLoan + totMeal;
            const expectedCash = Math.max(0, (initCash + cashSales) - totalDisb);

            if (window.closingShiftState) {
                window.closingShiftState.expectedCash = expectedCash;
            }

            // Update DOM badges and KPI
            const badgeDisb = document.getElementById('closing-total-disbursements-badge');
            if (badgeDisb) badgeDisb.innerText = '- ' + formatRupiah(totalDisb);

            const kpiDisb = document.getElementById('closing-kpi-disbursements');
            if (kpiDisb) kpiDisb.innerText = '- ' + formatRupiah(totalDisb);

            const kpiExp = document.getElementById('closing-kpi-expected');
            if (kpiExp) kpiExp.innerText = '= ' + formatRupiah(expectedCash);

            const subExp = document.getElementById('closing-sub-expense');
            if (subExp) subExp.innerText = formatRupiah(totExp);

            const subLoan = document.getElementById('closing-sub-loan');
            if (subLoan) subLoan.innerText = formatRupiah(totLoan);

            const subMeal = document.getElementById('closing-sub-meal');
            if (subMeal) subMeal.innerText = formatRupiah(totMeal);

            calculateClosingCashDifference(expectedCash);
        }

        function isBbmCategory(catName) {
            if (!catName) return false;
            const s = String(catName).toUpperCase();
            return s.indexOf('BBM') !== -1 || s.indexOf('BAHAN BAKAR') !== -1 || s.indexOf('BENSIN') !== -1 || s.indexOf('SOLAR') !== -1 || s.indexOf('PERTALITE') !== -1;
        }

        function onClosingExpenseCategoryChange(selectEl) {
            if (!selectEl) return;
            const row = selectEl.closest('.closing-expense-row');
            if (!row) return;
            const isBbm = isBbmCategory(selectEl.value);
            const bbmBox = row.querySelector('.expense-bbm-details');
            if (bbmBox) {
                if (isBbm) {
                    bbmBox.classList.remove('hidden');
                    const vehSelect = row.querySelector('.expense-vehicle-select');
                    if (vehSelect) onClosingExpenseVehicleChange(vehSelect);
                } else {
