        // ==========================================
        // WATER METER COUNTER & ADJUSTMENT HELPERS
        // ==========================================
        function calculateWaterMeterOutput() {
            const yesterday = parseFloat(_val('closing-meter-yesterday')) || 0;
            const todayInput = document.getElementById('closing-meter-today');
            const todayVal = todayInput ? todayInput.value.trim() : '';
            const previewEl = document.getElementById('closing-meter-dispensed-preview');
            const diffPulsaEl = document.getElementById('closing-meter-diff-pulsa');
            const adjustedPreviewEl = document.getElementById('closing-meter-final-adjusted-galon');
            
            if (todayVal === '') {
                if (previewEl) previewEl.innerText = '0.00 Galon';
                if (diffPulsaEl) diffPulsaEl.innerText = 'Selisih: 0 pulsa';
                if (adjustedPreviewEl) adjustedPreviewEl.innerText = '0.00 Galon';
                return;
            }

            const today = parseFloat(todayVal) || 0;
            const diff = today - yesterday;
            const adjType = _val('closing-meter-adj-type') || 'PULSE';
            const adjVal = parseFloat(_val('closing-meter-adj-val')) || 0;

            let galon = 0;
            if (adjType === 'GALON') {
                galon = (diff / 782) + adjVal;
            } else {
                galon = (diff + adjVal) / 782;
            }

            const rawGalon = diff / 782;

            if (previewEl) {
                previewEl.innerText = (galon < 0 ? '0.00' : galon.toFixed(2)) + ' Galon';
            }
            if (diffPulsaEl) {
                diffPulsaEl.innerText = `Selisih: ${diff.toLocaleString('id-ID')} pulsa (${rawGalon.toFixed(2)} gal)`;
            }
            if (adjustedPreviewEl) {
                adjustedPreviewEl.innerText = (galon < 0 ? '0.00' : galon.toFixed(2)) + ' Galon';
            }
        }

        function unlockYesterdayMeter() {
            const input = document.getElementById('closing-meter-yesterday');
            const btn = document.getElementById('btn-unlock-yesterday');
            if (!input) return;
            if (input.hasAttribute('readonly')) {
                input.removeAttribute('readonly');
                input.classList.remove('bg-slate-100');
                input.classList.add('bg-white', 'border-amber-400');
                input.focus();
                if (btn) btn.innerText = 'Kunci';
            } else {
                input.setAttribute('readonly', 'true');
                input.classList.remove('bg-white', 'border-amber-400');
                input.classList.add('bg-slate-100');
                if (btn) btn.innerText = 'Ubah';
            }
            calculateWaterMeterOutput();
        }

        function toggleFinalShiftWaterMeter() {
            const chk = document.getElementById('check-is-final-shift');
            const meterSection = document.getElementById('closing-water-meter-section');
            const meterTodayInput = document.getElementById('closing-meter-today');
            const modeBadge = document.getElementById('closing-shift-mode-badge');
            const isChecked = chk ? chk.checked : false;
            const shiftNum = parseInt((state.activeShift ? state.activeShift.shift_number : 1)) || 1;
            const shiftName = (state.activeShift ? state.activeShift.shift_name : 'Shift 1') || ('Shift ' + shiftNum);

            if (meterSection) {
                if (isChecked) {
                    meterSection.classList.remove('hidden');
                } else {
                    meterSection.classList.add('hidden');
                }
            }
            if (meterTodayInput) {
                meterTodayInput.disabled = !isChecked;
                if (!isChecked) {
                    meterTodayInput.value = '';
                    calculateWaterMeterOutput();
                } else {
                    setTimeout(() => meterTodayInput.focus(), 50);
                }
            }
            if (modeBadge) {
                modeBadge.className = `px-2.5 py-0.5 rounded-full text-[10px] font-black ${isChecked ? 'bg-rose-100 text-rose-800' : 'bg-indigo-100 text-indigo-800'} uppercase tracking-wider`;
                modeBadge.innerText = isChecked
                    ? 'Closing Day / Tutup Toko Malam 🌙'
                    : `Serah Terima Antar Kasir (${shiftName} → Shift ${shiftNum + 1}) 🔄`;
            }
            const btn = document.getElementById('shift-modal-action-btn');
            if (btn) {
                btn.innerText = isChecked
                    ? 'TUTUP TOKO (CLOSING DAY) & SIMPAN REKAP MALAM'
                    : `TUTUP ${shiftName.toUpperCase()} & SERAH TERIMA (LANJUT SHIFT ${shiftNum + 1})`;
            }
        }

