        function calculateModalMeterOutput() {
            const yesterday = parseFloat(_val('wma-yesterday')) || 0;
            const today = parseFloat(_val('wma-today')) || 0;
            const adjType = _val('wma-adj-type') || 'PULSE';
            const adjVal = parseFloat(_val('wma-adj-val')) || 0;
            const previewEl = document.getElementById('wma-calc-preview');

            const diff = today - yesterday;
            let galon = 0;
            if (adjType === 'GALON') {
                galon = (diff / 782) + adjVal;
            } else {
                galon = (diff + adjVal) / 782;
            }

            if (previewEl) {
                previewEl.innerText = `${galon.toFixed(2)} Galon (Δ ${diff.toLocaleString('id-ID')} pulsa)`;
            }
        }

        async function loadWaterMeterLogs() {
            const branchId = state.currentBranch ? state.currentBranch.id : 1;
            const container = document.getElementById('wma-logs-table-container');
            const yesterdayInput = document.getElementById('wma-yesterday');

            try {
                const res = await fetch(`api.php?action=get_water_meter_logs&branch_id=${branchId}&limit=30`);
                const data = await res.json();
                if (!data.success) {
                    if (container) container.innerHTML = `<div class="p-4 text-center text-rose-500">${escapeHtml(data.message || 'Gagal memuat log meteran')}</div>`;
                    return;
                }

                if (yesterdayInput && (!yesterdayInput.value || yesterdayInput.value === '0')) {
                    yesterdayInput.value = data.latest_meter || 0;
                }

                const logs = data.logs || [];
                if (logs.length === 0) {
                    if (container) container.innerHTML = `<div class="p-6 text-center text-slate-400">Belum ada riwayat pencatatan meteran air untuk cabang ini.</div>`;
                    return;
                }

                let rows = logs.map(l => {
                    const galon = parseFloat(l.water_dispensed_galon) || 0;
                    const diff = parseFloat(l.meter_difference) || 0;
                    const adj = parseFloat(l.meter_adjustment) || 0;
                    let adjText = '-';
                    if (adj !== 0) {
                        adjText = `<span class="text-amber-700 font-bold">${adj > 0 ? '+' : ''}${adj} ${escapeHtml(l.adjustment_type || 'PULSE')}</span>`;
                        if (l.adjustment_reason) {
                            adjText += `<br><span class="text-[9px] text-slate-400 italic">${escapeHtml(l.adjustment_reason)}</span>`;
                        }
                    }

                    return `
                        <tr class="hover:bg-slate-50 border-b border-slate-100 last:border-0">
                            <td class="p-2.5 font-bold text-slate-800">
                                <div>${l.log_date}</div>
                                <div class="text-[10px] text-slate-400 font-normal">${escapeHtml(l.shift_name || 'Penyesuaian')} • ${escapeHtml(l.recorder_name || '-')}</div>
                            </td>
                            <td class="p-2.5 text-center font-mono text-slate-600">${parseFloat(l.meter_yesterday).toLocaleString('id-ID')}</td>
                            <td class="p-2.5 text-center font-mono font-bold text-sky-900 bg-sky-50/50">${parseFloat(l.meter_today).toLocaleString('id-ID')}</td>
                            <td class="p-2.5 text-center font-mono text-slate-700">${diff.toLocaleString('id-ID')}</td>
                            <td class="p-2.5 text-center text-[11px]">${adjText}</td>
                            <td class="p-2.5 text-right font-mono font-black text-emerald-700">${galon.toFixed(2)} Galon</td>
                        </tr>
                    `;
                }).join('');

                if (container) {
                    container.innerHTML = `
                        <div class="overflow-x-auto max-h-60">
                            <table class="w-full text-left">
                                <thead class="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-black text-[10px] uppercase sticky top-0 border-b border-slate-200 dark:border-slate-700">
                                    <tr>
                                        <th class="p-2.5">Tanggal / Petugas</th>
                                        <th class="p-2.5 text-center">Awal</th>
                                        <th class="p-2.5 text-center">Akhir</th>
                                        <th class="p-2.5 text-center">Selisih</th>
                                        <th class="p-2.5 text-center">Koreksi</th>
                                        <th class="p-2.5 text-right">Galon</th>
                                    </tr>
                                </thead>
                                <tbody class="divide-y divide-slate-100">
                                    ${rows}
                                </tbody>
                            </table>
                        </div>
                    `;
                }
            } catch (e) {
                if (container) container.innerHTML = `<div class="p-4 text-center text-rose-500">Error: ${escapeHtml(e.message)}</div>`;
            }
        }

        async function saveWaterMeterAdjustmentForm(e) {
            if (e) e.preventDefault();
            const branchId = state.currentBranch ? state.currentBranch.id : 1;
            const userId = state.currentUser ? state.currentUser.id : 1;
            const date = _val('wma-date');
            const yesterday = parseFloat(_val('wma-yesterday')) || 0;
            const today = parseFloat(_val('wma-today')) || 0;
            const adjVal = parseFloat(_val('wma-adj-val')) || 0;
            const adjType = _val('wma-adj-type') || 'PULSE';
            const reason = _val('wma-reason').trim() || '';

            if (!date) {
                alert('Silakan pilih tanggal pencatatan.');
                return;
            }

            try {
                const res = await fetch('api.php?action=save_water_meter_adjustment', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        branch_id: branchId,
                        user_id: userId,
                        log_date: date,
                        meter_yesterday: yesterday,
                        meter_today: today,
                        meter_adjustment: adjVal,
                        adjustment_type: adjType,
                        adjustment_reason: reason
                    })
                });
                const data = await res.json();
                if (data.success) {
                    alert('Penyesuaian meteran air berhasil disimpan!');
                    const todayInput = document.getElementById('wma-today');
                    if (todayInput) todayInput.value = '';
                    const reasonInput = document.getElementById('wma-reason');
                    if (reasonInput) reasonInput.value = '';
                    const adjValInput = document.getElementById('wma-adj-val');
                    if (adjValInput) adjValInput.value = '0';
                    await loadWaterMeterLogs();
                    if (state.reportActiveSubtab === 'shifts') {
                        loadShiftReports();
                    }
                } else {
                    alert(data.message || 'Gagal menyimpan penyesuaian meteran air.');
                }
            } catch (err) {
                alert('Terjadi kesalahan koneksi: ' + err.message);
            }
        }

        function closeShiftModal() {
            window._isResolvingYesterdayShiftEndDay = false;
            document.getElementById('shift-modal').classList.add('hidden');
        }

                async function executeShiftAction() {
            const isShiftOpen = state.activeShift && state.activeShift.status === 'OPEN';
            if (isShiftOpen) {
                const btn = document.getElementById('shift-modal-action-btn');
                const originalBtnHtml = btn ? btn.innerHTML : '';

                // Validasi Beban Operasional BBM: Odometer Mandatory & Cek Odometer Sama
                const expenseRows = document.querySelectorAll('.closing-expense-row');
                for (let i = 0; i < expenseRows.length; i++) {
                    const row = expenseRows[i];
                    const cat = (row.querySelector('.expense-category-input') ? row.querySelector('.expense-category-input').value : '') || '';
                    const amt = parseFloat((row.querySelector('.expense-amount-input') ? row.querySelector('.expense-amount-input').value : '')) || 0;
                    if (typeof isBbmCategory === 'function' && isBbmCategory(cat) && amt > 0) {
                        const odoInput = row.querySelector('.expense-odometer-input');
                        const vehSelect = row.querySelector('.expense-vehicle-select');
                        const vehName = (vehSelect && vehSelect.options[vehSelect.selectedIndex]) ? vehSelect.options[vehSelect.selectedIndex].text : 'Kendaraan';
                        const odoValStr = odoInput ? odoInput.value.trim() : '';

                        if (odoValStr === '' || isNaN(parseFloat(odoValStr))) {
                            alert("PERINGATAN BEBAN BBM (MANDATORY):\n\nAnda memasukkan pengeluaran \"" + cat + "\" sebesar " + formatRupiah(amt) + ".\nUntuk pencatatan BBM, input KM Odometer kendaraan WAJIB diisi (mandatory).\n\nSilakan isi angka odometer fisik terkini dari armada " + vehName + ".");
                            if (typeof switchDisbursementTab === 'function') switchDisbursementTab('expense');
                            if (odoInput) {
                                odoInput.focus();
                                odoInput.scrollIntoView({ behavior: 'smooth', block: 'center' });
                            }
                            if (btn) {
                                btn.disabled = false;
                                btn.innerHTML = originalBtnHtml;
                            }
                            return;
                        }

                        const newOdo = parseFloat(odoValStr);
                        const lastOdo = parseFloat(odoInput.getAttribute('data-last-odometer') || 0);

                        if (newOdo === lastOdo) {
                            const proceedSame = confirm("⚠️ PERINGATAN ODOMETER KENDARAAN:\n\nAngka odometer yang Anda masukkan (" + formatDecimal(newOdo) + " KM) SAMA DENGAN odometer sebelumnya (" + formatDecimal(lastOdo) + " KM) untuk armada " + vehName + ".\n\nHal ini menandakan odometer/spedometer tidak jalan atau kendaraan tidak bergerak.\n\nApakah Anda yakin ingin tetap melanjutkan penutupan shift?");
                            if (!proceedSame) {
                                if (typeof switchDisbursementTab === 'function') switchDisbursementTab('expense');
                                if (odoInput) odoInput.focus();
                                if (btn) {
                                    btn.disabled = false;
                                    btn.innerHTML = originalBtnHtml;
                                }
                                return;
                            }
                        } else if (newOdo < lastOdo) {
                            const proceedLess = confirm("⚠️ PERHATIAN ODOMETER KENDARAAN:\n\nAngka odometer yang Anda masukkan (" + formatDecimal(newOdo) + " KM) LEBIH KECIL dari odometer sebelumnya (" + formatDecimal(lastOdo) + " KM) untuk armada " + vehName + ".\n\nApakah Anda yakin ingin tetap melanjutkan penutupan shift?");
                            if (!proceedLess) {
                                if (typeof switchDisbursementTab === 'function') switchDisbursementTab('expense');
                                if (odoInput) odoInput.focus();
                                if (btn) {
                                    btn.disabled = false;
                                    btn.innerHTML = originalBtnHtml;
                                }
                                return;
                            }
                        }
                    }
                }
                const actual = parseFloat(document.getElementById('shift-input-actual-cash').value) || 0;
                const elCloseMin = document.getElementById('closing-raw-mineral');
                const elCloseRo = document.getElementById('closing-raw-ro');
                const elClosePl = document.getElementById('closing-raw-plastik');
                const closeMin = (elCloseMin && elCloseMin.value.trim() !== '') ? parseInt(elCloseMin.value) : null;
                const closeRo = (elCloseRo && elCloseRo.value.trim() !== '') ? parseInt(elCloseRo.value) : null;
                const closePl = (elClosePl && elClosePl.value.trim() !== '') ? parseInt(elClosePl.value) : null;
                const notes = _val('shift-input-notes') || '';
                const isFinal = _chk('check-is-final-shift') ? 1 : 0;

                // Collect dynamic closing items
                const dynamicClosingItems = [];
                document.querySelectorAll('.shift-closing-item-input').forEach(input => {
                    const pId = parseInt(input.getAttribute('data-product-id')) || 0;
                    if (pId > 0) {
                        const hasVal = (input.value !== '' && input.value !== null && input.value.trim() !== '');
                        const rawVal = hasVal ? parseFloat(input.value) : null;
                        dynamicClosingItems.push({
                            product_id: pId,
                            closing_qty: (rawVal !== null && !isNaN(rawVal)) ? rawVal : null
                        });
                    }
                });

                // Collect 3 Jenis Pengeluaran Kasir
                const expenses = [];
                document.querySelectorAll('.closing-expense-row').forEach(row => {
                    const cat = (row.querySelector('.expense-category-input') ? row.querySelector('.expense-category-input').value : '') || 'Biaya Operasional Toko';
                    const amt = parseFloat((row.querySelector('.expense-amount-input') ? row.querySelector('.expense-amount-input').value : '')) || 0;
                    const nts = (row.querySelector('.expense-notes-input') ? row.querySelector('.expense-notes-input').value : '') || '';
                    const isBbm = (typeof isBbmCategory === 'function') ? isBbmCategory(cat) : false;
                    const vSelect = row.querySelector('.expense-vehicle-select');
                    const odoInput = row.querySelector('.expense-odometer-input');
                    const vehId = (isBbm && vSelect) ? parseInt(vSelect.value) : null;
                    const odoVal = (isBbm && odoInput && odoInput.value.trim() !== '') ? parseFloat(odoInput.value) : null;
                    if (amt > 0) {
                        expenses.push({
                            category: cat,
                            amount: amt,
                            notes: nts,
                            is_bbm: isBbm ? 1 : 0,
                            vehicle_id: vehId,
                            odometer: odoVal
                        });
                    }
                });

                const loans = [];
                document.querySelectorAll('.closing-loan-row').forEach(row => {
                    const uId = parseInt((row.querySelector('.loan-user-input') ? row.querySelector('.loan-user-input').value : '')) || 0;
                    const amt = parseFloat((row.querySelector('.loan-amount-input') ? row.querySelector('.loan-amount-input').value : '')) || 0;
                    const nts = (row.querySelector('.loan-notes-input') ? row.querySelector('.loan-notes-input').value : '') || '';
                    if (amt > 0 && uId > 0) {
                        loans.push({ user_id: uId, amount: amt, notes: nts });
                    }
                });

                const meals = [];
                document.querySelectorAll('.closing-meal-row').forEach(row => {
                    const uId = parseInt((row.querySelector('.meal-user-input') ? row.querySelector('.meal-user-input').value : '')) || 0;
                    const amt = parseFloat((row.querySelector('.meal-amount-input') ? row.querySelector('.meal-amount-input').value : '')) || 0;
                    const nts = (row.querySelector('.meal-notes-input') ? row.querySelector('.meal-notes-input').value : '') || '';
                    if (amt > 0 && uId > 0) {
                        meals.push({ user_id: uId, amount: amt, notes: nts });
                    }
                });

                // Collect Water Meter Display Counter Input (Hanya jika Tutup Toko Hari Ini / isFinal dicentang)
                const meterTodayVal = (isFinal && document.getElementById('closing-meter-today')) ? document.getElementById('closing-meter-today').value.trim() : '';
                const meterToday = meterTodayVal !== '' ? parseFloat(meterTodayVal) : null;
                const meterYesterdayVal = (isFinal && document.getElementById('closing-meter-yesterday')) ? document.getElementById('closing-meter-yesterday').value.trim() : '';
                const meterYesterday = meterYesterdayVal !== '' ? parseFloat(meterYesterdayVal) : null;
                const meterAdj = 0;
                const meterAdjType = 'PULSE';
                const meterAdjReason = '';

                const res = await fetch('api.php?action=close_shift', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        shift_id: state.activeShift.id,
                        actual_cash: actual,
                        items: dynamicClosingItems,
                        closing_raw_mineral: closeMin,
                        closing_raw_ro: closeRo,
                        closing_raw_plastik: closePl,
                        shift_notes: notes,
                        is_final_shift: isFinal,
                        expenses: expenses,
                        loans: loans,
                        meals: meals,
                        meter_today: meterToday,
                        meter_yesterday: meterYesterday,
                        meter_adjustment: meterAdj,
                        adjustment_type: meterAdjType,
                        adjustment_reason: meterAdjReason
                    })
                });
                const data = await res.json();
                if (data.success) {
                    let disbInfo = '';
                    if (data.summary && data.summary.total_disbursements > 0) {
                        disbInfo = `\n\n💸 Rincian Pengeluaran Kas Laci:\n- Biaya Beban Toko: ${formatRupiah(data.summary.total_expenses)}\n- Kasbon Karyawan: ${formatRupiah(data.summary.total_kasbon)}\n- Uang Makan Karyawan: ${formatRupiah(data.summary.total_meal_allowance)}\nTotal Kas Keluar: ${formatRupiah(data.summary.total_disbursements)}`;
                    }

                    let meterInfo = '';
                    if (data.summary && data.summary.water_meter_dispensed_galon !== null && data.summary.water_meter_dispensed_galon !== undefined) {
                        meterInfo = `\n💧 Pengeluaran Air Mesin: ${parseFloat(data.summary.water_meter_dispensed_galon).toFixed(2)} Galon (Display: ${data.summary.water_meter_today})`;
                    }

                    if (window._isResolvingYesterdayShiftEndDay) {
                        window._isResolvingYesterdayShiftEndDay = false;
                        var prevShiftId = state.activeShift ? state.activeShift.id : null;
                        if (prevShiftId) {
                            try {
                                localStorage.removeItem('kad_cross_day_confirmed_shift_' + prevShiftId);
                            } catch (e) {}
                        }
                        state.crossDayConfirmedShiftId = null;
                        state.activeShift = null;
                        state.branchClosedToday = false;
                        state.currentUserHasClosedShift = true;
                        window.userHasClosedShift = true;
                        updateShiftReportSubtabVisibility();
                        renderShiftBanner();
                        closeShiftModal();
                        if (state.reportActiveSubtab === 'shifts') {
                            loadShiftReports();
                        }
                        alert(`Penutupan End Day Shift Kemarin Berhasil!\n\nShift tanggal kemarin resmi ditutup & dibukukan.\nSistem membuka formulir OPENING SHIFT untuk operasional hari ini (${getDeviceLocalDateString()}).`);
                        setTimeout(function() {
                            openShiftModal(true);
                        }, 350);
                        return;
                    }

                    alert(`Penutupan Toko (End Day Closing) Berhasil!\n\nUang Fisik Aktual: ${formatRupiah(data.summary.actual_cash)}\nEkspektasi Sistem: ${formatRupiah(data.summary.expected_cash)}\nSelisih Kas: ${formatRupiah(data.summary.cash_difference)}${disbInfo}${meterInfo}\n\nOperasional toko hari ini resmi selesai. Sisa stok fisik malam telah direkap sebagai acuan pembukaan toko hari esok.`);
                    state.branchClosedToday = true;
                    state.finalClosedShift = {
                        id: (data.summary ? data.summary.shift_id : null),
                        shift_name: (data.summary ? data.summary.shift_name : 'Shift') || 'Closing Akhir',
                        cashier_name: (state.currentUser ? state.currentUser.name : 'Kasir') || 'Kasir',
                        end_time: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' })
                    };
                    state.activeShift = null;
                    state.currentUserHasClosedShift = true;
                    window.userHasClosedShift = true;
                    updateShiftReportSubtabVisibility();
                    renderShiftBanner();
                    closeShiftModal();
                    if (state.reportActiveSubtab === 'shifts') {
                        loadShiftReports();
                    }
                } else alert(data.message || data.error);
            } else {
                const actionBtn = document.getElementById('shift-modal-action-btn');
                const nextNum = parseInt((actionBtn ? actionBtn.getAttribute('data-next-shift-number') : null)) || 1;
                const nextName = (actionBtn ? actionBtn.getAttribute('data-next-shift-name') : null) || ('Shift ' + nextNum);

                const initCash = parseFloat(_val('shift-input-initial-cash')) || 0;

                // Collect dynamic opening items
                const dynamicOpeningItems = [];
                let openMin = null, openRo = null, openPl = null;
                let nightMin = null, nightRo = null, nightPl = null;

                if (nextNum === 1) {
                    // Kasir Pertama (Shift 1):
                    // Rumus: Stok Awal = Input Tambahan Baru + Stok Malam Kemarin
                    const nightInputsMap = {};
                    document.querySelectorAll('.shift-night-item-input').forEach(input => {
                        const pId = parseInt(input.getAttribute('data-product-id')) || 0;
                        if (pId > 0) {
                            nightInputsMap[pId] = parseInt(input.value) || 0;
                        }
                    });

                    document.querySelectorAll('.shift-added-item-input').forEach(input => {
                        const pId = parseInt(input.getAttribute('data-product-id')) || 0;
                        const sku = input.getAttribute('data-sku') || '';
                        const isCap = (sku === 'RAW-089' || sku === 'RAW-020' || (input.getAttribute('data-product-name') || '').toLowerCase().includes('tutup galon'));
                        const nightStockAttr = input.getAttribute('data-night-stock');
                        let nightStock = (nightStockAttr !== null && !isNaN(parseInt(nightStockAttr)))
                            ? parseInt(nightStockAttr)
                            : (nightInputsMap[pId] !== undefined ? nightInputsMap[pId] : 0);
                        if (isCap && nextNum === 1) {
                            nightStock = 0;
                        }
                        const hasVal = (input.value !== '' && input.value !== null && input.value.trim() !== '');
                        const rawVal = hasVal ? parseInt(input.value) : null;
                        const addedQty = (rawVal !== null && !isNaN(rawVal) && rawVal > 0) ? rawVal : null;
                        const openingQty = (addedQty !== null) ? (nightStock + addedQty) : nightStock;

                        if (pId > 0) {
                            dynamicOpeningItems.push({
                                product_id: pId,
                                sku: sku,
                                added_qty: addedQty,
                                night_qty: nightStock,
                                opening_qty: openingQty
                            });

                            if (sku === 'RAW-089' || pId === 89) {
                                openMin = openingQty;
                                nightMin = nightStock;
                            } else if (sku === 'RAW-020' || pId === 88) {
                                openRo = openingQty;
                                nightRo = nightStock;
                            } else if (sku === 'RAW-00092' || pId === 105) {
                                openPl = openingQty;
                                nightPl = nightStock;
                            }
                        }
                    });
                } else {
                    // Kasir Berikutnya (Shift 2+):
                    // Kasir hanya input uang modal awal! Stok otomatis diteruskan dari shift sebelumnya
                    document.querySelectorAll('.shift-carried-item').forEach(el => {
                        const pId = parseInt(el.getAttribute('data-product-id')) || 0;
                        const stock = parseInt(el.getAttribute('data-stock')) || 0;
                        if (pId > 0) {
                            dynamicOpeningItems.push({
                                product_id: pId,
                                added_qty: 0,
                                night_qty: stock,
                                opening_qty: stock
                            });

                            if (pId === 89) { openMin = stock; nightMin = stock; }
                            else if (pId === 88) { openRo = stock; nightRo = stock; }
                            else if (pId === 105) { openPl = stock; nightPl = stock; }
                        }
                    });
                }

                let data = null;
                try {
                    if (state.isOfflineMode || !navigator.onLine) {
                        throw new Error('OFFLINE_MODE');
                    }
                    const res = await fetch('api.php?action=open_shift', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            branch_id: (state.currentBranch ? state.currentBranch.id : 1) || 1,
                            user_id: (state.currentUser ? state.currentUser.id : 1) || 1,
                            shift_number: nextNum,
                            shift_name: nextName,
                            initial_cash: initCash,
                            force_override: window._forceShiftOverride ? 1 : 0,
                            items: dynamicOpeningItems,
                            opening_raw_mineral: openMin,
                            opening_raw_ro: openRo,
                            opening_raw_plastik: openPl,
                            closing_night_mineral: nightMin,
                            closing_night_ro: nightRo,
                            closing_night_plastik: nightPl
                        })
                    });
                    data = await res.json();
                } catch (netErr) {
                    console.warn('Gagal buka shift online, mengaktifkan shift offline:', netErr);
                    const offShiftRef = 'OFF-SHIFT-' + Date.now();
                    const offShift = {
                        id: offShiftRef,
                        offline_ref: offShiftRef,
                        branch_id: (state.currentBranch ? state.currentBranch.id : 1) || 1,
                        user_id: (state.currentUser ? state.currentUser.id : 1) || 1,
                        shift_number: nextNum,
                        shift_name: nextName,
                        initial_cash: initCash,
                        status: 'OPEN',
                        cashier_name: (state.currentUser ? state.currentUser.name : 'Kasir') || 'Kasir',
                        start_time: getDeviceLocalDateTimeString()
                    };
                    await OfflineDB.setItem('offline_shifts', offShift);
                    data = {
                        success: true,
                        message: 'Shift Kasir (Mode Offline) berhasil dibuka!',
                        shift: offShift
                    };
                }

                if (data && data.success) {
                    alert(data.message);
                    window._forceShiftOverride = false;
                    state.branchClosedToday = false;
                    state.activeShift = data.shift;
                    renderShiftBanner();
                    closeShiftModal();
                    if (state.reportActiveSubtab === 'shifts') {
                        loadShiftReports();
                    }
                    await updateOfflineSyncStatusUI();
                } else {
                    alert((data && (data.message || data.error)) || 'Gagal membuka shift kasir.');
                }
            }
        }

        window.confirmSuperAdminForceReopen = function() {
            if (!confirm("Peringatan: Toko hari ini sudah ditutup harian (Closing Akhir).\n\nApakah Anda yakin ingin membuka shift baru secara darurat (Override)?\nSistem akan membuka shift sebagai Shift 1 (Pagi).")) return;
            openShiftModal(true);
        };

        // ==========================================
        // 2. LAPORAN PENJUALAN
        // ==========================================
        async function loadSalesReports() {
            updateStoreResetButtonsVisibility();
            const start = document.getElementById('report-start-date').value;
            const end = document.getElementById('report-end-date').value;
            const method = document.getElementById('report-payment-filter').value;
            const branchId = state.currentBranch ? state.currentBranch.id : '';
            const delivStartSync = document.getElementById('deliv-report-start-date');
            const delivEndSync = document.getElementById('deliv-report-end-date');
            if (delivStartSync && start) delivStartSync.value = start;
            if (delivEndSync && end) delivEndSync.value = end;
            const discStartSync = document.getElementById('disc-report-start-date');
            const discEndSync = document.getElementById('disc-report-end-date');
            if (discStartSync && start) discStartSync.value = start;
            if (discEndSync && end) discEndSync.value = end;

            const res = await fetch(`api.php?action=sales_reports&branch_id=${branchId}&start_date=${start}&end_date=${end}&payment_method=${method}`);
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

            document.getElementById('kpi-net-sales').innerText = formatRupiah(data.kpi.net_sales);
            document.getElementById('kpi-cogs').innerText = formatRupiah(data.kpi.total_cogs);
            document.getElementById('kpi-gross-profit').innerText = formatRupiah(data.kpi.gross_profit);
            document.getElementById('kpi-gross-margin').innerText = `Margin: ${data.kpi.gross_margin_percent}%`;
            document.getElementById('kpi-discount').innerText = formatRupiah(data.kpi.total_discount);
            const elKpiDiscSub = document.getElementById('kpi-discount-orders-sub');
            if (elKpiDiscSub) {
                const discCnt = Number(data.kpi.discounted_orders_count) || 0;
                const discRate = Number(data.kpi.discount_rate_percent) || 0;
                elKpiDiscSub.innerText = discCnt > 0 ? `${discCnt} Nota Diskon • ${formatDecimal(discRate)}%` : '0 Nota Diskon';
            }
            const elKpiDelivFee = document.getElementById('kpi-delivery-fee');
            if (elKpiDelivFee) elKpiDelivFee.innerText = formatRupiah(data.kpi.total_delivery_fee || 0);
            const elKpiDelivSub = document.getElementById('kpi-delivery-orders-sub');
            if (elKpiDelivSub) {
                const dCount = Number(data.kpi.delivery_orders_count) || 0;
                const dDist = Number(data.kpi.total_delivery_distance_km) || 0;
                elKpiDelivSub.innerText = dDist > 0 ? `${dCount} Kiriman • ${formatDecimal(dDist)} km` : `${dCount} Kiriman`;
            }
            document.getElementById('kpi-tx-count').innerText = data.kpi.total_transactions;
            document.getElementById('kpi-aov').innerText = formatRupiah(data.kpi.aov);
            const elSalesTxBadge = document.getElementById('sales-tx-list-count-badge');
            if (elSalesTxBadge) {
                elSalesTxBadge.innerText = ((data.recent_sales && Array.isArray(data.recent_sales)) ? data.recent_sales.length : 0) + ' Faktur';
            }

            // Cek selisih stok shift untuk rentang tanggal laporan
            try {
                const shiftDiffRes = await fetch(`api.php?action=get_shift_reports&branch_id=${branchId}&date=${end}`);
                const shiftDiffData = await shiftDiffRes.json();
                const diffBanner = document.getElementById('sales-report-stock-diff-banner');
                if (diffBanner) {
                    if (shiftDiffData.success && shiftDiffData.daily_summary && shiftDiffData.daily_summary.has_stock_difference) {
                        diffBanner.classList.remove('hidden');
                        const descEl = document.getElementById('sales-report-stock-diff-desc');
                        if (descEl) descEl.innerText = `Ditemukan ${shiftDiffData.daily_summary.total_stock_differences_count || 1} selisih fisik stok pada penutupan shift kasir (${end}). Silakan klik tombol di samping untuk meninjau audit stok.`;
                    } else {
                        diffBanner.classList.add('hidden');
                    }
                }
            } catch (eDiff) {}

            document.getElementById('report-top-products-body').innerHTML = data.top_products.map(tp => `
                <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors">
                    <td class="py-2.5 px-3 font-semibold text-slate-800 dark:text-slate-100">${tp.product_name}</td>
                    <td class="py-2.5 px-3 text-right font-bold text-slate-700 dark:text-slate-200">${tp.total_qty} pcs</td>
                    <td class="py-2.5 px-3 text-right font-medium text-slate-600 dark:text-slate-300">${formatRupiah(tp.total_sales)}</td>
                    <td class="py-2.5 px-3 text-right font-bold text-emerald-700 dark:text-emerald-400">${formatRupiah(tp.profit)}</td>
                </tr>
            `).join('') || `<tr><td colspan="4" class="text-center py-4 text-slate-400">Belum ada transaksi</td></tr>`;

            document.getElementById('payment-breakdown-list').innerHTML = data.payment_breakdown.map(pb => `
                <div class="p-3 bg-slate-50 dark:bg-slate-800/80 border border-slate-100 dark:border-slate-800 rounded-xl flex items-center justify-between text-xs">
                    <span class="font-bold text-slate-700 dark:text-slate-200">${pb.payment_method}</span>
                    <div class="text-right">
                        <span class="font-extrabold text-indigo-900 dark:text-indigo-400">${formatRupiah(pb.total)}</span>
                        <span class="text-[10px] text-slate-400 ml-1">(${pb.count} tx)</span>
                    </div>
                </div>
            `).join('') || `<p class="text-xs text-slate-400">Belum ada transaksi</p>`;

            const courierBreakEl = document.getElementById('sales-courier-breakdown-list');
            if (courierBreakEl) {
                const couriersArr = (data.delivery_summary && Array.isArray(data.delivery_summary.couriers)) ? data.delivery_summary.couriers : [];
                if (couriersArr.length > 0) {
                    courierBreakEl.innerHTML = couriersArr.map(function(c) {
                        const cName = escapeHtml(c.courier_name || '-');
                        const plate = (c.plate_number && c.plate_number !== '-') ? (' • ' + escapeHtml(c.plate_number)) : '';
                        const distKm = Number(c.total_distance_km) || 0;
                        const distTxt = distKm > 0 ? (' • ' + formatDecimal(distKm) + ' km') : '';
                        return '<div class="p-2.5 bg-sky-50/70 dark:bg-sky-950/40 border border-sky-100 dark:border-sky-900/60 rounded-xl flex items-center justify-between text-xs">' +
                            '<div>' +
                                '<p class="font-bold text-slate-800 dark:text-slate-100">🚚 ' + cName + '<span class="text-[10px] font-medium text-slate-500 dark:text-slate-400">' + plate + '</span></p>' +
                                '<p class="text-[10px] text-slate-500 dark:text-slate-400 mt-0.5">' + (Number(c.delivery_count) || 0) + ' kiriman' + distTxt + '</p>' +
                            '</div>' +
                            '<div class="text-right">' +
                                '<span class="font-extrabold text-sky-800 dark:text-sky-300">' + formatRupiah(c.total_fee || 0) + '</span>' +
                                '<span class="block text-[10px] text-slate-400">Nota: ' + formatRupiah(c.total_order_value || 0) + '</span>' +
                            '</div>' +
                        '</div>';
                    }).join('');
                } else {
                    courierBreakEl.innerHTML = '<p class="text-xs text-slate-400">Belum ada kiriman kurir pada periode ini.</p>';
                }
            }

            const discBreakEl = document.getElementById('sales-discount-breakdown-list');
            if (discBreakEl) {
                const discArr = (data.discount_summary && Array.isArray(data.discount_summary.breakdown)) ? data.discount_summary.breakdown : [];
                if (discArr.length > 0) {
                    discBreakEl.innerHTML = discArr.map(function(d) {
                        const cshName = escapeHtml(d.cashier_name || '-');
                        const catName = escapeHtml(d.customer_category || 'REGULER');
                        const gSub = Number(d.gross_subtotal) || 0;
                        const tDisc = Number(d.total_discount) || 0;
                        const pct = gSub > 0 ? formatDecimal((tDisc / gSub) * 100, 1) : '0';
                        return '<div class="p-2.5 bg-rose-50/70 dark:bg-rose-950/40 border border-rose-100 dark:border-rose-900/60 rounded-xl flex items-center justify-between text-xs">' +
                            '<div>' +
                                '<p class="font-bold text-slate-800 dark:text-slate-100">🏷️ ' + cshName + ' <span class="px-1.5 py-0.5 rounded bg-rose-100 dark:bg-rose-900 text-rose-700 dark:text-rose-200 text-[10px] font-bold">' + catName + '</span></p>' +
                                '<p class="text-[10px] text-slate-500 dark:text-slate-400 mt-0.5">' + (Number(d.discount_count) || 0) + ' nota berdiskon • rata-rata ' + pct + '%</p>' +
                            '</div>' +
                            '<div class="text-right">' +
                                '<span class="font-extrabold text-rose-700 dark:text-rose-400">- ' + formatRupiah(tDisc) + '</span>' +
                                '<span class="block text-[10px] text-slate-400">Kotor: ' + formatRupiah(gSub) + '</span>' +
                            '</div>' +
                        '</div>';
                    }).join('');
                } else {
                    discBreakEl.innerHTML = '<p class="text-xs text-slate-400">Tidak ada transaksi berdiskon pada periode ini.</p>';
                }
            }

            document.getElementById('report-transactions-body').innerHTML = data.recent_sales.map(function(s) {
                let discCellHtml = '<span class="text-[11px] text-slate-300 dark:text-slate-600">-</span>';
                const discVal = Number(s.discount) || 0;
                if (discVal > 0) {
                    const subVal = Number(s.subtotal) || 0;
                    const discPctTxt = subVal > 0 ? ('<p class="text-[10px] text-rose-500 dark:text-rose-400 mt-0.5">' + formatDecimal((discVal / subVal) * 100, 1) + '% dari ' + formatRupiah(subVal) + '</p>') : '';
                    discCellHtml = '<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-100 dark:bg-rose-900/80 text-rose-700 dark:text-rose-300">🏷️ -' + formatRupiah(discVal) + '</span>' + discPctTxt;
                }

                let delivCellHtml = '<span class="text-[11px] text-slate-400">Ambil di Toko</span>';
                if (Number(s.is_delivery_order) === 1) {
                    const feeVal = Number(s.delivery_fee) || 0;
                    const badgeHtml = feeVal > 0
                        ? '<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-sky-100 dark:bg-sky-950/80 text-sky-800 dark:text-sky-300 border border-sky-200 dark:border-sky-800">🚚 ' + formatRupiah(feeVal) + '</span>'
                        : '<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800">🎁 Free Kirim</span>';
                    const drvParts = [];
                    if (s.effective_driver_name) drvParts.push(escapeHtml(s.effective_driver_name));
                    if (Number(s.delivery_distance_km) > 0) drvParts.push(formatDecimal(s.delivery_distance_km) + ' km');
                    const subDrvHtml = drvParts.length > 0 ? '<p class="text-[10px] text-slate-500 dark:text-slate-400 mt-0.5">' + drvParts.join(' • ') + '</p>' : '';
                    delivCellHtml = badgeHtml + subDrvHtml;
                }
                return `
                <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors">
                    <td class="py-2.5 px-3 font-mono font-bold">
                        <button onclick="openSaleDetailModal('${s.invoice_number}')" class="text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 hover:underline flex items-center space-x-1 font-bold text-left" title="Klik untuk lihat detail transaksi">
                            <span>${s.invoice_number}</span>
                            <i data-lucide="external-link" class="w-3 h-3 text-indigo-400"></i>
                        </button>
                    </td>
                    <td class="py-2.5 px-3 text-slate-500 dark:text-slate-400">${s.created_at}</td>
                    <td class="py-2.5 px-3 text-slate-700 dark:text-slate-200 font-medium">${s.branch_name}</td>
                    <td class="py-2.5 px-3 text-slate-600 dark:text-slate-300">${s.cashier_name}</td>
                    <td class="py-2.5 px-3"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200">${s.payment_method}</span></td>
                    <td class="py-2.5 px-3 text-right">${discCellHtml}</td>
                    <td class="py-2.5 px-3">${delivCellHtml}</td>
                    <td class="py-2.5 px-3 text-right font-bold text-slate-800 dark:text-slate-100">${formatRupiah(s.grand_total)}</td>
                    <td class="py-2.5 px-3 text-right font-bold text-emerald-700 dark:text-emerald-400">${formatRupiah(s.gross_profit)}</td>
                    <td class="py-2.5 px-3 text-center">
                        <div class="flex items-center justify-center space-x-1.5">
                            <button onclick="openSaleDetailModal('${s.invoice_number}')" class="p-1 px-2 text-[11px] bg-indigo-50 dark:bg-indigo-950/80 hover:bg-indigo-100 dark:hover:bg-indigo-900 text-indigo-700 dark:text-indigo-300 rounded-lg font-bold flex items-center space-x-1" title="Lihat Detail">
                                <i data-lucide="eye" class="w-3 h-3"></i>
                                <span>Detail</span>
                            </button>
                            <button onclick="exportSingleSaleExcel('${s.invoice_number}')" class="p-1 px-2 text-[11px] bg-emerald-50 dark:bg-emerald-950/80 hover:bg-emerald-100 dark:hover:bg-emerald-900 text-emerald-700 dark:text-emerald-300 rounded-lg font-bold flex items-center space-x-1" title="Export Excel Transaksi Ini">
                                <i data-lucide="file-spreadsheet" class="w-3 h-3"></i>
                                <span>Excel</span>
                            </button>
                        </div>
                    </td>
                </tr>
            `;
            }).join('') || `<tr><td colspan="10" class="text-center py-6 text-slate-400">Belum ada riwayat transaksi</td></tr>`;
            lucide.createIcons();
        }

        // --- Sales Detail Modal & Excel Export Functions ---
        let currentDetailSaleData = null;

        async function openSaleDetailModal(invoiceNumber) {
            try {
                const res = await fetch(`api.php?action=get_sale_detail&invoice_number=${encodeURIComponent(invoiceNumber)}`);
                const data = await res.json();
                if (!data.success) {
                    alert(data.error || 'Gagal memuat detail transaksi');
                    return;
                }

                currentDetailSaleData = data;
                const s = data.sale;
                const items = data.items || [];

                document.getElementById('detail-modal-invoice-badge').innerText = s.invoice_number;
                document.getElementById('detail-modal-time').innerText = `${s.created_at} • Shift ID: #${s.shift_id || '-'}`;
                document.getElementById('detail-modal-branch').innerText = s.branch_name || 'Cabang';
                document.getElementById('detail-modal-cashier').innerText = `${s.cashier_name || '-'} (${s.cashier_nik || 'NIK -'})`;
                document.getElementById('detail-modal-customer').innerText = s.customer_name || 'Pelanggan Umum';
                document.getElementById('detail-modal-customer-cat').innerText = `Kategori: ${s.customer_category || 'REGULER'}`;
                document.getElementById('detail-modal-payment').innerText = s.payment_method;
                document.getElementById('detail-modal-sales-type').innerText = `Jenis: ${s.sales_type || 'RETAIL'}`;

                // Delivery Card
                const delivCard = document.getElementById('detail-modal-delivery-card');
                const delivRow = document.getElementById('detail-modal-delivery-row');
                const hasDelivery = (s.delivery_fee && Number(s.delivery_fee) > 0) || (s.delivery_status && s.delivery_status !== 'NONE') || s.driver_name || s.effective_driver_name;
                if (hasDelivery) {
                    delivCard.classList.remove('hidden');
                    delivRow.classList.remove('hidden');
                    const driverName = s.effective_driver_name || s.driver_name || '-';
                    const plate = s.plate_number ? `(${s.plate_number})` : '';
                    const isInc = (Number(s.is_delivery_included) === 1 || Number(s.delivery_fee) === 0);
                    const delivTitle = isInc ? 'Termasuk Biaya Kirim (Rp 0)' : formatRupiah(s.delivery_fee);
                    document.getElementById('detail-modal-delivery-desc').innerText = `Driver: ${driverName} ${plate} • Status: ${s.delivery_status || 'DELIVERED'}${isInc ? ' (Free Included)' : ''}`;
                    document.getElementById('detail-modal-delivery-fee').innerText = delivTitle;
                    document.getElementById('detail-modal-delivery-dist').innerText = `Jarak: ${s.delivery_distance_km || 0} km`;
                    document.getElementById('detail-modal-delivery-subtotal').innerText = formatRupiah(s.delivery_fee || 0);
                } else {
                    delivCard.classList.add('hidden');
                    delivRow.classList.add('hidden');
                }

                // Items list
                document.getElementById('detail-modal-items-count').innerText = `${items.length} Item Produk`;
                document.getElementById('detail-modal-items-body').innerHTML = items.map(it => {
                    const varBadge = it.variant_name ? `<span class="px-1.5 py-0.5 rounded text-[10px] bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 font-medium ml-1">${it.variant_name}</span>` : '';
                    const taxBadge = (it.is_taxable && it.is_taxable == 1) ? `<span class="px-1.5 py-0.2 rounded text-[9px] bg-amber-50 text-amber-700 border border-amber-200">PPN ${it.tax_percent || 11}%</span>` : `<span class="text-[10px] text-slate-400">Non-PPN</span>`;
                    return `
                        <tr class="hover:bg-slate-50">
                            <td class="py-2 px-3">
                                <div class="font-bold text-slate-800">${it.product_name}</div>
                                <div class="flex items-center space-x-1 mt-0.5">
                                    <span class="text-[10px] text-slate-400 font-mono">${it.sku || '-'}</span>
                                    ${varBadge}
                                </div>
                            </td>
                            <td class="py-2 px-2 text-center font-bold text-slate-700">${it.qty} ${it.unit || 'pcs'}</td>
                            <td class="py-2 px-2 text-right font-medium text-slate-600">${formatRupiah(it.unit_price)}</td>
                            <td class="py-2 px-2 text-right">${taxBadge}</td>
                            <td class="py-2 px-3 text-right font-bold text-slate-800">${formatRupiah(it.subtotal_price)}</td>
                        </tr>
                    `;
                }).join('');

                // Financial Summary
                document.getElementById('detail-modal-subtotal').innerText = formatRupiah(s.subtotal);
                document.getElementById('detail-modal-discount').innerText = s.discount > 0 ? `- ${formatRupiah(s.discount)}` : 'Rp 0';
                document.getElementById('detail-modal-tax').innerText = formatRupiah(s.tax || 0);
                document.getElementById('detail-modal-grand-total').innerText = formatRupiah(s.grand_total);
                document.getElementById('detail-modal-cash-info').innerText = `Diterima: ${formatRupiah(s.cash_received || s.grand_total)} • Kembalian: ${formatRupiah(s.cash_change || 0)}`;

                // Render BOM Ingredients Terpakai
                const bomCard = document.getElementById('detail-modal-bom-card');
                const bomBody = document.getElementById('detail-modal-bom-body');
                const bomCount = document.getElementById('detail-modal-bom-count');
                const materials = data.bom_materials || [];
                if (materials.length > 0) {
                    if (bomCard) bomCard.classList.remove('hidden');
                    if (bomCount) bomCount.innerText = `${materials.length} Bahan Baku Terpotong`;
                    if (bomBody) {
                        bomBody.innerHTML = materials.map(m => {
                            const isVar = (m.notes || '').includes('Varian');
                            const typeBadge = `<span class="px-1.5 py-0.5 rounded text-[9px] font-semibold ${isVar ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700'}">${isVar ? 'VARIANT' : 'BASE BOM'}</span>`;
                            const qty = Math.abs(Number(m.qty_change)) || 0;
                            return `
                                <tr class="hover:bg-amber-50/50">
                                    <td class="py-1.5 px-3">
                                        <div class="font-bold text-slate-800">${m.ingredient_name || '-'}</div>
                                        <div class="text-[10px] text-slate-400 font-mono">${m.ingredient_sku || '-'}</div>
                                    </td>
                                    <td class="py-1.5 px-2 text-center">${typeBadge}</td>
                                    <td class="py-1.5 px-2 text-right font-black text-amber-900">${qty.toLocaleString('id-ID')} ${m.unit || 'pcs'}</td>
                                    <td class="py-1.5 px-3 text-right font-semibold text-slate-700">${formatRupiah(m.total_cogs || 0)}</td>
                                </tr>
                            `;
                        }).join('');
                    }
                } else {
                    if (bomCard) bomCard.classList.add('hidden');
                }

                document.getElementById('sale-detail-modal').classList.remove('hidden');
                lucide.createIcons();
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan saat memuat data transaksi');
            }
        }

        function closeSaleDetailModal() {
            document.getElementById('sale-detail-modal').classList.add('hidden');
        }

        // ==========================================
        // MODUL LAPORAN PEMAKAIAN BAHAN BAKU (BOM)
        // ==========================================
        let currentBomUsageData = null;

        async function loadBomUsageReport() {
            updateStoreResetButtonsVisibility();
            let start = document.getElementById('bom-report-start-date').value;
            let end = document.getElementById('bom-report-end-date').value;
            if (!start || !end) {
                const today = new Date().toISOString().split('T')[0];
                start = today;
                end = today;
                document.getElementById('bom-report-start-date').value = start;
                document.getElementById('bom-report-end-date').value = end;
            }
            const matFilter = document.getElementById('bom-report-material-filter').value || 'ALL';
            const branchId = state.currentBranch ? state.currentBranch.id : '';

            try {
                const res = await fetch(`api.php?action=bom_usage_report&branch_id=${branchId}&start_date=${start}&end_date=${end}&ingredient_id=${encodeURIComponent(matFilter === 'ALL' ? '' : matFilter)}`);
                const data = await res.json();
                if (!data.success) {
                    alert(data.error || 'Gagal memuat laporan pemakaian bahan baku');
                    return;
                }

                currentBomUsageData = data;

                // Populate KPI Cards
                const kpi = data.kpi || {};
                const waterLiters = Number(kpi.total_water_liters) || 0;
                document.getElementById('bom-kpi-water-liters').innerText = `${waterLiters.toLocaleString('id-ID')} L`;
                document.getElementById('bom-kpi-water-sub').innerText = `Air Baku: ${waterLiters.toLocaleString('id-ID')} L`;
                document.getElementById('bom-kpi-caps-mineral').innerText = `${(Number(kpi.total_caps_mineral) || 0).toLocaleString('id-ID')} Pcs`;
                document.getElementById('bom-kpi-caps-ro').innerText = `${(Number(kpi.total_caps_ro) || 0).toLocaleString('id-ID')} Pcs`;
                document.getElementById('bom-kpi-tissues').innerText = `${(Number(kpi.total_tissues) || 0).toLocaleString('id-ID')} Pcs`;
                document.getElementById('bom-kpi-plastics').innerText = `${(Number(kpi.total_plastics) || 0).toLocaleString('id-ID')} Pcs`;
                document.getElementById('bom-kpi-total-cost').innerText = formatRupiah(kpi.total_bom_cogs || 0);

                // Populate Material Filter Dropdown if options not built yet
                const matSelect = document.getElementById('bom-report-material-filter');
                if (matSelect && matSelect.options.length <= 1 && data.materials) {
                    data.materials.forEach(m => {
                        const opt = document.createElement('option');
                        opt.value = m.product_id;
                        opt.textContent = m.name;
                        matSelect.appendChild(opt);
                    });
                }

                // Populate Table 1: Rekapitulasi Akumulasi Per Bahan Baku (data.materials)
                const summaryBody = document.getElementById('bom-summary-tbody');
                const summaryCountBadge = document.getElementById('bom-summary-count-badge');
                if (summaryCountBadge) summaryCountBadge.innerText = `${(data.materials || []).length} Bahan Baku Terdata`;

                if (!data.materials || data.materials.length === 0) {
                    summaryBody.innerHTML = `<tr><td colspan="7" class="text-center py-6 text-slate-400">Tidak ada pemakaian bahan baku pada periode tanggal ini.</td></tr>`;
                } else {
                    summaryBody.innerHTML = data.materials.map(m => {
                        let statusBadge = '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-800">AMAN</span>';
                        if (m.stock_status === 'HABIS') {
                            statusBadge = '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-rose-100 text-rose-800">HABIS (0)</span>';
                        } else if (m.stock_status === 'MENIPIS') {
                            statusBadge = '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-800">MENIPIS</span>';
                        }

                        return `
                            <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                <td class="py-2.5 px-3">
                                    <div class="font-bold text-slate-800 dark:text-slate-100">${m.name}</div>
                                    <div class="text-[10px] text-slate-400 font-mono">${m.sku || '-'}</div>
                                </td>
                                <td class="py-2.5 px-3 text-slate-600 font-medium">Bahan Baku / Raw</td>
                                <td class="py-2.5 px-3 text-right font-black text-amber-900 text-sm">${Number(m.total_qty_used).toLocaleString('id-ID')} <span class="text-xs font-normal text-slate-500">${m.unit}</span></td>
                                <td class="py-2.5 px-3 text-right font-medium text-slate-600">${formatRupiah(m.cogs)}</td>
                                <td class="py-2.5 px-3 text-right font-bold text-slate-800">${formatRupiah(m.total_cogs_used)}</td>
                                <td class="py-2.5 px-3 text-right font-bold ${Number(m.current_stock) <= 0 ? 'text-rose-600' : 'text-slate-800'}">${Number(m.current_stock).toLocaleString('id-ID')} ${m.unit}</td>
                                <td class="py-2.5 px-3 text-center">${statusBadge}</td>
                            </tr>
                        `;
                    }).join('');
                }

                // Populate Table 2: Rincian Log Transaksi Penjualan yang Memotong Bahan Baku (data.raw_logs)
                const logsBody = document.getElementById('bom-logs-tbody');
                const logsCountBadge = document.getElementById('bom-logs-count-badge');
                if (logsCountBadge) logsCountBadge.innerText = `${(data.raw_logs || []).length} Log Transaksi`;

                if (!data.raw_logs || data.raw_logs.length === 0) {
                    logsBody.innerHTML = `<tr><td colspan="8" class="text-center py-6 text-slate-400">Tidak ada transaksi penjualan produk ber-BOM pada periode ini.</td></tr>`;
                } else {
                    logsBody.innerHTML = data.raw_logs.map(log => {
                        const isVar = (log.notes || '').includes('Varian');
                        const typeBadge = `<span class="px-1.5 py-0.5 rounded text-[9px] font-semibold ${isVar ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700'}">${isVar ? 'VARIANT' : 'BASE BOM'}</span>`;
                        const qty = Math.abs(Number(log.qty_change)) || 0;
                        return `
                            <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                <td class="py-2.5 px-3 font-mono text-slate-500 text-[11px]">${log.created_at}</td>
                                <td class="py-2.5 px-3">
                                    <span class="font-mono font-bold text-indigo-600 hover:underline cursor-pointer" onclick="openSaleDetailModal('${log.reference_no}')">${log.reference_no}</span>
                                </td>
                                <td class="py-2.5 px-3">
                                    <span class="font-bold text-slate-800">${log.notes}</span>
                                </td>
                                <td class="py-2.5 px-3 text-center font-bold text-slate-700">-</td>
                                <td class="py-2.5 px-3">
                                    <div class="flex items-center space-x-1.5">
                                        <span class="font-bold text-slate-800">${log.ingredient_name}</span>
                                        ${typeBadge}
                                    </div>
                                    <div class="text-[10px] text-slate-400 font-mono">${log.ingredient_sku || '-'}</div>
                                </td>
                                <td class="py-2.5 px-3 text-right font-black text-amber-900">${qty.toLocaleString('id-ID')} <span class="text-xs font-normal text-slate-500">${log.unit}</span></td>
                                <td class="py-2.5 px-3 text-right font-medium text-slate-700">${formatRupiah(log.total_ingredient_cost)}</td>
                                <td class="py-2.5 px-3 text-center">
                                    <button onclick="openSaleDetailModal('${log.reference_no}')" class="px-2.5 py-1 bg-indigo-50 hover:bg-indigo-100 text-indigo-600 rounded-lg text-xs font-bold transition-all">
                                        Lihat Nota
                                    </button>
                                </td>
                            </tr>
                        `;
                    }).join('');
                }

                lucide.createIcons();
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan koneksi saat memuat laporan pemakaian bahan baku');
            }
        }

        function exportBomUsageExcel() {
            let start = document.getElementById('bom-report-start-date').value;
            let end = document.getElementById('bom-report-end-date').value;
            if (!start || !end) {
                const today = new Date().toISOString().split('T')[0];
                start = today;
                end = today;
            }
            const matFilter = document.getElementById('bom-report-material-filter').value || 'ALL';
            const branchId = state.currentBranch ? state.currentBranch.id : '';
            window.location.href = `api.php?action=export_bom_usage_excel&branch_id=${branchId}&start_date=${start}&end_date=${end}&material_id=${encodeURIComponent(matFilter)}`;
        }

        function exportSalesDetailExcel() {
            const start = document.getElementById('report-start-date').value;
            const end = document.getElementById('report-end-date').value;
            const method = document.getElementById('report-payment-filter').value;
            const branchId = state.currentBranch ? state.currentBranch.id : '';

            const url = `api.php?action=export_sales_excel&branch_id=${branchId}&start_date=${start}&end_date=${end}&payment_method=${method}`;
