        async function loadDeliveryReports() {
            const startInput = document.getElementById('deliv-report-start-date');
            const endInput = document.getElementById('deliv-report-end-date');
            const salesStart = document.getElementById('report-start-date');
            const salesEnd = document.getElementById('report-end-date');
            const today = new Date().toISOString().split('T')[0];

            if (startInput && !startInput.value) {
                startInput.value = (salesStart && salesStart.value) ? salesStart.value : today;
            }
            if (endInput && !endInput.value) {
                endInput.value = (salesEnd && salesEnd.value) ? salesEnd.value : today;
            }

            const start = startInput ? startInput.value : today;
            const end = endInput ? endInput.value : today;
            const typeEl = document.getElementById('deliv-report-type-filter');
            const driverEl = document.getElementById('deliv-report-driver-filter');
            const payEl = document.getElementById('deliv-report-payment-filter');

            const deliveryType = typeEl ? typeEl.value : 'ALL';
            const prevDriver = driverEl ? driverEl.value : 'ALL';
            const paymentMethod = payEl ? payEl.value : 'ALL';
            const branchId = state.currentBranch ? state.currentBranch.id : '';

            try {
                const url = `api.php?action=delivery_reports&branch_id=${branchId}&start_date=${encodeURIComponent(start)}&end_date=${encodeURIComponent(end)}&delivery_type=${encodeURIComponent(deliveryType)}&driver_filter=${encodeURIComponent(prevDriver)}&payment_method=${encodeURIComponent(paymentMethod)}`;
                const res = await fetch(url);
                const data = await res.json();
                if (!data.success) {
                    console.error('Gagal memuat laporan kiriman:', data.error || 'Unknown error');
                    return;
                }

                // Populate dropdown Kurir Pengantar
                if (driverEl) {
                    const driversList = Array.isArray(data.drivers_list) ? data.drivers_list : [];
                    let optsHtml = '<option value="ALL">Semua Kurir</option>';
                    driversList.forEach(function(dName) {
                        const safeVal = escapeHtml(dName);
                        const selAttr = (dName === prevDriver) ? ' selected' : '';
                        optsHtml += '<option value="' + safeVal + '"' + selAttr + '>' + safeVal + '</option>';
                    });
                    driverEl.innerHTML = optsHtml;
                }

                const kpi = data.kpi || {};
                const elOrders = document.getElementById('deliv-kpi-orders');
                if (elOrders) elOrders.innerText = (Number(kpi.total_delivery_orders) || 0) + ' Kiriman';
                const elFee = document.getElementById('deliv-kpi-fee');
                if (elFee) elFee.innerText = formatRupiah(kpi.total_delivery_fee || 0);
                const elSplit = document.getElementById('deliv-kpi-split');
                if (elSplit) elSplit.innerText = (Number(kpi.paid_delivery_orders) || 0) + ' / ' + (Number(kpi.free_delivery_orders) || 0);
                const elDist = document.getElementById('deliv-kpi-distance');
                if (elDist) elDist.innerText = formatDecimal(Number(kpi.total_distance_km) || 0) + ' km';
                const elGrand = document.getElementById('deliv-kpi-grand-total');
                if (elGrand) elGrand.innerText = formatRupiah(kpi.total_grand_amount || 0);
                const elGoodsSub = document.getElementById('deliv-kpi-goods-sub');
                if (elGoodsSub) elGoodsSub.innerText = 'Produk: ' + formatRupiah(kpi.total_goods_value || 0);

                // Tabel 1: Rekap per Kurir & Armada
                const couriers = Array.isArray(data.courier_summary) ? data.courier_summary : [];
                const cBadge = document.getElementById('deliv-courier-count-badge');
                if (cBadge) cBadge.innerText = couriers.length + ' Kurir';
                const cTbody = document.getElementById('deliv-courier-summary-tbody');
                if (cTbody) {
                    if (couriers.length === 0) {
                        cTbody.innerHTML = '<tr><td colspan="7" class="text-center py-6 text-slate-400">Belum ada data pengiriman kurir pada filter ini.</td></tr>';
                    } else {
                        cTbody.innerHTML = couriers.map(function(c) {
                            const cName = escapeHtml(c.courier_name || '-');
                            const plate = escapeHtml(c.plate_number || '-');
                            const veh = (c.vehicle_name && c.vehicle_name !== '-') ? (' <span class="text-[10px] text-slate-400">(' + escapeHtml(c.vehicle_name) + ')</span>') : '';
                            return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">' +
                                '<td class="py-2.5 px-3 font-bold text-slate-800">🚚 ' + cName + '</td>' +
                                '<td class="py-2.5 px-3 text-slate-600 font-medium">' + plate + veh + '</td>' +
                                '<td class="py-2.5 px-3 text-center"><span class="px-2.5 py-0.5 rounded-full text-[11px] font-extrabold bg-sky-100 text-sky-800">' + (Number(c.total_trips) || 0) + ' Nota</span></td>' +
                                '<td class="py-2.5 px-3 text-center font-semibold text-slate-600">' + (Number(c.paid_trips) || 0) + ' / ' + (Number(c.free_trips) || 0) + '</td>' +
                                '<td class="py-2.5 px-3 text-right font-semibold text-amber-700">' + formatDecimal(Number(c.total_distance_km) || 0) + ' km</td>' +
                                '<td class="py-2.5 px-3 text-right font-extrabold text-sky-700">' + formatRupiah(c.total_delivery_fee || 0) + '</td>' +
                                '<td class="py-2.5 px-3 text-right font-bold text-slate-800">' + formatRupiah(c.total_grand_amount || 0) + '</td>' +
                            '</tr>';
                        }).join('');
                    }
                }

                // Tabel 2: Daftar Rincian Faktur Kiriman
                const deliveries = Array.isArray(data.deliveries) ? data.deliveries : [];
                const oBadge = document.getElementById('deliv-orders-count-badge');
                if (oBadge) oBadge.innerText = deliveries.length + ' Faktur';
                const oTbody = document.getElementById('deliv-orders-tbody');
                if (oTbody) {
                    if (deliveries.length === 0) {
                        oTbody.innerHTML = '<tr><td colspan="10" class="text-center py-6 text-slate-400">Belum ada faktur kiriman pelanggan pada rentang tanggal ini.</td></tr>';
                    } else {
                        oTbody.innerHTML = deliveries.map(function(dv) {
                            const inv = escapeHtml(dv.invoice_number || '');
                            const cust = escapeHtml(dv.customer_name || 'Pelanggan Umum');
                            const addr = dv.customer_address ? ('<p class="text-[10px] text-slate-400 truncate max-w-[180px]" title="' + escapeHtml(dv.customer_address) + '">📍 ' + escapeHtml(dv.customer_address) + '</p>') : '';
                            const itemsSum = escapeHtml(dv.items_summary || '-');
                            const cName = escapeHtml(dv.courier_name || '-');
                            const plateTxt = (dv.plate_number && dv.plate_number !== '-') ? ('<p class="text-[10px] text-slate-400">' + escapeHtml(dv.plate_number) + '</p>') : '';
                            const feeNum = Number(dv.delivery_fee) || 0;
                            const feeBadge = feeNum > 0
                                ? '<span class="font-extrabold text-sky-700">' + formatRupiah(feeNum) + '</span>'
                                : '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800">🎁 Free / Include</span>';
                            const distNum = Number(dv.delivery_distance_km) || 0;
                            const distCell = distNum > 0 ? (formatDecimal(distNum) + ' km') : '-';
                            return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">' +
                                '<td class="py-2.5 px-3 font-mono font-bold">' +
                                    '<button type="button" onclick="openSaleDetailModal(\'' + inv + '\')" class="text-indigo-600 hover:text-indigo-800 hover:underline flex items-center space-x-1 font-bold text-left">' +
                                        '<span>' + inv + '</span>' +
                                        '<i data-lucide="external-link" class="w-3 h-3 text-indigo-400"></i>' +
                                    '</button>' +
                                '</td>' +
                                '<td class="py-2.5 px-3 text-slate-500 whitespace-nowrap">' + escapeHtml(dv.created_at || '') + '</td>' +
                                '<td class="py-2.5 px-3"><span class="font-semibold text-slate-800">' + cust + '</span>' + addr + '</td>' +
                                '<td class="py-2.5 px-3 text-slate-700 max-w-[240px]"><span class="line-clamp-2" title="' + itemsSum + '">' + itemsSum + '</span></td>' +
                                '<td class="py-2.5 px-3"><span class="font-bold text-slate-700">🚚 ' + cName + '</span>' + plateTxt + '</td>' +
                                '<td class="py-2.5 px-3 text-right text-slate-600 font-medium whitespace-nowrap">' + distCell + '</td>' +
                                '<td class="py-2.5 px-3 text-right whitespace-nowrap">' + feeBadge + '</td>' +
                                '<td class="py-2.5 px-3 text-right font-bold text-slate-800 whitespace-nowrap">' + formatRupiah(dv.grand_total || 0) + '</td>' +
                                '<td class="py-2.5 px-3 text-center"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-200 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-300 dark:border-slate-700">' + escapeHtml(dv.payment_method || '-') + '</span></td>' +
                                '<td class="py-2.5 px-3 text-center">' +
                                    '<button type="button" onclick="openSaleDetailModal(\'' + inv + '\')" class="p-1 px-2 text-[11px] bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-lg font-bold inline-flex items-center space-x-1">' +
                                        '<i data-lucide="eye" class="w-3 h-3"></i><span>Detail</span>' +
                                    '</button>' +
                                '</td>' +
                            '</tr>';
                        }).join('');
                    }
                }
                lucide.createIcons();
            } catch (err) {
                console.error('Error loading delivery reports:', err);
            }
        }

        function exportDeliveryReportExcel() {
            const startInput = document.getElementById('deliv-report-start-date');
            const endInput = document.getElementById('deliv-report-end-date');
            const today = new Date().toISOString().split('T')[0];
            const start = (startInput && startInput.value) ? startInput.value : today;
            const end = (endInput && endInput.value) ? endInput.value : today;
            const typeEl = document.getElementById('deliv-report-type-filter');
            const driverEl = document.getElementById('deliv-report-driver-filter');
            const payEl = document.getElementById('deliv-report-payment-filter');
            const deliveryType = typeEl ? typeEl.value : 'ALL';
            const driverFilter = driverEl ? driverEl.value : 'ALL';
            const paymentMethod = payEl ? payEl.value : 'ALL';
            const branchId = state.currentBranch ? state.currentBranch.id : '';

            const url = `api.php?action=export_delivery_excel&branch_id=${branchId}&start_date=${encodeURIComponent(start)}&end_date=${encodeURIComponent(end)}&delivery_type=${encodeURIComponent(deliveryType)}&driver_filter=${encodeURIComponent(driverFilter)}&payment_method=${encodeURIComponent(paymentMethod)}`;
            window.open(url, '_blank');
        }

        async function loadDiscountReports() {
            const startInput = document.getElementById('disc-report-start-date');
            const endInput = document.getElementById('disc-report-end-date');
            const salesStart = document.getElementById('report-start-date');
            const salesEnd = document.getElementById('report-end-date');
            const today = new Date().toISOString().split('T')[0];

            if (startInput && !startInput.value) {
                startInput.value = (salesStart && salesStart.value) ? salesStart.value : today;
            }
            if (endInput && !endInput.value) {
                endInput.value = (salesEnd && salesEnd.value) ? salesEnd.value : today;
            }

            const start = startInput ? startInput.value : today;
            const end = endInput ? endInput.value : today;
            const catEl = document.getElementById('disc-report-category-filter');
            const cshEl = document.getElementById('disc-report-cashier-filter');
            const payEl = document.getElementById('disc-report-payment-filter');

            const customerCategory = catEl ? catEl.value : 'ALL';
            const prevCashier = cshEl ? cshEl.value : 'ALL';
            const paymentMethod = payEl ? payEl.value : 'ALL';
            const branchId = state.currentBranch ? state.currentBranch.id : '';

            try {
                const ruleEl = document.getElementById('disc-report-rule-filter');
            const prevRule = ruleEl ? ruleEl.value : 'ALL';
            const url = `api.php?action=discount_reports&branch_id=${branchId}&start_date=${encodeURIComponent(start)}&end_date=${encodeURIComponent(end)}&customer_category=${encodeURIComponent(customerCategory)}&cashier_filter=${encodeURIComponent(prevCashier)}&payment_method=${encodeURIComponent(paymentMethod)}&rule_filter=${encodeURIComponent(prevRule)}`;
                const res = await fetch(url);
                const data = await res.json();
                if (!data.success) {
                    console.error('Gagal memuat laporan diskon:', data.error || 'Unknown error');
                    return;
                }

                // Populate dropdown Kasir Pemberi Diskon
                if (cshEl) {
                    const cashiersList = Array.isArray(data.cashiers_list) ? data.cashiers_list : [];
                    let optsHtml = '<option value="ALL">Semua Kasir</option>';
                    cashiersList.forEach(function(cName) {
                        const safeVal = escapeHtml(cName);
                        const selAttr = (cName === prevCashier) ? ' selected' : '';
                        optsHtml += '<option value="' + safeVal + '"' + selAttr + '>' + safeVal + '</option>';
                    });
                    cshEl.innerHTML = optsHtml;
                }

                // Populate dropdown Aturan Promo & Tabel Rekap Pemakaian Aturan Diskon
                const rulesList = Array.isArray(data.rules_summary) ? data.rules_summary : [];
                if (ruleEl) {
                    const prevRuleVal = prevRule || 'ALL';
                    let rOpts = '<option value="ALL">Semua Promo / Diskon</option><option value="MANUAL_ONLY"' + (prevRuleVal === 'MANUAL_ONLY' ? ' selected' : '') + '>Diskon Manual Kasir Saja</option>';
                    rulesList.forEach(function(r) {
                        if (r.rule_name && r.rule_name !== 'Diskon Manual Kasir') {
                            const rSafe = escapeHtml(r.rule_name);
                            const isSel = (prevRuleVal === r.rule_name) ? ' selected' : '';
                            rOpts += '<option value="' + rSafe + '"' + isSel + '>' + rSafe + ' (' + (r.trigger_mode || 'AUTO') + ')</option>';
                        }
                    });
                    ruleEl.innerHTML = rOpts;
                }

                const rulesBadge = document.getElementById('disc-rules-count-badge');
                if (rulesBadge) rulesBadge.innerText = rulesList.length + ' Promo';
                const rulesTbody = document.getElementById('disc-rules-summary-tbody');
                if (rulesTbody) {
                    if (rulesList.length === 0) {
                        rulesTbody.innerHTML = '<tr><td colspan="8" class="text-center py-6 text-slate-400">Tidak ada pemakaian aturan diskon pada filter ini.</td></tr>';
                    } else {
                        rulesTbody.innerHTML = rulesList.map(function(rs) {
                            const isAuto = (rs.trigger_mode === 'AUTO');
                            const modeBadge = isAuto ? '<span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-300">⚡ AUTO</span>' : '<span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-indigo-100 text-indigo-800 dark:bg-indigo-950 dark:text-indigo-300">🔘 MANUAL</span>';
                            return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">' +
                                '<td class="py-2.5 px-3 font-bold text-slate-800">' + escapeHtml(rs.rule_name || 'Diskon Manual Kasir') + '</td>' +
                                '<td class="py-2.5 px-3 text-center font-mono text-[11px] text-slate-500">' + escapeHtml(rs.rule_code || '-') + '</td>' +
                                '<td class="py-2.5 px-3 text-center">' + modeBadge + '</td>' +
                                '<td class="py-2.5 px-3 text-center font-extrabold text-rose-700">' + (Number(rs.discount_orders) || 0) + ' Nota</td>' +
                                '<td class="py-2.5 px-3 text-right text-slate-600">' + formatRupiah(rs.gross_subtotal || 0) + '</td>' +
                                '<td class="py-2.5 px-3 text-right font-black text-rose-600">- ' + formatRupiah(rs.total_discount || 0) + '</td>' +
                                '<td class="py-2.5 px-3 text-right font-bold text-indigo-900">' + formatRupiah(rs.net_sales || 0) + '</td>' +
                                '<td class="py-2.5 px-3 text-right font-bold text-emerald-700">' + formatRupiah(rs.gross_profit || 0) + '</td>' +
                            '</tr>';
                        }).join('');
                    }
                }

                const kpi = data.kpi || {};
                const totOrders = Number(kpi.total_discounted_orders) || 0;
                const storeTx = Number(kpi.period_total_orders) || 0;
                const ordRatio = Number(kpi.discounted_orders_ratio_percent) || 0;

                const elOrders = document.getElementById('disc-kpi-orders');
                if (elOrders) elOrders.innerText = totOrders + ' Nota';
                const elOrdersSub = document.getElementById('disc-kpi-orders-sub');
                if (elOrdersSub) elOrdersSub.innerText = storeTx > 0 ? (totOrders + ' dari ' + storeTx + ' Nota (' + formatDecimal(ordRatio, 1) + '%)') : '0% dari total transaksi';

                const elAmount = document.getElementById('disc-kpi-amount');
                if (elAmount) elAmount.innerText = formatRupiah(kpi.total_discount_amount || 0);
                const elRateSub = document.getElementById('disc-kpi-rate-sub');
                if (elRateSub) elRateSub.innerText = 'Rasio Omzet: ' + formatDecimal(Number(kpi.discount_pct_of_store_gross) || 0, 2) + '% (' + formatDecimal(Number(kpi.discount_pct_of_discounted_sales) || 0, 1) + '% nota diskon)';

                const elAvg = document.getElementById('disc-kpi-avg');
                if (elAvg) elAvg.innerText = formatRupiah(kpi.avg_discount_per_order || 0);
                const elMaxSub = document.getElementById('disc-kpi-max-sub');
                if (elMaxSub) elMaxSub.innerText = 'Diskon Maks: ' + formatRupiah(kpi.max_single_discount || 0);

                const elNet = document.getElementById('disc-kpi-net-sales');
                if (elNet) elNet.innerText = formatRupiah(kpi.discounted_net_sales || 0);
                const elGrossSub = document.getElementById('disc-kpi-gross-sub');
                if (elGrossSub) elGrossSub.innerText = 'Sebelum Diskon: ' + formatRupiah(kpi.discounted_gross_subtotal || 0);

                const elProfit = document.getElementById('disc-kpi-profit');
                if (elProfit) elProfit.innerText = formatRupiah(kpi.discounted_gross_profit || 0);
                const elMarginSub = document.getElementById('disc-kpi-margin-sub');
                if (elMarginSub) elMarginSub.innerText = 'Margin Pasca-Diskon: ' + formatDecimal(Number(kpi.discounted_margin_percent) || 0, 1) + '%';

                // Tabel 1: Rekap per Kasir
                const cashiers = Array.isArray(data.cashier_summary) ? data.cashier_summary : [];
                const cshBadge = document.getElementById('disc-cashier-count-badge');
                if (cshBadge) cshBadge.innerText = cashiers.length + ' Kasir';
                const cshTbody = document.getElementById('disc-cashier-summary-tbody');
                if (cshTbody) {
                    if (cashiers.length === 0) {
                        cshTbody.innerHTML = '<tr><td colspan="5" class="text-center py-6 text-slate-400">Tidak ada pemberian diskon kasir pada filter ini.</td></tr>';
                    } else {
                        cshTbody.innerHTML = cashiers.map(function(cs) {
                            const gSub = Number(cs.gross_subtotal) || 0;
                            const tDisc = Number(cs.total_discount) || 0;
                            const pct = gSub > 0 ? formatDecimal((tDisc / gSub) * 100, 1) : '0';
                            return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">' +
                                '<td class="py-2.5 px-3 font-bold text-slate-800">' + escapeHtml(cs.cashier_name || '-') + '</td>' +
                                '<td class="py-2.5 px-3 text-center"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-100 text-rose-800">' + (Number(cs.discount_orders) || 0) + 'x</span></td>' +
                                '<td class="py-2.5 px-3 text-right text-slate-600">' + formatRupiah(gSub) + '</td>' +
                                '<td class="py-2.5 px-3 text-right font-extrabold text-rose-600">- ' + formatRupiah(tDisc) + '<span class="block text-[10px] font-semibold text-rose-400">' + pct + '%</span></td>' +
                                '<td class="py-2.5 px-3 text-right font-bold text-emerald-700">' + formatRupiah(cs.gross_profit || 0) + '</td>' +
                            '</tr>';
                        }).join('');
                    }
                }

                // Tabel 2: Rekap per Pelanggan
                const customers = Array.isArray(data.customer_summary) ? data.customer_summary : [];
                const custBadge = document.getElementById('disc-customer-count-badge');
                if (custBadge) custBadge.innerText = customers.length + ' Pelanggan';
                const custTbody = document.getElementById('disc-customer-summary-tbody');
                if (custTbody) {
                    if (customers.length === 0) {
                        custTbody.innerHTML = '<tr><td colspan="5" class="text-center py-6 text-slate-400">Tidak ada penerima diskon pada filter ini.</td></tr>';
                    } else {
                        custTbody.innerHTML = customers.map(function(cu) {
                            const gSub = Number(cu.gross_subtotal) || 0;
                            const tDisc = Number(cu.total_discount) || 0;
                            return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">' +
                                '<td class="py-2.5 px-3 font-bold text-slate-800">' + escapeHtml(cu.customer_name || 'Pelanggan Umum') + '</td>' +
                                '<td class="py-2.5 px-3 text-center"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-50 text-indigo-700">' + escapeHtml(cu.customer_category || 'REGULER') + '</span></td>' +
                                '<td class="py-2.5 px-3 text-center font-semibold text-slate-700">' + (Number(cu.discount_orders) || 0) + 'x</td>' +
                                '<td class="py-2.5 px-3 text-right text-slate-600">' + formatRupiah(gSub) + '</td>' +
                                '<td class="py-2.5 px-3 text-right font-extrabold text-rose-600">- ' + formatRupiah(tDisc) + '</td>' +
                            '</tr>';
                        }).join('');
                    }
                }

                // Tabel 3: Daftar Rincian Faktur Berdiskon
                const discRows = Array.isArray(data.discounts) ? data.discounts : [];
                const ordBadge = document.getElementById('disc-orders-count-badge');
                if (ordBadge) ordBadge.innerText = discRows.length + ' Faktur';
                const ordTbody = document.getElementById('disc-orders-tbody');
                if (ordTbody) {
                    if (discRows.length === 0) {
                        ordTbody.innerHTML = '<tr><td colspan="11" class="text-center py-6 text-slate-400">Belum ada faktur berdiskon pada rentang tanggal ini.</td></tr>';
                    } else {
                        ordTbody.innerHTML = discRows.map(function(dr) {
                            const inv = escapeHtml(dr.invoice_number || '');
                            const cust = escapeHtml(dr.customer_name || 'Pelanggan Umum');
                            const cat = escapeHtml(dr.customer_category || 'REGULER');
                            const itemsSum = escapeHtml(dr.items_summary || '-');
                            const discNum = Number(dr.discount) || 0;
                            const discPct = formatDecimal(Number(dr.discount_percent) || 0, 1);
                            const gpNum = Number(dr.gross_profit) || 0;
                            const gpClass = gpNum < 0 ? 'text-rose-700' : 'text-emerald-700';
                            return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">' +
                                '<td class="py-2.5 px-3 font-mono font-bold">' +
                                    '<button type="button" onclick="openSaleDetailModal(\'' + inv + '\')" class="text-indigo-600 hover:text-indigo-800 hover:underline flex items-center space-x-1 font-bold text-left">' +
                                        '<span>' + inv + '</span>' +
                                        '<i data-lucide="external-link" class="w-3 h-3 text-indigo-400"></i>' +
                                    '</button>' +
                                '</td>' +
                                '<td class="py-2.5 px-3 text-slate-500 whitespace-nowrap">' + escapeHtml(dr.created_at || '') + '</td>' +
                                '<td class="py-2.5 px-3 text-slate-700 font-medium">' + escapeHtml(dr.cashier_name || '-') + '<p class="text-[10px] text-slate-400">' + escapeHtml(dr.branch_name || '') + '</p></td>' +
                                '<td class="py-2.5 px-3"><span class="font-semibold text-slate-800">' + cust + '</span> <span class="px-1.5 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 text-[10px] font-bold">' + cat + '</span></td>' +
                                '<td class="py-2.5 px-3 whitespace-nowrap"><span class="font-bold text-slate-800 block text-xs">' + escapeHtml(dr.discount_name || 'Diskon Manual Kasir') + '</span><span class="text-[10px] ' + (dr.discount_trigger_mode === 'AUTO' ? 'text-emerald-700 font-bold' : 'text-indigo-600 font-medium') + '">' + (dr.discount_trigger_mode === 'AUTO' ? '⚡ Otomatis (AUTO)' : '🔘 Manual Kasir') + '</span></td>' +
                                '<td class="py-2.5 px-3 text-slate-700 max-w-[240px]"><span class="line-clamp-2" title="' + itemsSum + '">' + itemsSum + '</span></td>' +
                                '<td class="py-2.5 px-3 text-right text-slate-600 whitespace-nowrap">' + formatRupiah(dr.subtotal || 0) + '</td>' +
                                '<td class="py-2.5 px-3 text-right whitespace-nowrap"><span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-rose-100 text-rose-700">🏷️ -' + formatRupiah(discNum) + ' (' + discPct + '%)</span></td>' +
                                '<td class="py-2.5 px-3 text-right font-bold text-slate-800 whitespace-nowrap">' + formatRupiah(dr.grand_total || 0) + '</td>' +
                                '<td class="py-2.5 px-3 text-right font-bold ' + gpClass + ' whitespace-nowrap">' + formatRupiah(gpNum) + '</td>' +
                                '<td class="py-2.5 px-3 text-center"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-200 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-300 dark:border-slate-700">' + escapeHtml(dr.payment_method || '-') + '</span></td>' +
                                '<td class="py-2.5 px-3 text-center">' +
                                    '<div class="flex items-center justify-center space-x-1">' +
                                        '<button type="button" onclick="openSaleDetailModal(\'' + inv + '\')" class="p-1 px-2 text-[11px] bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-lg font-bold inline-flex items-center space-x-1">' +
                                            '<i data-lucide="eye" class="w-3 h-3"></i><span>Detail</span>' +
                                        '</button>' +
                                        '<button type="button" onclick="exportSingleSaleExcel(\'' + inv + '\')" class="p-1 px-2 text-[11px] bg-emerald-50 hover:bg-emerald-100 text-emerald-700 rounded-lg font-bold inline-flex items-center space-x-1">' +
                                            '<i data-lucide="file-spreadsheet" class="w-3 h-3"></i><span>Excel</span>' +
                                        '</button>' +
                                    '</div>' +
                                '</td>' +
                            '</tr>';
                        }).join('');
                    }
                }
                lucide.createIcons();
            } catch (err) {
                console.error('Error loading discount reports:', err);
            }
        }

        function exportDiscountReportExcel() {
            const startInput = document.getElementById('disc-report-start-date');
            const endInput = document.getElementById('disc-report-end-date');
            const today = new Date().toISOString().split('T')[0];
            const start = (startInput && startInput.value) ? startInput.value : today;
            const end = (endInput && endInput.value) ? endInput.value : today;
            const catEl = document.getElementById('disc-report-category-filter');
            const cshEl = document.getElementById('disc-report-cashier-filter');
            const payEl = document.getElementById('disc-report-payment-filter');
            const customerCategory = catEl ? catEl.value : 'ALL';
            const cashierFilter = cshEl ? cshEl.value : 'ALL';
            const paymentMethod = payEl ? payEl.value : 'ALL';
            const branchId = state.currentBranch ? state.currentBranch.id : '';

            const ruleEl = document.getElementById('disc-report-rule-filter');
            const ruleFilter = ruleEl ? ruleEl.value : 'ALL';
            const url = `api.php?action=export_discount_excel&branch_id=${branchId}&start_date=${encodeURIComponent(start)}&end_date=${encodeURIComponent(end)}&customer_category=${encodeURIComponent(customerCategory)}&cashier_filter=${encodeURIComponent(cashierFilter)}&payment_method=${encodeURIComponent(paymentMethod)}&rule_filter=${encodeURIComponent(ruleFilter)}`;
            window.open(url, '_blank');
        }

        function exportSingleSaleExcel(invoiceNumber) {
            if (!invoiceNumber) return;
            const url = `api.php?action=export_sales_excel&invoice_number=${encodeURIComponent(invoiceNumber)}`;
            window.open(url, '_blank');
        }

        function exportDetailCurrentInvoice() {
            if (!currentDetailSaleData || !currentDetailSaleData.sale) return;
            exportSingleSaleExcel(currentDetailSaleData.sale.invoice_number);
        }

        function printFromDetailModal() {
            if (!currentDetailSaleData || !currentDetailSaleData.sale) return;
            const s = currentDetailSaleData.sale;
            const items = currentDetailSaleData.items || [];
            
            // Siapkan format untuk showReceiptModal
            const modalData = {
                ...s,
                items: items
            };
            showReceiptModal(modalData);
        }

        // ==========================================
        // 2b. MODUL LAPORAN MULTI-SHIFT, PENJUALAN & PIUTANG USAHA
        // ==========================================
        let currentDailyShiftReportData = null;

        function updateShiftReportSubtabVisibility() {
            updateStoreResetButtonsVisibility();
            const btnShifts = document.getElementById('report-subtab-btn-shifts');
            const curUser = state.currentUser || state.loggedInUser;
            const userRole = String((curUser ? curUser.role : '') || '').toUpperCase().replace(/[^A-Z]/g, '');
            const isManagerOrAdmin = ['SUPERADMIN', 'BRANCHMANAGER', 'MANAGER'].includes(userRole);

            if (!btnShifts) return;

            if (isManagerOrAdmin) {
                btnShifts.classList.remove('hidden');
                return;
            }

            // Untuk level selain Super Admin dan Branch Manager:
            // Sub menu baru muncul setelah proses closing shift setiap user atau saat toko sudah tutup (Closing Day)
            const hasClosed = (state.currentUserHasClosedShift === true) 
                           || (window.userHasClosedShift === true)
                           || (state.branchClosedToday === true)
                           || (state.finalClosedShift !== null);
            if (hasClosed) {
                btnShifts.classList.remove('hidden');
            } else {
                btnShifts.classList.add('hidden');
                if (state.reportActiveSubtab === 'shifts') {
                    setReportSubtab('sales');
                }
            }
        }

        function setReportSubtab(subtab) {
            const curUser = state.currentUser || state.loggedInUser;
            const userRole = String((curUser ? curUser.role : '') || '').toUpperCase().replace(/[^A-Z]/g, '');
            const isManagerOrAdmin = ['SUPERADMIN', 'BRANCHMANAGER', 'MANAGER'].includes(userRole);
            const hasClosed = (state.currentUserHasClosedShift === true) 
                           || (window.userHasClosedShift === true)
                           || (state.branchClosedToday === true)
                           || (state.finalClosedShift !== null);

            // Validasi: selain superadmin & branch manager tidak bisa masuk subtab shift sebelum closing
            if (subtab === 'shifts' && !isManagerOrAdmin && !hasClosed) {
                alert('Sub-menu Laporan Shift Kasir & Tutup Toko baru dapat diakses setelah Anda menyelesaikan proses tutup shift (Closing Shift).');
                subtab = 'sales';
            }

            state.reportActiveSubtab = subtab;
            const btnSales = document.getElementById('report-subtab-btn-sales');
            const btnDeliveries = document.getElementById('report-subtab-btn-deliveries');
            const btnDiscounts = document.getElementById('report-subtab-btn-discounts');
            const btnAR = document.getElementById('report-subtab-btn-receivables');
            const btnShifts = document.getElementById('report-subtab-btn-shifts');
            const btnBom = document.getElementById('report-subtab-btn-bom');

            const viewSales = document.getElementById('subtab-reports-sales');
            const viewDeliveries = document.getElementById('subtab-reports-deliveries');
            const viewDiscounts = document.getElementById('subtab-reports-discounts');
            const viewAR = document.getElementById('subtab-reports-ar');
            const viewShifts = document.getElementById('subtab-reports-shifts');
            const viewBOM = document.getElementById('subtab-reports-bom');

            // Reset buttons style
            const inactiveClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-slate-100 hover:bg-slate-200/80 text-slate-700 hover:text-slate-900 dark:bg-slate-800 dark:hover:bg-slate-700 dark:text-slate-300 dark:hover:text-white';
            const activeClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-indigo-600 text-white shadow-2xs';

            if (btnSales) btnSales.className = inactiveClass;
            if (btnDeliveries) btnDeliveries.className = inactiveClass;
            if (btnDiscounts) btnDiscounts.className = inactiveClass;
            if (btnAR) btnAR.className = inactiveClass;
            if (btnShifts) btnShifts.className = inactiveClass;
            if (btnBom) btnBom.className = inactiveClass;

            if (viewSales) viewSales.classList.add('hidden');
            if (viewDeliveries) viewDeliveries.classList.add('hidden');
            if (viewDiscounts) viewDiscounts.classList.add('hidden');
            if (viewAR) viewAR.classList.add('hidden');
            if (viewShifts) viewShifts.classList.add('hidden');
            if (viewBOM) viewBOM.classList.add('hidden');

            if (subtab === 'deliveries') {
                if (viewDeliveries) viewDeliveries.classList.remove('hidden');
                if (btnDeliveries) btnDeliveries.className = activeClass;
                const dStart = document.getElementById('deliv-report-start-date');
                const dEnd = document.getElementById('deliv-report-end-date');
                const sStart = document.getElementById('report-start-date');
                const sEnd = document.getElementById('report-end-date');
                if (dStart && !dStart.value && sStart && sStart.value) dStart.value = sStart.value;
                if (dEnd && !dEnd.value && sEnd && sEnd.value) dEnd.value = sEnd.value;
                loadDeliveryReports();
            } else if (subtab === 'discounts') {
                if (viewDiscounts) viewDiscounts.classList.remove('hidden');
                if (btnDiscounts) btnDiscounts.className = activeClass;
                const dcStart = document.getElementById('disc-report-start-date');
                const dcEnd = document.getElementById('disc-report-end-date');
                const sStart = document.getElementById('report-start-date');
                const sEnd = document.getElementById('report-end-date');
                if (dcStart && !dcStart.value && sStart && sStart.value) dcStart.value = sStart.value;
                if (dcEnd && !dcEnd.value && sEnd && sEnd.value) dcEnd.value = sEnd.value;
                loadDiscountReports();
            } else if (subtab === 'receivables') {
                if (viewAR) viewAR.classList.remove('hidden');
                if (btnAR) btnAR.className = activeClass;
                loadReceivablesReport();
            } else if (subtab === 'shifts') {
                if (viewShifts) viewShifts.classList.remove('hidden');
                if (btnShifts) btnShifts.className = activeClass;
                loadShiftReports();
            } else if (subtab === 'bom') {
                if (viewBOM) viewBOM.classList.remove('hidden');
                if (btnBom) btnBom.className = activeClass;
                loadBomUsageReport();
            } else {
                if (viewSales) viewSales.classList.remove('hidden');
                if (btnSales) btnSales.className = activeClass;
                loadSalesReports();
            }
            lucide.createIcons();
        }

        async function loadShiftReports() {
            const dateInput = document.getElementById('shift-report-date');
            if (dateInput && !dateInput.value) {
                const today = new Date().toISOString().split('T')[0];
                dateInput.value = today;
            }
            const date = dateInput ? dateInput.value : new Date().toISOString().split('T')[0];
            const branchId = state.currentBranch ? state.currentBranch.id : 1;
            const curUser = state.currentUser || state.loggedInUser;
            const uId = curUser ? curUser.id : 0;

            const branchLabel = document.getElementById('shift-report-branch-label');
            if (branchLabel) {
                branchLabel.innerText = (state.currentBranch ? state.currentBranch.name : 'Cabang') || 'Cabang Aktif';
            }

            const container = document.getElementById('shift-cards-container');
            if (container) {
                container.innerHTML = `
                    <div class="col-span-full py-12 text-center text-slate-400 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800">
                        <div class="w-6 h-6 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-2"></div>
                        <span class="text-xs font-bold">Memuat rincian laporan shift kasir (${date})...</span>
                    </div>
                `;
            }

            try {
                const res = await fetch(`api.php?action=get_shift_reports&branch_id=${branchId}&date=${date}&user_id=${uId}`);
                const data = await res.json();
                if (!data.success) {
                    if (data.can_view === false) {
                        state.currentUserHasClosedShift = false;
                        window.userHasClosedShift = false;
                        updateShiftReportSubtabVisibility();
                        alert(data.message || 'Laporan shift belum dapat diakses sebelum Anda menyelesaikan proses tutup shift.');
                        setReportSubtab('sales');
                        return;
                    }
                    if (container) container.innerHTML = `<div class="col-span-full p-6 text-center text-rose-600 bg-rose-50 rounded-2xl border border-rose-200 text-xs font-bold">${escapeHtml(data.message || 'Gagal memuat data shift')}</div>`;
                    return;
                }

                // Sukses memuat data laporan shift
                state.currentUserHasClosedShift = true;
                window.userHasClosedShift = true;
                updateShiftReportSubtabVisibility();

                currentDailyShiftReportData = data;
                renderDailyClosingSummary(data.daily_summary, data.report_date);
                renderShiftCards(data.shifts);
                renderFinalNightStocksTable(data.daily_summary.final_stocks, data.daily_summary.is_store_closed, data.daily_summary.final_cashier_name, data.daily_summary.final_closing_time);
            } catch (err) {
                console.error("Gagal load shift reports:", err);
                if (container) {
                    container.innerHTML = `<div class="col-span-full p-6 text-center text-rose-600 bg-rose-50 rounded-2xl border border-rose-200 text-xs font-bold">Terjadi kesalahan memuat data: ${escapeHtml(err.message)}</div>`;
                }
            }
        }

        function renderDailyClosingSummary(summary, reportDate) {
            if (!summary) return;
            const curUser = state.currentUser || state.loggedInUser;
            const userRole = String((curUser ? curUser.role : '') || '').toUpperCase().replace(/[^A-Z]/g, '');
            const isManagerOrAdmin = ['SUPERADMIN', 'BRANCHMANAGER', 'MANAGER'].includes(userRole);

            const titleEl = document.getElementById('daily-closing-summary-title');
            const kpiRevLabel = document.getElementById('daily-kpi-revenue-label');
            const sectionTitle = document.getElementById('shift-reports-section-title');

            if (titleEl) {
                if (!isManagerOrAdmin) {
                    titleEl.innerText = `Rekapitulasi Shift Saya (${(curUser ? curUser.name : '') || 'Kasir'})`;
                } else {
                    titleEl.innerText = 'Rekapitulasi Penutupan Toko Harian';
                }
            }

            if (kpiRevLabel) {
                if (!isManagerOrAdmin) {
                    kpiRevLabel.innerText = 'Total Omzet Shift Saya';
                } else {
                    kpiRevLabel.innerText = 'Total Omzet (Semua Shift)';
                }
            }

            if (sectionTitle) {
                if (!isManagerOrAdmin) {
                    sectionTitle.innerText = `Rincian Laporan Shift Saya (${(curUser ? curUser.name : '') || 'Kasir'}) [Data Terisolasi Akun]`;
                } else {
                    sectionTitle.innerText = 'Rincian Laporan Kasir Per-Shift (Data Terisolasi)';
                }
            }

            const badge = document.getElementById('daily-store-status-badge');
            const desc = document.getElementById('daily-store-desc');
            const countEl = document.getElementById('daily-total-shifts-count');

            if (badge) {
                if (summary.is_store_closed) {
                    badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black bg-rose-500/20 text-rose-300 border border-rose-500/30';
                    badge.innerText = 'TUTUP TOKO MALAM SELESAI 🔒';
                } else if (summary.total_shifts > 0) {
                    badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black bg-emerald-500/20 text-emerald-300 border border-emerald-500/30';
                    badge.innerText = 'TOKO AKTIF BEROPERASI 🟢';
                } else {
                    badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black bg-slate-500/20 text-slate-300 border border-slate-500/30';
                    badge.innerText = 'BELUM ADA SHIFT ⚪';
                }
            }

            if (desc) {
                if (summary.is_store_closed) {
                    desc.innerText = `Toko telah ditutup resmi pada ${summary.final_closing_time || '-'} oleh ${summary.final_cashier_name || 'Kasir Akhir'}. Sisa stok fisik malam terkunci.`;
                } else {
                    desc.innerText = `Konsolidasi seluruh transaksi shift & rekonsiliasi kas laci toko tanggal ${reportDate}.`;
                }
            }

            if (countEl) countEl.innerText = `${summary.total_shifts} Shift`;

            const revEl = document.getElementById('daily-kpi-total-revenue');
            if (revEl) revEl.innerText = formatRupiah(summary.total_revenue || 0);

            const cashEl = document.getElementById('daily-kpi-cash-sales');
            if (cashEl) cashEl.innerText = formatRupiah(summary.total_cash_sales || 0);

            const nonCashEl = document.getElementById('daily-kpi-noncash-sales');
            if (nonCashEl) nonCashEl.innerText = formatRupiah(summary.total_non_cash_sales || 0);

            const initEl = document.getElementById('daily-kpi-initial-cash');
            if (initEl) initEl.innerText = formatRupiah(summary.total_initial_cash || 0);

            const actEl = document.getElementById('daily-kpi-actual-cash');
            if (actEl) actEl.innerText = formatRupiah(summary.total_actual_cash || 0);

            const diffEl = document.getElementById('daily-kpi-cash-difference');
            if (diffEl) {
                const diff = summary.total_cash_difference || 0;
                diffEl.innerText = (diff >= 0 ? '+' : '') + formatRupiah(diff);
                if (diff < 0) diffEl.className = 'text-sm sm:text-base font-black text-rose-300 mt-1 block';
                else if (diff > 0) diffEl.className = 'text-sm sm:text-base font-black text-amber-300 mt-1 block';
                else diffEl.className = 'text-sm sm:text-base font-black text-emerald-300 mt-1 block';
            }
        }

        function renderShiftCards(shifts) {
            const container = document.getElementById('shift-cards-container');
            if (!container) return;

            if (!shifts || shifts.length === 0) {
                container.innerHTML = `
                    <div class="col-span-full py-12 text-center text-slate-400 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 space-y-2">
                        <span class="text-3xl block">🏪</span>
                        <div class="text-sm font-bold text-slate-700">Belum Ada Shift Kasir Buka/Tutup</div>
                        <p class="text-xs text-slate-400 max-w-md mx-auto">Tidak ada rekaman transaksi atau pembukaan laci kasir pada tanggal yang dipilih di cabang ini.</p>
                    </div>
                `;
                return;
            }

            container.innerHTML = shifts.map(s => {
                const isOpen = s.status === 'OPEN';
                const isFinal = Number(s.is_final_shift) === 1;
                const statusBadge = isOpen
                    ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-200">SEDANG BERJALAN 🟢</span>'
                    : '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 border border-slate-200">SELESAI DITUTUP 🔒</span>';

                const shiftTypeBadge = s.shift_number === 1
                    ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-indigo-50 text-indigo-700 border border-indigo-200">Shift 1 (Pagi) 🌅</span>'
                    : `<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-amber-50 text-amber-800 border border-amber-200">${escapeHtml(s.shift_name || ('Shift ' + s.shift_number + ' (Siang/Malam)'))} 🌤️</span>`;

                const finalBadge = isFinal && !isOpen
                    ? '<span class="px-2 py-0.5 rounded-full text-[9px] font-black bg-rose-50 text-rose-700 border border-rose-200">Tutup Toko Malam 🌙</span>'
                    : '';

                const diff = s.cash_difference || 0;
                let diffText = formatRupiah(diff);
                let diffBadgeClass = 'text-emerald-700 bg-emerald-50 border-emerald-200';
                if (diff < 0) {
                    diffBadgeClass = 'text-rose-700 bg-rose-50 border-rose-200';
                    diffText = `Defisit ${formatRupiah(Math.abs(diff))}`;
                } else if (diff > 0) {
                    diffBadgeClass = 'text-amber-700 bg-amber-50 border-amber-200';
                    diffText = `Surplus +${formatRupiah(diff)}`;
                } else {
                    diffText = 'Seimbang Rp 0 ✅';
                }

                // Cek apakah terdapat selisih stok pada shift ini
                const hasShiftStockDiff = (s.reconciled_items || []).some(it => it.has_difference);

                // Table Mini Rekonsiliasi & Audit Stok Produk Shift
                const itemsRows = (s.reconciled_items || []).map(item => {
                    const diffVal = Number(item.difference_qty) || 0;
                    let diffBadge = `<span class="font-mono text-slate-400">0</span>`;
                    if (s.status !== 'CLOSED') {
                        diffBadge = `<span class="text-slate-400 text-[10px]">-</span>`;
                    } else if (diffVal < 0) {
                        diffBadge = `<span class="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-black bg-rose-100 text-rose-700 font-mono">${formatDecimal(diffVal)}</span>`;
                    } else if (diffVal > 0) {
                        diffBadge = `<span class="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-black bg-sky-100 text-sky-700 font-mono">+${formatDecimal(diffVal)}</span>`;
                    }

                    const initQty = (item.initial_qty !== undefined && item.initial_qty !== null) ? Number(item.initial_qty) : Number(item.opening_qty || 0);
                    const openAddQty = (item.opening_added_qty !== undefined && item.opening_added_qty !== null) ? Number(item.opening_added_qty) : 0;
                    const extraAddQty = (item.extra_added_qty !== undefined && item.extra_added_qty !== null) ? Number(item.extra_added_qty) : 0;
                    const expectedQty = (item.expected_qty !== undefined && item.expected_qty !== null) ? Number(item.expected_qty) : Number(item.closing_qty || 0);
                    const soldAmount = (item.usage_qty !== undefined) ? item.usage_qty : item.sold_qty;

                    return `
                    <tr class="hover:bg-slate-50/50">
                        <td class="py-2 px-2.5 font-bold text-slate-800 flex items-center gap-1.5">
                            <span>${item.image_emoji || '📦'}</span>
                            <span class="truncate">${escapeHtml(item.name)}</span>
                        </td>
                        <td class="py-2 px-1.5 text-center font-mono text-slate-600">${formatDecimal(initQty)}</td>
                        <td class="py-2 px-1.5 text-center font-mono ${openAddQty > 0 ? 'font-bold text-emerald-700' : 'text-slate-400'}">${openAddQty > 0 ? '+' + formatDecimal(openAddQty) : '0'}</td>
                        <td class="py-2 px-1.5 text-center">
                            <span class="font-bold text-rose-700 block">${soldAmount > 0 ? '-' + formatDecimal(soldAmount) : '0'}</span>
                            ${item.breakdown_subtext ? `<span class="text-[9px] text-slate-400 block font-normal leading-tight mt-0.5">${escapeHtml(item.breakdown_subtext)}</span>` : ''}
                        </td>
                        <td class="py-2 px-1.5 text-center">
                            <span class="font-mono ${extraAddQty !== 0 ? 'font-bold text-sky-700' : 'text-slate-400'} block">${extraAddQty > 0 ? '+' + formatDecimal(extraAddQty) : formatDecimal(extraAddQty)}</span>
                            ${item.extra_subtext ? `<span class="text-[9px] text-emerald-600 block font-semibold leading-tight mt-0.5">${escapeHtml(item.extra_subtext)}</span>` : ''}
                        </td>
                        <td class="py-2 px-1.5 text-center font-mono font-bold text-slate-800 bg-slate-100/70">${formatDecimal(expectedQty)}</td>
                        <td class="py-2 px-1.5 text-center font-black text-indigo-950 bg-indigo-50/50">${formatDecimal(item.closing_qty)}</td>
                        <td class="py-2 px-1.5 text-center font-bold">${diffBadge}</td>
                    </tr>
                    `;
                }).join('');

                return `
                    <div class="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200/90 dark:border-slate-800 shadow-sm p-4 sm:p-5 space-y-4 hover:border-indigo-300 dark:hover:border-indigo-600 transition-all text-slate-800 dark:text-slate-100">
                        <!-- Header Kartu Shift -->
                        <div class="flex flex-wrap items-center justify-between gap-2 border-b border-slate-100 pb-3">
                            <div class="flex items-center space-x-2 flex-wrap gap-1">
                                <h3 class="font-black text-sm sm:text-base text-slate-900">${escapeHtml(s.shift_name)}</h3>
                                ${shiftTypeBadge}
                                ${finalBadge}
                            </div>
                            <div>
                                ${statusBadge}
                            </div>
                        </div>

                        <!-- Info Petugas Kasir & Waktu -->
                        <div class="bg-slate-50 dark:bg-slate-800/70 p-3 rounded-2xl border border-slate-100 dark:border-slate-700 flex flex-wrap items-center justify-between gap-3 text-xs">
                            <div>
                                <span class="text-[10px] text-slate-400 font-bold uppercase block">Kasir Bertugas</span>
                                <span class="font-black text-slate-800 dark:text-slate-100 text-sm flex items-center gap-1">
                                    👤 ${escapeHtml(s.cashier_name)} <span class="text-[10px] font-normal text-slate-400">(${escapeHtml(s.cashier_nik || 'KASIR')})</span>
                                </span>
                            </div>
                            <div class="text-right text-[11px] text-slate-500 dark:text-slate-400 font-medium">
                                <div>Mulai: <b>${s.start_time || '-'}</b></div>
                                <div>Selesai: <b>${s.end_time || (isOpen ? 'Shift Berjalan' : '-')}</b></div>
                            </div>
                        </div>

                        <!-- Rincian Finansial Shift (Isolasi Kasir) -->
                        <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs">
                            <div class="bg-indigo-50/50 dark:bg-indigo-950/40 p-2.5 rounded-xl border border-indigo-100/80 dark:border-indigo-800/60">
                                <span class="text-[9px] text-indigo-500 font-bold uppercase block">Modal Awal</span>
                                <span class="font-black text-indigo-950 dark:text-indigo-200 text-xs sm:text-sm mt-0.5 block">${formatRupiah(s.initial_cash)}</span>
                            </div>
                            <div class="bg-slate-50 dark:bg-slate-800/60 p-2.5 rounded-xl border border-slate-100 dark:border-slate-700">
                                <span class="text-[9px] text-slate-500 dark:text-slate-400 font-bold uppercase block">Penjualan Tunai</span>
                                <span class="font-black text-slate-900 dark:text-slate-100 text-xs sm:text-sm mt-0.5 block">${formatRupiah(s.cash_sales)}</span>
                            </div>
                            <div class="bg-slate-50 dark:bg-slate-800/60 p-2.5 rounded-xl border border-slate-100 dark:border-slate-700">
                                <span class="text-[9px] text-slate-500 dark:text-slate-400 font-bold uppercase block">Non-Tunai (QRIS/Trf)</span>
                                <span class="font-black text-slate-900 dark:text-slate-100 text-xs sm:text-sm mt-0.5 block">${formatRupiah(s.non_cash_sales)}</span>
                            </div>
                            <div class="bg-emerald-50/60 dark:bg-emerald-950/40 p-2.5 rounded-xl border border-emerald-100 dark:border-emerald-800/60">
                                <span class="text-[9px] text-emerald-700 dark:text-emerald-400 font-bold uppercase block">Total Omzet Shift</span>
                                <span class="font-black text-emerald-900 dark:text-emerald-300 text-xs sm:text-sm mt-0.5 block">${formatRupiah(s.total_sales)}</span>
                            </div>
                        </div>

                        <!-- Rekonsiliasi Kas Laci Kasir -->
                        <div class="p-3 bg-slate-50 dark:bg-slate-800/60 rounded-2xl border border-slate-200 dark:border-slate-700/70 space-y-2 text-xs">
                            <div class="flex items-center justify-between text-slate-600 dark:text-slate-300 font-medium">
                                <span>Kas Terhitung Sistem (Modal + Tunai - Pengeluaran):</span>
                                <span class="font-bold text-slate-900 dark:text-slate-100">${formatRupiah(s.expected_cash)}</span>
                            </div>
                            ${(s.total_disbursements > 0) ? `
                                <div class="p-2.5 bg-rose-50/70 rounded-xl border border-rose-200/80 space-y-1.5">
                                    <div class="flex items-center justify-between font-bold text-rose-900 text-[11px]">
                                        <span>💸 Pengeluaran Kasir (Petty Cash):</span>
                                        <span class="font-mono text-rose-800">- ${formatRupiah(s.total_disbursements)}</span>
                                    </div>
                                    <div class="grid grid-cols-3 gap-1 text-[10px] text-slate-600 pt-1 border-t border-rose-100">
                                        <div>Beban Toko: <b class="text-rose-700">${formatRupiah(s.total_expenses || 0)}</b></div>
                                        <div>Kasbon: <b class="text-amber-700">${formatRupiah(s.total_kasbon || 0)}</b></div>
                                        <div>Uang Makan: <b class="text-emerald-700">${formatRupiah(s.total_meal_allowance || 0)}</b></div>
                                    </div>
                                    ${(s.disbursements_detail && Array.isArray(s.disbursements_detail.expenses) && s.disbursements_detail.expenses.length > 0) ? `
                                        <div class="pt-1.5 border-t border-rose-100/90 space-y-1">
                                            <span class="text-[9px] font-bold text-slate-400 uppercase tracking-wider block">Rincian Beban Shift:</span>
                                            ${s.disbursements_detail.expenses.map(function(ex) {
                                                var vehBadge = '';
                                                if (ex.odometer !== undefined && ex.odometer !== null) {
                                                    var vLabel = ex.plate_number ? (ex.plate_number + ' • ') : '';
                                                    vehBadge = ' <span class="px-1.5 py-0.5 rounded text-[9px] font-bold bg-amber-100 text-amber-800 border border-amber-200">🛵 ' + escapeHtml(vLabel) + 'KM Odo: ' + formatDecimal(ex.odometer) + '</span>';
                                                }
                                                return '<div class="flex items-center justify-between text-[10px] text-slate-700 gap-1">' +
                                                    '<span class="truncate flex items-center gap-1"><span>• ' + escapeHtml(ex.category || ex.notes || 'Beban') + '</span>' + vehBadge + '</span>' +
                                                    '<span class="font-mono font-bold text-rose-700 shrink-0">' + formatRupiah(ex.amount) + '</span>' +
                                                '</div>';
                                            }).join('')}
                                        </div>
                                    ` : ''}
                                </div>
                            ` : ''}
                            <div class="flex items-center justify-between text-slate-600 dark:text-slate-300 font-medium">
                                <span>Kas Fisik Aktual Diserahkan:</span>
                                <span class="font-black text-slate-900 dark:text-slate-100 text-sm">${isOpen ? 'Menunggu Closing' : formatRupiah(s.actual_cash)}</span>
                            </div>
                            ${!isOpen ? `
                                <div class="flex items-center justify-between pt-1 border-t border-slate-200 dark:border-slate-700">
                                    <span class="font-bold text-slate-700 dark:text-slate-200">Hasil Audit Kas Laci:</span>
                                    <span class="px-2.5 py-1 rounded-lg text-xs font-black border ${diffBadgeClass}">${diffText}</span>
                                </div>
                            ` : ''}
                        </div>

                        <!-- Rincian Pemakaian & Audit Stok Produk Shift Ini -->
                        <div class="space-y-1.5">
                            <div class="flex flex-wrap items-center justify-between gap-1 text-[11px] font-bold text-slate-700">
                                <span class="flex items-center gap-1.5">
                                    <span>Rekonsiliasi Stok Shift Ini:</span>
                                    ${hasShiftStockDiff ? `<span class="px-1.5 py-0.5 bg-rose-100 text-rose-700 text-[9px] font-black rounded-md border border-rose-200">Ada Selisih</span>` : ''}
                                </span>
                                <span class="text-slate-400 font-normal text-[10px]">Stok Akhir = Awal + Opening - Penjualan + Tambahan</span>
                            </div>
                            ${hasShiftStockDiff ? `
                            <div class="p-2 bg-rose-50 border border-rose-200 rounded-xl text-[10px] font-bold text-rose-800 flex items-center gap-1.5">
                                <i data-lucide="alert-triangle" class="w-3.5 h-3.5 text-rose-600 shrink-0"></i>
                                <span>Perhatian: Ditemukan selisih fisik stok pada penutupan shift ini. Periksa kolom Selisih.</span>
                            </div>
                            ` : ''}
                            <div class="overflow-x-auto rounded-xl border border-slate-100">
                                <table class="w-full text-left text-[11px]">
                                    <thead class="bg-slate-50 dark:bg-slate-800/80 text-slate-500 dark:text-slate-400 font-bold border-b border-slate-200 dark:border-slate-700">
                                        <tr>
                                            <th class="py-1.5 px-2.5">Produk</th>
                                            <th class="py-1.5 px-1.5 text-center">Awal</th>
                                            <th class="py-1.5 px-1.5 text-center text-emerald-700">+Opening</th>
                                            <th class="py-1.5 px-1.5 text-center text-rose-700">-Penjualan</th>
                                            <th class="py-1.5 px-1.5 text-center text-sky-700">+Tambahan</th>
                                            <th class="py-1.5 px-1.5 text-center bg-slate-100 dark:bg-slate-800 dark:text-slate-300">Akhir Sistem</th>
                                            <th class="py-1.5 px-1.5 text-center text-indigo-800">Sisa Fisik</th>
                                            <th class="py-1.5 px-1.5 text-center text-rose-600">Selisih</th>
                                        </tr>
                                    </thead>
                                    <tbody class="divide-y divide-slate-100">
                                        ${itemsRows}
                                    </tbody>
                                </table>
                            </div>
                        </div>

                        ${s.water_meter_today !== null ? `
                            <!-- Rincian Meteran Air Display Counter -->
                            <div class="p-3 bg-sky-50/70 rounded-2xl border border-sky-200 text-xs space-y-2">
                                <div class="flex items-center justify-between">
                                    <span class="font-black text-sky-950 flex items-center gap-1.5">
                                        <span>💧</span> Meteran Air Mesin (Display Counter)
                                    </span>
                                    <span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-sky-600 text-white shadow-2xs font-mono">
                                        ${s.water_meter_dispensed_galon !== null ? s.water_meter_dispensed_galon.toLocaleString('id-ID', {minimumFractionDigits: 1, maximumFractionDigits: 2}) : '0'} Galon
                                    </span>
                                </div>
                                <div class="grid grid-cols-3 gap-2 text-center pt-1 border-t border-sky-100">
                                    <div class="bg-white/80 dark:bg-slate-800/80 p-1.5 rounded-xl border border-sky-100 dark:border-sky-900/40 text-slate-800 dark:text-slate-100">
                                        <span class="text-[9px] text-slate-400 font-bold block uppercase">Kemarin</span>
                                        <span class="font-mono font-bold text-slate-700 text-xs">${(s.water_meter_yesterday || 0).toLocaleString('id-ID')}</span>
                                    </div>
                                    <div class="bg-white/80 dark:bg-slate-800/80 p-1.5 rounded-xl border border-sky-100 dark:border-sky-900/40 text-slate-800 dark:text-slate-100">
                                        <span class="text-[9px] text-slate-400 font-bold block uppercase">Hari Ini</span>
                                        <span class="font-mono font-black text-sky-900 text-xs">${(s.water_meter_today || 0).toLocaleString('id-ID')}</span>
                                    </div>
                                    <div class="bg-sky-100/70 p-1.5 rounded-xl border border-sky-200">
                                        <span class="text-[9px] text-sky-800 font-bold block uppercase">Selisih Pulsa</span>
                                        <span class="font-mono font-black text-sky-950 text-xs">${(s.water_meter_difference || 0).toLocaleString('id-ID')}</span>
                                    </div>
                                </div>
                                ${s.water_meter_adjustment ? `
                                    <div class="text-[10px] text-sky-900 dark:text-sky-200 bg-white/70 dark:bg-slate-800/70 p-2 rounded-xl border border-sky-100 dark:border-sky-900/40 flex items-center justify-between">
                                        <span>Adjustment (${escapeHtml(s.water_meter_adjustment_type || 'PULSE')}): <b>${s.water_meter_adjustment > 0 ? '+' : ''}${s.water_meter_adjustment}</b></span>
                                        <span class="italic text-slate-500">${escapeHtml(s.water_meter_adjustment_reason || '-')}</span>
                                    </div>
                                ` : ''}
                            </div>
                        ` : ''}

                        <!-- Catatan Shift & Tombol Cetak -->
                        <div class="pt-2 border-t border-slate-100 flex flex-wrap items-center justify-between gap-2">
                            <div class="text-[11px] text-slate-500 italic truncate max-w-xs">
                                ${s.shift_notes ? `Catatan: "${escapeHtml(s.shift_notes)}"` : '<span class="text-slate-400">Tidak ada catatan shift</span>'}
                            </div>
                            <button onclick="printSingleShiftReceipt(${s.id})" class="px-3 py-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 text-xs font-bold rounded-xl border border-slate-200 transition-colors flex items-center space-x-1">
                                <i data-lucide="printer" class="w-3.5 h-3.5"></i>
                                <span>Cetak Struk Shift</span>
                            </button>
                        </div>
                    </div>
                `;
            }).join('');

            lucide.createIcons();
        }

        function renderFinalNightStocksTable(finalStocks, isClosed, cashierName, closingTime) {
            const tbody = document.getElementById('daily-final-stocks-tbody');
            const metaBadge = document.getElementById('final-stocks-meta-badge');
            if (!tbody) return;

            if (metaBadge) {
                if (isClosed) {
                    metaBadge.innerHTML = `Terkunci Tutup Toko • <b>${cashierName || 'Kasir'}</b> (${closingTime || '-'})`;
                    metaBadge.className = 'text-xs font-mono font-bold text-emerald-900 bg-emerald-50 px-3 py-1 rounded-xl border border-emerald-200';
                } else {
                    metaBadge.innerHTML = `Estimasi Realtime • Shift Masih Aktif`;
                    metaBadge.className = 'text-xs font-mono font-bold text-amber-900 bg-amber-50 px-3 py-1 rounded-xl border border-amber-200';
                }
            }

            if (!finalStocks || finalStocks.length === 0) {
                tbody.innerHTML = `
                    <tr>
                        <td colspan="10" class="py-8 text-center text-slate-400 text-xs">Belum ada data stok closing malam untuk tanggal ini.</td>
                    </tr>
                `;
                return;
            }

            tbody.innerHTML = finalStocks.map(item => {
                const initQty = (item.initial_qty !== undefined && item.initial_qty !== null) ? Number(item.initial_qty) : Number(item.opening_qty || 0);
                const openAddQty = (item.opening_added_qty !== undefined && item.opening_added_qty !== null) ? Number(item.opening_added_qty) : 0;
                const extraAddQty = (item.extra_added_qty !== undefined && item.extra_added_qty !== null) ? Number(item.extra_added_qty) : 0;
                const expectedQty = (item.expected_qty !== undefined && item.expected_qty !== null) ? Number(item.expected_qty) : Number(item.closing_qty || 0);
                const totalSold = (item.usage_qty !== undefined) ? item.usage_qty : (item.sold_qty || 0);
                const unitLabel = escapeHtml(item.unit || 'pcs');
                const diffVal = Number(item.difference_qty) || 0;
                let diffBadge = `<span class="font-mono text-slate-400">0</span>`;
                if (!isClosed) {
                    diffBadge = `<span class="text-slate-400 text-[10px]">-</span>`;
                } else if (diffVal < 0) {
                    diffBadge = `<span class="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-black bg-rose-100 text-rose-700 font-mono">${formatDecimal(diffVal)}</span>`;
                } else if (diffVal > 0) {
                    diffBadge = `<span class="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-black bg-sky-100 text-sky-700 font-mono">+${formatDecimal(diffVal)}</span>`;
                }

                return `
                    <tr class="hover:bg-slate-50/50">
                        <td class="py-3 px-4 font-bold text-slate-800 flex items-center gap-2">
                            <span class="text-base">${item.image_emoji || '📦'}</span>
                            <div>
                                <span class="block">${escapeHtml(item.name)}</span>
                                <span class="text-[10px] text-slate-400 font-normal">${unitLabel}</span>
                            </div>
                        </td>
                        <td class="py-3 px-3 font-mono text-slate-500 text-[11px]">${escapeHtml(item.sku)}</td>
                        <td class="py-3 px-3 text-center font-mono font-semibold text-slate-700">${formatDecimal(initQty)}</td>
                        <td class="py-3 px-3 text-center font-mono ${openAddQty > 0 ? 'font-bold text-emerald-700' : 'text-slate-400'}">${openAddQty > 0 ? '+' + formatDecimal(openAddQty) : '0'}</td>
                        <td class="py-3 px-3 text-center">
                            <span class="font-bold text-rose-700 block">${totalSold > 0 ? '-' + formatDecimal(totalSold) : '0'}</span>
                            ${item.breakdown_subtext ? `<span class="text-[10px] text-slate-400 block font-normal mt-0.5">${escapeHtml(item.breakdown_subtext)}</span>` : ''}
                        </td>
                        <td class="py-3 px-3 text-center">
                            <span class="font-mono ${extraAddQty !== 0 ? 'font-bold text-sky-700' : 'text-slate-400'} block">${extraAddQty > 0 ? '+' + formatDecimal(extraAddQty) : formatDecimal(extraAddQty)}</span>
                            ${item.extra_subtext ? `<span class="text-[10px] text-emerald-600 block font-semibold mt-0.5">${escapeHtml(item.extra_subtext)}</span>` : ''}
                        </td>
                        <td class="py-3 px-3 text-center font-mono font-bold text-slate-900 bg-slate-100/70">
                            ${formatDecimal(expectedQty)} <span class="text-[10px] text-slate-400 font-normal">${unitLabel}</span>
                        </td>
                        <td class="py-3 px-3 text-center font-black text-indigo-950 bg-indigo-50/40 text-sm">
                            ${formatDecimal(item.closing_qty)} <span class="text-[10px] text-slate-400 font-normal">${unitLabel}</span>
                        </td>
                        <td class="py-3 px-3 text-center font-bold">
                            ${diffBadge}
                        </td>
                        <td class="py-3 px-3 text-center">
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${isClosed ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'}">
                                ${isClosed ? 'Terkunci 🔒' : 'Berjalan 🟢'}
                            </span>
                        </td>
                    </tr>
                `;
            }).join('');
        }

        function printSingleShiftReceipt(shiftId) {
            if (!currentDailyShiftReportData || !currentDailyShiftReportData.shifts) return;
            const s = currentDailyShiftReportData.shifts.find(x => x.id === shiftId);
            if (!s) {
                alert('Data shift tidak ditemukan.');
                return;
            }

            const branchName = s.branch_name || ((state.currentBranch ? state.currentBranch.name : 'Cabang') || 'OUTLET');
            const diff = s.cash_difference || 0;
            const diffStr = (diff >= 0 ? '+' : '') + formatRupiah(diff);

            const itemsStr = (s.reconciled_items || []).map(it => {
                const diffVal = Number(it.difference_qty) || 0;
                const initVal = (it.initial_qty !== undefined && it.initial_qty !== null) ? Number(it.initial_qty) : Number(it.opening_qty || 0);
                const openAddVal = (it.opening_added_qty !== undefined && it.opening_added_qty !== null) ? Number(it.opening_added_qty) : 0;
                const extraVal = (it.extra_added_qty !== undefined && it.extra_added_qty !== null) ? Number(it.extra_added_qty) : 0;
                const expVal = (it.expected_qty !== undefined && it.expected_qty !== null) ? Number(it.expected_qty) : Number(it.closing_qty || 0);
                const itSold = it.usage_qty !== undefined ? it.usage_qty : it.sold_qty;
                const diffText = diffVal !== 0 ? ` | Selisih ${(diffVal > 0 ? '+' : '') + diffVal}` : ' | Selisih 0';
                const subtext = it.breakdown_subtext ? ` ${it.breakdown_subtext}` : '';
                return `  - ${it.name} (${it.sku}): Awal ${initVal} | +Open ${openAddVal} | -Jual ${itSold}${subtext} | +Tambah ${extraVal} => Sistem ${expVal} | Fisik ${it.closing_qty}${diffText} ${it.unit}`;
            }).join('\n');

            const content = 
`========================================
       STRUK LAPORAN SHIFT KASIR        
========================================
Cabang     : ${branchName}
Shift      : ${s.shift_name} (${s.shift_type || 'SHIFT'})
Kasir      : ${s.cashier_name} (${s.cashier_nik || 'KASIR'})
Status     : ${s.status === 'CLOSED' ? 'SELESAI DITUTUP' : 'AKTIF'}
Mulai      : ${s.start_time}
Selesai    : ${s.end_time || '-'}
----------------------------------------
RINCIAN KEUANGAN KASIR:
- Modal Awal Kasir    : ${formatRupiah(s.initial_cash)}
- Penjualan Tunai     : ${formatRupiah(s.cash_sales)}
- Penjualan Non-Tunai : ${formatRupiah(s.non_cash_sales)}
  * QRIS              : ${formatRupiah(s.qris_sales)}
  * Transfer Bank     : ${formatRupiah(s.transfer_sales)}
  * Piutang Pelanggan : ${formatRupiah(s.piutang_sales)}
- Total Omzet Shift   : ${formatRupiah(s.total_sales)}
- Total Transaksi     : ${s.tx_count} Struk
----------------------------------------
AUDIT KAS LACI KASIR:
- Kas Terhitung Sistem: ${formatRupiah(s.expected_cash)}
- Kas Fisik Diserahkan: ${formatRupiah(s.actual_cash)}
- Selisih Kas         : ${diffStr}
----------------------------------------
REKONSILIASI STOK SHIFT:
${itemsStr || '  (Tidak ada item terlacak)'}
----------------------------------------
Catatan: ${s.shift_notes || '-'}
========================================
Dicetak: ${new Date().toLocaleString('id-ID')}
TTD Kasir: __________________
`;

            const win = window.open('', '_blank', 'width=450,height=600');
            win.document.write('<pre style="font-family:monospace;font-size:12px;padding:20px;">' + content + '</pre>');
            win.document.close();
            win.focus();
            setTimeout(() => { win.print(); }, 250);
        }

        function printDailyClosingSummaryReceipt() {
            if (!currentDailyShiftReportData || !currentDailyShiftReportData.daily_summary) {
                alert('Silakan muat laporan terlebih dahulu.');
                return;
            }
            const data = currentDailyShiftReportData;
            const ds = data.daily_summary;
            const branchName = (state.currentBranch ? state.currentBranch.name : 'Cabang') || 'SEMUA CABANG';

            const shiftsStr = (data.shifts || []).map(s => 
                `[${s.shift_name}] ${s.cashier_name} | Omzet: ${formatRupiah(s.total_sales)} | Tunai: ${formatRupiah(s.cash_sales)} | Fisik: ${formatRupiah(s.actual_cash)}`
            ).join('\n');

            const stocksStr = (ds.final_stocks || []).map(st => {
                const diffVal = Number(st.difference_qty) || 0;
                const diffText = diffVal !== 0 ? ` | Selisih ${(diffVal > 0 ? '+' : '') + diffVal}` : '';
                return `  - ${st.name} (${st.sku}): Fisik ${st.closing_qty}${diffText} ${st.unit}`;
            }).join('\n');

            const content = 
`========================================
    REKAP TUTUP TOKO HARIAN (SUMMARY)   
========================================
Cabang     : ${branchName}
Tanggal    : ${data.report_date}
Status     : ${ds.is_store_closed ? 'TUTUP TOKO SELESAI (MALAM)' : 'TOKO BERJALAN'}
Shift Final: Ditutup oleh ${ds.final_cashier_name || '-'} (${ds.final_closing_time || '-'})
----------------------------------------
KONSOLIDASI FINANSIAL (${ds.total_shifts} Shift):
- Total Omzet Gabungan: ${formatRupiah(ds.total_revenue)}
- Total Tunai Toko    : ${formatRupiah(ds.total_cash_sales)}
- Total Non-Tunai     : ${formatRupiah(ds.total_non_cash_sales)}
  * QRIS              : ${formatRupiah(ds.total_qris_sales)}
  * Transfer Bank     : ${formatRupiah(ds.total_transfer_sales)}
  * Piutang Pelanggan : ${formatRupiah(ds.total_piutang_sales)}
- Total Modal Awal    : ${formatRupiah(ds.total_initial_cash)}
- Total Kas Keluar    : - ${formatRupiah(ds.total_disbursements || 0)}
  * Beban Toko        : ${formatRupiah(ds.total_expenses || 0)}
  * Kasbon Karyawan   : ${formatRupiah(ds.total_kasbon || 0)}
  * Uang Makan        : ${formatRupiah(ds.total_meal_allowance || 0)}
- Total Kas Diserahkan: ${formatRupiah(ds.total_actual_cash)}
- Total Selisih Kas   : ${(ds.total_cash_difference >= 0 ? '+' : '') + formatRupiah(ds.total_cash_difference)}
- Total Transaksi     : ${ds.total_transactions} Struk
----------------------------------------
RINCIAN PER SHIFT:
${shiftsStr || '  (Tidak ada shift)'}
----------------------------------------
STOK AKHIR MALAM (TERKUNCI):
${stocksStr || '  (Tidak ada item terlacak)'}
========================================
Dicetak: ${new Date().toLocaleString('id-ID')}
Manager / Supervisor: __________________
`;

            const win = window.open('', '_blank', 'width=480,height=650');
            win.document.write('<pre style="font-family:monospace;font-size:12px;padding:20px;">' + content + '</pre>');
            win.document.close();
            win.focus();
            setTimeout(() => { win.print(); }, 250);
        }

        async function loadReceivablesReport() {
            try {
                const statusEl = document.getElementById('ar-filter-status');
                const startEl = document.getElementById('ar-start-date');
                const endEl = document.getElementById('ar-end-date');
                const kwEl = document.getElementById('ar-search-keyword');

                const status = statusEl ? statusEl.value : 'ALL';
                const start = startEl ? startEl.value : '';
                const end = endEl ? endEl.value : '';
                const keyword = kwEl ? encodeURIComponent(kwEl.value.trim()) : '';
                const branchId = state.currentBranch ? state.currentBranch.id : '';

                const res = await fetch(`api.php?action=get_receivables&branch_id=${branchId}&status=${status}&start_date=${start}&end_date=${end}&keyword=${keyword}`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                // 1. Update KPI Cards
                const kpi = data.kpi || {};
                const totalReceivables = Number(kpi.total_receivables || 0);
                const totalPaid = Number(kpi.total_paid || 0);
                const totalOut = Number(kpi.total_outstanding || 0);
                const paidRate = totalReceivables > 0 ? Math.round((totalPaid / totalReceivables) * 100) : 0;

                const elKpiTotal = document.getElementById('ar-kpi-total');
                if (elKpiTotal) elKpiTotal.innerText = formatRupiah(totalReceivables);
                const elKpiCount = document.getElementById('ar-kpi-invoices-count');
                if (elKpiCount) elKpiCount.innerText = `${kpi.total_invoices || 0} Total Faktur`;

                const elKpiPaid = document.getElementById('ar-kpi-paid');
                if (elKpiPaid) elKpiPaid.innerText = formatRupiah(totalPaid);
                const elKpiPaidRate = document.getElementById('ar-kpi-paid-rate');
                if (elKpiPaidRate) elKpiPaidRate.innerText = `Tertagih: ${paidRate}%`;

                const elKpiOut = document.getElementById('ar-kpi-outstanding');
                if (elKpiOut) elKpiOut.innerText = formatRupiah(totalOut);

                const elKpiUnpaid = document.getElementById('ar-kpi-unpaid-count');
                if (elKpiUnpaid) elKpiUnpaid.innerText = `${kpi.count_unpaid || 0} Faktur`;

                const elKpiOverdue = document.getElementById('ar-kpi-overdue-count');
                if (elKpiOverdue) elKpiOverdue.innerText = `${kpi.count_overdue || 0} Faktur`;

                const countLabel = document.getElementById('ar-table-count-label');
                if (countLabel) countLabel.innerText = `Menampilkan ${(data.receivables || []).length} faktur`;

                // 2. Render Tabel Piutang Usaha
                const tbody = document.getElementById('receivables-table-body');
                if (!tbody) return;

                if (!data.receivables || data.receivables.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="9" class="py-8 text-center text-slate-400">Tidak ada faktur piutang yang cocok dengan filter.</td></tr>`;
                    return;
                }

                tbody.innerHTML = data.receivables.map(r => {
                    const total = Number(r.total_amount || 0);
                    const paid = Number(r.paid_amount || 0);
                    const remaining = Number(r.remaining_amount || 0);
                    const isOverdue = r.is_overdue == 1;
                    const aging = Number(r.aging_days || 0);

                    // Badge Kategori Pelanggan
                    const catBadge = (r.customer_category === 'MITRA')
                        ? '<span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-purple-100 text-purple-700">🤝 MITRA</span>'
                        : (r.customer_category === 'RESELLER'
                            ? '<span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-blue-100 text-blue-700">📦 RESELLER</span>'
                            : (r.customer_category === 'MEMBER'
                                ? '<span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-800">⭐ MEMBER</span>'
                                : '<span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700">RITEL</span>'));

                    // Badge Status Piutang
                    let statusBadge = '<span class="px-2.5 py-1 rounded-lg text-[10px] font-black bg-rose-100 text-rose-800 border border-rose-200">BELUM LUNAS</span>';
                    if (r.status === 'SEBAGIAN') {
                        statusBadge = '<span class="px-2.5 py-1 rounded-lg text-[10px] font-black bg-amber-100 text-amber-900 border border-amber-300">SEBAGIAN (CICILAN)</span>';
                    } else if (r.status === 'LUNAS') {
                        statusBadge = '<span class="px-2.5 py-1 rounded-lg text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-300">LUNAS PENUH</span>';
                    }

                    // Aging & Due Date Indicator
                    let agingHtml = `<span class="text-slate-600 font-medium">${r.due_date || '-'}</span>`;
                    if (r.status !== 'LUNAS') {
                        if (isOverdue) {
                            agingHtml += `<br><span class="inline-block mt-0.5 px-1.5 py-0.5 rounded text-[10px] font-bold bg-rose-100 text-rose-700 border border-rose-200">⚠️ LEWAT JATUH TEMPO (${aging} hr)</span>`;
                        } else {
                            agingHtml += `<br><span class="inline-block mt-0.5 px-1.5 py-0.5 rounded text-[10px] font-semibold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700">Umur Piutang: ${aging} hr</span>`;
                        }
                    } else {
                        agingHtml += `<br><span class="inline-block mt-0.5 px-1.5 py-0.5 rounded text-[10px] font-bold bg-emerald-50 text-emerald-700">Selesai Dibayar</span>`;
                    }

                    // Tombol Aksi
                    const payBtnDisabled = (r.status === 'LUNAS' || remaining <= 0);
                    const payBtnCls = payBtnDisabled
                        ? 'p-1 px-2.5 text-[11px] bg-slate-100 text-slate-400 rounded-lg font-bold cursor-not-allowed flex items-center space-x-1'
                        : 'p-1 px-2.5 text-[11px] bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg font-bold shadow-sm transition-colors flex items-center space-x-1';

                    return `
                        <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                            <td class="py-3 px-3 font-mono font-bold">
                                <button onclick="openReceivableDetailModal(${r.id})" class="text-indigo-600 hover:text-indigo-900 hover:underline flex items-center space-x-1 text-left" title="Lihat detail faktur piutang">
                                    <span>${r.invoice_number}</span>
                                    <i data-lucide="external-link" class="w-3 h-3 text-indigo-400"></i>
                                </button>
                                <span class="text-[10px] text-slate-400 font-sans block">${r.branch_name}</span>
                            </td>
                            <td class="py-3 px-3">
                                <div class="font-bold text-slate-800">${r.customer_name}</div>
                                <div class="mt-0.5 flex items-center gap-1.5">${catBadge} <span class="text-[10px] text-slate-400 font-mono">${r.customer_phone || '-'}</span></div>
                            </td>
                            <td class="py-3 px-3 text-slate-500 font-mono text-[11px]">${r.created_at ? r.created_at.substring(0, 10) : '-'}</td>
                            <td class="py-3 px-3 font-mono text-[11px]">${agingHtml}</td>
                            <td class="py-3 px-3 text-right font-bold text-slate-800 font-mono">${formatRupiah(total)}</td>
                            <td class="py-3 px-3 text-right font-bold text-emerald-700 font-mono">${formatRupiah(paid)}</td>
                            <td class="py-3 px-3 text-right font-black ${remaining > 0 ? 'text-amber-700' : 'text-slate-400'} font-mono">${formatRupiah(remaining)}</td>
                            <td class="py-3 px-3 text-center">${statusBadge}</td>
                            <td class="py-3 px-3 text-center">
                                <div class="flex items-center justify-center space-x-1.5">
                                    <button onclick="openReceivableDetailModal(${r.id})" class="p-1 px-2 text-[11px] bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-lg font-bold flex items-center space-x-1" title="Lihat Detail Transaksi">
                                        <i data-lucide="eye" class="w-3.5 h-3.5"></i>
                                        <span>Detail</span>
                                    </button>
                                    <button onclick="openPayReceivableModal(${r.id}, ${remaining}, '${r.invoice_number}')" ${payBtnDisabled ? 'disabled' : ''} class="${payBtnCls}" title="${payBtnDisabled ? 'Faktur sudah lunas' : 'Catat cicilan/pelunasan'}">
                                        <i data-lucide="wallet" class="w-3.5 h-3.5"></i>
                                        <span>Bayar</span>
                                    </button>
                                </div>
                            </td>
                        </tr>
                    `;
                }).join('');
                lucide.createIcons();
            } catch (err) {
                console.error("loadReceivablesReport error:", err);
            }
        }

        function resetReceivablesFilter() {
            const statusEl = document.getElementById('ar-filter-status');
            const startEl = document.getElementById('ar-start-date');
            const endEl = document.getElementById('ar-end-date');
            const kwEl = document.getElementById('ar-search-keyword');
            if (statusEl) statusEl.value = 'ALL';
            if (startEl) startEl.value = '';
            if (endEl) endEl.value = '';
            if (kwEl) kwEl.value = '';
            loadReceivablesReport();
        }

        let currentActiveReceivable = null;

        async function openReceivableDetailModal(receivableId) {
            try {
                const res = await fetch(`api.php?action=get_receivable_detail&id=${receivableId}`);
                const data = await res.json();
                if (!data.success) {
                    alert(data.message || 'Gagal memuat detail piutang');
                    return;
                }

                currentActiveReceivable = data;
                const rec = data.receivable;
                const items = data.items || [];
                const payments = data.payments || [];

                document.getElementById('rd-invoice-no').innerText = rec.invoice_number;
                document.getElementById('rd-customer-name').innerText = rec.customer_name;
                document.getElementById('rd-customer-cat').innerText = `KATEGORI: ${rec.customer_category} • TELP: ${rec.customer_phone || '-'}`;
                document.getElementById('rd-branch-name').innerText = `${rec.branch_name} (${rec.cashier_name || 'Kasir'})`;
                document.getElementById('rd-sale-date').innerText = `Tgl Transaksi: ${rec.created_at || '-'}`;
                document.getElementById('rd-due-date').innerText = rec.due_date || '-';

                const agingEl = document.getElementById('rd-aging-badge');
                if (rec.status === 'LUNAS') {
                    agingEl.innerText = 'LUNAS';
                    agingEl.className = 'inline-block mt-0.5 px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-800';
                } else if (rec.is_overdue == 1) {
                    agingEl.innerText = `⚠️ LEWAT TEMPO (${rec.aging_days} hari)`;
                    agingEl.className = 'inline-block mt-0.5 px-2 py-0.5 rounded text-[10px] font-bold bg-rose-100 text-rose-800';
                } else {
                    agingEl.innerText = `Umur Piutang: ${rec.aging_days || 0} hari`;
                    agingEl.className = 'inline-block mt-0.5 px-2 py-0.5 rounded text-[10px] font-bold bg-slate-200 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-300 dark:border-slate-700';
                }

                const statusEl = document.getElementById('rd-status-badge');
                if (rec.status === 'LUNAS') {
                    statusEl.innerText = 'LUNAS PENUH';
                    statusEl.className = 'inline-block mt-0.5 px-2.5 py-1 rounded-lg text-xs font-black bg-emerald-100 text-emerald-800';
                } else if (rec.status === 'SEBAGIAN') {
                    statusEl.innerText = 'SEBAGIAN (CICILAN)';
                    statusEl.className = 'inline-block mt-0.5 px-2.5 py-1 rounded-lg text-xs font-black bg-amber-100 text-amber-900';
                } else {
                    statusEl.innerText = 'BELUM LUNAS';
                    statusEl.className = 'inline-block mt-0.5 px-2.5 py-1 rounded-lg text-xs font-black bg-rose-100 text-rose-800';
                }

                document.getElementById('rd-total-amount').innerText = formatRupiah(rec.total_amount);
                document.getElementById('rd-paid-amount').innerText = formatRupiah(rec.paid_amount);
                document.getElementById('rd-remaining-amount').innerText = formatRupiah(rec.remaining_amount);

                // Items list
                document.getElementById('rd-items-body').innerHTML = items.map(it => `
                    <tr>
                        <td class="py-2 px-3 font-semibold text-slate-800">${it.product_name}</td>
                        <td class="py-2 px-3 text-center font-bold text-slate-700">${it.qty}</td>
                        <td class="py-2 px-3 text-right font-mono text-slate-600">${formatRupiah(it.unit_price)}</td>
                        <td class="py-2 px-3 text-right font-mono font-bold text-slate-800">${formatRupiah(it.subtotal_price)}</td>
                    </tr>
                `).join('') || `<tr><td colspan="4" class="text-center py-3 text-slate-400">Tidak ada item tercatat</td></tr>`;

                // Payments list
                document.getElementById('rd-payments-count').innerText = `${payments.length} Kali Pembayaran`;
                document.getElementById('rd-payments-body').innerHTML = payments.map(p => `
                    <tr>
                        <td class="py-2 px-3 font-mono text-slate-700">${p.payment_date}</td>
                        <td class="py-2 px-3"><span class="px-2 py-0.5 rounded text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">${p.payment_method}</span></td>
                        <td class="py-2 px-3 text-slate-600 font-mono text-[11px]">${p.reference_no || '-'} <span class="text-slate-400">(${p.cashier_name || 'Kasir'})</span></td>
                        <td class="py-2 px-3 text-slate-500 italic text-[11px]">${p.notes || '-'}</td>
                        <td class="py-2 px-3 text-right font-mono font-bold text-emerald-700">${formatRupiah(p.amount)}</td>
                    </tr>
                `).join('') || `<tr><td colspan="5" class="text-center py-4 text-slate-400">Belum ada catatan pembayaran cicilan</td></tr>`;

                const notesEl = document.getElementById('rd-notes-text');
                if (notesEl) notesEl.innerText = rec.notes ? `Catatan Faktur: ${rec.notes}` : '';

                const actionPayBtn = document.getElementById('rd-btn-action-pay');
                if (actionPayBtn) {
                    if (rec.status === 'LUNAS' || Number(rec.remaining_amount) <= 0) {
                        actionPayBtn.classList.add('hidden');
                    } else {
                        actionPayBtn.classList.remove('hidden');
                        actionPayBtn.onclick = () => {
                            closeReceivableDetailModal();
                            openPayReceivableModal(rec.id, rec.remaining_amount, rec.invoice_number);
                        };
                    }
                }

                document.getElementById('receivable-detail-modal').classList.remove('hidden');
                lucide.createIcons();
            } catch (err) {
                console.error("openReceivableDetailModal error:", err);
            }
        }

        function closeReceivableDetailModal() {
            const modal = document.getElementById('receivable-detail-modal');
            if (modal) modal.classList.add('hidden');
        }

        let currentPayMaxRemaining = 0;

        function openPayReceivableModal(receivableId, remainingAmount, invoiceNumber) {
            currentPayMaxRemaining = Number(remainingAmount || 0);
            document.getElementById('pay-modal-receivable-id').value = receivableId;
            document.getElementById('pay-modal-invoice-no').innerText = invoiceNumber;
            document.getElementById('pay-modal-remaining-display').innerText = formatRupiah(currentPayMaxRemaining);
            document.getElementById('pay-modal-date').value = new Date().toISOString().split('T')[0];
            document.getElementById('pay-modal-amount').value = currentPayMaxRemaining;
            document.getElementById('pay-modal-method').value = 'CASH';
            document.getElementById('pay-modal-ref').value = '';
            document.getElementById('pay-modal-notes').value = '';

            document.getElementById('receivable-pay-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function closePayReceivableModal() {
            const modal = document.getElementById('receivable-pay-modal');
            if (modal) modal.classList.add('hidden');
        }

        function setPayAmountFull() {
            document.getElementById('pay-modal-amount').value = currentPayMaxRemaining;
        }

        async function submitPayReceivableForm(e) {
            e.preventDefault();
            const receivableId = parseInt(document.getElementById('pay-modal-receivable-id').value);
            const amount = parseFloat(document.getElementById('pay-modal-amount').value) || 0;
            const paymentDate = document.getElementById('pay-modal-date').value;
            const paymentMethod = document.getElementById('pay-modal-method').value;
            const ref = document.getElementById('pay-modal-ref').value.trim();
            const notes = document.getElementById('pay-modal-notes').value.trim();
            const cashierId = state.currentUser ? state.currentUser.id : 3;

            if (amount <= 0) {
                alert('Nominal pembayaran wajib lebih dari Rp 0');
                return;
            }
            if (amount > currentPayMaxRemaining) {
                alert(`Nominal pembayaran (${formatRupiah(amount)}) tidak boleh melebihi sisa tagihan (${formatRupiah(currentPayMaxRemaining)})`);
                return;
            }

            const submitBtn = document.getElementById('pay-modal-submit-btn');
            submitBtn.disabled = true;
            submitBtn.innerText = 'Memproses...';

            try {
                const res = await fetch('api.php?action=pay_receivable', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        receivable_id: receivableId,
                        amount: amount,
                        payment_date: paymentDate,
                        payment_method: paymentMethod,
                        reference_no: ref,
                        notes: notes,
                        cashier_user_id: cashierId
                    })
                });
                const data = await res.json();
                submitBtn.disabled = false;
                submitBtn.innerHTML = `<i data-lucide="check-circle" class="w-4 h-4"></i><span>Konfirmasi Bayar</span>`;

                if (data.success) {
                    alert(data.message);
                    closePayReceivableModal();
                    await loadReceivablesReport();
                    if (state.currentTab === 'pnl') await loadProfitLoss();
                } else {
                    alert('Gagal: ' + (data.message || data.error));
                }
            } catch (err) {
                submitBtn.disabled = false;
                submitBtn.innerHTML = `<i data-lucide="check-circle" class="w-4 h-4"></i><span>Konfirmasi Bayar</span>`;
                alert('Terjadi kesalahan jaringan.');
            }
        }

        // ==========================================
        // 3. EMPLOYEE SELF SERVICE (ESS)
        // ==========================================
        function isManagerOrSuperAdminUser(user) {
            const u = user || state.currentUser || state.loggedInUser;
            if (!u || !u.role) return false;
            const r = String(u.role).toUpperCase().trim();
            return ['SUPER_ADMIN', 'SUPERADMIN', 'BRANCH_MANAGER', 'MANAGER'].includes(r);
        }

        function populateReimburseCategoryDropdown(categories) {
            const select = document.getElementById('reimburse-category');
            if (!select) return;
            const currentVal = select.value;
            const cats = (categories && categories.length > 0) ? categories : (state.expenseCategories || []);
            const activeCats = cats.filter(c => c.is_active == 1);
            if (activeCats.length === 0) return;

            select.innerHTML = activeCats.map(c => `
                <option value="${escapeHtml(c.name)}">${escapeHtml(c.name)}</option>
            `).join('');

            if (currentVal && activeCats.some(c => c.name === currentVal)) {
                select.value = currentVal;
            }
        }

        async function loadEssData() {
            const curUser = state.currentUser || state.loggedInUser || { id: 3, role: 'CASHIER' };
            const uId = curUser.id || 3;
            const bId = state.currentBranch ? state.currentBranch.id : 1;
            const isManager = isManagerOrSuperAdminUser(curUser);

