            document.getElementById('ess-commission-amount').innerText = formatRupiah(data.commission.commission_earned);
            document.getElementById('ess-commission-details').innerText = `Rate: ${data.commission.rate_percent}% • Total Omzet: ${formatRupiah(data.commission.total_omzet)}`;

            const todayStatusEl = document.getElementById('ess-today-status');
            const todayTimeEl = document.getElementById('ess-today-time');
            if (data.today_attendance) {
                todayStatusEl.innerText = data.today_attendance.clock_out ? 'SELESAI (CLOCK-OUT)' : 'SUDAH CLOCK-IN';
                todayStatusEl.className = 'px-2 py-0.5 bg-emerald-200 text-emerald-900 rounded-md font-bold';
                todayTimeEl.innerText = `Masuk: ${data.today_attendance.clock_in} ${data.today_attendance.clock_out ? '• Pulang: ' + data.today_attendance.clock_out : ''}`;
            } else {
                todayStatusEl.innerText = 'BELUM CLOCK-IN';
                todayStatusEl.className = 'px-2 py-0.5 bg-rose-200 text-rose-900 rounded-md font-bold';
                todayTimeEl.innerText = 'Silakan periksa GPS dan tekan tombol Clock-In di atas.';
            }

            document.getElementById('ess-attendance-history').innerHTML = data.attendance_history.map(ah => `
                <div class="flex justify-between items-center p-2.5 bg-slate-50 dark:bg-slate-800/60 rounded-xl border border-slate-100 dark:border-slate-700">
                    <div>
                        <span class="font-bold text-slate-700">${ah.clock_in}</span>
                        <span class="text-[10px] text-slate-400 block">${ah.branch_name} (${ah.distance_meters}m)</span>
                    </div>
                    <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${ah.status === 'ON_TIME' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}">${ah.status}</span>
                </div>
            `).join('') || `<p class="text-slate-400">Belum ada riwayat</p>`;

            const titleEl = document.getElementById('ess-reimburse-table-title');
            if (titleEl) {
                titleEl.innerText = isManager ? 'Daftar Klaim Toko & Aksi Pencairan (Manager / Finance):' : 'Riwayat Pengajuan Klaim Reimbursement Saya:';
            }

            const btnClearAll = document.getElementById('btn-clear-all-reimburse');
            if (btnClearAll) {
                if (isManager && data.branch_reimbursements && data.branch_reimbursements.length > 0) {
                    btnClearAll.classList.remove('hidden');
                } else {
                    btnClearAll.classList.add('hidden');
                }
            }

            document.getElementById('ess-reimburse-table-body').innerHTML = data.branch_reimbursements.map(r => `
                <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors">
                    <td class="py-2.5 px-2.5 font-semibold text-slate-800 dark:text-slate-200">${r.employee_name}</td>
                    <td class="py-2.5 px-2.5 text-slate-600 dark:text-slate-300">${r.category}<br><span class="text-[10px] text-slate-400">${r.description}</span></td>
                    <td class="py-2.5 px-2.5 text-right font-bold text-slate-800 dark:text-white">${formatRupiah(r.amount)}</td>
                    <td class="py-2.5 px-2.5"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${r.status === 'DISBURSED' ? 'bg-emerald-100 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300' : (r.status === 'REJECTED' ? 'bg-rose-100 dark:bg-rose-950/60 text-rose-800 dark:text-rose-300' : 'bg-amber-100 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300')}">${r.status}</span></td>
                    <td class="py-2.5 px-2.5 text-center">
                        <div class="flex items-center justify-center space-x-1.5">
