                                isManager ? `
                                    <button onclick="disburseReimbursement(${r.id})" class="px-2 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold shadow-sm whitespace-nowrap">Cairkan & Catat</button>
                                ` : `<span class="px-2 py-0.5 bg-amber-100 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300 rounded-full text-[10px] font-semibold whitespace-nowrap">⏳ Menunggu</span>`
                            ) : `<span class="text-emerald-700 dark:text-emerald-400 font-bold text-[10px] whitespace-nowrap">✓ Dicairkan</span>`}
                            ${(isManager || r.status !== 'DISBURSED') ? `
                                <button onclick="deleteReimbursement(${r.id})" title="Hapus Data Reimbursement" class="p-1 text-slate-400 hover:text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-950/40 rounded-lg transition-colors">
                                    <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                                </button>
                            ` : ''}
                        </div>
                    </td>
                </tr>
            `).join('') || `<tr><td colspan="5" class="text-center py-4 text-slate-400">Belum ada klaim reimbursement</td></tr>`;
            lucide.createIcons();

            // Otomatis deteksi GPS perangkat saat modul presensi dibuka
            refreshDeviceGps(false);
        }

        // ==========================================
        // SENSOR GPS RIIL & GEOFENCING PRESENSI TOKO
        // ==========================================
        function getDeviceGpsPosition(options) {
            return new Promise(function(resolve, reject) {
                if (!navigator || !navigator.geolocation) {
                    reject({
                        code: 0,
                        message: 'Peramban ini tidak mendukung sensor GPS Geolocation.'
                    });
                    return;
                }

                var geoOptions = options || {
                    enableHighAccuracy: true,
                    timeout: 15000,
                    maximumAge: 0
                };

                navigator.geolocation.getCurrentPosition(
                    function(pos) {
                        resolve({
                            latitude: pos.coords.latitude,
                            longitude: pos.coords.longitude,
                            accuracy: pos.coords.accuracy,
                            timestamp: pos.timestamp
                        });
                    },
                    function(err) {
                        var userMessage = 'Gagal membaca sensor GPS.';
                        if (err.code === 1) { // PERMISSION_DENIED
                            userMessage = 'Izin Akses Lokasi Ditolak di peramban! Mohon izinkan akses lokasi (Location Permission) di setelan browser untuk presensi.';
                        } else if (err.code === 2) { // POSITION_UNAVAILABLE
                            userMessage = 'GPS HP / Tablet Belum Aktif (Location Services OFF)! Mohon aktifkan sakelar GPS/Lokasi di panel notifikasi atau setelan HP/Tablet Anda.';
                        } else if (err.code === 3) { // TIMEOUT
                            userMessage = 'Waktu pencarian sinyal GPS habis (Timeout). Pastikan Anda berada di area terbuka agar sinyal satelit GPS HP terkunci.';
                        } else if (err.message) {
                            userMessage = err.message;
                        }
                        reject({
                            code: err.code,
                            message: userMessage,
                            original: err
                        });
                    },
                    geoOptions
                );
            });
        }

        function calculateHaversineMeters(lat1, lon1, lat2, lon2) {
            var R = 6371000; // Radius Bumi dalam meter
            var dLat = (lat2 - lat1) * Math.PI / 180;
            var dLon = (lon2 - lon1) * Math.PI / 180;
            var a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
                    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
                    Math.sin(dLon / 2) * Math.sin(dLon / 2);
            var c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
            return R * c;
        }

        async function refreshDeviceGps(showAlert) {
            var statusBadge = document.getElementById('ess-gps-status-badge');
            var coordsEl = document.getElementById('ess-device-coords');
            var accEl = document.getElementById('ess-device-accuracy');
            var distEl = document.getElementById('ess-geo-distance');
            var alertBox = document.getElementById('ess-gps-alert-box');

            if (statusBadge) {
                statusBadge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800 animate-pulse';
                statusBadge.innerHTML = '🟡 Mencari Sinyal GPS...';
            }
            if (distEl) {
                distEl.innerHTML = '<span class="text-amber-600 animate-pulse font-sans text-xs">📡 Mengunci satelit GPS HP/Tablet...</span>';
            }

            try {
                var pos = await getDeviceGpsPosition({ enableHighAccuracy: true, timeout: 15000, maximumAge: 0 });
                state.lastDeviceGps = pos;

                if (statusBadge) {
                    statusBadge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800';
                    statusBadge.innerHTML = '🟢 GPS HP Terhubung';
                }
                if (coordsEl) {
                    coordsEl.innerText = pos.latitude.toFixed(6) + ', ' + pos.longitude.toFixed(6);
                }
                if (accEl) {
                    accEl.innerText = 'Akurasi: ±' + Math.round(pos.accuracy) + 'm';
                }

                var branch = state.currentBranchGeofence || state.currentBranch || {};
                var bLat = parseFloat(branch.latitude) || 0;
                var bLng = parseFloat(branch.longitude) || 0;
                var maxRadius = parseInt(branch.radius_meters) || 100;

                if (Math.abs(bLat) < 0.000001 && Math.abs(bLng) < 0.000001) {
                    if (distEl) {
                        distEl.className = 'font-bold text-amber-600 font-mono text-xs';
                        distEl.innerText = 'Koordinat toko belum diatur Admin';
                    }
                    if (alertBox) {
                        alertBox.className = 'p-2.5 rounded-xl text-xs bg-amber-50 dark:bg-amber-950/60 border border-amber-200 dark:border-amber-800/80 text-amber-800 dark:text-amber-200 flex items-start space-x-2';
                        alertBox.innerHTML = '<i data-lucide="alert-triangle" class="w-4 h-4 text-amber-600 shrink-0 mt-0.5"></i><span>Titik koordinat cabang toko belum diset oleh Administrator. Presensi belum dapat divalidasi.</span>';
                        if (window.lucide) lucide.createIcons();
                    }
                    return;
                }

                var distance = calculateHaversineMeters(pos.latitude, pos.longitude, bLat, bLng);
                var distMetersRounded = Math.round(distance * 10) / 10;
                state.lastGpsDistance = distMetersRounded;

                if (distance <= maxRadius) {
                    if (distEl) {
                        distEl.className = 'font-bold text-emerald-600 font-mono text-sm';
                        distEl.innerText = distMetersRounded + 'm (Valid di Toko - Batas: ' + maxRadius + 'm)';
                    }
                    if (alertBox) {
                        alertBox.className = 'p-2.5 rounded-xl text-xs bg-emerald-50 dark:bg-emerald-950/60 border border-emerald-200 dark:border-emerald-800/80 text-emerald-800 dark:text-emerald-200 flex items-start space-x-2';
                        alertBox.innerHTML = '<i data-lucide="check-circle" class="w-4 h-4 text-emerald-600 shrink-0 mt-0.5"></i><span><strong>Posisi Valid!</strong> Anda berada di area toko (Jarak: ' + distMetersRounded + 'm dari batas toleransi ' + maxRadius + 'm).</span>';
                        if (window.lucide) lucide.createIcons();
                    }
                } else {
                    if (distEl) {
                        distEl.className = 'font-bold text-rose-600 font-mono text-sm';
                        distEl.innerText = distMetersRounded + 'm (Di Luar Radius! Batas: ' + maxRadius + 'm)';
                    }
                    if (alertBox) {
                        alertBox.className = 'p-2.5 rounded-xl text-xs bg-rose-50 dark:bg-rose-950/60 border border-rose-200 dark:border-rose-800/80 text-rose-800 dark:text-rose-200 flex items-start space-x-2';
                        alertBox.innerHTML = '<i data-lucide="map-pin-off" class="w-4 h-4 text-rose-600 shrink-0 mt-0.5"></i><span><strong>Di Luar Radius!</strong> Posisi Anda ' + distMetersRounded + 'm melampaui batas radius ' + maxRadius + 'm. Mohon mendekat ke toko untuk presensi.</span>';
                        if (window.lucide) lucide.createIcons();
                    }
                }

                if (showAlert) {
                    alert('Sinyal GPS Berhasil Diperbarui!\n\nKoordinat: ' + pos.latitude.toFixed(6) + ', ' + pos.longitude.toFixed(6) + '\nAkurasi: ±' + Math.round(pos.accuracy) + ' meter\nJarak ke Toko: ' + distMetersRounded + ' meter (Batas: ' + maxRadius + ' meter)\nStatus: ' + (distance <= maxRadius ? 'VALID (Di dalam area toko)' : 'DI LUAR RADIUS TOKO'));
                }
            } catch (err) {
                state.lastDeviceGps = null;
                if (statusBadge) {
                    statusBadge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-rose-100 dark:bg-rose-950/80 text-rose-800 dark:text-rose-300 border border-rose-200 dark:border-rose-800';
                    statusBadge.innerHTML = '🔴 GPS Tidak Aktif';
                }
                if (coordsEl) {
                    coordsEl.innerText = 'GPS OFF / Ditolak';
                }
                if (accEl) {
                    accEl.innerText = 'Periksa setelan lokasi HP';
                }
                if (distEl) {
                    distEl.className = 'font-bold text-rose-600 font-mono text-xs';
                    distEl.innerText = 'GPS belum terhubung';
                }
                if (alertBox) {
                    alertBox.className = 'p-2.5 rounded-xl text-xs bg-rose-50 dark:bg-rose-950/60 border border-rose-200 dark:border-rose-800/80 text-rose-800 dark:text-rose-200 flex items-start space-x-2';
                    alertBox.innerHTML = '<i data-lucide="alert-circle" class="w-4 h-4 text-rose-600 shrink-0 mt-0.5"></i><span><strong>GPS Belum Aktif!</strong> ' + (err.message || 'Pastikan GPS HP/Tablet dalam posisi ON dan izin lokasi browser diaktifkan.') + '</span>';
                    if (window.lucide) lucide.createIcons();
                }

                if (showAlert) {
                    alert('⚠️ GAGAL MENGAKSES GPS HP / TABLET!\n\n' + err.message + '\n\nPetunjuk Solusi:\n1. Buka pengaturan HP/Tablet atau geser layar notifikasi atas, hidupkan tombol "Lokasi" (Location ON).\n2. Jika peramban menanyakan izin akses lokasi, pilih "Izinkan" (Allow).\n3. Tekan tombol "Ambil / Segarkan Sinyal GPS HP" sekali lagi.');
                }
            }
        }

        function setSimulatedGps(isInside) {
            var b = state.currentBranchGeofence || state.currentBranch || {};
            var bLat = parseFloat(b.latitude) || -6.2088;
            var bLng = parseFloat(b.longitude) || 106.8456;
            var maxRadius = parseInt(b.radius_meters) || 100;

            var simulatedLat = isInside ? (bLat + 0.00008) : (bLat + 0.0035);
            var simulatedLng = isInside ? (bLng + 0.00008) : (bLng + 0.0035);

            state.lastDeviceGps = {
                latitude: simulatedLat,
                longitude: simulatedLng,
                accuracy: 10,
                isSimulated: true
            };

            var statusBadge = document.getElementById('ess-gps-status-badge');
            var coordsEl = document.getElementById('ess-device-coords');
            var accEl = document.getElementById('ess-device-accuracy');
            var distEl = document.getElementById('ess-geo-distance');
            var alertBox = document.getElementById('ess-gps-alert-box');

            if (statusBadge) {
                statusBadge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-purple-100 dark:bg-purple-950/80 text-purple-800 dark:text-purple-300 border border-purple-200 dark:border-purple-800';
                statusBadge.innerHTML = '🧪 Mode Uji Coba Admin';
            }
            if (coordsEl) coordsEl.innerText = simulatedLat.toFixed(6) + ', ' + simulatedLng.toFixed(6);
            if (accEl) accEl.innerText = 'Mode: Uji Coba (±10m)';

            var distance = calculateHaversineMeters(simulatedLat, simulatedLng, bLat, bLng);
            var distMetersRounded = Math.round(distance * 10) / 10;

            if (distEl) {
                distEl.className = 'font-bold ' + (distance <= maxRadius ? 'text-emerald-600' : 'text-rose-600') + ' font-mono text-sm';
                distEl.innerText = distMetersRounded + 'm (' + (distance <= maxRadius ? 'Valid di Toko' : 'Di Luar Radius!') + ' - Batas: ' + maxRadius + 'm)';
            }
            if (alertBox) {
                alertBox.className = 'p-2.5 rounded-xl text-xs ' + (distance <= maxRadius ? 'bg-emerald-50 dark:bg-emerald-950/60 border-emerald-200 dark:border-emerald-800/80 text-emerald-800 dark:text-emerald-200' : 'bg-rose-50 dark:bg-rose-950/60 border-rose-200 dark:border-rose-800/80 text-rose-800 dark:text-rose-200') + ' border flex items-start space-x-2';
                alertBox.innerHTML = '<i data-lucide="info" class="w-4 h-4 shrink-0 mt-0.5"></i><span>[Mode Pengujian Admin] Posisi disimulasikan ' + (isInside ? 'DI DALAM' : 'DI LUAR') + ' radius toko (' + distMetersRounded + 'm dari batas toleransi ' + maxRadius + 'm).</span>';
                if (window.lucide) lucide.createIcons();
            }
        }

        async function submitClockIn() {
            var b = state.currentBranchGeofence || state.currentBranch || {};
            var u = state.currentUser || state.loggedInUser || {};

            // Mengambil koordinat GPS nyata dari sensor perangkat HP / Tablet
            var pos = null;
            if (state.lastDeviceGps && state.lastDeviceGps.isSimulated) {
                pos = state.lastDeviceGps;
            } else {
                try {
                    pos = await getDeviceGpsPosition({ enableHighAccuracy: true, timeout: 15000, maximumAge: 0 });
                    state.lastDeviceGps = pos;
                } catch (err) {
                    alert('⚠️ TIDAK DAPAT CLOCK-IN KARENA GPS BELUM AKTIF!\n\n' + err.message + '\n\nLangkah-langkah Penanganan:\n1. Pastikan sakelar LOKASI / GPS di HP/Tablet dalam posisi ON (Aktif).\n2. Berikan izin akses lokasi untuk peramban web ini.\n3. Tekan tombol "Ambil Sinyal GPS HP", lalu coba Clock-In kembali.');
                    return;
                }
            }

            if (!pos || !pos.latitude || !pos.longitude) {
                alert('Sinyal GPS tidak terdeteksi. Pastikan GPS HP/Tablet dalam posisi ON.');
                return;
            }

            try {
                var res = await fetch('api.php?action=ess_clock_in', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        user_id: u.id,
                        branch_id: b.id,
                        latitude: pos.latitude,
                        longitude: pos.longitude
                    })
                });
                var data = await res.json();
                if (data.success) {
                    alert('✅ ' + data.message);
                    loadEssData();
                } else {
                    alert('❌ ' + (data.message || data.error || 'Clock-in gagal'));
                }
            } catch (netErr) {
                alert('Gagal menghubungi server: ' + netErr.message);
            }
        }

        async function submitClockOut() {
            var u = state.currentUser || state.loggedInUser || {};
            try {
                var res = await fetch('api.php?action=ess_clock_out', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ user_id: u.id })
                });
                var data = await res.json();
                if (data.success) {
                    alert('✅ ' + data.message);
                    loadEssData();
                } else {
                    alert('❌ ' + (data.message || data.error || 'Clock-out gagal'));
                }
            } catch (netErr) {
                alert('Gagal menghubungi server: ' + netErr.message);
            }
        }

        // ==========================================
        // PENGATURAN RADIUS PRESENSI OLEH ADMIN
        // ==========================================
        function openEditAttendanceRadiusModal() {
            var branch = state.currentBranchGeofence || state.currentBranch || {};
            var modal = document.getElementById('ess-attendance-radius-modal');
            if (!modal) return;

            var nameEl = document.getElementById('ess-radius-branch-name');
            var inputEl = document.getElementById('ess-radius-input');
            if (nameEl) nameEl.innerText = branch.name || 'Cabang Aktif';
            if (inputEl) inputEl.value = (branch.radius_meters !== undefined && branch.radius_meters !== null) ? branch.radius_meters : 100;

            modal.classList.remove('hidden');
            if (window.lucide) lucide.createIcons();
        }

        function closeEditAttendanceRadiusModal() {
            var modal = document.getElementById('ess-attendance-radius-modal');
            if (modal) modal.classList.add('hidden');
        }

        function setRadiusPreset(val) {
            var inputEl = document.getElementById('ess-radius-input');
            if (inputEl) inputEl.value = val;
        }

        async function saveAttendanceRadius() {
            var branch = state.currentBranchGeofence || state.currentBranch || {};
            var inputEl = document.getElementById('ess-radius-input');
            var radiusVal = parseInt(inputEl ? inputEl.value : 100) || 100;

            if (radiusVal < 5 || radiusVal > 50000) {
                alert('Jarak radius harus di antara 5 meter sampai 50.000 meter.');
                return;
            }

            var u = state.currentUser || state.loggedInUser || {};

            try {
                var res = await fetch('api.php?action=update_attendance_radius', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        branch_id: branch.id,
                        radius_meters: radiusVal,
                        user_id: u.id
                    })
                });
                var data = await res.json();
                if (data.success) {
                    alert('✅ ' + data.message);
                    closeEditAttendanceRadiusModal();
                    if (state.currentBranchGeofence) state.currentBranchGeofence.radius_meters = radiusVal;
                    if (state.currentBranch) state.currentBranch.radius_meters = radiusVal;
                    var displayEl = document.getElementById('ess-branch-radius-display');
                    if (displayEl) displayEl.innerText = radiusVal + ' Meter';
                    refreshDeviceGps(false);
                } else {
                    alert('❌ ' + (data.error || data.message || 'Gagal menyimpan radius presensi.'));
                }
            } catch (err) {
                alert('Gagal menghubungi server: ' + err.message);
            }
        }

        async function submitReimbursement() {
            const cat = document.getElementById('reimburse-category').value;
            const amount = parseFloat(document.getElementById('reimburse-amount').value) || 0;
            const desc = document.getElementById('reimburse-notes').value;
            if (amount <= 0) { alert('Nominal tidak valid'); return; }

            const res = await fetch('api.php?action=ess_submit_reimbursement', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ user_id: state.currentUser.id, branch_id: state.currentBranch.id, category: cat, amount, description: desc })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                document.getElementById('reimburse-amount').value = '';
                document.getElementById('reimburse-notes').value = '';
                loadEssData();
            }
        }

        async function disburseReimbursement(id) {
            if (!confirm('Cairkan reimbursement? Nominal akan OTOMATIS tercatat ke Beban Laba Rugi!')) return;
            const res = await fetch('api.php?action=ess_approve_reimbursement', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ reimbursement_id: id, approval_action: 'DISBURSE' })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) loadEssData();
        }

        async function deleteReimbursement(id) {
            if (!confirm('Apakah Anda yakin ingin menghapus data klaim reimbursement ini?')) return;
            try {
                const res = await fetch('api.php?action=ess_delete_reimbursement', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ reimbursement_id: id })
                });
                const data = await res.json();
                alert(data.message || (data.success ? 'Data reimbursement berhasil dihapus.' : 'Gagal menghapus data.'));
                if (data.success) {
                    loadEssData();
                }
            } catch (err) {
                alert('Gagal menghubungi server: ' + err.message);
            }
        }

        async function clearAllReimbursements() {
            if (!confirm('Apakah Anda yakin ingin menghapus dan mengosongkan seluruh data reimbursement? Tindakan ini tidak dapat dibatalkan.')) return;
            try {
                const res = await fetch('api.php?action=ess_clear_all_reimbursements', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ branch_id: state.currentBranch ? state.currentBranch.id : 0 })
                });
                const data = await res.json();
                alert(data.message || (data.success ? 'Seluruh data reimbursement berhasil dikosongkan.' : 'Gagal mengosongkan data.'));
                if (data.success) {
                    loadEssData();
                }
            } catch (err) {
                alert('Gagal menghubungi server: ' + err.message);
            }
        }

        // ==========================================
        // 3b. ESS SUBTABS CONTROLLER & LOGIC
        // ==========================================
        let essActiveSubtab = 'presensi';
        let essWorkShiftsList = [];
        let essCurrentPayslipData = null;

        function setEssSubtab(subtab) {
            essActiveSubtab = subtab;
            const subtabs = ['presensi', 'schedules', 'swaps', 'leaves', 'attendance', 'payslip', 'loans'];
            subtabs.forEach(st => {
                const container = document.getElementById(`ess-subtab-${st}`);
                const btn = document.getElementById(`ess-subtab-btn-${st}`);
                if (container) container.classList.toggle('hidden', st !== subtab);
                if (btn) {
                    if (st === subtab) {
                        btn.className = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-indigo-600 text-white shadow-2xs';
                    } else {
                        btn.className = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-slate-100 hover:bg-slate-200/80 text-slate-700 hover:text-slate-900 dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700';
                    }
                }
            });

            if (subtab === 'presensi') loadEssData();
            if (subtab === 'schedules') {
                loadWorkShifts();
                initRosterControls();
                loadMonthlySchedules();
            }
            if (subtab === 'swaps') {
                populateSwapPeerDropdown();
                loadShiftSwaps();
            }
            if (subtab === 'leaves') loadLeaveRequests();
            if (subtab === 'attendance') {
                initAttendanceControls();
                loadAttendanceReport();
            }
            if (subtab === 'payslip') {
                initPayslipControls();
                loadEmployeePayslip();
            }
            if (subtab === 'loans') loadSalaryLoans();

            lucide.createIcons();
        }

        // --- 1. Master Jam Kerja (Work Shifts CRUD) ---
        async function loadWorkShifts() {
            try {
                const curUser = state.currentUser || state.loggedInUser || { id: 3, role: 'CASHIER' };
                const isManager = isManagerOrSuperAdminUser(curUser);
                const addBtn = document.getElementById('btn-add-work-shift');
                if (addBtn) addBtn.style.display = isManager ? '' : 'none';

                const res = await fetch('api.php?action=get_work_shifts');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }
                essWorkShiftsList = data.shifts || [];

                const container = document.getElementById('ess-work-shifts-grid');
                if (!container) return;

                container.innerHTML = essWorkShiftsList.map(ws => `
                    <div class="p-3.5 rounded-2xl border ${ws.is_day_off ? 'bg-slate-50 dark:bg-slate-800/80 border-slate-200 dark:border-slate-700/80' : 'bg-white dark:bg-slate-800/80 border-slate-200 dark:border-slate-700/80'} shadow-2xs space-y-2 relative transition-colors">
                        <div class="flex items-center justify-between">
                            <span class="px-2 py-0.5 rounded-lg text-[10px] font-black font-mono text-white shadow-2xs" style="background-color: ${ws.color_tag || '#3b82f6'}">${ws.code}</span>
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${ws.is_active ? 'bg-emerald-100 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800' : 'bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700'}">
                                ${ws.is_active ? 'Aktif' : 'Nonaktif'}
                            </span>
                        </div>
                        <div>
                            <h4 class="font-bold text-slate-800 dark:text-slate-100 text-xs">${ws.name}</h4>
                            <p class="font-mono text-xs text-slate-600 dark:text-slate-300 font-bold mt-0.5">
                                ${ws.is_day_off ? '🏖️ HARI LIBUR / OFF' : `🕒 ${ws.start_time} - ${ws.end_time}`}
                            </p>
                            ${!ws.is_day_off ? `<p class="text-[10px] text-slate-400 dark:text-slate-400 mt-0.5">Toleransi: ${ws.late_tolerance_mins} menit</p>` : ''}
                        </div>
                        ${isManager ? `
                        <div class="flex items-center justify-end space-x-1 pt-2 border-t border-slate-100 dark:border-slate-700/60">
                            <button onclick='openWorkShiftModal(${JSON.stringify(ws)})' class="p-1 text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400 rounded-lg text-xs font-semibold flex items-center space-x-1 transition-colors">
                                <i data-lucide="edit" class="w-3.5 h-3.5"></i>
                                <span>Edit</span>
                            </button>
                            <button onclick="deleteWorkShift(${ws.id})" class="p-1 text-slate-400 dark:text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 rounded-lg text-xs font-semibold transition-colors">
                                <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                            </button>
                        </div>
                        ` : ''}
                    </div>
                `).join('') || `<p class="text-xs text-slate-400 dark:text-slate-500 col-span-4">Belum ada shift kerja terdaftar</p>`;

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function openWorkShiftModal(shift = null) {
            const modal = document.getElementById('work-shift-modal');
            const title = document.getElementById('ws-modal-title');
            if (!modal) return;

            if (shift) {
                title.innerText = 'Edit Shift Jam Kerja';
                document.getElementById('ws-id').value = shift.id || '';
                document.getElementById('ws-code').value = shift.code || '';
                document.getElementById('ws-color').value = shift.color_tag || '#3b82f6';
                document.getElementById('ws-name').value = shift.name || '';
                document.getElementById('ws-start-time').value = shift.start_time || '07:00';
                document.getElementById('ws-end-time').value = shift.end_time || '15:00';
                document.getElementById('ws-tolerance').value = _nn(shift.late_tolerance_mins, 15);
                document.getElementById('ws-is-active').value = _nn(shift.is_active, 1);
                document.getElementById('ws-is-day-off').checked = shift.is_day_off == 1;
            } else {
                title.innerText = 'Tambah Shift Jam Kerja Baru';
                document.getElementById('ws-id').value = '';
                document.getElementById('ws-code').value = '';
                document.getElementById('ws-color').value = '#3b82f6';
                document.getElementById('ws-name').value = '';
                document.getElementById('ws-start-time').value = '07:00';
                document.getElementById('ws-end-time').value = '15:00';
                document.getElementById('ws-tolerance').value = 15;
                document.getElementById('ws-is-active').value = '1';
                document.getElementById('ws-is-day-off').checked = false;
            }
            modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeWorkShiftModal() {
            const modal = document.getElementById('work-shift-modal');
            if (modal) modal.classList.add('hidden');
        }

        async function saveWorkShiftForm(e) {
            e.preventDefault();
            const payload = {
                id: document.getElementById('ws-id').value || null,
                code: document.getElementById('ws-code').value,
                color_tag: document.getElementById('ws-color').value,
                name: document.getElementById('ws-name').value,
                start_time: document.getElementById('ws-start-time').value,
                end_time: document.getElementById('ws-end-time').value,
                late_tolerance_mins: parseInt(document.getElementById('ws-tolerance').value) || 15,
                is_active: parseInt(document.getElementById('ws-is-active').value) || 1,
                is_day_off: document.getElementById('ws-is-day-off').checked ? 1 : 0
            };

            const res = await fetch('api.php?action=save_work_shift', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeWorkShiftModal();
                loadWorkShifts();
                loadMonthlySchedules();
            }
        }

        async function deleteWorkShift(id) {
            if (!confirm('Hapus atau nonaktifkan shift kerja ini?')) return;
            const res = await fetch('api.php?action=delete_work_shift', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadWorkShifts();
                loadMonthlySchedules();
            }
        }

        // --- 2. Roster Jadwal Kerja Bulanan ---
        function initRosterControls() {
            const bSelect = document.getElementById('ess-roster-branch-select');
            const mInput = document.getElementById('ess-roster-month-input');
            const curUser = state.currentUser || state.loggedInUser || { id: 3, role: 'CASHIER' };
            const role = (curUser.role || 'CASHIER').toUpperCase().trim();
            const isSuperAdmin = (role === 'SUPERADMIN' || role === 'SUPER_ADMIN' || role === 'SUPER ADMIN');
            const userBranchId = curUser.branch_id || (state.currentBranch ? state.currentBranch.id : 1);

            if (bSelect && state.branches && state.branches.length > 0) {
                if (!isSuperAdmin) {
                    const userBranch = state.branches.find(b => parseInt(b.id) === parseInt(userBranchId)) || { id: userBranchId, name: (state.currentBranch ? state.currentBranch.name : 'Cabang') || 'Cabang Penugasan' };
                    bSelect.innerHTML = `<option value="${userBranch.id}" selected>${userBranch.name} (Terkunci)</option>`;
                    bSelect.value = userBranch.id;
                    bSelect.disabled = true;
                    bSelect.title = "Terkunci pada lokasi cabang penempatan Anda";
                    bSelect.className = "p-2 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 border border-slate-300 dark:border-slate-700 rounded-xl font-bold cursor-not-allowed opacity-90";
                } else {
                    bSelect.disabled = false;
                    bSelect.title = "Pilih cabang untuk melihat roster jadwal";
                    bSelect.className = "p-2 bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100 border border-slate-200 dark:border-slate-700 rounded-xl font-bold";
                    const currentSelected = bSelect.value || (state.currentBranch ? state.currentBranch.id : state.branches[0].id);
                    bSelect.innerHTML = state.branches.map(b => `<option value="${b.id}" ${parseInt(b.id) === parseInt(currentSelected) ? 'selected' : ''}>${b.name}</option>`).join('');
                }
            }
            if (mInput && !mInput.value) {
                const now = new Date();
                const mStr = now.toISOString().slice(0, 7);
                mInput.value = mStr;
            }
        }

        async function loadMonthlySchedules() {
            const curUser = state.currentUser || state.loggedInUser || { id: 3, role: 'CASHIER' };
            const role = (curUser.role || 'CASHIER').toUpperCase().trim();
            const isSuperAdmin = (role === 'SUPERADMIN' || role === 'SUPER_ADMIN' || role === 'SUPER ADMIN');
            const isManager = isManagerOrSuperAdminUser(curUser);
            const userBranchId = curUser.branch_id || (state.currentBranch ? state.currentBranch.id : 1);
            const bId = (!isSuperAdmin && userBranchId) ? userBranchId : (_val('ess-roster-branch-select') || state.currentBranch.id);
            const mVal = _val('ess-roster-month-input') || new Date().toISOString().slice(0, 7);

            const impBtn = document.getElementById('btn-import-schedule');
            if (impBtn) impBtn.style.display = isManager ? '' : 'none';
            const holBtn = document.getElementById('btn-holiday-setter');
            if (holBtn) holBtn.style.display = isManager ? '' : 'none';

            try {
                const res = await fetch(`api.php?action=get_monthly_schedules&branch_id=${bId}&month=${mVal}&user_id=${curUser.id}`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const thead = document.getElementById('ess-roster-table-head');
                const tbody = document.getElementById('ess-roster-table-body');
                if (!thead || !tbody) return;

                const daysCount = data.days_in_month || 31;
                const employees = data.employees || [];
                const schedules = data.schedules || [];

                // Map schedules: user_id -> date -> sched
                const schedMap = {};
                schedules.forEach(s => {
                    if (!schedMap[s.user_id]) schedMap[s.user_id] = {};
                    schedMap[s.user_id][s.shift_date] = s;
                });

                // Render Header
                let thHtml = `<tr>
                    <th class="py-2.5 px-3 sticky left-0 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 z-10 w-44 min-w-[170px] border-r border-slate-200 dark:border-slate-700">Karyawan / Tanggal</th>`;
                for (let d = 1; d <= daysCount; d++) {
                    const dStr = String(d).padStart(2, '0');
                    const fullDate = `${mVal}-${dStr}`;
                    const dayName = new Date(fullDate).toLocaleDateString('id-ID', { weekday: 'narrow' });
                    const isSun = new Date(fullDate).getDay() === 0;
                    thHtml += `<th class="py-2 px-1.5 text-center min-w-[38px] border-r border-slate-200 dark:border-slate-700/80 ${isSun ? 'bg-rose-50 dark:bg-rose-950/40 text-rose-700 dark:text-rose-400' : 'text-slate-700 dark:text-slate-200'}">
                        <span class="block text-[10px] ${isSun ? 'text-rose-500 dark:text-rose-400 font-bold' : 'text-slate-400 dark:text-slate-400 font-semibold'}">${dayName}</span>
                        <span>${d}</span>
                    </th>`;
                }
                thHtml += `</tr>`;
                thead.innerHTML = thHtml;

                // Render Body
                if (employees.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="${daysCount + 1}" class="text-center py-6 text-slate-400 dark:text-slate-500">Belum ada jadwal untuk Anda di periode ini</td></tr>`;
                    return;
                }

                let tbHtml = '';
                employees.forEach(emp => {
                    tbHtml += `<tr class="hover:bg-slate-50/80 dark:hover:bg-slate-800/50 transition-colors">
                        <td class="py-2 px-3 sticky left-0 bg-white dark:bg-slate-900 z-10 border-r border-slate-200 dark:border-slate-800 text-slate-800 dark:text-slate-200 shadow-xs">
                            <span class="font-bold text-slate-800 dark:text-slate-100 block truncate max-w-[150px]">${emp.name}</span>
                            <span class="text-[10px] text-slate-400 dark:text-slate-500 font-mono">${emp.nik} &bull; ${emp.role}</span>
                        </td>`;
                    for (let d = 1; d <= daysCount; d++) {
                        const dStr = String(d).padStart(2, '0');
                        const fullDate = `${mVal}-${dStr}`;
                        const isSun = new Date(fullDate).getDay() === 0;
                        const cellSched = schedMap[emp.id] ? schedMap[emp.id][fullDate] : null;

                        let badgeCode = cellSched ? (cellSched.shift_code || 'S1') : (isSun ? 'OFF' : '-');
                        let isOff = cellSched ? (cellSched.is_holiday == 1 || cellSched.shift_is_day_off == 1) : isSun;
                        let isUnscheduled = !cellSched && !isSun;
                        
                        let btnClass = '';
                        let styleAttr = '';

                        if (isUnscheduled) {
                            btnClass = 'bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-500 border border-slate-200 dark:border-slate-700/60';
                        } else if (isOff) {
                            btnClass = 'bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-300 dark:border-slate-700';
                        } else {
                            let color = cellSched.color_tag || '#3b82f6';
                            btnClass = 'text-white border border-transparent shadow-xs';
                            styleAttr = `background-color: ${color};`;
                        }

                        tbHtml += `<td class="p-1 text-center border-r border-slate-200 dark:border-slate-800/80 ${isSun ? 'bg-rose-50/30 dark:bg-rose-950/20' : ''}">
                            <button ${isManager ? `onclick="openSingleScheduleModal(${emp.id}, '${fullDate}', '${emp.name}', ${cellSched ? cellSched.work_shift_id : null})"` : `onclick="void(0)"`}
                                    class="w-full py-1 rounded text-[10px] font-black font-mono shadow-2xs ${isManager ? 'hover:scale-105 cursor-pointer' : 'cursor-default'} transition-transform ${btnClass}"
                                    ${styleAttr ? `style="${styleAttr}"` : ''}
                                    title="${cellSched ? `${cellSched.shift_name} (${cellSched.start_time}-${cellSched.end_time})` : (isManager ? 'Klik untuk atur shift' : 'Libur / Tidak Terjadwal')}">
                                ${badgeCode}
                            </button>
                        </td>`;
                    }
                    tbHtml += `</tr>`;
                });
                tbody.innerHTML = tbHtml;
                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function openSingleScheduleModal(userId, date, empName, currentShiftId) {
            const modal = document.getElementById('single-schedule-edit-modal');
            if (!modal) return;
            document.getElementById('sched-cell-user-id').value = userId;
            document.getElementById('sched-cell-date').value = date;
            document.getElementById('sched-cell-modal-sub').innerText = `Karyawan: ${empName} (${date})`;

            const select = document.getElementById('sched-cell-shift-select');
            select.innerHTML = essWorkShiftsList.map(ws => `
                <option value="${ws.id}" ${ws.id == currentShiftId ? 'selected' : ''}>
                    ${ws.code} - ${ws.name} (${ws.start_time} - ${ws.end_time})
                </option>
            `).join('');

            modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeSingleScheduleModal() {
            _cls('single-schedule-edit-modal', 'add', 'hidden');
        }

        async function saveSingleScheduleForm(e) {
            e.preventDefault();
            const bId = _val('ess-roster-branch-select') || state.currentBranch.id;
            const uId = document.getElementById('sched-cell-user-id').value;
            const date = document.getElementById('sched-cell-date').value;
            const shiftId = document.getElementById('sched-cell-shift-select').value;
            const notes = document.getElementById('sched-cell-notes').value;

            const res = await fetch('api.php?action=save_single_schedule', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ branch_id: bId, user_id: uId, shift_date: date, work_shift_id: shiftId, notes })
            });
            const data = await res.json();
            if (data.success) {
                closeSingleScheduleModal();
                loadMonthlySchedules();
            } else {
                alert(data.message || data.error);
            }
        }

        function exportMonthlySchedules() {
            const bId = _val('ess-roster-branch-select') || state.currentBranch.id;
            const mVal = _val('ess-roster-month-input') || new Date().toISOString().slice(0, 7);
            window.location.href = `api.php?action=export_monthly_schedules&branch_id=${bId}&month=${mVal}&download=1`;
        }

        function openImportScheduleModal() {
            _cls('import-schedule-modal', 'remove', 'hidden');
        }

        function closeImportScheduleModal() {
            _cls('import-schedule-modal', 'add', 'hidden');
        }

        function handleScheduleFileSelect(event) {
            const file = event.target.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = function(e) {
                document.getElementById('import-sched-text').value = e.target.result;
            };
            reader.readAsText(file);
        }

        async function submitImportSchedule(e) {
            e.preventDefault();
            const bId = _val('ess-roster-branch-select') || state.currentBranch.id;
            const csvText = document.getElementById('import-sched-text').value;

            if (!csvText.trim()) {
                alert('Silakan pilih file CSV atau tempel teks data CSV terlebih dahulu.');
                return;
            }

            const res = await fetch('api.php?action=import_monthly_schedules', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ branch_id: bId, csv_data: csvText })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeImportScheduleModal();
                loadMonthlySchedules();
            }
        }

