            const employeePool = (typeof allEmployeesData !== 'undefined' && allEmployeesData && allEmployeesData.length > 0) ? allEmployeesData : (state.users || []);
            const mgrUser = employeePool.find(e => ['BRANCH_MANAGER', 'MANAGER'].includes(e.role));
            const signMgr = document.getElementById('sq-sign-mgr');
            if (signMgr) signMgr.innerText = mgrUser ? mgrUser.name : 'Manager Operasional';
        }

        async function openPayrollSlipModal(userId, month = null) {
            const mVal = month || payrollModuleState.month || _val('payroll-month-input') || new Date().toISOString().slice(0, 7);
            const curUser = state.currentUser || state.loggedInUser || { id: 1 };

            try {
                const res = await fetch(`api.php?action=get_employee_payslip&user_id=${userId}&req_user_id=${curUser.id}&month=${mVal}`);
                const data = await res.json();
                if (!data.success) {
                    alert(data.message || 'Gagal memuat slip gaji');
                    return;
                }

                payrollModuleState.currentPayslip = data;
                const p = data.payroll || {};
                const u = data.user || {};
                const s = state.appSettings || {};
                const details = data.details || {};

                // 1. Render Format Rinci Starqua
                renderStarquaSlipTable(details, p, u, mVal);

                // 2. Render Format Standar Navy (Backup View)
                const payslipCompName = (s.payslip_company_name && s.payslip_company_name.trim())
                    ? s.payslip_company_name.trim()
                    : (s.company_name || 'KARYA ANUGERAH DIMENSI TECHNOLOGY');
                document.getElementById('modal-slip-company-name').innerText = payslipCompName.toUpperCase();
                document.getElementById('modal-slip-branch-name').innerText = u.branch_name || (state.currentBranch ? state.currentBranch.name : 'Pusat Cimahi');
                document.getElementById('modal-slip-branch-address').innerText = u.branch_address || 'Jl. Panembakan No. 47/39';
                document.getElementById('modal-slip-period-label').innerText = `Periode: ${mVal}`;
                document.getElementById('modal-slip-id-label').innerText = `NO: PAY-${mVal.replace('-', '')}-${String(u.id || 0).padStart(3, '0')}`;

                document.getElementById('modal-slip-emp-nik').innerText = u.nik || '-';
                document.getElementById('modal-slip-emp-name').innerText = u.name || '-';
                document.getElementById('modal-slip-emp-role').innerText = (u.role || '-').toUpperCase();
                document.getElementById('modal-slip-emp-attendance-days').innerText = `${p.attendance_days || 0} Hari Hadir`;
                if (document.getElementById('modal-slip-emp-comm-rate')) document.getElementById('modal-slip-emp-comm-rate').innerText = `${((parseFloat(u.commission_rate) || 0) * 100).toFixed(1)}%`;

                const isVerified = p.payment_status === 'GENERATED' || p.payment_status === 'PAID';
                const statusBadgeEl = document.getElementById('modal-slip-status-badge');
                if (statusBadgeEl) {
                    statusBadgeEl.className = isVerified
                        ? 'px-2 py-0.5 bg-emerald-100 text-emerald-800 rounded font-bold text-[10px]'
                        : 'px-2 py-0.5 bg-amber-100 text-amber-800 rounded font-bold text-[10px]';
                    statusBadgeEl.innerText = isVerified ? 'TERVERIFIKASI' : (p.payment_status || 'DRAFT');
                }

                const baseSal = parseFloat(p.base_salary) || 0;
                const allow = parseFloat(p.allowance) || 0;
                const transp = parseFloat(p.transport_total) || 0;
                const comm = parseFloat(p.sales_commission) || 0;
                const overtime = (parseFloat(p.overtime_pay) || 0) + (parseFloat(p.bonus_pay) || 0);
                const meal = parseFloat(data.shift_meal_allowance) || 0;
                const gross = parseFloat(p.gross_salary) || (baseSal + allow + transp + comm + overtime);

                document.getElementById('modal-slip-base-salary').innerText = formatRupiah(baseSal);
                document.getElementById('modal-slip-allowance').innerText = formatRupiah(allow);
                document.getElementById('modal-slip-transport').innerText = formatRupiah(transp);
                document.getElementById('modal-slip-commission').innerText = formatRupiah(comm);
                document.getElementById('modal-slip-overtime').innerText = formatRupiah(overtime);
                document.getElementById('modal-slip-meal-allowance-paid').innerText = formatRupiah(meal);
                document.getElementById('modal-slip-gross-salary').innerText = formatRupiah(gross);

                const dLate = parseFloat(p.late_deduction) || 0;
                const dAbsence = parseFloat(p.absence_deduction) || 0;
                const dLoan = parseFloat(p.loan_deduction) || 0;
                const dTax = parseFloat(p.tax_deduction) || 0;
                const dOther = parseFloat(p.other_deduction) || 0;
                const totDeduct = parseFloat(p.total_deductions) || (dLate + dAbsence + dLoan + dTax + dOther);

                document.getElementById('modal-slip-deduct-late').innerText = formatRupiah(dLate);
                document.getElementById('modal-slip-deduct-absence').innerText = formatRupiah(dAbsence);
                document.getElementById('modal-slip-deduct-loan').innerText = formatRupiah(dLoan);
                document.getElementById('modal-slip-deduct-tax').innerText = formatRupiah(dTax);
                document.getElementById('modal-slip-deduct-other').innerText = formatRupiah(dOther);
                document.getElementById('modal-slip-total-deductions').innerText = formatRupiah(totDeduct);

                const netSal = parseFloat(p.net_salary) || (gross - totDeduct);
                document.getElementById('modal-slip-net-salary').innerText = formatRupiah(netSal);
                document.getElementById('modal-slip-terbilang-text').innerText = angkaTerbilang(netSal) + " Rupiah";

                const empNameEl = document.getElementById('modal-slip-sign-emp-name');
                if (empNameEl) empNameEl.innerText = u.name || '-';
                const employeePool = (typeof allEmployeesData !== 'undefined' && allEmployeesData && allEmployeesData.length > 0) ? allEmployeesData : (state.users || []);
                const mgrUser = employeePool.find(e => ['BRANCH_MANAGER', 'MANAGER'].includes(e.role));
                const mgrNameEl = document.getElementById('modal-slip-sign-mgr-name');
                if (mgrNameEl) mgrNameEl.innerText = mgrUser ? mgrUser.name : 'Nina Indrayani, SE.';

                const footerStatusEl = document.getElementById('modal-slip-status-footer');
                if (footerStatusEl) footerStatusEl.innerText = `Status Dokumen: ${isVerified ? 'Terverifikasi (Resmi)' : 'Draft Otomatis'}`;

                // Set default tampilan ke Starqua
                switchPayslipTemplate(payrollModuleState.activeTemplate || 'starqua');

                const modalEl = document.getElementById('payroll-slip-modal');
                if (modalEl) modalEl.classList.remove('hidden');
                if (typeof lucide !== 'undefined' && lucide.createIcons) lucide.createIcons();
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan saat memuat slip gaji.');
            }
        }

        function closePayrollSlipModal() {
            document.getElementById('payroll-slip-modal').classList.add('hidden');
        }

        function printModalPayslip() {
            document.body.classList.add('printing-payslip');
            window.print();
            setTimeout(() => {
                document.body.classList.remove('printing-payslip');
            }, 1000);
        }

        function openPayrollEditorFromModal() {
            if (!payrollModuleState.currentPayslip) return;
            const u = payrollModuleState.currentPayslip.user;
            const m = payrollModuleState.currentPayslip.month;
            closePayrollSlipModal();
            openPayrollEditorModal(u.id, m);
        }

        function recalcStarquaEditor() {
            const baseSalary = parseFloat(_val('sq-ed-base-salary')) || 0;

            // Insentif 7 Produk
            let totIncentives = 0;
            for (let i = 0; i < 7; i++) {
                const q = parseFloat(_val(`sq-ed-inc-qty-${i}`)) || 0;
                const r = parseFloat(_val(`sq-ed-inc-rate-${i}`)) || 0;
                totIncentives += (q * r);
            }

            // Fasilitas 5 Items
            let totFacilities = 0;
            for (let i = 0; i < 5; i++) {
                const q = parseFloat(_val(`sq-ed-fac-qty-${i}`)) || 0;
                const r = parseFloat(_val(`sq-ed-fac-rate-${i}`)) || 0;
                totFacilities += (q * r);
            }

            // Lebihan
            const overageVal = parseFloat(_val('sq-ed-overage-rate')) || 0;

            // Subtotal 1 (Penerimaan Kotor)
            const sub1 = baseSalary + totIncentives + totFacilities + overageVal;
            const sub1El = document.getElementById('sq-ed-subtotal-1');
            if (sub1El) sub1El.innerText = formatRupiah(sub1);

            // Subtotal 2 (Penggantian Biaya)
            let sub2 = 0;
            for (let i = 0; i < 2; i++) {
                const q = parseFloat(_val(`sq-ed-reimb-qty-${i}`)) || 0;
                const r = parseFloat(_val(`sq-ed-reimb-rate-${i}`)) || 0;
                sub2 += (q * r);
            }
            const sub2El = document.getElementById('sq-ed-subtotal-2');
            if (sub2El) sub2El.innerText = formatRupiah(sub2);

            // Subtotal 3 (Potongan Ketidakhadiran)
            let sub3 = 0;
            for (let i = 0; i < 3; i++) {
                const q = parseFloat(_val(`sq-ed-abs-qty-${i}`)) || 0;
                const r = parseFloat(_val(`sq-ed-abs-rate-${i}`)) || 0;
                sub3 += (q * r);
            }
            const sub3El = document.getElementById('sq-ed-subtotal-3');
            if (sub3El) sub3El.innerText = formatRupiah(sub3);

            // Subtotal 4 (Potongan Lain-lain)
            let sub4 = 0;
            for (let i = 0; i < 3; i++) {
                const q = parseFloat(_val(`sq-ed-oth-qty-${i}`)) || 0;
                const r = parseFloat(_val(`sq-ed-oth-rate-${i}`)) || 0;
                sub4 += (q * r);
            }
            const sub4El = document.getElementById('sq-ed-subtotal-4');
            if (sub4El) sub4El.innerText = formatRupiah(sub4);

            // Subtotal 5 (Pinjaman)
            const loanQ = parseFloat(_val('sq-ed-loan-qty-0')) || 0;
            const loanR = parseFloat(_val('sq-ed-loan-rate-0')) || 0;
            const sub5 = loanQ * loanR;
            const sub5El = document.getElementById('sq-ed-subtotal-5');
            if (sub5El) sub5El.innerText = formatRupiah(sub5);

            // Grand Total Take Home Pay
            const net = Math.max(0, sub1 + sub2 - sub3 - sub4 - sub5);

            // Update formula summary bar
            document.getElementById('ped-summary-gross').innerText = `1. Rp ${formatCleanNumber(sub1)}`;
            document.getElementById('ped-summary-reimb').innerText = `2. Rp ${formatCleanNumber(sub2)}`;
            document.getElementById('ped-summary-abs').innerText = `3. Rp ${formatCleanNumber(sub3)}`;
            document.getElementById('ped-summary-oth').innerText = `4. Rp ${formatCleanNumber(sub4)}`;
            document.getElementById('ped-summary-loan').innerText = `5. Rp ${formatCleanNumber(sub5)}`;
            document.getElementById('ped-summary-net').innerText = formatRupiah(net);

            // Sync ke standard inputs
            if (document.getElementById('ped-base-salary')) document.getElementById('ped-base-salary').value = baseSalary;
            if (document.getElementById('ped-sales-commission')) document.getElementById('ped-sales-commission').value = totIncentives;
            if (document.getElementById('ped-allowance')) document.getElementById('ped-allowance').value = totFacilities;
            if (document.getElementById('ped-bonus-pay')) document.getElementById('ped-bonus-pay').value = overageVal;
            if (document.getElementById('ped-overtime-pay')) document.getElementById('ped-overtime-pay').value = sub2;
            if (document.getElementById('ped-late-deduction')) document.getElementById('ped-late-deduction').value = sub3;
            if (document.getElementById('ped-loan-deduction')) document.getElementById('ped-loan-deduction').value = sub4 + sub5;
        }

        async function openPayrollEditorModal(userId, month = null) {
            const curUser = state.currentUser || state.loggedInUser || { id: 1 };
            const rawRole = ((curUser.role || '') + '').toUpperCase().replace(/_/g, '');
            const canManage = (rawRole === 'SUPERADMIN' || rawRole.indexOf('MANAGER') !== -1);
            if (!canManage) {
                alert('Akses Dibatasi: Hanya Super Admin dan Branch Manager yang berwenang mengedit komponen gaji.');
                return;
            }
            const mVal = month || payrollModuleState.month || _val('payroll-month-input') || new Date().toISOString().slice(0, 7);

            try {
                const res = await fetch(`api.php?action=get_employee_payslip&user_id=${userId}&req_user_id=${curUser.id}&month=${mVal}`);
                const data = await res.json();
                if (!data.success) {
                    alert(data.message || 'Gagal memuat rincian gaji');
                    return;
                }

                payrollModuleState.currentPayslip = data;
                const p = data.payroll || {};
                const u = data.user || {};
                const details = data.details || {};

                document.getElementById('ped-modal-subtitle').innerText = `Karyawan: ${u.name} (${u.nik}) | Cabang: ${u.branch_name || 'Depo Cimahi'} | Periode: ${mVal}`;

                document.getElementById('ped-user-id').value = u.id;
                document.getElementById('ped-branch-id').value = u.branch_id || (state.currentBranch ? state.currentBranch.id : 1);
                document.getElementById('ped-period-month').value = mVal;

                // Populasi Starqua Form
                document.getElementById('sq-ed-base-salary').value = parseFloat(p.base_salary) || 1000000;

                const inc = (details.incentives && details.incentives.length) ? details.incentives : [
                    { qty: 825, rate: 750 }, { qty: 397, rate: 750 }, { qty: 39, rate: 750 },
                    { qty: 169, rate: 750 }, { qty: 10, rate: 750 }, { qty: 0, rate: 0 }, { qty: 317, rate: 750 }
                ];
                for (let i = 0; i < 7; i++) {
                    const row = inc[i] || { qty: 0, rate: 750 };
                    if (document.getElementById(`sq-ed-inc-qty-${i}`)) document.getElementById(`sq-ed-inc-qty-${i}`).value = row.qty;
                    if (document.getElementById(`sq-ed-inc-rate-${i}`)) document.getElementById(`sq-ed-inc-rate-${i}`).value = row.rate;
                }

                const fac = (details.facilities && details.facilities.length) ? details.facilities : [
                    { qty: 27, rate: 10000 }, { qty: 1, rate: 50000 }, { qty: 1, rate: 150000 },
                    { qty: 0, rate: 150000 }, { qty: 0, rate: 150000 }
                ];
                for (let i = 0; i < 5; i++) {
                    const row = fac[i] || { qty: 0, rate: 0 };
                    if (document.getElementById(`sq-ed-fac-qty-${i}`)) document.getElementById(`sq-ed-fac-qty-${i}`).value = row.qty;
                    if (document.getElementById(`sq-ed-fac-rate-${i}`)) document.getElementById(`sq-ed-fac-rate-${i}`).value = row.rate;
                }

                const overage = (details.overage && details.overage.length) ? details.overage : [{ rate: 40500 }];
                document.getElementById('sq-ed-overage-rate').value = (overage[0] ? overage[0].rate : 0) || 40500;

                const reimb = (details.reimbursements && details.reimbursements.length) ? details.reimbursements : [
                    { qty: 11, rate: 5000 }, { qty: 1, rate: 50000 }
                ];
                for (let i = 0; i < 2; i++) {
                    const row = reimb[i] || { qty: 0, rate: 0 };
                    if (document.getElementById(`sq-ed-reimb-qty-${i}`)) document.getElementById(`sq-ed-reimb-qty-${i}`).value = row.qty;
                    if (document.getElementById(`sq-ed-reimb-rate-${i}`)) document.getElementById(`sq-ed-reimb-rate-${i}`).value = row.rate;
                }

                const abs = (details.absence_deductions && details.absence_deductions.length) ? details.absence_deductions : [
                    { qty: 0, rate: 10000 }, { qty: 0, rate: 10000 }, { qty: 0, rate: 40385 }
                ];
                for (let i = 0; i < 3; i++) {
                    const row = abs[i] || { qty: 0, rate: 0 };
                    if (document.getElementById(`sq-ed-abs-qty-${i}`)) document.getElementById(`sq-ed-abs-qty-${i}`).value = row.qty;
                    if (document.getElementById(`sq-ed-abs-rate-${i}`)) document.getElementById(`sq-ed-abs-rate-${i}`).value = row.rate;
                }

                const oth = (details.other_deductions && details.other_deductions.length) ? details.other_deductions : [
                    { qty: 2, rate: 100000 }, { qty: 0, rate: 25000 }, { qty: 0, rate: 6000 }
                ];
                for (let i = 0; i < 3; i++) {
                    const row = oth[i] || { qty: 0, rate: 0 };
                    if (document.getElementById(`sq-ed-oth-qty-${i}`)) document.getElementById(`sq-ed-oth-qty-${i}`).value = row.qty;
                    if (document.getElementById(`sq-ed-oth-rate-${i}`)) document.getElementById(`sq-ed-oth-rate-${i}`).value = row.rate;
                }

                const loans = (details.loan_installments && details.loan_installments.length) ? details.loan_installments : [
                    { qty: 0, rate: 0 }
                ];
                if (document.getElementById('sq-ed-loan-qty-0')) document.getElementById('sq-ed-loan-qty-0').value = (loans[0] ? loans[0].qty : 0) || 0;
                if (document.getElementById('sq-ed-loan-rate-0')) document.getElementById('sq-ed-loan-rate-0').value = (loans[0] ? loans[0].rate : 0) || 0;

                const notes = (details.notes_list && details.notes_list.length) ? details.notes_list : [
                    "Lembur 11 Jam",
                    "Uang makan diambil harian"
                ];
                if (document.getElementById('sq-ed-notes-list')) {
                    document.getElementById('sq-ed-notes-list').value = notes.join('\n');
                }

                // Status & Catatan Standar
                document.getElementById('ped-payment-status').value = p.payment_status || 'GENERATED';
                document.getElementById('ped-notes').value = p.notes || '';

                // Default tab ke Starqua
                switchPayrollEditorTab('starqua');

                const modalEl = document.getElementById('payroll-editor-modal');
                if (modalEl) modalEl.classList.remove('hidden');
                if (typeof lucide !== 'undefined' && lucide.createIcons) lucide.createIcons();
            } catch (err) {
                console.error(err);
                alert('Gagal membuka editor payroll');
            }
        }

        function closePayrollEditorModal() {
            const modalEl = document.getElementById('payroll-editor-modal');
            if (modalEl) modalEl.classList.add('hidden');
        }

        function recalcPayrollEditorTotals() {
            const attDays = parseInt(_val('ped-attendance-days')) || 0;
            const rateTrans = parseFloat(_val('ped-daily-transport-rate')) || 0;
            const transTotal = attDays * rateTrans;
            if (document.getElementById('ped-transport-total')) document.getElementById('ped-transport-total').value = transTotal;

            const baseSal = parseFloat(_val('ped-base-salary')) || 0;
            const allow = parseFloat(_val('ped-allowance')) || 0;
            const comm = parseFloat(_val('ped-sales-commission')) || 0;
            const overtime = parseFloat(_val('ped-overtime-pay')) || 0;
            const bonus = parseFloat(_val('ped-bonus-pay')) || 0;

            const gross = baseSal + allow + transTotal + comm + overtime + bonus;

            const late = parseFloat(_val('ped-late-deduction')) || 0;
            const absence = parseFloat(_val('ped-absence-deduction')) || 0;
            const loan = parseFloat(_val('ped-loan-deduction')) || 0;
            const tax = parseFloat(_val('ped-tax-deduction')) || 0;
            const other = parseFloat(_val('ped-other-deduction')) || 0;

            const deductions = late + absence + loan + tax + other;
            const net = Math.max(0, gross - deductions);

            document.getElementById('ped-summary-gross').innerText = `1. Rp ${formatCleanNumber(gross)}`;
            document.getElementById('ped-summary-reimb').innerText = `2. Rp 0`;
            document.getElementById('ped-summary-abs').innerText = `3. Rp ${formatCleanNumber(late + absence)}`;
            document.getElementById('ped-summary-oth').innerText = `4. Rp ${formatCleanNumber(other + tax)}`;
            document.getElementById('ped-summary-loan').innerText = `5. Rp ${formatCleanNumber(loan)}`;
            document.getElementById('ped-summary-net').innerText = formatRupiah(net);
        }

        async function handleSavePayrollEditor(e) {
            e.preventDefault();

            const curPayslip = payrollModuleState.currentPayslip || {};
            const curDetails = curPayslip.details || {};
            const curUser = curPayslip.user || {};

            // Mengumpulkan data Starqua
            const baseSalary = parseFloat(_val('sq-ed-base-salary')) || 0;

            const incNames = ['Air Mineral', 'Es Kristal', 'Gas', 'RO', 'Aqua', 'Penjualan Depot', 'Warung'];
            const incUnits = ['Galon', 'Order', 'Tabung', 'Galon', 'Galon', 'Hari', 'Galon'];
            const compiledIncentives = [];
            let totIncentives = 0;
            for (let i = 0; i < 7; i++) {
                const q = parseFloat(_val(`sq-ed-inc-qty-${i}`)) || 0;
                const r = parseFloat(_val(`sq-ed-inc-rate-${i}`)) || 0;
                const tot = q * r;
                totIncentives += tot;
                compiledIncentives.push({
                    name: incNames[i],
                    qty: q,
                    unit: incUnits[i],
                    rate: r,
                    total: tot
                });
            }

            const facNames = ['Uang Makan', 'BPJS Kesehatan', 'Bonus Pencapaian 600 Galon', 'Bonus Pencapaian Es Kristal', 'Bonus Pencapaian RO 200 Galon'];
            const facUnits = ['Hari', 'Bulan', 'Target', 'Target', 'Target'];
            const compiledFacilities = [];
            let totFacilities = 0;
            let uangMakanHari = 0;
            for (let i = 0; i < 5; i++) {
                const q = parseFloat(_val(`sq-ed-fac-qty-${i}`)) || 0;
                const r = parseFloat(_val(`sq-ed-fac-rate-${i}`)) || 0;
                const tot = q * r;
                totFacilities += tot;
                if (i === 0) uangMakanHari = q;
                compiledFacilities.push({
                    name: facNames[i],
                    qty: q,
                    unit: facUnits[i],
                    rate: r,
                    total: tot
                });
            }

            const overageRate = parseFloat(_val('sq-ed-overage-rate')) || 0;
            const compiledOverage = [{
                name: 'Lebih Setoran',
                qty: overageRate > 0 ? 1 : 0,
                unit: 'Total',
                rate: overageRate,
                total: overageRate
            }];

            const sub1 = baseSalary + totIncentives + totFacilities + overageRate;

            const reimbNames = ['Biaya Lembur', 'Biaya Bensin'];
            const reimbUnits = ['Jam', 'Bon'];
            const compiledReimbursements = [];
            let sub2 = 0;
            let lemburNominal = 0;
            for (let i = 0; i < 2; i++) {
                const q = parseFloat(_val(`sq-ed-reimb-qty-${i}`)) || 0;
                const r = parseFloat(_val(`sq-ed-reimb-rate-${i}`)) || 0;
                const tot = q * r;
                sub2 += tot;
                if (i === 0) lemburNominal = tot;
                compiledReimbursements.push({
                    name: reimbNames[i],
                    qty: q,
                    unit: reimbUnits[i],
                    rate: r,
                    total: tot
                });
            }

            const absNames = ['Keterlambatan', 'Pulang Awal', 'Absen Tanpa Surat Dokter'];
            const compiledAbsence = [];
            let sub3 = 0;
            for (let i = 0; i < 3; i++) {
                const q = parseFloat(_val(`sq-ed-abs-qty-${i}`)) || 0;
                const r = parseFloat(_val(`sq-ed-abs-rate-${i}`)) || 0;
                const tot = q * r;
                sub3 += tot;
                compiledAbsence.push({
                    name: absNames[i],
                    qty: q,
                    unit: 'Hari',
                    rate: r,
                    total: tot
                });
            }

            const othNames = ['Kasbon tgl 7,14,21', 'selisih gas', 'Selisih RO 1'];
            const othUnits = ['Tanggal', 'Pcs', 'Pcs'];
            const compiledOther = [];
            let sub4 = 0;
            let kasbonNominal = 0;
            for (let i = 0; i < 3; i++) {
                const q = parseFloat(_val(`sq-ed-oth-qty-${i}`)) || 0;
                const r = parseFloat(_val(`sq-ed-oth-rate-${i}`)) || 0;
                const tot = q * r;
                sub4 += tot;
                if (i === 0) kasbonNominal = tot;
                compiledOther.push({
                    name: othNames[i],
                    qty: q,
                    unit: othUnits[i],
                    rate: r,
                    total: tot
                });
            }

            const loanQ = parseFloat(_val('sq-ed-loan-qty-0')) || 0;
            const loanR = parseFloat(_val('sq-ed-loan-rate-0')) || 0;
            const sub5 = loanQ * loanR;
            const compiledLoans = [{
                name: 'Cicilan',
                qty: loanQ,
                unit: 'Tanggal',
                rate: loanR,
                total: sub5
            }];

            const rawNotes = _val('sq-ed-notes-list') || '';
            const compiledNotes = rawNotes.split('\n').map(s => s.trim()).filter(s => s.length > 0);

            const detailsObj = {
                template: 'starqua',
                join_date: curDetails.join_date || curUser.join_date || '2024-07-13',
                incentives: compiledIncentives,
                facilities: compiledFacilities,
                overage: compiledOverage,
                reimbursements: compiledReimbursements,
                absence_deductions: compiledAbsence,
                other_deductions: compiledOther,
                loan_installments: compiledLoans,
                notes_list: compiledNotes
            };

            const deductions = sub3 + sub4 + sub5;
            const gross = sub1 + sub2;
            const net = Math.max(0, gross - deductions);

            const payload = {
                user_id: parseInt(document.getElementById('ped-user-id').value),
                branch_id: parseInt(document.getElementById('ped-branch-id').value) || 1,
                period_month: document.getElementById('ped-period-month').value,
                base_salary: baseSalary,
                allowance: totFacilities,
                attendance_days: uangMakanHari || 22,
                daily_transport_rate: 10000,
                transport_total: (uangMakanHari || 22) * 10000,
                sales_commission: totIncentives,
                overtime_pay: lemburNominal,
                bonus_pay: (sub2 - lemburNominal) + overageRate,
                gross_salary: gross,
                late_deduction: ((compiledAbsence[0] ? compiledAbsence[0].total : 0) || 0),
                absence_deduction: ((compiledAbsence[1] ? compiledAbsence[1].total : 0) || 0) + ((compiledAbsence[2] ? compiledAbsence[2].total : 0) || 0),
                loan_deduction: kasbonNominal + sub5,
                tax_deduction: 0,
                other_deduction: (sub4 - kasbonNominal),
                total_deductions: deductions,
                net_salary: net,
                payment_status: document.getElementById('ped-payment-status').value,
                notes: document.getElementById('ped-notes').value || 'Slip Gaji Rinci Starqua',
                details_json: detailsObj
            };

            try {
                const res = await fetch('api.php?action=generate_or_save_payroll', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                if (data.success) {
                    alert(data.message || 'Slip gaji berhasil disimpan & diverifikasi!');
                    closePayrollEditorModal();
                    loadPayrollModule();
                    // Buka kembali preview slip gaji yang telah diperbarui
                    openPayrollSlipModal(payload.user_id, payload.period_month);
                } else {
                    alert(data.error || 'Gagal menyimpan slip gaji.');
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan koneksi server saat menyimpan payroll.');
            }
        }
        async function resetOfficialPayroll() {
            if (!payrollModuleState.currentPayslip) return;
            const u = payrollModuleState.currentPayslip.user;
            const m = payrollModuleState.currentPayslip.month;

            if (!confirm(`Reset data slip gaji ${u.name} periode ${m} ke hitungan otomatis sistem?`)) {
                return;
            }

            try {
                const res = await fetch(`api.php?action=delete_saved_payroll&user_id=${u.id}&month=${m}`);
                const data = await res.json();
                alert(data.message || 'Data berhasil direset');
                closePayrollSlipModal();
                loadPayrollModule();
            } catch (err) {
                console.error(err);
                alert('Gagal mereset data slip gaji');
            }
        }

        // --- 7. Pinjaman / Kasbon Gaji Karyawan ---
        async function loadSalaryLoans() {
            try {
                const curUser = state.currentUser || state.loggedInUser || { id: 3, role: 'CASHIER' };
                const isManager = isManagerOrSuperAdminUser(curUser);
                const userBranchId = curUser.branch_id || (state.currentBranch ? state.currentBranch.id : 1);
                const role = (curUser.role || 'CASHIER').toUpperCase().trim();
                const isSuperAdmin = (role === 'SUPERADMIN' || role === 'SUPER_ADMIN' || role === 'SUPER ADMIN');
                const bId = (!isSuperAdmin && userBranchId) ? userBranchId : (state.currentBranch ? state.currentBranch.id : 1);
                const curUserId = curUser.id || 3;

                // Load loans
                const res = await fetch(`api.php?action=get_salary_loans&branch_id=${bId}&user_id=${curUserId}`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const loans = data.loans || [];

                // Calculate personal plafon
                const userLoans = loans.filter(l => l.user_id == curUserId && l.status === 'ACTIVE');
                const curDebt = userLoans.reduce((acc, l) => acc + (parseFloat(l.remaining_amount) || 0), 0);
                const baseSal = (curUser && curUser.base_salary) ? curUser.base_salary : 3000000;
                const maxPlafon = baseSal * 0.7;
                const available = Math.max(0, maxPlafon - curDebt);

                document.getElementById('loan-max-plafon').innerText = formatRupiah(maxPlafon);
                document.getElementById('loan-current-debt').innerText = formatRupiah(curDebt);
                document.getElementById('loan-available-limit').innerText = formatRupiah(available);

                // Render Table
                const tbody = document.getElementById('ess-loans-table-body');
                if (!tbody) return;

                tbody.innerHTML = loans.map(l => `
                    <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50">
                        <td class="py-2.5 px-3">
                            <span class="font-bold text-slate-800 dark:text-slate-100">${l.employee_name}</span>
                            <span class="text-slate-400 block text-[10px] font-mono">${l.employee_nik}</span>
                        </td>
                        <td class="py-2.5 px-3 font-mono text-slate-600 dark:text-slate-300">${l.loan_date}</td>
                        <td class="py-2.5 px-3 text-right font-mono font-bold text-slate-900 dark:text-slate-100">${formatRupiah(l.amount)}</td>
                        <td class="py-2.5 px-3 text-right font-mono text-rose-600 dark:text-rose-400">${formatRupiah(l.monthly_deduction)}/bln <span class="text-[10px] text-slate-400">(${l.installment_months}x)</span></td>
                        <td class="py-2.5 px-3 text-right font-mono font-bold ${l.remaining_amount > 0 ? 'text-amber-700 dark:text-amber-400' : 'text-emerald-700 dark:text-emerald-400'}">${formatRupiah(l.remaining_amount)}</td>
                        <td class="py-2.5 px-3">
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${
                                l.status === 'PAID' ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-950/60 dark:text-emerald-400' :
                                (l.status === 'ACTIVE' ? 'bg-blue-100 text-blue-800 dark:bg-blue-950/60 dark:text-blue-400' :
                                (l.status === 'REJECTED' ? 'bg-rose-100 text-rose-800 dark:bg-rose-950/60 dark:text-rose-400' : 'bg-amber-100 text-amber-800 dark:bg-amber-950/60 dark:text-amber-400'))
                            }">
                                ${l.status === 'PAID' ? '✓ LUNAS' : (l.status === 'ACTIVE' ? 'AKTIF (POTONG GAJI)' : (l.status === 'REJECTED' ? '✕ DITOLAK' : '⏳ PENDING'))}
                            </span>
                        </td>
                        <td class="py-2.5 px-3 text-center">
                            <div class="flex items-center justify-center space-x-1">
                                ${l.status === 'PENDING' ? (
                                    isManager ? `
                                        <button onclick="approveSalaryLoan(${l.id}, 'APPROVE')" class="px-2 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold shadow-xs">Setujui</button>
                                        <button onclick="approveSalaryLoan(${l.id}, 'REJECT')" class="px-2 py-1 bg-rose-600 hover:bg-rose-700 text-white rounded-lg text-[10px] font-bold shadow-xs">Tolak</button>
                                    ` : `<span class="text-[10px] text-amber-700 dark:text-amber-400 font-semibold">⏳ Menunggu</span>`
                                ) : (l.status === 'ACTIVE' && l.remaining_amount > 0 ? `
                                    <button onclick="openLoanRepayModal(${l.id}, ${l.remaining_amount})" class="px-2 py-1 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-[10px] font-bold shadow-xs">Bayar Angsuran</button>
                                ` : `<span class="text-[10px] text-slate-400">Tuntas</span>`)}
                                ${(isManager || l.user_id == curUser.id) ? `
                                    <button onclick="deleteSalaryLoan(${l.id})" title="Hapus Riwayat Kasbon" class="p-1 text-slate-400 hover:text-rose-600 rounded-lg transition-colors ml-1">
                                        <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                                    </button>
                                ` : ''}
                            </div>
                        </td>
                    </tr>
                `).join('') || `<tr><td colspan="7" class="text-center py-4 text-slate-400">Belum ada riwayat pengajuan kasbon</td></tr>`;

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function calculateLoanSimulation() {
            const amount = parseFloat(_val('loan-amount-input')) || 0;
            const tenor = parseInt(_val('loan-tenor-select')) || 1;
            const deduction = tenor > 0 ? Math.round(amount / tenor) : 0;
            const targetEl = document.getElementById('loan-simulation-deduction');
            if (targetEl) targetEl.value = formatRupiah(deduction);
        }

        async function submitSalaryLoanForm(e) {
            e.preventDefault();
            const curUser = state.currentUser || state.loggedInUser || { id: 3, role: 'CASHIER' };
            const curUserId = curUser.id;
            const userBranchId = curUser.branch_id || (state.currentBranch ? state.currentBranch.id : 1);
            const amount = parseFloat(document.getElementById('loan-amount-input').value) || 0;
            const tenor = parseInt(document.getElementById('loan-tenor-select').value) || 1;
            const reason = document.getElementById('loan-reason-input').value;

            const res = await fetch('api.php?action=submit_salary_loan', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    user_id: curUserId,
                    branch_id: userBranchId,
                    amount,
                    installment_months: tenor,
                    reason
                })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                document.getElementById('loan-amount-input').value = '';
                document.getElementById('loan-reason-input').value = '';
                document.getElementById('loan-simulation-deduction').value = 'Rp 0';
                loadSalaryLoans();
            }
        }

        async function approveSalaryLoan(loanId, action) {
            const reason = action === 'REJECT' ? prompt('Alasan penolakan (opsional):') : '';
            const approverId = state.currentUser ? state.currentUser.id : 1;

            const res = await fetch('api.php?action=approve_salary_loan', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ loan_id: loanId, action, user_id: approverId, rejection_reason: reason })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadSalaryLoans();
            }
        }

        async function deleteSalaryLoan(loanId) {
            if (!confirm('Hapus riwayat data pinjaman kasbon ini?')) return;
            const curUserId = state.currentUser ? state.currentUser.id : 1;
            try {
                const res = await fetch('api.php?action=delete_salary_loan', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ loan_id: loanId, user_id: curUserId })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    loadSalaryLoans();
                }
            } catch (err) {
                console.error(err);
                alert('Gagal menghapus kasbon: ' + err.message);
            }
        }

        async function clearAllSalaryLoans() {
            if (!confirm('Yakin ingin mengosongkan SELURUH riwayat kasbon karyawan? Tindakan ini tidak dapat dibatalkan.')) return;
            const curUserId = state.currentUser ? state.currentUser.id : 1;
            const userBranchId = (state.currentUser && state.currentUser.branch_id) || (state.currentBranch ? state.currentBranch.id : 1);
            try {
                const res = await fetch('api.php?action=clear_all_salary_loans', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ branch_id: userBranchId, user_id: curUserId })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    loadSalaryLoans();
                }
            } catch (err) {
                console.error(err);
                alert('Gagal mengosongkan kasbon: ' + err.message);
            }
        }

        function openLoanRepayModal(loanId, remaining) {
            const modal = document.getElementById('loan-repay-modal');
            if (!modal) return;
            document.getElementById('loan-repay-id').value = loanId;
            document.getElementById('loan-repay-sub').innerText = `Sisa Utang: ${formatRupiah(remaining)}`;
            document.getElementById('loan-repay-amount').value = remaining;
            modal.classList.remove('hidden');
        }

        function closeLoanRepayModal() {
            _cls('loan-repay-modal', 'add', 'hidden');
        }

        async function submitLoanRepayForm(e) {
            e.preventDefault();
            const loanId = document.getElementById('loan-repay-id').value;
            const amount = parseFloat(document.getElementById('loan-repay-amount').value) || 0;
            const notes = document.getElementById('loan-repay-notes').value;

            const res = await fetch('api.php?action=pay_salary_loan', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ loan_id: loanId, amount_paid: amount, notes })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeLoanRepayModal();
                loadSalaryLoans();
            }
        }

        // ==========================================
        // 4. KARYAWAN CRUD (EMPLOYEES) & SHIFT MAPPING
        // ==========================================
        let allEmployeesData = [];
        let currentEditingEmployee = null;
        let currentScheduleEmployee = null;
        let currentEmployeeScheduleData = null;

        async function ensureWorkShiftsLoaded() {
            if (!essWorkShiftsList || essWorkShiftsList.length === 0) {
                try {
                    const res = await fetch('api.php?action=get_work_shifts');
                    const data = await res.json();
                    if (data.success) {
                        essWorkShiftsList = data.shifts || [];
                    }
                } catch (e) {
                    console.error('Failed to load work shifts:', e);
                }
            }
            return essWorkShiftsList;
        }

        function populateEmployeeTableBranchFilter() {
            const filterSelect = document.getElementById('emp-table-branch-filter');
            if (!filterSelect) return;
            const currentVal = filterSelect.value || 'ALL';
            let opts = [
                '<option value="ALL">🌐 Semua Penempatan (Global & Seluruh Cabang)</option>',
                '<option value="GLOBAL">🌐 Penempatan Global Saja (Super Admin)</option>'
            ];
            (state.branches || []).forEach(b => {
                opts.push(`<option value="${b.id}">🏪 Cabang: ${b.name}</option>`);
            });
            filterSelect.innerHTML = opts.join('');
            if (opts.some(o => o.includes(`value="${currentVal}"`))) {
                filterSelect.value = currentVal;
            } else {
                filterSelect.value = 'ALL';
            }
        }

        function renderFilteredEmployeesTable() {
            const tbody = document.getElementById('employee-table-body');
            if (!tbody) return;

            const q = (_val('emp-table-search') || '').toLowerCase().trim();
            const branchFilter = _val('emp-table-branch-filter') || 'ALL';

            const filtered = (allEmployeesData || []).filter(e => {
                // Search filter
                if (q) {
                    const matchNik = (e.nik || '').toLowerCase().includes(q);
                    const matchName = (e.name || '').toLowerCase().includes(q);
                    const matchRole = (e.role || '').toLowerCase().includes(q);
                    const matchEmail = (e.email || '').toLowerCase().includes(q);
                    const matchPhone = (e.phone || '').toLowerCase().includes(q);
                    const matchBranch = (e.branch_name || '').toLowerCase().includes(q);
                    if (!matchNik && !matchName && !matchRole && !matchEmail && !matchPhone && !matchBranch) {
                        return false;
                    }
                }

                // Branch placement filter
                const roleClean = (e.role || '').toUpperCase().replace(/_/g, '');
                const isSuper = ['SUPERADMIN', 'SUPER_ADMIN'].includes(roleClean) || e.assigned_branch_ids === 'ALL';

                if (branchFilter === 'GLOBAL') {
                    return isSuper;
                } else if (branchFilter !== 'ALL') {
                    const targetBId = parseInt(branchFilter);
                    if (isSuper) {
                        return false; // Global placement doesn't tie to single physical branch filter
                    }
                    if (Array.isArray(e.assigned_branch_ids)) {
                        return e.assigned_branch_ids.includes(targetBId);
                    }
                    return parseInt(e.branch_id) === targetBId;
                }

                return true;
            });

            if (filtered.length === 0) {
                tbody.innerHTML = `
                    <tr>
                        <td colspan="9" class="py-8 text-center text-slate-400">
                            <i data-lucide="users" class="w-8 h-8 mx-auto mb-2 opacity-40"></i>
                            <p class="font-bold text-xs">Tidak ada data karyawan yang sesuai filter / pencarian.</p>
                        </td>
                    </tr>
                `;
                lucide.createIcons();
                return;
            }

            tbody.innerHTML = filtered.map(e => {
                const roleClean = (e.role || '').toUpperCase().replace(/_/g, '');
                const isSuper = ['SUPERADMIN', 'SUPER_ADMIN'].includes(roleClean) || e.assigned_branch_ids === 'ALL';
                const isManager = ['BRANCHMANAGER', 'BRANCH_MANAGER', 'MANAGER'].includes(roleClean);
                const isExempt = isSuper || isManager;

                // Shift badge
                let shiftBadge = '';
                if (isExempt) {
                    shiftBadge = `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700">Fleksibel (Manajerial)</span>`;
                } else if (e.default_shift_name) {
                    shiftBadge = `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-50 dark:bg-indigo-950/60 text-indigo-700 dark:text-indigo-300 border border-indigo-200 dark:border-indigo-800">${e.default_shift_code ? '[' + e.default_shift_code + '] ' : ''}${e.default_shift_name}</span>`;
                } else {
                    shiftBadge = `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-50 dark:bg-amber-950/60 text-amber-700 dark:text-amber-300 border border-amber-200 dark:border-amber-800">Belum Diset</span>`;
                }

                // Branch placement badge
                let branchPlacementHtml = '';
                if (isSuper) {
                    branchPlacementHtml = `
                        <div class="inline-flex items-center space-x-1.5 px-2.5 py-1 rounded-full text-[10px] font-black bg-gradient-to-r from-purple-100 to-indigo-100 dark:from-purple-950/70 dark:to-indigo-950/70 text-purple-900 dark:text-purple-300 border border-purple-200 dark:border-purple-800 shadow-2xs">
                            <span>🌐</span>
                            <span>Global (Seluruh Cabang)</span>
                        </div>
                    `;
                } else if (isManager) {
                    const assignedBranches = Array.isArray(e.assigned_branches) ? e.assigned_branches : [];
                    const count = assignedBranches.length;
                    if (count > 0) {
                        const names = assignedBranches.map(b => b.name).join(', ');
                        branchPlacementHtml = `
                            <div class="space-y-1">
                                <div class="inline-flex items-center space-x-1 px-2 py-0.5 rounded-md text-[10px] font-black bg-blue-100 dark:bg-blue-950/70 text-blue-900 dark:text-blue-300 border border-blue-200 dark:border-blue-800" title="${names}">
                                    <i data-lucide="building-2" class="w-3 h-3 text-blue-700 dark:text-blue-400"></i>
                                    <span>${count} Cabang Terhubung</span>
                                </div>
                                <div class="text-[10px] text-slate-600 dark:text-slate-400 font-medium truncate max-w-[200px]" title="${names}">
                                    ${names}
                                </div>
                            </div>
                        `;
                    } else {
                        branchPlacementHtml = `
                            <div class="inline-flex items-center space-x-1 px-2 py-0.5 rounded-md text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
                                <span>${e.branch_name || 'Belum Diset'}</span>
                            </div>
                        `;
                    }
                } else {
                    branchPlacementHtml = `
                        <div class="inline-flex items-center space-x-1 px-2 py-0.5 rounded-md text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-700">
                            <i data-lucide="map-pin" class="w-2.5 h-2.5 text-indigo-500"></i>
                            <span>${e.branch_name || 'Semua Cabang'}</span>
                        </div>
                    `;
                }

                return `
                <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/60 transition-colors">
                    <td class="py-2.5 px-4 font-mono font-bold text-indigo-700 dark:text-indigo-400">${e.nik}</td>
                    <td class="py-2.5 px-4 font-semibold text-slate-800 dark:text-slate-100">${e.name}</td>
                    <td class="py-2.5 px-4"><span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold ${isSuper ? 'bg-purple-100 dark:bg-purple-950/80 text-purple-800 dark:text-purple-300 border border-purple-200 dark:border-purple-800' : (isManager ? 'bg-blue-100 dark:bg-blue-950/80 text-blue-800 dark:text-blue-300 border border-blue-200 dark:border-blue-800' : 'bg-slate-200 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-300 dark:border-slate-700')}">${e.role}</span></td>
                    <td class="py-2.5 px-4">${branchPlacementHtml}</td>
                    <td class="py-2.5 px-4 text-slate-600 dark:text-slate-300 font-mono text-xs">${e.email || '-'} / ${e.phone || '-'}</td>
                    <td class="py-2.5 px-4">${shiftBadge}</td>
                    <td class="py-2.5 px-4">
                        <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${e.is_active ? 'bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800' : 'bg-rose-100 dark:bg-rose-950/80 text-rose-800 dark:text-rose-300 border border-rose-200 dark:border-rose-800'}">
                            ${e.is_active ? 'Aktif' : 'Nonaktif'}
                        </span>
                    </td>
                    <td class="py-2.5 px-4 text-center space-x-1 whitespace-nowrap">
                        <button onclick="editEmployeeById(${e.id})" class="px-2.5 py-1 bg-indigo-50 dark:bg-indigo-950/60 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-100 dark:hover:bg-indigo-900/60 rounded-lg text-[11px] font-bold transition-colors">Edit</button>
                        <button onclick="openEmployeeScheduleModalById(${e.id})" class="px-2.5 py-1 bg-purple-50 dark:bg-purple-950/60 text-purple-700 dark:text-purple-400 hover:bg-purple-100 dark:hover:bg-purple-900/60 rounded-lg text-[11px] font-bold transition-colors" title="Detail & Petakan Jadwal Shift">🗓️ Jadwal Shift</button>
                        <button onclick="openPayrollSlipModal(${e.id})" class="px-2.5 py-1 bg-emerald-50 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-400 hover:bg-emerald-100 dark:hover:bg-emerald-900/60 rounded-lg text-[11px] font-bold transition-colors" title="Lihat Slip Gaji Karyawan">💵 Slip Gaji</button>
                        ${e.id !== 1 ? `<button onclick="deleteEmployee(${e.id})" class="px-2.5 py-1 bg-rose-50 dark:bg-rose-950/60 text-rose-600 dark:text-rose-400 hover:bg-rose-100 dark:hover:bg-rose-900/60 rounded-lg text-[11px] font-bold transition-colors">Nonaktifkan</button>` : ''}
                    </td>
                </tr>
            `}).join('');
            lucide.createIcons();
        }

        async function loadEmployees() {
            await ensureWorkShiftsLoaded();
            populateEmployeeTableBranchFilter();
            try {
                const res = await fetch('api.php?action=get_employees');
                const data = await res.json();
                if (!data.success) {
                    console.error('Fetch employees failed:', data.error || 'Unknown error');
                    return;
                }
                allEmployeesData = data.employees || [];
                renderFilteredEmployeesTable();
            } catch (err) {
                console.error('Load employees error:', err);
            }
        }

        function editEmployeeById(id) {
            const emp = (allEmployeesData || []).find(u => u.id == id);
            if (emp) editEmployee(emp);
        }

        function openEmployeeScheduleModalById(id) {
            const emp = (allEmployeesData || []).find(u => u.id == id);
            if (emp) openEmployeeScheduleModal(emp);
        }

        function renderEmployeeMultiBranchCheckboxes(selectedIds = []) {
            const container = document.getElementById('emp-multi-branch-checkboxes');
            if (!container) return;
            const branches = state.branches || [];
            const selSet = new Set((selectedIds || []).map(x => parseInt(x)));

            container.innerHTML = branches.map(b => {
                const isChecked = selSet.has(parseInt(b.id));
                return `
                    <label class="flex items-center space-x-2 p-2 rounded-xl border border-slate-100 hover:bg-slate-50 cursor-pointer text-xs select-none transition-colors">
                        <input type="checkbox" name="emp_multi_branch_cb" value="${b.id}" ${isChecked ? 'checked' : ''} onchange="updateEmployeeMultiBranchCount()" class="w-4 h-4 rounded text-indigo-600 focus:ring-indigo-500 border-slate-300">
                        <span class="font-bold text-slate-700">${b.name}</span>
                    </label>
                `;
            }).join('');

            updateEmployeeMultiBranchCount();
        }

        function updateEmployeeMultiBranchCount() {
            const checked = document.querySelectorAll('input[name="emp_multi_branch_cb"]:checked');
            const badge = document.getElementById('emp-multi-branch-count-badge');
            if (badge) {
                badge.innerText = `${checked.length} Cabang`;
            }
        }

        function selectAllEmployeeBranches(check = true) {
            const checkboxes = document.querySelectorAll('input[name="emp_multi_branch_cb"]');
            checkboxes.forEach(cb => { cb.checked = check; });
            updateEmployeeMultiBranchCount();
        }

        async function openEmployeeModal(isEdit = false) {
            if (isEdit) {
                if (!hasUserPerm('employees', 'update')) {
                    showToast('Akses Ditolak: Peran Anda tidak memiliki izin untuk mengedit data karyawan!', 'error');
                    return false;
                }
            } else {
                if (!hasUserPerm('employees', 'create')) {
                    showToast('Akses Ditolak: Peran Anda tidak memiliki izin untuk menambah data karyawan!', 'error');
                    return false;
                }
            }
            currentEditingEmployee = null;
            await ensureWorkShiftsLoaded();

            document.getElementById('emp-id').value = '';
            document.getElementById('emp-nik').value = '';
            document.getElementById('emp-name').value = '';
            document.getElementById('emp-email').value = '';
            document.getElementById('emp-phone').value = '';
            document.getElementById('emp-password').value = '';
            document.getElementById('emp-pin').value = '123456';
            if (document.getElementById('emp-commission')) document.getElementById('emp-commission').value = '0';
            const elJoinDate = document.getElementById('emp-join-date');
            if (elJoinDate) elJoinDate.value = '';
            document.getElementById('emp-modal-title').innerText = 'Tambah Karyawan Baru';

            // Populate role options (Default: CASHIER)
            renderEmployeeRoleOptions('CASHIER');

            const curUser = state.currentUser || state.loggedInUser;
            const canSwitchBranch = curUser && (Number(curUser.can_access_all_branches) === 1 || ['SUPER_ADMIN', 'SUPERADMIN'].includes((curUser.role || '').toUpperCase().replace(/_/g, '')));
            const branchSelect = document.getElementById('emp-branch');
            if (!canSwitchBranch) {
                const uBId = curUser ? curUser.branch_id : (state.currentBranch ? state.currentBranch.id : 1);
                const uBranch = (state.branches || []).find(b => b.id == uBId) || state.currentBranch;
                branchSelect.innerHTML = `<option value="${uBranch.id}" selected>${uBranch.name}</option>`;
                branchSelect.disabled = true;
                branchSelect.title = "Karyawan cabang hanya dapat menambahkan/mengedit staf pada cabang penempatan yang sama.";
            } else {
                branchSelect.disabled = false;
                branchSelect.innerHTML = (state.branches || []).map(b => 
                    `<option value="${b.id}" ${b.id === (state.currentBranch ? state.currentBranch.id : 1) ? 'selected' : ''}>${b.name}</option>`
                ).join('');
            }

            // Reset multi-branch checkboxes
            renderEmployeeMultiBranchCheckboxes([]);

            // Populate default shifts & courier vehicles
            renderEmployeeModalShiftOptions();
            renderEmployeeModalVehicleOptions(state.currentBranch ? state.currentBranch.id : 1);
            document.getElementById('emp-branch').onchange = () => {
                renderEmployeeModalVehicleOptions(document.getElementById('emp-branch').value);
            };

            // Set role change listener
            const roleSelect = document.getElementById('emp-role');
            roleSelect.onchange = handleEmployeeRoleChange;
            handleEmployeeRoleChange();

            _cls('emp-shift-detail-action', 'add', 'hidden');
            document.getElementById('employee-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function renderEmployeeModalShiftOptions(selectedId = null) {
            const shiftSelect = document.getElementById('emp-default-shift');
            if (!shiftSelect) return;
            const options = ['<option value="">-- Pilih Shift Kerja Bawaan --</option>'];
            (essWorkShiftsList || []).forEach(ws => {
                const timeInfo = ws.is_day_off ? 'Hari Libur / Off' : `${ws.start_time} - ${ws.end_time}`;
                options.push(`<option value="${ws.id}" ${ws.id == selectedId ? 'selected' : ''}>${ws.code} - ${ws.name} (${timeInfo})</option>`);
            });
            shiftSelect.innerHTML = options.join('');
        }

        function renderEmployeeModalVehicleOptions(branchId, selectedVehId = null) {
            const vehSelect = document.getElementById('emp-assigned-vehicle');
            if (!vehSelect) return;
            const bId = branchId ? parseInt(branchId) : 1;
            const branchVehs = (state.vehicles || []).filter(v => (!v.branch_id || v.branch_id === bId) && v.status === 'ACTIVE');
            let opts = ['<option value="">-- Tidak Terhubung ke Armada (Bukan Kurir) --</option>'];
            branchVehs.forEach(v => {
                opts.push(`<option value="${v.id}" ${v.id == selectedVehId ? 'selected' : ''}>${v.plate_number} - ${v.vehicle_name} (${v.driver_name || 'Tanpa Driver'})</option>`);
            });
            vehSelect.innerHTML = opts.join('');
        }

        function handleEmployeeRoleChange() {
            const role = (document.getElementById('emp-role').value || '').toUpperCase().replace(/_/g, '');
            const isSuper = ['SUPERADMIN', 'SUPER_ADMIN'].includes(role);
            const isManager = ['BRANCHMANAGER', 'BRANCH_MANAGER', 'MANAGER'].includes(role);
            const isExempt = isSuper || isManager;

            const pickerGroup = document.getElementById('emp-shift-picker-group');
            const exemptNotice = document.getElementById('emp-shift-exempt-notice');
            const detailAction = document.getElementById('emp-shift-detail-action');

            if (isExempt) {
                if (pickerGroup) pickerGroup.classList.add('hidden');
                if (exemptNotice) exemptNotice.classList.remove('hidden');
                if (detailAction) detailAction.classList.add('hidden');
                const defShift = document.getElementById('emp-default-shift');
                if (defShift) defShift.value = '';
            } else {
                if (pickerGroup) pickerGroup.classList.remove('hidden');
                if (exemptNotice) exemptNotice.classList.add('hidden');
                if (currentEditingEmployee && currentEditingEmployee.id) {
                    if (detailAction) detailAction.classList.remove('hidden');
                } else {
                    if (detailAction) detailAction.classList.add('hidden');
                }
            }

            // Branch Placement UI toggling
            const globalGroup = document.getElementById('emp-branch-global-group');
            const multiGroup = document.getElementById('emp-branch-multi-group');
            const singleGroup = document.getElementById('emp-branch-single-group');

            if (isSuper) {
                if (globalGroup) globalGroup.classList.remove('hidden');
                if (multiGroup) multiGroup.classList.add('hidden');
                if (singleGroup) singleGroup.classList.add('hidden');
            } else if (isManager) {
                if (globalGroup) globalGroup.classList.add('hidden');
                if (multiGroup) multiGroup.classList.remove('hidden');
                if (singleGroup) singleGroup.classList.add('hidden');
            } else {
                if (globalGroup) globalGroup.classList.add('hidden');
                if (multiGroup) multiGroup.classList.add('hidden');
                if (singleGroup) singleGroup.classList.remove('hidden');
            }

            lucide.createIcons();
        }

        async function editEmployee(emp) {
            currentEditingEmployee = emp;
            const ok = await openEmployeeModal(true);
            if (ok === false) return;
            document.getElementById('emp-id').value = emp.id;
            document.getElementById('emp-nik').value = emp.nik;
            document.getElementById('emp-name').value = emp.name;
            renderEmployeeRoleOptions(emp.role);
            document.getElementById('emp-role').value = emp.role;
            const curUser = state.currentUser || state.loggedInUser;
            const canSwitchBranch = curUser && (Number(curUser.can_access_all_branches) === 1 || ['SUPER_ADMIN', 'SUPERADMIN'].includes((curUser.role || '').toUpperCase().replace(/_/g, '')));
            document.getElementById('emp-branch').value = emp.branch_id || 1;
            if (!canSwitchBranch) {
                document.getElementById('emp-branch').disabled = true;
            } else {
                document.getElementById('emp-branch').disabled = false;
            }
            document.getElementById('emp-email').value = emp.email || '';
            document.getElementById('emp-phone').value = emp.phone || '';
            document.getElementById('emp-pin').value = emp.pin || '123456';
            if (document.getElementById('emp-commission')) document.getElementById('emp-commission').value = ((parseFloat(emp.commission_rate) || 0) * 100).toFixed(1);
            const elJoinDate = document.getElementById('emp-join-date');
            if (elJoinDate) elJoinDate.value = emp.join_date || '';
            document.getElementById('emp-modal-title').innerText = 'Edit Karyawan: ' + emp.name;

            // Multi-branch selection initialization for Branch Manager
            let selectedBranchIds = [];
            if (Array.isArray(emp.assigned_branch_ids)) {
                selectedBranchIds = emp.assigned_branch_ids;
            } else if (typeof emp.assigned_branch_ids === 'string' && emp.assigned_branch_ids.startsWith('[')) {
                try { selectedBranchIds = JSON.parse(emp.assigned_branch_ids); } catch (e) {}
            } else if (emp.branch_id) {
                selectedBranchIds = [parseInt(emp.branch_id)];
            }
            renderEmployeeMultiBranchCheckboxes(selectedBranchIds);

            renderEmployeeModalShiftOptions(emp.default_work_shift_id);
            renderEmployeeModalVehicleOptions(emp.branch_id || 1, emp.assigned_vehicle_id);
            handleEmployeeRoleChange();
        }

        function closeEmployeeModal() {
            document.getElementById('employee-modal').classList.add('hidden');
        }

        function openScheduleFromEmployeeModal() {
            if (currentEditingEmployee) {
                closeEmployeeModal();
                openEmployeeScheduleModal(currentEditingEmployee);
            }
        }

        async function saveEmployeeForm(e) {
            e.preventDefault();
            const id = document.getElementById('emp-id').value;
            const role = document.getElementById('emp-role').value;
            const roleClean = (role || '').toUpperCase().replace(/_/g, '');
            const isSuper = ['SUPERADMIN', 'SUPER_ADMIN'].includes(roleClean);
            const isManager = ['BRANCHMANAGER', 'BRANCH_MANAGER', 'MANAGER'].includes(roleClean);
            const isExempt = isSuper || isManager;
            const defaultShiftId = (!isExempt && document.getElementById('emp-default-shift').value) ? parseInt(document.getElementById('emp-default-shift').value) : null;
            const assignedVehicleId = _val('emp-assigned-vehicle') ? parseInt(document.getElementById('emp-assigned-vehicle').value) : null;

            let branchId = null;
            let assignedBranchIds = null;

            if (isSuper) {
                branchId = null;
                assignedBranchIds = 'ALL';
            } else if (isManager) {
                const selectedCbs = Array.from(document.querySelectorAll('input[name="emp_multi_branch_cb"]:checked')).map(cb => parseInt(cb.value));
                if (selectedCbs.length === 0) {
                    alert('Harap pilih minimal 1 cabang penempatan wewenang untuk Branch Manager!');
                    return;
                }
                assignedBranchIds = selectedCbs;
                branchId = selectedCbs[0];
            } else {
                branchId = parseInt(document.getElementById('emp-branch').value) || 1;
                assignedBranchIds = [branchId];
            }

            const payload = {
                id: id ? parseInt(id) : null,
                nik: document.getElementById('emp-nik').value,
                name: document.getElementById('emp-name').value,
                role: role,
                branch_id: branchId,
                assigned_branch_ids: assignedBranchIds,
                email: document.getElementById('emp-email').value,
                phone: document.getElementById('emp-phone').value,
                pin: document.getElementById('emp-pin').value,
                password: document.getElementById('emp-password').value,
                commission_rate: document.getElementById('emp-commission') ? (parseFloat(document.getElementById('emp-commission').value) / 100) : 0,
                join_date: document.getElementById('emp-join-date') ? document.getElementById('emp-join-date').value : null,
                default_work_shift_id: defaultShiftId,
                assigned_vehicle_id: assignedVehicleId
            };

            const res = await fetch('api.php?action=save_employee', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeEmployeeModal();
                loadEmployees();
                if (typeof loadLogisticsData === 'function') loadLogisticsData();
                renderPosCourierSelect();
                if (typeof loadQuickLoginAccounts === 'function') loadQuickLoginAccounts();
            }
        }

        async function deleteEmployee(id) {
            if (!hasUserPerm('employees', 'delete')) {
                showToast('Akses Ditolak: Peran Anda tidak memiliki izin untuk menonaktifkan/menghapus karyawan!', 'error');
                return;
            }
            if (!confirm('Nonaktifkan karyawan ini?')) return;
            const res = await fetch('api.php?action=delete_employee', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadEmployees();
                if (typeof loadQuickLoginAccounts === 'function') loadQuickLoginAccounts();
            }
        }

        // ==========================================
        // 4b. DETAIL & PEMETAAN JADWAL SHIFT KARYAWAN
        // ==========================================
        async function openEmployeeScheduleModal(emp) {
            currentScheduleEmployee = emp;
            await ensureWorkShiftsLoaded();

            document.getElementById('emp-sched-user-name').innerText = emp.name;
            document.getElementById('emp-sched-user-nik').innerText = emp.nik;
            document.getElementById('emp-sched-user-role').innerText = emp.role;
            document.getElementById('emp-sched-user-branch').innerText = emp.branch_name || 'Semua Cabang';

            const mInput = document.getElementById('emp-sched-month-input');
            if (!mInput.value) {
                mInput.value = new Date().toISOString().slice(0, 7);
            }

            const isExempt = ['SUPER_ADMIN', 'SUPERADMIN', 'BRANCH_MANAGER', 'MANAGER'].includes(emp.role);
            const exemptContainer = document.getElementById('emp-sched-exempt-container');
            const mainContent = document.getElementById('emp-sched-main-content');

            if (isExempt) {
                exemptContainer.classList.remove('hidden');
                mainContent.classList.add('hidden');
                document.getElementById('emp-sched-exempt-role').innerText = emp.role;
            } else {
                exemptContainer.classList.add('hidden');
                mainContent.classList.remove('hidden');

                // Render default shift dropdown options in modal
                const defSelect = document.getElementById('emp-sched-default-shift-select');
                defSelect.innerHTML = ['<option value="">-- Pilih Shift Bawaan --</option>']
                    .concat((essWorkShiftsList || []).map(ws => {
                        const timeInfo = ws.is_day_off ? 'Libur / Off' : `${ws.start_time} - ${ws.end_time}`;
                        return `<option value="${ws.id}" ${ws.id == emp.default_work_shift_id ? 'selected' : ''}>${ws.code} - ${ws.name} (${timeInfo})</option>`;
                    })).join('');

                await loadEmployeeScheduleData();
            }

            document.getElementById('employee-schedule-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function closeEmployeeScheduleModal() {
            document.getElementById('employee-schedule-modal').classList.add('hidden');
        }

        async function loadEmployeeScheduleData() {
            if (!currentScheduleEmployee) return;
            const month = document.getElementById('emp-sched-month-input').value || new Date().toISOString().slice(0, 7);
            const tbody = document.getElementById('emp-sched-table-body');
            tbody.innerHTML = '<tr><td colspan="5" class="py-6 text-center text-slate-400">Memuat jadwal shift...</td></tr>';

            try {
                const res = await fetch(`api.php?action=get_employee_schedule&user_id=${currentScheduleEmployee.id}&month=${month}`);
                const data = await res.json();
                if (!data.success) {
                    tbody.innerHTML = `<tr><td colspan="5" class="py-6 text-center text-rose-500 font-medium">${data.message || 'Gagal memuat jadwal.'}</td></tr>`;
                    return;
                }

                currentEmployeeScheduleData = data;
                if (data.work_shifts) essWorkShiftsList = data.work_shifts;

                // Sync default shift dropdown if updated
                if (data.employee && data.employee.default_work_shift_id) {
                    currentScheduleEmployee.default_work_shift_id = data.employee.default_work_shift_id;
                    const defSelect = document.getElementById('emp-sched-default-shift-select');
                    if (defSelect) defSelect.value = data.employee.default_work_shift_id;
                }

                const daysInMonth = data.days_in_month;
                const schedules = data.schedules || {};
                const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

                let totalWork = 0;
                let totalOff = 0;
                let rowsHtml = '';

                for (let d = 1; d <= daysInMonth; d++) {
                    const dateStr = `${month}-${String(d).padStart(2, '0')}`;
                    const dateObj = new Date(`${dateStr}T00:00:00`);
                    const dayName = dayNames[dateObj.getDay()];
                    const isSunday = (dateObj.getDay() === 0);

                    const sched = schedules[dateStr] || null;
                    const assignedShiftId = sched ? sched.work_shift_id : null;
                    const isHoliday = sched ? sched.is_holiday : (isSunday ? 1 : 0);

                    let assignedShift = null;
                    if (assignedShiftId) {
                        assignedShift = essWorkShiftsList.find(ws => ws.id == assignedShiftId);
                    }

                    if (assignedShift && !assignedShift.is_day_off && !isHoliday) {
                        totalWork++;
                    } else {
                        totalOff++;
                    }

                    const shiftOptions = ['<option value="">-- Belum Diset / Libur --</option>']
                        .concat((essWorkShiftsList || []).map(ws => {
                            return `<option value="${ws.id}" ${ws.id == assignedShiftId ? 'selected' : ''}>${ws.code} - ${ws.name}</option>`;
                        })).join('');

                    const timeDisplay = (assignedShift && !assignedShift.is_day_off) 
                        ? `<span class="font-mono text-slate-700 font-bold">${assignedShift.start_time} - ${assignedShift.end_time}</span>` 
                        : `<span class="text-slate-400 font-medium italic">Libur / Fleksibel</span>`;

                    rowsHtml += `
                        <tr class="hover:bg-slate-50 transition-colors ${isSunday ? 'bg-rose-50/30' : ''}" data-date="${dateStr}">
                            <td class="py-2.5 px-3 font-mono font-bold text-slate-800">${dateStr}</td>
                            <td class="py-2.5 px-3 font-medium ${isSunday ? 'text-rose-600 font-bold' : 'text-slate-600'}">${dayName}</td>
                            <td class="py-2.5 px-3">
                                <select class="emp-row-shift-select p-1.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg text-xs font-medium text-slate-800 dark:text-slate-100 w-full max-w-[220px]" onchange="handleEmployeeRowShiftChange(this, '${dateStr}')">
                                    ${shiftOptions}
                                </select>
                            </td>
                            <td class="py-2.5 px-3 emp-row-time-col">
                                ${timeDisplay}
                            </td>
                            <td class="py-2.5 px-3">
                                <input type="text" class="emp-row-notes p-1.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs text-slate-800 dark:text-slate-100 w-full" placeholder="Catatan shift..." value="${sched ? (sched.notes || '') : ''}">
                            </td>
                        </tr>
                    `;
                }

                tbody.innerHTML = rowsHtml;
                document.getElementById('emp-sched-stats').innerHTML = `
                    <span class="inline-flex items-center gap-1.5">
                        <span class="w-2.5 h-2.5 rounded-full bg-emerald-500"></span>
                        <span>Hari Kerja: <strong>${totalWork} hari</strong></span>
                    </span>
                    <span class="mx-2 text-slate-300">|</span>
                    <span class="inline-flex items-center gap-1.5">
                        <span class="w-2.5 h-2.5 rounded-full bg-slate-400"></span>
                        <span>Hari Libur/Off: <strong>${totalOff} hari</strong></span>
                    </span>
                `;
            } catch (err) {
                tbody.innerHTML = `<tr><td colspan="5" class="py-6 text-center text-rose-500 font-medium">Terjadi kesalahan: ${err.message}</td></tr>`;
            }
        }

        function handleEmployeeRowShiftChange(selectEl, dateStr) {
            const shiftId = selectEl.value;
            const row = selectEl.closest('tr');
            const timeCol = row.querySelector('.emp-row-time-col');
            if (!shiftId) {
                timeCol.innerHTML = `<span class="text-slate-400 font-medium italic">Libur / Fleksibel</span>`;
                return;
            }
            const ws = (essWorkShiftsList || []).find(w => w.id == shiftId);
            if (ws && !ws.is_day_off) {
                timeCol.innerHTML = `<span class="font-mono text-slate-700 font-bold">${ws.start_time} - ${ws.end_time}</span>`;
            } else {
                timeCol.innerHTML = `<span class="text-slate-400 font-medium italic">Libur / Fleksibel</span>`;
            }
        }

        async function applyDefaultShiftToMonth(overrideAll) {
            if (!currentScheduleEmployee) return;
            const defSelect = document.getElementById('emp-sched-default-shift-select');
            const defaultShiftId = defSelect.value ? parseInt(defSelect.value) : null;
            if (!defaultShiftId) {
                alert('Silakan pilih Shift Bawaan terlebih dahulu pada dropdown di atas.');
                return;
            }

            const month = document.getElementById('emp-sched-month-input').value || new Date().toISOString().slice(0, 7);
            const confirmMsg = overrideAll 
                ? `Terapkan shift ini ke SELURUH hari pada bulan ${month} (semua jadwal lama akan ditimpa)?` 
                : `Terapkan shift ini ke tanggal-tanggal yang belum memiliki jadwal pada bulan ${month}?`;
            if (!confirm(confirmMsg)) return;

            try {
                const res = await fetch('api.php?action=apply_employee_default_shift_month', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        user_id: currentScheduleEmployee.id,
                        month: month,
                        default_work_shift_id: defaultShiftId,
                        override_all: overrideAll ? 1 : 0
                    })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    currentScheduleEmployee.default_work_shift_id = defaultShiftId;
                    await loadEmployeeScheduleData();
                    loadEmployees();
                }
            } catch (e) {
                alert('Terjadi kesalahan saat menerapkan shift: ' + e.message);
            }
        }

        async function saveEmployeeScheduleData() {
            if (!currentScheduleEmployee) return;
            const month = document.getElementById('emp-sched-month-input').value || new Date().toISOString().slice(0, 7);
            const rows = document.querySelectorAll('#emp-sched-table-body tr[data-date]');
            const entries = [];

            rows.forEach(r => {
                const dateStr = r.getAttribute('data-date');
                const shiftId = r.querySelector('.emp-row-shift-select').value;
                const notes = r.querySelector('.emp-row-notes').value;
                const ws = shiftId ? (essWorkShiftsList || []).find(w => w.id == shiftId) : null;
                const isHoliday = (!ws || ws.is_day_off) ? 1 : 0;

                entries.push({
                    shift_date: dateStr,
                    work_shift_id: shiftId ? parseInt(shiftId) : null,
                    is_holiday: isHoliday,
                    notes: notes
                });
            });

            try {
                const res = await fetch('api.php?action=save_employee_schedule_batch', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        user_id: currentScheduleEmployee.id,
                        month: month,
                        branch_id: currentScheduleEmployee.branch_id || 1,
                        entries: entries
                    })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    await loadEmployeeScheduleData();
                    loadEmployees();
                }
            } catch (e) {
                alert('Gagal menyimpan jadwal shift: ' + e.message);
            }
        }

        function goToBranchRosterTab() {
            closeEmployeeScheduleModal();
            const month = document.getElementById('emp-sched-month-input').value || new Date().toISOString().slice(0, 7);
            if (typeof switchTab === 'function') switchTab('ess');
            if (typeof setEssSubtab === 'function') setEssSubtab('schedules');
            const rMonth = document.getElementById('ess-roster-month-input');
            if (rMonth) rMonth.value = month;
            if (typeof loadMonthlySchedules === 'function') loadMonthlySchedules();
        }

        async function deleteEmployee(id) {
            if (!hasUserPerm('employees', 'delete')) {
                showToast('Akses Ditolak: Peran Anda tidak memiliki izin untuk menonaktifkan/menghapus karyawan!', 'error');
                return;
            }
            if (!confirm('Nonaktifkan karyawan ini?')) return;
            const res = await fetch('api.php?action=delete_employee', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) loadEmployees();
        }

        // ==========================================
        // 5. MASTER PRODUK, KATEGORI & VARIAN
        // ==========================================
        async function loadAllProducts() {
            const res = await fetch('api.php?action=get_all_products');
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }
            state.allProducts = data.products;

            document.getElementById('master-products-table-body').innerHTML = data.products.map(p => {
                const typeBadge = p.product_type === 'FINISHED_GOODS' 
                    ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 dark:bg-emerald-950/70 text-emerald-800 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800">Barang Jadi</span>'
                    : (p.product_type === 'RAW_MATERIAL'
                        ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 dark:bg-amber-950/70 text-amber-800 dark:text-amber-300 border border-amber-200 dark:border-amber-800">Bahan Baku</span>'
                        : '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-blue-100 dark:bg-blue-950/70 text-blue-800 dark:text-blue-300 border border-blue-200 dark:border-blue-800">Jasa</span>');

                const variantsText = p.variants && p.variants.length > 0 
                    ? p.variants.map(v => {
                        const addPrice = Number(v.additional_price || 0);
                        const isFree = addPrice === 0;
                        return `
                            <span class="inline-flex items-center gap-1 ${isFree ? 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700' : 'bg-emerald-50 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-800'} px-2 py-0.5 rounded-lg text-[10px] mr-1 mb-1 font-semibold">
                                <span>${v.variant_name}</span>
                                <span class="font-bold ${isFree ? 'text-slate-500 dark:text-slate-400' : 'text-emerald-700 dark:text-emerald-400'}">${isFree ? '(+Rp 0 / Bebas Biaya)' : '(+' + formatRupiah(addPrice) + ')'}</span>
                                <button type="button" onclick="deleteProductVariant(${v.id}, '${v.variant_name.replace(/'/g, "\\'")}')" class="text-rose-400 hover:text-rose-600 dark:hover:text-rose-300 ml-1 font-bold">×</button>
                            </span>
                        `;
                    }).join('')
                    : '<span class="text-slate-400 dark:text-slate-500 text-[10px]">Standar (Tanpa Varian)</span>';

                const isTaxable = p.is_taxable !== undefined ? Number(p.is_taxable) : 1;
                const taxName = p.tax_name || (isTaxable ? 'PPN 11%' : 'Bebas Pajak');
                const taxBadge = isTaxable === 1 
                    ? `<span class="inline-flex items-center gap-1 bg-emerald-50 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-800 px-2 py-0.5 rounded-full text-[10px] font-bold"><span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>${taxName}</span>`
                    : `<span class="inline-flex items-center gap-1 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700 px-2 py-0.5 rounded-full text-[10px] font-bold"><span class="w-1.5 h-1.5 rounded-full bg-slate-400"></span>Non-Pajak</span>`;

                const isDelivInc = Number(p.is_delivery_included || 0) === 1 || Number(p.is_delivery_required || 0) === 2;
                const isDelivReq = Number(p.is_delivery_required || 0) === 1;
                const deliveryBadge = isDelivInc
                    ? `<span class="inline-flex items-center gap-1 bg-emerald-50 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-800 px-2 py-0.5 rounded-full text-[10px] font-bold"><span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>🎁 Termasuk Kirim</span>`
                    : (isDelivReq
                        ? `<span class="inline-flex items-center gap-1 bg-amber-50 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300 border border-amber-300 dark:border-amber-800 px-2 py-0.5 rounded-full text-[10px] font-bold"><span class="w-1.5 h-1.5 rounded-full bg-amber-500"></span>🚚 Wajib Ongkir</span>`
                        : `<span class="inline-flex items-center gap-1 bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-400 border border-slate-200 dark:border-slate-700 px-2 py-0.5 rounded-full text-[10px] font-medium">Standar</span>`);

                return `
                    <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                        <td class="py-2.5 px-3 font-mono font-bold text-indigo-700 dark:text-indigo-400">${p.sku}<br><span class="text-[10px] text-slate-400 dark:text-slate-500">${p.barcode}</span></td>
                        <td class="py-2.5 px-3 font-semibold text-slate-800 dark:text-slate-100">
                            <span class="mr-1.5">${p.image_emoji || '📦'}</span>${p.name}${
                                (Number(p.is_stockable) === 2)
                                    ? ' <span class="inline-block text-[9px] px-1.5 py-0.2 bg-amber-100 dark:bg-amber-950/70 text-amber-800 dark:text-amber-300 border border-amber-300 dark:border-amber-800 rounded font-bold">🔄 Hibrida</span>'
                                    : ((p.effective_is_stockable === 0 || p.requires_stock === 0) ? ' <span class="inline-block text-[9px] px-1.5 py-0.2 bg-violet-100 dark:bg-violet-950/70 text-violet-800 dark:text-violet-300 border border-violet-200 dark:border-violet-800 rounded font-bold">⚡ Tanpa Stok</span>' : '')
                            }
                        </td>
                        <td class="py-2.5 px-3">${typeBadge}</td>
                        <td class="py-2.5 px-3 text-slate-600 dark:text-slate-300">${p.category}</td>
                        <td class="py-2.5 px-3 text-slate-500 dark:text-slate-400 font-medium">${p.unit}</td>
                        <td class="py-2.5 px-3 text-right font-medium text-slate-700 dark:text-slate-300 font-mono">${formatRupiah(p.cogs)}</td>
                        <td class="py-2.5 px-3 text-right font-mono">
                            ${p.product_type === 'RAW_MATERIAL' ? '-' : `
                                <span class="font-bold text-indigo-900 dark:text-indigo-300">${formatRupiah(p.selling_price)}</span>
                                <div class="text-[9px] text-emerald-700 dark:text-emerald-400 font-semibold tracking-tight" title="Harga Tier Mitra Umum">Mitra: ${formatRupiah(p.mitra_price > 0 ? p.mitra_price : p.selling_price)}</div>
                            `}
                        </td>
                        <td class="py-2.5 px-3 text-center">
                            <div class="flex flex-col items-center gap-1">
                                ${taxBadge}
                                ${deliveryBadge}
                            </div>
                        </td>
                        <td class="py-2.5 px-3">
                            <div class="flex flex-wrap items-center">
                                ${variantsText}
                            </div>
                            <div class="mt-1 flex items-center space-x-2">
                                <button onclick="openProductVariantModal(${p.id}, '${p.name.replace(/'/g, "\\'")}', '${p.sku}')" class="text-[10px] text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 font-bold flex items-center space-x-0.5">
                                    <span>➕ Tambah Varian</span>
                                </button>
                                ${p.has_bom ? '<span class="text-[9px] text-emerald-600 dark:text-emerald-400 font-bold">🧪 Ada BOM</span>' : ''}
                            </div>
                        </td>
                        <td class="py-2.5 px-3 text-center whitespace-nowrap">
                            <div class="inline-flex items-center space-x-1">
                                <button onclick='editProduct(${JSON.stringify(p)})' class="px-2.5 py-1 bg-indigo-50 dark:bg-indigo-950/60 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-100 dark:hover:bg-indigo-900/60 rounded-lg text-[11px] font-bold transition-colors">Edit</button>
                                <button onclick="deleteProduct(${p.id}, '${p.name.replace(/'/g, "\\'")}')" class="px-2 py-1 bg-rose-50 dark:bg-rose-950/60 text-rose-600 dark:text-rose-400 hover:bg-rose-100 dark:hover:bg-rose-900/60 rounded-lg text-[11px] font-bold transition-colors flex items-center space-x-0.5" title="Hapus Produk">
                                    <i data-lucide="trash-2" class="w-3 h-3"></i>
                                    <span>Hapus</span>
                                </button>
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');
            lucide.createIcons();
        }

        function renderTaxOptionsForProductModal(selectedTaxId = 1) {
            const select = document.getElementById('prod-tax-id');
            if (!select) return;
            const taxes = state.taxes || [];
            select.innerHTML = taxes.map(t => 
                `<option value="${t.id}" ${t.id == selectedTaxId ? 'selected' : ''}>${t.name} (${t.rate_percent}%)</option>`
            ).join('');
        }

        function toggleProductTaxSelect() {
            const isChecked = document.getElementById('prod-is-taxable').checked;
            const cont = document.getElementById('prod-tax-select-container');
            const badge = document.getElementById('prod-tax-status-badge');
            if (isChecked) {
                if (cont) cont.classList.remove('hidden');
                if (badge) {
                    badge.innerText = 'Kena Pajak';
                    badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800';
                }
            } else {
                if (cont) cont.classList.add('hidden');
                if (badge) {
                    badge.innerText = 'Bebas Pajak (Tax Exempt)';
                    badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-slate-200 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-300 dark:border-slate-700';
                }
            }
        }

        function toggleProductDeliveryBadge() {
            const selectEl = document.getElementById('prod-delivery-mode');
            const hiddenEl = document.getElementById('prod-is-delivery-required');
            const badge = document.getElementById('prod-delivery-status-badge');
            const desc = document.getElementById('prod-delivery-desc-text');
            if (!badge) return;

            const mode = selectEl ? selectEl.value : (hiddenEl && (hiddenEl.checked || hiddenEl.value === '1') ? '1' : '0');
            if (hiddenEl) {
                hiddenEl.value = (mode === '2') ? '2' : ((mode === '1') ? '1' : '0');
                hiddenEl.checked = (mode === '1' || mode === '2');
            }

            if (mode === '2') {
                badge.innerText = 'Termasuk Ongkir';
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-300';
                if (desc) desc.innerText = '🎁 Produk sudah termasuk ongkir: Biaya kirim Rp 0 di POS, kurir pengirim & armada tetap dicatat.';
            } else if (mode === '1') {
                badge.innerText = 'Wajib Ongkir (+Tarif)';
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-amber-100 text-amber-800 border border-amber-300';
                if (desc) desc.innerText = '🚚 Wajib ongkir tambahan: Kasir otomatis dikenakan tarif dasar pengiriman cabang / per KM.';
            } else {
                badge.innerText = 'Standar';
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700';
                if (desc) desc.innerText = '⚪ Standar: Pelanggan belanja biasa di toko tanpa mewajibkan layanan pengantaran.';
            }
        }

        function onProductTypeChange() {
            const type = document.getElementById('prod-type').value;
            const id = document.getElementById('prod-id').value;
            const btnBom = document.getElementById('btn-fetch-bom-cogs');
            if (type === 'FINISHED_GOODS' && id) {
                if (btnBom) btnBom.classList.remove('hidden');
            } else if (!id && type === 'FINISHED_GOODS') {
                if (btnBom) btnBom.classList.add('hidden');
            } else {
                if (btnBom) btnBom.classList.add('hidden');
            }
            // Auto generate SKU baru jika menambah produk baru
            if (!id) {
                autoGenerateSkuBarcode();
            }
        }

        async function autoGenerateSkuBarcode() {
            try {
                const pType = document.getElementById('prod-type').value || 'FINISHED_GOODS';
                const cId = document.getElementById('prod-category').value || 1;
                const res = await fetch(`api.php?action=generate_sku_barcode&product_type=${pType}&category_id=${cId}`);
                const data = await res.json();
                if (data.success) {
                    document.getElementById('prod-sku').value = data.sku;
                    document.getElementById('prod-barcode').value = data.barcode;
                }
            } catch (err) {
                console.error('Gagal generate SKU/Barcode:', err);
            }
        }

        function renderProductModalOptions(selectedType = 'FINISHED_GOODS', selectedCatId = 1, selectedUnit = 'pcs') {
            // Render Jenis Produk
            const typeSelect = document.getElementById('prod-type');
            if (typeSelect && state.productTypes && state.productTypes.length > 0) {
                typeSelect.innerHTML = state.productTypes.map(pt => 
                    `<option value="${pt.code}" ${pt.code === selectedType ? 'selected' : ''}>${pt.name} (${pt.prefix})</option>`
                ).join('');
            } else if (typeSelect) {
                typeSelect.innerHTML = `
                    <option value="FINISHED_GOODS" ${selectedType === 'FINISHED_GOODS' ? 'selected' : ''}>Barang Jadi (PRD)</option>
                    <option value="RAW_MATERIAL" ${selectedType === 'RAW_MATERIAL' ? 'selected' : ''}>Bahan Baku (RAW)</option>
                    <option value="SERVICE" ${selectedType === 'SERVICE' ? 'selected' : ''}>Jasa / Servis (SRV)</option>
                `;
            }

            // Render Kategori
            const catSelect = document.getElementById('prod-category');
            if (catSelect && state.categories) {
                catSelect.innerHTML = state.categories.map(c => 
                    `<option value="${c.id}" ${c.id == selectedCatId ? 'selected' : ''}>${c.name}</option>`
                ).join('');
            }

            // Render Satuan
            const unitSelect = document.getElementById('prod-unit');
            if (unitSelect && state.productUnits && state.productUnits.length > 0) {
                unitSelect.innerHTML = state.productUnits.map(u => 
                    `<option value="${u.code}" ${u.code.toLowerCase() === (selectedUnit || '').toLowerCase() ? 'selected' : ''}>${u.code} - ${u.name}</option>`
                ).join('');
            } else if (unitSelect) {
                const defaultUnits = ['pcs', 'cup', 'botol', 'porsi', 'gram', 'kg', 'ml', 'liter', 'pack', 'box'];
                unitSelect.innerHTML = defaultUnits.map(u => 
                    `<option value="${u}" ${u.toLowerCase() === (selectedUnit || '').toLowerCase() ? 'selected' : ''}>${u}</option>`
                ).join('');
            }
        }

        async function autoFillCogsFromBOM() {
            const id = document.getElementById('prod-id').value;
            if (!id) {
                alert('Simpan produk terlebih dahulu atau tambahkan formula resep di Menu BOM untuk menghitung HPP otomatis.');
                return;
            }
            try {
                const res = await fetch(`api.php?action=get_product_bom_cogs&product_id=${id}`);
                const data = await res.json();
                if (data.success && data.count > 0) {
                    document.getElementById('prod-cogs').value = data.calculated_cogs;
                    const hint = document.getElementById('prod-cogs-hint');
                    if (hint) {
                        hint.innerText = `✓ Dihitung dari ${data.count} bahan baku BOM: Rp ${formatRupiah(data.calculated_cogs)}`;
                        hint.classList.remove('hidden');
                    }
                    alert(`HPP Berhasil Diperbarui dari Formula BOM!\n\nTotal modal dari ${data.count} bahan baku: Rp ${formatRupiah(data.calculated_cogs)}`);
                } else {
                    alert('Produk ini belum memiliki bahan baku terdaftar di formula resep (BOM). Silakan atur formula di Tab BOM.');
                }
            } catch (err) {
                alert('Gagal mengambil kalkulasi HPP dari BOM.');
            }
        }

        function calcDefaultTierPrices(force = false) {
            const retail = parseFloat(_val('prod-price')) || 0;
            const elMitra = document.getElementById('prod-mitra-price');
            const elReseller = document.getElementById('prod-reseller-price');
            const elMember = document.getElementById('prod-member-price');
            if (!elMitra || !elReseller || !elMember) return;

            if (force || !elMitra.value || elMitra.value == 0) {
                elMitra.value = retail;
            }
            if (force || !elReseller.value || elReseller.value == 0) {
                elReseller.value = retail;
            }
            if (force || !elMember.value || elMember.value == 0) {
                elMember.value = retail;
            }
        }

        function onSellingPriceChange() {
            const isNew = !_val('prod-id');
            if (isNew) {
                calcDefaultTierPrices(true);
            }
        }

        async function openProductModal() {
            if (!hasUserPerm('products', 'create') && !hasUserPerm('products:fg', 'create')) {
                showToast('Akses Ditolak: Peran Anda tidak memiliki izin untuk menambah produk!', 'error');
                return;
            }
            document.getElementById('prod-id').value = '';
            document.getElementById('prod-sku').value = '';
            document.getElementById('prod-barcode').value = '';
            document.getElementById('prod-name').value = '';
            document.getElementById('prod-cogs').value = '10000';
            document.getElementById('prod-price').value = '25000';
            document.getElementById('prod-mitra-price').value = 25000;
            document.getElementById('prod-reseller-price').value = 25000;
            document.getElementById('prod-member-price').value = 25000;
            document.getElementById('prod-emoji').value = '📦';
            document.getElementById('prod-has-bom').checked = false;
            document.getElementById('prod-reorder').value = '10';
            document.getElementById('prod-modal-title').innerText = 'Tambah Produk Baru';

            renderProductModalOptions('FINISHED_GOODS', 1, 'pcs');

            const btnBom = document.getElementById('btn-fetch-bom-cogs');
            if (btnBom) btnBom.classList.add('hidden');
            const hint = document.getElementById('prod-cogs-hint');
            if (hint) hint.classList.add('hidden');

            // Reset status pajak default aktif
            document.getElementById('prod-is-taxable').checked = true;
            renderTaxOptionsForProductModal(1);
            toggleProductTaxSelect();

            // Reset status pengiriman default Standar (0)
            if (document.getElementById('prod-delivery-mode')) {
                document.getElementById('prod-delivery-mode').value = '0';
            }
            document.getElementById('prod-is-delivery-required').value = '0';
            document.getElementById('prod-is-delivery-required').checked = false;
            toggleProductDeliveryBadge();
            if (document.getElementById('prod-is-stockable')) {
                document.getElementById('prod-is-stockable').value = '1';
            }
            toggleProductStockableBadge();

            // Generate otomatis SKU dan Barcode unik untuk produk baru (5 digit)
            await autoGenerateSkuBarcode();

            document.getElementById('product-modal').classList.remove('hidden');
            if (typeof lucide !== 'undefined') lucide.createIcons();
        }

        async function editProduct(p) {
            if (!hasUserPerm('products', 'update') && !hasUserPerm('products:fg', 'update')) {
                showToast('Akses Ditolak: Peran Anda tidak memiliki izin untuk mengedit produk!', 'error');
                return;
            }
            document.getElementById('prod-id').value = p.id;
            document.getElementById('prod-sku').value = p.sku;
            document.getElementById('prod-barcode').value = p.barcode;
            document.getElementById('prod-name').value = p.name;
            document.getElementById('prod-cogs').value = p.cogs;
            document.getElementById('prod-price').value = p.selling_price;
            const retPrice = Number(p.selling_price || 0);
            document.getElementById('prod-mitra-price').value = (p.mitra_price !== undefined && p.mitra_price !== null && Number(p.mitra_price) > 0) ? Number(p.mitra_price) : retPrice;
            document.getElementById('prod-reseller-price').value = (p.reseller_price !== undefined && p.reseller_price !== null && Number(p.reseller_price) > 0) ? Number(p.reseller_price) : retPrice;
            document.getElementById('prod-member-price').value = (p.member_price !== undefined && p.member_price !== null && Number(p.member_price) > 0) ? Number(p.member_price) : retPrice;
            document.getElementById('prod-emoji').value = p.image_emoji || '📦';
            document.getElementById('prod-has-bom').checked = !!p.has_bom;
            document.getElementById('prod-reorder').value = p.reorder_point || 10;
            
            renderProductModalOptions(p.product_type || 'FINISHED_GOODS', p.category_id || 1, p.unit || 'pcs');

            // Tampilkan tombol kalkulasi BOM jika barang jadi
            const btnBom = document.getElementById('btn-fetch-bom-cogs');
            const hint = document.getElementById('prod-cogs-hint');
            if (p.product_type === 'FINISHED_GOODS') {
                if (btnBom) btnBom.classList.remove('hidden');
                if (p.has_bom && hint) {
                    hint.innerText = `💡 Produk memiliki formula BOM. Klik 'Dari BOM' untuk sinkronisasi modal.`;
                    hint.classList.remove('hidden');
                } else if (hint) {
                    hint.classList.add('hidden');
                }
            } else {
                if (btnBom) btnBom.classList.add('hidden');
                if (hint) hint.classList.add('hidden');
            }

            // Atur status pajak produk
            const isTaxable = p.is_taxable !== undefined ? (Number(p.is_taxable) === 1) : true;
            document.getElementById('prod-is-taxable').checked = isTaxable;
            renderTaxOptionsForProductModal(p.tax_id || 1);
            toggleProductTaxSelect();

            // Atur status ongkos kirim / delivery produk (0 = Standar, 1 = Wajib Ongkir Ekstra, 2 = Termasuk Ongkir)
            let delivVal = '0';
            if (p.is_delivery_included == 1 || p.is_delivery_required == 2) {
                delivVal = '2';
            } else if (p.is_delivery_required == 1) {
                delivVal = '1';
            }
            if (document.getElementById('prod-delivery-mode')) {
                document.getElementById('prod-delivery-mode').value = delivVal;
            }
            document.getElementById('prod-is-delivery-required').value = delivVal;
            document.getElementById('prod-is-delivery-required').checked = (delivVal === '1' || delivVal === '2');
            toggleProductDeliveryBadge();
            if (document.getElementById('prod-is-stockable')) {
                document.getElementById('prod-is-stockable').value = (p.is_stockable !== undefined && p.is_stockable !== null) ? String(p.is_stockable) : '1';
            }
            toggleProductStockableBadge();

            document.getElementById('prod-modal-title').innerText = 'Edit Produk: ' + p.name;
            document.getElementById('product-modal').classList.remove('hidden');
            if (typeof lucide !== 'undefined') lucide.createIcons();
        }

        function toggleProductStockableBadge() {
            const el = document.getElementById('prod-is-stockable');
            const badge = document.getElementById('prod-stockable-status-badge');
            const desc = document.getElementById('prod-stockable-desc-text');
            if (!el || !badge) return;
            const val = String(el.value);
            if (val === '0') {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-violet-100 text-violet-800 border border-violet-200';
                badge.innerText = '⚡ Tanpa Stok (BOM)';
                if (desc) desc.innerHTML = 'Jika diset <strong>Tidak Di-Stok</strong>, kasir dapat menjual produk ini tanpa dibatasi sisa stok fisik jadi, dan sistem akan langsung memotong stok bahan baku BOM terkait.';
            } else if (val === '2') {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-amber-100 text-amber-800 border border-amber-300';
                badge.innerText = '🔄 Hibrida (Fisik + Auto-BOM)';
                if (desc) desc.innerHTML = '<strong>Kombinasi Kedua Fitur (Hibrida):</strong> Saldo stok fisik produk tetap dihitung & dicatat di inventori/shift, namun kasir <strong>bebas menjual tanpa dibatasi</strong> jika stok habis (otomatis potong bahan baku resep BOM).';
            } else {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-200';
                badge.innerText = '📦 Wajib Stok';
                if (desc) desc.innerHTML = 'Standar: Produk wajib memiliki saldo fisik di cabang dan kasir <strong>dibatasi jika stok habis</strong>.';
            }
        }

        function closeProductModal() {
            document.getElementById('product-modal').classList.add('hidden');
        }

        async function saveProductForm(e) {
            e.preventDefault();
            const id = document.getElementById('prod-id').value;
            const isTaxable = document.getElementById('prod-is-taxable').checked ? 1 : 0;
            const taxId = parseInt(document.getElementById('prod-tax-id').value) || 1;
            
            const delivMode = document.getElementById('prod-delivery-mode') 
                ? document.getElementById('prod-delivery-mode').value 
                : (document.getElementById('prod-is-delivery-required').checked ? '1' : '0');
            const isDelivReq = (delivMode === '2') ? 2 : ((delivMode === '1') ? 1 : 0);
            const isDelivInc = (delivMode === '2') ? 1 : 0;

            const payload = {
                id: id ? parseInt(id) : null,
                branch_id: state.currentBranch ? state.currentBranch.id : 1,
                sku: document.getElementById('prod-sku').value,
                barcode: document.getElementById('prod-barcode').value,
                name: document.getElementById('prod-name').value,
                product_type: document.getElementById('prod-type').value,
                category_id: parseInt(document.getElementById('prod-category').value),
                unit: document.getElementById('prod-unit').value,
                cogs: parseFloat(document.getElementById('prod-cogs').value) || 0,
                selling_price: parseFloat(document.getElementById('prod-price').value) || 0,
                mitra_price: parseFloat(document.getElementById('prod-mitra-price').value) || 0,
                reseller_price: parseFloat(document.getElementById('prod-reseller-price').value) || 0,
                member_price: parseFloat(document.getElementById('prod-member-price').value) || 0,
                image_emoji: document.getElementById('prod-emoji').value,
                has_bom: document.getElementById('prod-has-bom').checked ? 1 : 0,
                reorder_point: parseInt(document.getElementById('prod-reorder').value) || 10,
                is_taxable: isTaxable,
                tax_id: taxId,
                is_delivery_required: isDelivReq,
                is_delivery_included: isDelivInc,
                is_stockable: document.getElementById('prod-is-stockable') ? parseInt(document.getElementById('prod-is-stockable').value) : 1
            };

            const res = await fetch('api.php?action=save_product', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeProductModal();
                loadAllProducts();
                await initApp();
                recalculateCartPrices();
            }
        }

        async function deleteProduct(id, name) {
            if (!hasUserPerm('products', 'delete') && !hasUserPerm('products:fg', 'delete')) {
                showToast('Akses Ditolak: Peran Anda tidak memiliki izin untuk menghapus produk!', 'error');
                return;
            }
            if (!confirm(`Apakah Anda yakin ingin MENGHAPUS produk '${name}'?\n\nJika produk memiliki riwayat transaksi, produk akan dinonaktifkan (Soft Delete) agar laporan akuntansi tetap terjaga.`)) {
                return;
            }
            try {
                const res = await fetch('api.php?action=delete_product', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: id })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    await loadAllProducts();
                    await initApp();
                    recalculateCartPrices();
                }
            } catch (err) {
                alert('Terjadi kesalahan jaringan saat menghapus produk.');
            }
        }

        function exportMasterProducts() {
