        async function submitImportProducts(e) {
            e.preventDefault();
            const fileInput = document.getElementById('product-import-file-input');
            const textInput = document.getElementById('product-import-text-input');
            const btnSubmit = document.getElementById('btn-submit-import-products');

            const hasFile = fileInput && fileInput.files && fileInput.files.length > 0;
            const hasText = textInput && textInput.value.trim().length > 0;

            if (!hasFile && !hasText) {
                alert('Silakan pilih file CSV atau tempel teks data CSV terlebih dahulu.');
                return;
            }

            btnSubmit.disabled = true;
            btnSubmit.innerHTML = `<span>Memproses Import...</span>`;

            try {
                let res;
                if (hasFile) {
                    const formData = new FormData();
                    formData.append('file', fileInput.files[0]);
                    res = await fetch('api.php?action=import_products', {
                        method: 'POST',
                        body: formData
                    });
                } else {
                    res = await fetch('api.php?action=import_products', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ csv_content: textInput.value.trim() })
                    });
                }

                const data = await res.json();
                btnSubmit.disabled = false;
                btnSubmit.innerHTML = `<i data-lucide="upload" class="w-4 h-4"></i><span>Proses Import Produk</span>`;

                alert(data.message || (data.success ? 'Import produk selesai!' : 'Gagal import produk'));
                if (data.success) {
                    closeImportProductModal();
                    await loadAllProducts();
                    await initApp();
                }
            } catch (err) {
                btnSubmit.disabled = false;
                btnSubmit.innerHTML = `<i data-lucide="upload" class="w-4 h-4"></i><span>Proses Import Produk</span>`;
                alert('Terjadi kesalahan jaringan saat import data produk: ' + err.message);
            }
        }

