        // Edit Varian Langsung (Bisa ubah Nama, SKU, Tambahan Harga, dan HPP, serta centang produk jadi lain)
        function openEditVariantFromBOMModal(variant) {
            const primaryId = variant.primary_variant_id || variant.id;
            document.getElementById('pvam-modal-title').innerHTML = '<i data-lucide="edit-3" class="w-4 h-4 text-amber-600"></i><span>Edit Varian & Terapkan ke Produk Jadi</span>';
            document.getElementById('pvam-variant-id').value = primaryId;
            
            const attachedProducts = variant.products && variant.products.length > 0 
                ? variant.products 
                : [{ product_id: variant.product_id, product_name: variant.product_name, product_sku: variant.product_sku }];
            
            const firstP = attachedProducts[0];
            document.getElementById('pvam-product-id').value = firstP.product_id;
            document.getElementById('pvam-product-title').innerText = `Varian: ${variant.variant_name} (${attachedProducts.length} Produk Induk)`;

            const attachedProductIds = attachedProducts.map(p => p.product_id);

            // Tampilkan checklist produk jadi dan centang seluruh produk yang saat ini menggunakan varian ini
            const fgList = state.variantRecipesData ? (state.variantRecipesData.finished_goods || []) : [];
            const containerEl = document.getElementById('pvam-product-checkboxes');
            
            if (fgList.length === 0) {
                containerEl.innerHTML = '<p class="text-slate-400 text-xs italic py-2 text-center">Tidak ada produk jadi aktif.</p>';
            } else {
                containerEl.innerHTML = fgList.map(fg => {
                    const isAttached = attachedProductIds.includes(fg.id);
                    return `
                        <label class="flex items-center space-x-2.5 p-2 ${isAttached ? 'bg-indigo-50/70 dark:bg-indigo-950/40 border border-indigo-200 dark:border-indigo-800' : 'hover:bg-indigo-50/40 dark:hover:bg-indigo-950/30'} rounded-xl cursor-pointer transition-colors">
                            <input type="checkbox" name="pvam-parent-products" value="${fg.id}" data-sku="${fg.sku}" class="rounded text-indigo-600 focus:ring-indigo-500 w-4 h-4 shrink-0" ${isAttached ? 'checked' : ''}>
                            <div class="flex-1 min-w-0">
                                <span class="text-xs font-bold ${isAttached ? 'text-indigo-900 dark:text-indigo-200' : 'text-slate-800 dark:text-slate-100'} block truncate">${fg.name} ${isAttached ? '<span class="text-[9px] px-1.5 py-0.2 bg-indigo-200 dark:bg-indigo-900 text-indigo-800 dark:text-indigo-200 rounded-md font-black ml-1">Terdaftar</span>' : ''}</span>
                                <span class="text-[10px] text-slate-400 font-mono block">${fg.sku} • Dasar: ${formatRupiah(fg.selling_price || 0)}</span>
                            </div>
                        </label>
                    `;
                }).join('');
            }

            document.getElementById('pvam-product-select-container').classList.remove('hidden');

            document.getElementById('pvam-variant-name').value = variant.variant_name;
            document.getElementById('pvam-sku-variant').value = variant.sku_variant;
            document.getElementById('pvam-add-price').value = variant.additional_price || 0;
            document.getElementById('pvam-add-cogs').value = variant.additional_cogs || 0;
            document.getElementById('pvam-submit-btn').innerText = 'Perbarui & Terapkan Varian';

            document.getElementById('product-variant-add-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function closeProductVariantModal() {
            document.getElementById('product-variant-add-modal').classList.add('hidden');
        }

        async function saveProductVariantForm(e) {
            e.preventDefault();
            const varId = document.getElementById('pvam-variant-id').value;
            
            // Periksa apakah ini mode edit atau create
            let selectedProductIds = [];
            const isMultiVisible = !document.getElementById('pvam-product-select-container').classList.contains('hidden');
            
            if (isMultiVisible) {
                const checkedCbs = document.querySelectorAll('input[name="pvam-parent-products"]:checked');
                selectedProductIds = Array.from(checkedCbs).map(cb => parseInt(cb.value));
                if (selectedProductIds.length === 0) {
                    alert('Pilih minimal satu produk induk / jadi untuk varian ini!');
                    return;
                }
            } else if (varId) {
                selectedProductIds = [parseInt(document.getElementById('pvam-product-id').value)];
            } else {
                const singlePId = document.getElementById('pvam-product-id').value;
                if (singlePId) {
                    selectedProductIds = [parseInt(singlePId)];
                }
            }

            if (selectedProductIds.length === 0) {
                alert('Produk induk belum dipilih!');
                return;
            }

            const payload = {
                id: varId ? parseInt(varId) : null,
                product_ids: selectedProductIds,
                product_id: selectedProductIds[0],
                variant_name: document.getElementById('pvam-variant-name').value.trim(),
                sku_variant: document.getElementById('pvam-sku-variant').value.trim(),
                additional_price: parseFloat(document.getElementById('pvam-add-price').value) || 0,
                additional_cogs: parseFloat(document.getElementById('pvam-add-cogs').value) || 0
            };

            const res = await fetch('api.php?action=save_variant', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeProductVariantModal();
                loadAllProducts();
                loadVariantBOMRecipes();
                initApp();
            }
        }

        async function deleteProductVariant(variantId, variantName) {
            if (!confirm(`Hapus varian '${variantName}'? Tindakan ini tidak dapat dibatalkan.`)) return;
            const res = await fetch('api.php?action=delete_variant', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ variant_id: variantId })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadAllProducts();
                loadVariantBOMRecipes();
                initApp();
            }
        }

        async function deleteProductVariantGroup(variantName, variantIds) {
            if (!confirm(`Hapus varian '${variantName}' dari seluruh produk yang menggunakannya? Tindakan ini tidak dapat dibatalkan.`)) return;
            try {
                for (const vid of variantIds) {
                    await fetch('api.php?action=delete_variant', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ variant_id: vid })
                    });
                }
                alert(`Varian '${variantName}' berhasil dihapus.`);
                loadAllProducts();
                loadVariantBOMRecipes();
                initApp();
            } catch (err) {
                alert('Gagal menghapus varian: ' + err.message);
            }
        }

        async function detachProductFromVariant(variantId, productName, variantName) {
            if (!confirm(`Lepas varian '${variantName}' dari produk '${productName}'?`)) return;
            try {
                const res = await fetch('api.php?action=detach_product_from_variant', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ variant_id: variantId })
                });
                const data = await res.json();
                if (data.success) {
                    alert('✅ ' + (data.message || 'Produk berhasil dilepas dari varian.'));
                    loadAllProducts();
                    loadVariantBOMRecipes();
                    initApp();
                } else {
                    alert('⚠️ TIDAK BISA DILEPAS:\n\n' + (data.message || data.error || 'Terjadi kesalahan sistem'));
                }
            } catch (err) {
                alert('Gagal melepas produk dari varian: ' + err.message);
            }
        }

        // Buka Modal untuk Terapkan Varian ke Produk Jadi Lainnya (Multi-Product Assignment)
        function openApplyVariantToProductsModal(variant) {
            const primaryId = variant.primary_variant_id || variant.id;
            document.getElementById('avp-source-variant-id').value = primaryId;
            document.getElementById('avp-variant-name').innerText = variant.variant_name;
            document.getElementById('avp-variant-badge').innerText = `SKU: ${variant.sku_variant}`;

            const attachedProducts = variant.products && variant.products.length > 0 
                ? variant.products 
                : [{ product_id: variant.product_id, product_name: variant.product_name, product_sku: variant.product_sku }];

            const attachedNames = attachedProducts.map(p => `${p.product_name} (${p.product_sku})`).join(', ');
            document.getElementById('avp-source-product').innerText = attachedNames;

            const addPrice = Number(variant.additional_price || 0);
            document.getElementById('avp-add-price').innerText = addPrice === 0 ? '+Rp 0 (Bebas Biaya)' : `+${formatRupiah(addPrice)}`;

            const ingCount = (variant.ingredients && variant.ingredients.length) ? variant.ingredients.length : 0;
            document.getElementById('avp-bom-info').innerText = ingCount > 0 ? `${ingCount} Bahan Baku Resep` : 'Tanpa Bahan Tambahan';

            // Filter produk jadi yang BELUM memiliki varian ini
            const attachedProductIds = attachedProducts.map(p => p.product_id);
            const allFG = state.variantRecipesData ? (state.variantRecipesData.finished_goods || []) : [];
            const otherFG = allFG.filter(fg => !attachedProductIds.includes(fg.id));

            const container = document.getElementById('avp-target-products-list');
            if (otherFG.length === 0) {
                container.innerHTML = '<p class="text-slate-400 text-xs italic py-3 text-center">Varian ini sudah diterapkan ke semua produk jadi yang ada!</p>';
            } else {
                container.innerHTML = otherFG.map((fg, idx) => `
                    <label class="flex items-center space-x-2.5 p-2 hover:bg-white dark:hover:bg-slate-800 rounded-xl cursor-pointer transition-colors border border-transparent hover:border-slate-200 dark:hover:border-slate-700 text-slate-800 dark:text-slate-200">
                        <input type="checkbox" name="avp-target-product" value="${fg.id}" data-sku="${fg.sku}" class="rounded text-indigo-600 focus:ring-indigo-500 w-4 h-4" checked>
                        <div class="flex-1 min-w-0">
                            <span class="text-xs font-bold text-slate-800 dark:text-slate-100 block truncate">${fg.name}</span>
                            <span class="text-[10px] text-slate-400 font-mono">${fg.sku} • Harga Dasar: ${formatRupiah(fg.selling_price || 0)}</span>
                        </div>
                    </label>
                `).join('');
            }

            document.getElementById('apply-variant-to-products-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function toggleAllApplyVariantProducts(select) {
            const checkboxes = document.querySelectorAll('input[name="avp-target-product"]');
            checkboxes.forEach(cb => cb.checked = select);
        }

        function closeApplyVariantModal() {
            document.getElementById('apply-variant-to-products-modal').classList.add('hidden');
        }

        async function submitApplyVariantToProducts(e) {
            e.preventDefault();
            const sourceVarId = parseInt(document.getElementById('avp-source-variant-id').value);
            const checkedCbs = document.querySelectorAll('input[name="avp-target-product"]:checked');
            const targetIds = Array.from(checkedCbs).map(cb => parseInt(cb.value));

            if (targetIds.length === 0) {
                alert('Pilih minimal satu produk jadi tujuan untuk menerapkan varian ini!');
                return;
            }

            const copyRecipes = document.getElementById('avp-copy-recipes').checked;
            const btnSubmit = document.getElementById('avp-submit-btn');
            btnSubmit.disabled = true;
            btnSubmit.innerHTML = `<i data-lucide="loader-2" class="w-4 h-4 animate-spin"></i><span>Menerapkan...</span>`;

            try {
                const res = await fetch('api.php?action=apply_variant_to_products', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        source_variant_id: sourceVarId,
                        target_product_ids: targetIds,
                        copy_recipes: copyRecipes
                    })
                });
                const data = await res.json();
                alert(data.message || (data.success ? 'Berhasil diterapkan!' : 'Gagal menerapkan varian'));
                if (data.success) {
                    closeApplyVariantModal();
                    loadAllProducts();
                    loadVariantBOMRecipes();
                    initApp();
                }
            } catch (err) {
                alert('Terjadi kesalahan jaringan: ' + err.message);
            } finally {
                btnSubmit.disabled = false;
                btnSubmit.innerHTML = `<i data-lucide="check" class="w-4 h-4"></i><span>Terapkan Sekarang</span>`;
                lucide.createIcons();
            }
        }

        // ==========================================
        // SUB-TAB & CRUD MASTER PAJAK / TAXES
        // ==========================================
        function switchProductSubTab(subTab) {
            const catalogView = document.getElementById('product-view-catalog');
            const categoriesView = document.getElementById('product-view-categories');
            const typesView = document.getElementById('product-view-types');
            const unitsView = document.getElementById('product-view-units');
            const taxesView = document.getElementById('product-view-taxes');
            const openingShiftView = document.getElementById('product-view-opening_shift');

            const btnCatalog = document.getElementById('prod-subtab-btn-catalog');
            const btnCategories = document.getElementById('prod-subtab-btn-categories');
            const btnTypes = document.getElementById('prod-subtab-btn-types');
            const btnUnits = document.getElementById('prod-subtab-btn-units');
            const btnTaxes = document.getElementById('prod-subtab-btn-taxes');
            const btnOpeningShift = document.getElementById('prod-subtab-btn-opening_shift');

            const btnAddProd = document.getElementById('btn-add-product-header');
            const btnAddCat = document.getElementById('btn-add-category-header');
            const btnAddType = document.getElementById('btn-add-type-header');
            const btnAddUnit = document.getElementById('btn-add-unit-header');
            const btnAddTax = document.getElementById('btn-add-tax-header');
            const btnAddOsp = document.getElementById('btn-add-osp-header');

            // Hide all sub-views first
            if (catalogView) catalogView.classList.add('hidden');
            if (categoriesView) categoriesView.classList.add('hidden');
            if (typesView) typesView.classList.add('hidden');
            if (unitsView) unitsView.classList.add('hidden');
            if (taxesView) taxesView.classList.add('hidden');
            if (openingShiftView) openingShiftView.classList.add('hidden');

            // Reset tab button styles
            const inactiveClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-slate-100 hover:bg-slate-200/80 text-slate-700 hover:text-slate-900 dark:bg-slate-800 dark:hover:bg-slate-700 dark:text-slate-300 dark:hover:text-white border border-transparent dark:border-slate-700';
            const activeClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-indigo-600 text-white shadow-2xs';

            if (btnCatalog) btnCatalog.className = inactiveClass;
            if (btnCategories) btnCategories.className = inactiveClass;
            if (btnTypes) btnTypes.className = inactiveClass;
            if (btnUnits) btnUnits.className = inactiveClass;
            if (btnTaxes) btnTaxes.className = inactiveClass;
            if (btnOpeningShift) btnOpeningShift.className = inactiveClass;

            // Hide all action buttons
            if (btnAddProd) btnAddProd.classList.add('hidden');
            if (btnAddCat) btnAddCat.classList.add('hidden');
            if (btnAddType) btnAddType.classList.add('hidden');
            if (btnAddUnit) btnAddUnit.classList.add('hidden');
            if (btnAddTax) btnAddTax.classList.add('hidden');
            if (btnAddOsp) btnAddOsp.classList.add('hidden');

            if (subTab === 'categories') {
                if (categoriesView) categoriesView.classList.remove('hidden');
                if (btnCategories) btnCategories.className = activeClass;
                if (btnAddCat) btnAddCat.classList.remove('hidden');
                loadCategoriesTable();
            } else if (subTab === 'types') {
                if (typesView) typesView.classList.remove('hidden');
                if (btnTypes) btnTypes.className = activeClass;
                if (btnAddType) btnAddType.classList.remove('hidden');
                loadProductTypesTable();
            } else if (subTab === 'units') {
                if (unitsView) unitsView.classList.remove('hidden');
                if (btnUnits) btnUnits.className = activeClass;
                if (btnAddUnit) btnAddUnit.classList.remove('hidden');
                loadProductUnitsTable();
            } else if (subTab === 'taxes') {
                if (taxesView) taxesView.classList.remove('hidden');
                if (btnTaxes) btnTaxes.className = activeClass;
                if (btnAddTax) btnAddTax.classList.remove('hidden');
                loadTaxes();
            } else if (subTab === 'opening_shift') {
                if (openingShiftView) openingShiftView.classList.remove('hidden');
                if (btnOpeningShift) btnOpeningShift.className = activeClass;
                if (btnAddOsp) btnAddOsp.classList.remove('hidden');
                loadOpeningShiftProductsTable();
            } else {
                if (catalogView) catalogView.classList.remove('hidden');
                if (btnCatalog) btnCatalog.className = activeClass;
                if (btnAddProd) btnAddProd.classList.remove('hidden');
                loadAllProducts();
            }
            lucide.createIcons();
        }

        // ==========================================
        // SUB-TAB 2: CRUD KATEGORI PRODUK
        // ==========================================
        async function loadCategoriesTable() {
            try {
                const res = await fetch('api.php?action=get_categories');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }
                state.categories = data.categories;

                const tbody = document.getElementById('categories-table-body');
                if (!tbody) return;

                tbody.innerHTML = data.categories.map(c => {
                    const isProtected = Number(c.id) === 1;
                    const stockStatus = (c.is_stockable !== undefined) ? Number(c.is_stockable) : 1;
                    let stockBadge = '';
                    if (stockStatus === 2) {
                        stockBadge = `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 dark:bg-amber-950/70 text-amber-800 dark:text-amber-300 border border-amber-300 dark:border-amber-800">🔄 Hibrida</span>
                                      <button onclick="toggleCategoryStockable(${c.id}, 1)" class="text-[9px] text-slate-400 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400 underline">Ubah ke Wajib Stok</button>`;
                    } else if (stockStatus === 0) {
                        stockBadge = `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-violet-100 dark:bg-violet-950/70 text-violet-800 dark:text-violet-300 border border-violet-200 dark:border-violet-800">⚡ Tanpa Stok (BOM)</span>
                                      <button onclick="toggleCategoryStockable(${c.id}, 2)" class="text-[9px] text-slate-400 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400 underline">Ubah ke Hibrida</button>`;
                    } else {
                        stockBadge = `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 dark:bg-emerald-950/70 text-emerald-800 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800">📦 Wajib Stok</span>
                                      <button onclick="toggleCategoryStockable(${c.id}, 0)" class="text-[9px] text-slate-400 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400 underline">Ubah ke Tanpa Stok</button>`;
                    }
                    return `
                        <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                            <td class="py-3 px-4 font-mono font-bold text-slate-500 dark:text-slate-400">#${c.id}</td>
                            <td class="py-3 px-4 text-xl">${c.icon || '🏷️'}</td>
                            <td class="py-3 px-4 font-bold text-slate-800 dark:text-slate-100">${c.name}</td>
                            <td class="py-3 px-4 font-semibold text-slate-600 dark:text-slate-300">${c.product_count || 0} Produk Terkait</td>
                            <td class="py-3 px-4 text-center">
                                <div class="inline-flex flex-col items-center gap-1">
                                    ${stockBadge}
                                </div>
                            </td>
                            <td class="py-3 px-4 text-center space-x-1">
                                <button onclick='editCategory(${JSON.stringify(c)})' class="px-2.5 py-1 bg-purple-50 dark:bg-purple-950/60 text-purple-700 dark:text-purple-300 hover:bg-purple-100 dark:hover:bg-purple-900/60 rounded-lg text-[11px] font-bold transition-colors border border-purple-200 dark:border-purple-800">Edit</button>
                                ${!isProtected ? `<button onclick="deleteCategory(${c.id}, '${c.name.replace(/'/g, "\\'")}')" class="px-2.5 py-1 bg-rose-50 dark:bg-rose-950/60 text-rose-600 dark:text-rose-300 hover:bg-rose-100 dark:hover:bg-rose-900/60 rounded-lg text-[11px] font-bold transition-colors border border-rose-200 dark:border-rose-800">Hapus</button>` : '<span class="text-[10px] text-slate-400 dark:text-slate-400 font-semibold px-2 py-0.5 bg-slate-100 dark:bg-slate-800 rounded border border-slate-200 dark:border-slate-700">Default</span>'}
                            </td>
                        </tr>
                    `;
                }).join('');
                lucide.createIcons();
            } catch (err) {
                console.error('Gagal memuat tabel kategori:', err);
            }
        }

        function openCategoryModal() {
            document.getElementById('category-modal-id').value = '';
            document.getElementById('category-modal-name').value = '';
            document.getElementById('category-modal-icon').value = '🏷️';
            const stkEl = document.getElementById('category-modal-is-stockable');
            if (stkEl) stkEl.value = '1';
            document.getElementById('category-modal-title').innerText = 'Tambah Kategori Baru';
            document.getElementById('category-modal').classList.remove('hidden');
        }

        function editCategory(c) {
            openCategoryModal();
            document.getElementById('category-modal-id').value = c.id;
            document.getElementById('category-modal-name').value = c.name;
            document.getElementById('category-modal-icon').value = c.icon || '🏷️';
            const stkEl = document.getElementById('category-modal-is-stockable');
            if (stkEl) stkEl.value = (c.is_stockable !== undefined && c.is_stockable !== null) ? String(c.is_stockable) : '1';
            document.getElementById('category-modal-title').innerText = 'Edit Kategori: ' + c.name;
        }

        async function toggleCategoryStockable(id, newStatus) {
            try {
                const res = await fetch('api.php?action=toggle_category_stockable', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: id, is_stockable: newStatus })
                });
                const data = await res.json();
                if (data.success) {
                    await loadCategoriesTable();
                    await initApp();
                    if (typeof loadAllProducts === 'function') await loadAllProducts();
                } else {
                    alert(data.message || 'Gagal mengubah status stok kategori');
                }
            } catch (err) {
                alert('Terjadi kesalahan jaringan saat mengubah status stok kategori.');
            }
        }

        function closeCategoryModal() {
            document.getElementById('category-modal').classList.add('hidden');
        }

        async function saveCategoryForm(e) {
            e.preventDefault();
            const id = document.getElementById('category-modal-id').value;
            const stkEl = document.getElementById('category-modal-is-stockable');
            const isStockable = stkEl ? parseInt(stkEl.value) : 1;
            const payload = {
                id: id ? parseInt(id) : null,
                name: document.getElementById('category-modal-name').value.trim(),
                icon: document.getElementById('category-modal-icon').value.trim() || '🏷️',
                is_stockable: isStockable
            };

            const btn = document.getElementById('category-modal-submit-btn');
            btn.disabled = true;

            try {
                const res = await fetch('api.php?action=save_category', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                btn.disabled = false;
                alert(data.message || data.error);
                if (data.success) {
                    closeCategoryModal();
                    loadCategoriesTable();
                    initApp();
                }
            } catch (err) {
                btn.disabled = false;
                alert('Terjadi kesalahan jaringan.');
            }
        }

        async function deleteCategory(id, name) {
            if (!confirm(`Hapus kategori '${name}'?`)) return;
            try {
                const res = await fetch('api.php?action=delete_category', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    loadCategoriesTable();
                    initApp();
                }
            } catch (err) {
                alert('Terjadi kesalahan jaringan.');
            }
        }

        // ==========================================
        // SUB-TAB 3: CRUD MASTER JENIS PRODUK
        // ==========================================
        async function loadProductTypesTable() {
            try {
                const res = await fetch('api.php?action=get_product_types');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }
                state.productTypes = data.product_types;

                const tbody = document.getElementById('product-types-table-body');
                if (!tbody) return;

                const coreCodes = ['FINISHED_GOODS', 'RAW_MATERIAL', 'SERVICE'];

                tbody.innerHTML = data.product_types.map(pt => {
                    const isCore = coreCodes.includes(pt.code);
                    const stockableBadge = Number(pt.is_stockable) === 1
                        ? '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 dark:bg-emerald-950/70 text-emerald-800 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800">Ya (Stok Fisik)</span>'
                        : '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700">Tidak</span>';
                    const saleableBadge = Number(pt.is_saleable) === 1
                        ? '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-100 dark:bg-indigo-950/70 text-indigo-800 dark:text-indigo-300 border border-indigo-200 dark:border-indigo-800">Ya (Kasir POS)</span>'
                        : '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 dark:bg-amber-950/70 text-amber-800 dark:text-amber-300 border border-amber-200 dark:border-amber-800">Bahan Resep</span>';

                    return `
                        <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                            <td class="py-3 px-4 font-mono font-bold text-teal-800 dark:text-teal-400">${pt.icon_emoji || '📦'} ${pt.code}</td>
                            <td class="py-3 px-4 font-bold text-slate-800 dark:text-slate-100">${pt.name}</td>
                            <td class="py-3 px-4 text-center font-mono font-black text-indigo-600 dark:text-indigo-300 bg-indigo-50/50 dark:bg-indigo-950/50 rounded">${pt.prefix}-00001</td>
                            <td class="py-3 px-4 text-center">${stockableBadge}</td>
                            <td class="py-3 px-4 text-center">${saleableBadge}</td>
                            <td class="py-3 px-4 text-slate-600 dark:text-slate-300">${pt.description || '-'}</td>
                            <td class="py-3 px-4 text-center font-bold text-slate-700 dark:text-slate-300">${pt.product_count || 0} Item</td>
                            <td class="py-3 px-4 text-center space-x-1">
                                <button onclick='editProductType(${JSON.stringify(pt)})' class="px-2.5 py-1 bg-teal-50 dark:bg-teal-950/60 text-teal-700 dark:text-teal-300 hover:bg-teal-100 dark:hover:bg-teal-900/60 rounded-lg text-[11px] font-bold transition-colors border border-teal-200 dark:border-teal-800">Edit</button>
                                ${!isCore ? `<button onclick="deleteProductType(${pt.id}, '${pt.name.replace(/'/g, "\\'")}')" class="px-2.5 py-1 bg-rose-50 dark:bg-rose-950/60 text-rose-600 dark:text-rose-300 hover:bg-rose-100 dark:hover:bg-rose-900/60 rounded-lg text-[11px] font-bold transition-colors border border-rose-200 dark:border-rose-800">Hapus</button>` : '<span class="text-[10px] text-slate-400 dark:text-slate-400 font-semibold px-2 py-0.5 bg-slate-100 dark:bg-slate-800 rounded border border-slate-200 dark:border-slate-700">Sistem Inti</span>'}
                            </td>
                        </tr>
                    `;
                }).join('');
                lucide.createIcons();
            } catch (err) {
                console.error('Gagal memuat jenis produk:', err);
            }
        }

