                const res = await fetch('api.php?action=delete_tax', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    loadTaxes();
                    initApp();
                }
            } catch (err) {
                alert('Terjadi kesalahan jaringan.');
            }
        }

        // ==========================================
        // SUB-TAB 6: CRUD PRODUK PELACAKAN OPENING SALES
        // ==========================================
        async function loadOpeningShiftProductsTable() {
            try {
                const res = await fetch('api.php?action=get_opening_shift_products');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }
                state.openingShiftProducts = data.products || [];

                const tbody = document.getElementById('opening-shift-products-table-body');
                if (!tbody) return;

                if (state.openingShiftProducts.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="7" class="py-4 text-center text-slate-400">Belum ada produk pelacakan opening shift. Klik '+ Tambah Produk' untuk menambahkan.</td></tr>`;
                    return;
                }

                tbody.innerHTML = state.openingShiftProducts.map((p, idx) => {
                    const statusBadge = p.is_active != 0
                        ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800">Aktif Dilacak</span>'
                        : '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-300 dark:border-slate-700">Nonaktif</span>';

                    return `
                        <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                            <td class="py-3 px-4 text-center font-mono font-bold text-slate-500 dark:text-slate-400">${p.sort_order || (idx + 1)}</td>
                            <td class="py-3 px-4 font-mono font-bold text-indigo-700 dark:text-indigo-400">${p.sku}</td>
                            <td class="py-3 px-4 font-black text-slate-800 dark:text-slate-100">
                                <span class="mr-1.5">${p.image_emoji || '📦'}</span>${p.name}${
                                    (Number(p.is_stockable) === 2)
                                        ? ' <span class="inline-block text-[9px] px-1.5 py-0.2 bg-amber-100 dark:bg-amber-950/70 text-amber-800 dark:text-amber-300 border border-amber-300 dark:border-amber-800 rounded font-bold">🔄 Hibrida</span>'
                                        : ((p.effective_is_stockable === 0 || p.requires_stock === 0) ? ' <span class="inline-block text-[9px] px-1.5 py-0.2 bg-violet-100 dark:bg-violet-950/70 text-violet-800 dark:text-violet-300 border border-violet-200 dark:border-violet-800 rounded font-bold">⚡ Tanpa Stok</span>' : '')
                                }
                            </td>
                            <td class="py-3 px-4">
                                <span class="px-2 py-0.5 rounded-md text-[10px] font-bold ${p.product_type === 'RAW_MATERIAL' ? 'bg-amber-100 dark:bg-amber-950/70 text-amber-900 dark:text-amber-300' : 'bg-indigo-100 dark:bg-indigo-950/70 text-indigo-900 dark:text-indigo-300'}">${p.product_type}</span>
                                <span class="text-[11px] text-slate-500 dark:text-slate-400 ml-1">• ${p.category}</span>
                            </td>
                            <td class="py-3 px-4 font-semibold text-slate-600 dark:text-slate-300">${p.unit}</td>
                            <td class="py-3 px-4 text-center">${statusBadge}</td>
                            <td class="py-3 px-4 text-center space-x-1 whitespace-nowrap">
                                <button onclick="toggleOpeningShiftProductStatus(${p.product_id}, ${p.is_active != 0 ? 0 : 1})" class="px-2.5 py-1 ${p.is_active != 0 ? 'bg-amber-50 dark:bg-amber-950/60 text-amber-700 dark:text-amber-300 hover:bg-amber-100 dark:hover:bg-amber-900/60' : 'bg-emerald-50 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-300 hover:bg-emerald-100 dark:hover:bg-emerald-900/60'} rounded-lg text-[11px] font-bold transition-colors border ${p.is_active != 0 ? 'border-amber-200 dark:border-amber-800' : 'border-emerald-200 dark:border-emerald-800'}">
                                    ${p.is_active != 0 ? 'Nonaktifkan' : 'Aktifkan'}
                                </button>
                                <button onclick="deleteOpeningShiftProduct(${p.product_id}, '${p.name.replace(/'/g, "\\'")}')" class="px-2.5 py-1 bg-rose-50 dark:bg-rose-950/60 text-rose-600 dark:text-rose-300 hover:bg-rose-100 dark:hover:bg-rose-900/60 rounded-lg text-[11px] font-bold transition-colors border border-rose-200 dark:border-rose-800">
                                    Hapus
                                </button>
                            </td>
                        </tr>
                    `;
                }).join('');
                lucide.createIcons();
            } catch (err) {
                console.error('Gagal memuat produk opening shift:', err);
            }
        }

        async function openOpeningShiftProductModal() {
            // Load dropdown seluruh produk aktif
            const selectEl = document.getElementById('osp-modal-product-select');
            if (selectEl) {
                const prods = state.allProducts && state.allProducts.length > 0 ? state.allProducts : state.products;
                // Exclude yang sudah terdaftar
                const existingIds = (state.openingShiftProducts || []).map(o => Number(o.product_id));
                selectEl.innerHTML = prods.map(p => {
                    const isAlready = existingIds.includes(Number(p.id));
                    return `<option value="${p.id}" ${isAlready ? 'disabled class="text-slate-300"' : ''}>${p.sku} - ${p.name} (${p.unit}) ${isAlready ? '[Sudah Terdaftar]' : ''}</option>`;
                }).join('');
            }
            document.getElementById('osp-modal-sort-order').value = (state.openingShiftProducts ? state.openingShiftProducts.length + 1 : 1);
            document.getElementById('osp-modal-is-active').value = '1';
            document.getElementById('opening-shift-product-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function closeOpeningShiftProductModal() {
            document.getElementById('opening-shift-product-modal').classList.add('hidden');
        }

        async function saveOpeningShiftProductForm(e) {
            e.preventDefault();
            const prodId = parseInt(document.getElementById('osp-modal-product-select').value);
            const sortOrder = parseInt(document.getElementById('osp-modal-sort-order').value) || 0;
            const isActive = parseInt(document.getElementById('osp-modal-is-active').value);

            if (!prodId) {
                alert('Pilih produk yang valid.');
                return;
            }

            try {
                const res = await fetch('api.php?action=save_opening_shift_product', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ product_id: prodId, sort_order: sortOrder, is_active: isActive })
                });
                const data = await res.json();
                alert(data.message || (data.success ? 'Berhasil disimpan!' : 'Gagal menyimpan'));
                if (data.success) {
                    closeOpeningShiftProductModal();
                    loadOpeningShiftProductsTable();
                }
            } catch (err) {
                alert('Terjadi kesalahan jaringan.');
            }
        }

        async function toggleOpeningShiftProductStatus(productId, newStatus) {
            try {
                const res = await fetch('api.php?action=save_opening_shift_product', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ product_id: productId, is_active: newStatus })
                });
                const data = await res.json();
                if (data.success) {
                    loadOpeningShiftProductsTable();
                } else alert(data.message || data.error);
            } catch (err) {
                alert('Terjadi kesalahan jaringan.');
            }
        }

        async function deleteOpeningShiftProduct(productId, name) {
            if (!confirm(`Hapus produk '${name}' dari daftar pelacakan Opening Shift?`)) return;
            try {
                const res = await fetch('api.php?action=delete_opening_shift_product', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ product_id: productId })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    loadOpeningShiftProductsTable();
                }
            } catch (err) {
                alert('Terjadi kesalahan jaringan.');
            }
        }

        // ==========================================
        // 6. RECIPE / BOM (BILL OF MATERIALS)
        // ==========================================
        async function loadBOMRecipes() {
            const res = await fetch('api.php?action=get_recipes');
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }
            state.recipesData = data;

            document.getElementById('bom-cards-grid').innerHTML = data.finished_goods.map(function(fg) {
                var ingHtml = (fg.ingredients && fg.ingredients.length > 0) ? fg.ingredients.map(function(ing) {
                    var isFg = (ing.ingredient_product_type === 'FINISHED_GOODS');
                    var typeBadge = isFg 
                        ? '<span class="px-1.5 py-0.5 text-[9px] font-bold rounded-md bg-amber-100 dark:bg-amber-950/80 text-amber-800 dark:text-amber-300 border border-amber-200 dark:border-amber-800">📦 Produk Jadi</span>'
                        : '<span class="px-1.5 py-0.5 text-[9px] font-bold rounded-md bg-slate-200/70 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-300/60 dark:border-slate-700">🧪 Bahan Baku</span>';
                    var escapedName = ing.ingredient_name ? escapeHtml(ing.ingredient_name) : '-';
                    var escapedUnit = ing.unit ? escapeHtml(ing.unit) : 'pcs';

                    return '<div class="flex items-center justify-between p-2.5 bg-slate-50 dark:bg-slate-800/60 rounded-xl border border-slate-100 dark:border-slate-700">' +
                        '<div>' +
                            '<div class="flex items-center space-x-1.5">' +
                                '<span class="font-bold text-slate-700 dark:text-slate-200">' + escapedName + '</span>' +
                                typeBadge +
                            '</div>' +
                            '<span class="text-[10px] text-slate-400 block">' + formatDecimal(ing.qty_needed) + ' ' + escapedUnit + ' @ ' + formatRupiah(ing.ingredient_cogs) + '/' + escapedUnit + '</span>' +
                        '</div>' +
                        '<div class="flex items-center space-x-2">' +
                            '<span class="font-mono text-slate-700 dark:text-slate-200 font-bold">' + formatRupiah(ing.subtotal_ingredient_cost) + '</span>' +
                            '<button type="button" onclick="deleteRecipeItem(' + ing.id + ')" class="text-rose-500 hover:text-rose-700 dark:hover:text-rose-400 p-1" title="Hapus dari formula resep">' +
                                '<i data-lucide="trash-2" class="w-3.5 h-3.5"></i>' +
                            '</button>' +
                        '</div>' +
                    '</div>';
                }).join('') : '<p class="text-slate-400 text-center py-2.5 font-medium">Belum ada formula resep bahan / produk</p>';

                var hasBOM = (fg.ingredients && fg.ingredients.length > 0);
                var deleteBtnHtml = hasBOM ? 
                    '<button type="button" onclick="deleteBaseBOM(' + fg.id + ', \'' + (fg.name ? fg.name.replace(/'/g, "\\'") : '') + '\')" class="px-2.5 py-1.5 bg-rose-50 dark:bg-rose-950/60 hover:bg-rose-100 dark:hover:bg-rose-900/60 text-rose-600 dark:text-rose-400 rounded-xl text-xs font-bold border border-rose-200 dark:border-rose-800/80 flex items-center space-x-1 transition-colors shadow-2xs" title="Hapus seluruh formula resep Base BOM untuk ' + escapeHtml(fg.name) + '">' +
                        '<i data-lucide="trash-2" class="w-3.5 h-3.5 text-rose-500 dark:text-rose-400"></i>' +
                        '<span>Hapus BOM</span>' +
                    '</button>' : '';

                return '<div class="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm space-y-3 text-slate-800 dark:text-slate-100">' +
                    '<div class="flex items-center justify-between border-b border-slate-100 dark:border-slate-800 pb-2.5">' +
                        '<div>' +
                            '<h4 class="font-bold text-slate-800 dark:text-slate-100 text-sm flex items-center space-x-1.5">' +
                                '<span class="text-xl">☕</span>' +
                                '<span>' + escapeHtml(fg.name) + '</span>' +
                            '</h4>' +
                            '<p class="text-[10px] text-slate-400 font-medium">' + escapeHtml(fg.sku) + ' &bull; Jual: ' + formatRupiah(fg.selling_price) + '</p>' +
                        '</div>' +
                        '<div class="flex items-center space-x-1.5">' +
                            deleteBtnHtml +
                            '<button type="button" onclick="openAddRecipeModal(' + fg.id + ', \'' + (fg.name ? fg.name.replace(/'/g, "\\'") : '') + '\')" class="px-3 py-1.5 bg-indigo-50 dark:bg-indigo-950/60 hover:bg-indigo-100 dark:hover:bg-indigo-900/60 text-indigo-700 dark:text-indigo-300 rounded-xl text-xs font-bold border border-indigo-200 dark:border-indigo-800 flex items-center space-x-1 transition-colors shadow-2xs">' +
                                '<i data-lucide="plus" class="w-3.5 h-3.5"></i>' +
                                '<span>+ Komponen Resep</span>' +
                            '</button>' +
                        '</div>' +
                    '</div>' +

                    '<!-- Ingredients List -->' +
                    '<div class="space-y-1.5 text-xs">' +
                        ingHtml +
                    '</div>' +

                    '<!-- Total BOM Cost Calculation -->' +
                    '<div class="p-3 bg-emerald-50 dark:bg-emerald-950/50 rounded-xl border border-emerald-200 dark:border-emerald-800/80 flex justify-between items-center text-xs">' +
                        '<span class="font-bold text-emerald-900 dark:text-emerald-300">Total HPP Berbasis Resep:</span>' +
                        '<span class="font-black text-emerald-800 dark:text-emerald-400 text-sm font-mono">' + formatRupiah(fg.calculated_cogs) + '</span>' +
                    '</div>' +
                '</div>';
            }).join('');
            lucide.createIcons();
        }

        var currentRecipeFgId = 0;
        var currentRecipeTypeFilter = 'ALL';

        function renderUnitSelectOptions(selectId, selectedUnit) {
            var select = document.getElementById(selectId);
            if (!select) return;
            var units = (state.productUnits && state.productUnits.length > 0)
                ? state.productUnits.map(function(u) { return { code: u.code, label: u.code + ' - ' + u.name }; })
                : ['pcs', 'cup', 'botol', 'porsi', 'gram', 'kg', 'ml', 'liter', 'pack', 'box', 'ball'].map(function(u) { return { code: u, label: u }; });
            
            var currentCode = (selectedUnit || '').toLowerCase().trim();
            if (currentCode) {
                var exists = units.some(function(u) { return u.code.toLowerCase() === currentCode; });
                if (!exists) {
                    units.unshift({ code: selectedUnit, label: selectedUnit });
                }
            }
            select.innerHTML = units.map(function(u) {
                return '<option value="' + u.code + '" ' + (u.code.toLowerCase() === currentCode ? 'selected' : '') + '>' + escapeHtml(u.label) + '</option>';
            }).join('');
            if (currentCode) {
                select.value = selectedUnit;
            }
        }

        function openAddRecipeModal(fgId, fgName) {
            currentRecipeFgId = parseInt(fgId, 10) || 0;
            currentRecipeTypeFilter = 'ALL';
            document.getElementById('recipe-finished-id').value = String(currentRecipeFgId);
            document.getElementById('recipe-modal-product-name').innerText = 'Produk: ' + fgName;

            updateRecipeFilterTabUI('ALL');
            renderRecipeIngredientOptions();

            document.getElementById('recipe-qty-needed').value = '1';
            onRecipeIngredientChange();
            document.getElementById('recipe-add-modal').classList.remove('hidden');
        }

        function setRecipeIngredientTypeFilter(filterType) {
            currentRecipeTypeFilter = filterType;
            updateRecipeFilterTabUI(filterType);
            renderRecipeIngredientOptions();
            onRecipeIngredientChange();
        }

        function updateRecipeFilterTabUI(activeType) {
            var tabs = [
                { id: 'recipe-filter-tab-all', type: 'ALL' },
                { id: 'recipe-filter-tab-raw', type: 'RAW_MATERIAL' },
                { id: 'recipe-filter-tab-fg', type: 'FINISHED_GOODS' }
            ];
            tabs.forEach(function(t) {
                var btn = document.getElementById(t.id);
                if (!btn) return;
                if (t.type === activeType) {
                    btn.className = 'py-1.5 px-2 rounded-lg font-bold text-[11px] bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-300 shadow-2xs transition-all';
                } else {
                    btn.className = 'py-1.5 px-2 rounded-lg font-bold text-[11px] text-slate-600 dark:text-slate-400 hover:bg-white/60 dark:hover:bg-slate-700/60 transition-all';
                }
            });
        }

        function renderRecipeIngredientOptions() {
            var sel = document.getElementById('recipe-ingredient-select');
            if (!sel) return;

            var rawMaterials = (state.recipesData && state.recipesData.raw_materials) ? state.recipesData.raw_materials : [];
            var fgList = (state.recipesData && state.recipesData.fg_ingredients) 
                ? state.recipesData.fg_ingredients 
                : ((state.recipesData && state.recipesData.finished_goods) ? state.recipesData.finished_goods : []);

            // Filter out the product itself from fgList to prevent self-dependency!
            var filteredFg = fgList.filter(function(fg) {
                return parseInt(fg.id, 10) !== parseInt(currentRecipeFgId, 10);
            });

            var html = '';

            if (currentRecipeTypeFilter === 'ALL' || currentRecipeTypeFilter === 'RAW_MATERIAL') {
                if (rawMaterials.length > 0) {
                    html += '<optgroup label="🧪 Bahan Baku (Raw Material)">';
                    rawMaterials.forEach(function(rm) {
                        html += '<option value="' + rm.id + '" data-type="RAW_MATERIAL">🧪 ' + escapeHtml(rm.name) + ' (' + escapeHtml(rm.sku) + ' - Satuan: ' + escapeHtml(rm.unit) + ')</option>';
                    });
                    html += '</optgroup>';
                }
            }

            if (currentRecipeTypeFilter === 'ALL' || currentRecipeTypeFilter === 'FINISHED_GOODS') {
                if (filteredFg.length > 0) {
                    html += '<optgroup label="📦 Produk Jadi (Finished Goods)">';
                    filteredFg.forEach(function(fg) {
                        html += '<option value="' + fg.id + '" data-type="FINISHED_GOODS">📦 ' + escapeHtml(fg.name) + ' (' + escapeHtml(fg.sku) + ' - Satuan: ' + escapeHtml(fg.unit) + ')</option>';
                    });
                    html += '</optgroup>';
                }
            }

            if (!html) {
                html = '<option value="" disabled>-- Tidak ada item yang sesuai --</option>';
            }

            sel.innerHTML = html;
        }

        function onRecipeIngredientChange() {
            var sel = document.getElementById('recipe-ingredient-select');
            var ingId = sel ? parseInt(sel.value, 10) : 0;
            var rawMaterials = (state.recipesData && state.recipesData.raw_materials) ? state.recipesData.raw_materials : [];
            var fgList = (state.recipesData && state.recipesData.fg_ingredients) 
                ? state.recipesData.fg_ingredients 
                : ((state.recipesData && state.recipesData.finished_goods) ? state.recipesData.finished_goods : []);

            var foundItem = rawMaterials.find(function(r) { return parseInt(r.id, 10) === ingId; });
            if (!foundItem) {
                foundItem = fgList.find(function(f) { return parseInt(f.id, 10) === ingId; });
            }

            var unit = foundItem ? (foundItem.unit || 'pcs') : 'pcs';
            renderUnitSelectOptions('recipe-unit-name', unit);

            updateRecipeCogsPreview();
        }

        function updateRecipeCogsPreview() {
            var sel = document.getElementById('recipe-ingredient-select');
            var ingId = sel ? parseInt(sel.value, 10) : 0;
            var rawMaterials = (state.recipesData && state.recipesData.raw_materials) ? state.recipesData.raw_materials : [];
            var fgList = (state.recipesData && state.recipesData.fg_ingredients) 
                ? state.recipesData.fg_ingredients 
                : ((state.recipesData && state.recipesData.finished_goods) ? state.recipesData.finished_goods : []);

            var foundItem = rawMaterials.find(function(r) { return parseInt(r.id, 10) === ingId; });
            if (!foundItem) {
                foundItem = fgList.find(function(f) { return parseInt(f.id, 10) === ingId; });
            }

            var unit = foundItem ? (foundItem.unit || 'pcs') : 'pcs';
            var qtyInput = document.getElementById('recipe-qty-needed');
            var qtyVal = qtyInput ? (parseFloat(qtyInput.value) || 0) : 0;
            var cogsPerUnit = foundItem ? (parseFloat(foundItem.cogs) || 0) : 0;
            var totalCogs = qtyVal * cogsPerUnit;

            var cogsValEl = document.getElementById('recipe-cogs-val');
            if (cogsValEl) {
                cogsValEl.innerText = formatRupiah(totalCogs) + (foundItem ? ' (@ ' + formatRupiah(cogsPerUnit) + '/' + unit + ')' : '');
            }
        }

        function closeRecipeModal() {
            document.getElementById('recipe-add-modal').classList.add('hidden');
        }

        async function saveRecipeItemForm(e) {
            e.preventDefault();
            const payload = {
                finished_product_id: parseInt(document.getElementById('recipe-finished-id').value),
                ingredient_product_id: parseInt(document.getElementById('recipe-ingredient-select').value),
                qty_needed: parseFloat(document.getElementById('recipe-qty-needed').value),
                unit: document.getElementById('recipe-unit-name').value
            };

            const res = await fetch('api.php?action=save_recipe_item', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeRecipeModal();
                loadBOMRecipes();
            }
        }

        async function deleteRecipeItem(id) {
            if (!confirm('Hapus komponen ini dari formula resep?')) return;
            try {
                const res = await fetch('api.php?action=delete_recipe_item', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ recipe_id: id })
                });
                const data = await res.json();
                if (data.success) {
                    alert('✅ ' + (data.message || 'Komponen berhasil dihapus dari resep.'));
                    loadBOMRecipes();
                } else {
                    alert('⚠️ TIDAK BISA DIHAPUS:\n\n' + (data.message || data.error || 'Terjadi kesalahan saat menghapus komponen resep.'));
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan koneksi saat menghapus komponen resep.');
            }
        }

        async function deleteBaseBOM(productId, productName) {
            const confirmed = confirm(`Apakah Anda yakin ingin menghapus seluruh formula resep Base BOM untuk produk "${productName}"?\n\nSetelah dihapus, penjualan produk ini tidak akan memotong bahan baku Base BOM secara otomatis.`);
            if (!confirmed) return;

            try {
                const res = await fetch('api.php?action=delete_base_bom', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ product_id: productId })
                });
                const data = await res.json();
                if (data.success) {
                    alert('✅ ' + (data.message || 'Formula resep Base BOM berhasil dihapus.'));
                    loadBOMRecipes();
                } else {
                    alert('⚠️ TIDAK BISA DIHAPUS:\n\n' + (data.message || data.error || 'Terjadi kesalahan sistem'));
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan koneksi saat menghapus Base BOM.');
            }
        }

        async function resetAllBaseBOM() {
            const confirmed = confirm('⚠️ PERINGATAN: Apakah Anda yakin ingin menghapus SELURUH formula resep Base BOM untuk semua produk jadi?\n\nTindakan ini akan mengosongkan seluruh bahan baku resep utama di semua produk. Tindakan ini tidak dapat dibatalkan.');
            if (!confirmed) return;

            const secondCheck = prompt('Ketik "HAPUS BOM" untuk mengonfirmasi penghapusan seluruh Base BOM:');
            if (secondCheck !== 'HAPUS BOM') {
                alert('Konfirmasi dibatalkan atau teks konfirmasi tidak cocok.');
                return;
            }

            try {
                const res = await fetch('api.php?action=reset_all_base_bom', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({})
                });
                const data = await res.json();
                if (data.success) {
                    alert('✅ ' + (data.message || 'Seluruh Base BOM berhasil dihapus.'));
                    loadBOMRecipes();
                } else {
                    alert('⚠️ TIDAK BISA DIHAPUS:\n\n' + (data.message || data.error || 'Terjadi kesalahan sistem'));
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan koneksi saat mereset seluruh Base BOM.');
            }
        }

        // --- SUBTAB BOM: SWITCH SUBTAB & VARIANT BOM RECIPES ---
        function switchBOMSubTab(sub) {
            const btnBase = document.getElementById('bom-subtab-btn-base');
            const btnVar = document.getElementById('bom-subtab-btn-variant');
            const viewBase = document.getElementById('bom-view-base');
            const viewVar = document.getElementById('bom-view-variant');
            const actionsBase = document.getElementById('bom-base-actions');

            const activeClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-indigo-600 text-white shadow-2xs';
            const inactiveClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-slate-100 hover:bg-slate-200/80 text-slate-700 hover:text-slate-900 dark:bg-slate-800 dark:hover:bg-slate-700 dark:text-slate-300 dark:hover:text-white border border-transparent dark:border-slate-700';

            if (sub === 'base') {
                btnBase.className = activeClass;
                btnVar.className = inactiveClass;
                viewBase.classList.remove('hidden');
                viewVar.classList.add('hidden');
                if (actionsBase) actionsBase.classList.remove('hidden');
                loadBOMRecipes();
            } else {
                btnVar.className = activeClass;
                btnBase.className = inactiveClass;
                viewVar.classList.remove('hidden');
                viewBase.classList.add('hidden');
                if (actionsBase) actionsBase.classList.add('hidden');
                loadVariantBOMRecipes();
            }
            lucide.createIcons();
        }

        async function loadVariantBOMRecipes() {
            try {
                const res = await fetch('api.php?action=get_variant_recipes');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                state.variantRecipesData = data;
                const container = document.getElementById('variant-bom-cards-grid');
                if (!container) return;

                if (!data.variants || data.variants.length === 0) {
                    container.innerHTML = `<div class="col-span-2 text-center py-12 text-slate-400 text-sm">Belum ada varian produk yang terdaftar.</div>`;
                    return;
                }

                container.innerHTML = data.variants.map(v => {
                    const hasIngs = (v.ingredients && v.ingredients.length > 0);
                    const addPrice = Number(v.additional_price || 0);
                    const isFree = addPrice === 0;
                    const primaryVarId = v.primary_variant_id || v.id;
                    const productsList = v.products && v.products.length > 0 ? v.products : [{
                        variant_id: v.id,
                        product_id: v.product_id,
                        product_name: v.product_name || 'Produk Induk',
                        product_sku: v.product_sku || 'PRD',
                        sku_variant: v.sku_variant
                    }];

                    const priceBadge = isFree
                        ? `<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-300 dark:border-slate-700">Harga Normal (+Rp 0 Bebas Biaya)</span>`
                        : `<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-800">+${formatRupiah(addPrice)} (Ada Tambahan Harga)</span>`;

                    return `
                        <div class="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200/90 dark:border-slate-800 shadow-sm hover:shadow-md transition-shadow overflow-hidden flex flex-col">
                            <!-- Card Header (Variant Identity & Action Toolbar) -->
                            <div class="p-4 border-b border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 space-y-3">
                                <div class="flex items-start justify-between gap-3">
                                    <div class="flex items-start space-x-3 min-w-0">
                                        <div class="w-10 h-10 rounded-2xl bg-gradient-to-br from-indigo-500 to-purple-600 text-white flex items-center justify-center shrink-0 text-base shadow-sm mt-0.5">
                                            ✨
                                        </div>
                                        <div class="min-w-0">
                                            <div class="flex flex-wrap items-center gap-1.5">
                                                <h4 class="font-black text-slate-900 dark:text-slate-100 text-sm leading-snug">
                                                    ${v.variant_name}
                                                </h4>
                                                <span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-black ${hasIngs ? 'bg-purple-100 dark:bg-purple-950/80 text-purple-800 dark:text-purple-300 border border-purple-200 dark:border-purple-800' : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700'}">
                                                    ${hasIngs ? '⚡ Potong BOM Tambahan' : '🛡️ Tanpa Potong Bahan'}
                                                </span>
                                            </div>
                                            <p class="text-[11px] text-slate-400 font-mono mt-0.5">
                                                Kode / SKU Varian: <span class="text-indigo-600 dark:text-indigo-400 font-bold bg-indigo-50 dark:bg-indigo-950/60 px-2 py-0.5 rounded-md border border-indigo-100 dark:border-indigo-800/80">${v.sku_variant}</span>
                                            </p>
                                        </div>
                                    </div>

                                    <!-- Quick Delete Variant Action -->
                                    <button onclick="deleteProductVariantGroup('${v.variant_name.replace(/'/g, "\\'")}', ${JSON.stringify(v.variant_ids || [v.id])})" class="p-2 bg-rose-50 dark:bg-rose-950/60 hover:bg-rose-100 dark:hover:bg-rose-900/60 text-rose-600 dark:text-rose-400 rounded-xl border border-rose-200 dark:border-rose-800 transition-colors shrink-0 shadow-2xs" title="Hapus Varian '${v.variant_name}' dari Semua Produk">
                                        <i data-lucide="trash-2" class="w-4 h-4"></i>
                                    </button>
                                </div>

                                <!-- Action Buttons Toolbar -->
                                <div class="flex flex-wrap items-center gap-1.5 pt-1 border-t border-slate-100 dark:border-slate-800">
                                    <button onclick='openApplyVariantToProductsModal(${JSON.stringify(v)})' class="px-3 py-1.5 bg-indigo-50 dark:bg-indigo-950/60 hover:bg-indigo-100 dark:hover:bg-indigo-900/60 text-indigo-700 dark:text-indigo-300 rounded-xl text-xs font-bold border border-indigo-200 dark:border-indigo-800 flex items-center space-x-1.5 transition-colors shadow-2xs">
                                        <i data-lucide="copy-plus" class="w-3.5 h-3.5 text-indigo-600 dark:text-indigo-400 shrink-0"></i>
                                        <span>+ Kelola / Tambah Produk Induk</span>
                                    </button>
                                    <button onclick='openEditVariantFromBOMModal(${JSON.stringify(v)})' class="px-2.5 py-1.5 bg-amber-50 dark:bg-amber-950/60 hover:bg-amber-100 dark:hover:bg-amber-900/60 text-amber-700 dark:text-amber-300 rounded-xl text-xs font-bold border border-amber-200 dark:border-amber-800 flex items-center space-x-1 transition-colors shadow-2xs">
                                        <i data-lucide="edit-3" class="w-3.5 h-3.5 text-amber-600 dark:text-amber-400 shrink-0"></i>
                                        <span>Edit Harga</span>
                                    </button>
                                    <button onclick="openAddVariantRecipeModal(${primaryVarId}, '${v.variant_name.replace(/'/g, "\\'")}', 'Semua Produk Terkait')" class="px-2.5 py-1.5 bg-purple-50 dark:bg-purple-950/60 hover:bg-purple-100 dark:hover:bg-purple-900/60 text-purple-700 dark:text-purple-300 rounded-xl text-xs font-bold border border-purple-200 dark:border-purple-800 flex items-center space-x-1 transition-colors shadow-2xs">
                                        <i data-lucide="plus" class="w-3.5 h-3.5 text-purple-600 dark:text-purple-400 shrink-0"></i>
                                        <span>+ Resep Bahan</span>
                                    </button>
                                </div>

                                <!-- Parent Product Section: Multi-Products Pills Container -->
                                <div class="bg-slate-50 dark:bg-slate-800/60 rounded-2xl p-3 border border-slate-200 dark:border-slate-700 space-y-2">
                                    <div class="flex flex-wrap items-center justify-between gap-2 text-xs">
                                        <div class="flex items-center space-x-1.5 font-black text-slate-700 dark:text-slate-300 uppercase tracking-wider text-[10px]">
                                            <span class="text-indigo-600 dark:text-indigo-400">📦</span>
                                            <span>Diterapkan Pada Produk Induk:</span>
                                            <span class="bg-indigo-100 dark:bg-indigo-950/80 text-indigo-800 dark:text-indigo-300 border border-indigo-200 dark:border-indigo-800 px-2 py-0.5 rounded-full text-[10px] font-bold">${productsList.length} Produk</span>
                                        </div>
                                        <div>
                                            ${priceBadge}
                                        </div>
                                    </div>

                                    <!-- Daftar Pill Produk Induk Terkait -->
                                    <div class="flex flex-wrap items-center gap-1.5 pt-0.5">
                                        ${productsList.map(p => `
                                            <div class="inline-flex items-center space-x-1.5 bg-white dark:bg-slate-800 px-2.5 py-1 rounded-xl border border-indigo-200 dark:border-indigo-800 shadow-2xs text-xs text-slate-800 dark:text-slate-200">
                                                <span class="w-2 h-2 rounded-full bg-emerald-500 shrink-0"></span>
                                                <span class="font-bold text-slate-800 dark:text-slate-100">${p.product_name}</span>
                                                <span class="text-[10px] font-mono text-slate-400 dark:text-slate-400 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 px-1 py-0.5 rounded">(${p.product_sku})</span>
                                                ${productsList.length > 1 ? `
                                                    <button onclick="detachProductFromVariant(${p.variant_id}, '${p.product_name.replace(/'/g, "\\'")}', '${v.variant_name.replace(/'/g, "\\'")}')" class="text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 ml-1 p-0.5 transition-colors" title="Lepas varian '${v.variant_name}' dari produk ${p.product_name}">
                                                        <i data-lucide="x" class="w-3 h-3"></i>
                                                    </button>
                                                ` : ''}
                                            </div>
                                        `).join('')}

                                        <button onclick='openApplyVariantToProductsModal(${JSON.stringify(v)})' class="inline-flex items-center space-x-1 px-2.5 py-1 rounded-xl border border-dashed border-indigo-300 dark:border-indigo-700 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-950/50 text-[11px] font-bold transition-colors">
                                            <i data-lucide="plus" class="w-3 h-3"></i>
                                            <span>+ Tambah Produk Lain</span>
                                        </button>
                                    </div>
                                </div>
                            </div>

                            <!-- Card Body (Variant Ingredients: Berlaku untuk semua produk di atas) -->
                            <div class="p-4 flex-1 space-y-2 text-xs">
                                <div class="flex items-center justify-between text-[11px] font-bold text-slate-500 dark:text-slate-400 pb-0.5">
                                    <span>🧪 Formula Bahan Tambahan (Potong Stok saat Checkout):</span>
                                    <span class="text-slate-400 font-normal">Berlaku untuk semua produk induk</span>
                                </div>
                                ${hasIngs ? `
                                    <div class="space-y-1.5">
                                        ${v.ingredients.map(ing => `
                                            <div class="flex items-center justify-between p-2.5 bg-slate-50 dark:bg-slate-800/60 rounded-xl border border-slate-100 dark:border-slate-700">
                                                <div class="min-w-0 pr-2">
                                                    <span class="font-bold text-slate-700 dark:text-slate-200 block truncate">${ing.ingredient_name}</span>
                                                    <span class="text-[10px] text-slate-400 block">${formatDecimal(ing.qty_needed)} ${ing.unit} @ ${formatRupiah(ing.ingredient_cogs)}/${ing.unit} ${ing.notes ? `• ${ing.notes}` : ''}</span>
                                                </div>
                                                <div class="flex items-center space-x-2 shrink-0">
                                                    <span class="font-mono text-slate-700 dark:text-slate-200 font-bold">${formatRupiah(ing.subtotal_ingredient_cost)}</span>
                                                    <button onclick="deleteVariantRecipeItem(${ing.id})" class="text-rose-500 dark:text-rose-400 hover:text-rose-700 dark:hover:text-rose-300 p-1" title="Hapus bahan">
                                                        <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                                                    </button>
                                                </div>
                                            </div>
                                        `).join('')}
                                    </div>
                                ` : `
                                    <div class="p-3 bg-slate-50/70 dark:bg-slate-800/40 rounded-xl border border-dashed border-slate-200 dark:border-slate-700 text-center">
                                        <p class="text-slate-500 dark:text-slate-400 text-xs font-semibold">Tidak ada bahan baku tambahan.</p>
                                        <p class="text-[10px] text-slate-400 mt-0.5">Saat varian ini dipilih (contoh: galon tanpa tutup / refill), stok bahan tutup TIDAK akan dipotong.</p>
                                    </div>
                                `}
                            </div>

                            <!-- Card Footer (Total Variant Additional BOM Cost) -->
                            <div class="p-3.5 bg-gradient-to-r from-purple-50/90 to-indigo-50/90 dark:from-purple-950/60 dark:to-indigo-950/60 border-t border-purple-100 dark:border-purple-900/50 flex justify-between items-center text-xs">
                                <span class="font-bold text-purple-900 dark:text-purple-300">Total HPP Tambahan Varian:</span>
                                <span class="font-black text-purple-900 dark:text-purple-300 text-sm font-mono">${formatRupiah(v.calculated_variant_cogs || 0)}</span>
                            </div>
                        </div>
                    `;
                }).join('');

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function onVariantIngredientChange() {
            const ingId = parseInt(document.getElementById('vr-ingredient-select').value);
            const rawList = state.variantRecipesData ? (state.variantRecipesData.raw_materials || []) : [];
            const raw = rawList.find(r => r.id === ingId);
            const unit = raw ? raw.unit : 'pcs';
            renderUnitSelectOptions('vr-unit-name', unit);
        }

        function openAddVariantRecipeModal(vId, vName, pName) {
            document.getElementById('vr-variant-id').value = vId;
            document.getElementById('vr-modal-title-desc').innerText = `Varian: ${vName} (${pName})`;

            const rawList = state.variantRecipesData ? (state.variantRecipesData.raw_materials || []) : [];
            document.getElementById('vr-ingredient-select').innerHTML = rawList.map(rm => 
                `<option value="${rm.id}">${rm.name} (${rm.sku} - Satuan: ${rm.unit})</option>`
            ).join('');

            document.getElementById('vr-qty-needed').value = '1';
            onVariantIngredientChange();
            document.getElementById('vr-notes').value = '1 pcs per penjualan varian ini';
            document.getElementById('variant-recipe-add-modal').classList.remove('hidden');
        }

        function closeVariantRecipeModal() {
            document.getElementById('variant-recipe-add-modal').classList.add('hidden');
        }

        async function saveVariantRecipeItemForm(e) {
            e.preventDefault();
            const payload = {
                variant_id: parseInt(document.getElementById('vr-variant-id').value),
                ingredient_product_id: parseInt(document.getElementById('vr-ingredient-select').value),
                qty_needed: parseFloat(document.getElementById('vr-qty-needed').value),
                unit: document.getElementById('vr-unit-name').value.trim(),
                notes: document.getElementById('vr-notes').value.trim()
            };

            const res = await fetch('api.php?action=save_variant_recipe', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeVariantRecipeModal();
                loadVariantBOMRecipes();
                initApp(); // reload bootstrap data
            }
        }

        async function deleteVariantRecipeItem(id) {
            if (!confirm('Hapus bahan baku ini dari formula varian?')) return;
            try {
                const res = await fetch('api.php?action=delete_variant_recipe', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ variant_recipe_id: id })
                });
                const data = await res.json();
                if (data.success) {
                    alert('✅ ' + (data.message || 'Bahan baku varian berhasil dihapus.'));
                    loadVariantBOMRecipes();
                    initApp();
                } else {
                    alert('⚠️ TIDAK BISA DIHAPUS:\n\n' + (data.message || data.error || 'Terjadi kesalahan saat menghapus bahan baku varian.'));
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan koneksi saat menghapus bahan baku varian.');
            }
        }

        // ==========================================
        // 7. STOK CRUD & STOCK MOVEMENT
        // ==========================================
        function switchStockSubTab(sub) {
            const btnBal = document.getElementById('subtab-btn-balance');
            const btnMov = document.getElementById('subtab-btn-movements');
            const viewBal = document.getElementById('stock-view-balance');
            const viewMov = document.getElementById('stock-view-movements');

            const activeClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-indigo-600 text-white shadow-2xs';
            const inactiveClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-slate-100 hover:bg-slate-200/80 text-slate-700 hover:text-slate-900 dark:bg-slate-800 dark:hover:bg-slate-700 dark:text-slate-300 dark:hover:text-white border border-transparent dark:border-slate-700';

            if (sub === 'balance') {
                if (btnBal) btnBal.className = activeClass;
                if (btnMov) btnMov.className = inactiveClass;
                if (viewBal) viewBal.classList.remove('hidden');
                if (viewMov) viewMov.classList.add('hidden');
                loadStockInventory();
            } else {
                if (btnMov) btnMov.className = activeClass;
                if (btnBal) btnBal.className = inactiveClass;
                if (viewMov) viewMov.classList.remove('hidden');
                if (viewBal) viewBal.classList.add('hidden');
                loadStockMovements();
            }
            lucide.createIcons();
        }

        function initStockBranchSelector() {
            const select = document.getElementById('stock-branch-select');
            if (!select) return;
            const canAccessAll = canUserAccessAllBranches();
            const userBranch = getUserAssignedBranch();

            if (!canAccessAll) {
                // Karyawan Cabang (Kasir / Staf): Kunci mutlak ke cabang lokasi bersangkutan!
                select.innerHTML = `<option value="${userBranch.id}" selected>🔒 ${userBranch.name} (Terkunci)</option>`;
                select.disabled = true;
                select.value = userBranch.id;
                select.title = "Akses inventori stok terkunci pada cabang penugasan Anda.";
            } else {
                select.disabled = false;
                select.title = "Pilih cabang untuk melihat inventori stok";
                const curVal = select.value || (state.currentBranch ? state.currentBranch.id : 'ALL');
                let html = '<option value="ALL">🌐 Semua Cabang (Konsolidasi Global)</option>';
                if (Array.isArray(state.branches)) {
                    state.branches.forEach(b => {
                        html += `<option value="${b.id}" ${b.id == curVal ? 'selected' : ''}>📍 ${b.name} (${b.code || ''})</option>`;
                    });
                }
                select.innerHTML = html;
                select.value = curVal;
            }
        }

        function onStockBranchChange() {
            loadStockInventory();
            const viewMov = document.getElementById('stock-view-movements');
            if (viewMov && !viewMov.classList.contains('hidden')) {
                loadStockMovements();
            }
        }

        async function loadStockInventory() {
            initStockBranchSelector();
            const canAccessAll = canUserAccessAllBranches();
            const userBranch = getUserAssignedBranch();
            const branchSelect = document.getElementById('stock-branch-select');
            const bId = (!canAccessAll) ? userBranch.id : (branchSelect ? branchSelect.value : 'ALL');
            const isGlobal = canAccessAll && (bId === 'ALL' || bId === '0' || bId === '');

            // Sembunyikan tombol Reset Stok jika bukan Superadmin / multi-cabang
            updateStoreResetButtonsVisibility();

            // Update Kolom Header
            const headerCol = document.getElementById('stock-col-header-balance');
            if (headerCol) {
                if (isGlobal) {
                    headerCol.innerHTML = `Stok Fisik Gabungan <span class="block text-[10px] text-indigo-600 font-semibold">(Semua Cabang)</span>`;
                } else {
                    const br = (state.branches || []).find(b => b.id == bId) || userBranch;
                    const brName = br ? br.name : `Cabang #${bId}`;
                    headerCol.innerHTML = `Stok Fisik Cabang <span class="block text-[10px] text-emerald-600 font-semibold">(${brName})</span>`;
                }
            }

            // Update Hak Akses Tombol Header Sesuai Peran Pengguna
            const curUser = state.currentUser || state.loggedInUser;
            const userRole = String((curUser ? curUser.role : '') || '').toUpperCase().replace(/[^A-Z]/g, '');
            const isManagerOrAdmin = ['SUPERADMIN', 'BRANCHMANAGER', 'MANAGER'].includes(userRole);

            const btnHeaderAdjust = document.getElementById('btn-stock-adjust-header');
            if (btnHeaderAdjust) {
                if (isManagerOrAdmin) {
                    btnHeaderAdjust.className = "px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs font-bold shadow flex items-center space-x-2 transition-colors";
                    btnHeaderAdjust.innerHTML = `<i data-lucide="arrow-left-right" class="w-4 h-4"></i><span id="btn-stock-adjust-header-text">Penyesuaian / Tambah Stok</span>`;
                    btnHeaderAdjust.title = "Penyesuaian stok awal, opname, kerusakan, atau penambahan stok";
                } else {
                    btnHeaderAdjust.className = "px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-xs font-bold shadow flex items-center space-x-2 transition-colors";
                    btnHeaderAdjust.innerHTML = `<i data-lucide="plus-circle" class="w-4 h-4"></i><span id="btn-stock-adjust-header-text">+ Tambah Stok Masuk</span>`;
                    btnHeaderAdjust.title = "Catat penambahan stok barang masuk cabang";
                }
            }

            // Update Label Tombol Reset Stok sesuai cabang yang sedang dilihat
            const btnResetLabel = document.getElementById('btn-stock-reset-label');
            if (btnResetLabel) {
                if (isGlobal) {
                    btnResetLabel.innerText = 'Reset Transaksi & Stok (Global)';
                } else {
                    const brObj = (state.branches || []).find(b => b.id == bId) || userBranch;
                    const brTitle = brObj ? brObj.name : `Cabang #${bId}`;
                    btnResetLabel.innerText = `Reset Transaksi & Stok ${brTitle}`;
                }
            }

            const res = await fetch(`api.php?action=get_inventory_stocks&branch_id=${bId}`);
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

            document.getElementById('stock-balance-table-body').innerHTML = data.stocks.map(s => {
                let stockVal = parseFloat(s.stock) || 0;
                // Produk Jadi (FINISHED_GOODS) tidak boleh bernilai minus, jika minus dinormalkan ke 0
                if (s.product_type === 'FINISHED_GOODS' && stockVal < 0) {
                    stockVal = 0;
                    s.stock = 0;
                }
                const reorderVal = parseFloat(s.reorder_point);
                const isWarning = stockVal <= reorderVal;

                // Breakdown cabang jika tampilan global
                let breakdownHtml = '';
                if (isGlobal && Array.isArray(s.branch_breakdown) && s.branch_breakdown.length > 0) {
                    breakdownHtml = `
                        <div class="flex flex-wrap gap-1 mt-1 justify-end">
                            ${s.branch_breakdown.map(bb => `
                                <span class="inline-flex items-center px-1.5 py-0.5 rounded text-[9px] bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 border border-slate-200 font-mono" title="${bb.branch_name}">
                                    <span class="font-semibold text-slate-800 dark:text-slate-200 mr-1">${bb.branch_name.replace('Cabang ', '')}:</span> ${formatDecimal(bb.stock)}
                                </span>
                            `).join('')}
                        </div>
                    `;
                }

                const actionBtnHtml = isManagerOrAdmin ? `
                    <button onclick="openStockAdjustModal(${s.product_id}, ${isGlobal ? 'null' : bId})" class="px-2.5 py-1 bg-indigo-50 dark:bg-indigo-950/70 hover:bg-indigo-100 dark:hover:bg-indigo-900/80 text-indigo-700 dark:text-indigo-300 border border-indigo-200 dark:border-indigo-800 rounded-lg text-[11px] font-bold shadow-sm transition-colors inline-flex items-center space-x-1" title="Atur / Setel Stok Awal Cabang">
                        <i data-lucide="edit-3" class="w-3.5 h-3.5"></i>
                        <span>Atur Stok</span>
                    </button>
                ` : `
                    <button onclick="openStockAdjustModal(${s.product_id}, ${isGlobal ? 'null' : bId})" class="px-2.5 py-1 bg-emerald-50 dark:bg-emerald-950/70 hover:bg-emerald-100 dark:hover:bg-emerald-900/80 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800 rounded-lg text-[11px] font-bold shadow-sm transition-colors inline-flex items-center space-x-1" title="Tambah Stok Barang Masuk Cabang">
                        <i data-lucide="plus-circle" class="w-3.5 h-3.5"></i>
                        <span>+ Tambah Stok</span>
                    </button>
                `;

                return `
                    <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                        <td class="py-2.5 px-3 font-mono font-bold text-indigo-700 dark:text-indigo-400">${s.sku}</td>
                        <td class="py-2.5 px-3 font-semibold text-slate-800 dark:text-slate-100">${s.image_emoji || ''} ${s.name}</td>
                        <td class="py-2.5 px-3"><span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold ${s.product_type === 'FINISHED_GOODS' ? 'bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800' : 'bg-amber-100 dark:bg-amber-950/80 text-amber-800 dark:text-amber-300 border border-amber-200 dark:border-amber-800'}">${s.product_type}</span></td>
                        <td class="py-2.5 px-3 text-slate-500 dark:text-slate-400 font-medium">${s.unit}</td>
                        <td class="py-2.5 px-3 text-right">
                            <span class="font-black text-sm font-mono ${isWarning ? 'text-rose-600 dark:text-rose-400' : 'text-slate-800 dark:text-slate-100'}">${formatDecimal(s.stock)}</span>
                            ${breakdownHtml}
                        </td>
                        <td class="py-2.5 px-3 text-right text-slate-500 dark:text-slate-400 font-mono">${formatDecimal(s.reorder_point)}</td>
                        <td class="py-2.5 px-3 text-right text-slate-700 dark:text-slate-300 font-mono">${formatRupiah(s.local_cogs)}</td>
                        <td class="py-2.5 px-3">
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${isWarning ? 'bg-rose-100 dark:bg-rose-950/80 text-rose-800 dark:text-rose-300 border border-rose-200 dark:border-rose-800 animate-pulse' : 'bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800'}">
                                ${isWarning ? '⚠️ Menipis' : 'Aman'}
                            </span>
                        </td>
                        <td class="py-2.5 px-3 text-center">
                            ${actionBtnHtml}
                        </td>
                    </tr>
                `;
            }).join('');
            lucide.createIcons();
        }

        async function loadStockMovements() {
            const canAccessAll = canUserAccessAllBranches();
            const userBranch = getUserAssignedBranch();
            const branchSelect = document.getElementById('stock-branch-select');
            const bId = (!canAccessAll) ? userBranch.id : (branchSelect ? branchSelect.value : 'ALL');

            const res = await fetch(`api.php?action=get_stock_movements&branch_id=${bId}`);
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

            document.getElementById('stock-movements-table-body').innerHTML = data.movements.map(m => {
                let badgeClass = 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 font-bold';
                if (m.movement_type === 'BOM_DEDUCTION') badgeClass = 'bg-purple-100 dark:bg-purple-950/80 text-purple-800 dark:text-purple-300 border border-purple-200 dark:border-purple-800 font-black';
                else if (m.movement_type === 'STOCK_OUT_SALE') badgeClass = 'bg-rose-100 dark:bg-rose-950/80 text-rose-800 dark:text-rose-300 border border-rose-200 dark:border-rose-800 font-bold';
                else if (m.movement_type === 'PURCHASE') badgeClass = 'bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800 font-bold';
                else if (m.movement_type === 'INITIAL_STOCK') badgeClass = 'bg-indigo-100 dark:bg-indigo-950/80 text-indigo-800 dark:text-indigo-300 border border-indigo-200 dark:border-indigo-800 font-black';
                else if (m.movement_type === 'ADJUSTMENT_DAMAGE') badgeClass = 'bg-rose-100 dark:bg-rose-950/80 text-rose-800 dark:text-rose-300 border border-rose-200 dark:border-rose-800 font-bold';
                else if (m.movement_type === 'ADJUSTMENT_OPNAME') badgeClass = 'bg-amber-100 dark:bg-amber-950/80 text-amber-800 dark:text-amber-300 border border-amber-200 dark:border-amber-800 font-bold';
                else if (m.movement_type === 'TRANSFER_IN') badgeClass = 'bg-teal-100 dark:bg-teal-950/80 text-teal-800 dark:text-teal-300 border border-teal-200 dark:border-teal-800 font-bold';
                else if (m.movement_type === 'TRANSFER_OUT') badgeClass = 'bg-orange-100 dark:bg-orange-950/80 text-orange-800 dark:text-orange-300 border border-orange-200 dark:border-orange-800 font-bold';

                const qtyVal = parseFloat(m.qty_change);
                return `
                    <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                        <td class="py-2.5 px-3 text-slate-500 dark:text-slate-400 whitespace-nowrap text-[11px] font-mono">${m.created_at}</td>
                        <td class="py-2.5 px-3 font-semibold text-indigo-900 text-[11px] whitespace-nowrap">
                            <span class="px-2 py-0.5 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 rounded-md border border-slate-200 dark:border-slate-700">${m.branch_name || '-'}</span>
                        </td>
                        <td class="py-2.5 px-3 font-semibold text-slate-800 dark:text-slate-100">${m.product_name} (${m.unit})</td>
                        <td class="py-2.5 px-3"><span class="px-2 py-0.5 rounded-full text-[10px] ${badgeClass}">${m.movement_type}</span></td>
                        <td class="py-2.5 px-3 text-right font-black font-mono ${qtyVal < 0 ? 'text-rose-600' : 'text-emerald-600'}">${qtyVal > 0 ? '+' : ''}${formatDecimal(m.qty_change)}</td>
                        <td class="py-2.5 px-3 text-right text-slate-400 dark:text-slate-500 font-mono">${formatDecimal(m.stock_before)}</td>
                        <td class="py-2.5 px-3 text-right text-slate-800 dark:text-slate-100 font-bold font-mono">${formatDecimal(m.stock_after)}</td>
                        <td class="py-2.5 px-3 font-mono text-[10px] text-indigo-700 dark:text-indigo-400 font-bold">${m.reference_no || '-'}</td>
                        <td class="py-2.5 px-3 text-slate-600 dark:text-slate-300 text-[11px]">${m.notes || '-'}</td>
                        <td class="py-2.5 px-3 text-slate-500 dark:text-slate-400">${m.user_name || 'Admin'}</td>
                    </tr>
                `;
            }).join('') || `<tr><td colspan="10" class="py-8 text-center text-slate-400">Belum ada riwayat pergerakan stok untuk cabang terpilih.</td></tr>`;
            lucide.createIcons();
        }

        // Variabel penampung stok saat ini untuk kalkulasi modal
        let currentModalBranchStocks = [];

        async function openStockAdjustModal(targetProductId = null, targetBranchId = null) {
            const canAccessAll = canUserAccessAllBranches();
            const userBranch = getUserAssignedBranch();
            const curUser = state.currentUser || state.loggedInUser;
            const userRole = String((curUser ? curUser.role : '') || '').toUpperCase().replace(/[^A-Z]/g, '');
            const isManagerOrAdmin = ['SUPERADMIN', 'BRANCHMANAGER', 'MANAGER'].includes(userRole);

            // 1. Populasi Dropdown Cabang
            const branchSelect = document.getElementById('adj-branch-select');
            if (branchSelect) {
                if (!canAccessAll) {
                    branchSelect.innerHTML = `<option value="${userBranch.id}" selected>🔒 ${userBranch.name} (Cabang Anda)</option>`;
                    branchSelect.disabled = true;
                    branchSelect.value = userBranch.id;
                    branchSelect.title = "Lokasi penyesuaian stok terkunci pada cabang penugasan Anda.";
                } else {
                    branchSelect.disabled = false;
                    branchSelect.innerHTML = (state.branches || []).map(b => 
                        `<option value="${b.id}">📍 ${b.name} (${b.code || ''})</option>`
                    ).join('');

                    // Tentukan cabang default
                    if (targetBranchId) {
                        branchSelect.value = targetBranchId;
                    } else {
                        const pageBranch = _val('stock-branch-select');
                        if (pageBranch && pageBranch !== 'ALL') {
                            branchSelect.value = pageBranch;
                        } else if (state.currentBranch) {
                            branchSelect.value = state.currentBranch.id;
                        }
                    }
                }
            }

            // 2. Muat produk dan set stok awal
            await loadStockAdjustProducts(targetProductId);

            // 3. Batasi Opsi Aksi Berdasarkan Peran Pengguna
            const modalTitle = document.getElementById('stock-adjust-modal-title');
            const modalSubtitle = document.getElementById('stock-adjust-modal-subtitle');
            const modalIcon = document.getElementById('stock-adjust-modal-icon');
            const adjTypeSelect = document.getElementById('adj-type');
            const submitBtn = document.getElementById('stock-adjust-submit-btn');
            const submitText = document.getElementById('stock-adjust-submit-text');
            const submitIcon = document.getElementById('stock-adjust-submit-icon');

            if (!isManagerOrAdmin) {
                // Non Superadmin & Non Branch Manager (Kasir / Staf): HANYA BISA TAMBAH STOK
                if (modalTitle) modalTitle.innerText = '+ Tambah Stok Barang Masuk';
                if (modalSubtitle) modalSubtitle.innerText = 'Pencatatan persediaan barang masuk / restock cabang. Hak akses akun Anda dibatasi khusus untuk penambahan stok barang masuk.';
                if (modalIcon) {
                    modalIcon.setAttribute('data-lucide', 'plus-circle');
                    modalIcon.className = 'w-5 h-5 text-emerald-600';
                }
                if (adjTypeSelect) {
                    Array.from(adjTypeSelect.options).forEach(opt => {
                        if (opt.value === 'PURCHASE') {
                            opt.hidden = false;
                            opt.disabled = false;
                        } else {
                            opt.hidden = true;
                            opt.disabled = true;
                        }
                    });
                    adjTypeSelect.value = 'PURCHASE';
                    adjTypeSelect.disabled = true;
                    adjTypeSelect.title = "Tingkat hak akses kasir/staf hanya diizinkan untuk menambah stok barang masuk.";
                }
                if (submitBtn) {
                    submitBtn.className = "py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold shadow transition-colors flex items-center justify-center space-x-1.5";
                }
                if (submitText) {
                    submitText.innerText = "+ Simpan Tambah Stok";
                }
                if (submitIcon) {
                    submitIcon.setAttribute('data-lucide', 'plus-circle');
                }
            } else {
                // Super Admin & Branch Manager: Full Access
                if (modalTitle) modalTitle.innerText = 'Setel Stok Awal & Mutasi Cabang';
                if (modalSubtitle) modalSubtitle.innerText = 'Pilih cabang tujuan untuk menyetel stok awal atau mencatat penyesuaian/mutasi kuantitas stok barang.';
                if (modalIcon) {
                    modalIcon.setAttribute('data-lucide', 'layers');
                    modalIcon.className = 'w-5 h-5 text-indigo-600';
                }
                if (adjTypeSelect) {
                    Array.from(adjTypeSelect.options).forEach(opt => {
                        opt.hidden = false;
                        opt.disabled = false;
                    });
                    adjTypeSelect.disabled = false;
                    adjTypeSelect.value = 'INITIAL_STOCK';
                }
                if (submitBtn) {
                    submitBtn.className = "py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold shadow transition-colors flex items-center justify-center space-x-1.5";
                }
                if (submitText) {
                    submitText.innerText = "Simpan Stok Cabang";
                }
                if (submitIcon) {
                    submitIcon.setAttribute('data-lucide', 'check-circle-2');
                }
            }

            onStockAdjustTypeChange();

            document.getElementById('stock-adjust-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        async function loadStockAdjustProducts(selectedProductId = null) {
            const bId = parseInt(_val('adj-branch-select') || (state.currentBranch ? state.currentBranch.id : 1));
            const prodSelect = document.getElementById('adj-product-select');
            if (prodSelect && prodSelect.options.length === 0) {
                prodSelect.innerHTML = '<option value="">⏳ Memuat daftar barang...</option>';
            }

            try {
                const res = await fetch(`api.php?action=get_inventory_stocks&branch_id=${bId}`);
                const data = await res.json();
                if (data.success && Array.isArray(data.stocks) && data.stocks.length > 0) {
                    currentModalBranchStocks = data.stocks;
                    prodSelect.innerHTML = currentModalBranchStocks.map(s => {
                        const icon = s.product_type === 'FINISHED_GOODS' ? '📦' : '🧪';
                        const typeLabel = s.product_type === 'FINISHED_GOODS' ? 'Barang Jadi' : 'Bahan Baku';
                        return `<option value="${s.product_id}" data-stock="${s.stock}" data-unit="${s.unit}">${icon} ${s.name} (${s.sku}) [${typeLabel}] - Stok Cabang Ini: ${s.stock} ${s.unit}</option>`;
                    }).join('');
                } else if (state.products && state.products.length > 0) {
                    // Fallback to bootstrap products if stock query is empty
                    prodSelect.innerHTML = state.products.map(p => {
                        const icon = p.product_type === 'FINISHED_GOODS' ? '📦' : '🧪';
                        const typeLabel = p.product_type === 'FINISHED_GOODS' ? 'Barang Jadi' : 'Bahan Baku';
                        return `<option value="${p.id}" data-stock="0" data-unit="${p.unit || 'pcs'}">${icon} ${p.name} (${p.sku}) [${typeLabel}] - Stok Cabang Ini: 0 ${p.unit || 'pcs'}</option>`;
                    }).join('');
                } else {
                    prodSelect.innerHTML = '<option value="">⚠️ Tidak ada data barang ditemukan</option>';
                }
            } catch (err) {
                console.error("Gagal memuat barang stok modal:", err);
                if (state.products && state.products.length > 0) {
                    prodSelect.innerHTML = state.products.map(p => {
                        const icon = p.product_type === 'FINISHED_GOODS' ? '📦' : '🧪';
                        const typeLabel = p.product_type === 'FINISHED_GOODS' ? 'Barang Jadi' : 'Bahan Baku';
                        return `<option value="${p.id}" data-stock="0" data-unit="${p.unit || 'pcs'}">${icon} ${p.name} (${p.sku}) [${typeLabel}] - Stok Cabang Ini: 0 ${p.unit || 'pcs'}</option>`;
                    }).join('');
                } else {
                    prodSelect.innerHTML = '<option value="">⚠️ Gagal memuat barang</option>';
                }
            }

            if (selectedProductId) {
                prodSelect.value = selectedProductId;
            }
            onStockAdjustProductChange();
        }

        async function onStockAdjustBranchChange() {
            const curPId = parseInt(_val('adj-product-select') || 0);
            await loadStockAdjustProducts(curPId);
        }

        function onStockAdjustProductChange() {
            const prodSelect = document.getElementById('adj-product-select');
            const selectedOpt = prodSelect ? prodSelect.options[prodSelect.selectedIndex] : null;
            const curStock = selectedOpt ? parseFloat(selectedOpt.getAttribute('data-stock') || 0) : 0;
            const curUnit = selectedOpt ? (selectedOpt.getAttribute('data-unit') || 'pcs') : 'pcs';

            const badge = document.getElementById('adj-current-stock-badge');
            if (badge) badge.innerText = `${formatDecimal(curStock)} ${curUnit}`;

            updateStockAdjustPreview();
        }

        function onStockAdjustTypeChange() {
            const adjType = document.getElementById('adj-type').value;
            const labelEl = document.getElementById('adj-qty-label');
            const inputEl = document.getElementById('adj-qty');
            const notesEl = document.getElementById('adj-notes');

            if (adjType === 'INITIAL_STOCK') {
                labelEl.innerText = 'Nilai Stok Baru (Stok Awal Cabang):';
                inputEl.placeholder = 'Contoh: 100 (Stok akan disetel persis ke nilai ini)';
                if (!notesEl.value || notesEl.value.includes('Penerimaan') || notesEl.value.includes('Opname')) {
                    notesEl.value = 'Setel stok awal cabang';
                }
            } else if (adjType === 'PURCHASE') {
                labelEl.innerText = 'Jumlah Tambahan Stok Masuk (+):';
                inputEl.placeholder = 'Contoh: 50 (Menambah stok)';
                notesEl.value = 'Barang masuk pembelian / restock';
            } else if (adjType === 'ADJUSTMENT_DAMAGE') {
                labelEl.innerText = 'Jumlah Stok Berkurang / Rusak (-):';
                inputEl.placeholder = 'Contoh: 5 (Mengurangi stok)';
                notesEl.value = 'Barang rusak / bocor / kadaluwarsa';
            } else {
                labelEl.innerText = 'Selisih Kuantitas Opname (+ / -):';
                inputEl.placeholder = 'Contoh: 10 atau -3';
                notesEl.value = 'Koreksi penyesuaian stock opname fisik';
            }
            updateStockAdjustPreview();
        }

        function updateStockAdjustPreview() {
            const prodSelect = document.getElementById('adj-product-select');
            const selectedOpt = prodSelect ? prodSelect.options[prodSelect.selectedIndex] : null;
            const curStock = selectedOpt ? parseFloat(selectedOpt.getAttribute('data-stock') || 0) : 0;
            const curUnit = selectedOpt ? (selectedOpt.getAttribute('data-unit') || '') : '';

            const adjType = document.getElementById('adj-type').value;
            const inputVal = parseFloat(document.getElementById('adj-qty').value) || 0;
            const previewEl = document.getElementById('adj-preview-calc');
            if (!previewEl) return;

            let newStock = curStock;
            let diff = 0;

            if (adjType === 'INITIAL_STOCK') {
                newStock = inputVal;
                diff = newStock - curStock;
            } else if (adjType === 'ADJUSTMENT_DAMAGE') {
                diff = -Math.abs(inputVal);
                newStock = curStock + diff;
            } else {
                diff = inputVal;
                newStock = curStock + diff;
            }

            const diffText = diff >= 0 ? `+${formatDecimal(diff)}` : `${formatDecimal(diff)}`;
            const warnText = newStock < 0 ? '<span class="text-rose-600 font-bold ml-2">⚠️ Stok minus tidak diizinkan!</span>' : '';
            previewEl.innerHTML = `Perhitungan: Stok saat ini <b>${formatDecimal(curStock)} ${curUnit}</b> → Stok baru <b>${formatDecimal(newStock)} ${curUnit}</b> (Perubahan: <b>${diffText}</b>)${warnText}`;
        }

        function closeStockAdjustModal() {
            document.getElementById('stock-adjust-modal').classList.add('hidden');
        }

        async function saveStockAdjustForm(e) {
            e.preventDefault();
            const curUser = state.currentUser || state.loggedInUser;
            const userRole = String((curUser ? curUser.role : '') || '').toUpperCase().replace(/[^A-Z]/g, '');
            const isManagerOrAdmin = ['SUPERADMIN', 'BRANCHMANAGER', 'MANAGER'].includes(userRole);

            const branchId = parseInt(document.getElementById('adj-branch-select').value);
            const pId = parseInt(document.getElementById('adj-product-select').value);
            const adjTypeSelect = document.getElementById('adj-type');
            const adjType = (!isManagerOrAdmin) ? 'PURCHASE' : (adjTypeSelect ? adjTypeSelect.value : 'INITIAL_STOCK');
            const inputVal = parseFloat(document.getElementById('adj-qty').value);
            const notes = document.getElementById('adj-notes').value.trim();

            if (isNaN(inputVal)) {
                alert('Silakan masukkan angka kuantitas yang valid.');
                return;
            }

            if (!isManagerOrAdmin) {
                if (adjType !== 'PURCHASE') {
                    alert('Akses Ditolak: Staf / Kasir hanya berwenang melakukan aksi Tambah Stok Barang Masuk.');
                    return;
                }
                if (inputVal <= 0) {
                    alert('Kuantitas penambahan stok harus lebih besar dari 0.');
                    return;
                }
            }

            let payload = {
                branch_id: branchId,
                product_id: pId,
                adjustment_type: adjType,
                notes: notes,
                user_id: curUser ? curUser.id : 1
            };

            if (adjType === 'INITIAL_STOCK') {
                payload.exact_stock = inputVal;
            } else if (adjType === 'ADJUSTMENT_DAMAGE') {
                payload.qty_change = -Math.abs(inputVal);
            } else {
                payload.qty_change = inputVal;
            }

            const res = await fetch('api.php?action=adjust_stock', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeStockAdjustModal();
                loadStockInventory();
                loadStockMovements();
            }
        }

        // ==========================================
        // 7B. MODUL INPUT PENAMBAHAN STOK (MANUAL & TRANSFER CABANG)
        // ==========================================
        const stockInState = {
            activeSubTab: 'manual',
            canAccessAll: false,
            allowedBranchIds: [],
            permissions: {
                manual_view: true,
                manual_create: true,
                transfer_view: true,
                transfer_create: true,
                transfer_delete: false
            },
            branches: [],
            products: [],
            branchStocksMap: {},
            manualHistory: [],
            transfers: [],
            manualRows: [],
            transferRows: [],
            nextRowSeq: 1,
            transferStatusFilter: 'ALL',
            initialized: false
        };

        function isStockInRawMaterial(pType) {
            return String(pType || '').toUpperCase().indexOf('RAW') !== -1;
        }

        function getStockInBranchBalance(branchId, productId) {
            const bKey = String(parseInt(branchId, 10) || 0);
            const pKey = String(parseInt(productId, 10) || 0);
            const mapObj = stockInState.branchStocksMap || {};
            const bMap = mapObj[bKey] || mapObj[parseInt(branchId, 10)] || null;
            if (!bMap) return 0;
            const rawVal = bMap[pKey] !== undefined ? bMap[pKey] : bMap[parseInt(productId, 10)];
            const parsed = parseFloat(rawVal);
            return isNaN(parsed) ? 0 : parsed;
        }

        function getStockInProductById(productId) {
            const pid = parseInt(productId, 10) || 0;
            const list = stockInState.products || [];
            for (let i = 0; i < list.length; i++) {
                if (parseInt(list[i].id, 10) === pid) return list[i];
            }
            return null;
        }

        function buildStockInProductOptionsHtml(selectedProductId, typeFilter, stockRefBranchId) {
            const selId = parseInt(selectedProductId, 10) || 0;
            const filterMode = String(typeFilter || 'ALL').toUpperCase();
            const refBranch = parseInt(stockRefBranchId, 10) || 0;
            let html = '<option value="0">-- Pilih Produk / Bahan Baku --</option>';
            const list = stockInState.products || [];

            for (let i = 0; i < list.length; i++) {
                const p = list[i];
                const isRaw = isStockInRawMaterial(p.product_type);
                if (filterMode === 'FINISHED_GOOD' && isRaw) continue;
                if (filterMode === 'RAW_MATERIAL' && !isRaw) continue;

                const pId = parseInt(p.id, 10);
                const icon = isRaw ? '🧪' : '📦';
                const skuLabel = p.sku ? (' (' + escapeHtml(p.sku) + ')') : '';
                const unitLabel = escapeHtml(p.unit || 'pcs');
                let stockSuffix = '';
                if (refBranch > 0) {
                    const curBal = getStockInBranchBalance(refBranch, pId);
                    stockSuffix = ' — Stok: ' + formatDecimal(curBal) + ' ' + unitLabel;
                }
                const selAttr = (pId === selId) ? ' selected' : '';
                html += '<option value="' + pId + '"' + selAttr + '>' + icon + ' ' + escapeHtml(p.name) + skuLabel + stockSuffix + '</option>';
            }
            return html;
        }

        function switchStockInSubTab(subtab) {
            const canManual = hasUserPerm('stock-in:manual', 'view') && (stockInState.permissions.manual_view !== false);
            const canTransfer = hasUserPerm('stock-in:transfer', 'view') && (stockInState.permissions.transfer_view !== false);

            let target = (subtab === 'transfer') ? 'transfer' : 'manual';
            if (target === 'manual' && !canManual && canTransfer) {
                target = 'transfer';
            } else if (target === 'transfer' && !canTransfer && canManual) {
                target = 'manual';
            }
            stockInState.activeSubTab = target;

            const btnManual = document.getElementById('stockin-subtab-btn-manual');
            const btnTransfer = document.getElementById('stockin-subtab-btn-transfer');
            const viewManual = document.getElementById('stockin-view-manual');
            const viewTransfer = document.getElementById('stockin-view-transfer');

            const activeManualCls = 'px-3.5 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-2 bg-emerald-600 text-white shadow-2xs';
            const activeTransferCls = 'px-3.5 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-2 bg-indigo-600 text-white shadow-2xs';
            const inactiveCls = 'px-3.5 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-2 bg-slate-100 hover:bg-slate-200/80 text-slate-700 hover:text-slate-900 dark:bg-slate-800 dark:hover:bg-slate-700 dark:text-slate-300 dark:hover:text-white border border-transparent dark:border-slate-700';

            if (btnManual) {
                btnManual.className = (target === 'manual') ? activeManualCls : inactiveCls;
                if (!canManual) {
                    btnManual.classList.add('hidden');
                    btnManual.style.display = 'none';
                } else {
                    btnManual.classList.remove('hidden');
                    btnManual.style.display = '';
                }
            }
            if (btnTransfer) {
                btnTransfer.className = (target === 'transfer') ? activeTransferCls : inactiveCls;
                if (!canTransfer) {
                    btnTransfer.classList.add('hidden');
                    btnTransfer.style.display = 'none';
                } else {
                    btnTransfer.classList.remove('hidden');
                    btnTransfer.style.display = '';
                }
            }

            if (viewManual) {
                if (target === 'manual' && canManual) viewManual.classList.remove('hidden');
                else viewManual.classList.add('hidden');
            }
            if (viewTransfer) {
                if (target === 'transfer' && canTransfer) viewTransfer.classList.remove('hidden');
                else viewTransfer.classList.add('hidden');
            }

            lucide.createIcons();
        }

        async function loadStockInModule() {
            const filterSel = document.getElementById('stockin-filter-branch');
            const prevFilterVal = (stockInState.initialized && filterSel && filterSel.value) ? filterSel.value : 'ALL';
            const prevManualBranch = _val('stockin-manual-branch');
            const prevTrfFrom = _val('stockin-trf-from-branch');
            const prevTrfTo = _val('stockin-trf-to-branch');

            syncStockInManualRowsFromDOM();
            syncStockTransferRowsFromDOM();

            try {
                const res = await fetch('api.php?action=get_stock_in_data&filter_branch_id=' + encodeURIComponent(prevFilterVal));
                const data = await res.json();
                if (!data.success) {
                    showToast(data.message || 'Gagal memuat modul Input Penambahan Stok.', 'error');
                    return;
                }

                stockInState.canAccessAll = !!data.can_access_all_branches;
                stockInState.allowedBranchIds = Array.isArray(data.allowed_branch_ids)
                    ? data.allowed_branch_ids.map(function(x) { return parseInt(x, 10); })
                    : [];
                stockInState.permissions = data.permissions || {
                    manual_view: true,
                    manual_create: true,
                    transfer_view: true,
                    transfer_create: true,
                    transfer_delete: false
                };
                stockInState.branches = Array.isArray(data.branches) ? data.branches : [];
                stockInState.products = Array.isArray(data.products) ? data.products : [];
                stockInState.branchStocksMap = data.branch_stocks_map || {};
                stockInState.manualHistory = Array.isArray(data.manual_history) ? data.manual_history : [];
                stockInState.transfers = Array.isArray(data.transfers) ? data.transfers : [];

                const allBranches = stockInState.branches;
                const allowedBranches = stockInState.canAccessAll
                    ? allBranches
                    : allBranches.filter(function(b) {
                        return stockInState.allowedBranchIds.indexOf(parseInt(b.id, 10)) !== -1;
                    });
                const effectiveAllowed = allowedBranches.length > 0 ? allowedBranches : allBranches;
                const defaultOwnBranchId = state.currentBranch ? parseInt(state.currentBranch.id, 10) : (effectiveAllowed[0] ? parseInt(effectiveAllowed[0].id, 10) : 1);

                // 1. Dropdown Filter Riwayat Header
                if (filterSel) {
                    if (stockInState.canAccessAll) {
                        let fHtml = '<option value="ALL">🌐 Semua Cabang</option>';
                        allBranches.forEach(function(b) {
                            fHtml += '<option value="' + b.id + '">🏢 ' + escapeHtml(b.name) + '</option>';
                        });
                        filterSel.innerHTML = fHtml;
                        filterSel.disabled = false;
                        filterSel.value = prevFilterVal || 'ALL';
                        if (!filterSel.value) filterSel.value = 'ALL';
                    } else if (effectiveAllowed.length > 1) {
                        let fHtml = '';
                        effectiveAllowed.forEach(function(b) {
                            fHtml += '<option value="' + b.id + '">🏢 ' + escapeHtml(b.name) + '</option>';
                        });
                        filterSel.innerHTML = fHtml;
                        filterSel.disabled = false;
                        if (prevFilterVal && prevFilterVal !== 'ALL') filterSel.value = prevFilterVal;
                    } else if (effectiveAllowed[0]) {
                        filterSel.innerHTML = '<option value="' + effectiveAllowed[0].id + '">🔒 ' + escapeHtml(effectiveAllowed[0].name) + '</option>';
                        filterSel.disabled = true;
                        filterSel.value = String(effectiveAllowed[0].id);
                    }
                }

                // 2. Dropdown Cabang Tujuan Penambahan Manual
                const manualBrSel = document.getElementById('stockin-manual-branch');
                if (manualBrSel) {
                    manualBrSel.innerHTML = effectiveAllowed.map(function(b) {
                        const lockIcon = (!stockInState.canAccessAll && effectiveAllowed.length === 1) ? '🔒 ' : '📍 ';
                        return '<option value="' + b.id + '">' + lockIcon + escapeHtml(b.name) + (b.code ? ' (' + escapeHtml(b.code) + ')' : '') + '</option>';
                    }).join('');
                    manualBrSel.disabled = (!stockInState.canAccessAll && effectiveAllowed.length <= 1);
                    if (prevManualBranch && effectiveAllowed.some(function(b) { return String(b.id) === String(prevManualBranch); })) {
                        manualBrSel.value = String(prevManualBranch);
                    } else if (effectiveAllowed.some(function(b) { return parseInt(b.id, 10) === defaultOwnBranchId; })) {
                        manualBrSel.value = String(defaultOwnBranchId);
                    }
                }

                // 3. Dropdown Cabang Asal & Cabang Tujuan Transfer
                const trfFromSel = document.getElementById('stockin-trf-from-branch');
                const trfToSel = document.getElementById('stockin-trf-to-branch');
                if (trfFromSel) {
                    trfFromSel.innerHTML = allBranches.map(function(b) {
                        return '<option value="' + b.id + '">📤 ' + escapeHtml(b.name) + (b.code ? ' (' + escapeHtml(b.code) + ')' : '') + '</option>';
                    }).join('');
                    trfFromSel.disabled = false;
                    if (prevTrfFrom && allBranches.some(function(b) { return String(b.id) === String(prevTrfFrom); })) {
                        trfFromSel.value = String(prevTrfFrom);
                    } else if (allBranches.some(function(b) { return parseInt(b.id, 10) === defaultOwnBranchId; })) {
                        trfFromSel.value = String(defaultOwnBranchId);
                    } else if (allBranches[0]) {
                        trfFromSel.value = String(allBranches[0].id);
                    }
                }
                if (trfToSel) {
                    const curFromId = trfFromSel ? parseInt(trfFromSel.value, 10) : 0;
                    trfToSel.innerHTML = allBranches.map(function(b) {
                        return '<option value="' + b.id + '">📥 ' + escapeHtml(b.name) + (b.code ? ' (' + escapeHtml(b.code) + ')' : '') + '</option>';
                    }).join('');
                    if (prevTrfTo && parseInt(prevTrfTo, 10) !== curFromId && allBranches.some(function(b) { return String(b.id) === String(prevTrfTo); })) {
                        trfToSel.value = String(prevTrfTo);
                    } else {
                        const otherBranch = allBranches.find(function(b) { return parseInt(b.id, 10) !== curFromId; });
                        if (otherBranch) trfToSel.value = String(otherBranch.id);
                    }
                }

                // 4. Visibilitas Kartu Form Berdasarkan Izin Create Role
                const manualFormCard = document.getElementById('stockin-manual-form-card');
                if (manualFormCard) {
                    const allowManualCreate = hasUserPerm('stock-in:manual', 'create') && (stockInState.permissions.manual_create !== false);
                    if (allowManualCreate) manualFormCard.classList.remove('hidden');
                    else manualFormCard.classList.add('hidden');
                }
                const trfFormCard = document.getElementById('stockin-transfer-form-card');
                if (trfFormCard) {
                    const allowTrfCreate = hasUserPerm('stock-in:transfer', 'create') && (stockInState.permissions.transfer_create !== false);
                    if (allowTrfCreate) trfFormCard.classList.remove('hidden');
                    else trfFormCard.classList.add('hidden');
                }

                // 5. Badge Kiriman In-Transit
                const pendingCount = stockInState.transfers.filter(function(t) {
                    return t.status === 'IN_TRANSIT';
                }).length;
                const pendingBadge = document.getElementById('stockin-pending-badge');
                if (pendingBadge) {
                    if (pendingCount > 0) {
                        pendingBadge.innerText = String(pendingCount);
                        pendingBadge.classList.remove('hidden');
                    } else {
                        pendingBadge.classList.add('hidden');
                    }
                }

                // 6. Baris Input Awal & Render Tabel
                if (stockInState.manualRows.length === 0) {
                    stockInState.manualRows.push({ rowId: stockInState.nextRowSeq++, productId: 0, qty: '', notes: '' });
                }
                if (stockInState.transferRows.length === 0) {
                    stockInState.transferRows.push({ rowId: stockInState.nextRowSeq++, productId: 0, qty: '', notes: '' });
                }

                stockInState.initialized = true;
                renderStockInManualRows();
                renderStockInManualHistory();
                renderIncomingTransfersBanner();
                renderStockTransferRows();
                renderStockTransferHistory();
                switchStockInSubTab(stockInState.activeSubTab);
            } catch (err) {
                console.error('loadStockInModule error:', err);
                showToast('Gagal menghubungi server saat memuat data penambahan stok.', 'error');
            }
        }

        // ---------- 1. PENAMBAHAN MANUAL ----------
        function syncStockInManualRowsFromDOM() {
            stockInState.manualRows.forEach(function(r) {
                const pEl = document.getElementById('stockin-man-prod-' + r.rowId);
                const qEl = document.getElementById('stockin-man-qty-' + r.rowId);
                const nEl = document.getElementById('stockin-man-note-' + r.rowId);
                if (pEl) r.productId = parseInt(pEl.value, 10) || 0;
                if (qEl) r.qty = qEl.value;
                if (nEl) r.notes = nEl.value;
            });
        }

        function renderStockInManualRows() {
            const tbody = document.getElementById('stockin-manual-rows-body');
            if (!tbody) return;
            const branchId = parseInt(_val('stockin-manual-branch'), 10) || 0;
            const typeFilter = _val('stockin-manual-type-filter') || 'ALL';

            tbody.innerHTML = stockInState.manualRows.map(function(r, idx) {
                const prodObj = getStockInProductById(r.productId);
                const unitText = prodObj ? (prodObj.unit || 'pcs') : '-';
                const curStock = (r.productId > 0 && branchId > 0) ? getStockInBranchBalance(branchId, r.productId) : 0;
                const qtyNum = parseFloat(r.qty) || 0;
                const estAfter = curStock + (qtyNum > 0 ? qtyNum : 0);
                const optsHtml = buildStockInProductOptionsHtml(r.productId, typeFilter, branchId);
                const disableDel = stockInState.manualRows.length <= 1;

                return '<tr class="hover:bg-slate-50/70 dark:hover:bg-slate-800/50 transition-colors">' +
                    '<td class="py-2.5 px-3 text-center font-mono text-slate-400 font-bold">' + (idx + 1) + '</td>' +
                    '<td class="py-2.5 px-3">' +
                        '<select id="stockin-man-prod-' + r.rowId + '" onchange="onManualRowProductChange(' + r.rowId + ')" class="w-full p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-semibold text-slate-800 dark:text-slate-100 focus:ring-2 focus:ring-emerald-500 focus:outline-none">' +
                            optsHtml +
                        '</select>' +
                    '</td>' +
                    '<td class="py-2.5 px-3 text-right font-mono font-bold text-slate-600 dark:text-slate-300" id="stockin-man-cur-' + r.rowId + '">' +
                        (r.productId > 0 ? (formatDecimal(curStock) + ' <span class="text-[10px] text-slate-400">' + escapeHtml(unitText) + '</span>') : '-') +
                    '</td>' +
                    '<td class="py-2.5 px-3">' +
                        '<input type="number" step="any" min="0" id="stockin-man-qty-' + r.rowId + '" value="' + escapeHtml(r.qty) + '" oninput="onManualRowQtyInput(' + r.rowId + ')" placeholder="0" class="w-full p-2 text-center bg-emerald-50/60 dark:bg-emerald-950/40 border border-emerald-200 dark:border-emerald-700/80 rounded-xl font-mono font-black text-emerald-800 dark:text-emerald-300 focus:ring-2 focus:ring-emerald-500 focus:outline-none">' +
                    '</td>' +
                    '<td class="py-2.5 px-3 text-right font-mono font-black text-emerald-700 dark:text-emerald-400" id="stockin-man-after-' + r.rowId + '">' +
                        (r.productId > 0 ? (formatDecimal(estAfter) + ' <span class="text-[10px] text-slate-400">' + escapeHtml(unitText) + '</span>') : '-') +
                    '</td>' +
                    '<td class="py-2.5 px-3">' +
                        '<input type="text" id="stockin-man-note-' + r.rowId + '" value="' + escapeHtml(r.notes) + '" placeholder="Keterangan baris (opsional)" class="w-full p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs text-slate-700 dark:text-slate-300 focus:ring-2 focus:ring-emerald-500 focus:outline-none">' +
                    '</td>' +
                    '<td class="py-2.5 px-3 text-center">' +
                        '<button type="button" onclick="removeStockInManualRow(' + r.rowId + ')" ' + (disableDel ? 'disabled' : '') + ' class="p-1.5 rounded-lg ' + (disableDel ? 'text-slate-300 dark:text-slate-600 cursor-not-allowed' : 'text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-950/40') + '" title="Hapus Baris">' +
                            '<i data-lucide="trash-2" class="w-4 h-4"></i>' +
                        '</button>' +
                    '</td>' +
                '</tr>';
            }).join('');
            lucide.createIcons();
        }

        function addStockInManualRow() {
            syncStockInManualRowsFromDOM();
            stockInState.manualRows.push({ rowId: stockInState.nextRowSeq++, productId: 0, qty: '', notes: '' });
            renderStockInManualRows();
        }

        function removeStockInManualRow(rowId) {
            syncStockInManualRowsFromDOM();
            if (stockInState.manualRows.length <= 1) return;
            stockInState.manualRows = stockInState.manualRows.filter(function(r) { return r.rowId !== rowId; });
            renderStockInManualRows();
        }

        function resetStockInManualForm() {
            stockInState.manualRows = [{ rowId: stockInState.nextRowSeq++, productId: 0, qty: '', notes: '' }];
            const refEl = document.getElementById('stockin-manual-ref');
            const notesEl = document.getElementById('stockin-manual-notes');
            if (refEl) refEl.value = '';
            if (notesEl) notesEl.value = '';
            renderStockInManualRows();
        }

        function onStockInManualTypeFilterChange() {
            syncStockInManualRowsFromDOM();
            renderStockInManualRows();
        }

        function refreshStockInManualBalances() {
            syncStockInManualRowsFromDOM();
            renderStockInManualRows();
        }

        function onManualRowProductChange(rowId) {
            syncStockInManualRowsFromDOM();
            onManualRowQtyInput(rowId);
        }

        function onManualRowQtyInput(rowId) {
            const pEl = document.getElementById('stockin-man-prod-' + rowId);
            const qEl = document.getElementById('stockin-man-qty-' + rowId);
            const curCell = document.getElementById('stockin-man-cur-' + rowId);
            const afterCell = document.getElementById('stockin-man-after-' + rowId);
            const branchId = parseInt(_val('stockin-manual-branch'), 10) || 0;
            const pId = pEl ? (parseInt(pEl.value, 10) || 0) : 0;
            const qtyVal = qEl ? (parseFloat(qEl.value) || 0) : 0;

            const rowObj = stockInState.manualRows.find(function(r) { return r.rowId === rowId; });
            if (rowObj) {
                rowObj.productId = pId;
                rowObj.qty = qEl ? qEl.value : '';
            }

            if (pId <= 0) {
                if (curCell) curCell.innerHTML = '-';
                if (afterCell) afterCell.innerHTML = '-';
                return;
            }
            const prodObj = getStockInProductById(pId);
            const unitText = prodObj ? (prodObj.unit || 'pcs') : 'pcs';
            const curStock = getStockInBranchBalance(branchId, pId);
            const estAfter = curStock + (qtyVal > 0 ? qtyVal : 0);
            if (curCell) curCell.innerHTML = formatDecimal(curStock) + ' <span class="text-[10px] text-slate-400">' + escapeHtml(unitText) + '</span>';
            if (afterCell) afterCell.innerHTML = formatDecimal(estAfter) + ' <span class="text-[10px] text-slate-400">' + escapeHtml(unitText) + '</span>';
        }

        async function submitManualStockInForm() {
            syncStockInManualRowsFromDOM();
            const targetBranchId = parseInt(_val('stockin-manual-branch'), 10) || 0;
            const refNo = (_val('stockin-manual-ref') || '').trim();
            const generalNotes = (_val('stockin-manual-notes') || '').trim();

            if (targetBranchId <= 0) {
                alert('Pilih cabang tujuan penambahan stok terlebih dahulu.');
                return;
            }

            const validItems = [];
            for (let i = 0; i < stockInState.manualRows.length; i++) {
                const r = stockInState.manualRows[i];
                const pId = parseInt(r.productId, 10) || 0;
                const qty = parseFloat(r.qty) || 0;
                if (pId > 0 && qty > 0) {
                    validItems.push({
                        product_id: pId,
                        qty: qty,
                        notes: (r.notes || '').trim()
                    });
                } else if (pId > 0 && qty <= 0) {
                    const pObj = getStockInProductById(pId);
                    alert('Masukkan jumlah tambah (+) lebih dari 0 untuk produk "' + (pObj ? pObj.name : ('#' + pId)) + '".');
                    return;
                }
            }

            if (validItems.length === 0) {
                alert('Pilih minimal 1 produk/bahan baku dan isi jumlah penambahan stok lebih dari 0.');
                return;
            }

            const btn = document.getElementById('btn-submit-manual-stockin');
            if (btn) btn.disabled = true;
            try {
                const res = await fetch('api.php?action=submit_manual_stock_in', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        target_branch_id: targetBranchId,
                        reference_no: refNo,
                        general_notes: generalNotes,
                        items: validItems
                    })
                });
                const data = await res.json();
                if (data.success) {
                    showToast(data.message || 'Penambahan stok manual berhasil disimpan!', 'success');
                    resetStockInManualForm();
                    await loadStockInModule();
                    if (typeof loadStockInventory === 'function') loadStockInventory();
                } else {
                    alert(data.message || 'Gagal menyimpan penambahan stok manual.');
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi gangguan koneksi saat menyimpan penambahan stok.');
            } finally {
                if (btn) btn.disabled = false;
            }
        }

        function renderStockInManualHistory() {
            const tbody = document.getElementById('stockin-manual-history-body');
            if (!tbody) return;
            const list = stockInState.manualHistory || [];
            if (list.length === 0) {
                tbody.innerHTML = '<tr><td colspan="9" class="py-8 text-center text-slate-400">Belum ada riwayat penambahan stok masuk manual pada filter cabang terpilih.</td></tr>';
                return;
            }

            tbody.innerHTML = list.map(function(m) {
                const isRaw = isStockInRawMaterial(m.product_type);
                const icon = isRaw ? '🧪' : '📦';
                return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">' +
                    '<td class="py-2.5 px-3 font-mono text-[11px] text-slate-500 whitespace-nowrap">' + escapeHtml(m.created_at || '-') + '</td>' +
                    '<td class="py-2.5 px-3 whitespace-nowrap"><span class="px-2 py-0.5 bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md font-bold text-[11px] text-slate-700 dark:text-slate-300">'  + escapeHtml(m.branch_name || '-') + '</span></td>' +
                    '<td class="py-2.5 px-3 font-bold text-slate-800 dark:text-slate-100">' + icon + ' ' + escapeHtml(m.product_name || '-') + ' <span class="text-[10px] font-mono text-slate-400">(' + escapeHtml(m.product_sku || '') + ')</span></td>' +
                    '<td class="py-2.5 px-3 text-right font-mono font-black text-emerald-600 dark:text-emerald-400">+' + formatDecimal(m.qty_change) + ' <span class="text-[10px] font-normal text-slate-400">' + escapeHtml(m.unit || '') + '</span></td>' +
                    '<td class="py-2.5 px-3 text-right font-mono text-slate-400">' + formatDecimal(m.stock_before) + '</td>' +
                    '<td class="py-2.5 px-3 text-right font-mono font-bold text-slate-800 dark:text-slate-100">' + formatDecimal(m.stock_after) + '</td>' +
                    '<td class="py-2.5 px-3 font-mono text-[11px] font-bold text-emerald-700 dark:text-emerald-400">' + escapeHtml(m.reference_no || '-') + '</td>' +
                    '<td class="py-2.5 px-3 text-slate-600 dark:text-slate-300 text-[11px]">' + escapeHtml(m.notes || '-') + '</td>' +
                    '<td class="py-2.5 px-3 text-slate-500 dark:text-slate-400 text-[11px]">' + escapeHtml(m.user_name || 'Admin') + '</td>' +
                '</tr>';
            }).join('');
        }

        // ---------- 2. TRANSFER CABANG ----------
        function syncStockTransferRowsFromDOM() {
            stockInState.transferRows.forEach(function(r) {
                const pEl = document.getElementById('stockin-trf-prod-' + r.rowId);
                const qEl = document.getElementById('stockin-trf-qty-' + r.rowId);
                const nEl = document.getElementById('stockin-trf-note-' + r.rowId);
                if (pEl) r.productId = parseInt(pEl.value, 10) || 0;
                if (qEl) r.qty = qEl.value;
                if (nEl) r.notes = nEl.value;
            });
        }

        function onStockTransferBranchChange(which) {
            syncStockTransferRowsFromDOM();
            var fromSel = document.getElementById('stockin-trf-from-branch');
            var toSel = document.getElementById('stockin-trf-to-branch');
            var allBr = stockInState.branches || [];
            if (fromSel && toSel && fromSel.value === toSel.value && allBr.length > 1) {
                if (which === 'from') {
                    var altTo = allBr.find(function(b) { return String(b.id) !== String(fromSel.value); });
                    if (altTo) toSel.value = String(altTo.id);
                } else {
                    var altFrom = allBr.find(function(b) { return String(b.id) !== String(toSel.value); });
                    if (altFrom) fromSel.value = String(altFrom.id);
                }
            }
            renderStockTransferRows();
        }

        function renderStockTransferRows() {
            var tbody = document.getElementById('stockin-trf-rows-body');
            if (!tbody) return;
            var fromBranchId = parseInt(_val('stockin-trf-from-branch'), 10) || 0;
            var toBranchId = parseInt(_val('stockin-trf-to-branch'), 10) || 0;
            var allBr = stockInState.branches || [];

            // update label nama cabang di header kolom
            var fromLabelEl = document.getElementById('stockin-trf-from-label');
            var toLabelEl = document.getElementById('stockin-trf-to-label');
            if (fromLabelEl) {
                var fromBrObj = allBr.find(function(b) { return parseInt(b.id, 10) === fromBranchId; });
                fromLabelEl.textContent = fromBrObj ? escapeHtml(fromBrObj.name) : '';
            }
            if (toLabelEl) {
                var toBrObj = allBr.find(function(b) { return parseInt(b.id, 10) === toBranchId; });
                toLabelEl.textContent = toBrObj ? escapeHtml(toBrObj.name) : '';
            }

            tbody.innerHTML = stockInState.transferRows.map(function(r, idx) {
                var prodObj = getStockInProductById(r.productId);
                var unitText = prodObj ? (prodObj.unit || 'pcs') : '-';
                var fromStock = (r.productId > 0 && fromBranchId > 0) ? getStockInBranchBalance(fromBranchId, r.productId) : 0;
                var toStock = (r.productId > 0 && toBranchId > 0) ? getStockInBranchBalance(toBranchId, r.productId) : 0;
                var qtyNum = parseFloat(r.qty) || 0;
                var isInsufficient = (r.productId > 0 && qtyNum > fromStock);
                var optsHtml = buildStockInProductOptionsHtml(r.productId, 'ALL', fromBranchId);
                var disableDel = stockInState.transferRows.length <= 1;

                return '<tr class="hover:bg-slate-50/70 dark:hover:bg-slate-800/50 transition-colors">' +
                    '<td class="py-2.5 px-3 text-center font-mono text-slate-400 font-bold">' + (idx + 1) + '</td>' +
                    '<td class="py-2.5 px-3">' +
                        '<select id="stockin-trf-prod-' + r.rowId + '" onchange="onTransferRowProductChange(' + r.rowId + ')" class="w-full p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-semibold text-slate-800 dark:text-slate-100 focus:ring-2 focus:ring-indigo-500 focus:outline-none">' +
                            optsHtml +
                        '</select>' +
                    '</td>' +
                    '<td class="py-2.5 px-3 text-right font-mono font-bold ' + (isInsufficient ? 'text-rose-600 dark:text-rose-400' : 'text-slate-700 dark:text-slate-300') + '" id="stockin-trf-frombal-' + r.rowId + '">' +
                        (r.productId > 0 ? (formatDecimal(fromStock) + ' <span class="text-[10px] text-slate-400">' + escapeHtml(unitText) + '</span>') : '-') +
                    '</td>' +
                    '<td class="py-2.5 px-3 text-right font-mono font-semibold text-indigo-700 dark:text-indigo-400" id="stockin-trf-tobal-' + r.rowId + '">' +
                        (r.productId > 0 ? (formatDecimal(toStock) + ' <span class="text-[10px] text-slate-400">' + escapeHtml(unitText) + '</span>') : '-') +
                    '</td>' +
                    '<td class="py-2.5 px-3">' +
                        '<input type="number" step="any" min="0" id="stockin-trf-qty-' + r.rowId + '" value="' + escapeHtml(r.qty) + '" oninput="onTransferRowQtyInput(' + r.rowId + ')" placeholder="0" class="w-full p-2 text-center bg-indigo-50/60 dark:bg-indigo-950/40 border ' + (isInsufficient ? 'border-rose-400 text-rose-700 dark:text-rose-300' : 'border-indigo-200 dark:border-indigo-700/80 text-indigo-900 dark:text-indigo-300') + ' rounded-xl font-mono font-black focus:ring-2 focus:ring-indigo-500 focus:outline-none">' +
                    '</td>' +
                    '<td class="py-2.5 px-3">' +
                        '<input type="text" id="stockin-trf-note-' + r.rowId + '" value="' + escapeHtml(r.notes) + '" placeholder="Catatan item (opsional)" class="w-full p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs text-slate-700 dark:text-slate-300 focus:ring-2 focus:ring-indigo-500 focus:outline-none">' +
                    '</td>' +
                    '<td class="py-2.5 px-3 text-center">' +
                        '<button type="button" onclick="removeStockTransferRow(' + r.rowId + ')" ' + (disableDel ? 'disabled' : '') + ' class="p-1.5 rounded-lg ' + (disableDel ? 'text-slate-300 dark:text-slate-600 cursor-not-allowed' : 'text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-950/40') + '" title="Hapus Baris">' +
                            '<i data-lucide="trash-2" class="w-4 h-4"></i>' +
                        '</button>' +
                    '</td>' +
                '</tr>';
            }).join('');
            lucide.createIcons();
        }

        function addStockTransferRow() {
            syncStockTransferRowsFromDOM();
            stockInState.transferRows.push({ rowId: stockInState.nextRowSeq++, productId: 0, qty: '', notes: '' });
            renderStockTransferRows();
        }

        function removeStockTransferRow(rowId) {
            syncStockTransferRowsFromDOM();
            if (stockInState.transferRows.length <= 1) return;
            stockInState.transferRows = stockInState.transferRows.filter(function(r) { return r.rowId !== rowId; });
            renderStockTransferRows();
        }

        function resetStockTransferForm() {
            stockInState.transferRows = [{ rowId: stockInState.nextRowSeq++, productId: 0, qty: '', notes: '' }];
            const notesEl = document.getElementById('stockin-trf-notes');
            if (notesEl) notesEl.value = '';
            renderStockTransferRows();
        }

        function onTransferRowProductChange(rowId) {
            syncStockTransferRowsFromDOM();
            onTransferRowQtyInput(rowId);
        }

        function onTransferRowQtyInput(rowId) {
            const pEl = document.getElementById('stockin-trf-prod-' + rowId);
            const qEl = document.getElementById('stockin-trf-qty-' + rowId);
            const fromCell = document.getElementById('stockin-trf-frombal-' + rowId);
            const toCell = document.getElementById('stockin-trf-tobal-' + rowId);
            const fromBranchId = parseInt(_val('stockin-trf-from-branch'), 10) || 0;
            const toBranchId = parseInt(_val('stockin-trf-to-branch'), 10) || 0;
            const pId = pEl ? (parseInt(pEl.value, 10) || 0) : 0;
            const qtyVal = qEl ? (parseFloat(qEl.value) || 0) : 0;

            const rowObj = stockInState.transferRows.find(function(r) { return r.rowId === rowId; });
            if (rowObj) {
                rowObj.productId = pId;
                rowObj.qty = qEl ? qEl.value : '';
            }

            if (pId <= 0) {
                if (fromCell) fromCell.innerHTML = '-';
                if (toCell) toCell.innerHTML = '-';
                return;
            }
            const prodObj = getStockInProductById(pId);
            const unitText = prodObj ? (prodObj.unit || 'pcs') : 'pcs';
            const fromStock = getStockInBranchBalance(fromBranchId, pId);
            const toStock = getStockInBranchBalance(toBranchId, pId);
            if (fromCell) {
                fromCell.className = 'py-2.5 px-3 text-right font-mono font-bold ' + (qtyVal > fromStock ? 'text-rose-600 dark:text-rose-400' : 'text-slate-700 dark:text-slate-300');
                fromCell.innerHTML = formatDecimal(fromStock) + ' <span class="text-[10px] text-slate-400">' + escapeHtml(unitText) + '</span>';
            }
            if (toCell) {
                toCell.innerHTML = formatDecimal(toStock) + ' <span class="text-[10px] text-slate-400">' + escapeHtml(unitText) + '</span>';
            }
        }

        async function submitStockTransferForm() {
            syncStockTransferRowsFromDOM();
            if ((stockInState.branches || []).length < 2) {
                alert('Dibutuhkan minimal 2 cabang aktif untuk melakukan Transfer Cabang. Silakan tambahkan cabang terlebih dahulu di menu Kelola Cabang.');
                return;
            }

            const fromBranchId = parseInt(_val('stockin-trf-from-branch'), 10) || 0;
            const toBranchId = parseInt(_val('stockin-trf-to-branch'), 10) || 0;
            const transferMode = _val('stockin-trf-mode') || 'DIRECT';
            const notes = (_val('stockin-trf-notes') || '').trim();

            if (fromBranchId <= 0 || toBranchId <= 0) {
                alert('Pilih Cabang Asal dan Cabang Tujuan transfer terlebih dahulu.');
                return;
            }
            if (fromBranchId === toBranchId) {
                alert('Cabang Asal dan Cabang Tujuan tidak boleh sama!');
                return;
            }

            const validItems = [];
            const qtyByProd = {};
            for (let i = 0; i < stockInState.transferRows.length; i++) {
                const r = stockInState.transferRows[i];
                const pId = parseInt(r.productId, 10) || 0;
                const qty = parseFloat(r.qty) || 0;
                if (pId > 0 && qty > 0) {
                    qtyByProd[pId] = (qtyByProd[pId] || 0) + qty;
                    validItems.push({
                        product_id: pId,
                        qty: qty,
                        notes: (r.notes || '').trim()
                    });
                } else if (pId > 0 && qty <= 0) {
                    const pObj = getStockInProductById(pId);
                    alert('Masukkan kuantitas transfer lebih dari 0 untuk produk "' + (pObj ? pObj.name : ('#' + pId)) + '".');
                    return;
                }
            }

            if (validItems.length === 0) {
                alert('Pilih minimal 1 produk/bahan baku dan isi kuantitas transfer lebih dari 0.');
                return;
            }

            const prodIds = Object.keys(qtyByProd);
            for (let k = 0; k < prodIds.length; k++) {
                const pid = parseInt(prodIds[k], 10);
                const reqQty = qtyByProd[pid];
                const avail = getStockInBranchBalance(fromBranchId, pid);
                if (reqQty > avail) {
                    const pObj = getStockInProductById(pid);
                    const pName = pObj ? pObj.name : ('#' + pid);
                    const pUnit = pObj ? (pObj.unit || 'pcs') : 'pcs';
                    alert('Stok "' + pName + '" di Cabang Asal tidak mencukupi! Tersedia: ' + formatDecimal(avail) + ' ' + pUnit + ', Diminta: ' + formatDecimal(reqQty) + ' ' + pUnit + '.');
                    return;
                }
            }

            const btn = document.getElementById('btn-submit-stock-transfer');
            if (btn) btn.disabled = true;
            try {
                const res = await fetch('api.php?action=create_stock_transfer', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        from_branch_id: fromBranchId,
                        to_branch_id: toBranchId,
                        transfer_mode: transferMode,
                        notes: notes,
                        items: validItems
                    })
                });
                const data = await res.json();
                if (data.success) {
                    showToast(data.message || 'Transfer stok antar cabang berhasil diproses!', 'success');
                    resetStockTransferForm();
                    await loadStockInModule();
                    if (typeof loadStockInventory === 'function') loadStockInventory();
                } else {
                    alert(data.message || 'Gagal memproses transfer stok cabang.');
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi gangguan koneksi saat mengirim data transfer cabang.');
            } finally {
                if (btn) btn.disabled = false;
            }
        }

        function renderIncomingTransfersBanner() {
            const banner = document.getElementById('stockin-incoming-banner');
            if (!banner) return;

            const incoming = (stockInState.transfers || []).filter(function(t) {
                if (t.status !== 'IN_TRANSIT') return false;
                if (stockInState.canAccessAll) return true;
                return stockInState.allowedBranchIds.indexOf(parseInt(t.to_branch_id, 10)) !== -1;
            });

            if (incoming.length === 0) {
                banner.classList.add('hidden');
                banner.innerHTML = '';
                return;
            }

            const cardsHtml = incoming.map(function(t) {
                const itemsSummary = (t.items || []).map(function(it) {
                    return escapeHtml(it.product_name || ('#' + it.product_id)) + ' (' + formatDecimal(it.qty_sent) + ' ' + escapeHtml(it.unit || 'pcs') + ')';
                }).join(', ');
                return '<div class="p-3 bg-white dark:bg-slate-900 rounded-xl border border-amber-200 dark:border-amber-800 flex flex-wrap items-center justify-between gap-2">' +
                    '<div class="text-xs">' +
                        '<div class="font-black text-slate-800 dark:text-slate-100">' + escapeHtml(t.transfer_no) + ' — <span class="text-indigo-700 dark:text-indigo-400">' + escapeHtml(t.from_branch_name || '-') + ' ➔ ' + escapeHtml(t.to_branch_name || '-') + '</span></div>' +
                        '<div class="text-[11px] text-slate-600 dark:text-slate-300 mt-0.5">' + (itemsSummary || '-') + '</div>' +
                    '</div>' +
                    '<button type="button" onclick="receiveStockTransferAction(' + parseInt(t.id, 10) + ', \'' + escapeHtml(t.transfer_no) + '\')" class="px-3.5 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-xs font-black shadow-xs flex items-center space-x-1.5">' +
                        '<i data-lucide="package-check" class="w-4 h-4"></i>' +
                        '<span>Terima Barang Masuk</span>' +
                    '</button>' +
                '</div>';
            }).join('');

            banner.innerHTML =
                '<div class="flex items-center space-x-2 text-amber-900 dark:text-amber-300 font-black text-xs">' +
                    '<i data-lucide="truck" class="w-4 h-4 text-amber-600 dark:text-amber-400"></i>' +
                    '<span>🚚 Terdapat ' + incoming.length + ' Pengiriman Transfer Cabang Menunggu Konfirmasi Penerimaan:</span>' +
                '</div>' +
                '<div class="space-y-2">' + cardsHtml + '</div>';
            banner.classList.remove('hidden');
        }

        function setStockTransferStatusFilter(status) {
            stockInState.transferStatusFilter = status || 'ALL';
            const statuses = ['ALL', 'IN_TRANSIT', 'COMPLETED', 'CANCELLED'];
            statuses.forEach(function(st) {
                const pill = document.getElementById('trf-filter-pill-' + st);
                if (!pill) return;
                if (st === stockInState.transferStatusFilter) {
                    pill.className = 'px-3 py-1.5 rounded-xl font-bold bg-indigo-600 text-white';
                } else {
                    pill.className = 'px-3 py-1.5 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-200 dark:hover:bg-slate-700';
                }
            });
            renderStockTransferHistory();
        }

        function renderStockTransferHistory() {
            const tbody = document.getElementById('stockin-trf-history-body');
            if (!tbody) return;
            const filterSt = stockInState.transferStatusFilter || 'ALL';
            const filtered = (stockInState.transfers || []).filter(function(t) {
                if (filterSt === 'ALL') return true;
                return t.status === filterSt;
            });

            if (filtered.length === 0) {
                tbody.innerHTML = '<tr><td colspan="8" class="py-8 text-center text-slate-400">Belum ada dokumen transfer stok antar cabang pada filter ini.</td></tr>';
                return;
            }

            const canCancelPerm = hasUserPerm('stock-in:transfer', 'delete') || stockInState.permissions.transfer_delete;

            tbody.innerHTML = filtered.map(function(t) {
                let statusBadge = '<span class="px-2.5 py-1 rounded-full text-[10px] font-black bg-emerald-100 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800">✅ SELESAI</span>';
                if (t.status === 'IN_TRANSIT') {
                    statusBadge = '<span class="px-2.5 py-1 rounded-full text-[10px] font-black bg-amber-100 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300 border border-amber-200 dark:border-amber-800">🚚 IN-TRANSIT</span>';
                } else if (t.status === 'CANCELLED') {
                    statusBadge = '<span class="px-2.5 py-1 rounded-full text-[10px] font-black bg-rose-100 dark:bg-rose-950/60 text-rose-800 dark:text-rose-300 border border-rose-200 dark:border-rose-800">❌ DIBATALKAN</span>';
                }

                const modeBadge = (t.transfer_mode === 'IN_TRANSIT')
                    ? '<span class="block text-[10px] text-amber-700 dark:text-amber-400 font-semibold mt-0.5">Konfirmasi Tujuan</span>'
                    : '<span class="block text-[10px] text-indigo-600 dark:text-indigo-400 font-semibold mt-0.5">⚡ Langsung (Instan)</span>';

                const itemsHtml = (t.items || []).map(function(it) {
                    const icon = isStockInRawMaterial(it.product_type) ? '🧪' : '📦';
                    return '<div class="inline-flex items-center px-2 py-0.5 mr-1 mb-1 rounded-lg bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-[11px] font-semibold text-slate-800 dark:text-slate-200">' +
                        icon + ' ' + escapeHtml(it.product_name || ('#' + it.product_id)) + ': <b class="ml-1 font-mono text-indigo-700 dark:text-indigo-400">' + formatDecimal(it.qty_sent) + ' ' + escapeHtml(it.unit || 'pcs') + '</b>' +
                    '</div>';
                }).join('');

                const canReceiveThis = (t.status === 'IN_TRANSIT') && (stockInState.canAccessAll || stockInState.allowedBranchIds.indexOf(parseInt(t.to_branch_id, 10)) !== -1);
                const canCancelThis = (t.status === 'IN_TRANSIT') && canCancelPerm && (stockInState.canAccessAll || stockInState.allowedBranchIds.indexOf(parseInt(t.from_branch_id, 10)) !== -1);

                let actionsHtml = '<span class="text-slate-300 dark:text-slate-600 text-[11px]">—</span>';
                if (canReceiveThis || canCancelThis) {
                    actionsHtml = '<div class="flex flex-wrap items-center justify-center gap-1.5">';
                    if (canReceiveThis) {
                        actionsHtml += '<button type="button" onclick="receiveStockTransferAction(' + parseInt(t.id, 10) + ', \'' + escapeHtml(t.transfer_no) + '\')" class="px-2.5 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[11px] font-bold">Terima</button>';
                    }
                    if (canCancelThis) {
                        actionsHtml += '<button type="button" onclick="cancelStockTransferAction(' + parseInt(t.id, 10) + ', \'' + escapeHtml(t.transfer_no) + '\')" class="px-2.5 py-1.5 bg-rose-50 dark:bg-rose-950/60 hover:bg-rose-100 dark:hover:bg-rose-900/60 text-rose-700 dark:text-rose-300 border border-rose-200 dark:border-rose-800 rounded-lg text-[11px] font-bold">Batal</button>';
                    }
                    actionsHtml += '</div>';
                }

                let actorInfo = 'Kirim: ' + escapeHtml(t.created_by_name || 'Admin');
                if (t.status === 'COMPLETED' && t.received_by_name) {
                    actorInfo += '<span class="block text-[10px] text-emerald-700 dark:text-emerald-400">Terima: ' + escapeHtml(t.received_by_name) + '</span>';
                } else if (t.status === 'CANCELLED' && t.cancelled_by_name) {
                    actorInfo += '<span class="block text-[10px] text-rose-600 dark:text-rose-400">Batal: ' + escapeHtml(t.cancelled_by_name) + '</span>';
                }

                return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">' +
                    '<td class="py-3 px-3 font-mono text-[11px] text-slate-500 whitespace-nowrap">' + escapeHtml(t.created_at || '-') + '</td>' +
                    '<td class="py-3 px-3 font-mono text-[11px] font-black text-indigo-800 dark:text-indigo-400 whitespace-nowrap">' + escapeHtml(t.transfer_no) + modeBadge + '</td>' +
                    '<td class="py-3 px-3 whitespace-nowrap">' +
                        '<div class="text-xs font-bold text-slate-800 dark:text-slate-100">📤 ' + escapeHtml(t.from_branch_name || '-') + '</div>' +
                        '<div class="text-xs font-bold text-teal-700 dark:text-teal-400 mt-0.5">📥 ' + escapeHtml(t.to_branch_name || '-') + '</div>' +
                    '</td>' +
                    '<td class="py-3 px-3">' + (itemsHtml || '-') + '</td>' +
                    '<td class="py-3 px-3 whitespace-nowrap">' + statusBadge + '</td>' +
                    '<td class="py-3 px-3 text-[11px] text-slate-600 dark:text-slate-300">' + escapeHtml(t.notes || '-') + '</td>' +
                    '<td class="py-3 px-3 text-[11px] text-slate-600 dark:text-slate-400 whitespace-nowrap">' + actorInfo + '</td>' +
                    '<td class="py-3 px-3 text-center whitespace-nowrap">' + actionsHtml + '</td>' +
                '</tr>';
            }).join('');
            lucide.createIcons();
        }

        async function receiveStockTransferAction(transferId, transferNo) {
            if (!confirm('Konfirmasi penerimaan barang masuk untuk dokumen ' + transferNo + '?\nStok akan langsung ditambahkan ke Cabang Tujuan.')) {
                return;
            }
            try {
                const res = await fetch('api.php?action=receive_stock_transfer', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ transfer_id: transferId })
                });
                const data = await res.json();
                if (data.success) {
                    showToast(data.message || 'Barang transfer berhasil diterima!', 'success');
                    await loadStockInModule();
                    if (typeof loadStockInventory === 'function') loadStockInventory();
                } else {
                    alert(data.message || 'Gagal mengonfirmasi penerimaan transfer.');
                }
            } catch (err) {
                alert('Terjadi kesalahan koneksi saat mengonfirmasi penerimaan transfer.');
            }
        }

        async function cancelStockTransferAction(transferId, transferNo) {
            if (!confirm('Batalkan dokumen transfer ' + transferNo + '?\nSeluruh stok yang telah dipotong akan dikembalikan utuh ke Cabang Asal.')) {
                return;
            }
            try {
                const res = await fetch('api.php?action=cancel_stock_transfer', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ transfer_id: transferId })
                });
                const data = await res.json();
                if (data.success) {
                    showToast(data.message || 'Dokumen transfer dibatalkan & stok dikembalikan.', 'info');
                    await loadStockInModule();
                    if (typeof loadStockInventory === 'function') loadStockInventory();
                } else {
                    alert(data.message || 'Gagal membatalkan dokumen transfer.');
                }
            } catch (err) {
                alert('Terjadi kesalahan koneksi saat membatalkan transfer.');
            }
        }

        // ==========================================
        // 8. LAPORAN LABA RUGI & INTEGRASI PIUTANG USAHA
        // ==========================================
        async function loadProfitLoss() {
            const bId = state.currentBranch ? state.currentBranch.id : '';
            const res = await fetch(`api.php?action=profit_loss_report&branch_id=${bId}`);
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

            const pnl = data.income_statement;
            const ar = pnl.receivables_analysis || {};

            const pnlCompany = (data.company_name && data.company_name.trim())
                ? data.company_name.trim()
                : ((state.appSettings && state.appSettings.company_name && state.appSettings.company_name.trim())
                    ? state.appSettings.company_name.trim()
                    : ((state.appSettings && state.appSettings.app_name) ? state.appSettings.app_name : 'ESBAS RETAIL INDONESIA'));
            const pnlCompEl = document.getElementById('pnl-header-company');
            if (pnlCompEl) pnlCompEl.innerText = pnlCompany.toUpperCase();

