            document.getElementById('pnl-gross-sales').innerText = formatRupiah(pnl.gross_sales);
            
            const elCashSales = document.getElementById('pnl-cash-sales');
            if (elCashSales) elCashSales.innerText = formatRupiah(pnl.cash_sales || 0);

            const elRecSales = document.getElementById('pnl-receivable-sales');
            if (elRecSales) elRecSales.innerText = formatRupiah(pnl.receivable_sales || 0);

            document.getElementById('pnl-discount').innerText = `(${formatRupiah(pnl.discount)})`;
            document.getElementById('pnl-cogs').innerText = `(${formatRupiah(pnl.cogs)})`;
            document.getElementById('pnl-cogs-detail').innerText = formatRupiah(pnl.cogs);
            document.getElementById('pnl-gross-profit').innerText = `${formatRupiah(pnl.gross_profit)} (${pnl.gross_margin_percent}%)`;
            document.getElementById('pnl-total-expenses').innerText = `(${formatRupiah(pnl.total_operating_expenses)})`;

            document.getElementById('pnl-expenses-list').innerHTML = pnl.operating_expenses_list.map(exp => `
                <div class="flex justify-between items-center py-1 border-b border-dashed border-slate-100 dark:border-slate-800">
                    <span class="text-slate-600 dark:text-slate-300">${exp.category} ${exp.source === 'REIMBURSEMENT_ESS' ? '<span class="text-[9px] px-2 py-0.5 bg-amber-100 dark:bg-amber-950/80 text-amber-800 dark:text-amber-300 border border-amber-200 dark:border-amber-800/80 rounded-full font-bold ml-1">ESS Klaim</span>' : ''}</span>
                    <span class="font-bold text-slate-700 dark:text-slate-200 font-mono">${formatRupiah(exp.total_amount)}</span>
                </div>
            `).join('') || `<p class="text-slate-400 dark:text-slate-500">Belum ada beban operasional tercatat</p>`;

            document.getElementById('pnl-operating-income').innerText = formatRupiah(pnl.operating_income);
            document.getElementById('pnl-tax').innerText = `(${formatRupiah(pnl.estimated_tax)})`;
            document.getElementById('pnl-net-profit').innerText = formatRupiah(pnl.net_profit);
            document.getElementById('pnl-net-margin').innerText = `${pnl.net_margin_percent}%`;

            // Populasi Kotak Analisis Piutang Usaha & Realisasi Kas
            const elArRatio = document.getElementById('pnl-ar-ratio-badge');
            if (elArRatio) elArRatio.innerText = `Rasio Piutang: ${ar.receivable_ratio_percent || 0}%`;

            const elArBilled = document.getElementById('pnl-ar-billed');
            if (elArBilled) elArBilled.innerText = formatRupiah(ar.period_receivables_billed || 0);

            const elArCollected = document.getElementById('pnl-ar-collected');
            if (elArCollected) elArCollected.innerText = `+ ${formatRupiah(ar.period_receivables_collected || 0)}`;

            const elArPeriodOut = document.getElementById('pnl-ar-period-outstanding');
            if (elArPeriodOut) elArPeriodOut.innerText = formatRupiah(ar.period_receivables_outstanding || 0);

            const elArCumOut = document.getElementById('pnl-ar-cum-outstanding');
            if (elArCumOut) elArCumOut.innerText = formatRupiah(ar.cumulative_outstanding_receivables || 0);

            const elArCashSales = document.getElementById('pnl-ar-cash-realized-sales');
            if (elArCashSales) elArCashSales.innerText = formatRupiah(ar.cash_realized_sales || 0);

            const elArCashProfit = document.getElementById('pnl-ar-cash-realized-profit');
            if (elArCashProfit) elArCashProfit.innerText = formatRupiah(ar.cash_realized_net_profit || 0);

            lucide.createIcons();
        }

        // ==========================================
        // 8B. MODUL LAPORAN PENJUALAN MITRA (B2B PARTNER SALES REPORT)
        // ==========================================
        let partnerPeriodType = 'monthly';
        let partnerReportRawData = null;
        let activePartnerOrder = null;

        function setPartnerPeriod(type) {
            partnerPeriodType = type;
            const pills = ['weekly', 'monthly', 'quarter', 'semester', 'yearly', 'custom'];
            pills.forEach(p => {
                const btn = document.getElementById(`partner-pill-${p}`);
                if (!btn) return;
                if (p === type) {
                    btn.className = "px-3 py-1.5 rounded-xl text-xs font-bold transition-all bg-emerald-600 text-white shadow-2xs";
                } else {
                    btn.className = "px-3 py-1.5 rounded-xl text-xs font-bold transition-all bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-200";
                }
            });
            renderPartnerPeriodControls();
            loadPartnerSalesReport();
        }

        function renderPartnerPeriodControls() {
            const container = document.getElementById('partner-time-dynamic-container');
            if (!container) return;

            const now = new Date();
            const curYear = now.getFullYear();
            const curMonth = now.getMonth() + 1; // 1-12

            let html = '';

            if (partnerPeriodType === 'weekly') {
                html = `
                    <div class="flex items-center space-x-2">
                        <span class="font-bold text-slate-600">Pilihan Minggu:</span>
                        <select id="partner-control-week-preset" onchange="loadPartnerSalesReport()" class="p-1.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl font-bold text-slate-800 dark:text-slate-100 text-xs focus:ring-2 focus:ring-emerald-500">
                            <option value="this_week" selected>Minggu Ini (Senin - Minggu Sekarang)</option>
                            <option value="last_week">1 Minggu Lalu (Last Week)</option>
                            <option value="last_2_weeks">2 Minggu Lalu</option>
                            <option value="last_4_weeks">4 Minggu Terakhir (Trailing 28 Hari)</option>
                        </select>
                    </div>
                `;
            } else if (partnerPeriodType === 'monthly') {
                const months = [
                    'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
                    'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'
                ];
                let mOptions = months.map((m, idx) => {
                    const val = idx + 1;
                    return `<option value="${val}" ${val === curMonth ? 'selected' : ''}>${m}</option>`;
                }).join('');

                let yOptions = '';
                for (let y = curYear; y >= curYear - 4; y--) {
                    yOptions += `<option value="${y}" ${y === curYear ? 'selected' : ''}>${y}</option>`;
                }

                html = `
                    <div class="flex items-center space-x-2">
                        <span class="font-bold text-slate-600">Bulan:</span>
                        <select id="partner-control-month" onchange="loadPartnerSalesReport()" class="p-1.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl font-bold text-slate-800 dark:text-slate-100 text-xs focus:ring-2 focus:ring-emerald-500">
                            ${mOptions}
                        </select>
                    </div>
                    <div class="flex items-center space-x-2">
                        <span class="font-bold text-slate-600">Tahun:</span>
                        <select id="partner-control-year" onchange="loadPartnerSalesReport()" class="p-1.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl font-bold text-slate-800 dark:text-slate-100 text-xs focus:ring-2 focus:ring-emerald-500">
                            ${yOptions}
                        </select>
                    </div>
                `;
            } else if (partnerPeriodType === 'quarter') {
                const curQuarter = Math.ceil(curMonth / 3);
                let qOptions = [
                    { val: 1, label: 'Kuartal 1 (Q1: Januari - Maret)' },
                    { val: 2, label: 'Kuartal 2 (Q2: April - Juni)' },
                    { val: 3, label: 'Kuartal 3 (Q3: Juli - September)' },
                    { val: 4, label: 'Kuartal 4 (Q4: Oktober - Desember)' }
                ].map(q => `<option value="${q.val}" ${q.val === curQuarter ? 'selected' : ''}>${q.label}</option>`).join('');

                let yOptions = '';
                for (let y = curYear; y >= curYear - 4; y--) {
                    yOptions += `<option value="${y}" ${y === curYear ? 'selected' : ''}>${y}</option>`;
                }

                html = `
                    <div class="flex items-center space-x-2">
                        <span class="font-bold text-slate-600">Kuartal:</span>
                        <select id="partner-control-quarter" onchange="loadPartnerSalesReport()" class="p-1.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl font-bold text-slate-800 dark:text-slate-100 text-xs focus:ring-2 focus:ring-emerald-500">
                            ${qOptions}
                        </select>
                    </div>
                    <div class="flex items-center space-x-2">
                        <span class="font-bold text-slate-600">Tahun:</span>
                        <select id="partner-control-year" onchange="loadPartnerSalesReport()" class="p-1.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl font-bold text-slate-800 dark:text-slate-100 text-xs focus:ring-2 focus:ring-emerald-500">
                            ${yOptions}
                        </select>
                    </div>
                `;
            } else if (partnerPeriodType === 'semester') {
                const curSem = curMonth <= 6 ? 1 : 2;
                let sOptions = [
                    { val: 1, label: 'Semester 1 (Januari - Juni)' },
                    { val: 2, label: 'Semester 2 (Juli - Desember)' }
                ].map(s => `<option value="${s.val}" ${s.val === curSem ? 'selected' : ''}>${s.label}</option>`).join('');

                let yOptions = '';
                for (let y = curYear; y >= curYear - 4; y--) {
                    yOptions += `<option value="${y}" ${y === curYear ? 'selected' : ''}>${y}</option>`;
                }

                html = `
                    <div class="flex items-center space-x-2">
                        <span class="font-bold text-slate-600">Semester:</span>
                        <select id="partner-control-semester" onchange="loadPartnerSalesReport()" class="p-1.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl font-bold text-slate-800 dark:text-slate-100 text-xs focus:ring-2 focus:ring-emerald-500">
                            ${sOptions}
                        </select>
                    </div>
                    <div class="flex items-center space-x-2">
                        <span class="font-bold text-slate-600">Tahun:</span>
                        <select id="partner-control-year" onchange="loadPartnerSalesReport()" class="p-1.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl font-bold text-slate-800 dark:text-slate-100 text-xs focus:ring-2 focus:ring-emerald-500">
                            ${yOptions}
                        </select>
                    </div>
                `;
            } else if (partnerPeriodType === 'yearly') {
                let yOptions = '';
                for (let y = curYear; y >= curYear - 5; y--) {
                    yOptions += `<option value="${y}" ${y === curYear ? 'selected' : ''}>Tahun Fiskal ${y}</option>`;
                }

                html = `
                    <div class="flex items-center space-x-2">
                        <span class="font-bold text-slate-600">Pilih Tahun:</span>
                        <select id="partner-control-year" onchange="loadPartnerSalesReport()" class="p-1.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl font-bold text-slate-800 dark:text-slate-100 text-xs focus:ring-2 focus:ring-emerald-500">
                            ${yOptions}
                        </select>
                    </div>
                `;
            } else if (partnerPeriodType === 'custom') {
                const todayStr = now.toISOString().split('T')[0];
                const firstDayStr = new Date(curYear, now.getMonth(), 1).toISOString().split('T')[0];
                html = `
                    <div class="flex items-center space-x-2">
                        <span class="font-bold text-slate-600">Mulai:</span>
                        <input type="date" id="partner-control-start-date" value="${firstDayStr}" class="p-1.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl font-bold text-slate-800 dark:text-slate-100 text-xs focus:ring-2 focus:ring-emerald-500">
                    </div>
                    <div class="flex items-center space-x-2">
                        <span class="font-bold text-slate-600">Sampai:</span>
                        <input type="date" id="partner-control-end-date" value="${todayStr}" class="p-1.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl font-bold text-slate-800 dark:text-slate-100 text-xs focus:ring-2 focus:ring-emerald-500">
                    </div>
                    <button type="button" onclick="loadPartnerSalesReport()" class="px-3 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-xs font-bold shadow-2xs">Terapkan Tanggal</button>
                `;
            }

            container.innerHTML = html;
        }

        function populatePartnerBranchesDropdown() {
            const select = document.getElementById('partner-filter-branch');
            if (!select) return;

            const curUser = state.currentUser || state.loggedInUser || {};
            const rawRole = ((curUser.role || 'CASHIER') + '').toUpperCase().replace(/_/g, '').trim();
            const isSuperAdmin = (rawRole === 'SUPERADMIN' || rawRole === 'SUPER ADMIN');
            const isManager = isSuperAdmin || rawRole === 'BRANCHMANAGER' || rawRole === 'MANAGER';
            const userBranchId = curUser.branch_id || (state.currentBranch ? state.currentBranch.id : 1);

            let optionsHtml = '';
            if (isSuperAdmin) {
                optionsHtml += '<option value="ALL">🌐 Semua Cabang (Konsolidasi)</option>';
                if (state.branches && state.branches.length > 0) {
                    state.branches.forEach(b => {
                        optionsHtml += `<option value="${b.id}">${escapeHtml(b.name)}</option>`;
                    });
                }
                select.disabled = false;
                select.classList.remove('opacity-75', 'cursor-not-allowed', 'bg-slate-100');
            } else if (isManager) {
                let myBranches = [];
                if (curUser.assigned_branch_ids) {
                    try {
                        const parsed = typeof curUser.assigned_branch_ids === 'string' ? JSON.parse(curUser.assigned_branch_ids) : curUser.assigned_branch_ids;
                        if (Array.isArray(parsed) && parsed.length > 0) {
                            myBranches = (state.branches || []).filter(b => parsed.indexOf(parseInt(b.id, 10)) !== -1);
                        }
                    } catch(e) {}
                }
                if (myBranches.length === 0) {
                    myBranches = (state.branches || []).filter(b => b.id == userBranchId);
                }
                if (myBranches.length > 1) {
                    optionsHtml += '<option value="ALL">🌐 Semua Cabang Ditugaskan</option>';
                    myBranches.forEach(b => {
                        optionsHtml += `<option value="${b.id}">${escapeHtml(b.name)}</option>`;
                    });
                    select.disabled = false;
                    select.classList.remove('opacity-75', 'cursor-not-allowed', 'bg-slate-100');
                } else {
                    const bObj = myBranches[0] || (state.branches || []).find(b => b.id == userBranchId) || state.currentBranch || { id: userBranchId, name: 'Cabang Penugasan' };
                    optionsHtml += `<option value="${bObj.id}">📍 ${escapeHtml(bObj.name)}</option>`;
                    select.disabled = true;
                    select.classList.add('opacity-75', 'cursor-not-allowed', 'bg-slate-100');
                }
            } else {
                // KASIR / STAFF / KARYAWAN: HANYA BISA MELIHAT CABANG DI MANA DIA DIPOSISIKAN
                const myBranch = (state.branches || []).find(b => b.id == userBranchId) || state.currentBranch || { id: userBranchId, name: 'Cabang Penugasan' };
                optionsHtml += `<option value="${myBranch.id}">📍 ${escapeHtml(myBranch.name)} (Terkunci)</option>`;
                select.disabled = true;
                select.classList.add('opacity-75', 'cursor-not-allowed', 'bg-slate-100');
            }

            select.innerHTML = optionsHtml;
            if (isSuperAdmin) {
                const curVal = select.value;
                if (curVal && select.querySelector(`option[value="${curVal}"]`)) {
                    select.value = curVal;
                } else {
                    select.value = 'ALL';
                }
            } else {
                select.value = userBranchId;
            }
        }

        function populatePartnerMitraDropdown(mitraList) {
            const select = document.getElementById('partner-filter-customer');
            if (!select || !mitraList) return;

            const curVal = select.value;
            let optionsHtml = '<option value="ALL">🌐 Semua Mitra Terdaftar</option>';

            mitraList.forEach(m => {
                optionsHtml += `<option value="${m.id}">${escapeHtml(m.name)} (${escapeHtml(m.branch_name || 'Cabang')})</option>`;
            });

            select.innerHTML = optionsHtml;
            if (curVal && select.querySelector(`option[value="${curVal}"]`)) {
                select.value = curVal;
            }
        }

        async function loadPartnerSalesReport() {
            try {
                // Populate branch dropdown if empty
                const branchSel = document.getElementById('partner-filter-branch');
                if (branchSel && branchSel.options.length <= 1) {
                    populatePartnerBranchesDropdown();
                }

                // Check period controls
                const container = document.getElementById('partner-time-dynamic-container');
                if (container && (!container.innerHTML || container.children.length === 0)) {
                    renderPartnerPeriodControls();
                }

                const curUser = state.currentUser || state.loggedInUser || {};
                const rawRole = ((curUser.role || 'CASHIER') + '').toUpperCase().replace(/_/g, '').trim();
                const isSuperAdmin = (rawRole === 'SUPERADMIN' || rawRole === 'SUPER ADMIN');
                const isManager = isSuperAdmin || rawRole === 'BRANCHMANAGER' || rawRole === 'MANAGER';
                const userBranchId = curUser.branch_id || (state.currentBranch ? state.currentBranch.id : 1);

                let branchId = branchSel ? branchSel.value : 'ALL';
                if (!isSuperAdmin && !isManager) {
                    branchId = userBranchId;
                    if (branchSel) branchSel.value = userBranchId;
                }

                const customerId = _val('partner-filter-customer') || 'ALL';
                const paymentStatus = _val('partner-filter-status') || 'ALL';
                const paymentMethod = _val('partner-filter-method') || 'ALL';

                let url = `api.php?action=partner_sales_report&period_type=${encodeURIComponent(partnerPeriodType)}`;
                if (curUser && curUser.id) url += `&user_id=${encodeURIComponent(curUser.id)}`;
                if (branchId) url += `&branch_id=${encodeURIComponent(branchId)}`;
                if (customerId) url += `&customer_id=${encodeURIComponent(customerId)}`;
                if (paymentStatus) url += `&payment_status=${encodeURIComponent(paymentStatus)}`;
                if (paymentMethod) url += `&payment_method=${encodeURIComponent(paymentMethod)}`;

                if (partnerPeriodType === 'weekly') {
                    const preset = _val('partner-control-week-preset') || 'this_week';
                    url += `&week_preset=${encodeURIComponent(preset)}`;
                } else if (partnerPeriodType === 'monthly') {
                    const m = _val('partner-control-month');
                    const y = _val('partner-control-year');
                    if (m) url += `&month=${m}`;
                    if (y) url += `&year=${y}`;
                } else if (partnerPeriodType === 'quarter') {
                    const q = _val('partner-control-quarter');
                    const y = _val('partner-control-year');
                    if (q) url += `&quarter=${q}`;
                    if (y) url += `&year=${y}`;
                } else if (partnerPeriodType === 'semester') {
                    const s = _val('partner-control-semester');
                    const y = _val('partner-control-year');
                    if (s) url += `&semester=${s}`;
                    if (y) url += `&year=${y}`;
                } else if (partnerPeriodType === 'yearly') {
                    const y = _val('partner-control-year');
                    if (y) url += `&year=${y}`;
                } else if (partnerPeriodType === 'custom') {
                    const sDate = _val('partner-control-start-date');
                    const eDate = _val('partner-control-end-date');
                    if (sDate) url += `&start_date=${encodeURIComponent(sDate)}`;
                    if (eDate) url += `&end_date=${encodeURIComponent(eDate)}`;
                }

                const res = await fetch(url);
                const data = await res.json();
                if (!data.success) {
                    console.error('Failed to load partner sales report:', data.error);
                    return;
                }

                partnerReportRawData = data;
                renderPartnerSalesReport(data);
            } catch (err) {
                console.error('Error loading partner sales report:', err);
            }
        }

        function renderPartnerSalesReport(data) {
            if (!data) return;

            // Period Label
            const periodLabel = data.period_label || 'Periode Terpilih';
            const periodTextEl = document.getElementById('partner-active-period-text');
            if (periodTextEl) {
                periodTextEl.innerHTML = `<strong>Periode Aktif:</strong> ${escapeHtml(periodLabel)} &bull; Rentang Tanggal: <span class="font-mono text-emerald-800 font-bold">${escapeHtml(data.start_date || '')}</span> s/d <span class="font-mono text-emerald-800 font-bold">${escapeHtml(data.end_date || '')}</span>`;
            }

            const orders = data.orders || [];
            const countBadge = document.getElementById('partner-active-orders-count-badge');
            if (countBadge) countBadge.innerText = `${orders.length} Pesanan Mitra`;

            // Populate Mitra Filter
            if (data.mitra_list) {
                populatePartnerMitraDropdown(data.mitra_list);
            }

            // KPI Cards
            const kpi = data.kpi || {};
            const revEl = document.getElementById('partner-kpi-revenue');
            if (revEl) revEl.innerText = formatRupiah(kpi.total_revenue || 0);

            const revSubEl = document.getElementById('partner-kpi-revenue-sub');
            if (revSubEl) revSubEl.innerText = `Kotor: ${formatRupiah(kpi.gross_sales || 0)} (Disc: -${formatRupiah(kpi.total_discount || 0)})`;

            const ordEl = document.getElementById('partner-kpi-orders');
            if (ordEl) ordEl.innerText = (kpi.total_orders || 0).toLocaleString('id-ID');

            const ordSubEl = document.getElementById('partner-kpi-orders-sub');
            if (ordSubEl) ordSubEl.innerText = `${(kpi.total_items_sold || 0).toLocaleString('id-ID')} Total Item Terjual`;

            const profitEl = document.getElementById('partner-kpi-profit');
            if (profitEl) profitEl.innerText = formatRupiah(kpi.gross_profit || 0);

            const profitSubEl = document.getElementById('partner-kpi-profit-sub');
            if (profitSubEl) profitSubEl.innerText = `Margin: ${kpi.margin_percent || 0}% • HPP: ${formatRupiah(kpi.total_cogs || 0)}`;

            const paidEl = document.getElementById('partner-kpi-paid');
            if (paidEl) paidEl.innerText = formatRupiah(kpi.total_paid || 0);

            const recEl = document.getElementById('partner-kpi-receivable');
            if (recEl) recEl.innerText = formatRupiah(kpi.total_receivables || 0);

            // Leaderboard Top Partners
            const topBoard = document.getElementById('partner-top-leaderboard');
            if (topBoard) {
                const tops = data.top_partners || [];
                if (tops.length === 0) {
                    topBoard.innerHTML = '<div class="col-span-full py-4 text-center text-xs text-slate-400 italic">Belum ada transaksi mitra pada kurun waktu ini.</div>';
                } else {
                    topBoard.innerHTML = tops.map((p, idx) => {
                        const rankMedals = ['🥇', '🥈', '🥉', '🏅'];
                        const medal = rankMedals[idx] || '⭐';
                        const partnerTitle = p.partner_name || p.customer_name || 'Mitra';
                        const totalOrders = _nn(p.total_orders, _nn(p.order_count, 0));
                        const totalRevenue = _nn(p.total_revenue, _nn(p.total_spend, 0));
                        const totalItems = _nn(p.total_items, 0);
                        const totalProfit = _nn(p.total_profit, _nn(p.gross_profit, 0));
                        return `
                            <div class="bg-slate-50 dark:bg-slate-800/80 p-3 rounded-2xl border border-slate-200/80 dark:border-slate-800 flex items-center space-x-3 hover:bg-slate-100/70 dark:hover:bg-slate-700/60 transition-colors">
                                <span class="text-2xl">${medal}</span>
                                <div class="min-w-0 flex-1">
                                    <div class="flex items-center justify-between">
                                        <h5 class="font-bold text-slate-800 dark:text-slate-100 text-xs truncate" title="${escapeHtml(partnerTitle)}">${escapeHtml(partnerTitle)}</h5>
                                        <span class="text-[10px] font-bold text-emerald-700 dark:text-emerald-300 bg-emerald-100 dark:bg-emerald-950/80 px-1.5 py-0.5 rounded border border-emerald-200 dark:border-emerald-800">${totalOrders} Order</span>
                                    </div>
                                    <div class="text-xs font-black text-slate-900 dark:text-slate-100 font-mono mt-0.5">${formatRupiah(totalRevenue)}</div>
                                    <div class="text-[10px] text-slate-400 dark:text-slate-400 flex items-center justify-between mt-0.5">
                                        <span>${totalItems} item</span>
                                        <span class="text-indigo-600 dark:text-indigo-400 font-medium">Laba: ${formatRupiah(totalProfit)}</span>
                                    </div>
                                </div>
                            </div>
                        `;
                    }).join('');
                }
            }

            renderFilteredPartnerOrdersTable();
            lucide.createIcons();
        }

        function renderFilteredPartnerOrdersTable() {
            if (!partnerReportRawData) return;
            const tbody = document.getElementById('partner-orders-tbody');
            if (!tbody) return;

            const searchQuery = (_val('partner-orders-search') || '').toLowerCase().trim();
            const orders = partnerReportRawData.orders || [];

            const filtered = orders.filter(o => {
                if (!searchQuery) return true;
                const inv = (o.invoice_number || '').toLowerCase();
                const cust = (o.customer_name || '').toLowerCase();
                const branch = (o.branch_name || '').toLowerCase();
                const itemsText = (o.items || []).map(i => `${i.product_name} ${i.variant_name || ''}`).join(' ').toLowerCase();
                return inv.includes(searchQuery) || cust.includes(searchQuery) || branch.includes(searchQuery) || itemsText.includes(searchQuery);
            });

            if (filtered.length === 0) {
                tbody.innerHTML = `
                    <tr>
                        <td colspan="9" class="py-12 text-center text-slate-400 text-xs">
                            <i data-lucide="inbox" class="w-8 h-8 mx-auto text-slate-300 mb-2"></i>
                            <p class="font-bold">Tidak ada transaksi penjualan mitra yang cocok dengan filter / pencarian.</p>
                        </td>
                    </tr>
                `;
                lucide.createIcons();
                return;
            }

            tbody.innerHTML = filtered.map((o) => {
                // Status badge
                let statusBadge = '<span class="px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-200">LUNAS</span>';
                if (o.payment_status === 'UNPAID') {
                    statusBadge = '<span class="px-2 py-0.5 rounded-full text-[10px] font-black bg-amber-100 text-amber-800 border border-amber-200">PIUTANG</span>';
                }

                // Render items preview
                const items = o.items || [];
                let itemsPreview = '';
                if (items.length === 0) {
                    itemsPreview = '<span class="text-slate-400 italic text-[11px]">- Tidak ada rincian item -</span>';
                } else {
                    const shownItems = items.slice(0, 2);
                    const itemLines = shownItems.map(it => {
                        const vText = it.variant_name ? ` (${it.variant_name})` : '';
                        const qty = _nn(it.quantity, _nn(it.qty, 0));
                        return `<div class="truncate text-slate-700 font-medium" title="${escapeHtml(it.product_name + vText)}">• <strong>${qty}x</strong> ${escapeHtml(it.product_name + vText)} <span class="text-slate-400 font-mono text-[10px]">@${formatRupiah(it.unit_price)}</span></div>`;
                    }).join('');
                    const moreCount = items.length - shownItems.length;
                    const moreTag = moreCount > 0 ? `<div class="text-[10px] text-emerald-600 font-bold mt-0.5">+${moreCount} item lainnya...</div>` : '';
                    itemsPreview = itemLines + moreTag;
                }

                // Profit tag
                const profitColor = Number(o.profit || 0) >= 0 ? 'text-indigo-700 font-bold' : 'text-rose-600 font-bold';

                return `
                    <tr class="hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors">
                        <td class="py-3 px-3.5 font-mono font-bold text-slate-800 dark:text-slate-100">
                            <button type="button" onclick="openSaleDetailModal('${escapeHtml(o.invoice_number)}')" class="text-emerald-700 dark:text-emerald-400 hover:text-emerald-800 dark:hover:text-emerald-300 hover:underline flex items-center space-x-1" title="Lihat struk/faktur">
                                <span>${escapeHtml(o.invoice_number)}</span>
                                <i data-lucide="external-link" class="w-3 h-3 text-emerald-600 dark:text-emerald-400"></i>
                            </button>
                        </td>
                        <td class="py-3 px-3 font-mono text-slate-600 dark:text-slate-400 text-[11px] whitespace-nowrap">
                            ${escapeHtml(o.created_at || '-')}
                        </td>
                        <td class="py-3 px-3.5">
                            <div class="font-bold text-slate-900 dark:text-slate-100">${escapeHtml(o.customer_name || 'Mitra')}</div>
                            <div class="text-[10px] text-slate-400 font-mono">${escapeHtml(o.customer_phone || '-')}</div>
                        </td>
                        <td class="py-3 px-3">
                            <div class="font-bold text-slate-800 dark:text-slate-200">${escapeHtml(o.branch_name || '-')}</div>
                            <div class="text-[10px] text-slate-500 dark:text-slate-400">Kasir: ${escapeHtml(o.cashier_name || '-')}</div>
                        </td>
                        <td class="py-3 px-4 max-w-xs">
                            ${itemsPreview}
                        </td>
                        <td class="py-3 px-3 text-center whitespace-nowrap space-y-1">
                            <div>${statusBadge}</div>
                            <span class="px-2 py-0.5 rounded text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">${escapeHtml(o.payment_method || 'CASH')}</span>
                        </td>
                        <td class="py-3 px-3 text-right font-mono font-bold text-slate-900 dark:text-slate-100">
                            ${formatRupiah(_nn(o.final_total, _nn(o.grand_total, 0)))}
                        </td>
                        <td class="py-3 px-3 text-right font-mono ${profitColor}">
                            <div>${formatRupiah(o.profit || 0)}</div>
                            <div class="text-[10px] text-slate-400 font-normal">HPP: ${formatRupiah(_nn(o.cogs, _nn(o.total_cogs, 0)))}</div>
                        </td>
                        <td class="py-3 px-3 text-center whitespace-nowrap">
                            <div class="flex items-center justify-center space-x-1.5">
                                <button type="button" onclick="openPartnerOrderDetail(${o.id})" class="p-1.5 bg-emerald-50 dark:bg-emerald-950/80 hover:bg-emerald-100 dark:hover:bg-emerald-900 text-emerald-700 dark:text-emerald-300 rounded-lg text-xs font-bold transition-colors" title="Rincian Pesanan Mitra Lengkap">
                                    <i data-lucide="eye" class="w-4 h-4"></i>
                                </button>
                                <button type="button" onclick="openSaleDetailModal('${escapeHtml(o.invoice_number)}')" class="p-1.5 bg-indigo-50 dark:bg-indigo-950/80 hover:bg-indigo-100 dark:hover:bg-indigo-900 text-indigo-700 dark:text-indigo-300 rounded-lg text-xs font-bold transition-colors" title="Cetak Struk / Faktur Kasir">
                                    <i data-lucide="printer" class="w-4 h-4"></i>
                                </button>
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');

            lucide.createIcons();
        }

        function openPartnerOrderDetail(saleId) {
            if (!partnerReportRawData || !partnerReportRawData.orders) return;
            const order = partnerReportRawData.orders.find(o => o.id == saleId);
            if (!order) return;

            activePartnerOrder = order;

            const modal = document.getElementById('partner-order-detail-modal');
            if (!modal) return;

            // Invoice & Badges
            document.getElementById('pod-modal-invoice').innerText = order.invoice_number || 'INV/-';
            
            const statusEl = document.getElementById('pod-modal-status-badge');
            if (statusEl) {
                if (order.payment_status === 'UNPAID') {
                    statusEl.className = "px-2.5 py-0.5 rounded-full text-[10px] font-black bg-amber-100 text-amber-800 border border-amber-200";
                    statusEl.innerText = 'PIUTANG (BELUM LUNAS)';
                } else {
                    statusEl.className = "px-2.5 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-200";
                    statusEl.innerText = 'LUNAS';
                }
            }

            const methodEl = document.getElementById('pod-modal-method-badge');
            if (methodEl) {
                methodEl.innerText = order.payment_method || 'CASH';
            }

            // Customer & Location info
            document.getElementById('pod-modal-partner-name').innerText = order.customer_name || 'Mitra B2B';
            document.getElementById('pod-modal-partner-phone').innerText = `Telp: ${order.customer_phone || '-'}`;
            document.getElementById('pod-modal-partner-address').innerText = order.customer_address || '-';
            document.getElementById('pod-modal-datetime').innerText = `${order.created_at || '-'} • Kasir: ${order.cashier_name || '-'}`;
            document.getElementById('pod-modal-branch').innerText = `Cabang: ${order.branch_name || '-'}`;

            // Items Table
            const tbody = document.getElementById('pod-modal-items-tbody');
            const items = order.items || [];

            if (items.length === 0) {
                tbody.innerHTML = '<tr><td colspan="8" class="py-6 text-center text-slate-400 italic">Tidak ada rincian item pesanan.</td></tr>';
            } else {
                tbody.innerHTML = items.map((it, idx) => {
                    const vText = it.variant_name ? ` <span class="text-emerald-700 font-medium">(${escapeHtml(it.variant_name)})</span>` : '';
                    const profit = Number(it.profit || 0);
                    const profitClass = profit >= 0 ? 'text-indigo-700 font-bold' : 'text-rose-600 font-bold';
                    const qty = _nn(it.quantity, _nn(it.qty, 0));
                    const subtotal = _nn(it.subtotal, _nn(it.subtotal_price, 0));
                    const costPrice = _nn(it.cost_price, _nn(it.unit_cogs, 0));
                    const totalCogs = _nn(it.total_cogs, _nn(it.subtotal_cogs, 0));
                    return `
                        <tr class="hover:bg-slate-50">
                            <td class="py-2.5 px-3 text-slate-400 font-mono">${idx + 1}</td>
                            <td class="py-2.5 px-3">
                                <div class="font-bold text-slate-800">${escapeHtml(it.product_name)}${vText}</div>
                                <div class="text-[10px] text-slate-400 font-mono">SKU: ${escapeHtml(it.sku || '-')}</div>
                            </td>
                            <td class="py-2.5 px-2 text-center font-bold text-slate-900">${qty}</td>
                            <td class="py-2.5 px-3 text-right font-mono text-slate-700">${formatRupiah(it.unit_price || 0)}</td>
                            <td class="py-2.5 px-3 text-right font-mono font-bold text-slate-900">${formatRupiah(subtotal)}</td>
                            <td class="py-2.5 px-3 text-right font-mono text-slate-500">${formatRupiah(costPrice)}</td>
                            <td class="py-2.5 px-3 text-right font-mono text-slate-600">${formatRupiah(totalCogs)}</td>
                            <td class="py-2.5 px-3 text-right font-mono ${profitClass}">${formatRupiah(profit)}</td>
                        </tr>
                    `;
                }).join('');
            }

            // Summary Breakdown
            document.getElementById('pod-modal-subtotal').innerText = formatRupiah(_nn(order.total_amount, _nn(order.subtotal, 0)));
            document.getElementById('pod-modal-discount').innerText = `- ${formatRupiah(order.discount || 0)}`;
            document.getElementById('pod-modal-delivery').innerText = formatRupiah(order.delivery_fee || 0);
            document.getElementById('pod-modal-grand-total').innerText = formatRupiah(_nn(order.final_total, _nn(order.grand_total, 0)));

            const finalTotal = Number(_nn(order.final_total, _nn(order.grand_total, 0)));
            const profitMargin = finalTotal > 0 ? ((Number(order.profit || 0) / finalTotal) * 100).toFixed(1) : '0';
            document.getElementById('pod-modal-total-profit').innerText = `${formatRupiah(order.profit || 0)} (Margin: ${profitMargin}%)`;

            modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closePartnerOrderDetailModal() {
            const modal = document.getElementById('partner-order-detail-modal');
            if (modal) modal.classList.add('hidden');
        }

        function printReceiptFromPartnerOrder() {
            if (activePartnerOrder && activePartnerOrder.invoice_number) {
                closePartnerOrderDetailModal();
                openSaleDetailModal(activePartnerOrder.invoice_number);
            }
        }

        function exportPartnerSalesExcel() {
            const curUser = state.currentUser || state.loggedInUser || {};
            const rawRole = ((curUser.role || 'CASHIER') + '').toUpperCase().replace(/_/g, '').trim();
            const isSuperAdmin = (rawRole === 'SUPERADMIN' || rawRole === 'SUPER ADMIN');
            const isManager = isSuperAdmin || rawRole === 'BRANCHMANAGER' || rawRole === 'MANAGER';
            const userBranchId = curUser.branch_id || (state.currentBranch ? state.currentBranch.id : 1);

            const branchSel = document.getElementById('partner-filter-branch');
            let branchId = branchSel ? branchSel.value : 'ALL';
            if (!isSuperAdmin && !isManager) {
                branchId = userBranchId;
            }

            const customerId = _val('partner-filter-customer') || 'ALL';
            const paymentStatus = _val('partner-filter-status') || 'ALL';
            const paymentMethod = _val('partner-filter-method') || 'ALL';

            let url = `api.php?action=export_partner_sales_excel&period_type=${encodeURIComponent(partnerPeriodType)}`;
            if (curUser && curUser.id) url += `&user_id=${encodeURIComponent(curUser.id)}`;
            if (branchId) url += `&branch_id=${encodeURIComponent(branchId)}`;
            if (customerId) url += `&customer_id=${encodeURIComponent(customerId)}`;
            if (paymentStatus) url += `&payment_status=${encodeURIComponent(paymentStatus)}`;
            if (paymentMethod) url += `&payment_method=${encodeURIComponent(paymentMethod)}`;

            if (partnerPeriodType === 'weekly') {
                const preset = _val('partner-control-week-preset') || 'this_week';
                url += `&week_preset=${encodeURIComponent(preset)}`;
            } else if (partnerPeriodType === 'monthly') {
                const m = _val('partner-control-month');
                const y = _val('partner-control-year');
                if (m) url += `&month=${m}`;
                if (y) url += `&year=${y}`;
            } else if (partnerPeriodType === 'quarter') {
                const q = _val('partner-control-quarter');
                const y = _val('partner-control-year');
                if (q) url += `&quarter=${q}`;
                if (y) url += `&year=${y}`;
            } else if (partnerPeriodType === 'semester') {
                const s = _val('partner-control-semester');
                const y = _val('partner-control-year');
                if (s) url += `&semester=${s}`;
                if (y) url += `&year=${y}`;
            } else if (partnerPeriodType === 'yearly') {
                const y = _val('partner-control-year');
                if (y) url += `&year=${y}`;
            } else if (partnerPeriodType === 'custom') {
                const sDate = _val('partner-control-start-date');
                const eDate = _val('partner-control-end-date');
                if (sDate) url += `&start_date=${encodeURIComponent(sDate)}`;
                if (eDate) url += `&end_date=${encodeURIComponent(eDate)}`;
            }

            window.open(url, '_blank');
        }

        // ==========================================
        // 9. MODUL BUKU CATATAN BEBAN OPERASIONAL CABANG & MASTER KATEGORI BEBAN
        // ==========================================
        function setExpenseSubtab(subtab) {
            state.expenseSubtab = subtab;
            const btnLedger = document.getElementById('subtab-btn-exp-ledger');
            const btnCat = document.getElementById('subtab-btn-exp-category');
            const viewLedger = document.getElementById('subtab-exp-ledger');
            const viewCat = document.getElementById('subtab-exp-category');
            const btnAddExp = document.getElementById('exp-btn-add-expense');
            const btnAddCat = document.getElementById('exp-btn-add-category');

            const activeLedgerClass = "px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-rose-600 text-white shadow-2xs";
            const activeCatClass = "px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-indigo-600 text-white shadow-2xs";
            const inactiveClass = "px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-slate-100 hover:bg-slate-200/80 text-slate-700 hover:text-slate-900 dark:bg-slate-800 dark:hover:bg-slate-700 dark:text-slate-300 dark:hover:text-white border border-transparent dark:border-slate-700";

            if (subtab === 'ledger') {
                if (btnLedger) btnLedger.className = activeLedgerClass;
                if (btnCat) btnCat.className = inactiveClass;
                if (viewLedger) viewLedger.classList.remove('hidden');
                if (viewCat) viewCat.classList.add('hidden');
                if (btnAddExp) btnAddExp.classList.remove('hidden');
                if (btnAddCat) btnAddCat.classList.add('hidden');
                loadBranchExpensesTable();
            } else {
                if (btnLedger) btnLedger.className = inactiveClass;
                if (btnCat) btnCat.className = activeCatClass;
                if (viewLedger) viewLedger.classList.add('hidden');
                if (viewCat) viewCat.classList.remove('hidden');
                if (btnAddExp) btnAddExp.classList.add('hidden');
                if (btnAddCat) btnAddCat.classList.remove('hidden');
                loadExpenseCategoriesTable(true);
            }
            lucide.createIcons();
        }

        async function loadBranchExpensesModule() {
            // Set default date jika belum terisi
            const startDateEl = document.getElementById('exp-ledger-start-date');
            const endDateEl = document.getElementById('exp-ledger-end-date');
            if (startDateEl && !startDateEl.value) {
                const now = new Date();
                startDateEl.value = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
            }
            if (endDateEl && !endDateEl.value) {
                endDateEl.value = new Date().toISOString().split('T')[0];
            }

            // Populasi cabang di dropdown filter ledger
            const branchSelect = document.getElementById('exp-ledger-branch-select');
            if (branchSelect) {
                const canAccessAll = canUserAccessAllBranches();
                const userBranch = getUserAssignedBranch();
                if (!canAccessAll) {
                    branchSelect.innerHTML = `<option value="${userBranch.id}" selected>🔒 ${userBranch.name}</option>`;
                    branchSelect.disabled = true;
                    branchSelect.value = userBranch.id;
                } else {
                    branchSelect.disabled = false;
                    const curBId = state.currentBranch ? state.currentBranch.id : '';
                    branchSelect.innerHTML = `<option value="">Semua Cabang Outlet</option>` + (state.branches || []).map(b => `
                        <option value="${b.id}" ${b.id === curBId ? 'selected' : ''}>${b.name}</option>
                    `).join('');
                }
            }

            // Muat kategori beban terlebih dahulu
            await loadExpenseCategoriesTable(false);

            // Muat konten sub-tab aktif
            if (state.expenseSubtab === 'category') {
                renderExpenseCategoriesTable();
            } else {
                await loadBranchExpensesTable();
            }
        }

        function populateExpenseCategoryFilterDropdown() {
            const filterSelect = document.getElementById('exp-ledger-cat-filter');
            if (!filterSelect) return;
            const curVal = filterSelect.value || 'ALL';
            let html = '<option value="ALL">Semua Kategori Beban</option>';
            (state.expenseCategories || []).forEach(cat => {
                html += `<option value="${cat.name}">${cat.name}</option>`;
            });
            filterSelect.innerHTML = html;
            filterSelect.value = curVal;
        }

        async function loadBranchExpensesTable() {
            try {
                const branchSelect = document.getElementById('exp-ledger-branch-select');
                const bId = branchSelect ? branchSelect.value : (state.currentBranch ? state.currentBranch.id : '');
                const sDate = _val('exp-ledger-start-date') || '';
                const eDate = _val('exp-ledger-end-date') || '';
                const catFilter = _val('exp-ledger-cat-filter') || 'ALL';

                let url = `api.php?action=get_branch_expenses&category=${encodeURIComponent(catFilter)}`;
                if (bId) url += `&branch_id=${bId}`;
                if (sDate) url += `&start_date=${sDate}`;
                if (eDate) url += `&end_date=${eDate}`;

                const res = await fetch(url);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const expenses = data.expenses || [];
                const tbody = document.getElementById('branch-expenses-table-body');
                const totalBadge = document.getElementById('exp-ledger-total-badge');
                const kpiTotal = document.getElementById('exp-kpi-total-amount');
                const kpiCount = document.getElementById('exp-kpi-total-count');
                const kpiBranch = document.getElementById('exp-kpi-branch-name');

                const totalFormatted = formatRupiah(data.total_amount || 0);
                if (totalBadge) totalBadge.innerText = totalFormatted;
                if (kpiTotal) kpiTotal.innerText = totalFormatted;
                if (kpiCount) kpiCount.innerText = expenses.length;

                if (kpiBranch) {
                    if (bId) {
                        const br = (state.branches || []).find(b => b.id == bId);
                        kpiBranch.innerText = br ? br.name : `Cabang ID #${bId}`;
                    } else {
                        kpiBranch.innerText = 'Semua Cabang';
                    }
                }

                // Update label dan kontrol tombol Hapus Data Beban Cabang
                updateStoreResetButtonsVisibility();
                const purgeBtnLabel = document.getElementById('exp-btn-purge-label');
                if (canUserResetStoreData() && purgeBtnLabel) {
                    if (bId && bId !== 'ALL') {
                        const br = (state.branches || []).find(b => b.id == bId);
                        purgeBtnLabel.innerText = br ? `Hapus Beban ${br.name}` : `Hapus Beban Cabang`;
                    } else {
                        purgeBtnLabel.innerText = 'Hapus Semua Beban Toko';
                    }
                }

                if (!tbody) return;

                if (expenses.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="7" class="text-center py-10 text-slate-400">Belum ada catatan beban operasional pada kriteria filter ini</td></tr>`;
                    return;
                }

                tbody.innerHTML = expenses.map(function(exp) {
                    var isManual = (exp.source === 'MANUAL');
                    var srcBadge = '<span class="px-2 py-0.5 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 rounded-full font-bold text-[10px]">Manual Input</span>';
                    if (exp.source === 'VEHICLE_FUEL') {
                        srcBadge = '<span class="px-2 py-0.5 bg-amber-100 text-amber-800 rounded-full font-bold text-[10px]">Armada BBM</span>';
                    } else if (exp.source === 'VEHICLE_SERVICE') {
                        srcBadge = '<span class="px-2 py-0.5 bg-rose-100 text-rose-800 rounded-full font-bold text-[10px]">Servis Armada</span>';
                    } else if (exp.source === 'REIMBURSEMENT_ESS') {
                        srcBadge = '<span class="px-2 py-0.5 bg-purple-100 text-purple-800 rounded-full font-bold text-[10px]">ESS Klaim</span>';
                    } else if (exp.source === 'SHIFT_EXPENSE') {
                        srcBadge = '<span class="px-2 py-0.5 bg-sky-100 text-sky-800 rounded-full font-bold text-[10px]">Tutup Shift</span>';
                    }

                    var rawNotes = exp.notes || '-';
                    var noteDisplay = rawNotes;
                    var odoBadge = '';

                    // Deteksi catatan odometer BBM: [Armada: PLAT (NAMA) | KM Odo: 1234 (Sebelumnya: 1200)]
                    var odoRegex = /\[Armada:\s*([^\|\]]+)\s*\|\s*KM Odo:\s*([^\]]+)\]/i;
                    var odoMatch = rawNotes.match(odoRegex);
                    if (odoMatch) {
                        noteDisplay = rawNotes.replace(odoMatch[0], '').trim();
                        var armadaInfo = odoMatch[1].trim();
                        var odoInfo = odoMatch[2].trim();
                        odoBadge = '<div class="mt-1 flex items-center gap-1.5 flex-wrap">' +
                            '<span class="inline-flex items-center space-x-1 px-2 py-0.5 rounded-md text-[10px] font-bold bg-indigo-50 text-indigo-700 border border-indigo-200">' +
                                '<span>🛵 ' + escapeHtml(armadaInfo) + '</span>' +
                            '</span>' +
                            '<span class="inline-flex items-center space-x-1 px-2 py-0.5 rounded-md text-[10px] font-bold bg-amber-50 text-amber-800 border border-amber-200">' +
                                '<span>📍 KM Odo: ' + escapeHtml(odoInfo) + '</span>' +
                            '</span>' +
                        '</div>';
                    }

                    return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">' +
                        '<td class="py-3 px-4 font-mono text-slate-600">' + escapeHtml(exp.expense_date) + '</td>' +
                        '<td class="py-3 px-4 font-bold text-slate-800">' + escapeHtml(exp.category) + '</td>' +
                        '<td class="py-3 px-4 text-slate-600 font-medium">' + escapeHtml(exp.branch_name || 'Cabang') + '</td>' +
                        '<td class="py-3 px-4 text-slate-600 text-[11px] max-w-sm">' +
                            '<div class="font-medium text-slate-700 leading-snug">' + escapeHtml(noteDisplay) + '</div>' +
                            odoBadge +
                        '</td>' +
                        '<td class="py-3 px-4 text-center">' + srcBadge + '</td>' +
                        '<td class="py-3 px-4 text-right font-mono font-black text-rose-700">' + formatRupiah(exp.amount) + '</td>' +
                        '<td class="py-3 px-4 text-center">' +
                            (isManual ? (
                                '<div class="inline-flex items-center space-x-1.5">' +
                                    '<button onclick="editBranchExpense(' + JSON.stringify(exp).replace(/"/g, '&quot;') + ')" title="Edit Beban" class="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-slate-100 rounded-lg transition-colors">' +
                                        '<i data-lucide="edit-3" class="w-4 h-4"></i>' +
                                    '</button>' +
                                    '<button onclick="deleteBranchExpense(' + exp.id + ', \'' + (exp.category ? exp.category.replace(/'/g, "\\'") : '') + '\', ' + exp.amount + ')" title="Hapus Beban" class="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors">' +
                                        '<i data-lucide="trash-2" class="w-4 h-4"></i>' +
                                    '</button>' +
                                '</div>'
                            ) : (
                                '<span class="text-[10px] text-slate-400 italic">Sistem Auto</span>'
                            )) +
                        '</td>' +
                    '</tr>';
                }).join('');

                lucide.createIcons();
            } catch (err) {
                console.error('Gagal memuat daftar beban operasional:', err);
            }
        }

        // ==========================================
        // 9B. CRUD MASTER KATEGORI BEBAN OPERASIONAL
        // ==========================================
        async function loadExpenseCategoriesTable(render = true) {
            try {
                const res = await fetch('api.php?action=get_expense_categories');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                state.expenseCategories = data.expense_categories || [];

                const kpiCatCount = document.getElementById('exp-kpi-categories-count');
                if (kpiCatCount) kpiCatCount.innerText = state.expenseCategories.length;

                populateExpenseCategoryFilterDropdown();
                populateReimburseCategoryDropdown(state.expenseCategories);
                state.discountRules = Array.isArray(data.discount_rules) ? data.discount_rules : (state.discountRules || []);
                if (!state.discountRules || state.discountRules.length === 0) {
                    loadDiscountRules();
                }

                if (render) {
                    renderExpenseCategoriesTable();
                }
            } catch (err) {
                console.error('Gagal memuat kategori beban:', err);
            }
        }

        function renderExpenseCategoriesTable() {
            const tbody = document.getElementById('expense-categories-table-body');
            if (!tbody) return;

            const groupFilter = _val('exp-cat-group-filter') || 'ALL';
            const statusFilter = _val('exp-cat-status-filter') || 'ALL';
            const searchKeyword = (_val('exp-cat-search-input') || '').toLowerCase().trim();

            let filtered = (state.expenseCategories || []).filter(cat => {
                if (groupFilter !== 'ALL' && cat.group_type !== groupFilter) return false;
                if (statusFilter !== 'ALL' && cat.is_active != statusFilter) return false;
                if (searchKeyword) {
                    const matchName = (cat.name || '').toLowerCase().includes(searchKeyword);
                    const matchCode = (cat.code || '').toLowerCase().includes(searchKeyword);
                    const matchDesc = (cat.description || '').toLowerCase().includes(searchKeyword);
                    if (!matchName && !matchCode && !matchDesc) return false;
                }
                return true;
            });

            if (filtered.length === 0) {
                tbody.innerHTML = `<tr><td colspan="8" class="text-center py-10 text-slate-400">Tidak ada kategori beban yang sesuai filter</td></tr>`;
                return;
            }

            const groupBadgeMap = {
                'OPERASIONAL': '<span class="px-2 py-0.5 bg-rose-50 text-rose-700 border border-rose-200 rounded-full font-bold text-[10px]">Operasional Toko</span>',
                'UMUM_ADMIN': '<span class="px-2 py-0.5 bg-indigo-50 text-indigo-700 border border-indigo-200 rounded-full font-bold text-[10px]">Umum & Admin</span>',
                'PENJUALAN': '<span class="px-2 py-0.5 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-full font-bold text-[10px]">Penjualan & Promo</span>',
                'LAINNYA': '<span class="px-2 py-0.5 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 border border-slate-200 rounded-full font-bold text-[10px]">Lain-lain</span>'
            };

            tbody.innerHTML = filtered.map((cat, idx) => {
                const isActive = (cat.is_active == 1);
                const usageCount = parseInt(cat.expense_usage_count || 0);
                const totalUsed = parseFloat(cat.total_amount_used || 0);

                return `
                    <tr class="hover:bg-slate-50 transition-colors ${!isActive ? 'opacity-60 bg-slate-50/50' : ''}">
                        <td class="py-3 px-4 text-center font-bold text-slate-400">${idx + 1}</td>
                        <td class="py-3 px-4 font-mono font-bold text-indigo-700">${cat.code}</td>
                        <td class="py-3 px-4 font-black text-slate-800">${cat.name}</td>
                        <td class="py-3 px-4">${groupBadgeMap[cat.group_type] || cat.group_type}</td>
                        <td class="py-3 px-4 text-slate-500 text-[11px] max-w-xs truncate">${cat.description || '-'}</td>
                        <td class="py-3 px-4 text-center">
                            <button onclick="toggleExpenseCategoryStatus(${cat.id}, ${cat.is_active})" title="Klik untuk ubah status" class="px-2.5 py-1 rounded-full text-[10px] font-black cursor-pointer transition-colors ${isActive ? 'bg-emerald-100 text-emerald-800 hover:bg-emerald-200' : 'bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-300 dark:border-slate-700 hover:bg-slate-300'}">
                                ${isActive ? '✓ Aktif' : '✕ Nonaktif'}
                            </button>
                        </td>
                        <td class="py-3 px-4 text-right">
                            <span class="inline-flex items-center space-x-1 font-mono font-bold ${usageCount > 0 ? 'text-rose-700' : 'text-slate-400'}">
                                <span>${usageCount} Trx</span>
                                <span class="text-[10px]">(${formatRupiah(totalUsed)})</span>
                            </span>
                        </td>
                        <td class="py-3 px-4 text-center">
                            <div class="inline-flex items-center space-x-1.5">
                                <button onclick="editExpenseCategory(${JSON.stringify(cat).replace(/"/g, '&quot;')})" title="Edit Kategori" class="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors">
                                    <i data-lucide="edit-3" class="w-4 h-4"></i>
                                </button>
                                <button onclick="deleteExpenseCategory(${cat.id}, '${cat.name.replace(/'/g, "\\'")}', ${usageCount})" title="${usageCount > 0 ? 'Kategori sedang digunakan transaksi' : 'Hapus Kategori'}" class="p-1.5 ${usageCount > 0 ? 'text-slate-300 cursor-not-allowed' : 'text-slate-400 hover:text-rose-600 hover:bg-rose-50 cursor-pointer'} rounded-lg transition-colors">
                                    <i data-lucide="trash-2" class="w-4 h-4"></i>
                                </button>
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');

            lucide.createIcons();
        }

        function openExpenseCategoryModal(cat = null) {
            const modal = document.getElementById('expense-category-modal');
            const titleEl = document.getElementById('expense-category-modal-title');
            if (!modal) return;

            if (cat) {
                titleEl.innerText = 'Edit Kategori Beban';
                document.getElementById('exp-cat-id').value = cat.id;
                document.getElementById('exp-cat-code').value = cat.code;
                document.getElementById('exp-cat-name').value = cat.name;
                document.getElementById('exp-cat-group').value = cat.group_type || 'OPERASIONAL';
                document.getElementById('exp-cat-desc').value = cat.description || '';
                document.getElementById('exp-cat-is-active').checked = (cat.is_active == 1);
            } else {
                titleEl.innerText = 'Tambah Kategori Beban Baru';
                document.getElementById('exp-cat-id').value = '';
                document.getElementById('exp-cat-code').value = '';
                document.getElementById('exp-cat-name').value = '';
                document.getElementById('exp-cat-group').value = 'OPERASIONAL';
                document.getElementById('exp-cat-desc').value = '';
                document.getElementById('exp-cat-is-active').checked = true;
            }

            modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeExpenseCategoryModal() {
            const modal = document.getElementById('expense-category-modal');
            if (modal) modal.classList.add('hidden');
        }

        function autoGenerateExpenseCategoryCode() {
            const name = _val('exp-cat-name').trim() || '';
            let slug = name.replace(/[^A-Za-z0-9]/g, '').toUpperCase().substring(0, 6);
            if (!slug) slug = 'EXP' + Math.floor(100 + Math.random() * 900);
            else slug = 'EXP-' + slug;
            document.getElementById('exp-cat-code').value = slug;
        }

        async function saveExpenseCategoryForm(e) {
            e.preventDefault();
            const id = document.getElementById('exp-cat-id').value;
            const code = document.getElementById('exp-cat-code').value.trim();
            const name = document.getElementById('exp-cat-name').value.trim();
            const groupType = document.getElementById('exp-cat-group').value;
            const description = document.getElementById('exp-cat-desc').value.trim();
            const isActive = document.getElementById('exp-cat-is-active').checked ? 1 : 0;

            if (!name) {
                alert('Nama kategori beban wajib diisi!');
                return;
            }

            const payload = {
                id: id ? parseInt(id) : null,
                code: code,
                name: name,
                group_type: groupType,
                description: description,
                is_active: isActive
            };

            try {
                const res = await fetch('api.php?action=save_expense_category', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    closeExpenseCategoryModal();
                    await loadExpenseCategoriesTable(true);
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        function editExpenseCategory(cat) {
            openExpenseCategoryModal(cat);
        }

        async function toggleExpenseCategoryStatus(id, currentStatus) {
            try {
                const res = await fetch('api.php?action=toggle_expense_category_status', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: id, is_active: (currentStatus == 1 ? 0 : 1) })
                });
                const data = await res.json();
                if (data.success) {
                    await loadExpenseCategoriesTable(true);
                } else {
                    alert(data.message || data.error);
                }
            } catch (err) {
                console.error(err);
            }
        }

        async function deleteExpenseCategory(id, name, usageCount) {
            if (usageCount > 0) {
                alert(`Kategori '${name}' tidak dapat dihapus karena masih digunakan oleh ${usageCount} transaksi beban operasional.\nSilakan nonaktifkan status kategori sebagai gantinya.`);
                return;
            }

            if (!confirm(`Hapus kategori beban '${name}'?\nOperasi ini tidak dapat dibatalkan.`)) {
                return;
            }

            try {
                const res = await fetch('api.php?action=delete_expense_category', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: id })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    await loadExpenseCategoriesTable(true);
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        // ==========================================
        // 9C. MODAL INPUT & EDIT BEBAN OPERASIONAL
        // ==========================================
        function openBranchExpenseModal(expense = null) {
            const reqMode = expense ? 'update' : 'create';
            if (!hasUserPerm('expenses', reqMode) && !hasUserPerm('expenses:ledger', reqMode)) {
                showToast(`Akses Ditolak: Peran Anda tidak memiliki izin untuk ${expense ? 'mengedit' : 'mencatat'} pengeluaran beban!`, 'error');
                return;
            }
            const modal = document.getElementById('branch-expense-modal');
            const titleEl = document.getElementById('branch-expense-modal-title');
            const branchSelect = document.getElementById('be-branch-id');
            const catSelect = document.getElementById('be-category');
            const customInput = document.getElementById('be-category-custom');

            // Populasi cabang
            const curBranchId = state.currentBranch ? state.currentBranch.id : 1;
            branchSelect.innerHTML = (state.branches || []).map(b => `
                <option value="${b.id}" ${b.id === curBranchId ? 'selected' : ''}>${b.name}</option>
            `).join('');

            // Populasi opsi kategori dari state.expenseCategories yang aktif
            const activeCats = (state.expenseCategories || []).filter(c => c.is_active == 1);
            let catOptionsHtml = activeCats.map(c => `
                <option value="${c.name}">${c.name}</option>
            `).join('');
            catOptionsHtml += `<option value="CUSTOM">Lainnya (Tulis Kategori Kustom...)</option>`;
            catSelect.innerHTML = catOptionsHtml;

            if (expense) {
                titleEl.innerText = 'Edit Beban Operasional Cabang';
                document.getElementById('be-id').value = expense.id;
                branchSelect.value = expense.branch_id;
                document.getElementById('be-amount').value = expense.amount;
                document.getElementById('be-expense-date').value = expense.expense_date;
                document.getElementById('be-notes').value = expense.notes || '';

                const standardOptions = Array.from(catSelect.options).map(o => o.value);
                if (standardOptions.includes(expense.category)) {
                    catSelect.value = expense.category;
                    customInput.classList.add('hidden');
                    customInput.value = '';
                } else {
                    catSelect.value = 'CUSTOM';
                    customInput.classList.remove('hidden');
                    customInput.value = expense.category;
                }
            } else {
                titleEl.innerText = 'Catat Beban Operasional Cabang';
                document.getElementById('be-id').value = '';
                document.getElementById('be-amount').value = '';
                document.getElementById('be-expense-date').value = new Date().toISOString().split('T')[0];
                document.getElementById('be-notes').value = '';
                if (activeCats.length > 0) {
                    catSelect.value = activeCats[0].name;
                }
                customInput.classList.add('hidden');
                customInput.value = '';
            }

            modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeBranchExpenseModal() {
            document.getElementById('branch-expense-modal').classList.add('hidden');
        }

        function onBeCategoryChange() {
            const catSelect = document.getElementById('be-category');
            const customInput = document.getElementById('be-category-custom');
            if (catSelect.value === 'CUSTOM') {
                customInput.classList.remove('hidden');
                customInput.focus();
            } else {
                customInput.classList.add('hidden');
                customInput.value = '';
            }
        }

        function editBranchExpense(exp) {
            openBranchExpenseModal(exp);
        }

        async function saveBranchExpenseForm(e) {
            e.preventDefault();
            const id = document.getElementById('be-id').value;
            const branchId = parseInt(document.getElementById('be-branch-id').value) || (state.currentBranch ? state.currentBranch.id : 1);
            const catSelect = document.getElementById('be-category').value;
            const customCat = document.getElementById('be-category-custom').value.trim();
            const category = (catSelect === 'CUSTOM') ? customCat : catSelect;
            const amount = parseFloat(document.getElementById('be-amount').value) || 0;
            const expenseDate = document.getElementById('be-expense-date').value;
            const notes = document.getElementById('be-notes').value.trim();

            if (!category) {
                alert('Tulis nama kategori beban operasional!');
                return;
            }
            if (amount <= 0) {
                alert('Nominal beban harus lebih besar dari 0!');
                return;
            }

            const payload = {
                id: id ? parseInt(id) : null,
                branch_id: branchId,
                category: category,
                amount: amount,
                expense_date: expenseDate,
                notes: notes
            };

            try {
                const res = await fetch('api.php?action=save_branch_expense', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    closeBranchExpenseModal();
                    loadBranchExpensesTable();
                    if (state.currentTab === 'pnl') loadProfitLoss();
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        async function deleteBranchExpense(id, category, amount) {
            if (!hasUserPerm('expenses', 'delete') && !hasUserPerm('expenses:ledger', 'delete')) {
                showToast('Akses Ditolak: Peran Anda tidak memiliki izin untuk menghapus catatan beban operasional!', 'error');
                return;
            }
            if (!confirm(`Hapus catatan beban '${category}' sebesar ${formatRupiah(amount)}?\nPenghapusan ini akan mengembalikan Laba Bersih cabang.`)) {
                return;
            }

            try {
                const res = await fetch('api.php?action=delete_branch_expense', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: id })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    loadBranchExpensesTable();
                    if (state.currentTab === 'pnl') loadProfitLoss();
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        function getEffectiveProductPrice(product, customer = null, category = null) {
            const cust = customer || state.selectedCustomer;
            const cat = category || state.selectedCustomerCategory || (cust ? cust.category : 'REGULER');
            const baseBranchPrice = Number(product.selling_price || 0);

            // Hubungkan kategori pelanggan ke default_tier dari master customer_categories
            const catObj = (state.customerCategories || []).find(c => c.code === cat || c.name === cat || c.id == cat);
            const tier = (catObj && catObj.default_tier) ? catObj.default_tier : cat;

            if (tier === 'MITRA') {
                // Prioritas 1: Jika mitra ini memiliki harga kontrak khusus tersimpan
                if (cust && state.mitraPrices && state.mitraPrices.length > 0) {
                    const custom = state.mitraPrices.find(mp => mp.customer_id == cust.id && mp.product_id == product.id);
                    if (custom && Number(custom.custom_price) > 0) {
                        return { 
                            price: Number(custom.custom_price), 
                            tag: '🤝 Kontrak Khusus', 
                            isContract: true 
                        };
                    }
                }
                // Prioritas 2: Harga Tier Mitra Umum produk
                if (Number(product.mitra_price) > 0) {
                    return { price: Number(product.mitra_price), tag: '🤝 Tier Mitra', isContract: false };
                }
                // Fallback default mengikuti ritel standar
                return { price: baseBranchPrice, tag: '🤝 Tier Mitra', isContract: false };
            }

            if (tier === 'RESELLER') {
                if (Number(product.reseller_price) > 0) {
                    return { price: Number(product.reseller_price), tag: '📦 Reseller', isContract: false };
                }
                return { price: baseBranchPrice, tag: '📦 Reseller', isContract: false };
            }

            if (tier === 'MEMBER') {
                if (Number(product.member_price) > 0) {
                    return { price: Number(product.member_price), tag: '⭐ Member VIP', isContract: false };
                }
                return { price: baseBranchPrice, tag: '⭐ Member VIP', isContract: false };
            }

            // REGULER
            return { price: baseBranchPrice, tag: 'Ritel Standar', isContract: false };
        }

        // Render Dinamis Tombol Pilihan Tier Pelanggan di Halaman Kasir POS
        function renderPosTierButtons() {
            const container = document.getElementById('pos-tier-buttons');
            if (!container) return;

            // Ambil hanya kategori pelanggan yang aktif (is_active == 1)
            const activeCats = (state.customerCategories || []).filter(c => c.is_active == 1);
            const activeCodes = activeCats.map(c => c.code);

            // Jika kategori yang sedang aktif saat ini dinonaktifkan, otomatis fallback ke kategori aktif pertama (atau REGULER)
            if (activeCodes.length > 0 && !activeCodes.includes(state.selectedCustomerCategory)) {
                state.selectedCustomerCategory = activeCodes.includes('REGULER') ? 'REGULER' : activeCodes[0];
                if (state.selectedCustomer && !activeCodes.includes(state.selectedCustomer.category)) {
                    state.selectedCustomer = (state.customers || []).find(c => (c.category || 'REGULER') === state.selectedCustomerCategory) || null;
                }
            }

            const currentCat = state.selectedCustomerCategory || 'REGULER';

            if (activeCats.length === 0) {
                container.innerHTML = `<span class="text-[11px] text-slate-400 italic px-2">Tidak ada kategori aktif</span>`;
                return;
            }

            container.innerHTML = activeCats.map(c => {
                const isSelected = (c.code === currentCat);
                const btnClass = isSelected 
                    ? 'px-2.5 py-1 rounded-lg text-[11px] font-bold bg-indigo-600 text-white shadow-xs transition-all'
                    : 'px-2.5 py-1 rounded-lg text-[11px] font-bold text-slate-600 hover:bg-slate-100 transition-all';
                
                // Label tombol tier
                let label = c.name;
                if (c.code === 'REGULER') label = 'Ritel';
                else if (c.code === 'MEMBER') label = 'Member';
                else if (c.code === 'RESELLER') label = 'Reseller';
                else if (c.code === 'MITRA') label = 'Mitra B2B';

                const emoji = c.icon_emoji ? c.icon_emoji + ' ' : '';
                return `
                    <button type="button" onclick="setPosCustomerCategory('${c.code}')" id="btn-tier-${c.code}" class="${btnClass}">
                        ${emoji}${label}
                    </button>
                `;
            }).join('');
        }

        // ========================================================
        // FITUR PENCARIAN PELANGGAN POS BERBASIS KATA KUNCI (KEYWORD SEARCH)
        // ========================================================

        var _custSearchDebounceTimer = null;
        function onPosCustomerSearchInput(query) {
            const clearBtn = document.getElementById('pos-customer-search-clear');
            if (clearBtn) {
                if (query && query.trim().length > 0) {
                    clearBtn.classList.remove('hidden');
                } else {
                    clearBtn.classList.add('hidden');
                }
            }

            if (_custSearchDebounceTimer) clearTimeout(_custSearchDebounceTimer);
            _custSearchDebounceTimer = setTimeout(function() {
                _executePosCustomerSearch(query);
            }, 120);
        }

        function _executePosCustomerSearch(query) {
            const q = (query || '').trim().toLowerCase();
            const resultsContainer = document.getElementById('pos-customer-search-results');
            if (!resultsContainer) return;

            // Jika kata kunci kosong, sembunyikan dropdown hasil pencarian
            if (q.length === 0) {
                resultsContainer.innerHTML = '';
                resultsContainer.classList.add('hidden');
                return;
            }

            // Ambil kategori tier aktif saat ini
            const activeCat = state.selectedCustomerCategory || 'REGULER';
            const catObj = (state.customerCategories || []).find(c => c.code === activeCat || c.name === activeCat);
            const activeCatName = catObj ? catObj.name : (activeCat === 'REGULER' ? 'Ritel' : activeCat);

            // Filter pelanggan: Aktif + HANYA SESUAI DENGAN TIER YANG SEDANG AKTIF + Cocok Keyword
            const matches = (state.customers || []).filter(c => {
                if (c.is_active != 1 && c.is_active !== undefined) return false;
                const custCat = c.category || 'REGULER';
                if (custCat !== activeCat) return false; // WAJIB SESUAI DENGAN TIER AKTIF!

                const name = (c.name || '').toLowerCase();
                const phone = (c.phone || '').toLowerCase();
                const code = (c.code || '').toLowerCase();
                const address = (c.address || '').toLowerCase();
                return name.includes(q) || phone.includes(q) || code.includes(q) || address.includes(q);
            }).slice(0, 15); // Batasi maksimal 15 hasil pencarian relevan

            if (matches.length === 0) {
                resultsContainer.innerHTML = `
                    <div class="p-3.5 text-center text-xs text-slate-500 dark:text-slate-400">
                        <i data-lucide="search-x" class="w-5 h-5 mx-auto mb-1.5 text-slate-400"></i>
                        <p>Tidak ada pelanggan tier <span class="font-black text-indigo-600 dark:text-indigo-400">${escapeHtml(activeCatName)}</span> dengan kata kunci "<span class="font-bold text-slate-700 dark:text-slate-200">${escapeHtml(query)}</span>"</p>
                        <div class="mt-2.5 pt-2 border-t border-slate-100 dark:border-slate-800 flex items-center justify-center space-x-2">
                            ${activeCat === 'REGULER' ? `
                            <button type="button" onclick="selectPosWalkInCustomer()" class="px-2.5 py-1 text-[11px] font-bold text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg">
                                Pilih Pelanggan Umum
                            </button>` : ''}
                            <button type="button" onclick="closePosCustomerSearch(); openCustomerModal();" class="px-2.5 py-1 text-[11px] font-bold text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-950/50 rounded-lg">
                                + Pelanggan Baru (${escapeHtml(activeCatName)})
                            </button>
                        </div>
                    </div>
                `;
                resultsContainer.classList.remove('hidden');
                if (window.lucide) lucide.createIcons();
                return;
            }

            // Render daftar kartu hasil pencarian kata kunci sesuai tier aktif
            let html = `
                <div class="p-2 bg-slate-50 dark:bg-slate-800/80 border-b border-slate-100 dark:border-slate-700/60 flex items-center justify-between text-[10px] font-bold text-slate-400 uppercase tracking-wider px-3">
                    <span>Hasil Pencarian Tier ${escapeHtml(activeCatName)} (${matches.length})</span>
                    <span>Klik / Tekan Enter</span>
                </div>
                <div class="divide-y divide-slate-100 dark:divide-slate-800/60 overflow-y-auto max-h-60">
            `;

            matches.forEach((c) => {
                const cat = c.category || 'REGULER';
                let badgeColor = 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300';
                if (cat === 'MITRA') badgeColor = 'bg-emerald-100 text-emerald-800 dark:bg-emerald-950/60 dark:text-emerald-300 border border-emerald-300/60';
                else if (cat === 'MEMBER') badgeColor = 'bg-purple-100 text-purple-800 dark:bg-purple-950/60 dark:text-purple-300 border border-purple-300/60';
                else if (cat === 'RESELLER') badgeColor = 'bg-amber-100 text-amber-800 dark:bg-amber-950/60 dark:text-amber-300 border border-amber-300/60';

                const isCurrent = state.selectedCustomer && state.selectedCustomer.id === c.id;
                const phoneText = c.phone && c.phone !== '-' ? `<span class="flex items-center space-x-1 text-slate-400 dark:text-slate-500"><i data-lucide="phone" class="w-3 h-3"></i><span>${escapeHtml(c.phone)}</span></span>` : '';
                const codeText = c.code ? `<span class="text-slate-400 dark:text-slate-500 font-mono text-[10px]">${escapeHtml(c.code)}</span>` : '';

                html += `
                    <div onclick="selectPosCustomer(${c.id})" 
                         class="p-2.5 hover:bg-indigo-50/80 dark:hover:bg-indigo-950/50 cursor-pointer transition-colors flex items-center justify-between gap-2.5 ${isCurrent ? 'bg-indigo-50/50 dark:bg-indigo-950/30' : ''}">
                        <div class="min-w-0 flex-1">
                            <div class="flex items-center space-x-1.5">
                                <span class="font-bold text-xs text-slate-800 dark:text-slate-100 truncate">${escapeHtml(c.name)}</span>
                                ${isCurrent ? '<span class="text-[10px] text-indigo-600 dark:text-indigo-400 font-bold shrink-0">✓ Aktif</span>' : ''}
                            </div>
                            <div class="flex items-center space-x-2 text-[10px] mt-0.5">
                                ${phoneText}
                                ${codeText}
                            </div>
                        </div>
                        <span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold uppercase shrink-0 ${badgeColor}">
                            ${escapeHtml(cat)}
                        </span>
                    </div>
                `;
            });

            html += `</div>`;
            resultsContainer.innerHTML = html;
            resultsContainer.classList.remove('hidden');
            if (window.lucide) lucide.createIcons();
        }

        function onPosCustomerSearchFocus() {
            const input = document.getElementById('pos-customer-search-input');
            if (input) {
                setTimeout(() => input.select(), 50);
            }
        }

        function onPosCustomerSearchKeydown(event) {
            if (event.key === 'Escape') {
                closePosCustomerSearch();
                const input = document.getElementById('pos-customer-search-input');
                if (input && state.selectedCustomer) {
                    input.value = state.selectedCustomer.name;
                }
            } else if (event.key === 'Enter') {
                event.preventDefault();
                const resultsContainer = document.getElementById('pos-customer-search-results');
                if (resultsContainer && !resultsContainer.classList.contains('hidden')) {
                    const firstItem = resultsContainer.querySelector('[onclick^="selectPosCustomer"]');
                    if (firstItem) {
                        firstItem.click();
                    }
                }
            }
        }

        function closePosCustomerSearch() {
            const resultsContainer = document.getElementById('pos-customer-search-results');
            if (resultsContainer) {
                resultsContainer.classList.add('hidden');
                resultsContainer.innerHTML = '';
            }
        }

        function selectPosCustomer(customerId) {
            const cust = (state.customers || []).find(c => c.id == customerId);
            if (!cust) return;

            const prevCustId = state.selectedCustomer ? state.selectedCustomer.id : null;
            const prevCat = state.selectedCustomerCategory;

            state.selectedCustomer = cust;
            state.selectedCustomerCategory = cust.category || 'REGULER';

            const hiddenSelect = document.getElementById('pos-customer-select');
            if (hiddenSelect) hiddenSelect.value = cust.id;

            const searchInput = document.getElementById('pos-customer-search-input');
            if (searchInput) searchInput.value = cust.name;

            const clearBtn = document.getElementById('pos-customer-search-clear');
            if (clearBtn) {
                clearBtn.classList.remove('hidden');
            }

            closePosCustomerSearch();
            updatePosCustomerUI();

            // Jika ganti pelanggan: list order dan fitur delivery direset agar kasir menginput ulang sesuai pelanggan
            if (prevCustId !== cust.id || prevCat !== state.selectedCustomerCategory || (state.cart && state.cart.length > 0)) {
                state.cart = [];
                resetPosDelivery(true);
                renderCart();
            }

            renderProducts();
            if (typeof evaluatePosAutoDiscounts === 'function') evaluatePosAutoDiscounts();
        }

        function selectPosWalkInCustomer() {
            let walkIn = (state.customers || []).find(c => c.id == 1 || (c.name || '').toLowerCase().includes('umum') || (c.name || '').toLowerCase().includes('walk-in'));
            if (!walkIn) {
                walkIn = (state.customers || []).find(c => (c.category || 'REGULER') === 'REGULER') || { id: 1, name: 'Pelanggan Umum (Walk-in)', category: 'REGULER' };
            }
            selectPosCustomer(walkIn.id);
        }

        function clearPosCustomerSearch() {
            state.selectedCustomer = null;
            const hiddenSelect = document.getElementById('pos-customer-select');
            if (hiddenSelect) hiddenSelect.value = '';
            const input = document.getElementById('pos-customer-search-input');
            if (input) {
                input.value = '';
                input.focus();
            }
            const clearBtn = document.getElementById('pos-customer-search-clear');
            if (clearBtn) clearBtn.classList.add('hidden');
            closePosCustomerSearch();
            updatePosCustomerUI();

            // Reset keranjang & ongkir karena pelanggan dikosongkan
            if (state.cart && state.cart.length > 0) {
                state.cart = [];
                resetPosDelivery(true);
                renderCart();
                if (typeof evaluatePosAutoDiscounts === 'function') evaluatePosAutoDiscounts();
            }
            renderProducts();
        }

        function renderPosCustomerSelect() {
            const hiddenSelect = document.getElementById('pos-customer-select');
            const searchInput = document.getElementById('pos-customer-search-input');
            const clearBtn = document.getElementById('pos-customer-search-clear');

            // Ambil daftar kategori aktif
            const activeCats = (state.customerCategories || []).filter(c => c.is_active == 1);
            const activeCodes = activeCats.map(c => c.code);

            // Pastikan kategori tier aktif ada dalam daftar kategori aktif
            if (activeCodes.length > 0 && !activeCodes.includes(state.selectedCustomerCategory)) {
                state.selectedCustomerCategory = activeCodes.includes('REGULER') ? 'REGULER' : activeCodes[0];
            }

            // DEFAULT KOSONG: Jangan otomatis pilih pelanggan jika belum dipilih pengguna
            if (!state.selectedCustomer) {
                if (hiddenSelect) hiddenSelect.value = '';
                if (searchInput && document.activeElement !== searchInput) {
                    searchInput.value = '';
                }
                if (clearBtn) clearBtn.classList.add('hidden');
            } else {
                if (hiddenSelect) hiddenSelect.value = state.selectedCustomer.id;
                if (searchInput && document.activeElement !== searchInput) {
                    searchInput.value = state.selectedCustomer.name;
                }
                if (clearBtn) clearBtn.classList.remove('hidden');
            }

            updatePosCustomerUI();
            if (_chk('check-delivery-mode')) {
                calculateDeliveryFeeForPOS();
            }
        }

        function updatePosCustomerUI() {
            const cust = state.selectedCustomer;
            const cat = state.selectedCustomerCategory || 'REGULER';
            const catObj = (state.customerCategories || []).find(c => c.code === cat || c.name === cat);
            const tier = (catObj && catObj.default_tier) ? catObj.default_tier : cat;
            const catDisplayName = catObj ? catObj.name : (cat === 'REGULER' ? 'Ritel' : cat);

            const badge = document.getElementById('pos-customer-category-badge');
            const desc = document.getElementById('pos-customer-tier-desc');

            if (badge) {
                if (!cust) {
                    badge.innerText = `(Belum Dipilih - Tier ${catDisplayName})`;
                    badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800 border border-amber-300 dark:bg-amber-950/60 dark:text-amber-300';
                    if (desc) desc.innerText = `• Silakan pilih pelanggan terlebih dahulu untuk transaksi`;
                } else {
                    badge.innerText = catDisplayName;
                    if (tier === 'MITRA') {
                        badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-emerald-100 text-emerald-800 border border-emerald-300';
                        if (desc) desc.innerText = `• Mitra Rekanan: ${cust.name} (Tier Mitra / Kontrak)`;
                    } else if (tier === 'MEMBER') {
                        badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-purple-100 text-purple-800 border border-purple-300';
                        if (desc) desc.innerText = `• Diskon Member VIP (${catDisplayName})`;
                    } else if (tier === 'RESELLER') {
                        badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-amber-100 text-amber-800 border border-amber-300';
                        if (desc) desc.innerText = `• Harga Reseller / Grosir (${catDisplayName})`;
                    } else {
                        badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-slate-200 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-300 dark:border-slate-700';
                        if (desc) desc.innerText = `• Harga Ritel Standar (${catDisplayName})`;
                    }
                }
            }

            // Sinkronisasi status tombol tier dinamis
            renderPosTierButtons();
        }

        function onPosCustomerChange() {
            const select = document.getElementById('pos-customer-select');
            if (!select || !select.value) return;
            selectPosCustomer(select.value);
        }

        function setPosCustomerCategory(cat) {
            // Validasi apakah kategori ini aktif
            const activeCats = (state.customerCategories || []).filter(c => c.is_active == 1);
            const isCatActive = activeCats.some(c => c.code === cat);
            if (!isCatActive && activeCats.length > 0) {
                alert(`Kategori '${cat}' saat ini sedang dinonaktifkan dan tidak dapat digunakan di menu penjualan.`);
                return;
            }

            const prevCustId = state.selectedCustomer ? state.selectedCustomer.id : null;
            const prevCat = state.selectedCustomerCategory;

            state.selectedCustomerCategory = cat;

            // Jika pelanggan aktif saat ini bukan dari kategori yang dipilih, kosongkan pelanggan (default kosong)
            if (state.selectedCustomer && (state.selectedCustomer.category || 'REGULER') !== cat) {
                state.selectedCustomer = null;
                const searchInput = document.getElementById('pos-customer-search-input');
                if (searchInput) searchInput.value = '';
                const clearBtn = document.getElementById('pos-customer-search-clear');
                if (clearBtn) clearBtn.classList.add('hidden');
            }

            renderPosTierButtons();
            renderPosCustomerSelect();

            // Jika ganti kategori/pelanggan: list order dan fitur delivery dihilangkan agar kasir menginput ulang
            const isCustChanged = (prevCustId !== (state.selectedCustomer ? state.selectedCustomer.id : null)) || (prevCat !== cat);
            if (isCustChanged && state.cart && state.cart.length > 0) {
                state.cart = [];
                resetPosDelivery(true);
                renderCart();
            }

            renderProducts();
        }

        // ========================================================
        // MODAL PEMILIH PELANGGAN POS (PROMPT SEBELUM INPUT PRODUK)
        // ========================================================

        function openSelectCustomerModal(pendingProductId = null, pendingVariantId = null) {
            state.pendingCartProduct = pendingProductId ? { productId: pendingProductId, variantId: pendingVariantId } : null;

            const modal = document.getElementById('pos-select-customer-modal');
            if (!modal) return;

            // Reset input pencarian modal
            const searchInput = document.getElementById('pos-modal-cust-search-input');
            if (searchInput) searchInput.value = '';
            const clearBtn = document.getElementById('pos-modal-cust-search-clear');
            if (clearBtn) clearBtn.classList.add('hidden');

            // Render tombol tier di modal
            renderPosModalTierButtons();

            // Render daftar pelanggan sesuai tier aktif
            renderPosModalCustomerList('');

            modal.classList.remove('hidden');
            if (window.lucide) lucide.createIcons();
            setTimeout(() => {
                if (searchInput) searchInput.focus();
            }, 100);
        }

        function closeSelectCustomerModal() {
            const modal = document.getElementById('pos-select-customer-modal');
            if (modal) modal.classList.add('hidden');
            state.pendingCartProduct = null;
        }

        function renderPosModalTierButtons() {
            const container = document.getElementById('pos-modal-tier-buttons');
            const labelEl = document.getElementById('pos-modal-active-tier-label');
            if (!container) return;

            const activeCats = (state.customerCategories || []).filter(c => c.is_active == 1);
            const currentCat = state.selectedCustomerCategory || 'REGULER';
            const currentCatObj = activeCats.find(c => c.code === currentCat);
            if (labelEl) labelEl.innerText = currentCatObj ? currentCatObj.name : currentCat;

            container.innerHTML = activeCats.map(c => {
                const isSelected = (c.code === currentCat);
                const btnClass = isSelected
                    ? 'px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white shadow-xs transition-all'
                    : 'px-3 py-1.5 rounded-xl text-xs font-bold text-slate-600 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 transition-all cursor-pointer';

                let label = c.name;
                if (c.code === 'REGULER') label = 'Ritel';
                else if (c.code === 'MEMBER') label = 'Member / Premium';
                else if (c.code === 'RESELLER') label = 'Reseller';
                else if (c.code === 'MITRA') label = 'Mitra B2B';

                const emoji = c.icon_emoji ? c.icon_emoji + ' ' : '';
                return `
                    <button type="button" onclick="setPosModalTier('${c.code}')" class="${btnClass}">
                        ${emoji}${label}
                    </button>
                `;
            }).join('');
        }

        function setPosModalTier(cat) {
            state.selectedCustomerCategory = cat;
            renderPosTierButtons();
            renderPosModalTierButtons();
            renderPosCustomerSelect();
            const query = _val('pos-modal-cust-search-input') || '';
            renderPosModalCustomerList(query);
            renderProducts();
        }

        function onPosModalCustSearchInput(val) {
            const clearBtn = document.getElementById('pos-modal-cust-search-clear');
            if (clearBtn) {
                if (val && val.trim().length > 0) clearBtn.classList.remove('hidden');
                else clearBtn.classList.add('hidden');
            }
            renderPosModalCustomerList(val);
        }

        function clearPosModalCustSearch() {
            const input = document.getElementById('pos-modal-cust-search-input');
            if (input) {
                input.value = '';
                input.focus();
            }
            const clearBtn = document.getElementById('pos-modal-cust-search-clear');
            if (clearBtn) clearBtn.classList.add('hidden');
            renderPosModalCustomerList('');
        }

        function renderPosModalCustomerList(query = '') {
            const listEl = document.getElementById('pos-modal-customers-list');
            const countEl = document.getElementById('pos-modal-list-count');
            const walkInCard = document.getElementById('pos-modal-walkin-card');
            if (!listEl) return;

            const activeCat = state.selectedCustomerCategory || 'REGULER';
            if (walkInCard) {
                if (activeCat === 'REGULER' && !query.trim()) {
                    walkInCard.classList.remove('hidden');
                } else {
                    walkInCard.classList.add('hidden');
                }
            }

            const q = (query || '').trim().toLowerCase();
            const branch = state.currentBranch;
            const branchLat = branch ? parseFloat(branch.latitude) : null;
            const branchLon = branch ? parseFloat(branch.longitude) : null;

            // Filter pelanggan: aktif + tier sesuai + keyword
            const filtered = (state.customers || []).filter(c => {
                if (c.is_active != 1 && c.is_active !== undefined) return false;
                const custCat = c.category || 'REGULER';
                if (custCat !== activeCat) return false;

                // Jangan tampilkan ID 1 (Walk-in) di daftar bawah jika sudah ada kartu walk-in di atas
                if (c.id == 1 && activeCat === 'REGULER') return false;

                if (!q) return true;
                const name = (c.name || '').toLowerCase();
                const phone = (c.phone || '').toLowerCase();
                const code = (c.code || '').toLowerCase();
                const address = (c.address || '').toLowerCase();
                return name.includes(q) || phone.includes(q) || code.includes(q) || address.includes(q);
            });

            if (countEl) {
                countEl.innerText = `${filtered.length} Pelanggan`;
            }

            if (filtered.length === 0) {
                listEl.innerHTML = `
                    <div class="p-6 text-center text-xs text-slate-400">
                        <i data-lucide="user-x" class="w-8 h-8 mx-auto mb-2 text-slate-300 dark:text-slate-600"></i>
                        <p class="font-bold text-slate-600 dark:text-slate-300">Tidak ada pelanggan tier ${escapeHtml(activeCat)}</p>
                        <p class="text-[11px] mt-1 text-slate-400">${q ? `Tidak cocok dengan kata kunci "${escapeHtml(query)}"` : 'Belum ada data pelanggan di kategori tier ini.'}</p>
                    </div>
                `;
                if (window.lucide) lucide.createIcons();
                return;
            }

            listEl.innerHTML = filtered.map(c => {
                // Hitung estimasi jarak jika ada koordinat
                let distText = '';
                const cLat = parseFloat(c.latitude);
                const cLon = parseFloat(c.longitude);
                if (branchLat && branchLon && cLat && cLon && !isNaN(cLat) && !isNaN(cLon) && !(cLat === 0 && cLon === 0)) {
                    const dist = getHaversineDistanceKm(branchLat, branchLon, cLat, cLon);
                    distText = `<span class="inline-flex items-center space-x-1 px-1.5 py-0.5 rounded text-[10px] font-bold bg-indigo-50 dark:bg-indigo-950/60 text-indigo-700 dark:text-indigo-300 border border-indigo-200/80"><i data-lucide="map-pin" class="w-3 h-3"></i><span>${formatDecimal(dist)} km</span></span>`;
                }

                const phoneText = c.phone && c.phone !== '-' ? `<span class="flex items-center space-x-1 text-slate-400"><i data-lucide="phone" class="w-3 h-3"></i><span>${escapeHtml(c.phone)}</span></span>` : '';
                const addrText = c.address ? `<span class="truncate max-w-[200px] text-slate-400"><i data-lucide="home" class="w-3 h-3 inline mr-1"></i>${escapeHtml(c.address)}</span>` : '';

                return `
                    <div onclick="selectCustomerFromModal(${c.id})"
                         class="p-3 hover:bg-indigo-50/70 dark:hover:bg-indigo-950/40 cursor-pointer transition-all flex items-center justify-between gap-3 group">
                        <div class="min-w-0 flex-1">
                            <div class="flex items-center space-x-2">
                                <h4 class="font-bold text-xs text-slate-800 dark:text-slate-100 group-hover:text-indigo-600 dark:group-hover:text-indigo-400 truncate">${escapeHtml(c.name)}</h4>
                                ${distText}
                            </div>
                            <div class="flex items-center space-x-3 text-[10px] mt-1 text-slate-500">
                                ${phoneText}
                                ${addrText}
                            </div>
                        </div>
                        <button type="button" class="px-2.5 py-1 rounded-xl text-[10px] font-bold bg-slate-100 dark:bg-slate-800 group-hover:bg-indigo-600 group-hover:text-white text-slate-700 dark:text-slate-200 transition-colors shrink-0">
                            Pilih
                        </button>
                    </div>
                `;
            }).join('');

            if (window.lucide) lucide.createIcons();
        }

        function selectCustomerFromModal(customerId) {
            closeSelectCustomerModal();
            selectPosCustomer(customerId);

            // Jika ada produk yang sebelumnya diklik saat pelanggan belum dipilih, lanjutkan transaksi!
            if (state.pendingCartProduct) {
                const pending = state.pendingCartProduct;
                state.pendingCartProduct = null;
                if (pending.productId) {
                    if (pending.variantId) {
                        addToCart(pending.productId, pending.variantId);
                    } else {
                        onProductClick(pending.productId);
                    }
                }
            }
        }

        function recalculateCartPrices() {
            if (!state.cart || state.cart.length === 0) return;

            state.cart = state.cart.map(item => {
                const prod = state.products.find(p => p.id === item.product_id);
                if (!prod) return item;
                const priceInfo = getEffectiveProductPrice(prod);
                return {
                    ...item,
                    price: priceInfo.price,
                    price_tag: priceInfo.tag
                };
            });
            renderCart();
        }

        // Subtab Navigation inside Tab 9
        function setCustomerSubtab(subtab) {
            state.customerActiveSubtab = subtab;
            const subtabs = [
                { key: 'list', elId: 'subview-cust-list', btnId: 'subtab-btn-cust-list' },
                { key: 'mitra-pricing', elId: 'subview-cust-mitra', btnId: 'subtab-btn-cust-mitra' },
                { key: 'branch-pricing', elId: 'subview-cust-branch', btnId: 'subtab-btn-cust-branch' },
                { key: 'category', elId: 'subview-cust-category', btnId: 'subtab-btn-cust-category' },
                { key: 'maps', elId: 'subview-cust-maps', btnId: 'subtab-btn-cust-maps' }
            ];

            const activeClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-indigo-600 text-white shadow-2xs';
            const inactiveClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-slate-100 hover:bg-slate-200/80 text-slate-700 hover:text-slate-900 dark:bg-slate-800 dark:hover:bg-slate-700 dark:text-slate-300 dark:hover:text-white border border-transparent dark:border-slate-700';

            subtabs.forEach(item => {
                const el = document.getElementById(item.elId);
                const btn = document.getElementById(item.btnId);
                if (item.key === subtab) {
                    if (el) el.classList.remove('hidden');
                    if (btn) btn.className = activeClass;
                } else {
                    if (el) el.classList.add('hidden');
                    if (btn) btn.className = inactiveClass;
                }
            });

            if (subtab === 'maps') {
                setTimeout(() => {
                    initCustomerMap();
                }, 150);
            }

            if (subtab === 'list') loadCustomers();
            if (subtab === 'mitra-pricing') loadMitraPricing();
            if (subtab === 'branch-pricing') loadBranchPricing();
            if (subtab === 'category') loadCustomerCategories();
                        lucide.createIcons();
        }

        // SUBTAB 1: CUSTOMERS CRUD
        async function loadCustomers() {
            try {
                const cat = state.custCategoryFilter || 'ALL';
                const kw = encodeURIComponent(state.custSearchKeyword || '');
                const res = await fetch(`api.php?action=get_customers&category=${cat}&keyword=${kw}`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const custs = data.customers || [];
                state.customers = custs;

                // Update KPI Cards
                document.getElementById('cust-kpi-total').innerText = custs.length;
                document.getElementById('cust-kpi-member').innerText = custs.filter(c => c.category === 'MEMBER').length;
                document.getElementById('cust-kpi-reseller').innerText = custs.filter(c => c.category === 'RESELLER').length;
                document.getElementById('cust-kpi-mitra').innerText = custs.filter(c => c.category === 'MITRA').length;

                const tbody = document.getElementById('customers-table-body');
                if (custs.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="8" class="text-center py-8 text-slate-400">Tidak ada data pelanggan ditemukan</td></tr>`;
                    return;
                }

                tbody.innerHTML = custs.map(c => {
                    const catBadge = c.category === 'MITRA' ? '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-800">🤝 Mitra B2B</span>' :
                                    (c.category === 'MEMBER' ? '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-purple-100 dark:bg-purple-950/80 text-purple-800 dark:text-purple-300 border border-purple-300 dark:border-purple-800">⭐ Member VIP</span>' :
                                    (c.category === 'RESELLER' ? '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 dark:bg-amber-950/80 text-amber-800 dark:text-amber-300 border border-amber-300 dark:border-amber-800">📦 Reseller</span>' :
                                    '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">Ritel Reguler</span>'));

                    return `
                        <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                            <td class="py-3 px-4 font-mono font-bold text-slate-600 dark:text-slate-400">${c.code}</td>
                            <td class="py-3 px-4 font-bold text-slate-900 dark:text-slate-100">${c.name}</td>
                            <td class="py-3 px-4">${catBadge}</td>
                            <td class="py-3 px-4 text-slate-600 dark:text-slate-300">${c.phone || '-'} <br><span class="text-[10px] text-slate-400 dark:text-slate-400">${c.email || ''}</span></td>
                            <td class="py-3 px-4 text-slate-600 dark:text-slate-300">${c.branch_name || 'Semua Cabang'}</td>
                            <td class="py-3 px-4 font-bold text-indigo-700 dark:text-indigo-400">${c.discount_percent > 0 ? c.discount_percent + '%' : '-'}</td>
                            <td class="py-3 px-4 text-slate-500 dark:text-slate-400 max-w-[180px] truncate">${c.notes || '-'}</td>
                            <td class="py-3 px-4 text-center">
                                <div class="flex items-center justify-center space-x-1.5">
                                    ${c.category === 'MITRA' ? `
                                        <button onclick="switchDirectToMitraContract(${c.id})" title="Kelola Harga Kontrak Mitra Ini" class="px-2 py-1 text-[11px] font-bold text-emerald-700 dark:text-emerald-300 bg-emerald-50 dark:bg-emerald-950/60 hover:bg-emerald-600 dark:hover:bg-emerald-900/60 hover:text-white rounded-lg border border-emerald-200 dark:border-emerald-800 transition-colors flex items-center space-x-1 shadow-2xs">
                                            <i data-lucide="file-signature" class="w-3.5 h-3.5"></i>
                                            <span>Set Kontrak</span>
                                        </button>
                                    ` : ''}
                                    <button onclick="focusCustomerOnMap(${c.id})" title="Lihat Titik di Peta Maps" class="p-1.5 text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 hover:bg-indigo-50 dark:hover:bg-indigo-950/60 rounded-lg transition-colors">
                                        <i data-lucide="map-pin" class="w-4 h-4"></i>
                                    </button>
                                    <button onclick="editCustomer(${c.id})" title="Edit Pelanggan" class="p-1.5 text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors">
                                        <i data-lucide="edit-3" class="w-4 h-4"></i>
                                    </button>
                                    ${c.id !== 1 ? `
                                        <button onclick="deleteCustomer(${c.id})" title="Hapus Pelanggan" class="p-1.5 text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/60 rounded-lg transition-colors">
                                            <i data-lucide="trash-2" class="w-4 h-4"></i>
                                        </button>
                                    ` : ''}
                                </div>
                            </td>
                        </tr>
                    `;
                }).join('');

                if (state.customerActiveSubtab === 'maps' && state.customerMap) {
                    populateCustomerMapSelections();
                    renderCustomerMapMarkers();
                }

                renderPosCustomerSelect();
                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function setCustCategoryFilter(cat) {
            state.custCategoryFilter = cat;
            document.querySelectorAll('.cust-cat-pill').forEach(btn => {
                if ((cat === 'ALL' && btn.innerText === 'Semua') || btn.innerText.toLowerCase().includes(cat.toLowerCase())) {
                    btn.className = 'cust-cat-pill px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white';
                } else {
                    btn.className = 'cust-cat-pill px-3 py-1.5 rounded-xl text-xs font-semibold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-200';
                }
            });
            loadCustomers();
        }

        function filterCustomerList() {
            state.custSearchKeyword = document.getElementById('cust-search-keyword').value;
            loadCustomers();
        }

        function updateCustPickerBadge(lat, lon) {
            const badge = document.getElementById('cust-picker-coords-text');
            const gmapsLink = document.getElementById('cust-modal-gmaps-link');
            const nLat = parseFloat(lat);
            const nLon = parseFloat(lon);
            if (badge) {
                if (!isNaN(nLat) && !isNaN(nLon)) {
                    badge.innerText = `${nLat.toFixed(6)}, ${nLon.toFixed(6)}`;
                } else {
                    badge.innerText = '-';
                }
            }
            if (gmapsLink && !isNaN(nLat) && !isNaN(nLon)) {
                gmapsLink.href = `https://www.google.com/maps?q=${nLat.toFixed(6)},${nLon.toFixed(6)}`;
            }
        }

        function toggleCustSearchClearBtn() {
            const input = document.getElementById('cust-modal-search-input');
            const clearBtn = document.getElementById('cust-modal-search-clear-btn');
            if (input && clearBtn) {
                if (input.value.trim().length > 0) {
                    clearBtn.classList.remove('hidden');
                } else {
                    clearBtn.classList.add('hidden');
                }
            }
        }

        function clearCustAddressSearch() {
            const input = document.getElementById('cust-modal-search-input');
            if (input) input.value = '';
            toggleCustSearchClearBtn();
            const statusEl = document.getElementById('cust-modal-search-status');
            if (statusEl) {
                statusEl.innerHTML = '';
                statusEl.classList.add('hidden');
            }
        }

        function copyCustAddressToSearch() {
            const address = _val('cust-address').trim() || '';
            const name = _val('cust-name').trim() || '';
            const query = address || name;
            if (!query) {
                alert('Silakan ketik Nama Pelanggan atau Alamat Lengkap terlebih dahulu pada formulir di sebelah kiri.');
                return;
            }
            const input = document.getElementById('cust-modal-search-input');
            if (input) {
                input.value = query;
                toggleCustSearchClearBtn();
                searchCustAddressOnMap();
            }
        }

        function applyCustFoundCoords(lat, lon, label) {
            const latVal = Number(lat).toFixed(6);
            const lonVal = Number(lon).toFixed(6);
            document.getElementById('cust-latitude').value = latVal;
            document.getElementById('cust-longitude').value = lonVal;
            updateCustPickerFromInputs();
            if (state.customerPickerMap) {
                state.customerPickerMap.setView([lat, lon], 16);
            }
            const statusEl = document.getElementById('cust-modal-search-status');
            if (statusEl) {
                statusEl.innerHTML = `<div class="p-2 bg-emerald-50 border border-emerald-200/80 rounded-lg text-emerald-800 text-[11px] flex items-start space-x-1.5"><i data-lucide="check-circle-2" class="w-3.5 h-3.5 text-emerald-600 shrink-0 mt-0.5"></i><div class="min-w-0 flex-1"><span class="font-bold">Lokasi Ditemukan (${latVal}, ${lonVal}):</span><p class="text-[10px] text-slate-600 truncate">${escapeHtml(label)}</p></div><a href="https://www.google.com/maps?q=${latVal},${lonVal}" target="_blank" rel="noopener noreferrer" class="text-indigo-600 hover:text-indigo-800 font-bold underline shrink-0 text-[10px]">Google Maps</a></div>`;
                statusEl.classList.remove('hidden');
                if (window.lucide) lucide.createIcons();
            }
        }

        async function searchCustAddressOnMap() {
            const input = document.getElementById('cust-modal-search-input');
            let query = (input && input.value ? input.value.trim() : '') || '';
            if (!query) {
                query = _val('cust-address').trim() || '';
                if (query && input) {
                    input.value = query;
                    toggleCustSearchClearBtn();
                }
            }
            if (!query) {
                alert('Silakan masukkan alamat pelanggan, nama tempat, atau link / koordinat Google Maps.');
                if (input) input.focus();
                return;
            }

            const searchBtn = document.getElementById('cust-modal-search-btn');
            const statusEl = document.getElementById('cust-modal-search-status');
            const originalBtnHtml = searchBtn ? searchBtn.innerHTML : '';

            if (searchBtn) {
                searchBtn.disabled = true;
                searchBtn.innerHTML = '<span class="inline-block animate-spin mr-1">⏳</span><span>Mencari...</span>';
            }
            if (statusEl) {
                statusEl.innerHTML = '<span class="text-slate-500 italic flex items-center space-x-1"><span class="animate-spin inline-block">⏳</span><span>Menghubungkan & mencari lokasi alamat di peta...</span></span>';
                statusEl.classList.remove('hidden');
            }

            const finishSearch = () => {
                if (searchBtn) {
                    searchBtn.disabled = false;
                    searchBtn.innerHTML = originalBtnHtml;
                    if (window.lucide) lucide.createIcons();
                }
            };

            // 1. Cek apakah input berupa koordinat langsung atau URL Google Maps
            const coordRegex = /([-+]?\d{1,2}\.\d+)[,\s]+([-+]?\d{1,3}\.\d+)/;
            const match = query.match(coordRegex);
            if (match) {
                const lat = parseFloat(match[1]);
                const lon = parseFloat(match[2]);
                if (!isNaN(lat) && !isNaN(lon) && lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180) {
                    applyCustFoundCoords(lat, lon, `Koordinat Google Maps Terdeteksi: ${lat.toFixed(6)}, ${lon.toFixed(6)}`);
                    finishSearch();
                    return;
                }
            }

            // 2. Geocoding via OpenStreetMap Nominatim API
            try {
                const encodedQuery = encodeURIComponent(query);
                const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodedQuery}&addressdetails=1&limit=1`;
                const resp = await fetch(url, { headers: { 'Accept-Language': 'id,en' } });
                const data = await resp.json();

                if (Array.isArray(data) && data.length > 0) {
                    const lat = parseFloat(data[0].lat);
                    const lon = parseFloat(data[0].lon);
                    applyCustFoundCoords(lat, lon, data[0].display_name);
                } else {
                    let fallbackFound = false;
                    const commaParts = query.split(',').map(s => s.trim()).filter(Boolean);
                    if (commaParts.length > 1) {
                        const broaderQuery = commaParts.slice(1).join(', ');
                        const resp2 = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(broaderQuery)}&addressdetails=1&limit=1`, { headers: { 'Accept-Language': 'id,en' } });
                        const data2 = await resp2.json();
                        if (Array.isArray(data2) && data2.length > 0) {
                            fallbackFound = true;
                            const lat = parseFloat(data2[0].lat);
                            const lon = parseFloat(data2[0].lon);
                            applyCustFoundCoords(lat, lon, `${data2[0].display_name} (Wilayah Terdekat)`);
                        }
                    }

                    if (!fallbackFound) {
                        const gmapsSearchUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
                        if (statusEl) {
                            statusEl.innerHTML = `<div class="p-2 bg-amber-50 border border-amber-200 rounded-lg text-amber-800 text-[11px] flex items-start space-x-1.5"><i data-lucide="alert-triangle" class="w-3.5 h-3.5 text-amber-600 shrink-0 mt-0.5"></i><div class="min-w-0 flex-1"><span>Alamat tidak ditemukan otomatis.</span> <a href="${gmapsSearchUrl}" target="_blank" rel="noopener noreferrer" class="font-bold underline text-indigo-700 hover:text-indigo-900 inline-flex items-center space-x-1 ml-1"><span>Cari di Google Maps</span><i data-lucide="external-link" class="w-3 h-3 inline"></i></a><p class="text-[10px] text-slate-500 mt-0.5">Anda bisa salin link atau koordinat dari Google Maps dan tempel di sini.</p></div></div>`;
                            if (window.lucide) lucide.createIcons();
                        }
                    }
                }
            } catch (err) {
                const gmapsSearchUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
                if (statusEl) {
                    statusEl.innerHTML = `<div class="p-2 bg-rose-50 border border-rose-200 rounded-lg text-rose-800 text-[11px] flex items-start space-x-1.5"><i data-lucide="wifi-off" class="w-3.5 h-3.5 text-rose-600 shrink-0 mt-0.5"></i><div class="min-w-0 flex-1"><span>Koneksi pencarian alamat gagal.</span> <a href="${gmapsSearchUrl}" target="_blank" rel="noopener noreferrer" class="font-bold underline text-indigo-700 hover:text-indigo-900 inline-flex items-center space-x-1 ml-1"><span>Buka Langsung di Google Maps</span><i data-lucide="external-link" class="w-3 h-3 inline"></i></a></div></div>`;
                    if (window.lucide) lucide.createIcons();
                }
            } finally {
                finishSearch();
            }
        }

        function onCustBranchChangeInModal() {
            const bId = _val('cust-branch');
            const b = (state.branches || []).find(x => x.id == bId);
            if (b && (!_val('cust-latitude') || !_val('cust-id'))) {
                const bLat = parseFloat(b.latitude);
                const bLon = parseFloat(b.longitude);
                if (!isNaN(bLat) && !isNaN(bLon)) {
                    document.getElementById('cust-latitude').value = bLat.toFixed(6);
                    document.getElementById('cust-longitude').value = bLon.toFixed(6);
                    updateCustPickerBadge(bLat, bLon);
                    if (state.customerPickerMap) {
                        state.customerPickerMap.setView([bLat, bLon], 14);
                        if (state.customerPickerMarker) state.customerPickerMarker.setLatLng([bLat, bLon]);
                    }
                }
            }
        }

        function resetCustPickerToBranch() {
            const bId = _val('cust-branch');
            const b = (state.branches || []).find(x => x.id == bId) || state.currentBranch || (state.branches || [])[0];
            if (b) {
                const bLat = parseFloat(b.latitude) || -6.879400;
                const bLon = parseFloat(b.longitude) || 107.530000;
                document.getElementById('cust-latitude').value = bLat.toFixed(6);
                document.getElementById('cust-longitude').value = bLon.toFixed(6);
                updateCustPickerBadge(bLat, bLon);
                if (state.customerPickerMap) {
                    state.customerPickerMap.setView([bLat, bLon], 14);
                    if (state.customerPickerMarker) state.customerPickerMarker.setLatLng([bLat, bLon]);
                }
            }
        }

        function openCustomerModal(cust = null) {
            const reqMode = cust ? 'update' : 'create';
            // Izinkan pendaftaran pelanggan baru bagi staf/kasir yang memiliki akses POS atau izin create pelanggan
            const canCreateCustomer = (!cust && (hasUserPerm('customers', 'create') || hasUserPerm('customers:list', 'create') || hasUserPerm('pos', 'view') || hasUserPerm('pos', 'create')));
            if (!canCreateCustomer && !hasUserPerm('customers', reqMode) && !hasUserPerm('customers:list', reqMode)) {
                showToast(`Akses Ditolak: Peran Anda tidak memiliki izin untuk ${cust ? 'mengedit' : 'menambah'} data pelanggan!`, 'error');
                return;
            }
            const modal = document.getElementById('customer-modal');
            const title = document.getElementById('cust-modal-title');
            const branchSelect = document.getElementById('cust-branch');

            // Populate branch options
            const canAccessAll = canUserAccessAllBranches();
            const userBranch = getUserAssignedBranch();
            if (!canAccessAll) {
                branchSelect.innerHTML = `<option value="${userBranch.id}" selected>🔒 ${userBranch.name}</option>`;
                branchSelect.disabled = true;
                branchSelect.value = userBranch.id;
            } else {
                branchSelect.disabled = false;
                const branchList = state.branches || [];
                branchSelect.innerHTML = '<option value="">Semua Cabang (Global)</option>' + 
                    branchList.map(b => `<option value="${b.id}">${b.name}</option>`).join('');
            }

            // Populate category options dynamically from active categories
            const catSelect = document.getElementById('cust-category');
            if (catSelect) {
                const cats = state.customerCategories || [];
                const availableCats = cats.filter(c => c.is_active == 1 || (cust && cust.category === c.code));
                if (availableCats.length > 0) {
                    catSelect.innerHTML = availableCats.map(c => `
                        <option value="${c.code}">${c.icon_emoji ? c.icon_emoji + ' ' : ''}${c.name} (${c.code})</option>
                    `).join('');
                } else {
                    catSelect.innerHTML = `
                        <option value="REGULER">👤 Pelanggan Reguler (REGULER)</option>
                        <option value="MEMBER">⭐ Member Loyalitas (MEMBER)</option>
                        <option value="RESELLER">🛍️ Reseller / Agen (RESELLER)</option>
                        <option value="MITRA">🏢 Mitra Bisnis B2B (MITRA)</option>
                    `;
                }
            }

            if (cust) {
                title.innerText = 'Edit Data Pelanggan / Mitra';
                const submitBtn = document.getElementById('cust-modal-submit-btn');
                if (submitBtn) submitBtn.innerHTML = '<i data-lucide="save" class="w-4 h-4"></i><span>Perbarui Data</span>';
                document.getElementById('cust-id').value = cust.id;
                document.getElementById('cust-category').value = cust.category || 'REGULER';
                document.getElementById('cust-code').value = cust.code;
                document.getElementById('cust-name').value = cust.name;
                document.getElementById('cust-phone').value = cust.phone || '';
                document.getElementById('cust-email').value = cust.email || '';
                document.getElementById('cust-discount').value = cust.discount_percent || 0;
                document.getElementById('cust-branch').value = cust.branch_id || '';
                document.getElementById('cust-address').value = cust.address || '';
                document.getElementById('cust-latitude').value = cust.latitude || '';
                document.getElementById('cust-longitude').value = cust.longitude || '';
                document.getElementById('cust-notes').value = cust.notes || '';
                
                const searchInput = document.getElementById('cust-modal-search-input');
                if (searchInput) searchInput.value = cust.address || cust.name || '';
                toggleCustSearchClearBtn();
                const statusEl = document.getElementById('cust-modal-search-status');
                if (statusEl) {
                    statusEl.innerHTML = '';
                    statusEl.classList.add('hidden');
                }

                updateCustPickerBadge(cust.latitude, cust.longitude);
            } else {
                title.innerText = 'Tambah Pelanggan / Mitra Baru';
                const submitBtn = document.getElementById('cust-modal-submit-btn');
                if (submitBtn) submitBtn.innerHTML = '<i data-lucide="check" class="w-4 h-4"></i><span>Simpan Data</span>';
                document.getElementById('cust-id').value = '';
                document.getElementById('cust-category').value = 'REGULER';
                document.getElementById('cust-code').value = '';
                document.getElementById('cust-name').value = '';
                document.getElementById('cust-phone').value = '';
                document.getElementById('cust-email').value = '';
                document.getElementById('cust-discount').value = '0';
                document.getElementById('cust-branch').value = (userBranch ? userBranch.id : '') || (state.currentBranch ? state.currentBranch.id : '');
                document.getElementById('cust-address').value = '';
                const defLat = (state.currentBranch ? state.currentBranch.latitude : -6.879400) || -6.879400;
                const defLon = (state.currentBranch ? state.currentBranch.longitude : 107.530000) || 107.530000;
                document.getElementById('cust-latitude').value = Number(defLat).toFixed(6);
                document.getElementById('cust-longitude').value = Number(defLon).toFixed(6);
                document.getElementById('cust-notes').value = '';
                clearCustAddressSearch();
                updateCustPickerBadge(defLat, defLon);
            }
            modal.classList.remove('hidden');
            setTimeout(() => {
                initCustomerPickerMap();
            }, 100);
            setTimeout(() => {
                if (state.customerPickerMap) state.customerPickerMap.invalidateSize();
            }, 300);
            setTimeout(() => {
                if (state.customerPickerMap) state.customerPickerMap.invalidateSize();
            }, 500);
            lucide.createIcons();
        }

        function closeCustomerModal() {
            document.getElementById('customer-modal').classList.add('hidden');
        }

        function autoDetectCustLocation() {
            if (navigator.geolocation) {
                navigator.geolocation.getCurrentPosition(
                    pos => {
                        const lat = pos.coords.latitude.toFixed(6);
                        const lon = pos.coords.longitude.toFixed(6);
                        document.getElementById('cust-latitude').value = lat;
                        document.getElementById('cust-longitude').value = lon;
                        updateCustPickerBadge(lat, lon);
                        updateCustPickerFromInputs();
                        alert(`Titik GPS berhasil dideteksi:\nLat: ${lat}, Lon: ${lon}`);
                    },
                    err => {
                        // Fallback koordinat sekitar Cimahi/Cabang
                        const defLat = (state.currentBranch ? state.currentBranch.latitude : -6.879400) || -6.879400;
                        const defLon = (state.currentBranch ? state.currentBranch.longitude : 107.530000) || 107.530000;
                        const sLat = (defLat + (Math.random() - 0.5) * 0.02).toFixed(6);
                        const sLon = (defLon + (Math.random() - 0.5) * 0.02).toFixed(6);
                        document.getElementById('cust-latitude').value = sLat;
                        document.getElementById('cust-longitude').value = sLon;
                        updateCustPickerBadge(sLat, sLon);
                        updateCustPickerFromInputs();
                        alert('Izin GPS tidak diberikan atau offline. Koordinat simulasi sekitar outlet telah diisi.');
                    }
                );
            } else {
                alert('Browser Anda tidak mendukung geolokasi GPS.');
            }
        }

        // --- CUSTOMER MINI-MAP PICKER ---
        function updateCustPickerFromInputs() {
            const lat = parseFloat(_val('cust-latitude'));
            const lon = parseFloat(_val('cust-longitude'));
            updateCustPickerBadge(lat, lon);
            if (!isNaN(lat) && !isNaN(lon) && state.customerPickerMap && state.customerPickerMarker) {
                state.customerPickerMarker.setLatLng([lat, lon]);
                state.customerPickerMap.setView([lat, lon], state.customerPickerMap.getZoom() || 14);
            }
        }

        function initCustomerPickerMap() {
            const container = document.getElementById('cust-modal-map-picker');
            if (!container) return;

            let lat = parseFloat(_val('cust-latitude'));
            let lon = parseFloat(_val('cust-longitude'));

            if (isNaN(lat) || isNaN(lon) || (lat === 0 && lon === 0)) {
                const bId = _val('cust-branch');
                const b = (state.branches || []).find(x => x.id == bId) || state.currentBranch;
                lat = parseFloat((b ? b.latitude : null)) || -6.879400;
                lon = parseFloat((b ? b.longitude : null)) || 107.530000;
                document.getElementById('cust-latitude').value = lat.toFixed(6);
                document.getElementById('cust-longitude').value = lon.toFixed(6);
            }

            updateCustPickerBadge(lat, lon);

            if (!state.customerPickerMap) {
                state.customerPickerMap = L.map('cust-modal-map-picker', {
                    zoomControl: true,
                    attributionControl: false
                }).setView([lat, lon], 14);

                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    maxZoom: 19
                }).addTo(state.customerPickerMap);

                state.customerPickerMarker = L.marker([lat, lon], { draggable: true }).addTo(state.customerPickerMap);

                state.customerPickerMarker.on('dragend', function(e) {
                    const pos = e.target.getLatLng();
                    document.getElementById('cust-latitude').value = pos.lat.toFixed(6);
                    document.getElementById('cust-longitude').value = pos.lng.toFixed(6);
                    updateCustPickerBadge(pos.lat, pos.lng);
                });

                state.customerPickerMap.on('click', function(e) {
                    state.customerPickerMarker.setLatLng(e.latlng);
                    document.getElementById('cust-latitude').value = e.latlng.lat.toFixed(6);
                    document.getElementById('cust-longitude').value = e.latlng.lng.toFixed(6);
                    updateCustPickerBadge(e.latlng.lat, e.latlng.lng);
                });
            } else {
                state.customerPickerMarker.setLatLng([lat, lon]);
                state.customerPickerMap.setView([lat, lon], 14);
            }

            setTimeout(() => {
                if (state.customerPickerMap) state.customerPickerMap.invalidateSize();
            }, 50);
            setTimeout(() => {
                if (state.customerPickerMap) state.customerPickerMap.invalidateSize();
            }, 250);
            setTimeout(() => {
                if (state.customerPickerMap) state.customerPickerMap.invalidateSize();
            }, 500);
        }

        // --- SUBTAB 5: PETA GEOSPASIAL PELANGGAN & MITRA ---
        function getHaversineDistanceKm(lat1, lon1, lat2, lon2) {
            if (!lat1 || !lon1 || !lat2 || !lon2) return 0;
            const R = 6371; // Earth's radius in km
            const dLat = (lat2 - lat1) * Math.PI / 180;
            const dLon = (lon2 - lon1) * Math.PI / 180;
            const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
                      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
                      Math.sin(dLon/2) * Math.sin(dLon/2);
            const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
            return parseFloat((R * c).toFixed(2));
        }

        async function initCustomerMap() {
            const mapContainer = document.getElementById('customer-geospatial-map');
            if (!mapContainer) return;

            if (!state.branches || state.branches.length === 0) {
                await loadBranches();
            }
            if (!state.customers || state.customers.length === 0) {
                await loadCustomers();
            }

            const branchLat = parseFloat((state.currentBranch ? state.currentBranch.latitude : -6.879400)) || -6.879400;
            const branchLon = parseFloat((state.currentBranch ? state.currentBranch.longitude : 107.530000)) || 107.530000;

            if (!state.customerMap) {
                state.customerMap = L.map('customer-geospatial-map').setView([branchLat, branchLon], 12);
                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    maxZoom: 19,
                    attribution: '&copy; OpenStreetMap contributors'
                }).addTo(state.customerMap);
            } else {
                state.customerMap.invalidateSize();
            }

            setTimeout(() => {
                if (state.customerMap) state.customerMap.invalidateSize();
            }, 50);
            setTimeout(() => {
                if (state.customerMap) state.customerMap.invalidateSize();
            }, 250);

            populateCustomerMapSelections();
            renderCustomerMapMarkers();
        }

        function populateCustomerMapSelections() {
            const bFilter = document.getElementById('cust-map-branch-filter');
            const cSelect = document.getElementById('cust-map-customer-select');
            if (!bFilter || !cSelect) return;

            const curBVal = bFilter.value || 'ALL';
            bFilter.innerHTML = '<option value="ALL">Semua Cabang Pendaftaran</option>' + 
                state.branches.map(b => `<option value="${b.id}" ${curBVal == b.id ? 'selected' : ''}>🏢 ${b.name}</option>`).join('');

            const bFilterVal = bFilter.value || 'ALL';
            const catFilterVal = _val('cust-map-category-filter') || 'ALL';

            const filteredCusts = state.customers.filter(c => {
                const matchBranch = (bFilterVal === 'ALL' || c.branch_id == bFilterVal);
                const matchCat = (catFilterVal === 'ALL' || c.category === catFilterVal);
                return matchBranch && matchCat;
            });

            if (filteredCusts.length === 0) {
                cSelect.innerHTML = '<option value="">Tidak ada pelanggan ditemukan</option>';
            } else {
                cSelect.innerHTML = filteredCusts.map(c => `
                    <option value="${c.id}">📍 ${c.name} [${c.category || 'REGULER'}]</option>
                `).join('');
            }
        }

        function filterCustomerMapMarkers() {
            populateCustomerMapSelections();
            renderCustomerMapMarkers();
        }

        function renderCustomerMapMarkers() {
            if (!state.customerMap) return;

            // Clear old markers
            if (state.customerMapMarkers) {
                state.customerMapMarkers.forEach(m => state.customerMap.removeLayer(m));
            }
            state.customerMapMarkers = [];

            if (state.customerMapPolyline) {
                state.customerMap.removeLayer(state.customerMapPolyline);
                state.customerMapPolyline = null;
            }

            const bFilterVal = _val('cust-map-branch-filter') || 'ALL';
            const catFilterVal = _val('cust-map-category-filter') || 'ALL';

            // 1. Add branch markers (Outlet toko acuan)
            state.branches.forEach(b => {
                if (b.latitude && b.longitude && (bFilterVal === 'ALL' || b.id == bFilterVal)) {
                    const marker = L.marker([b.latitude, b.longitude]).addTo(state.customerMap);
                    marker.bindPopup(`
                        <div class="text-xs">
                            <strong class="text-indigo-900 block text-sm">🏢 ${b.name}</strong>
                            <p class="text-slate-600">${b.address}</p>
                            <span class="inline-block mt-1 px-2 py-0.5 bg-indigo-100 text-indigo-800 rounded font-bold text-[10px]">Outlet Cabang</span>
                        </div>
                    `);
                    state.customerMapMarkers.push(marker);
                }
            });

            // 2. Add customer markers
            const filteredCusts = state.customers.filter(c => {
                const matchBranch = (bFilterVal === 'ALL' || c.branch_id == bFilterVal);
                const matchCat = (catFilterVal === 'ALL' || c.category === catFilterVal);
                return matchBranch && matchCat;
            });

            const categoryColors = {
                'MITRA': '#059669',    // emerald
                'MEMBER': '#9333ea',   // purple
                'RESELLER': '#d97706', // amber
                'REGULER': '#4f46e5'   // indigo
            };

            filteredCusts.forEach(c => {
                if (c.latitude && c.longitude) {
                    const fillColor = categoryColors[c.category] || '#4f46e5';
                    const marker = L.circleMarker([c.latitude, c.longitude], {
                        radius: 8,
                        fillColor: fillColor,
                        color: '#ffffff',
                        weight: 2,
                        opacity: 1,
                        fillOpacity: 0.9
                    }).addTo(state.customerMap);

                    marker.bindPopup(`
                        <div class="text-xs">
                            <strong class="text-slate-900 block font-bold">${c.category === 'MITRA' ? '🤝 Mitra:' : (c.category === 'MEMBER' ? '⭐ Member:' : (c.category === 'RESELLER' ? '📦 Reseller:' : '👤 Pelanggan:'))} ${c.name}</strong>
                            <p class="text-slate-500">${c.address || '-'}</p>
                            <div class="mt-1 flex items-center space-x-1">
                                <span class="px-1.5 py-0.5 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 rounded text-[10px] font-mono">
                                    ${Number(c.latitude).toFixed(4)}, ${Number(c.longitude).toFixed(4)}
                                </span>
                                <span class="px-1.5 py-0.5 rounded text-[10px] font-bold" style="background:${fillColor}20; color:${fillColor};">
                                    ${c.category || 'REGULER'}
                                </span>
                            </div>
                        </div>
                    `);

                    marker.on('click', () => {
                        selectCustomerOnMap(c);
                    });

                    state.customerMapMarkers.push(marker);
                }
            });

            // Default select
            const cSelect = document.getElementById('cust-map-customer-select');
            const selectedCustId = cSelect ? parseInt(cSelect.value) : null;
            const targetCust = filteredCusts.find(c => c.id === selectedCustId) || filteredCusts[0];
            if (targetCust) {
                selectCustomerOnMap(targetCust, false);
            }
        }

        function onCustomerMapSelectChange() {
            const cId = parseInt(_val('cust-map-customer-select') || 0);
            const cust = state.customers.find(c => c.id === cId);
            if (cust) {
                selectCustomerOnMap(cust, true);
            }
        }

        function selectCustomerOnMap(cust, zoomTo = true) {
            if (!cust) return;
            state.customerSelectedOnMap = cust;

            const cSelect = document.getElementById('cust-map-customer-select');
            if (cSelect && cSelect.value != cust.id) {
                cSelect.value = cust.id;
            }

            const avatarEl = document.getElementById('cust-map-avatar');
            const nameEl = document.getElementById('cust-map-info-name');
            const catBadgeEl = document.getElementById('cust-map-info-cat-badge');
            const codeEl = document.getElementById('cust-map-info-code');
            const phoneEl = document.getElementById('cust-map-info-phone');
            const waBtn = document.getElementById('cust-map-wa-btn');
            const waContainer = document.getElementById('cust-map-wa-container');
            const addrEl = document.getElementById('cust-map-info-address');
            const branchEl = document.getElementById('cust-map-info-branch');
            const coordsEl = document.getElementById('cust-map-info-coords');
            const distEl = document.getElementById('cust-map-info-distance');
            const etaEl = document.getElementById('cust-map-info-eta');
            const notesBox = document.getElementById('cust-map-notes-box');
            const notesEl = document.getElementById('cust-map-info-notes');
            const gmapsLink = document.getElementById('cust-map-gmaps-link');

            const avatars = {
                'MITRA': '🤝',
                'MEMBER': '⭐',
                'RESELLER': '📦',
                'REGULER': '👤'
            };

            if (avatarEl) avatarEl.innerText = avatars[cust.category] || '👤';
            if (nameEl) nameEl.innerText = cust.name;
            if (codeEl) codeEl.innerText = `Kode: ${cust.code || '-'}`;
            if (catBadgeEl) {
                catBadgeEl.innerText = cust.category || 'REGULER';
                if (cust.category === 'MITRA') catBadgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800';
                else if (cust.category === 'MEMBER') catBadgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-purple-100 text-purple-800';
                else if (cust.category === 'RESELLER') catBadgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800';
                else catBadgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700';
            }

            if (phoneEl) phoneEl.innerText = cust.phone || '-';
            if (waBtn && waContainer) {
                if (cust.phone && cust.phone.length > 5) {
                    let cleanPhone = cust.phone.replace(/[^0-9]/g, '');
                    if (cleanPhone.startsWith('0')) cleanPhone = '62' + cleanPhone.substring(1);
                    waBtn.href = `https://wa.me/${cleanPhone}?text=Halo%20${encodeURIComponent(cust.name)},%20kami%20dari%20${encodeURIComponent((state.currentBranch ? state.currentBranch.name : 'Cabang') || 'Kasir')}.`;
                    waContainer.classList.remove('hidden');
                } else {
                    waContainer.classList.add('hidden');
                }
            }

            if (addrEl) addrEl.innerText = cust.address || 'Alamat fisik belum diisi';
            if (branchEl) branchEl.innerText = cust.branch_name || (state.currentBranch ? state.currentBranch.name : 'Semua Cabang');

            const cLat = parseFloat(cust.latitude);
            const cLon = parseFloat(cust.longitude);
            const hasCoords = !isNaN(cLat) && !isNaN(cLon) && (cLat !== 0 || cLon !== 0);

            if (coordsEl) {
                coordsEl.innerText = hasCoords ? `${cLat.toFixed(6)}, ${cLon.toFixed(6)}` : 'Koordinat belum diset';
            }

            const branch = state.branches.find(b => b.id == cust.branch_id) || state.currentBranch || state.branches[0];
            if (hasCoords && branch && branch.latitude && branch.longitude) {
                const bLat = parseFloat(branch.latitude);
                const bLon = parseFloat(branch.longitude);
                const distKm = getHaversineDistanceKm(bLat, bLon, cLat, cLon);
                if (distEl) distEl.innerText = `${distKm} km`;
                if (etaEl) {
                    const minTime = Math.max(5, Math.round(distKm * 3));
                    etaEl.innerText = `~${minTime} - ${minTime + 5} Menit (Motor)`;
                }

                if (state.customerMap) {
                    if (state.customerMapPolyline) {
                        state.customerMap.removeLayer(state.customerMapPolyline);
                    }
                    state.customerMapPolyline = L.polyline([[bLat, bLon], [cLat, cLon]], {
                        color: '#4f46e5',
                        weight: 3,
                        dashArray: '6, 6',
                        opacity: 0.8
                    }).addTo(state.customerMap);
                }
            } else {
                if (distEl) distEl.innerText = '- km';
                if (etaEl) etaEl.innerText = '-';
                if (state.customerMapPolyline && state.customerMap) {
                    state.customerMap.removeLayer(state.customerMapPolyline);
                    state.customerMapPolyline = null;
                }
            }

            if (notesBox && notesEl) {
                if (cust.notes && cust.notes.trim()) {
                    notesEl.innerText = cust.notes;
                    notesBox.classList.remove('hidden');
                } else {
                    notesBox.classList.add('hidden');
                }
            }

            if (gmapsLink) {
                if (hasCoords) {
                    gmapsLink.href = `https://www.google.com/maps?q=${cLat},${cLon}`;
                    gmapsLink.classList.remove('opacity-50', 'pointer-events-none');
                } else {
                    gmapsLink.href = '#';
                    gmapsLink.classList.add('opacity-50', 'pointer-events-none');
                }
            }

            if (zoomTo && hasCoords && state.customerMap) {
                state.customerMap.setView([cLat, cLon], 15, { animate: true });
            }
        }

        function fitCustomerMapBounds() {
            if (!state.customerMap) return;
            const group = L.featureGroup(state.customerMapMarkers || []);
            if (group.getLayers().length > 0) {
                state.customerMap.fitBounds(group.getBounds(), { padding: [50, 50] });
            }
        }

        function focusCustomerOnMap(custId) {
            setCustomerSubtab('maps');
            setTimeout(() => {
                const cSelect = document.getElementById('cust-map-customer-select');
                if (cSelect) {
                    cSelect.value = custId;
                    onCustomerMapSelectChange();
                }
            }, 200);
        }

        function openCustomerModalFromMap() {
            if (state.customerSelectedOnMap) {
                openCustomerModal(state.customerSelectedOnMap);
            } else {
                openCustomerModal();
            }
        }

        function onModalCustCategoryChange() {
            const cat = document.getElementById('cust-category').value;
            const codeInput = document.getElementById('cust-code');
            if (!codeInput.value || codeInput.value.startsWith('CUST-') || codeInput.value.startsWith('MBR-') || codeInput.value.startsWith('MTR-')) {
                const prefix = (cat === 'MITRA') ? 'MTR-' : ((cat === 'MEMBER') ? 'MBR-' : ((cat === 'RESELLER') ? 'RSL-' : 'CUST-'));
                const rand = Math.floor(100 + Math.random() * 900);
                codeInput.value = prefix + String(Date.now()).slice(-4) + rand;
            }
        }

        function editCustomer(id) {
            const cust = state.customers.find(c => c.id === id);
            if (cust) openCustomerModal(cust);
        }

        async function saveCustomerForm(e) {
            e.preventDefault();
            const id = document.getElementById('cust-id').value;
            const latVal = document.getElementById('cust-latitude').value;
            const lonVal = document.getElementById('cust-longitude').value;
            const payload = {
                id: id ? parseInt(id) : null,
                category: document.getElementById('cust-category').value,
                code: document.getElementById('cust-code').value,
                name: document.getElementById('cust-name').value,
                phone: document.getElementById('cust-phone').value,
                email: document.getElementById('cust-email').value,
                discount_percent: parseFloat(document.getElementById('cust-discount').value) || 0,
                branch_id: document.getElementById('cust-branch').value ? parseInt(document.getElementById('cust-branch').value) : null,
                address: document.getElementById('cust-address').value,
                latitude: latVal ? parseFloat(latVal) : null,
                longitude: lonVal ? parseFloat(lonVal) : null,
                notes: document.getElementById('cust-notes').value
            };

            const res = await fetch('api.php?action=save_customer', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeCustomerModal();
                await loadCustomers();
                await initApp();
                // Otomatis pilih pelanggan baru jika didaftarkan saat di POS Kasir
                if (!id && data.customer_id) {
                    selectPosCustomer(data.customer_id);
                }
            }
        }

        async function deleteCustomer(id) {
            if (!hasUserPerm('customers', 'delete') && !hasUserPerm('customers:list', 'delete')) {
                showToast('Akses Ditolak: Peran Anda tidak memiliki izin untuk menonaktifkan/menghapus pelanggan!', 'error');
                return;
            }
            if (!confirm('Apakah Anda yakin ingin menonaktifkan pelanggan ini?')) return;
            const res = await fetch('api.php?action=delete_customer', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadCustomers();
                initApp();
            }
        }

        // ==========================================
        // IMPORT MASSAL PELANGGAN & MITRA (EXCEL / CSV / TSV)
        // ==========================================
        function populateCustomerImportBranches() {
            const select = document.getElementById('cust-import-branch-select');
            const badge = document.getElementById('cust-import-branch-badge');
            if (!select) return;

            const branches = state.branches || [];
            const curUser = state.currentUser || state.loggedInUser || {};
            const isSuper = curUser && (Number(curUser.can_access_all_branches) === 1 || ['SUPER_ADMIN', 'SUPERADMIN'].includes((curUser.role || '').toUpperCase().replace(/_/g, '')));

            let html = '';
            branches.forEach(b => {
                html += `<option value="${b.id}">${escapeHtml(b.name)} (${b.code || 'CAB-' + b.id})</option>`;
            });
            select.innerHTML = html;

            const defaultBranchId = (state.currentBranch ? state.currentBranch.id : 1) || curUser.branch_id || (branches[0] ? branches[0].id : 1);
            select.value = defaultBranchId;

            if (!isSuper) {
                select.disabled = true;
                select.value = curUser.branch_id || defaultBranchId;
                if (badge) {
                    badge.innerText = 'Terkunci ke Cabang Tugas Anda';
                    badge.className = 'text-[10px] text-amber-700 font-semibold bg-white px-2 py-0.5 rounded-full border border-amber-200';
                }
            } else {
                select.disabled = false;
                if (badge) {
                    badge.innerText = 'Super Admin: Bebas pilih cabang tujuan';
                    badge.className = 'text-[10px] text-emerald-700 font-semibold bg-white px-2 py-0.5 rounded-full border border-emerald-200';
                }
            }
        }

        function onCustomerImportBranchChange() {
            const fileInput = document.getElementById('cust-import-file-input');
            const textInput = document.getElementById('cust-import-text-input');
            if (fileInput && fileInput.files && fileInput.files.length > 0) {
                handleCustomerImportFileSelect({ target: fileInput });
            } else if (textInput && textInput.value.trim().length > 0) {
                handleCustomerImportTextChange();
            }
        }

        function normalizeCustomerPhoneJS(phone) {
            let digits = (phone || '').replace(/\D+/g, '');
            if (!digits) return '';
            if (digits.startsWith('62') && digits.length >= 9) {
                digits = '0' + digits.substring(2);
            } else if (!digits.startsWith('0') && digits.length >= 8) {
                digits = '0' + digits;
            }
            return digits;
        }

        function openImportCustomerModal() {
            const fileInput = document.getElementById('cust-import-file-input');
            const textInput = document.getElementById('cust-import-text-input');
            const previewBox = document.getElementById('cust-import-preview-box');
            const warningBanner = document.getElementById('cust-import-cross-warning-banner');
            if (fileInput) fileInput.value = '';
            if (textInput) textInput.value = '';
            if (previewBox) previewBox.classList.add('hidden');
            if (warningBanner) warningBanner.classList.add('hidden');
            window.customerImportPreviewRows = [];
            window.customerImportCrossBranchRows = [];

            // Isi pilihan cabang tujuan import
            populateCustomerImportBranches();

            const modal = document.getElementById('customer-import-modal');
            if (modal) {
                modal.classList.remove('hidden');
                modal.style.setProperty('display', 'flex', 'important');
            }
            if (window.lucide) lucide.createIcons();
        }

        function closeImportCustomerModal() {
            const modal = document.getElementById('customer-import-modal');
            if (modal) {
                modal.classList.add('hidden');
                modal.style.setProperty('display', 'none', 'important');
            }
        }

        function downloadCustomerImportTemplate() {
            window.open('api.php?action=download_customer_template&format=xlsx', '_blank');
        }

        async function handleCustomerImportFileSelect(e) {
            const file = e.target.files[0];
            if (!file) return;

            const previewBox = document.getElementById('cust-import-preview-box');
            const tbody = document.getElementById('cust-import-preview-tbody');
            const countEl = document.getElementById('cust-import-preview-count');
            const badgeEl = document.getElementById('cust-import-valid-badge');
            const textInput = document.getElementById('cust-import-text-input');
            const branchSelect = document.getElementById('cust-import-branch-select');
            const targetBranchId = branchSelect ? parseInt(branchSelect.value) : ((state.currentBranch ? state.currentBranch.id : 1) || 1);

            const fileName = file.name.toLowerCase();
            const isExcel = fileName.endsWith('.xlsx') || fileName.endsWith('.xls');

            if (isExcel) {
                if (textInput) textInput.value = '';
                if (previewBox && tbody) {
                    previewBox.classList.remove('hidden');
                    if (countEl) countEl.innerText = `Membaca berkas Excel: ${file.name}...`;
                    if (badgeEl) {
                        badgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-100 text-indigo-800';
                        badgeEl.innerText = 'Memeriksa Format Excel & Data Cabang...';
                    }
                    tbody.innerHTML = `<tr><td colspan="7" class="p-4 text-center text-slate-500 font-semibold"><span class="inline-block animate-spin mr-1.5">⏳</span> Sedang membaca data dari berkas Excel & memvalidasi cabang...</td></tr>`;
                }

                try {
                    const formData = new FormData();
                    formData.append('file', file);
                    formData.append('branch_id', targetBranchId);
                    const res = await fetch('api.php?action=preview_customer_import', {
                        method: 'POST',
                        body: formData
                    });
                    const rawText = await res.text();
                    let result;
                    try {
                        result = JSON.parse(rawText);
                    } catch (e) {
                        throw new Error('Respon server bukan JSON: ' + (rawText ? rawText.substring(0, 150) : 'Kosong (HTTP ' + res.status + ')'));
                    }
                    if (result.success && Array.isArray(result.rows) && result.rows.length > 0) {
                        renderCustomerImportPreviewRows(result.rows, result.total, result.valid_count, result.invalid_count, result.cross_branch_count, result.target_branch_name, result.cross_branch_list);
                    } else {
                        if (tbody) {
                            tbody.innerHTML = `<tr><td colspan="7" class="p-3 text-center text-rose-600 font-semibold">⚠️ ${result.message || 'Tidak ada baris data yang ditemukan dalam berkas Excel ini.'}</td></tr>`;
                        }
                        if (badgeEl) {
                            badgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-100 text-rose-800';
                            badgeEl.innerText = 'Format Kosong / Tidak Sesuai';
                        }
                    }
                } catch (err) {
                    if (tbody) {
                        tbody.innerHTML = `<tr><td colspan="7" class="p-3 text-center text-rose-600">Gagal membaca preview Excel: ${err.message}</td></tr>`;
                    }
                }
                return;
            }

            // CSV atau Plain Text
            const reader = new FileReader();
            reader.onload = function(evt) {
                const text = evt.target.result;
                if (textInput) {
                    textInput.value = text;
                    handleCustomerImportTextChange();
                }
            };
            reader.readAsText(file);
        }

        function extractGoogleCoordsJS(val) {
            if (!val || typeof val !== 'string') return null;
            val = val.trim();
            // Pola 1: @lat,lon
            let m = val.match(/@(-?\d{1,2}\.\d+),(-?\d{1,3}\.\d+)/);
            if (m) return { lat: parseFloat(m[1]), lon: parseFloat(m[2]) };
            // Pola 2: q=lat,lon atau query=lat,lon
            m = val.match(/(?:[?&](?:q|query|ll|destination)=(-?\d{1,2}\.\d+)[,+](-?\d{1,3}\.\d+))/i);
            if (m) return { lat: parseFloat(m[1]), lon: parseFloat(m[2]) };
            // Pola 3: /place/lat,lon
            m = val.match(/\/place\/(-?\d{1,2}\.\d+)[,+](-?\d{1,3}\.\d+)/i);
            if (m) return { lat: parseFloat(m[1]), lon: parseFloat(m[2]) };
            // Pola 4: Raw decimal coordinates
            m = val.match(/(-?\d{1,2}\.\d{3,})[,\s]+(-?\d{1,3}\.\d{3,})/);
            if (m) {
                const lat = parseFloat(m[1]);
                const lon = parseFloat(m[2]);
                if (lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180) {
                    return { lat, lon };
                }
            }
            return null;
        }

        function renderCustomerImportPreviewRows(rows, total, validCount, invalidCount, crossBranchCount = 0, targetBranchName = '', crossBranchList = []) {
            const previewBox = document.getElementById('cust-import-preview-box');
            const tbody = document.getElementById('cust-import-preview-tbody');
            const countEl = document.getElementById('cust-import-preview-count');
            const badgeEl = document.getElementById('cust-import-valid-badge');
            const warningBanner = document.getElementById('cust-import-cross-warning-banner');
            const warningDesc = document.getElementById('cust-import-cross-warning-desc');
            if (!previewBox || !tbody) return;

            window.customerImportPreviewRows = rows || [];
            window.customerImportCrossBranchRows = (crossBranchList && crossBranchList.length > 0) 
                ? crossBranchList 
                : (rows || []).filter(r => r.match_type === 'CROSS_BRANCH');

            const actualCrossCount = crossBranchCount || window.customerImportCrossBranchRows.length;

            // Handle warning banner
            if (warningBanner && warningDesc) {
                if (actualCrossCount > 0) {
                    warningBanner.classList.remove('hidden');
                    const sampleNames = window.customerImportCrossBranchRows.slice(0, 3).map(r => `<strong>${escapeHtml(r.name)}</strong> (di <em>${escapeHtml(r.other_branch_name)}</em>)`).join(', ');
                    const more = actualCrossCount > 3 ? ` dan ${actualCrossCount - 3} pelanggan lainnya` : '';
                    warningDesc.innerHTML = `Ditemukan <strong>${actualCrossCount} data</strong> yang sudah terdaftar di cabang lain (${sampleNames}${more}). Jika diimport, data akan otomatis didaftarkan sebagai pelanggan baru untuk <strong>${escapeHtml(targetBranchName || 'cabang yang dipilih')}</strong>.`;
                } else {
                    warningBanner.classList.add('hidden');
                }
            }

            const rowsHtml = rows.slice(0, 15).map((r, idx) => {
                const name = r.name || '';
                const phone = r.phone || '';
                const addr = r.address || '-';
                const gmaps = r.maps_url || '';
                const cat = r.category || 'REGULER';
                const isValid = (r.is_valid !== undefined) ? r.is_valid : (name.length > 0 && phone.replace(/[^\d+]/g, '').length >= 6);

                let coords = r.coords;
                if (!coords && gmaps) {
                    coords = extractGoogleCoordsJS(gmaps);
                }

                const coordsBadge = coords 
                    ? `<span class="px-1.5 py-0.5 bg-emerald-50 text-emerald-700 font-mono text-[9px] rounded font-bold" title="${escapeHtml(gmaps)}">📍 ${coords.lat.toFixed(4)}, ${coords.lon.toFixed(4)}</span>`
                    : (gmaps ? `<span class="text-slate-400 truncate max-w-[120px] inline-block text-[10px]" title="${escapeHtml(gmaps)}">${escapeHtml(gmaps)}</span>` : '<span class="text-slate-300">-</span>');

                let statusBadge = '';
                if (!isValid) {
                    statusBadge = '<span class="px-1.5 py-0.5 bg-rose-100 text-rose-800 rounded-full font-bold text-[9px]">Gagal</span>';
                } else if (r.match_type === 'UPDATE') {
                    statusBadge = '<span class="px-1.5 py-0.5 bg-blue-100 text-blue-800 rounded-full font-bold text-[9px]" title="Sudah terdaftar di cabang ini, profil akan diperbarui">Update Cabang</span>';
                } else if (r.match_type === 'CROSS_BRANCH') {
                    statusBadge = `<span class="px-1.5 py-0.5 bg-amber-100 text-amber-900 border border-amber-300 rounded-full font-bold text-[9px]" title="Sudah terdaftar di cabang ${escapeHtml(r.other_branch_name)}">⚠️ Di: ${escapeHtml(r.other_branch_name)}</span>`;
                } else {
                    statusBadge = '<span class="px-1.5 py-0.5 bg-emerald-100 text-emerald-800 rounded-full font-bold text-[9px]">Baru</span>';
                }

                return `
                    <tr class="${!isValid ? 'bg-rose-50/50' : (r.match_type === 'CROSS_BRANCH' ? 'bg-amber-50/30' : 'hover:bg-slate-50')}">
                        <td class="p-2 text-slate-400 font-mono">${idx + 1}</td>
                        <td class="p-2 font-bold ${isValid ? 'text-slate-800' : 'text-rose-600'}">${escapeHtml(name) || '<span class="italic text-rose-500 font-normal">Kosong (Wajib)</span>'}</td>
                        <td class="p-2 font-mono ${phone.replace(/[^\d+]/g, '').length >= 6 ? 'text-slate-700' : 'text-rose-600'}">${escapeHtml(phone) || '<span class="italic text-rose-500 font-normal">Kosong (Wajib)</span>'}</td>
                        <td class="p-2 text-slate-500 truncate max-w-[140px]" title="${escapeHtml(addr)}">${escapeHtml(addr)}</td>
                        <td class="p-2">${coordsBadge}</td>
                        <td class="p-2"><span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">${escapeHtml(cat || 'REGULER')}</span></td>
                        <td class="p-2 text-center whitespace-nowrap">
                            ${statusBadge}
                        </td>
                    </tr>
                `;
            }).join('');

            tbody.innerHTML = rowsHtml;
            previewBox.classList.remove('hidden');

            if (countEl) {
                countEl.innerText = `Pratinjau: ${total} Baris Ditemukan (${validCount} Valid${total > 15 ? ', menampilkan 15 baris pertama' : ''})`;
            }
            if (badgeEl) {
                if (invalidCount === 0 && actualCrossCount === 0) {
                    badgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800';
                    badgeEl.innerText = `${validCount} Baris Siap Diimport`;
                } else if (actualCrossCount > 0) {
                    badgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-900 border border-amber-300';
                    badgeEl.innerText = `${validCount} Valid (${actualCrossCount} Terdaftar di Cabang Lain)`;
                } else {
                    badgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800';
                    badgeEl.innerText = `${validCount} Valid, ${invalidCount} Baris Tidak Lengkap (Akan Dilewati)`;
                }
            }
            if (window.lucide) lucide.createIcons();
        }

        function handleCustomerImportTextChange() {
            const textInput = document.getElementById('cust-import-text-input');
            const previewBox = document.getElementById('cust-import-preview-box');
            const tbody = document.getElementById('cust-import-preview-tbody');
            const branchSelect = document.getElementById('cust-import-branch-select');
            if (!textInput || !previewBox || !tbody) return;

            const text = textInput.value.trim();
            if (!text) {
                previewBox.classList.add('hidden');
                return;
            }

            const targetBranchId = branchSelect ? parseInt(branchSelect.value) : ((state.currentBranch ? state.currentBranch.id : 1) || 1);
            const targetBranchName = (branchSelect && branchSelect.selectedOptions[0]) ? branchSelect.selectedOptions[0].text : 'Cabang Terpilih';

            const lines = text.split(/\r?\n/).filter(l => l.trim().length > 0);
            if (lines.length === 0) {
                previewBox.classList.add('hidden');
                return;
            }

            // Detect delimiter
            const first = lines[0];
            const tabC = (first.match(/\t/g) || []).length;
            const semiC = (first.match(/;/g) || []).length;
            const commaC = (first.match(/,/g) || []).length;
            let delim = ',';
            if (tabC > commaC && tabC > semiC) delim = '\t';
            else if (semiC > commaC) delim = ';';

            // Check header
            const headerTokens = first.split(delim).map(s => s.trim().replace(/^["']|["']$/g, '').toLowerCase());
            let isHeader = false;
            let colMap = { name: 0, phone: 1, address: 2, maps_url: 3, category: 4 };

            headerTokens.forEach((ht, idx) => {
                if (ht.includes('nama') || ht.includes('name')) { isHeader = true; colMap.name = idx; }
                else if (ht.includes('telp') || ht.includes('telepon') || ht.includes('phone') || ht.includes('hp') || ht.includes('wa')) { isHeader = true; colMap.phone = idx; }
                else if (ht.includes('alamat') || ht.includes('address')) { isHeader = true; colMap.address = idx; }
                else if (ht.includes('map') || ht.includes('koordinat') || ht.includes('longlat') || ht.includes('latlong') || ht.includes('url')) { isHeader = true; colMap.maps_url = idx; }
                else if (ht.includes('kategori') || ht.includes('category') || ht.includes('tier')) { isHeader = true; colMap.category = idx; }
            });

            const dataLines = isHeader ? lines.slice(1) : lines;
            if (dataLines.length === 0) {
                previewBox.classList.add('hidden');
                return;
            }

            // Index existing customers in memory
            const existingCusts = state.customers || [];
            const targetNormMap = {};
            const targetNameMap = {};
            const otherNormMap = {};
            const otherNameMap = {};

            existingCusts.forEach(c => {
                const isTarget = (parseInt(c.branch_id) === targetBranchId);
                const normP = normalizeCustomerPhoneJS(c.phone);
                const normN = (c.name || '').trim().toLowerCase();
                if (isTarget) {
                    if (normP) targetNormMap[normP] = c;
                    if (normN) targetNameMap[normN] = c;
                } else {
                    if (normP && !otherNormMap[normP]) otherNormMap[normP] = c;
                    if (normN && !otherNameMap[normN]) otherNameMap[normN] = c;
                }
            });

            let validCount = 0;
            let invalidCount = 0;
            let crossBranchCount = 0;
            const rows = [];
            const crossBranchList = [];

            dataLines.forEach((l, idx) => {
                let cols = l.split(delim).map(s => s.trim().replace(/^["']|["']$/g, ''));
                if (cols.length > 5 && colMap.maps_url !== undefined && cols[colMap.maps_url]) {
                    const candidate = cols[colMap.maps_url] + ',' + (cols[colMap.maps_url + 1] || '');
                    if (candidate.match(/(?:[?&]q=|-?\d{1,2}\.\d+)[,+](?:-?\d{1,3}\.\d+)/i)) {
                        const merged = cols.slice(0, colMap.maps_url);
                        merged.push(candidate);
                        cols = merged.concat(cols.slice(colMap.maps_url + 2));
                    }
                }

                const name = cols[colMap.name] || '';
                const phone = cols[colMap.phone] || '';
                const addr = cols[colMap.address] || '-';
                const gmaps = cols[colMap.maps_url] || '';
                const cat = cols[colMap.category] || 'REGULER';
                const isValid = (name.length > 0 && phone.replace(/[^\d+]/g, '').length >= 6);

                let matchType = 'NEW';
                let otherBranchName = null;
                let otherBranchId = null;

                if (isValid) {
                    validCount++;
                    const normP = normalizeCustomerPhoneJS(phone);
                    const normN = name.trim().toLowerCase();

                    if (targetNormMap[normP] || targetNameMap[normN]) {
                        matchType = 'UPDATE';
                    } else if (otherNormMap[normP] || otherNameMap[normN]) {
                        const other = otherNormMap[normP] || otherNameMap[normN];
                        matchType = 'CROSS_BRANCH';
                        otherBranchName = other.branch_name || 'Cabang Lain';
                        otherBranchId = other.branch_id;
                        crossBranchCount++;
                        crossBranchList.push({
                            row: idx + 1,
                            name,
                            phone,
                            other_branch_name: otherBranchName,
                            other_branch_id: otherBranchId
                        });
                    }
                } else {
                    invalidCount++;
                }

                rows.push({
                    name, phone, address: addr, maps_url: gmaps, category: cat, is_valid: isValid,
                    match_type: matchType, other_branch_name: otherBranchName, other_branch_id: otherBranchId
                });
            });

            renderCustomerImportPreviewRows(rows, dataLines.length, validCount, invalidCount, crossBranchCount, targetBranchName, crossBranchList);
        }

        async function submitImportCustomers(e) {
            e.preventDefault();
            const fileInput = document.getElementById('cust-import-file-input');
            const textInput = document.getElementById('cust-import-text-input');
            const btnSubmit = document.getElementById('btn-submit-import-customers');
            const branchSelect = document.getElementById('cust-import-branch-select');

            const targetBranchId = branchSelect ? parseInt(branchSelect.value) : ((state.currentBranch ? state.currentBranch.id : 1) || 1);
            const targetBranchName = (branchSelect && branchSelect.selectedOptions[0]) ? branchSelect.selectedOptions[0].text : 'Cabang Terpilih';

            const hasFile = fileInput && fileInput.files && fileInput.files.length > 0;
            const hasText = textInput && textInput.value.trim().length > 0;

            if (!hasFile && !hasText) {
                alert('Silakan pilih berkas CSV / Excel atau tempel teks data pelanggan terlebih dahulu.');
                return;
            }

            // Konfirmasi jika terdapat data yang sudah terdaftar di cabang lain
            const crossList = window.customerImportCrossBranchRows || [];
            if (crossList.length > 0) {
                const listPreview = crossList.slice(0, 5).map(r => `• ${r.name} (${r.phone}): Terdaftar di "${r.other_branch_name}"`).join('\n');
                const moreText = crossList.length > 5 ? `\n...dan ${crossList.length - 5} pelanggan lainnya` : '';
                const confirmMsg = `⚠️ KONFIRMASI DATA TERDAFTAR DI CABANG LAIN:\n\n` +
                    `Terdapat ${crossList.length} data pelanggan yang sudah terdaftar di cabang berbeda:\n` +
                    `${listPreview}${moreText}\n\n` +
                    `Data ini akan tetap didaftarkan sebagai pelanggan untuk cabang:\n` +
                    `👉 "${targetBranchName}"\n\n` +
                    `Apakah Anda yakin ingin melanjutkan proses import?`;
                if (!confirm(confirmMsg)) {
                    return;
                }
            }

            btnSubmit.disabled = true;
            btnSubmit.innerHTML = `<span class="inline-block animate-spin mr-1">⏳</span><span>Memproses Import ke ${escapeHtml(targetBranchName)}...</span>`;

            try {
                let res;
                if (hasFile) {
                    const formData = new FormData();
                    formData.append('file', fileInput.files[0]);
                    formData.append('branch_id', targetBranchId);
                    res = await fetch('api.php?action=import_customers', {
                        method: 'POST',
                        body: formData
                    });
                } else {
                    res = await fetch('api.php?action=import_customers', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ 
                            csv_content: textInput.value.trim(),
                            branch_id: targetBranchId 
                        })
                    });
                }

                const rawRes = await res.text();
                let data;
                try {
                    data = JSON.parse(rawRes);
                } catch (errJson) {
                    throw new Error('Respon server bukan JSON: ' + (rawRes ? rawRes.substring(0, 150) : 'Kosong (HTTP ' + res.status + ')'));
                }
                btnSubmit.disabled = false;
                btnSubmit.innerHTML = `<i data-lucide="upload" class="w-4 h-4"></i><span>Proses Import Pelanggan</span>`;
                if (window.lucide) lucide.createIcons();

                alert(data.message || (data.success ? 'Import pelanggan selesai!' : 'Gagal import pelanggan'));
                if (data.success) {
                    closeImportCustomerModal();
                    await loadCustomers();
                    await initApp();
                }
            } catch (err) {
                btnSubmit.disabled = false;
                btnSubmit.innerHTML = `<i data-lucide="upload" class="w-4 h-4"></i><span>Proses Import Pelanggan</span>`;
                if (window.lucide) lucide.createIcons();
                alert('Terjadi kesalahan jaringan saat import data pelanggan: ' + err.message);
            }
        }

        // ==========================================
        // TOOL TRANSAKSI PENGUJIAN: IMPORT PENJUALAN & POTONG STOK
        // ==========================================
        function openSaleImportModal() {
            const modal = document.getElementById('sale-import-modal');
            if (!modal) return;

            // Populate branch dropdown
            const branchSelect = document.getElementById('sale-import-branch-select');
            const branchContainer = document.getElementById('sale-import-branch-container');
            if (branchSelect) {
                branchSelect.innerHTML = '';
                const branches = (state && state.branches) ? state.branches : [];
                const currentBranchId = (state && state.currentBranch && state.currentBranch.id) ? parseInt(state.currentBranch.id) : 1;
                const isSuperAdmin = (state && state.currentUser && (state.currentUser.role === 'SUPERADMIN' || state.currentUser.role === 'SUPER_ADMIN'));

                if (branches && branches.length > 0) {
                    branches.forEach(function(b) {
                        const opt = document.createElement('option');
                        opt.value = b.id;
                        opt.textContent = b.name + (b.code ? ' (' + b.code + ')' : '');
                        if (parseInt(b.id) === currentBranchId) {
                            opt.selected = true;
                        }
                        branchSelect.appendChild(opt);
                    });
                } else {
                    const opt = document.createElement('option');
                    opt.value = currentBranchId;
                    opt.textContent = (state && state.currentBranch && state.currentBranch.name) ? state.currentBranch.name : 'Cabang Utama';
                    opt.selected = true;
                    branchSelect.appendChild(opt);
                }

                if (!isSuperAdmin && branchContainer) {
                    branchSelect.value = currentBranchId;
                    branchSelect.disabled = true;
                } else if (branchSelect) {
                    branchSelect.disabled = false;
                }
            }

            // Reset file and preview
            clearSaleImportFile();

            modal.classList.remove('hidden');
            modal.style.setProperty('display', 'flex', 'important');
            if (window.lucide) lucide.createIcons();
        }

        function closeSaleImportModal() {
            const modal = document.getElementById('sale-import-modal');
            if (modal) {
                modal.classList.add('hidden');
                modal.style.setProperty('display', 'none', 'important');
            }
        }

