        async function handleSaleImportFileSelect(e) {
            const file = (e.target && e.target.files) ? e.target.files[0] : null;
            if (!file) return;

            const previewBox = document.getElementById('sale-import-preview-box');
            const tbody = document.getElementById('sale-import-preview-tbody');
            const badgeEl = document.getElementById('sale-import-valid-badge');
            const countEl = document.getElementById('sale-import-preview-count');
            const branchSelect = document.getElementById('sale-import-branch-select');
            const targetBranchId = branchSelect ? parseInt(branchSelect.value) : ((state && state.currentBranch && state.currentBranch.id) ? state.currentBranch.id : 1);

            const fileName = file.name.toLowerCase();

            if (previewBox && tbody) {
                previewBox.classList.remove('hidden');
                if (countEl) countEl.innerText = 'Membaca berkas: ' + file.name + '...';
                if (badgeEl) {
                    badgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800';
                    badgeEl.innerText = 'Memvalidasi Produk & Stok Cabang...';
                }
                tbody.innerHTML = '<tr><td colspan="11" class="p-4 text-center text-slate-500 font-semibold"><span class="inline-block animate-spin mr-1.5">⏳</span> Membaca data transaksi Excel & menghitung simulasi stok cabang...</td></tr>';
            }

            try {
                const formData = new FormData();
                formData.append('file', file);
                formData.append('branch_id', targetBranchId);

                const res = await fetch('api.php?action=preview_sale_import', {
                    method: 'POST',
                    body: formData
                });
                const rawText = await res.text();
                let result;
                try {
                    result = JSON.parse(rawText);
                } catch (eParse) {
                    throw new Error('Respon server bukan JSON: ' + (rawText ? rawText.substring(0, 150) : 'Kosong (HTTP ' + res.status + ')'));
                }

                if (result.success && Array.isArray(result.rows) && result.rows.length > 0) {
                    renderSaleImportPreview(result);
                } else {
                    if (tbody) {
                        tbody.innerHTML = '<tr><td colspan="11" class="p-4 text-center text-rose-600 font-semibold">⚠️ ' + escapeHtml(result.message || 'Tidak ada baris data penjualan yang dapat dibaca.') + '</td></tr>';
                    }
                    if (badgeEl) {
                        badgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-100 text-rose-800';
                        badgeEl.innerText = 'Format Kosong / Tidak Sesuai';
                    }
                }
            } catch (err) {
                if (tbody) {
                    tbody.innerHTML = '<tr><td colspan="11" class="p-4 text-center text-rose-600">Gagal memproses pratinjau penjualan: ' + escapeHtml(err.message) + '</td></tr>';
                }
            }
        }

        async function handleSaleImportTextChange() {
            const textInput = document.getElementById('sale-import-text-input');
            if (!textInput) return;
            const text = textInput.value.trim();
            const previewBox = document.getElementById('sale-import-preview-box');
            const tbody = document.getElementById('sale-import-preview-tbody');
            const branchSelect = document.getElementById('sale-import-branch-select');
            const targetBranchId = branchSelect ? parseInt(branchSelect.value) : ((state && state.currentBranch && state.currentBranch.id) ? state.currentBranch.id : 1);

            if (!text) {
                if (previewBox) previewBox.classList.add('hidden');
                return;
            }

            if (previewBox && tbody) {
                previewBox.classList.remove('hidden');
                tbody.innerHTML = '<tr><td colspan="11" class="p-4 text-center text-slate-500 font-semibold"><span class="inline-block animate-spin mr-1.5">⏳</span> Memvalidasi teks CSV...</td></tr>';
            }

            try {
                const res = await fetch('api.php?action=preview_sale_import', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        csv_content: text,
                        branch_id: targetBranchId
                    })
                });
                const rawText = await res.text();
                let result;
                try {
                    result = JSON.parse(rawText);
                } catch (eParse) {
                    throw new Error('Respon server bukan JSON: ' + (rawText ? rawText.substring(0, 150) : 'Kosong'));
                }
                if (result.success && Array.isArray(result.rows) && result.rows.length > 0) {
                    renderSaleImportPreview(result);
                } else if (tbody) {
                    tbody.innerHTML = '<tr><td colspan="11" class="p-4 text-center text-rose-600 font-semibold">⚠️ ' + escapeHtml(result.message || 'Tidak ada baris data valid.') + '</td></tr>';
                }
            } catch (err) {
                if (tbody) {
                    tbody.innerHTML = '<tr><td colspan="11" class="p-4 text-center text-rose-600">Gagal membaca teks CSV: ' + escapeHtml(err.message) + '</td></tr>';
                }
            }
        }

        function renderSaleImportPreview(data) {
            const rows = data.rows || [];
            const previewBox = document.getElementById('sale-import-preview-box');
            const tbody = document.getElementById('sale-import-preview-tbody');
            const badgeEl = document.getElementById('sale-import-valid-badge');
            const countEl = document.getElementById('sale-import-preview-count');

            if (!previewBox || !tbody) return;
            window.saleImportPreviewRows = rows;

            // KPI
            const elTotalRows = document.getElementById('sale-preview-total-rows');
            const elValidRows = document.getElementById('sale-preview-valid-rows');
            const elUniqueInv = document.getElementById('sale-preview-unique-invoices');
            const elTotalQty = document.getElementById('sale-preview-total-qty');
            const elTotalOmzet = document.getElementById('sale-preview-total-omzet');

            if (elTotalRows) elTotalRows.innerText = data.total_rows || rows.length;
            if (elValidRows) elValidRows.innerText = data.valid_count || 0;
            if (elUniqueInv) elUniqueInv.innerText = data.unique_invoices_count || (rows.length > 0 ? 1 : 0);
            if (elTotalQty) elTotalQty.innerText = formatNumber(data.total_qty || 0);
            if (elTotalOmzet) elTotalOmzet.innerText = 'Rp ' + formatNumber(data.total_estimated_sales || 0);

            if (countEl) {
                countEl.innerText = 'Pratinjau Data Penjualan di ' + (data.target_branch_name || 'Cabang Terpilih') + ':';
            }
            if (badgeEl) {
                if ((data.invalid_count || 0) === 0) {
                    badgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800';
                    badgeEl.innerText = (data.valid_count || 0) + ' Baris Valid (Siap Eksekusi)';
                } else {
                    badgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-900';
                    badgeEl.innerText = (data.valid_count || 0) + ' Valid, ' + (data.invalid_count || 0) + ' Error';
                }
            }

            const rowsHtml = rows.slice(0, 30).map(function(r, idx) {
                const isValid = r.is_valid;
                const statusBadge = isValid 
                    ? '<span class="px-1.5 py-0.5 bg-emerald-100 text-emerald-800 rounded-full font-bold text-[9px]">Valid</span>'
                    : '<span class="px-1.5 py-0.5 bg-rose-100 text-rose-800 rounded-full font-bold text-[9px]" title="' + escapeHtml(r.error_message || 'Data error') + '">Error</span>';

                let bomBadge = '<span class="text-slate-300">-</span>';
                if (r.has_bom && r.bom_list && r.bom_list.length > 0) {
                    const bomDetails = r.bom_list.map(function(b) {
                        return b.ing_name + ' (-' + formatNumber(b.qty_needed) + ' ' + (b.unit || '') + ')';
                    }).join(', ');
                    bomBadge = '<span class="px-1.5 py-0.5 bg-indigo-50 text-indigo-700 font-semibold text-[9px] rounded" title="' + escapeHtml(bomDetails) + '">🧪 ' + r.bom_list.length + ' Bahan Baku</span>';
                }

                const stockBefore = typeof r.stock_before !== 'undefined' ? formatNumber(r.stock_before) : '-';
                const stockAfter = typeof r.stock_after !== 'undefined' ? formatNumber(r.stock_after) : '-';
                const stockDisplay = isValid 
                    ? '<span class="font-mono text-[10px] text-slate-600">' + stockBefore + ' &rarr; <strong class="text-indigo-900">' + stockAfter + '</strong></span>'
                    : '<span class="text-slate-300">-</span>';

                const prodTitle = r.product_name + (r.variant_name ? ' [' + r.variant_name + ']' : '');

                return '<tr class="' + (!isValid ? 'bg-rose-50/50' : 'hover:bg-slate-50') + '">' +
                    '<td class="p-2 text-slate-400 font-mono">' + (idx + 1) + '</td>' +
                    '<td class="p-2">' + statusBadge + '</td>' +
                    '<td class="p-2 font-mono text-slate-700 font-semibold">' + escapeHtml(r.invoice_number || 'AUTO') + '</td>' +
                    '<td class="p-2">' +
                        '<div class="font-bold ' + (isValid ? 'text-slate-800' : 'text-rose-600') + '">' + escapeHtml(prodTitle) + '</div>' +
                        '<div class="font-mono text-[9px] text-slate-400">' + escapeHtml(r.sku || '-') + '</div>' +
                        (!isValid && r.error_message ? '<div class="text-[10px] text-rose-600 italic mt-0.5">⚠️ ' + escapeHtml(r.error_message) + '</div>' : '') +
                    '</td>' +
                    '<td class="p-2 text-center font-bold font-mono text-slate-800">' + formatNumber(r.qty) + '</td>' +
                    '<td class="p-2 text-right font-mono text-slate-700">' + formatNumber(r.unit_price) + '</td>' +
                    '<td class="p-2 text-right font-mono font-bold text-slate-900">' + formatNumber(r.subtotal) + '</td>' +
                    '<td class="p-2 text-center">' + stockDisplay + '</td>' +
                    '<td class="p-2">' + bomBadge + '</td>' +
                    '<td class="p-2"><span class="font-medium text-slate-700">' + escapeHtml(r.customer_name || 'Umum') + '</span> <span class="text-[9px] font-bold text-indigo-700">(' + escapeHtml(r.customer_category || 'REGULER') + ')</span></td>' +
                    '<td class="p-2 font-semibold text-slate-700 text-[10px]">' + escapeHtml(r.payment_method || 'CASH') + '</td>' +
                '</tr>';
            }).join('');

            tbody.innerHTML = rowsHtml;
            if (rows.length > 30) {
                tbody.innerHTML += '<tr><td colspan="11" class="p-2 text-center text-slate-400 italic">Menampilkan 30 baris pertama dari total ' + rows.length + ' baris transaksi.</td></tr>';
            }
        }

        async function submitSaleImport(e) {
            e.preventDefault();
            const fileInput = document.getElementById('sale-import-file-input');
            const textInput = document.getElementById('sale-import-text-input');
            const branchSelect = document.getElementById('sale-import-branch-select');
            const btnSubmit = document.getElementById('btn-submit-sale-import');

            const targetBranchId = branchSelect ? parseInt(branchSelect.value) : ((state && state.currentBranch && state.currentBranch.id) ? state.currentBranch.id : 1);
            const targetBranchName = (branchSelect && branchSelect.selectedOptions && branchSelect.selectedOptions[0]) ? branchSelect.selectedOptions[0].text : 'Cabang Terpilih';

            const hasFile = fileInput && fileInput.files && fileInput.files.length > 0;
            const hasText = textInput && textInput.value.trim().length > 0;
            const previewRows = window.saleImportPreviewRows || [];

            if (!hasFile && !hasText && previewRows.length === 0) {
                alert('Silakan pilih berkas Excel/CSV atau tempel data penjualan terlebih dahulu.');
                return;
            }

            const validCount = previewRows.filter(function(r) { return r.is_valid; }).length;
            const confirmMsg = '⚡ KONFIRMASI IMPORT PENJUALAN & POTONG STOK:\n\n' +
                'Cabang Tujuan: ' + targetBranchName + '\n' +
                'Jumlah Transaksi/Baris Valid: ' + (validCount || 'Sesuai berkas') + '\n\n' +
                'Sistem akan langsung membuat faktur penjualan dan MEMOTONG SALDO STOK PRODUK & BAHAN BAKU BOM secara realtime.\n\n' +
                'Apakah Anda yakin ingin mengeksekusi import transaksi sekarang?';

            if (!confirm(confirmMsg)) {
                return;
            }

            btnSubmit.disabled = true;
            btnSubmit.innerHTML = '<span class="inline-block animate-spin mr-1">⏳</span><span>Mengeksekusi Transaksi & Memotong Stok...</span>';

            try {
                let res;
                if (hasFile) {
                    const formData = new FormData();
                    formData.append('file', fileInput.files[0]);
                    formData.append('branch_id', targetBranchId);
                    res = await fetch('api.php?action=execute_sale_import', {
                        method: 'POST',
                        body: formData
                    });
                } else if (hasText) {
                    res = await fetch('api.php?action=execute_sale_import', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            csv_content: textInput.value.trim(),
                            branch_id: targetBranchId
                        })
                    });
                } else if (previewRows.length > 0) {
                    res = await fetch('api.php?action=execute_sale_import', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            rows: previewRows,
                            branch_id: targetBranchId
                        })
                    });
                }

                const rawRes = await res.text();
                let data;
                try {
                    data = JSON.parse(rawRes);
                } catch (eParse) {
                    throw new Error('Respon server bukan JSON: ' + (rawRes ? rawRes.substring(0, 150) : 'Kosong (HTTP ' + res.status + ')'));
                }

                btnSubmit.disabled = false;
                btnSubmit.innerHTML = '<i data-lucide="zap" class="w-4 h-4"></i><span>Eksekusi Import &amp; Potong Stok Sekarang</span>';
                if (window.lucide) lucide.createIcons();

                alert(data.message || (data.success ? 'Eksekusi transaksi berhasil diproses!' : 'Gagal mengeksekusi import penjualan'));

                if (data.success) {
                    closeSaleImportModal();
                    if (typeof loadSalesReports === 'function') {
                        loadSalesReports();
                    }
                    if (typeof loadStockData === 'function') {
                        loadStockData();
                    }
                    if (typeof initApp === 'function') {
                        await initApp();
                    }
                }
            } catch (err) {
                btnSubmit.disabled = false;
                btnSubmit.innerHTML = '<i data-lucide="zap" class="w-4 h-4"></i><span>Eksekusi Import &amp; Potong Stok Sekarang</span>';
                if (window.lucide) lucide.createIcons();
                alert('Terjadi kesalahan jaringan saat mengeksekusi import penjualan: ' + err.message);
            }
        }

        // SUBTAB 2: HARGA KONTRAK MITRA (Setiap mitra harga berbeda)
        async function switchDirectToMitraContract(partnerId) {
            setCustomerSubtab('mitra-pricing');
            const select = document.getElementById('mitra-pricing-partner-select');
            if (select) {
                select.value = partnerId;
            }
            await loadMitraPricing(partnerId);
        }

        async function loadMitraPricing(targetPartnerId = null) {
            try {
                if (!state.customers || state.customers.length === 0) {
                    const cres = await fetch('api.php?action=get_customers&category=ALL');
                    const cdata = await cres.json();
                    if (cdata.success) state.customers = cdata.customers || [];
                }

                if (!state.products || state.products.length === 0) {
                    const pres = await fetch('api.php?action=bootstrap');
                    const pdata = await pres.json();
                    if (pdata.success) state.products = pdata.products || [];
                }

                // Populate Mitra Partner Dropdown
                const partnerSelect = document.getElementById('mitra-pricing-partner-select');
                const mitraPartners = (state.customers || []).filter(c => c.category === 'MITRA');

                if (mitraPartners.length === 0) {
                    partnerSelect.innerHTML = '<option value="">Tidak ada Mitra B2B terdaftar</option>';
                    document.getElementById('mitra-pricing-table-body').innerHTML = `
                        <tr><td colspan="6" class="text-center py-8 text-slate-400">Belum ada mitra rekanan B2B. Daftarkan mitra baru di tab Data Pelanggan.</td></tr>
                    `;
                    return;
                }

                const currentPartnerId = targetPartnerId ? parseInt(targetPartnerId) : (partnerSelect.value ? parseInt(partnerSelect.value) : mitraPartners[0].id);
                partnerSelect.innerHTML = mitraPartners.map(m => `
                    <option value="${m.id}" ${m.id === currentPartnerId ? 'selected' : ''}>${m.name} (${m.code})</option>
                `).join('');
                partnerSelect.value = currentPartnerId;

                const selectedPartner = mitraPartners.find(m => m.id === currentPartnerId) || mitraPartners[0];

                // Fetch custom contract prices for this mitra
                const res = await fetch(`api.php?action=get_mitra_prices&customer_id=${selectedPartner.id}`);
                const data = await res.json();
                const contractPrices = (data.success && data.prices) ? data.prices : [];

                // Render table: all finished goods products
                const tbody = document.getElementById('mitra-pricing-table-body');
                const products = state.products || [];

                tbody.innerHTML = products.map(p => {
                    const custom = contractPrices.find(cp => cp.product_id === p.id);
                    const defaultRetail = Number(p.selling_price);
                    const defaultMitra = Number(p.mitra_price > 0 ? p.mitra_price : defaultRetail);
                    const isContractSet = custom && Number(custom.custom_price) > 0;
                    const contractPrice = isContractSet ? Number(custom.custom_price) : defaultMitra;

                    return `
                        <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                            <td class="py-3 px-4 font-bold text-slate-900 dark:text-slate-100">${p.image_emoji || '📦'} ${p.name}</td>
                            <td class="py-3 px-4 font-mono text-slate-500 dark:text-slate-400">${p.sku}</td>
                            <td class="py-3 px-4 text-right text-slate-600 dark:text-slate-300 font-semibold">${formatRupiah(defaultRetail)}</td>
                            <td class="py-3 px-4 text-right font-black ${isContractSet ? 'text-emerald-700 dark:text-emerald-400 text-sm' : 'text-slate-400 dark:text-slate-500'}">
                                ${formatRupiah(contractPrice)}
                            </td>
                            <td class="py-3 px-4 text-center">
                                ${isContractSet ? 
                                    '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-800">✅ Kontrak Aktif</span>' :
                                    '<span class="px-2 py-0.5 rounded-full text-[10px] font-medium bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700" title="Belum diset kontrak. Produk ini tidak akan dimunculkan di menu POS untuk mitra ini.">⚪ Belum Diset (Tidak Tampil di POS)</span>'
                                }
                            </td>
                            <td class="py-3 px-4 text-center">
                                <div class="flex items-center justify-center space-x-1">
                                    <button onclick="openMitraPriceModal(${p.id}, ${contractPrice})" class="px-2.5 py-1 bg-indigo-50 dark:bg-indigo-950/60 hover:bg-indigo-600 dark:hover:bg-indigo-900/60 hover:text-white text-indigo-700 dark:text-indigo-300 font-bold text-[11px] rounded-lg border border-indigo-200 dark:border-indigo-800 transition-colors shadow-2xs">
                                        ${isContractSet ? 'Edit Kontrak' : '+ Set Kontrak'}
                                    </button>
                                    ${isContractSet ? `
                                        <button onclick="deleteMitraPrice(${custom.id})" title="Hapus Kontrak Khusus" class="p-1 text-slate-400 hover:text-rose-600 rounded-lg">
                                            <i data-lucide="rotate-ccw" class="w-3.5 h-3.5"></i>
                                        </button>
                                    ` : ''}
                                </div>
                            </td>
                        </tr>
                    `;
                }).join('');

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function onMitraPartnerSelectChange() {
            loadMitraPricing();
        }

        function openMitraPriceModal(productId = null, currentPrice = null) {
            const partnerSelect = document.getElementById('mitra-pricing-partner-select');
            const mitraPartners = (state.customers || []).filter(c => c.category === 'MITRA');
            
            if (mitraPartners.length === 0) {
                alert('Belum ada mitra rekanan B2B yang terdaftar. Silakan tambahkan pelanggan dengan kategori MITRA terlebih dahulu.');
                return;
            }

            const activePartnerId = partnerSelect && partnerSelect.value ? parseInt(partnerSelect.value) : mitraPartners[0].id;

            // Populate Mitra Partner select in modal
            const modalPartnerSelect = document.getElementById('mp-customer-id-select');
            if (modalPartnerSelect) {
                modalPartnerSelect.innerHTML = mitraPartners.map(m => `
                    <option value="${m.id}" ${m.id === activePartnerId ? 'selected' : ''}>${m.name} (${m.code})</option>
                `).join('');
                modalPartnerSelect.value = activePartnerId;
            }

            document.getElementById('mp-customer-id').value = activePartnerId;
            const selectedPartner = mitraPartners.find(m => m.id === activePartnerId) || mitraPartners[0];
            document.getElementById('mp-modal-partner-desc').innerText = `Mitra: ${selectedPartner.name} (${selectedPartner.code})`;

            const prodSelect = document.getElementById('mp-product-select');
            prodSelect.innerHTML = state.products.map(p => `
                <option value="${p.id}" ${productId && p.id === productId ? 'selected' : ''}>${p.image_emoji || '📦'} ${p.name} (${p.sku})</option>
            `).join('');

            if (productId) {
                prodSelect.value = productId;
            }

            onMpProductSelectChange();
            if (currentPrice) {
                document.getElementById('mp-custom-price').value = currentPrice;
            }

            document.getElementById('mitra-price-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function onMpPartnerSelectChange() {
            const modalPartnerSelect = document.getElementById('mp-customer-id-select');
            const pId = parseInt(modalPartnerSelect.value);
            document.getElementById('mp-customer-id').value = pId;
            const mitraPartners = (state.customers || []).filter(c => c.category === 'MITRA');
            const partner = mitraPartners.find(m => m.id === pId);
            if (partner) {
                document.getElementById('mp-modal-partner-desc').innerText = `Mitra: ${partner.name} (${partner.code})`;
            }
        }

        function closeMitraPriceModal() {
            document.getElementById('mitra-price-modal').classList.add('hidden');
        }

        function onMpProductSelectChange() {
            const pId = parseInt(document.getElementById('mp-product-select').value);
            const p = state.products.find(pr => pr.id === pId);
            if (!p) return;

            const defaultRetail = Number(p.selling_price);
            const defaultMitra = Number(p.mitra_price > 0 ? p.mitra_price : defaultRetail);

            document.getElementById('mp-info-retail').innerText = formatRupiah(defaultRetail);
            document.getElementById('mp-info-mitra-default').innerText = formatRupiah(defaultMitra);
            if (!document.getElementById('mp-custom-price').value || document.getElementById('mp-custom-price').value == 0) {
                document.getElementById('mp-custom-price').value = defaultMitra;
            }
        }

        async function saveMitraPriceForm(e) {
            e.preventDefault();
            const customerId = parseInt(document.getElementById('mp-customer-id').value) || parseInt(document.getElementById('mp-customer-id-select').value);
            const productId = parseInt(document.getElementById('mp-product-select').value);
            const customPrice = parseFloat(document.getElementById('mp-custom-price').value);

            if (!customerId || !productId || customPrice <= 0) {
                alert('Pilih mitra, produk, dan isi harga kontrak khusus yang valid!');
                return;
            }

            const payload = {
                customer_id: customerId,
                product_id: productId,
                custom_price: customPrice,
                notes: document.getElementById('mp-notes').value
            };

            const res = await fetch('api.php?action=save_mitra_price', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeMitraPriceModal();
                // Ensure page partner select matches
                const partnerSelect = document.getElementById('mitra-pricing-partner-select');
                if (partnerSelect) partnerSelect.value = customerId;
                loadMitraPricing();
                initApp();
            }
        }

        async function deleteMitraPrice(id) {
            if (!confirm('Kembalikan harga jual produk ini ke harga tier mitra default?')) return;
            const res = await fetch('api.php?action=delete_mitra_price', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadMitraPricing();
                initApp();
            }
        }

        // SUBTAB 3: HARGA JUAL ANTAR CABANG (Setiap branch harga berbeda)
        async function loadBranchPricing() {
            try {
                if (!state.branches || state.branches.length === 0) {
                    const bres = await fetch('api.php?action=bootstrap');
                    const bdata = await bres.json();
                    if (bdata.success) {
                        state.branches = bdata.branches || [];
                        state.products = bdata.products || [];
                    }
                }

                const branchSelect = document.getElementById('branch-pricing-branch-select');
                const canAccessAll = canUserAccessAllBranches();
                const userBranch = getUserAssignedBranch();
                let currentBranchId = userBranch.id;

                if (!canAccessAll) {
                    branchSelect.innerHTML = `<option value="${userBranch.id}" selected>🔒 ${userBranch.name}</option>`;
                    branchSelect.disabled = true;
                    branchSelect.value = userBranch.id;
                    currentBranchId = userBranch.id;
                } else {
                    branchSelect.disabled = false;
                    currentBranchId = branchSelect.value ? parseInt(branchSelect.value) : (state.currentBranch ? state.currentBranch.id : 1);
                    branchSelect.innerHTML = (state.branches || []).map(b => `
                        <option value="${b.id}" ${b.id === currentBranchId ? 'selected' : ''}>${b.name}</option>
                    `).join('');
                }

                const res = await fetch(`api.php?action=get_inventory_stocks&branch_id=${currentBranchId}&product_type=FINISHED_GOODS`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const stocks = data.stocks || [];
                const tbody = document.getElementById('branch-pricing-table-body');

                if (stocks.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="9" class="text-center py-8 text-slate-400">Tidak ada produk ditemukan</td></tr>`;
                    return;
                }

                tbody.innerHTML = stocks.map(st => {
                    const cogs = Number(st.local_cogs);
                    const price = Number(st.local_price);
                    const margin = price > 0 ? Math.round(((price - cogs) / price) * 100) : 0;
                    const isActive = Number(_nn(st.is_active, 1)) === 1;

                    // Hitung status pengiriman cabang (0 = Standar, 1 = Wajib Ongkir, 2 = Termasuk Biaya Kirim)
                    let currentDelivMode = 0;
                    if (Number(st.is_delivery_included) === 1 || Number(st.is_delivery_required) === 2) {
                        currentDelivMode = 2;
                    } else if (Number(st.is_delivery_required) === 1) {
                        currentDelivMode = 1;
                    }
                    const nextDelivMode = (currentDelivMode === 0) ? 1 : ((currentDelivMode === 1) ? 2 : 0);

                    let delivBadgeClass = 'bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700 border-slate-300 hover:bg-slate-200';
                    let delivBadgeText = '⚪ Standar Toko';
                    if (currentDelivMode === 2) {
                        delivBadgeClass = 'bg-emerald-100 dark:bg-emerald-950/80 text-emerald-900 dark:text-emerald-300 border-emerald-300 dark:border-emerald-800 hover:bg-emerald-200 dark:hover:bg-emerald-900/60';
                        delivBadgeText = '🎁 Termasuk Kirim';
                    } else if (currentDelivMode === 1) {
                        delivBadgeClass = 'bg-amber-100 dark:bg-amber-950/80 text-amber-900 dark:text-amber-300 border-amber-300 dark:border-amber-800 hover:bg-amber-200 dark:hover:bg-amber-900/60';
                        delivBadgeText = '🚚 Wajib Ongkir';
                    }

                    return `
                        <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors ${!isActive ? 'bg-slate-50/70 dark:bg-slate-800/30 opacity-75' : ''}">
                            <td class="py-3 px-4 font-bold text-slate-900 dark:text-slate-100">
                                <div class="flex items-center space-x-2">
                                    <span class="text-base">${st.image_emoji || '📦'}</span>
                                    <div>
                                        <div class="${!isActive ? 'line-through text-slate-500 dark:text-slate-400' : ''}">${st.name}</div>
                                        ${!isActive ? '<span class="text-[10px] font-bold text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-950/60 px-1.5 py-0.5 rounded border border-rose-200 dark:border-rose-800">Nonaktif di Cabang</span>' : ''}
                                    </div>
                                </div>
                            </td>
                            <td class="py-3 px-4 font-mono text-slate-500 dark:text-slate-400">${st.sku}</td>
                            <td class="py-3 px-4 text-slate-600 dark:text-slate-300">${st.category}</td>
                            <td class="py-3 px-4 text-center">
                                <div class="inline-flex items-center space-x-2">
                                    <button onclick="toggleBranchProductStatus(${currentBranchId}, ${st.product_id}, ${isActive ? 0 : 1})" 
                                            title="${isActive ? 'Klik untuk nonaktifkan menu di cabang ini' : 'Klik untuk aktifkan menu di cabang ini'}"
                                            class="inline-flex items-center space-x-1.5 px-2.5 py-1 rounded-full text-[11px] font-bold border transition-colors cursor-pointer ${isActive ? 'bg-emerald-50 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-300 border-emerald-200 dark:border-emerald-800 hover:bg-emerald-100 dark:hover:bg-emerald-900/60' : 'bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700 border-slate-300 hover:bg-slate-200'}">
                                        <span class="w-2 h-2 rounded-full ${isActive ? 'bg-emerald-500' : 'bg-slate-400'}"></span>
                                        <span>${isActive ? 'Dijual (Aktif)' : 'Nonaktif'}</span>
                                    </button>
                                </div>
                            </td>
                            <td class="py-3 px-4 text-center">
                                <div class="inline-flex items-center space-x-2">
                                    <button onclick="toggleBranchProductDelivery(${currentBranchId}, ${st.product_id}, ${nextDelivMode})" 
                                            title="Mode Pengiriman Cabang: ${delivBadgeText}. Klik untuk ganti rotasi (Standar -> Wajib Ongkir -> Termasuk Kirim)."
                                            class="inline-flex items-center space-x-1.5 px-2.5 py-1 rounded-full text-[11px] font-bold border transition-colors cursor-pointer ${delivBadgeClass}">
                                        <span>${delivBadgeText}</span>
                                    </button>
                                </div>
                            </td>
                            <td class="py-3 px-4 text-right text-rose-700 dark:text-rose-400 font-semibold">${formatRupiah(cogs)}</td>
                            <td class="py-3 px-4 text-right font-black text-indigo-950 dark:text-indigo-200 text-sm">${formatRupiah(price)}</td>
                            <td class="py-3 px-4 text-right font-bold ${margin >= 40 ? 'text-emerald-700 dark:text-emerald-400' : 'text-amber-700 dark:text-amber-400'}">${margin}%</td>
                            <td class="py-3 px-4 text-center">
                                <button onclick="openBranchPriceModal(${st.product_id}, '${st.name.replace(/'/g, "\\'")}', ${cogs}, ${price}, ${isActive ? 1 : 0}, ${currentDelivMode})" class="px-2.5 py-1 bg-indigo-50 dark:bg-indigo-950/60 hover:bg-indigo-600 dark:hover:bg-indigo-900/60 hover:text-white text-indigo-700 dark:text-indigo-300 font-bold text-[11px] rounded-lg border border-indigo-200 dark:border-indigo-800 transition-colors shadow-2xs">
                                    Edit Menu & Harga
                                </button>
                            </td>
                        </tr>
                    `;
                }).join('');

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function onBranchPricingSelectChange() {
            loadBranchPricing();
        }

        async function toggleBranchProductStatus(branchId, productId, newStatus) {
            try {
                const res = await fetch('api.php?action=toggle_branch_product_status', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ branch_id: branchId, product_id: productId, is_active: newStatus })
                });
                const data = await res.json();
                if (data.success) {
                    loadBranchPricing();
                    // Jika cabang yang diubah adalah cabang aktif saat ini di POS kasir, muat ulang produk POS
                    if (state.currentBranch && state.currentBranch.id === branchId) {
                        initApp();
                    }
                } else {
                    alert(data.message || 'Gagal mengubah status menu cabang.');
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        async function toggleBranchProductDelivery(branchId, productId, newStatus) {
            try {
                const res = await fetch('api.php?action=toggle_branch_product_delivery', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ branch_id: branchId, product_id: productId, is_delivery_required: newStatus })
                });
                const data = await res.json();
                if (data.success) {
                    loadBranchPricing();
                    // Jika cabang yang diubah adalah cabang aktif saat ini di POS kasir, muat ulang produk POS
                    if (state.currentBranch && state.currentBranch.id === branchId) {
                        initApp();
                    }
                } else {
                    alert(data.message || 'Gagal mengubah pengaturan ongkir cabang.');
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        function onBpDeliveryModeChange() {
            const selectEl = document.getElementById('bp-delivery-mode');
            const badge = document.getElementById('bp-delivery-badge');
            if (!badge || !selectEl) return;
            const mode = selectEl.value;
            if (mode === '2') {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800';
                badge.innerText = '🎁 Free Ongkir';
            } else if (mode === '1') {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-amber-100 text-amber-800';
                badge.innerText = '🚚 Wajib Ongkir';
            } else if (mode === '0') {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700';
                badge.innerText = '⚪ Standar';
            } else {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700';
                badge.innerText = 'Default Master';
            }
        }

        async function openBranchPriceModal(productId = null, productName = null, cogs = null, currentPrice = null, isActive = 1, isDeliveryMode = null) {
            const branchSelect = document.getElementById('branch-pricing-branch-select');
            const branchId = branchSelect && branchSelect.value ? parseInt(branchSelect.value) : (state.currentBranch ? state.currentBranch.id : 1);

            // Populate branch dropdown in modal
            const modalBranchSelect = document.getElementById('bp-branch-id-select');
            if (modalBranchSelect) {
                modalBranchSelect.innerHTML = (state.branches || []).map(b => `
                    <option value="${b.id}" ${b.id === branchId ? 'selected' : ''}>${b.name}</option>
                `).join('');
                modalBranchSelect.value = branchId;
            }

            document.getElementById('bp-branch-id').value = branchId;
            const branchObj = (state.branches || []).find(b => b.id === branchId);
            const branchName = branchObj ? branchObj.name : 'Cabang';
            document.getElementById('bp-modal-branch-desc').innerText = `Cabang: ${branchName}`;

            // Checkbox status menu
            const activeCheckbox = document.getElementById('bp-is-active');
            if (activeCheckbox) activeCheckbox.checked = (isActive === 1);

            // Select delivery mode
            const delivSelect = document.getElementById('bp-delivery-mode');

            // Populate products dropdown in modal
            const prodSelect = document.getElementById('bp-product-select');
            const finishedGoods = (state.products || []).filter(p => p.product_type === 'FINISHED_GOODS' || !p.product_type);
            prodSelect.innerHTML = finishedGoods.map(p => `
                <option value="${p.id}" ${productId && p.id === productId ? 'selected' : ''}>${p.image_emoji || '📦'} ${p.name} (${p.sku})</option>
            `).join('');

            if (productId) {
                prodSelect.value = productId;
                document.getElementById('bp-product-id').value = productId;
                document.getElementById('bp-cogs').value = cogs || 0;
                document.getElementById('bp-local-price').value = currentPrice || 0;
                document.getElementById('bp-info-cogs-display').innerText = formatRupiah(cogs || 0);

                const pObj = finishedGoods.find(p => p.id === productId);
                document.getElementById('bp-info-central-retail').innerText = formatRupiah(pObj ? pObj.selling_price : currentPrice || 0);
                if (delivSelect) {
                    delivSelect.value = (isDeliveryMode !== null) ? isDeliveryMode.toString() : '';
                    onBpDeliveryModeChange();
                }
            } else {
                onBpProductSelectChange();
            }

            document.getElementById('branch-price-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function onBpBranchSelectChange() {
            const modalBranchSelect = document.getElementById('bp-branch-id-select');
            const branchId = parseInt(modalBranchSelect.value);
            document.getElementById('bp-branch-id').value = branchId;
            const branchObj = (state.branches || []).find(b => b.id === branchId);
            if (branchObj) {
                document.getElementById('bp-modal-branch-desc').innerText = `Cabang: ${branchObj.name}`;
            }
            onBpProductSelectChange();
        }

        async function onBpProductSelectChange() {
            const prodSelect = document.getElementById('bp-product-select');
            const productId = parseInt(prodSelect.value);
            const branchId = parseInt(document.getElementById('bp-branch-id').value) || 1;

            document.getElementById('bp-product-id').value = productId;

            const pObj = (state.products || []).find(p => p.id === productId);
            const defaultSelling = pObj ? Number(pObj.selling_price) : 0;
            const defaultCogs = pObj ? Number(pObj.cogs) : 0;

            document.getElementById('bp-info-central-retail').innerText = formatRupiah(defaultSelling);
            document.getElementById('bp-cogs').value = defaultCogs;
            document.getElementById('bp-info-cogs-display').innerText = formatRupiah(defaultCogs);

            const activeCheckbox = document.getElementById('bp-is-active');
            const delivSelect = document.getElementById('bp-delivery-mode');

            // Fetch current branch price if already exists
            try {
                const res = await fetch(`api.php?action=get_inventory_stocks&branch_id=${branchId}&product_type=FINISHED_GOODS`);
                const data = await res.json();
                if (data.success && data.stocks) {
                    const st = data.stocks.find(s => s.product_id === productId);
                    if (st) {
                        document.getElementById('bp-cogs').value = Number(st.local_cogs);
                        document.getElementById('bp-info-cogs-display').innerText = formatRupiah(Number(st.local_cogs));
                        document.getElementById('bp-local-price').value = Number(st.local_price);
                        if (activeCheckbox) activeCheckbox.checked = Number(_nn(st.is_active, 1)) === 1;
                        if (delivSelect) {
                            if (Number(st.is_delivery_included) === 1 || Number(st.is_delivery_required) === 2) {
                                delivSelect.value = '2';
                            } else if (Number(st.is_delivery_required) === 1) {
                                delivSelect.value = '1';
                            } else if (st.is_delivery_required !== null && st.is_delivery_required !== undefined) {
                                delivSelect.value = '0';
                            } else {
                                delivSelect.value = '';
                            }
                            onBpDeliveryModeChange();
                        }
                        return;
                    }
                }
            } catch (err) {
                console.error(err);
            }

            document.getElementById('bp-local-price').value = defaultSelling;
            if (activeCheckbox) activeCheckbox.checked = true;
            if (delivSelect) {
                delivSelect.value = '';
                onBpDeliveryModeChange();
            }
        }

        function closeBranchPriceModal() {
            document.getElementById('branch-price-modal').classList.add('hidden');
        }

        async function saveBranchPriceForm(e) {
            e.preventDefault();
            const branchId = parseInt(document.getElementById('bp-branch-id').value) || parseInt(document.getElementById('bp-branch-id-select').value);
            const productId = parseInt(document.getElementById('bp-product-id').value) || parseInt(document.getElementById('bp-product-select').value);
            const localPrice = parseFloat(document.getElementById('bp-local-price').value);
            const activeCheckbox = document.getElementById('bp-is-active');
            const isActive = activeCheckbox && activeCheckbox.checked ? 1 : 0;
            const delivSelect = document.getElementById('bp-delivery-mode');
            const delivVal = delivSelect ? delivSelect.value : '';

            let isDeliveryRequired = (delivVal === '') ? null : parseInt(delivVal);
            let isDeliveryIncluded = (delivVal === '2') ? 1 : (delivVal === '' ? null : 0);

            if (!branchId || !productId || localPrice <= 0) {
                alert('Pilih cabang, produk, dan isi harga jual cabang yang valid!');
                return;
            }

            const payload = {
                branch_id: branchId,
                product_id: productId,
                local_price: localPrice,
                is_active: isActive,
                is_delivery_required: isDeliveryRequired,
                is_delivery_included: isDeliveryIncluded
            };

            const res = await fetch('api.php?action=update_branch_product_price', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeBranchPriceModal();
                const branchSelect = document.getElementById('branch-pricing-branch-select');
                if (branchSelect) branchSelect.value = branchId;
                loadBranchPricing();
                initApp();
            }
        }

        // ========================================================
        // SUBTAB 4: MASTER KATEGORI PELANGGAN & STATUS AKTIF/NONAKTIF
        // ========================================================
        state.custCatStatusFilter = 'ALL';

        async function loadCustomerCategories() {
            try {
                const res = await fetch('api.php?action=get_customer_categories');
                const data = await res.json();
                if (data.success) {
                    state.customerCategories = data.customer_categories || [];
                    renderCustomerCategoriesTable();
                }
            } catch (err) {
                console.error('Gagal memuat kategori pelanggan:', err);
            }
        }

        function setCustCatStatusFilter(status) {
            state.custCatStatusFilter = status;
            document.querySelectorAll('.cust-cat-status-filter').forEach(btn => {
                btn.className = 'cust-cat-status-filter px-3 py-1.5 rounded-xl text-xs font-semibold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-200';
            });
            if (status === 'ALL') {
                const el = document.getElementById('filter-cust-cat-all');
                if (el) el.className = 'cust-cat-status-filter px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white';
            } else if (status === 'ACTIVE') {
                const el = document.getElementById('filter-cust-cat-active');
                if (el) el.className = 'cust-cat-status-filter px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white';
            } else if (status === 'INACTIVE') {
                const el = document.getElementById('filter-cust-cat-inactive');
                if (el) el.className = 'cust-cat-status-filter px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white';
            }
            renderCustomerCategoriesTable();
        }

        function renderCustomerCategoriesTable() {
            const tbody = document.getElementById('customer-categories-table-body');
            if (!tbody) return;

            let cats = state.customerCategories || [];
            const kw = (_val('cust-cat-search-keyword') || '').toLowerCase().trim();

            if (state.custCatStatusFilter === 'ACTIVE') {
                cats = cats.filter(c => c.is_active == 1);
            } else if (state.custCatStatusFilter === 'INACTIVE') {
                cats = cats.filter(c => c.is_active == 0);
            }

            if (kw) {
                cats = cats.filter(c => 
                    (c.name && c.name.toLowerCase().includes(kw)) ||
                    (c.code && c.code.toLowerCase().includes(kw)) ||
                    (c.default_tier && c.default_tier.toLowerCase().includes(kw)) ||
                    (c.description && c.description.toLowerCase().includes(kw))
                );
            }

            if (cats.length === 0) {
                tbody.innerHTML = `<tr><td colspan="7" class="text-center py-8 text-slate-400">Tidak ada kategori pelanggan yang cocok</td></tr>`;
                return;
            }

            tbody.innerHTML = cats.map(cat => {
                const isActive = (cat.is_active == 1);
                
                // Tier badge styling
                let tierBadge = '<span class="px-2.5 py-1 rounded-xl text-[11px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">👤 Ritel Reguler</span>';
                if (cat.default_tier === 'MEMBER') {
                    tierBadge = '<span class="px-2.5 py-1 rounded-xl text-[11px] font-bold bg-purple-100 text-purple-800">⭐ Member VIP</span>';
                } else if (cat.default_tier === 'RESELLER') {
                    tierBadge = '<span class="px-2.5 py-1 rounded-xl text-[11px] font-bold bg-amber-100 text-amber-800">🛍️ Reseller / Grosir</span>';
                } else if (cat.default_tier === 'MITRA') {
                    tierBadge = '<span class="px-2.5 py-1 rounded-xl text-[11px] font-bold bg-emerald-100 text-emerald-800">🏢 Kontrak Mitra B2B</span>';
                }

                // Active toggle switch
                const toggleSwitch = `
                    <div class="flex items-center justify-center space-x-2">
                        <span class="text-[10px] font-bold ${isActive ? 'text-emerald-700' : 'text-slate-400'}">${isActive ? 'Aktif' : 'Nonaktif'}</span>
                        <label class="relative inline-flex items-center cursor-pointer">
                            <input type="checkbox" ${isActive ? 'checked' : ''} onchange="toggleCustomerCategoryStatus(${cat.id}, this.checked ? 1 : 0)" class="sr-only peer">
                            <div class="w-9 h-5 bg-slate-300 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-emerald-600"></div>
                        </label>
                    </div>
                `;

                const activeCustCount = cat.active_customer_count !== undefined ? Number(cat.active_customer_count) : 0;
                const totalCustCount = cat.total_customer_count !== undefined ? Number(cat.total_customer_count) : activeCustCount;

                // Escaped JSON for edit button
                const catJson = JSON.stringify(cat).replace(/"/g, '&quot;');

                return `
                    <tr class="hover:bg-slate-50 transition-colors ${!isActive ? 'opacity-60 bg-slate-50/50' : ''}">
                        <td class="py-3.5 px-4 font-bold text-slate-900">
                            <div class="flex items-center space-x-2.5">
                                <span class="p-2 bg-slate-100 dark:bg-slate-800 rounded-xl text-base border border-slate-200 dark:border-slate-700">${cat.icon_emoji || '👥'}</span>
                                <div>
                                    <p class="font-bold text-slate-900 text-xs">${cat.name}</p>
                                    <p class="text-[10px] text-slate-400 font-normal">ID: #${cat.id}</p>
                                </div>
                            </div>
                        </td>
                        <td class="py-3.5 px-4">
                            <span class="px-2.5 py-1 bg-slate-100 dark:bg-slate-800 font-mono font-bold text-slate-800 dark:text-slate-200 rounded-lg text-xs border border-slate-200 dark:border-slate-700">${cat.code}</span>
                        </td>
                        <td class="py-3.5 px-4">${tierBadge}</td>
                        <td class="py-3.5 px-4 text-slate-600 max-w-xs truncate" title="${cat.description || '-'}">${cat.description || '-'}</td>
                        <td class="py-3.5 px-4 text-center">
                            <span class="px-2.5 py-1 bg-indigo-50 text-indigo-700 font-bold rounded-full text-xs">
                                ${activeCustCount} org
                            </span>
                        </td>
                        <td class="py-3.5 px-4 text-center">${toggleSwitch}</td>
                        <td class="py-3.5 px-4 text-center">
                            <div class="flex items-center justify-center space-x-1.5">
                                <button onclick="openCustomerCategoryModal(${catJson})" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-indigo-50 dark:hover:bg-indigo-950/50 hover:text-indigo-600 dark:hover:text-indigo-400 text-slate-600 dark:text-slate-300 rounded-lg transition-colors border border-slate-200 dark:border-slate-700" title="Edit Kategori">
                                    <i data-lucide="edit-3" class="w-4 h-4"></i>
                                </button>
                                <button onclick="deleteCustomerCategory(${cat.id}, '${cat.name.replace(/'/g, "\\'")}', ${activeCustCount})" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-rose-50 dark:hover:bg-rose-950/50 hover:text-rose-600 dark:hover:text-rose-400 text-slate-600 dark:text-slate-300 rounded-lg transition-colors border border-slate-200 dark:border-slate-700" title="Hapus Kategori">
                                    <i data-lucide="trash-2" class="w-4 h-4"></i>
                                </button>
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');

            lucide.createIcons();
        }

        function openCustomerCategoryModal(cat = null) {
            const modal = document.getElementById('customer-category-modal');
            const title = document.getElementById('cust-cat-modal-title');
            const badge = document.getElementById('cust-cat-modal-badge');
            const isEdit = !!cat;

            if (isEdit) {
                title.innerText = 'Edit Kategori Pelanggan';
                badge.innerText = cat.icon_emoji || '👥';
                document.getElementById('cust-cat-id').value = cat.id;
                document.getElementById('cust-cat-emoji').value = cat.icon_emoji || '👥';
                document.getElementById('cust-cat-code').value = cat.code;
                document.getElementById('cust-cat-name').value = cat.name;
                document.getElementById('cust-cat-tier').value = cat.default_tier || 'REGULER';
                document.getElementById('cust-cat-desc').value = cat.description || '';
                document.getElementById('cust-cat-is-active').checked = (cat.is_active == 1);
            } else {
                title.innerText = 'Tambah Kategori Pelanggan Baru';
                badge.innerText = '👥';
                document.getElementById('cust-cat-id').value = '';
                document.getElementById('cust-cat-emoji').value = '👥';
                document.getElementById('cust-cat-code').value = '';
                document.getElementById('cust-cat-name').value = '';
                document.getElementById('cust-cat-tier').value = 'REGULER';
                document.getElementById('cust-cat-desc').value = '';
                document.getElementById('cust-cat-is-active').checked = true;
            }

            onCustomerCatStatusToggleChange();
            modal.classList.remove('hidden');
        }

        function closeCustomerCategoryModal() {
            document.getElementById('customer-category-modal').classList.add('hidden');
        }

        function onCustomerCatStatusToggleChange() {
            const chk = document.getElementById('cust-cat-is-active');
            const lbl = document.getElementById('cust-cat-status-label');
            if (chk.checked) {
                lbl.innerText = 'Aktif (Dapat digunakan transaksi & pendaftaran)';
                lbl.className = 'text-[11px] text-emerald-600 font-semibold';
            } else {
                lbl.innerText = 'Nonaktif (Disembunyikan dari pendaftaran & kasir)';
                lbl.className = 'text-[11px] text-rose-600 font-semibold';
            }
        }

        async function saveCustomerCategoryForm(e) {
            e.preventDefault();
            const id = document.getElementById('cust-cat-id').value;
            const code = document.getElementById('cust-cat-code').value.trim().toUpperCase();
            const name = document.getElementById('cust-cat-name').value.trim();
            const defaultTier = document.getElementById('cust-cat-tier').value;
            const description = document.getElementById('cust-cat-desc').value.trim();
            const iconEmoji = document.getElementById('cust-cat-emoji').value.trim() || '👥';
            const isActive = document.getElementById('cust-cat-is-active').checked ? 1 : 0;

            if (!name) {
                alert('Nama kategori pelanggan wajib diisi!');
                return;
            }

            const payload = {
                id: id ? parseInt(id) : null,
                code: code,
                name: name,
                default_tier: defaultTier,
                description: description,
                icon_emoji: iconEmoji,
                is_active: isActive
            };

            try {
                const res = await fetch('api.php?action=save_customer_category', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    closeCustomerCategoryModal();
                    await loadCustomerCategories();
                    await initApp();
                    renderPosTierButtons();
                    renderPosCustomerSelect();
                    recalculateCartPrices();
                    renderProducts();
                }
            } catch (err) {
                alert('Gagal menyimpan kategori: ' + err.message);
            }
        }

        async function toggleCustomerCategoryStatus(id, newStatus) {
            try {
                const res = await fetch('api.php?action=toggle_customer_category_status', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id, is_active: newStatus })
                });
                const data = await res.json();
                if (!data.success) {
                    alert(data.message || 'Gagal mengubah status kategori');
                }
                await loadCustomerCategories();
                await initApp();
                renderPosTierButtons();
                renderPosCustomerSelect();
                recalculateCartPrices();
                renderProducts();
            } catch (err) {
                console.error(err);
                alert('Gagal mengubah status: ' + err.message);
                loadCustomerCategories();
            }
        }

        async function deleteCustomerCategory(id, name, activeCount) {
            if (activeCount > 0) {
                if (confirm(`Kategori '${name}' sedang digunakan oleh ${activeCount} pelanggan aktif.\nKategori tidak dapat dihapus permanen.\n\nApakah Anda ingin menonaktifkan status kategori ini saja?`)) {
                    toggleCustomerCategoryStatus(id, 0);
                }
                return;
            }

            if (!confirm(`Apakah Anda yakin ingin menghapus kategori '${name}'?`)) return;

            try {
                const res = await fetch('api.php?action=delete_customer_category', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    await loadCustomerCategories();
                    await initApp();
                    renderPosTierButtons();
                    renderPosCustomerSelect();
                    recalculateCartPrices();
                    renderProducts();
                }
            } catch (err) {
                alert('Gagal menghapus kategori: ' + err.message);
            }
        }

        // ========================================================
        // MODUL 10: KURIR, LOGISTIK, PETA GEOSPASIAL & ARMADA MOTOR
        // ========================================================
        function setLogisticsSubtab(subtab) {
            state.logisticsActiveSubtab = subtab;
            const subtabs = [
                { key: 'vehicles', viewId: 'subtab-logistics-vehicles', btnId: 'subtab-btn-vehicles' },
                { key: 'fuel', viewId: 'subtab-logistics-fuel', btnId: 'subtab-btn-fuel' },
                { key: 'service', viewId: 'subtab-logistics-service', btnId: 'subtab-btn-service' },
                { key: 'settings', viewId: 'subtab-logistics-settings', btnId: 'subtab-btn-settings' },
                { key: 'maps', viewId: 'subtab-logistics-maps', btnId: 'subtab-btn-maps' }
            ];

            const activeClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-indigo-600 text-white shadow-2xs';
            const inactiveClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-slate-100 hover:bg-slate-200/80 text-slate-700 hover:text-slate-900 dark:bg-slate-800 dark:hover:bg-slate-700 dark:text-slate-300 dark:hover:text-white border border-transparent dark:border-slate-700';

            subtabs.forEach(item => {
                const view = document.getElementById(item.viewId);
                const btn = document.getElementById(item.btnId);
                if (item.key === subtab) {
                    if (view) view.classList.remove('hidden');
                    if (btn) btn.className = activeClass;
                } else {
                    if (view) view.classList.add('hidden');
                    if (btn) btn.className = inactiveClass;
                }
            });

            if (subtab === 'vehicles') loadVehicles();
            if (subtab === 'fuel') loadFuelLogs();
            if (subtab === 'service') loadServiceLogs();
            if (subtab === 'settings') loadDeliverySettings();
            if (subtab === 'maps') {
                setTimeout(() => {
                    initLogisticsMap();
                }, 150);
            }
            lucide.createIcons();
        }

        // Alias for compatibility
        function switchLogisticsSubtab(subtab) {
            setLogisticsSubtab(subtab);
        }

        async function loadLogisticsData() {
            setLogisticsSubtab(state.logisticsActiveSubtab || 'vehicles');
        }

        // --- SUBTAB 1: ARMADA KENDARAAN KURIR ---
        async function loadVehicles() {
            try {
                const curUser = state.currentUser || state.loggedInUser || {};
                const rawRole = ((curUser.role || 'CASHIER') + '').toUpperCase().replace(/_/g, '').trim();
                const isSuperAdmin = (rawRole === 'SUPERADMIN' || rawRole === 'SUPER ADMIN');
                const isManager = isSuperAdmin || rawRole === 'BRANCHMANAGER' || rawRole === 'MANAGER';
                const userBranchId = curUser.branch_id || (state.currentBranch ? state.currentBranch.id : 1);

                // Populate Branch Filter for Vehicles
                const branchFilter = document.getElementById('vehicle-branch-filter');
                if (branchFilter) {
                    if (!isSuperAdmin && !isManager) {
                        const myBranch = (state.branches || []).find(b => b.id == userBranchId) || state.currentBranch || { id: userBranchId, name: 'Cabang Penugasan' };
                        branchFilter.innerHTML = `<option value="${userBranchId}">📍 ${escapeHtml(myBranch.name)} (Terkunci)</option>`;
                        branchFilter.value = userBranchId;
                        branchFilter.disabled = true;
                        branchFilter.classList.add('opacity-75', 'cursor-not-allowed', 'bg-slate-100');
                    } else if (isManager) {
                        let myBranches = [];
                        if (curUser.assigned_branch_ids) {
                            try {
                                const parsed = typeof curUser.assigned_branch_ids === 'string' ? JSON.parse(curUser.assigned_branch_ids) : curUser.assigned_branch_ids;
                                if (Array.isArray(parsed) && parsed.length > 0) {
                                    myBranches = (state.branches || []).filter(b => parsed.indexOf(parseInt(b.id, 10)) !== -1);
                                }
                            } catch(e) {}
                        }
                        if (myBranches.length === 0) {
                            myBranches = (state.branches || []).filter(b => b.id == userBranchId);
                        }
                        if (myBranches.length > 1) {
                            const curVal = branchFilter.value || 'ALL';
                            branchFilter.innerHTML = '<option value="ALL">Semua Cabang Ditugaskan</option>' + 
                                myBranches.map(b => `<option value="${b.id}" ${curVal == b.id ? 'selected' : ''}>${escapeHtml(b.name)}</option>`).join('');
                            branchFilter.disabled = false;
                            branchFilter.classList.remove('opacity-75', 'cursor-not-allowed', 'bg-slate-100');
                        } else {
                            const bObj = myBranches[0] || (state.branches || []).find(b => b.id == userBranchId) || state.currentBranch || { id: userBranchId, name: 'Cabang Penugasan' };
                            branchFilter.innerHTML = `<option value="${bObj.id}">📍 ${escapeHtml(bObj.name)}</option>`;
                            branchFilter.value = userBranchId;
                            branchFilter.disabled = true;
                            branchFilter.classList.add('opacity-75', 'cursor-not-allowed', 'bg-slate-100');
                        }
                    } else {
                        // Super Admin
                        const curBranchVal = branchFilter.value || 'ALL';
                        let bOpts = '<option value="ALL">Semua Cabang</option>';
                        (state.branches || []).forEach(b => {
                            bOpts += `<option value="${b.id}" ${curBranchVal == b.id ? 'selected' : ''}>${escapeHtml(b.name)}</option>`;
                        });
                        branchFilter.innerHTML = bOpts;
                        branchFilter.disabled = false;
                        branchFilter.classList.remove('opacity-75', 'cursor-not-allowed', 'bg-slate-100');
                    }
                }

                let reqBranchId = branchFilter ? branchFilter.value : 'ALL';
                if (!isSuperAdmin && !isManager) {
                    reqBranchId = userBranchId;
                }

                let url = 'api.php?action=get_courier_vehicles';
                if (curUser && curUser.id) url += '&user_id=' + encodeURIComponent(curUser.id);
                if (reqBranchId) url += '&branch_id=' + encodeURIComponent(reqBranchId);

                const res = await fetch(url);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                state.vehicles = data.vehicles || [];

                if (!isSuperAdmin && !isManager) {
                    state.vehicles = state.vehicles.filter(v => v.branch_id == userBranchId);
                }

                // Update KPIs
                const totalVehicles = state.vehicles.length;
                const activeBikes = state.vehicles.filter(v => v.vehicle_type === 'MOTOR' && v.status === 'ACTIVE').length;
                const activeCars = state.vehicles.filter(v => v.vehicle_type === 'MOBIL' && v.status === 'ACTIVE').length;

                const kpiTotal = document.getElementById('logistics-kpi-vehicles');
                const kpiActive = document.getElementById('logistics-kpi-active');
                if (kpiTotal) kpiTotal.innerText = totalVehicles;
                if (kpiActive) kpiActive.innerText = `${activeBikes} Motor / ${activeCars} Mobil`;

                renderVehiclesTable();
                renderPosCourierSelect();
                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function renderVehiclesTable() {
            const tbody = document.getElementById('vehicles-table-body');
            if (!tbody) return;

            const searchInput = document.getElementById('vehicle-search');
            const searchVal = searchInput ? searchInput.value.trim().toLowerCase() : '';

            const curUser = state.currentUser || state.loggedInUser || {};
            const rawRole = ((curUser.role || 'CASHIER') + '').toUpperCase().replace(/_/g, '').trim();
            const isSuperAdmin = (rawRole === 'SUPERADMIN' || rawRole === 'SUPER ADMIN');
            const isManager = isSuperAdmin || rawRole === 'BRANCHMANAGER' || rawRole === 'MANAGER';
            const userBranchId = curUser.branch_id || (state.currentBranch ? state.currentBranch.id : 1);

            const branchFilter = document.getElementById('vehicle-branch-filter');
            let branchVal = branchFilter ? branchFilter.value : 'ALL';
            if (!isSuperAdmin && !isManager) {
                branchVal = userBranchId;
            }

            let filtered = state.vehicles || [];
            if (branchVal !== 'ALL') {
                filtered = filtered.filter(v => v.branch_id == branchVal);
            }
            if (searchVal) {
                filtered = filtered.filter(v => 
                    (v.plate_number && v.plate_number.toLowerCase().includes(searchVal)) ||
                    (v.vehicle_name && v.vehicle_name.toLowerCase().includes(searchVal)) ||
                    (v.driver_name && v.driver_name.toLowerCase().includes(searchVal))
                );
            }

            if (filtered.length === 0) {
                tbody.innerHTML = `<tr><td colspan="8" class="text-center py-8 text-slate-400">Tidak ada armada kurir terdaftar${searchVal ? ' yang cocok dengan pencarian' : ''}. Klik "+ Tambah Kendaraan Kurir" untuk mendaftarkan motor/mobil.</td></tr>`;
                return;
            }

            tbody.innerHTML = filtered.map(v => {
                const _foundBr = state.branches.find(b => b.id === v.branch_id);
                const branchName = (_foundBr ? _foundBr.name : 'Semua Cabang');
                const ratioText = (v.fuel_ratio_unit === 'METER_PER_LITER') ? `${formatDecimal(v.fuel_ratio)} m/L` : `${formatDecimal(v.fuel_ratio)} km/L`;
                
                let statusBadge = '';
                if (v.status === 'ACTIVE') {
                    statusBadge = '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-800">✅ Aktif Operasional</span>';
                } else if (v.status === 'MAINTENANCE') {
                    statusBadge = '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 dark:bg-amber-950/80 text-amber-800 dark:text-amber-300 border border-amber-300 dark:border-amber-800">🔧 Sedang Servis</span>';
                } else {
                    statusBadge = '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-300 dark:border-slate-700">Nonaktif</span>';
                }

                return `
                    <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                        <td class="py-3 px-4">
                            <span class="font-mono font-black text-indigo-950 dark:text-indigo-200 px-2 py-1 bg-indigo-50 dark:bg-indigo-950/60 border border-indigo-200 dark:border-indigo-800 rounded-lg text-xs tracking-wider">${v.plate_number}</span>
                        </td>
                        <td class="py-3 px-4 font-bold text-slate-800 dark:text-slate-100">
                            <span>${v.vehicle_type === 'MOTOR' ? '🛵' : '🚚'} ${v.vehicle_name}</span>
                        </td>
                        <td class="py-3 px-4 text-slate-600 dark:text-slate-300 font-medium">${v.driver_name || '-'}</td>
                        <td class="py-3 px-4 text-slate-600 dark:text-slate-300">${branchName}</td>
                        <td class="py-3 px-4 font-mono font-bold text-slate-800 dark:text-slate-200 text-right">${Number(v.current_odometer).toLocaleString('id-ID')} km</td>
                        <td class="py-3 px-4 text-center">
                            <span class="font-mono font-bold text-amber-700 dark:text-amber-400 bg-amber-50 dark:bg-amber-950/60 px-2 py-0.5 rounded-md border border-amber-200 dark:border-amber-800 text-[11px]">${ratioText}</span>
                            <span class="text-[10px] text-slate-400 dark:text-slate-400 block">${v.fuel_type || 'Pertalite'}</span>
                        </td>
                        <td class="py-3 px-4 text-center">${statusBadge}</td>
                        <td class="py-3 px-4 text-center">
                            <div class="flex items-center justify-center space-x-1">
                                <button onclick="editVehicle(${v.id})" class="px-2 py-1 bg-indigo-50 dark:bg-indigo-950/60 hover:bg-indigo-600 dark:hover:bg-indigo-900/60 hover:text-white text-indigo-700 dark:text-indigo-300 font-bold text-[11px] rounded-lg border border-indigo-200 dark:border-indigo-800 transition-colors shadow-2xs">
                                    Edit
                                </button>
                                <button onclick="deleteVehicle(${v.id})" title="Hapus Kendaraan" class="p-1 text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 rounded-lg transition-colors">
                                    <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                                </button>
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');

            lucide.createIcons();
        }

        function populateVehicleDriverOptions(selectedBranchId, selectedDriverUserId = null, currentDriverName = '') {
            const driverSelect = document.getElementById('vehicle-driver-select');
            const hiddenDriverInput = document.getElementById('vehicle-driver');
            if (!driverSelect) return;

            const branchId = selectedBranchId ? parseInt(selectedBranchId) : null;
            // Ambil data karyawan sesuai lokasi cabang yang dimiliki oleh karyawan
            const branchEmployees = (state.users || []).filter(u => (!branchId || !u.branch_id || u.branch_id === branchId) && u.is_active != 0);

            let optionsHtml = '';
            if (branchEmployees.length === 0) {
                optionsHtml = '<option value="">(Belum ada karyawan di cabang ini)</option>';
            } else {
                optionsHtml = '<option value="">-- Pilih Karyawan Cabang sebagai Driver --</option>' +
                    branchEmployees.map(u => {
                        const isSel = (selectedDriverUserId && u.id === selectedDriverUserId) || (!selectedDriverUserId && currentDriverName && u.name === currentDriverName);
                        return `<option value="${u.id}" data-name="${u.name}" ${isSel ? 'selected' : ''}>${u.name} (${u.role}) - ${u.phone || '-'}</option>`;
                    }).join('');
            }

            // Opsi jika driver nama kustom yang belum terhubung dengan akun user
            if (currentDriverName && !branchEmployees.some(u => u.name === currentDriverName)) {
                optionsHtml = `<option value="" data-name="${currentDriverName}" selected>${currentDriverName} (Driver Eksternal / Mitra)</option>` + optionsHtml;
            }

            driverSelect.innerHTML = optionsHtml;
            onVehicleDriverSelectChange();
        }

        function onVehicleBranchChange() {
            const branchSelect = document.getElementById('vehicle-branch');
            const selectedBranchId = branchSelect ? branchSelect.value : null;
            populateVehicleDriverOptions(selectedBranchId);
        }

        function onVehicleDriverSelectChange() {
            const driverSelect = document.getElementById('vehicle-driver-select');
            const hiddenDriverInput = document.getElementById('vehicle-driver');
            if (!driverSelect || !hiddenDriverInput) return;

            const selectedOption = driverSelect.options[driverSelect.selectedIndex];
            if (selectedOption && selectedOption.value) {
                hiddenDriverInput.value = selectedOption.getAttribute('data-name') || selectedOption.text.split(' (')[0];
            } else if (selectedOption && selectedOption.getAttribute('data-name')) {
                hiddenDriverInput.value = selectedOption.getAttribute('data-name');
            } else {
                hiddenDriverInput.value = '';
            }
        }

        function openVehicleModal(veh = null) {
            const modal = document.getElementById('vehicle-modal');
            const title = document.getElementById('vehicle-modal-title');
            const branchSelect = document.getElementById('vehicle-branch');

            const curUser = state.currentUser || state.loggedInUser || {};
            const rawRole = ((curUser.role || 'CASHIER') + '').toUpperCase().replace(/_/g, '').trim();
            const isSuperAdmin = (rawRole === 'SUPERADMIN' || rawRole === 'SUPER ADMIN');
            const isManager = isSuperAdmin || rawRole === 'BRANCHMANAGER' || rawRole === 'MANAGER';
            const userBranchId = curUser.branch_id || (state.currentBranch ? state.currentBranch.id : 1);

            if (!isSuperAdmin && !isManager) {
                const myBranch = (state.branches || []).find(b => b.id == userBranchId) || state.currentBranch || { id: userBranchId, name: 'Cabang Penugasan' };
                branchSelect.innerHTML = `<option value="${userBranchId}">${escapeHtml(myBranch.name)}</option>`;
                branchSelect.value = userBranchId;
                branchSelect.disabled = true;
            } else {
                branchSelect.disabled = false;
                branchSelect.innerHTML = '<option value="">Semua Cabang (Global)</option>' + 
                    state.branches.map(b => `<option value="${b.id}">${escapeHtml(b.name)}</option>`).join('');
            }

            if (veh) {
                title.innerText = 'Edit Data Armada Kendaraan Kurir';
                document.getElementById('vehicle-id').value = veh.id;
                document.getElementById('vehicle-branch').value = veh.branch_id || '';
                document.getElementById('vehicle-plate').value = veh.plate_number;
                document.getElementById('vehicle-name').value = veh.vehicle_name;
                document.getElementById('vehicle-type').value = veh.vehicle_type || 'MOTOR';
                document.getElementById('vehicle-driver').value = veh.driver_name || '';
                document.getElementById('vehicle-odometer').value = formatDecimal(veh.current_odometer || 0);
                document.getElementById('vehicle-fuel-ratio').value = formatDecimal(veh.fuel_ratio || 35);
                document.getElementById('vehicle-fuel-ratio-unit').value = veh.fuel_ratio_unit || 'KM_PER_LITER';
                document.getElementById('vehicle-fuel-type').value = veh.fuel_type || 'Pertalite';
                document.getElementById('vehicle-status').value = veh.status || 'ACTIVE';
                document.getElementById('vehicle-notes').value = veh.notes || '';
                populateVehicleDriverOptions(veh.branch_id, veh.driver_user_id, veh.driver_name);
            } else {
                title.innerText = 'Tambah Armada Kendaraan Baru';
                document.getElementById('vehicle-id').value = '';
                const defaultBranchId = state.currentBranch ? state.currentBranch.id : '';
                document.getElementById('vehicle-branch').value = defaultBranchId;
                document.getElementById('vehicle-plate').value = '';
                document.getElementById('vehicle-name').value = '';
                document.getElementById('vehicle-type').value = 'MOTOR';
                document.getElementById('vehicle-driver').value = '';
                document.getElementById('vehicle-odometer').value = '0';
                document.getElementById('vehicle-fuel-ratio').value = '35';
                document.getElementById('vehicle-fuel-ratio-unit').value = 'KM_PER_LITER';
                document.getElementById('vehicle-fuel-type').value = 'Pertalite';
                document.getElementById('vehicle-status').value = 'ACTIVE';
                document.getElementById('vehicle-notes').value = '';
                populateVehicleDriverOptions(defaultBranchId, null, '');
            }
            modal.classList.remove('hidden');
        }

        function closeVehicleModal() {
            document.getElementById('vehicle-modal').classList.add('hidden');
        }

        function editVehicle(id) {
            const veh = state.vehicles.find(v => v.id === id);
            if (veh) openVehicleModal(veh);
        }

        async function saveVehicleForm(e) {
            e.preventDefault();
            const id = document.getElementById('vehicle-id').value;
