                vehicle_name: document.getElementById('vehicle-name').value.trim(),
                vehicle_type: document.getElementById('vehicle-type').value,
                driver_user_id: driverUserId,
                driver_name: driverName,
                current_odometer: parseFloat(document.getElementById('vehicle-odometer').value) || 0,
                fuel_ratio: parseFloat(document.getElementById('vehicle-fuel-ratio').value) || 35,
                fuel_ratio_unit: document.getElementById('vehicle-fuel-ratio-unit').value,
                fuel_type: document.getElementById('vehicle-fuel-type').value,
                status: document.getElementById('vehicle-status').value,
                notes: document.getElementById('vehicle-notes').value.trim()
            };

            const res = await fetch('api.php?action=save_courier_vehicle', {
