        function editPaymentMethod(m) {
            document.getElementById('pm-modal-id').value = m.id;
            document.getElementById('pm-modal-code').value = m.code;
            document.getElementById('pm-modal-code').readOnly = (m.id == 1 || m.code === 'CASH');
