        // ==========================================
        // 15. MODUL PEMBATALAN TRANSAKSI PENJUALAN (VOID SALES)
        // ==========================================
        let voidSalesStatusFilter = 'ALL';
        let voidSearchDebounceTimer = null;

        function setVoidStatusFilter(status) {
            voidSalesStatusFilter = status;
            ['all', 'completed', 'cancelled'].forEach(s => {
                const btn = document.getElementById(`void-filter-btn-${s}`);
                if (btn) {
                    if (s === status.toLowerCase()) {
                        btn.className = 'px-3 py-1.5 rounded-lg bg-white text-slate-800 shadow-xs font-bold transition-colors';
                    } else {
                        btn.className = 'px-3 py-1.5 rounded-lg text-slate-600 hover:text-slate-800 font-bold transition-colors';
                    }
                }
            });
            loadSaleCancellations();
        }

        function onVoidSearchKeyUp(e) {
            clearTimeout(voidSearchDebounceTimer);
            voidSearchDebounceTimer = setTimeout(() => {
                loadSaleCancellations();
            }, 300);
        }

        async function loadSaleCancellations() {
            const tableBody = document.getElementById('cancellations-table-body');
            if (!tableBody) return;

            // Render authority banner
            const authContainer = document.getElementById('void-auth-status-container');
            const isSuperAdmin = (state.loggedInUser && ['SUPER_ADMIN', 'SUPERADMIN'].includes(state.loggedInUser.role));

            if (authContainer) {
                if (isSuperAdmin) {
                    authContainer.innerHTML = `
                        <div class="flex items-center space-x-2 bg-rose-950/60 border border-rose-500/50 px-3 py-1.5 rounded-2xl">
                            <span class="w-2.5 h-2.5 rounded-full bg-emerald-400 animate-pulse"></span>
                            <span class="text-xs font-bold text-rose-100">Super Admin: ${state.loggedInUser.name}</span>
                        </div>
                        <button type="button" onclick="openPurgeSalesModal()" class="px-3 py-1.5 bg-rose-600 hover:bg-rose-500 text-white rounded-xl text-xs font-black shadow transition-colors flex items-center space-x-1.5" title="Hapus seluruh riwayat penjualan dari database">
                            <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                            <span>Hapus Seluruh Data Penjualan</span>
                        </button>
                    `;
                } else {
                    const currentRole = state.loggedInUser ? state.loggedInUser.role : 'KASIR';
                    authContainer.innerHTML = `
                        <div class="flex items-center space-x-2">
                            <span class="text-xs text-rose-300 font-semibold hidden md:inline">Peran Saat Ini: ${currentRole}</span>
                            <button type="button" onclick="loginAsSuperadminVoid()" class="px-3 py-1.5 bg-rose-600 hover:bg-rose-500 text-white rounded-xl text-xs font-black shadow transition-colors flex items-center space-x-1">
                                <span>👑 Beralih ke Super Admin</span>
                            </button>
                        </div>
                    `;
                }
            }

            const branchId = state.currentBranch ? state.currentBranch.id : '';
            const keyword = document.getElementById('void-search-keyword') ? document.getElementById('void-search-keyword').value.trim() : '';
            const startDate = document.getElementById('void-start-date') ? document.getElementById('void-start-date').value : '';
            const endDate = document.getElementById('void-end-date') ? document.getElementById('void-end-date').value : '';

            tableBody.innerHTML = `<tr><td colspan="10" class="text-center py-8 text-slate-400">Memuat data transaksi...</td></tr>`;

            try {
                let url = `api.php?action=get_cancellable_sales&status_filter=${voidSalesStatusFilter}`;
                if (branchId) url += `&branch_id=${branchId}`;
                if (keyword) url += `&keyword=${encodeURIComponent(keyword)}`;
                if (startDate && endDate) url += `&start_date=${startDate}&end_date=${endDate}`;

                const res = await fetch(url);
                const data = await res.json();

                if (!data.success) {
                    tableBody.innerHTML = `<tr><td colspan="10" class="text-center py-8 text-rose-500 font-bold">${data.message || 'Gagal memuat transaksi'}</td></tr>`;
                    return;
                }

                // Update KPI Cards
                if (data.kpi) {
                    document.getElementById('void-kpi-active-count').innerText = (data.kpi.active_count || 0).toLocaleString('id-ID');
                    document.getElementById('void-kpi-active-amount').innerText = formatRupiah(data.kpi.active_amount || 0);
                    document.getElementById('void-kpi-cancelled-count').innerText = (data.kpi.cancelled_count || 0).toLocaleString('id-ID');
                    document.getElementById('void-kpi-cancelled-amount').innerText = formatRupiah(data.kpi.cancelled_amount || 0);
                    document.getElementById('void-kpi-restocked-qty').innerText = (data.kpi.total_restocked_qty || 0).toLocaleString('id-ID') + ' unit';
                    document.getElementById('void-kpi-void-receivables').innerText = formatRupiah(data.kpi.total_void_receivables || 0);
                }

                const sales = data.sales || [];
                const tableInfo = document.getElementById('void-table-info');
                if (tableInfo) tableInfo.innerText = `Menampilkan ${sales.length} transaksi`;

                if (sales.length === 0) {
                    tableBody.innerHTML = `<tr><td colspan="10" class="text-center py-10 text-slate-400">Tidak ada transaksi penjualan ditemukan untuk filter ini.</td></tr>`;
                    return;
                }

                tableBody.innerHTML = sales.map(s => {
                    const isCancelled = (s.status === 'CANCELLED');
                    const badgeClass = isCancelled 
                        ? 'bg-rose-100 text-rose-800 border border-rose-300' 
                        : 'bg-emerald-100 text-emerald-800 border border-emerald-300';
                    const statusLabel = isCancelled ? 'DIBATALKAN (VOID)' : 'COMPLETED';

                    let voidDetailsHtml = '<span class="text-slate-300">-</span>';
                    if (isCancelled) {
                        voidDetailsHtml = `
                            <div class="text-[11px] leading-tight">
                                <span class="font-bold text-rose-700 block">Dibatalkan oleh: ${s.cancelled_by_name || 'Super Admin'}</span>
                                <span class="text-slate-500 block text-[10px]">${s.cancelled_at || '-'}</span>
                                <span class="text-slate-700 italic block mt-0.5 bg-rose-50 p-1 rounded border border-rose-100">"${s.cancellation_reason || '-'}"</span>
                            </div>
                        `;
                    }

                    const actionBtn = isCancelled
                        ? `<button type="button" onclick="showSaleDetail('${s.invoice_number}')" class="px-2.5 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-lg text-xs font-bold transition-colors">Detail</button>`
                        : `
                            <div class="flex items-center space-x-1.5 justify-center">
                                <button type="button" onclick="showSaleDetail('${s.invoice_number}')" class="px-2 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-lg text-xs font-bold transition-colors">
                                    Detail
                                </button>
                                <button type="button" onclick="openVoidSaleModal(${s.id}, '${s.invoice_number}', ${s.grand_total}, '${(s.customer_name || 'Pelanggan Umum').replace(/'/g, "\\'")}', '${(s.branch_name || '').replace(/'/g, "\\'")}', '${s.payment_method}', '${(s.cashier_name || '').replace(/'/g, "\\'")}')" class="px-2.5 py-1 bg-rose-600 hover:bg-rose-700 text-white rounded-lg text-xs font-black shadow-xs transition-colors flex items-center space-x-1">
                                    <i data-lucide="ban" class="w-3 h-3"></i>
                                    <span>Batalkan</span>
                                </button>
                            </div>
                        `;

                    return `
                        <tr class="hover:bg-slate-50/80 transition-colors ${isCancelled ? 'bg-rose-50/30' : ''}">
                            <td class="py-3 px-4 font-mono font-bold ${isCancelled ? 'text-rose-600 line-through' : 'text-indigo-600'}">
                                ${s.invoice_number}
                            </td>
                            <td class="py-3 px-4 text-slate-500 text-[11px] whitespace-nowrap">
                                ${s.created_at || '-'}
                            </td>
                            <td class="py-3 px-4 font-medium text-slate-800">
                                ${s.branch_name || '-'}
                            </td>
                            <td class="py-3 px-4 text-slate-700">
                                ${s.cashier_name || '-'}
                            </td>
                            <td class="py-3 px-4">
                                <span class="font-bold text-slate-800">${s.customer_name || 'Pelanggan Umum'}</span>
                                <span class="block text-[10px] text-slate-400 font-semibold">${s.customer_category || 'REGULER'}</span>
                            </td>
                            <td class="py-3 px-4 text-right font-bold font-mono text-slate-900">
                                ${formatRupiah(s.grand_total)}
                            </td>
                            <td class="py-3 px-4 text-center">
                                <span class="px-2 py-0.5 rounded-md text-[10px] font-bold ${s.payment_method === 'PIUTANG' ? 'bg-amber-100 text-amber-800' : 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700'}">
                                    ${s.payment_method}
                                </span>
                            </td>
                            <td class="py-3 px-4 text-center">
                                <span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold ${badgeClass}">
                                    ${statusLabel}
                                </span>
                            </td>
                            <td class="py-3 px-4 max-w-xs">
                                ${voidDetailsHtml}
                            </td>
                            <td class="py-3 px-4 text-center whitespace-nowrap">
                                ${actionBtn}
                            </td>
                        </tr>
                    `;
                }).join('');

                lucide.createIcons();
            } catch (err) {
                tableBody.innerHTML = `<tr><td colspan="10" class="text-center py-8 text-rose-500">Gagal mengambil data dari server.</td></tr>`;
            }
        }

        function openVoidSaleModal(saleId, invoiceNumber, grandTotal, customerName, branchName, paymentMethod, cashierName) {
            document.getElementById('void-modal-sale-id').value = saleId;
            document.getElementById('void-modal-invoice-no').innerText = invoiceNumber;
            document.getElementById('void-modal-branch').innerText = branchName || '-';
            document.getElementById('void-modal-cashier').innerText = cashierName || '-';
            document.getElementById('void-modal-customer').innerText = customerName || 'Pelanggan Umum';
            document.getElementById('void-modal-payment').innerText = paymentMethod || 'CASH';
            document.getElementById('void-modal-grand-total').innerText = formatRupiah(grandTotal);

            // Reset form inputs
            document.getElementById('void-modal-reason-quick').value = '';
            document.getElementById('void-modal-reason-text').value = '';
            
            // Auto fill PIN if logged in as superadmin
            if (state.loggedInUser && ['SUPER_ADMIN', 'SUPERADMIN'].includes(state.loggedInUser.role)) {
                document.getElementById('void-modal-admin-pin').value = state.loggedInUser.pin || '999999';
                document.getElementById('void-modal-admin-password').value = 'admin123';
            } else {
                document.getElementById('void-modal-admin-pin').value = '';
                document.getElementById('void-modal-admin-password').value = '';
            }

            document.getElementById('void-sale-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function closeVoidSaleModal() {
            document.getElementById('void-sale-modal').classList.add('hidden');
        }

        function onVoidReasonQuickChange() {
            const quickVal = document.getElementById('void-modal-reason-quick').value;
            const textEl = document.getElementById('void-modal-reason-text');
            if (quickVal && quickVal !== 'Lainnya') {
                textEl.value = quickVal;
            }
        }

        async function submitVoidSaleForm(e) {
            e.preventDefault();
            const submitBtn = document.getElementById('void-modal-submit-btn');
            const saleId = document.getElementById('void-modal-sale-id').value;
            const invoiceNo = document.getElementById('void-modal-invoice-no').innerText;
            const reason = document.getElementById('void-modal-reason-text').value.trim();
            const adminPin = document.getElementById('void-modal-admin-pin').value.trim();
            const adminPassword = document.getElementById('void-modal-admin-password').value.trim();

            if (!reason) {
                alert('Alasan pembatalan transaksi wajib diisi!');
                return;
            }

            if (!adminPin && !adminPassword && (!state.loggedInUser || !['SUPER_ADMIN', 'SUPERADMIN'].includes(state.loggedInUser.role))) {
                alert('Masukkan PIN atau Kata Sandi Super Admin (Budi Santoso - PIN 999999 / Password admin123) untuk mengotorisasi pembatalan!');
                return;
            }

            if (!confirm(`PERINGATAN: Apakah Anda yakin ingin MEMBATALKAN transaksi '${invoiceNo}'?\n\nSemua persediaan produk & bahan baku BOM akan dikembalikan ke cabang, dan catatan piutang (jika ada) akan dibatalkan permanen.`)) {
                return;
            }

            submitBtn.disabled = true;
            submitBtn.innerHTML = `<span>Memproses Void...</span>`;

            try {
                const res = await fetch('api.php?action=cancel_sale', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        sale_id: saleId,
                        invoice_number: invoiceNo,
                        reason: reason,
                        admin_pin: adminPin || '999999',
                        admin_password: adminPassword || 'admin123',
                        admin_user_id: state.loggedInUser ? state.loggedInUser.id : 1
                    })
                });

                const data = await res.json();
                submitBtn.disabled = false;
                submitBtn.innerHTML = `<i data-lucide="ban" class="w-4 h-4"></i><span>Batalkan Transaksi (Void)</span>`;

                if (data.success) {
                    alert('BERHASIL! ' + data.message);
                    closeVoidSaleModal();
                    await loadSaleCancellations();
                    // Refresh other tabs cache if loaded
                    if (state.currentTab === 'stocks') loadStockInventory();
                    if (state.currentTab === 'reports') loadSalesReports();
                    if (state.currentTab === 'pnl') loadProfitLoss();
                } else {
                    alert('GAGAL: ' + (data.message || data.error));
                }
            } catch (err) {
                submitBtn.disabled = false;
                submitBtn.innerHTML = `<i data-lucide="ban" class="w-4 h-4"></i><span>Batalkan Transaksi (Void)</span>`;
                alert('Terjadi kesalahan jaringan saat membatalkan transaksi.');
            }
        }

        async function loginAsSuperadminVoid() {
            if (!confirm('Beralih ke akun Super Admin sekarang? Anda wajib memasukkan kata sandi Super Admin untuk otorisasi.')) return;
            showLoginScreen('Silakan masukkan kata sandi Super Admin untuk melanjutkan otorisasi.');
            selectQuickAccount('ADM001', 'Super Admin');
        }

        // --- Fitur Hapus Seluruh Riwayat Penjualan (Super Admin Only) ---
        // ==============================================================
        // MASTER RESET & PEMBERSIHAN DATA CABANG (GRANULAR DATA PURGE)
        // ==============================================================
        function setMasterResetTargetBranch(scope) {
            const select = document.getElementById('master-reset-branch-select');
            if (!select) return;
            if (scope === 'ALL') {
                select.value = 'ALL';
            } else if (scope === 'SPECIFIC') {
                const stockSelect = document.getElementById('stock-branch-select');
                if (stockSelect && stockSelect.value && stockSelect.value !== 'ALL') {
                    select.value = stockSelect.value;
                } else if (state.currentBranch && state.currentBranch.id) {
                    select.value = String(state.currentBranch.id);
                } else if (select.options.length > 1) {
                    select.selectedIndex = 1;
                }
            } else {
                select.value = String(scope);
            }
            updateResetScopeInfo();
        }

        function setMasterResetDateMode(mode) {
            const btnAll = document.getElementById('btn-date-mode-all');
            const btnCustom = document.getElementById('btn-date-mode-custom');
            const container = document.getElementById('master-reset-date-container');
            const badge = document.getElementById('reset-date-mode-badge');
            const desc = document.getElementById('reset-date-scope-desc');
            const stockTitle = document.getElementById('reset-opt-stocks-title');
            const stockBadge = document.getElementById('reset-opt-stocks-badge');
            const stockDesc = document.getElementById('reset-opt-stocks-desc');

            if (mode === 'ALL') {
                if (btnAll) btnAll.className = 'py-2 px-3 rounded-xl border-2 text-[11px] font-black flex items-center justify-center space-x-1.5 transition-all bg-rose-50 border-rose-600 text-rose-800 shadow-xs';
                if (btnCustom) btnCustom.className = 'py-2 px-3 rounded-xl border text-[11px] font-bold flex items-center justify-center space-x-1.5 transition-all bg-white border-slate-300 text-slate-600 hover:border-slate-400';
                if (container) container.classList.add('hidden');
                if (badge) {
                    badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-100 text-rose-800';
                    badge.innerText = 'Semua Waktu (All-Time)';
                }
                if (desc) {
                    desc.innerHTML = 'Operasi akan mengeksekusi reset pada <b>seluruh data riwayat transaksi</b> dari awal sistem berjalan.';
                }
                if (stockTitle) stockTitle.innerText = '📦 1. Hapus Stok Seluruh Data';
                if (stockBadge) {
                    stockBadge.innerText = 'Stok = 0';
                    stockBadge.className = 'px-1.5 py-0.2 rounded text-[9px] bg-rose-100 text-rose-800 font-semibold';
                }
                if (stockDesc) stockDesc.innerText = 'Mengosongkan saldo stok fisik seluruh produk (barang jadi & bahan baku) menjadi 0 pada cabang terpilih / semua cabang, serta membersihkan seluruh riwayat kartu mutasi stok fisik.';
            } else {
                if (btnAll) btnAll.className = 'py-2 px-3 rounded-xl border text-[11px] font-bold flex items-center justify-center space-x-1.5 transition-all bg-white border-slate-300 text-slate-600 hover:border-slate-400';
                if (btnCustom) btnCustom.className = 'py-2 px-3 rounded-xl border-2 text-[11px] font-black flex items-center justify-center space-x-1.5 transition-all bg-indigo-50 border-indigo-600 text-indigo-800 shadow-xs';
                if (container) container.classList.remove('hidden');

                const startInput = document.getElementById('master-reset-start-date');
                const endInput = document.getElementById('master-reset-end-date');
                const todayStr = (typeof getDeviceLocalDateString === 'function') ? getDeviceLocalDateString() : new Date().toISOString().split('T')[0];
                if (startInput && !startInput.value) startInput.value = todayStr;
                if (endInput && !endInput.value) endInput.value = todayStr;

                updateResetDateScopeInfo();

                if (stockTitle) stockTitle.innerText = '📦 1. Bersihkan Kartu Pergerakan Stok';
                if (stockBadge) {
                    stockBadge.innerText = 'Mutasi Tanggal Terpilih';
                    stockBadge.className = 'px-1.5 py-0.2 rounded text-[9px] bg-amber-100 text-amber-800 font-semibold';
                }
                if (stockDesc) stockDesc.innerText = 'Menghapus riwayat kartu mutasi pergerakan stok fisik (stock_movements) yang tercatat pada rentang tanggal terpilih.';
            }
            if (typeof updateResetKeepInitialUI === 'function') {
                updateResetKeepInitialUI();
            }
            if (typeof lucide !== 'undefined' && lucide.createIcons) {
                lucide.createIcons();
            }
        }

        function setMasterResetDatePreset(preset) {
            const today = new Date();
            const pad = function(n) { return (n < 10 ? '0' : '') + n; };
            const formatDate = function(d) {
                return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
            };
            const startInput = document.getElementById('master-reset-start-date');
            const endInput = document.getElementById('master-reset-end-date');
            if (!startInput || !endInput) return;

            if (preset === 'today') {
                startInput.value = formatDate(today);
                endInput.value = formatDate(today);
            } else if (preset === 'yesterday') {
                const yest = new Date();
                yest.setDate(today.getDate() - 1);
                startInput.value = formatDate(yest);
                endInput.value = formatDate(yest);
            } else if (preset === '7days') {
                const d7 = new Date();
                d7.setDate(today.getDate() - 6);
                startInput.value = formatDate(d7);
                endInput.value = formatDate(today);
            } else if (preset === '30days') {
                const d30 = new Date();
                d30.setDate(today.getDate() - 29);
                startInput.value = formatDate(d30);
                endInput.value = formatDate(today);
            } else if (preset === 'this_month') {
                const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
                startInput.value = formatDate(firstDay);
                endInput.value = formatDate(today);
            }
            updateResetDateScopeInfo();
        }

        function updateResetDateScopeInfo() {
            const startInput = document.getElementById('master-reset-start-date');
            const endInput = document.getElementById('master-reset-end-date');
            const badge = document.getElementById('reset-date-mode-badge');
            const desc = document.getElementById('reset-date-scope-desc');
            if (!startInput || !endInput || !badge || !desc) return;

            const sVal = startInput.value;
            const eVal = endInput.value;
            if (!sVal || !eVal) {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800';
                badge.innerText = 'Pilih Tanggal';
                desc.innerHTML = '<span class="text-amber-700 font-bold">Harap tentukan tanggal mulai dan tanggal selesai!</span>';
                return;
            }

            badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-indigo-600 text-white';
            if (sVal === eVal) {
                badge.innerText = '📅 Tanggal: ' + sVal;
                desc.innerHTML = 'Operasi reset <b>HANYA BERDAMPAK</b> pada data transaksi yang tercatat pada tanggal <b>' + sVal + '</b>. Transaksi sebelum dan sesudah tanggal ini tetap utuh dan aman.';
            } else {
                badge.innerText = '📅 ' + sVal + ' s/d ' + eVal;
                desc.innerHTML = 'Operasi reset <b>HANYA BERDAMPAK</b> pada data transaksi antara tanggal <b>' + sVal + '</b> sampai <b>' + eVal + '</b>. Transaksi di luar rentang ini tetap utuh dan aman.';
            }
        }

        // ==========================================
        // 15.1 SINKRONISASI DATABASE MASTER (HOSTING & LOKAL)
        // ==========================================
        let currentModalSyncMode = 'remote';

        function openMasterSyncModal(preselectOpts = {}) {
            if (!canUserAccessAllBranches()) {
                alert('Akses Ditolak: Fitur Sinkronisasi Master Data hanya dapat diakses oleh Super Admin.');
                return;
            }

            // Sync URL input
            const hostingUrl = (document.getElementById('subtab-sync-hosting-url') && document.getElementById('subtab-sync-hosting-url').value) || 'https://kadtech.my.id';
            const modalUrlInput = document.getElementById('modal-sync-hosting-url');
            if (modalUrlInput) modalUrlInput.value = hostingUrl;

            // Reset checklist checkboxes
            const tables = preselectOpts.tables || null;
            if (tables && Array.isArray(tables)) {
                const setCb = (id, val) => { const el = document.getElementById(id); if (el) el.checked = val; };
                setCb('sync-cat-products', tables.some(t => ['products', 'categories', 'product_types', 'product_units', 'product_variants'].includes(t)));
                setCb('sync-cat-recipes', tables.some(t => ['product_recipes', 'variant_recipes'].includes(t)));
                setCb('sync-cat-branches', tables.some(t => ['branches', 'branch_settings'].includes(t)));
                setCb('sync-cat-users', tables.some(t => ['users', 'user_roles', 'role_menu_permissions'].includes(t)));
                setCb('sync-cat-customers', tables.some(t => ['customers', 'customer_categories', 'mitra_custom_prices'].includes(t)));
                setCb('sync-cat-payments', tables.some(t => ['payment_methods', 'cash_denominations', 'taxes'].includes(t)));
                setCb('sync-cat-logistics', tables.some(t => ['delivery_settings', 'courier_vehicles'].includes(t)));
                setCb('sync-cat-settings', tables.some(t => ['app_settings', 'opening_shift_products', 'work_shifts'].includes(t)));
            } else {
                setAllSyncCheckboxes(true);
            }
            const stockCb = document.getElementById('sync-cat-stocks');
            if (stockCb) stockCb.checked = false;

            setModalSyncMode('remote');
            const consoleBox = document.getElementById('modal-sync-console-box');
            if (consoleBox) consoleBox.classList.add('hidden');
            const pBar = document.getElementById('modal-sync-progress-bar');
            if (pBar) pBar.style.width = '0%';

            const modal = document.getElementById('master-sync-modal');
            if (modal) modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeMasterSyncModal() {
            const modal = document.getElementById('master-sync-modal');
            if (modal) modal.classList.add('hidden');
        }

        function setAllSyncCheckboxes(isChecked) {
            ['products', 'recipes', 'branches', 'users', 'customers', 'payments', 'logistics', 'settings'].forEach(cat => {
                const cb = document.getElementById(`sync-cat-${cat}`);
                if (cb) cb.checked = isChecked;
            });
        }

        function setModalSyncMode(mode) {
            currentModalSyncMode = mode;
            const tabRemote = document.getElementById('modal-sync-tab-remote');
            const tabFile = document.getElementById('modal-sync-tab-file');
            const contentRemote = document.getElementById('modal-sync-content-remote');
            const contentFile = document.getElementById('modal-sync-content-file');

            if (mode === 'remote') {
                if (tabRemote) tabRemote.className = 'px-3 py-1.5 rounded-lg font-bold bg-indigo-600 text-white shadow-xs';
                if (tabFile) tabFile.className = 'px-3 py-1.5 rounded-lg font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-200';
                if (contentRemote) contentRemote.classList.remove('hidden');
                if (contentFile) contentFile.classList.add('hidden');
            } else {
                if (tabRemote) tabRemote.className = 'px-3 py-1.5 rounded-lg font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-200';
                if (tabFile) tabFile.className = 'px-3 py-1.5 rounded-lg font-bold bg-blue-600 text-white shadow-xs';
                if (contentRemote) contentRemote.classList.add('hidden');
                if (contentFile) contentFile.classList.remove('hidden');
            }
        }

        function getSelectedSyncTableNames() {
            const tableMap = {
                'products': ['products', 'categories', 'product_types', 'product_units', 'product_variants'],
                'recipes': ['product_recipes', 'variant_recipes'],
                'branches': ['branches', 'branch_settings'],
                'users': ['users', 'user_roles', 'role_menu_permissions'],
                'customers': ['customers', 'customer_categories', 'mitra_custom_prices'],
                'payments': ['payment_methods', 'cash_denominations', 'taxes'],
                'logistics': ['delivery_settings', 'courier_vehicles'],
                'settings': ['app_settings', 'opening_shift_products', 'work_shifts', 'expense_categories']
            };

            let tables = [];
            Object.keys(tableMap).forEach(cat => {
                const cb = document.getElementById(`sync-cat-${cat}`);
                if (cb && cb.checked) {
                    tables = tables.concat(tableMap[cat]);
                }
            });
            return tables;
        }

        async function testHostingConnection(urlInputId, badgeId) {
            const urlInput = document.getElementById(urlInputId);
            const badge = document.getElementById(badgeId);
            if (!urlInput || !badge) return;

            const url = urlInput.value.trim();
            if (!url) {
                alert('Silakan masukkan URL server hosting terlebih dahulu.');
                return;
            }

            badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-sky-100 text-sky-700 animate-pulse';
            badge.innerText = 'Menguji...';

            try {
                const res = await fetch('api.php?action=test_hosting_connection', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ hosting_url: url })
                });
                const data = await res.json();
                if (data.success) {
                    const ver = (data.version_data && data.version_data.version) ? ` (v${data.version_data.version})` : '';
                    badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-emerald-100 text-emerald-800';
                    badge.innerText = `Terhubung ${data.latency_ms}ms${ver}`;
                    const supportNote = data.support_note ? `\nStatus Mode: ${data.support_note}` : '';
                    alert(`✅ Koneksi Berhasil!\n\nServer hosting terjangkau (${data.latency_ms} ms).\nVersi Hosting: ${data.version_data ? data.version_data.version : 'OK'}${supportNote}`);
                } else {
                    badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-rose-100 text-rose-700';
                    badge.innerText = 'Gagal Terhubung';
                    alert(`❌ Uji Koneksi Gagal:\n\n${data.message || 'Tidak dapat menghubungi hosting.'}`);
                }
            } catch (err) {
                badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-rose-100 text-rose-700';
                badge.innerText = 'Error Jaringan';
                alert(`❌ Kesalahan Uji Koneksi: ${err.message}`);
            }
        }

        async function executeModalMasterSyncRemote() {
            const urlInput = document.getElementById('modal-sync-hosting-url');
            const hostingUrl = urlInput ? urlInput.value.trim() : 'https://kadtech.my.id';
            const selectedTables = getSelectedSyncTableNames();
            const includeStocks = document.getElementById('sync-cat-stocks') && document.getElementById('sync-cat-stocks').checked;

            if (selectedTables.length === 0) {
                alert('Pilih minimal satu modul master data untuk disinkronkan.');
                return;
            }

            if (!confirm(`Mulai sinkronisasi master data dari ${hostingUrl}?\n\nModul yang akan diperbarui: ${selectedTables.length} tabel master.\nData transaksi kasir dan shift lokal akan tetap aman.`)) {
                return;
            }

            const btn = document.getElementById('btn-modal-exec-remote');
            const consoleBox = document.getElementById('modal-sync-console-box');
            const pBar = document.getElementById('modal-sync-progress-bar');
            const consoleEl = document.getElementById('modal-sync-console');

            if (btn) {
                btn.disabled = true;
                btn.innerHTML = `<i data-lucide="loader-2" class="w-4 h-4 animate-spin"></i><span>Menghubungi Hosting...</span>`;
            }
            if (consoleBox) consoleBox.classList.remove('hidden');
            if (pBar) pBar.style.width = '30%';
            if (consoleEl) {
                consoleEl.innerText = `[${new Date().toLocaleTimeString()}] Menghubungi server hosting di ${hostingUrl}...\n[${new Date().toLocaleTimeString()}] Mengunduh paket data master JSON...\n`;
            }
            lucide.createIcons();

            try {
                const res = await fetch('api.php?action=sync_master_data', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        mode: 'remote',
                        hosting_url: hostingUrl,
                        sync_mode: 'upsert',
                        tables: selectedTables,
                        include_stocks: includeStocks ? 1 : 0
                    })
                });
                const result = await res.json();

                if (pBar) pBar.style.width = '100%';

                if (result.success) {
                    let logDetails = `[${new Date().toLocaleTimeString()}] ✅ SINKRONISASI MASTER BERHASIL DISAJIKAN!\n`;
                    logDetails += `Total tabel: ${result.total_synced_tables} tabel | Total baris: ${result.total_synced_rows} baris\n`;
                    logDetails += `Versi Sumber Hosting: ${result.source_version} | Driver: ${result.source_driver}\n`;
                    logDetails += `Waktu Selesai: ${result.synced_at}\n\nRincian Baris:\n`;
                    if (result.report) {
                        for (const [tbl, cnt] of Object.entries(result.report)) {
                            logDetails += ` - ${tbl}: ${cnt} baris\n`;
                        }
                    }
                    if (consoleEl) consoleEl.innerText += logDetails;

                    // Sync subtab update
                    const subConsole = document.getElementById('subtab-sync-console');
                    if (subConsole) subConsole.innerText = logDetails;
                    const subTime = document.getElementById('subtab-sync-last-time');
                    if (subTime) subTime.innerText = `Terakhir: ${new Date().toLocaleTimeString()}`;

                    alert(`🎉 Sinkronisasi Berhasil!\n\n${result.message}\nTotal ${result.total_synced_rows} baris diperbarui pada ${result.total_synced_tables} tabel master.`);

                    // Reload application state
                    if (typeof initApp === 'function') {
                        await initApp();
                    }
                } else {
                    const errMsg = `[${new Date().toLocaleTimeString()}] ❌ GAGAL: ${result.message}\n`;
                    if (consoleEl) consoleEl.innerText += errMsg;
                    alert(`❌ Sinkronisasi Gagal:\n\n${result.message}`);
                }
            } catch (err) {
                if (consoleEl) consoleEl.innerText += `[${new Date().toLocaleTimeString()}] ❌ Exception: ${err.message}\n`;
                alert(`❌ Terjadi kesalahan jaringan saat sinkronisasi: ${err.message}`);
            } finally {
                if (btn) {
                    btn.disabled = false;
                    btn.innerHTML = `<i data-lucide="cloud-download" class="w-4 h-4"></i><span>Mulai Tarik Data dari Hosting</span>`;
                    lucide.createIcons();
                }
            }
        }

        async function executeModalMasterSyncFile() {
            const fileInput = document.getElementById('modal-sync-file-input');
            if (!fileInput || !fileInput.files || fileInput.files.length === 0) {
                alert('Pilih berkas master data JSON (.json) terlebih dahulu.');
                return;
            }

            const selectedTables = getSelectedSyncTableNames();
            const includeStocks = document.getElementById('sync-cat-stocks') && document.getElementById('sync-cat-stocks').checked;

            const btn = document.getElementById('btn-modal-exec-file');
            const consoleBox = document.getElementById('modal-sync-console-box');
            const pBar = document.getElementById('modal-sync-progress-bar');
            const consoleEl = document.getElementById('modal-sync-console');

            if (btn) {
                btn.disabled = true;
                btn.innerHTML = `<i data-lucide="loader-2" class="w-4 h-4 animate-spin"></i><span>Memproses Berkas...</span>`;
            }
            if (consoleBox) consoleBox.classList.remove('hidden');
            if (pBar) pBar.style.width = '40%';
            if (consoleEl) {
                consoleEl.innerText = `[${new Date().toLocaleTimeString()}] Membaca berkas ${fileInput.files[0].name}...\n`;
            }
            lucide.createIcons();

            const formData = new FormData();
            formData.append('mode', 'upload');
            formData.append('sync_mode', 'upsert');
            formData.append('include_stocks', includeStocks ? '1' : '0');
            selectedTables.forEach(t => formData.append('tables[]', t));
            formData.append('master_file', fileInput.files[0]);

            try {
                const res = await fetch('api.php?action=sync_master_data', {
                    method: 'POST',
                    body: formData
                });
                const result = await res.json();
                if (pBar) pBar.style.width = '100%';

                if (result.success) {
                    let logDetails = `[${new Date().toLocaleTimeString()}] ✅ IMPOR BERKAS MASTER BERHASIL!\n`;
                    logDetails += `Total tabel: ${result.total_synced_tables} tabel | Total baris: ${result.total_synced_rows} baris\n`;
                    logDetails += `Versi Sumber: ${result.source_version} | Driver: ${result.source_driver}\n`;
                    if (result.report) {
                        for (const [tbl, cnt] of Object.entries(result.report)) {
                            logDetails += ` - ${tbl}: ${cnt} baris\n`;
                        }
                    }
                    if (consoleEl) consoleEl.innerText += logDetails;

                    alert(`🎉 Impor Berkas Berhasil!\n\n${result.message}\nTotal ${result.total_synced_rows} baris diperbarui.`);
                    if (typeof initApp === 'function') {
                        await initApp();
                    }
                } else {
                    if (consoleEl) consoleEl.innerText += `[${new Date().toLocaleTimeString()}] ❌ GAGAL: ${result.message}\n`;
                    alert(`❌ Impor Berkas Gagal:\n\n${result.message}`);
                }
            } catch (err) {
                if (consoleEl) consoleEl.innerText += `[${new Date().toLocaleTimeString()}] ❌ Exception: ${err.message}\n`;
                alert(`❌ Kesalahan saat membaca berkas: ${err.message}`);
            } finally {
                if (btn) {
                    btn.disabled = false;
                    btn.innerHTML = `<i data-lucide="upload" class="w-4 h-4"></i><span>Terapkan Berkas ke Database</span>`;
                    lucide.createIcons();
                }
            }
        }

        // Quick action wrapper for subtab buttons
