        function openMasterResetModal(preselectOpts = {}) {
            if (!canUserResetStoreData()) {
                alert('Akses Ditolak: Fitur Reset Data Toko hanya dapat diakses oleh Super Admin.');
                return;
            }

            // Tentukan target branch ID:
            // 1. Dari preselectOpts.branch_id jika didefinisikan
            // 2. Jika tidak ada dan sedang di tab stok, baca stock-branch-select
            // 3. Fallback ke state.currentBranch.id atau 'ALL'
            let targetBranch = preselectOpts.branch_id;
            if (targetBranch === undefined || targetBranch === null || targetBranch === '') {
                const stockSelect = document.getElementById('stock-branch-select');
                if (stockSelect && stockSelect.value) {
                    targetBranch = stockSelect.value;
                } else if (state.currentBranch && state.currentBranch.id) {
                    targetBranch = String(state.currentBranch.id);
                } else {
                    targetBranch = 'ALL';
                }
            }

            // Populate branch dropdown
            const branchSelect = document.getElementById('master-reset-branch-select');
            if (branchSelect) {
                let html = '<option value="ALL">🌐 SEMUA CABANG (Global Reset - Seluruh Database)</option>';
                if (state.branches && state.branches.length > 0) {
                    state.branches.forEach(b => {
                        const isSel = (String(targetBranch) === String(b.id)) ? 'selected' : '';
                        html += `<option value="${b.id}" ${isSel}>📍 Cabang: ${b.name} (${b.code || ''})</option>`;
                    });
                }
                branchSelect.innerHTML = html;
                branchSelect.value = String(targetBranch);
            }

            // Set checkboxes based on preselectOpts
            const optStocks = document.getElementById('reset-opt-stocks');
            const optSales = document.getElementById('reset-opt-sales');
            const optBom = document.getElementById('reset-opt-bom');
            const optShifts = document.getElementById('reset-opt-shifts');
            const optExpenses = document.getElementById('reset-opt-expenses');

            if (Object.keys(preselectOpts).length === 0) {
                if (optStocks) optStocks.checked = false;
                if (optSales) optSales.checked = true;
                if (optBom) optBom.checked = false;
                if (optShifts) optShifts.checked = true;
                if (optExpenses) optExpenses.checked = false;
            } else if (preselectOpts.source === 'stocks') {
                if (optStocks) optStocks.checked = true;
                if (optSales) optSales.checked = true;
                if (optBom) optBom.checked = true;
                if (optShifts) optShifts.checked = true;
                if (optExpenses) optExpenses.checked = false;
            } else {
                if (optStocks) optStocks.checked = !!preselectOpts.stocks;
                if (optSales) optSales.checked = !!preselectOpts.sales;
                if (optBom) optBom.checked = !!preselectOpts.bom;
                if (optShifts) optShifts.checked = (preselectOpts.shifts !== undefined ? !!preselectOpts.shifts : true);
                if (optExpenses) optExpenses.checked = !!preselectOpts.expenses;
            }

            // Inisialisasi Mode Tanggal: default 'ALL' atau sesuai preselectOpts.date_mode
            const initDateMode = preselectOpts.date_mode || 'ALL';
            setMasterResetDateMode(initDateMode);

            const todayStr = (typeof getDeviceLocalDateString === 'function') ? getDeviceLocalDateString() : new Date().toISOString().split('T')[0];
            const startInput = document.getElementById('master-reset-start-date');
            const endInput = document.getElementById('master-reset-end-date');
            if (startInput) startInput.value = preselectOpts.start_date || todayStr;
            if (endInput) endInput.value = preselectOpts.end_date || todayStr;
            if (initDateMode === 'CUSTOM') {
                updateResetDateScopeInfo();
            }

            const optRestoreStock = document.getElementById('reset-opt-restore-stock');
            if (optRestoreStock) optRestoreStock.checked = true;

            const optKeepInitial = document.getElementById('reset-opt-keep-initial-stock');
            if (optKeepInitial) optKeepInitial.checked = !!preselectOpts.keep_initial_stock;
            updateResetKeepInitialUI();

            // Auto-fill credentials if Superadmin
            if (state.loggedInUser && ['SUPER_ADMIN', 'SUPERADMIN'].includes(state.loggedInUser.role)) {
                document.getElementById('master-reset-admin-pin').value = state.loggedInUser.pin || '999999';
                document.getElementById('master-reset-admin-password').value = 'admin123';
            } else {
                document.getElementById('master-reset-admin-pin').value = '';
                document.getElementById('master-reset-admin-password').value = '';
            }

            // Reset confirmation text
            const confirmInput = document.getElementById('master-reset-confirm-text');
            if (confirmInput) confirmInput.value = '';

            updateResetScopeInfo();

            const modal = document.getElementById('master-reset-modal');
            if (modal) modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeMasterResetModal() {
            const modal = document.getElementById('master-reset-modal');
            if (modal) modal.classList.add('hidden');
        }

        // Backward compatibility alias
        function openPurgeSalesModal() {
            openMasterResetModal({ sales: true });
        }
        function closePurgeSalesModal() {
            closeMasterResetModal();
        }

        function openPurgeExpenseModal(customBranchId = null) {
            const bSelect = document.getElementById('exp-ledger-branch-select');
            let targetBranch = customBranchId;
            if (targetBranch === null || targetBranch === undefined) {
                targetBranch = (bSelect && bSelect.value) ? bSelect.value : 'ALL';
            }
            openMasterResetModal({
                expenses: true,
                branch_id: targetBranch
            });
        }

        function toggleSelectAllResetOptions(checked) {
            const optStocks = document.getElementById('reset-opt-stocks');
            const optSales = document.getElementById('reset-opt-sales');
            const optBom = document.getElementById('reset-opt-bom');
            const optShifts = document.getElementById('reset-opt-shifts');
            const optExpenses = document.getElementById('reset-opt-expenses');

            if (optStocks) optStocks.checked = checked;
            if (optSales) optSales.checked = checked;
            if (optBom) optBom.checked = checked;
            if (optShifts) optShifts.checked = checked;
            if (optExpenses) optExpenses.checked = checked;
            updateResetKeepInitialUI();
        }

        function onKeepInitialStockToggle() {
            const optKeep = document.getElementById('reset-opt-keep-initial-stock');
            const optStocks = document.getElementById('reset-opt-stocks');
            if (optKeep && optKeep.checked && optStocks && !optStocks.checked) {
                optStocks.checked = true;
            }
            updateResetKeepInitialUI();
        }

        function updateResetKeepInitialUI() {
            const optStocks = document.getElementById('reset-opt-stocks');
            const optKeep = document.getElementById('reset-opt-keep-initial-stock');
            const wrapper = document.getElementById('reset-keep-initial-stock-wrapper');
            const stockBadge = document.getElementById('reset-opt-stocks-badge');
            const dateContainer = document.getElementById('master-reset-date-container');
            const isDateCustom = dateContainer ? !dateContainer.classList.contains('hidden') : false;

            if (wrapper) {
                if (optStocks && !optStocks.checked) {
                    wrapper.classList.add('opacity-60');
                } else {
                    wrapper.classList.remove('opacity-60');
                }
            }

            if (stockBadge && !isDateCustom) {
                if (optKeep && optKeep.checked) {
                    stockBadge.innerText = 'Kembali ke Stok Awal';
                    stockBadge.className = 'px-1.5 py-0.2 rounded text-[9px] bg-emerald-100 text-emerald-800 font-semibold';
                } else {
                    stockBadge.innerText = 'Stok = 0';
                    stockBadge.className = 'px-1.5 py-0.2 rounded text-[9px] bg-rose-100 text-rose-800 font-semibold';
                }
            }
        }

        function updateResetScopeInfo() {
            const select = document.getElementById('master-reset-branch-select');
            const badge = document.getElementById('reset-scope-badge');
            const desc = document.getElementById('reset-scope-desc');
            const btnAll = document.getElementById('btn-scope-all');
            const btnSpec = document.getElementById('btn-scope-specific');
            if (!select || !badge || !desc) return;

            const val = select.value;
            if (val === 'ALL') {
                badge.className = 'px-2.5 py-1 rounded-full text-[10px] font-black bg-rose-600 text-white shadow-xs';
                badge.innerText = '🌐 SEMUA CABANG (GLOBAL)';
                desc.innerHTML = '<span class="text-rose-700 font-bold">PERINGATAN:</span> Operasi akan mereset data pada <b>SELURUH CABANG</b> (Multi-Cabang) di seluruh database sistem secara serentak!';
                if (btnAll) {
                    btnAll.className = 'py-2 px-3 rounded-xl border-2 text-[11px] font-black flex items-center justify-center space-x-1.5 transition-all bg-rose-50 border-rose-600 text-rose-800 shadow-xs';
                }
                if (btnSpec) {
                    btnSpec.className = 'py-2 px-3 rounded-xl border text-[11px] font-bold flex items-center justify-center space-x-1.5 transition-all bg-white border-slate-300 text-slate-600 hover:border-slate-400';
                }
            } else {
                const text = select.options[select.selectedIndex] ? select.options[select.selectedIndex].text : `Cabang #${val}`;
                badge.className = 'px-2.5 py-1 rounded-full text-[10px] font-black bg-indigo-600 text-white shadow-xs';
                badge.innerText = '📍 ' + text.replace('📍 Cabang: ', '');
                desc.innerHTML = `Operasi reset <b>HANYA BERDAMPAK</b> pada <b>${text}</b>. Cabang lainnya tetap utuh dan aman.`;
                if (btnAll) {
                    btnAll.className = 'py-2 px-3 rounded-xl border text-[11px] font-bold flex items-center justify-center space-x-1.5 transition-all bg-white border-slate-300 text-slate-600 hover:border-slate-400';
                }
                if (btnSpec) {
                    btnSpec.className = 'py-2 px-3 rounded-xl border-2 text-[11px] font-black flex items-center justify-center space-x-1.5 transition-all bg-indigo-50 border-indigo-600 text-indigo-800 shadow-xs';
                }
            }
        }

        async function submitMasterResetForm(e) {
            e.preventDefault();
            const submitBtn = document.getElementById('master-reset-submit-btn');
            const branchId = document.getElementById('master-reset-branch-select').value;
            
            const purgeStocks = document.getElementById('reset-opt-stocks').checked;
            const purgeSales = document.getElementById('reset-opt-sales').checked;
            const purgeBom = document.getElementById('reset-opt-bom').checked;
            const purgeShifts = document.getElementById('reset-opt-shifts').checked;
            const purgeExpenses = document.getElementById('reset-opt-expenses') ? document.getElementById('reset-opt-expenses').checked : false;

            if (!purgeStocks && !purgeSales && !purgeBom && !purgeShifts && !purgeExpenses) {
                alert('Pilih minimal salah satu opsi data yang ingin direset!');
                return;
            }

            const adminPin = document.getElementById('master-reset-admin-pin').value.trim();
            const adminPassword = document.getElementById('master-reset-admin-password').value.trim();
            const confirmText = document.getElementById('master-reset-confirm-text').value.trim().toUpperCase();

            if (!['RESET DATA', 'RESET', 'HAPUS', 'HAPUS DATA', 'HAPUS PENJUALAN', 'HAPUS BEBAN'].includes(confirmText)) {
                alert('Teks konfirmasi salah! Anda wajib mengetik "RESET DATA".');
                return;
            }

            if (!adminPin && !adminPassword && (!state.loggedInUser || !['SUPER_ADMIN', 'SUPERADMIN'].includes(state.loggedInUser.role))) {
                alert('Masukkan PIN atau Kata Sandi Super Admin untuk otorisasi reset data!');
                return;
            }

            const branchLabel = branchId === 'ALL' ? 'SEMUA CABANG (GLOBAL WIPE)' : ((document.getElementById('master-reset-branch-select').selectedOptions[0] ? document.getElementById('master-reset-branch-select').selectedOptions[0].text : '') || `Cabang #${branchId}`);
            
            // Evaluasi mode tanggal
            const isDateCustom = !document.getElementById('master-reset-date-container').classList.contains('hidden');
            let startDateVal = null;
            let endDateVal = null;
            let restoreSalesStockVal = false;

            if (isDateCustom) {
                startDateVal = document.getElementById('master-reset-start-date') ? document.getElementById('master-reset-start-date').value : '';
                endDateVal = document.getElementById('master-reset-end-date') ? document.getElementById('master-reset-end-date').value : '';
                if (!startDateVal || !endDateVal) {
                    alert('Harap tentukan Tanggal Mulai dan Tanggal Selesai untuk reset data berdasarkan tanggal!');
                    return;
                }
                const restoreCb = document.getElementById('reset-opt-restore-stock');
                restoreSalesStockVal = restoreCb ? restoreCb.checked : true;
            }

            const zeroPhysicalStockVal = isDateCustom ? (document.getElementById('reset-opt-zero-physical-stock') ? document.getElementById('reset-opt-zero-physical-stock').checked : false) : true;
            const keepInitialStockVal = document.getElementById('reset-opt-keep-initial-stock') ? document.getElementById('reset-opt-keep-initial-stock').checked : false;

            const dateScopeText = isDateCustom ? `Rentang Tanggal: ${startDateVal} s/d ${endDateVal}` : 'Rentang Tanggal: SELURUH DATA SEKALIGUS (All-Time)';

            const selectedItems = [];
            if (purgeStocks) {
                let stockLabel = isDateCustom ? ('1. Bersihkan Kartu Pergerakan Stok pada Tanggal Terpilih' + (zeroPhysicalStockVal ? ' (Saldo fisik cabang dinolkan)' : '')) : '1. Stok Seluruh Produk (Set ke 0)';
                if (keepInitialStockVal) stockLabel += ' — KECUALI Stok Awal (dipertahankan)';
                selectedItems.push(stockLabel);
            }
            if (purgeSales) selectedItems.push('2. Riwayat Transaksi Penjualan & Piutang' + (isDateCustom && restoreSalesStockVal ? ' (Stok fisik dipulihkan)' : ''));
            if (purgeBom) selectedItems.push('3. Log Pemakaian Bahan Baku (BOM)');
            if (purgeShifts) selectedItems.push('4. Riwayat Laporan Shift, Meteran Air & Stok Acuan Malam Kemarin (Reset ke 0)');
            if (purgeExpenses) selectedItems.push('5. Buku Catatan Beban Operasional Cabang');

            const finalConfirm = confirm(`⚠️ PERINGATAN TINGKAT TINGGI!\n\nAnda akan MENGHAPUS / MERESET:\n• ${selectedItems.join('\n• ')}\n\nLingkup Target: ${branchLabel}\nPeriode: ${dateScopeText}\n\nOperasi ini bersifat PERMANEN dan TIDAK DAPAT DIBATALKAN!\n\nApakah Anda benar-benar yakin ingin mengeksekusi reset?`);
            if (!finalConfirm) return;

            submitBtn.disabled = true;
            submitBtn.innerHTML = `<span>Mengeksekusi Reset...</span>`;

            try {
                const res = await fetch('api.php?action=master_reset_data', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        branch_id: branchId,
                        date_scope: isDateCustom ? 'CUSTOM' : 'ALL',
                        start_date: startDateVal,
                        end_date: endDateVal,
                        restore_sales_stock: restoreSalesStockVal,
                        reset_physical_stock_zero: zeroPhysicalStockVal,
                        keep_initial_stock: keepInitialStockVal,
                        purge_stocks: purgeStocks,
                        purge_sales: purgeSales,
                        purge_bom: purgeBom,
                        purge_shifts: purgeShifts,
                        purge_expenses: purgeExpenses,
                        confirm_text: confirmText,
                        admin_pin: adminPin || '999999',
                        admin_password: adminPassword || 'admin123',
                        admin_user_id: state.loggedInUser ? state.loggedInUser.id : 1
                    })
                });

                const data = await res.json();
                if (data.success) {
                    alert(`✅ ${data.message}`);
                    closeMasterResetModal();

                    // Bersihkan cache status shift lokal agar opening toko hari ini langsung bersih dari awal
                    if (purgeShifts) {
                        state.activeShift = null;
                        state.branchClosedToday = false;
                        state.finalClosedShift = null;
                        state.currentUserHasClosedShift = false;
                        window.userHasClosedShift = false;
                        if (typeof renderShiftBanner === 'function') renderShiftBanner();
                        if (typeof updateShiftReportSubtabVisibility === 'function') updateShiftReportSubtabVisibility();
                    }

                    // Refresh relevant tables and views
                    if (typeof loadSalesReports === 'function') loadSalesReports();
                    if (typeof loadBomUsageReport === 'function') loadBomUsageReport();
                    if (typeof loadShiftReports === 'function') loadShiftReports();
                    if (typeof loadStockInventory === 'function') loadStockInventory();
                    if (typeof loadStockMovements === 'function') loadStockMovements();
                    if (typeof loadReceivablesReport === 'function') loadReceivablesReport();
                    if (typeof loadSaleCancellations === 'function') loadSaleCancellations();
                    if (typeof loadBranchExpensesTable === 'function') loadBranchExpensesTable();
                    if (typeof bootstrapApp === 'function') bootstrapApp();
                } else {
                    alert(`❌ GAGAL: ${data.message || 'Terjadi kesalahan sistem'}`);
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan koneksi saat mereset data.');
            } finally {
                submitBtn.disabled = false;
                submitBtn.innerHTML = `<i data-lucide="trash-2" class="w-4 h-4"></i><span>Eksekusi Reset Sekarang</span>`;
                lucide.createIcons();
            }
        }

        // Backward compatibility
        async function submitPurgeSalesForm(e) {
            submitMasterResetForm(e);
        }

        // ==========================================
        // 15. CONTROLLER PENGATURAN SISTEM, ROLE & CETAK
        // ==========================================
        let settingsSubtabActive = 'general';

        function setSettingsSubtab(subtab) {
            settingsSubtabActive = subtab;
            const subtabs = ['general', 'roles', 'printer', 'receipt', 'payslip', 'notifications', 'sync', 'security'];
            const activeClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-indigo-600 text-white shadow-2xs';
            const inactiveClass = 'px-3 sm:px-3.5 py-1.5 sm:py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap shrink-0 flex items-center space-x-1.5 sm:space-x-2 bg-slate-100 hover:bg-slate-200/80 text-slate-700 hover:text-slate-900 dark:bg-slate-800 dark:hover:bg-slate-700 dark:text-slate-300 dark:hover:text-white border border-transparent dark:border-slate-700';

            subtabs.forEach(st => {
                const el = document.getElementById(`settings-subtab-${st}`);
                const btn = document.getElementById(`settings-tab-btn-${st}`);
                if (st === subtab) {
                    if (el) el.classList.remove('hidden');
                    if (btn) btn.className = activeClass;
                } else {
                    if (el) el.classList.add('hidden');
                    if (btn) btn.className = inactiveClass;
                }
            });

            if (subtab === 'receipt') updateReceiptLivePreview();
            if (subtab === 'roles') renderRolePermissionsMatrix();
            if (subtab === 'security') loadSecurityShieldStatus(false);
            lucide.createIcons();
        }

        async function loadSecurityShieldStatus(isManualRefresh) {
            try {
                const res = await fetch('api.php?action=get_security_status');
                const json = await res.json();
                if (!json || !json.success || !json.data) {
                    if (isManualRefresh && json && json.message) alert(json.message);
                    return;
                }

                const d = json.data;
                const ipBadge = document.getElementById('sec-current-ip-badge');
                if (ipBadge) ipBadge.textContent = d.current_client_ip || '127.0.0.1';

                const bannedBadge = document.getElementById('sec-banned-count-badge');
                if (bannedBadge) bannedBadge.textContent = (d.total_banned_ips || 0) + ' IP';

                const logsBadge = document.getElementById('sec-logs-count-badge');
                if (logsBadge) logsBadge.textContent = (d.total_incidents_logged || 0) + ' Aktivitas';

                // Render Banned IPs
                const bannedTbody = document.getElementById('sec-banned-ips-tbody');
                if (bannedTbody) {
                    if (!d.banned_ips || d.banned_ips.length === 0) {
                        bannedTbody.innerHTML = '<tr><td colspan="5" class="py-6 text-center text-slate-400 dark:text-slate-500 text-xs">Semua aman! Tidak ada alamat IP yang sedang diblokir.</td></tr>';
                    } else {
                        bannedTbody.innerHTML = d.banned_ips.map(function(b) {
                            return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50">' +
                                '<td class="py-2.5 px-3 font-mono font-bold text-rose-700 dark:text-rose-400">' + escapeHtml(b.ip_address) + '</td>' +
                                '<td class="py-2.5 px-3 text-slate-600 dark:text-slate-300">' + escapeHtml(b.reason || 'Mencurigakan') + '</td>' +
                                '<td class="py-2.5 px-3 font-mono text-[11px] text-slate-500 dark:text-slate-400">' + escapeHtml(b.banned_at || '-') + '</td>' +
                                '<td class="py-2.5 px-3 font-mono text-[11px] text-slate-500 dark:text-slate-400">' + escapeHtml(b.banned_until || '-') + '</td>' +
                                '<td class="py-2.5 px-3 text-center">' +
                                    '<button type="button" onclick="executeUnbanSecurityIp(\'' + escapeHtml(b.ip_address) + '\')" class="px-2.5 py-1 bg-emerald-50 dark:bg-emerald-950/80 hover:bg-emerald-100 dark:hover:bg-emerald-900 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800 rounded-lg text-[10px] font-bold transition-all">' +
                                        'Buka Blokir' +
                                    '</button>' +
                                '</td>' +
                            '</tr>';
                        }).join('');
                    }
                }

                // Render Audit Logs
                const logsTbody = document.getElementById('sec-audit-logs-tbody');
                if (logsTbody) {
                    if (!d.recent_logs || d.recent_logs.length === 0) {
                        logsTbody.innerHTML = '<tr><td colspan="5" class="py-6 text-center text-slate-400 dark:text-slate-500 text-xs">Belum ada rekaman insiden keamanan.</td></tr>';
                    } else {
                        logsTbody.innerHTML = d.recent_logs.map(function(l) {
                            var typeClass = 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700';
                            if (l.event_type === 'LOGIN_SUCCESS') {
                                typeClass = 'bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800/80 font-bold';
                            } else if (l.event_type === 'LOGIN_FAILED') {
                                typeClass = 'bg-amber-100 dark:bg-amber-950/80 text-amber-800 dark:text-amber-300 border border-amber-200 dark:border-amber-800/80 font-bold';
                            } else if (l.event_type === 'LOGIN_LOCKOUT' || l.event_type === 'BRUTE_FORCE_BLOCKED' || l.event_type === 'IP_BANNED') {
                                typeClass = 'bg-rose-100 dark:bg-rose-950/80 text-rose-800 dark:text-rose-300 border border-rose-200 dark:border-rose-800/80 font-bold';
                            } else if (l.event_type.indexOf('SQL') !== -1 || l.event_type.indexOf('WAF') !== -1 || l.event_type.indexOf('RCE') !== -1) {
                                typeClass = 'bg-purple-100 dark:bg-purple-950/80 text-purple-800 dark:text-purple-300 border border-purple-200 dark:border-purple-800/80 font-bold';
                            }

                            return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/50">' +
                                '<td class="py-2 px-3 font-mono text-[10px] text-slate-500 dark:text-slate-400 whitespace-nowrap">' + escapeHtml(l.created_at || '-') + '</td>' +
                                '<td class="py-2 px-3 font-mono font-semibold text-slate-700 dark:text-slate-300 whitespace-nowrap">' + escapeHtml(l.ip_address) + '</td>' +
                                '<td class="py-2 px-3"><span class="px-2 py-0.5 rounded text-[10px] ' + typeClass + '">' + escapeHtml(l.event_type) + '</span></td>' +
                                '<td class="py-2 px-3 text-slate-600 dark:text-slate-300 max-w-xs truncate" title="' + escapeHtml(l.details || '') + '">' + escapeHtml(l.details || '-') + '</td>' +
                                '<td class="py-2 px-3 font-mono text-[10px] text-slate-400 dark:text-slate-500 max-w-xs truncate" title="' + escapeHtml(l.request_uri || l.user_agent || '') + '">' + escapeHtml(l.request_uri || '-') + '</td>' +
                            '</tr>';
                        }).join('');
                    }
                }

                if (isManualRefresh) {
                    alert('Status Perisai Keamanan Siber berhasil diperbarui!');
                }
            } catch (err) {
                console.error('Gagal memuat status keamanan:', err);
            }
        }

        async function executeUnbanSecurityIp(ipAddress) {
            if (!confirm('Buka pemblokiran untuk alamat IP ' + ipAddress + '?')) return;
            try {
                const res = await fetch('api.php?action=unban_security_ip', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ ip_address: ipAddress })
                });
                const json = await res.json();
                if (json && json.success) {
                    alert(json.message || 'Pemblokiran IP berhasil dibuka.');
                    loadSecurityShieldStatus(false);
                } else {
                    alert((json && json.message) || 'Gagal membuka pemblokiran IP.');
                }
            } catch (err) {
                alert('Terjadi kesalahan jaringan.');
            }
        }

        function applyAppSettingsToUI() {
            const s = state.appSettings || {};

            // 1. Ubah Logo (Foto / Gambar Kustom atau Emoji)
            const logoEmoji = s.app_logo_emoji || '🛍️';
            const logoUrl = (s.app_logo_url && s.app_logo_url.trim()) ? s.app_logo_url.trim() : '';

            // Expanded Sidebar Logo
            const logoEl = document.getElementById('sidebar-app-logo');
            if (logoEl) {
                if (logoUrl) {
                    logoEl.className = 'w-10 h-10 rounded-xl bg-white/10 p-1 flex items-center justify-center shrink-0 overflow-hidden';
                    logoEl.innerHTML = `<img src="${logoUrl}" class="w-full h-full object-contain" alt="Logo" onerror="this.onerror=null; this.parentElement.className='p-2 bg-indigo-600 rounded-xl text-xl shrink-0'; this.parentElement.innerText='${logoEmoji}';">`;
                } else {
                    logoEl.className = 'p-2 bg-indigo-600 rounded-xl text-xl shrink-0';
                    logoEl.innerText = logoEmoji;
                }
            }

            // Collapsed Sidebar Logo
            const logoCollapsedEl = document.getElementById('sidebar-app-logo-collapsed');
            if (logoCollapsedEl) {
                if (logoUrl) {
                    logoCollapsedEl.className = 'group-hover:hidden transition-transform duration-200 flex items-center justify-center w-7 h-7';
                    logoCollapsedEl.innerHTML = `<img src="${logoUrl}" class="w-7 h-7 object-contain rounded-lg" alt="Logo" onerror="this.onerror=null; this.parentElement.className='text-xl group-hover:hidden transition-transform duration-200'; this.parentElement.innerText='${logoEmoji}';">`;
                } else {
                    logoCollapsedEl.className = 'text-xl group-hover:hidden transition-transform duration-200';
                    logoCollapsedEl.innerText = logoEmoji;
                }
            }

            // Login Screen Logo
            const loginLogoEl = document.getElementById('login-app-logo');
            if (loginLogoEl) {
                if (logoUrl) {
                    loginLogoEl.className = 'inline-flex items-center justify-center w-20 h-20 p-2 bg-indigo-100 dark:bg-indigo-950/80 rounded-2xl shadow-inner overflow-hidden mx-auto';
                    loginLogoEl.innerHTML = `<img src="${logoUrl}" class="max-w-full max-h-full object-contain" alt="Logo" onerror="this.onerror=null; this.parentElement.className='inline-block p-3 bg-indigo-100 dark:bg-indigo-950/80 rounded-2xl text-4xl shadow-inner'; this.parentElement.innerText='${logoEmoji}';">`;
                } else {
                    loginLogoEl.className = 'inline-block p-3 bg-indigo-100 dark:bg-indigo-950/80 rounded-2xl text-4xl shadow-inner';
                    loginLogoEl.innerText = logoEmoji;
                }
            }

            // 2. Ubah Nama Aplikasi & Slogan
            const appName = s.app_name || 'ESBAS RETAIL';
            const appSubtitle = s.app_subtitle || 'POS, BOM & ESS';
            const nameEl = document.getElementById('sidebar-app-name');
            const subEl = document.getElementById('sidebar-app-subtitle');
            if (nameEl) nameEl.innerText = appName;
            if (subEl) subEl.innerText = appSubtitle;

            // 3. Ubah Nama Perusahaan pada Dokumen Resmi (Laporan Laba Rugi & Slip Gaji)
            const companyName = (s.company_name && s.company_name.trim()) 
                ? s.company_name.trim() 
                : ((s.app_name && s.app_name.trim()) ? s.app_name.trim() : 'ESBAS RETAIL INDONESIA');
            const pnlCompEl = document.getElementById('pnl-header-company');
            if (pnlCompEl) pnlCompEl.innerText = companyName.toUpperCase();

            const payslipCompName = (s.payslip_company_name && s.payslip_company_name.trim())
                ? s.payslip_company_name.trim()
                : companyName;
            const slipCompEl = document.getElementById('slip-company-name');
            if (slipCompEl) slipCompEl.innerText = payslipCompName.toUpperCase();

            // Dokumen Title
            document.title = `${appName} - ${appSubtitle}`;
        }

