                { id: 'ess-subtab-btn-leaves', key: 'ess:leaves' },
                { id: 'ess-subtab-btn-attendance', key: 'ess:report' },
                { id: 'ess-subtab-btn-payslip', key: 'ess:payslip' },
                { id: 'ess-subtab-btn-loans', key: 'ess:loans' },

                // Products
                { id: 'prod-subtab-btn-catalog', key: 'products:fg' },
                { id: 'prod-subtab-btn-categories', key: 'products:cat' },
                { id: 'prod-subtab-btn-types', key: 'products:cat' },
                { id: 'prod-subtab-btn-units', key: 'products:cat' },
                { id: 'prod-subtab-btn-taxes', key: 'products:cat' },
                { id: 'prod-subtab-btn-opening_shift', key: 'products:fg' },

                // Stocks
                { id: 'subtab-btn-balance', key: 'stocks:balance' },
                { id: 'subtab-btn-movements', key: 'stocks:movements' },

                // Input Penambahan Stok
                { id: 'stockin-subtab-btn-manual', key: 'stock-in:manual' },
                { id: 'stockin-subtab-btn-transfer', key: 'stock-in:transfer' },

                // Expenses
                { id: 'subtab-btn-exp-ledger', key: 'expenses:ledger' },
                { id: 'subtab-btn-exp-category', key: 'expenses:category' },

                // Customers
                { id: 'subtab-btn-cust-list', key: 'customers:list' },
                { id: 'subtab-btn-cust-mitra', key: 'customers:mitra-pricing' },
                { id: 'subtab-btn-cust-branch', key: 'customers:category' },
                { id: 'subtab-btn-cust-category', key: 'customers:category' },
                { id: 'subtab-btn-cust-maps', key: 'customers:maps' },
                { id: 'subtab-btn-cust-discounts', key: 'customers:discounts' },

                // Logistics
                { id: 'subtab-btn-vehicles', key: 'logistics:couriers' },
                { id: 'subtab-btn-fuel', key: 'logistics:logs' },
                { id: 'subtab-btn-service', key: 'logistics:logs' },
                { id: 'subtab-btn-settings', key: 'logistics:settings' },
                { id: 'subtab-btn-maps', key: 'logistics:maps' },

                // Branches
                { id: 'subtab-btn-branch-table', key: 'branches:table' },
                { id: 'subtab-btn-branch-maps', key: 'branches:maps' },

                // Settings
                { id: 'settings-tab-btn-general', key: 'settings:general' },
                { id: 'settings-tab-btn-roles', key: 'settings:roles' },
                { id: 'settings-tab-btn-printer', key: 'settings:general' },
                { id: 'settings-tab-btn-receipt', key: 'settings:general' },
                { id: 'settings-tab-btn-payslip', key: 'settings:general' },
                { id: 'settings-tab-btn-notifications', key: 'settings:general' },
                { id: 'settings-tab-btn-sync', key: 'settings:sync' }
            ];

            subTabMapping.forEach(item => {
                const btn = document.getElementById(item.id);
                if (!btn) return;
                const allowed = isSuperAdmin ? true : hasUserPerm(item.key, 'view');
                if (allowed) {
                    btn.classList.remove('hidden');
                    btn.style.display = '';
                } else {
                    btn.classList.add('hidden');
                    btn.style.display = 'none';
                }
            });
        }

        function applyRolePermissionsToSidebar() {
            const curUser = state.currentUser || state.loggedInUser;
            if (!curUser) return;
            const role = (curUser.role || 'CASHIER').toUpperCase().trim();
            const isSuperAdmin = (role === 'SUPERADMIN' || role === 'SUPER_ADMIN' || role === 'SUPER ADMIN');

            // Ambil izin menu role
            const allMenus = ['dashboard', 'pos', 'reports', 'ess', 'employees', 'payroll', 'products', 'bom', 'stocks', 'stock-in', 'pnl', 'expenses', 'customers', 'logistics', 'branches', 'payments', 'discounts', 'sale-cancellations', 'settings'];

            allMenus.forEach(mKey => {
                const btn = document.getElementById(`tab-btn-${mKey}`);
                if (!btn) return;

                // Superadmin SELALU memiliki akses penuh ke seluruh menu
                let canAccess = true;
                if (!isSuperAdmin) {
                    if (mKey === 'dashboard') {
                        canAccess = (role === 'MANAGER' || role === 'BRANCH_MANAGER');
                    } else if (mKey === 'stock-in') {
                        canAccess = hasUserPerm('stock-in', 'view') || hasUserPerm('stock-in:manual', 'view') || hasUserPerm('stock-in:transfer', 'view');
                    } else {
                        canAccess = hasUserPerm(mKey, 'view');
                    }
                }

                if (canAccess) {
                    btn.classList.remove('hidden');
                    btn.style.display = 'flex';
                } else {
                    btn.classList.add('hidden');
                    btn.style.display = 'none';
                }
            });

            // Toggle Section Eksekutif container
            const secExec = document.getElementById('sidebar-sec-executive');
            if (secExec) {
                if (isSuperAdmin || role === 'MANAGER' || role === 'BRANCH_MANAGER') {
                    secExec.classList.remove('hidden');
                    secExec.style.display = 'block';
                } else {
                    secExec.classList.add('hidden');
                    secExec.style.display = 'none';
                }
            }
            updateShiftReportSubtabVisibility();
            updateStoreResetButtonsVisibility();
            applySubTabPermissions();
        }

        state.settingsSelectedBranchId = 0;

        async function loadAppSettingsModule() {
            try {
                populateSettingsBranchSelect();
                const branchId = state.settingsSelectedBranchId || 0;
                await loadBranchSettings(branchId);

                const resRoles = await fetch('api.php?action=get_role_permissions');
                const dataRoles = await resRoles.json();
                if (dataRoles.success) {
                    state.userRoles = dataRoles.roles || state.userRoles || [];
                    state.rolePermissions = dataRoles.permissions || [];
                    state.groupedRolePermissions = dataRoles.grouped || {};
                    renderRolePermissionsMatrix();
                }
            } catch (err) {
                console.error(err);
            }
        }

        function populateSettingsBranchSelect() {
            const selectEl = document.getElementById('settings-branch-select');
            if (!selectEl) return;
            const canAccessAll = canUserAccessAllBranches();
            const userBranch = getUserAssignedBranch();

            if (!canAccessAll) {
                selectEl.innerHTML = `<option value="${userBranch.id}">🏢 [Cabang ${userBranch.id}] ${escapeHtml(userBranch.name)}</option>`;
                selectEl.disabled = true;
                selectEl.value = String(userBranch.id);
            } else {
                selectEl.disabled = false;
                const curVal = selectEl.value || '0';
                let html = '<option value="0">🌐 [Standar Global] Semua Cabang / Kantor Pusat</option>';
                if (Array.isArray(state.branches)) {
                    state.branches.forEach(b => {
                        html += `<option value="${b.id}">🏢 [Cabang ${b.id}] ${escapeHtml(b.name)}</option>`;
                    });
                }
                selectEl.innerHTML = html;
                selectEl.value = curVal;
            }
        }

        async function onSettingsBranchChange() {
            const bId = parseInt(_val('settings-branch-select') || '0');
            state.settingsSelectedBranchId = bId;
            await loadBranchSettings(bId);
        }

        async function loadBranchSettings(branchId) {
            try {
                const res = await fetch('api.php?action=get_app_settings&branch_id=' + branchId);
                const data = await res.json();
                if (data.success) {
                    populateAppSettingsForm(data.settings || {}, data.has_override);

                    // Update Badge Status & Tombol Reset
                    const badge = document.getElementById('settings-branch-badge');
                    const btnReset = document.getElementById('btn-reset-branch-settings');
                    if (badge) {
                        if (branchId === 0) {
                            badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-indigo-100 text-indigo-700 border border-indigo-200';
                            badge.innerText = '🌐 Standar Global (Pusat)';
                        } else if (data.has_override) {
                            badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-emerald-100 text-emerald-800 border border-emerald-300';
                            badge.innerText = '🏢 Pengaturan Khusus Cabang Aktif';
                        } else {
                            badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 border border-slate-300';
                            badge.innerText = '🏢 Mewarisi Standar Pusat';
                        }
                    }

                    if (btnReset) {
                        if (branchId > 0 && data.has_override) {
                            btnReset.classList.remove('hidden');
                        } else {
                            btnReset.classList.add('hidden');
                        }
                    }
                }
            } catch (err) {
                console.error('Gagal memuat setting cabang:', err);
            }
        }

        async function resetCurrentBranchSettings() {
            const branchId = parseInt(_val('settings-branch-select') || '0');
            if (branchId <= 0) return;

            if (!confirm('Apakah Anda yakin ingin menghapus seluruh kustomisasi pengaturan cabang ini dan mengembalikannya ke pengaturan standar kantor pusat?')) {
                return;
            }

            try {
                const res = await fetch('api.php?action=reset_branch_settings', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ branch_id: branchId })
                });
                const data = await res.json();
                alert(data.message || 'Pengaturan cabang berhasil di-reset!');
                if (data.success) {
                    if (branchId === parseInt((state.currentBranch ? state.currentBranch.id : 1))) {
                        state.appSettings = data.settings || {};
                        applyAppSettingsToUI();
                    }
                    await loadBranchSettings(branchId);
                }
            } catch (err) {
                alert('Gagal me-reset pengaturan cabang.');
            }
        }

        function populateAppSettingsForm(settingsData, hasOverride) {
            const s = settingsData || state.appSettings || {};

            // 1. Identitas & Logo
            if (document.getElementById('set-app-name')) document.getElementById('set-app-name').value = s.app_name || 'ESBAS RETAIL';
            if (document.getElementById('set-app-subtitle')) document.getElementById('set-app-subtitle').value = s.app_subtitle || 'POS, BOM & ESS';
            if (document.getElementById('set-app-logo-emoji')) document.getElementById('set-app-logo-emoji').value = s.app_logo_emoji || '🛍️';
            if (document.getElementById('set-app-logo-url')) document.getElementById('set-app-logo-url').value = s.app_logo_url || '';
            updateLogoPreviewUI();
            if (document.getElementById('set-company-name')) document.getElementById('set-company-name').value = s.company_name || 'ESBAS RETAIL INDONESIA';
            if (document.getElementById('set-company-address')) document.getElementById('set-company-address').value = s.company_address || '';
            if (document.getElementById('set-company-phone')) document.getElementById('set-company-phone').value = s.company_phone || '';

            // 4. Printer
            if (document.getElementById('set-printer-type')) document.getElementById('set-printer-type').value = s.printer_type || 'BROWSER';
            if (document.getElementById('set-printer-ip')) document.getElementById('set-printer-ip').value = s.printer_ip_address || '192.168.1.200';
            if (document.getElementById('set-printer-port')) document.getElementById('set-printer-port').value = s.printer_ip_port || '9100';
            if (document.getElementById('set-printer-paper-width')) document.getElementById('set-printer-paper-width').value = s.printer_paper_width || '58mm';
            if (document.getElementById('set-printer-auto-cut')) document.getElementById('set-printer-auto-cut').checked = (s.printer_auto_cut == '1');
            if (document.getElementById('set-printer-cash-drawer')) document.getElementById('set-printer-cash-drawer').checked = (s.printer_cash_drawer == '1');

            // 5. Layout Struk Nota
            if (document.getElementById('set-receipt-header-title')) document.getElementById('set-receipt-header-title').value = s.receipt_header_title || 'ESBAS RETAIL TOKO';
            if (document.getElementById('set-receipt-header-subtitle')) document.getElementById('set-receipt-header-subtitle').value = s.receipt_header_subtitle || 'Pusat Belanja & Grosir Terpadu';
            if (document.getElementById('set-receipt-header-custom')) document.getElementById('set-receipt-header-custom').value = s.receipt_header_custom_text || '';
            if (document.getElementById('set-receipt-show-logo')) document.getElementById('set-receipt-show-logo').checked = (s.receipt_show_logo !== '0');
            if (document.getElementById('set-receipt-show-sku')) document.getElementById('set-receipt-show-sku').checked = (s.receipt_body_show_sku === '1');
            if (document.getElementById('set-receipt-compact')) document.getElementById('set-receipt-compact').checked = (s.receipt_body_compact_spacing === '1');
            if (document.getElementById('set-receipt-footer-1')) document.getElementById('set-receipt-footer-1').value = s.receipt_footer_line1 || 'Terima Kasih Atas Kunjungan Anda!';
            if (document.getElementById('set-receipt-footer-2')) document.getElementById('set-receipt-footer-2').value = s.receipt_footer_line2 || 'Barang yang sudah dibeli tidak dapat ditukar/dikembalikan.';
            if (document.getElementById('set-receipt-footer-3')) document.getElementById('set-receipt-footer-3').value = s.receipt_footer_line3 || 'Simpan struk ini sebagai bukti pembayaran yang sah.';

            // 6. Layout Slip Gaji
            if (document.getElementById('set-payslip-header-title')) document.getElementById('set-payslip-header-title').value = s.payslip_header_title || 'SLIP GAJI KARYAWAN';
            if (document.getElementById('set-payslip-company-name')) document.getElementById('set-payslip-company-name').value = s.payslip_company_name || 'PT ESBAS RETAIL NUSANTARA';
            if (document.getElementById('set-payslip-confidential')) document.getElementById('set-payslip-confidential').value = s.payslip_confidential_label || 'RAHASIA & PRIBADI (CONFIDENTIAL)';
            if (document.getElementById('set-payslip-show-terbilang')) document.getElementById('set-payslip-show-terbilang').checked = (s.payslip_show_terbilang !== '0');
            if (document.getElementById('set-payslip-show-attendance')) document.getElementById('set-payslip-show-attendance').checked = (s.payslip_show_attendance_detail !== '0');
            if (document.getElementById('set-payslip-signer-1')) document.getElementById('set-payslip-signer-1').value = s.payslip_signer_1_title || 'Penerima (Karyawan)';
            if (document.getElementById('set-payslip-signer-2')) document.getElementById('set-payslip-signer-2').value = s.payslip_signer_2_title || 'Finance & Payroll';
            if (document.getElementById('set-payslip-footer-notes')) document.getElementById('set-payslip-footer-notes').value = s.payslip_footer_notes || 'Slip gaji ini dicetak secara komputerisasi...';

            // 7. Notifikasi WA & Telegram
            if (document.getElementById('set-wa-provider')) document.getElementById('set-wa-provider').value = s.wa_gateway_provider || 'FONNTE';
            if (document.getElementById('set-wa-api-url')) document.getElementById('set-wa-api-url').value = s.wa_api_url || 'https://api.fonnte.com/send';
            if (document.getElementById('set-wa-token')) document.getElementById('set-wa-token').value = s.wa_api_token || '';
            if (document.getElementById('set-wa-template')) document.getElementById('set-wa-template').value = s.wa_template_message || '';
            if (document.getElementById('set-tg-token')) document.getElementById('set-tg-token').value = s.telegram_bot_token || '';
            if (document.getElementById('set-tg-chat-id')) document.getElementById('set-tg-chat-id').value = s.telegram_chat_id || '';
            if (document.getElementById('set-tg-template')) document.getElementById('set-tg-template').value = s.telegram_template_message || '';

            updateReceiptLivePreview();
        }

        async function saveAllAppSettings() {
            const branchId = parseInt(_val('settings-branch-select') || '0');

            const settingsPayload = {
                // 1 & 2. Logo & Nama Aplikasi
                app_name: _val('set-app-name').trim() || 'ESBAS RETAIL',
                app_subtitle: _val('set-app-subtitle').trim() || 'POS, BOM & ESS',
                app_logo_emoji: _val('set-app-logo-emoji').trim() || '🛍️',
                app_logo_url: _val('set-app-logo-url').trim() || '',
                company_name: _val('set-company-name').trim() || '',
                company_address: _val('set-company-address').trim() || '',
                company_phone: _val('set-company-phone').trim() || '',

                // 4. Printer USB / IP
                printer_type: _val('set-printer-type') || 'BROWSER',
                printer_ip_address: _val('set-printer-ip').trim() || '192.168.1.200',
                printer_ip_port: _val('set-printer-port').trim() || '9100',
                printer_paper_width: _val('set-printer-paper-width') || '58mm',
                printer_auto_cut: _chk('set-printer-auto-cut') ? '1' : '0',
                printer_cash_drawer: _chk('set-printer-cash-drawer') ? '1' : '0',

                // 5. Layout Nota Struk
                receipt_header_title: _val('set-receipt-header-title').trim() || 'ESBAS RETAIL TOKO',
                receipt_header_subtitle: _val('set-receipt-header-subtitle').trim() || 'Pusat Belanja & Grosir Terpadu',
                receipt_header_custom_text: _val('set-receipt-header-custom').trim() || '',
                receipt_show_logo: _chk('set-receipt-show-logo') ? '1' : '0',
                receipt_body_show_sku: _chk('set-receipt-show-sku') ? '1' : '0',
                receipt_body_compact_spacing: _chk('set-receipt-compact') ? '1' : '0',
                receipt_footer_line1: _val('set-receipt-footer-1').trim() || 'Terima Kasih Atas Kunjungan Anda!',
                receipt_footer_line2: _val('set-receipt-footer-2').trim() || '',
                receipt_footer_line3: _val('set-receipt-footer-3').trim() || '',

                // 6. Layout Slip Gaji
                payslip_header_title: _val('set-payslip-header-title').trim() || 'SLIP GAJI KARYAWAN',
                payslip_company_name: _val('set-payslip-company-name').trim() || 'PT ESBAS RETAIL NUSANTARA',
                payslip_confidential_label: _val('set-payslip-confidential').trim() || 'RAHASIA & PRIBADI (CONFIDENTIAL)',
                payslip_show_terbilang: _chk('set-payslip-show-terbilang') ? '1' : '0',
                payslip_show_attendance_detail: _chk('set-payslip-show-attendance') ? '1' : '0',
                payslip_signer_1_title: _val('set-payslip-signer-1').trim() || 'Penerima (Karyawan)',
                payslip_signer_2_title: _val('set-payslip-signer-2').trim() || 'Finance & Payroll',
                payslip_footer_notes: _val('set-payslip-footer-notes').trim() || '',

                // 7. Notifikasi WA & Telegram
                wa_gateway_provider: _val('set-wa-provider') || 'FONNTE',
                wa_api_url: _val('set-wa-api-url').trim() || 'https://api.fonnte.com/send',
                wa_api_token: _val('set-wa-token').trim() || '',
                wa_template_message: _val('set-wa-template').trim() || '',
                telegram_bot_token: _val('set-tg-token').trim() || '',
                telegram_chat_id: _val('set-tg-chat-id').trim() || '',
                telegram_template_message: _val('set-tg-template').trim() || ''
            };

            try {
                const res = await fetch('api.php?action=save_app_settings', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ 
                        branch_id: branchId,
                        settings: settingsPayload 
                    })
                });
                const data = await res.json();
                alert(data.message || 'Konfigurasi berhasil disimpan!');
                if (data.success) {
                    if (branchId === 0 || branchId === parseInt((state.currentBranch ? state.currentBranch.id : 1))) {
                        state.appSettings = { ...state.appSettings, ...settingsPayload };
                        applyAppSettingsToUI();
                    }
                    await loadBranchSettings(branchId);
                }
            } catch (err) {
                alert('Terjadi kesalahan koneksi server.');
            }
        }

        function updateReceiptLivePreview() {
            const showLogo = _chk('set-receipt-show-logo');
            const logoUrl = _val('set-app-logo-url').trim();
            const logoEmoji = _val('set-app-logo-emoji') || '🛍️';
            const logoEl = document.getElementById('prev-receipt-logo');
            if (logoEl) {
                if (!showLogo) {
                    logoEl.style.display = 'none';
                } else {
                    logoEl.style.display = 'block';
                    if (logoUrl) {
                        logoEl.innerHTML = `<img src="${logoUrl}" class="max-h-10 max-w-24 mx-auto object-contain mb-1" alt="Logo" onerror="this.onerror=null; this.parentElement.innerText='${logoEmoji}';">`;
                    } else {
                        logoEl.innerText = logoEmoji;
                    }
                }
            }

            if (document.getElementById('prev-receipt-title')) {
                document.getElementById('prev-receipt-title').innerText = _val('set-receipt-header-title') || 'ESBAS RETAIL TOKO';
            }
            if (document.getElementById('prev-receipt-subtitle')) {
                document.getElementById('prev-receipt-subtitle').innerText = _val('set-receipt-header-subtitle') || 'Pusat Belanja & Grosir';
            }
            if (document.getElementById('prev-receipt-custom')) {
                document.getElementById('prev-receipt-custom').innerText = _val('set-receipt-header-custom') || '';
            }

            const showSku = _chk('set-receipt-show-sku');
            if (document.getElementById('prev-item-1')) {
                document.getElementById('prev-item-1').innerText = showSku ? 'Air Galon RO 19L (PRD-001) x2' : 'Air Galon RO 19L x2';
            }
            if (document.getElementById('prev-item-2')) {
                document.getElementById('prev-item-2').innerText = showSku ? 'Kopi Arabika 250g (PRD-002) x1' : 'Kopi Arabika 250g x1';
            }

            if (document.getElementById('prev-receipt-f1')) {
                document.getElementById('prev-receipt-f1').innerText = _val('set-receipt-footer-1') || 'Terima Kasih!';
            }
            if (document.getElementById('prev-receipt-f2')) {
                document.getElementById('prev-receipt-f2').innerText = _val('set-receipt-footer-2') || '';
            }
            if (document.getElementById('prev-receipt-f3')) {
                document.getElementById('prev-receipt-f3').innerText = _val('set-receipt-footer-3') || '';
            }
        }

                function getRoleBadgeEmoji(code) {
            const c = (code || '').toUpperCase().replace(/_/g, '');
            if (c === 'SUPERADMIN') return '👑';
            if (c === 'BRANCHMANAGER' || c === 'MANAGER') return '👔';
            if (c === 'CASHIER') return '🛒';
            if (c === 'STAFF') return '📦';
            if (c.includes('KURIR') || c.includes('DRIVER')) return '🛵';
            if (c.includes('SUPERVISOR') || c.includes('SPV')) return '⭐';
            if (c.includes('GUDANG')) return '🏭';
            return '🛡️';
        }

