                    { product_name: 'Air Galon RO 19L', sku: 'PRD-001', qty: 2, unit_price: 19000, subtotal_price: 38000 },
                    { product_name: 'Kopi Arabika 250g', sku: 'PRD-002', qty: 1, unit_price: 35000, subtotal_price: 35000 }
                ]
            };
