        function cleanWhatsAppNumber(phone) {
            if (!phone) return '';
            let clean = String(phone).replace(/[^0-9]/g, '');
            if (clean.startsWith('0')) {
                clean = '62' + clean.slice(1);
            } else if (clean.startsWith('8')) {
                clean = '62' + clean;
            }
            return clean;
        }

        /**
         * Membangun teks nota belanja lengkap yang 100% selaras dengan Pengaturan Layout Nota Struk
         * Mencakup: Header (Logo, Judul, Subjudul, Cabang, Alamat, Teks Legal/NPWP), Metadata, Body Item (+ opsi SKU & kurir),
         * Rincian Total (Subtotal, Diskon, Pajak, Grand Total, Bayar, Kembalian), dan 3 Baris Footer.
         */
        function buildReceiptTextFromLayout(sale) {
            if (!sale) return '';
            const s = state.appSettings || {};

            // 1. BAGIAN HEADER (BAGIAN ATAS NOTA)
            const showLogo = (s.receipt_show_logo === '1' || s.receipt_show_logo === 1 || s.receipt_show_logo === true);
            const logoEmoji = s.app_logo_emoji || '🛍️';
            const storeTitle = s.receipt_header_title || (s.app_name || 'ESBAS RETAIL TOKO');
            const storeSubtitle = s.receipt_header_subtitle || (s.app_subtitle || 'Pusat Belanja & Grosir Terpadu');
            const branchName = sale.branch_name || (state.currentBranch ? state.currentBranch.name : 'Cabang') || s.company_name || 'Cabang Utama';
            const branchAddress = sale.branch_address || (state.currentBranch ? state.currentBranch.address : '') || '';
            const customLegalText = s.receipt_header_custom_text || '';

            let headerParts = [];
            if (showLogo) {
                headerParts.push(logoEmoji);
            }
            headerParts.push(`*${storeTitle}*`);
            if (storeSubtitle && storeSubtitle.trim()) {
                headerParts.push(storeSubtitle.trim());
            }
            let branchLine = branchName;
            if (branchAddress && branchAddress.trim()) {
                branchLine += ` • ${branchAddress.trim()}`;
            }
            headerParts.push(branchLine);
            if (customLegalText && customLegalText.trim()) {
                headerParts.push(customLegalText.trim());
            }

            // 2. METADATA TRANSAKSI (Persis sesuai Pratinjau Struk)
            const invoiceNo = sale.invoice_number || '-';
            const dateStr = sale.created_at || (new Date().toLocaleString('id-ID'));
            const cashierName = sale.cashier_name || (state.currentUser ? state.currentUser.name : 'Kasir') || 'Kasir';
            const custName = sale.customer_name || 'Pelanggan Umum';

            let metaParts = [
                `No:         *${invoiceNo}*`,
                `Waktu:      ${dateStr}`,
                `Kasir:      ${cashierName}`,
                `Pelanggan:  ${custName}`
            ];

            // 3. BAGIAN BODY (DAFTAR ITEM & RINCIAN)
            const showSku = (s.receipt_body_show_sku === '1' || s.receipt_body_show_sku === 1);
            const items = sale.items || [];
            let itemParts = items.map(it => {
                const prodName = it.product_name || it.name || 'Produk';
                const skuText = (showSku && it.sku) ? ` (${it.sku})` : '';
                const vName = (it.variant_name && !prodName.includes(it.variant_name)) ? ` [${it.variant_name}]` : '';
                const qty = it.qty || it.quantity || 1;
                const unitPrice = it.unit_price || (it.subtotal_price ? Math.round(it.subtotal_price / qty) : (it.price || 0));
                const sub = it.subtotal_price || it.subtotal || (unitPrice * qty);
                return `${prodName}${skuText}${vName} x${qty} : ${formatRupiah(sub)}`;
            });

            // Biaya Kirim Kurir / Layanan Antar
            const effectiveDriver = sale.driver_name || (sale.effective_driver_name ? sale.effective_driver_name : '');
            if (sale.delivery_fee && Number(sale.delivery_fee) > 0) {
                const dist = (sale.delivery_distance_km && Number(sale.delivery_distance_km) > 0) ? ` (${formatDecimal(sale.delivery_distance_km)} km)` : '';
                const driverInfo = effectiveDriver ? ` • Kurir: ${effectiveDriver}` : '';
                itemParts.push(`🛵 Biaya Kirim Kurir${dist}${driverInfo} : ${formatRupiah(sale.delivery_fee)}`);
            } else if (sale.delivery_status && sale.delivery_status !== 'NONE') {
                const dist = (sale.delivery_distance_km && Number(sale.delivery_distance_km) > 0) ? ` (${formatDecimal(sale.delivery_distance_km)} km)` : '';
                const driverInfo = effectiveDriver ? ` • Kurir: ${effectiveDriver}` : '';
                itemParts.push(`🛵 Layanan Antar Kurir${dist}${driverInfo} : Rp 0 (Termasuk Ongkir)`);
            }

            // 4. RINGKASAN TOTAL (Persis sesuai Pratinjau Struk)
            let totalParts = [];
            totalParts.push(`Subtotal:    ${formatRupiah(sale.subtotal || 0)}`);
            const discVal = Number(sale.discount) || 0;
            totalParts.push(`Diskon:      ${discVal > 0 ? '- ' + formatRupiah(discVal) : 'Rp 0'}`);
            if (sale.tax && Number(sale.tax) > 0) {
                totalParts.push(`Pajak (Tax): ${formatRupiah(sale.tax)}`);
            }
            totalParts.push(`*TOTAL:       ${formatRupiah(sale.grand_total || 0)}*`);

            const payMethod = sale.payment_method || 'TUNAI';
            const payLabel = (payMethod.toUpperCase().includes('CASH') || payMethod.toUpperCase() === 'TUNAI') ? 'TUNAI (CASH)' : payMethod;
            if (Number(sale.cash_received) > 0) {
                totalParts.push(`${payLabel}: ${formatRupiah(sale.cash_received)}`);
                totalParts.push(`Kembalian:   ${formatRupiah(sale.cash_change || 0)}`);
            } else {
                totalParts.push(`${payLabel}: ${formatRupiah(sale.grand_total || 0)}`);
            }

            // 5. BAGIAN FOOTER (CATATAN BAWAH NOTA)
            let footerParts = [];
            const f1 = s.receipt_footer_line1 || 'Terima Kasih Atas Kunjungan Anda!';
            const f2 = s.receipt_footer_line2 || '';
            const f3 = s.receipt_footer_line3 || '';
            if (f1 && f1.trim()) footerParts.push(f1.trim());
            if (f2 && f2.trim()) footerParts.push(f2.trim());
            if (f3 && f3.trim()) footerParts.push(f3.trim());

            const sepLine = '--------------------------------';

            return [
                headerParts.join('\n'),
                sepLine,
                metaParts.join('\n'),
                sepLine,
                itemParts.join('\n'),
                sepLine,
                totalParts.join('\n'),
                sepLine,
                footerParts.join('\n')
            ].join('\n');
        }

        function buildWhatsAppReceiptText(sale) {
            if (!sale) return '';
            const layoutReceipt = buildReceiptTextFromLayout(sale);
            const s = state.appSettings || {};

            const tpl = (s.wa_template_message || '').trim();
            // Jika template kosong, default {receipt_layout}, atau greeting bawaan lama yang tidak memiliki layout nota
            if (!tpl || tpl === '{receipt_layout}' || tpl.toLowerCase().startsWith('halo {customer_name}') || !tpl.includes('{')) {
                return layoutReceipt;
            }

            if (tpl.includes('{receipt_layout}')) {
                return tpl
                    .replace(/{receipt_layout}/g, layoutReceipt)
                    .replace(/{customer_name}/g, sale.customer_name || 'Pelanggan Umum')
                    .replace(/{invoice_number}/g, sale.invoice_number || '-');
            }

            // Jika ada template kustom lain tanpa {receipt_layout}, gabungkan dengan layout nota utuh di bawahnya
            return tpl + '\n\n' + layoutReceipt;
        }

        function launchWhatsAppDirect(cleanPhone, message) {
            const encodedText = encodeURIComponent(message);
            // Protocol whatsapp:// langsung memanggil aplikasi native WhatsApp di tablet / smartphone
            const waAppUrl = `whatsapp://send?phone=${cleanPhone}&text=${encodedText}`;
            const waWebUrl = `https://api.whatsapp.com/send?phone=${cleanPhone}&text=${encodedText}`;

            showToast('Membuka aplikasi WhatsApp...', 'info');

            // Trigger peluncuran aplikasi WhatsApp secara langsung melalui click event
            try {
                const link = document.createElement('a');
                link.href = waAppUrl;
                link.target = '_top';
                link.rel = 'noopener noreferrer';
                document.body.appendChild(link);
                link.click();
                setTimeout(() => {
                    try {
                        if (link.parentNode) link.parentNode.removeChild(link);
                    } catch (e) {}
                }, 500);
            } catch (err) {
                window.location.href = waAppUrl;
            }

            // Fallback jika browser tablet tertentu memblokir anchor click custom protocol:
            setTimeout(() => {
                if (document.hasFocus()) {
                    try {
                        window.location.href = waAppUrl;
                    } catch (e) {
                        window.open(waWebUrl, '_blank');
                    }
                }
            }, 600);
        }

        async function sendReceiptViaWA(customSale = null) {
            const sale = customSale || state.lastProcessedSale;
            if (!sale) {
                alert('Pilih atau selesaikan transaksi terlebih dahulu untuk kirim nota WA.');
                return;
            }

            // Ambil nomor telepon pelanggan dari data transaksi atau pelanggan aktif
            let rawPhone = (sale.customer_phone && sale.customer_phone !== '-') 
                ? sale.customer_phone 
                : (state.selectedCustomer && state.selectedCustomer.phone && state.selectedCustomer.phone !== '-' ? state.selectedCustomer.phone : '');

            let cleanPhone = cleanWhatsAppNumber(rawPhone);

            // Jika transaksi/pelanggan belum memiliki nomor telepon yang valid, baru mintakan nomor tujuan
            if (!cleanPhone || cleanPhone.length < 7) {
                const phoneInput = prompt('Pelanggan ini belum memiliki nomor telepon. Masukkan nomor WhatsApp tujuan:', '08');
                if (!phoneInput) return;
                cleanPhone = cleanWhatsAppNumber(phoneInput);
                if (!cleanPhone || cleanPhone.length < 7) {
                    alert('Nomor WhatsApp tidak valid. Pastikan nomor diawali dengan 08 atau 62 (minimal 7 digit).');
                    return;
                }
            }

            // 1. Susun pesan nota elektronik WhatsApp lengkap
            const receiptMessage = buildWhatsAppReceiptText(sale);

            // 2. Panggil aplikasi WhatsApp yang terpasang di tablet secara langsung
            launchWhatsAppDirect(cleanPhone, receiptMessage);

            // 3. Catat di backend di latar belakang tanpa mengganggu jalannya aplikasi
            try {
                fetch('api.php?action=test_send_electronic_receipt', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        channel: 'WA',
                        destination: cleanPhone,
                        invoice_number: sale.invoice_number,
                        branch_id: sale.branch_id || (state.currentBranch ? state.currentBranch.id : 1),
                        message: receiptMessage
                    })
                }).catch(() => {});
            } catch (e) {}
        }

        function sendReceiptViaWAFromDetail() {
            if (!currentDetailSaleData || !currentDetailSaleData.sale) {
                alert('Pilih atau buka detail transaksi terlebih dahulu.');
                return;
            }
            const s = currentDetailSaleData.sale;
            const items = currentDetailSaleData.items || [];
            sendReceiptViaWA({
                ...s,
                items: items
            });
        }

        async function sendReceiptViaTelegram() {
            if (!state.lastProcessedSale) {
                alert('Pilih atau selesaikan transaksi terlebih dahulu untuk kirim nota Telegram.');
                return;
            }
            const s = state.appSettings || {};
            const chatId = s.telegram_chat_id || prompt('Kirim Struk Telegram ke ID Chat / Channel Toko:', '-1001234567890');
            if (!chatId) return;

            try {
                const res = await fetch('api.php?action=test_send_electronic_receipt', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        channel: 'TELEGRAM',
                        destination: chatId,
                        invoice_number: state.lastProcessedSale.invoice_number
                    })
                });
                const data = await res.json();
                alert('Notifikasi Telegram:\n' + data.message);
            } catch (err) {
                alert('Gagal mengirim Telegram.');
            }
        }

        /* ======================================================== */
        /* EXECUTIVE DASHBOARD & REAL-TIME TRANSACTION MONITORING   */
        /* ======================================================== */

        function playNewTransactionBeep() {
            try {
                const AudioCtx = window.AudioContext || window.webkitAudioContext;
                if (!AudioCtx) return;
                const ctx = new AudioCtx();
                const now = ctx.currentTime;
                
                // Tone 1: 587.33 Hz (D5)
                const osc1 = ctx.createOscillator();
                const gain1 = ctx.createGain();
                osc1.type = 'sine';
                osc1.frequency.setValueAtTime(587.33, now);
                gain1.gain.setValueAtTime(0.12, now);
                gain1.gain.exponentialRampToValueAtTime(0.0001, now + 0.18);
                osc1.connect(gain1);
                gain1.connect(ctx.destination);
                osc1.start(now);
                osc1.stop(now + 0.18);

                // Tone 2: 880.00 Hz (A5)
                const osc2 = ctx.createOscillator();
                const gain2 = ctx.createGain();
                osc2.type = 'sine';
                osc2.frequency.setValueAtTime(880.0, now + 0.10);
                gain2.gain.setValueAtTime(0.15, now + 0.10);
                gain2.gain.exponentialRampToValueAtTime(0.0001, now + 0.35);
                osc2.connect(gain2);
                gain2.connect(ctx.destination);
                osc2.start(now + 0.10);
                osc2.stop(now + 0.35);
            } catch (e) {
                // AudioContext may be restricted by autoplay policy before user interaction
            }
        }

        function toggleExecSound() {
            state.execSoundEnabled = !state.execSoundEnabled;
            const btn = document.getElementById('btn-exec-sound');
            const icon = document.getElementById('exec-sound-icon');
            if (state.execSoundEnabled) {
                if (btn) btn.classList.remove('opacity-50');
                if (icon) {
                    icon.classList.remove('text-slate-500');
                    icon.classList.add('text-amber-400');
                }
                playNewTransactionBeep();
            } else {
                if (btn) btn.classList.add('opacity-50');
                if (icon) {
                    icon.classList.remove('text-amber-400');
                    icon.classList.add('text-slate-500');
                }
            }
        }

        function toggleExecAutoRefresh() {
            state.execAutoRefreshEnabled = !state.execAutoRefreshEnabled;
            const label = document.getElementById('exec-autorefresh-label');
            const btn = document.getElementById('btn-exec-autorefresh');
            if (state.execAutoRefreshEnabled) {
                if (label) label.innerText = 'Live 10d: ON';
                if (btn) {
                    btn.className = 'px-3 py-2 bg-emerald-600/30 hover:bg-emerald-600/40 text-emerald-300 border border-emerald-500/40 rounded-xl text-xs font-bold flex items-center space-x-1.5 transition-colors';
                }
                startExecAutoRefresh();
            } else {
                if (label) label.innerText = 'Live: PAUSED';
                if (btn) {
                    btn.className = 'px-3 py-2 bg-slate-800 hover:bg-slate-700 text-slate-400 border border-slate-700 rounded-xl text-xs font-bold flex items-center space-x-1.5 transition-colors';
                }
                stopExecAutoRefresh();
            }
        }

        function startExecAutoRefresh() {
            stopExecAutoRefresh();
            if (!state.execAutoRefreshEnabled) return;
            state.execAutoRefreshTimer = setInterval(() => {
                if (state.currentTab === 'dashboard') {
                    loadExecutiveDashboard(true);
                }
            }, 10000);
        }

        function stopExecAutoRefresh() {
            if (state.execAutoRefreshTimer) {
                clearInterval(state.execAutoRefreshTimer);
                state.execAutoRefreshTimer = null;
            }
        }

        function setExecDateFilter(preset) {
            const now = new Date();
            let start = '';
            let end = '';

            const formatDate = (d) => {
                const year = d.getFullYear();
                const month = String(d.getMonth() + 1).padStart(2, '0');
                const day = String(d.getDate()).padStart(2, '0');
                return `${year}-${month}-${day}`;
            };

            if (preset === 'today') {
                start = end = formatDate(now);
            } else if (preset === 'yesterday') {
                const y = new Date(now);
                y.setDate(y.getDate() - 1);
                start = end = formatDate(y);
            } else if (preset === 'week') {
                const w = new Date(now);
                w.setDate(w.getDate() - 6);
                start = formatDate(w);
                end = formatDate(now);
            } else if (preset === 'month') {
                const m = new Date(now.getFullYear(), now.getMonth(), 1);
                start = formatDate(m);
                end = formatDate(now);
            }

            state.execStartDate = start;
            state.execEndDate = end;

            // Highlight button
            const presets = ['today', 'yesterday', 'week', 'month'];
            presets.forEach(p => {
                const b = document.getElementById(`exec-date-btn-${p}`);
                if (!b) return;
                if (p === preset) {
                    b.className = 'exec-date-btn px-2.5 py-1 rounded-lg text-[11px] font-bold bg-amber-500 text-slate-950 transition-colors shadow-2xs';
                } else {
                    b.className = 'exec-date-btn px-2.5 py-1 rounded-lg text-[11px] font-semibold text-slate-600 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white transition-colors';
                }
            });

            loadExecutiveDashboard(false);
        }

        function onExecBranchFilterChange() {
            const el = document.getElementById('exec-branch-filter');
            if (el) {
                state.execSelectedBranchId = parseInt(el.value, 10) || 0;
            }
            loadExecutiveDashboard(false);
        }

        function formatRelativeTime(dateStr) {
            if (!dateStr) return '-';
            const d = new Date(dateStr.replace(' ', 'T'));
            if (isNaN(d.getTime())) return dateStr;
            const now = new Date();
            const diffSec = Math.floor((now.getTime() - d.getTime()) / 1000);
            if (diffSec < 15) return 'Baru saja';
            if (diffSec < 60) return `${diffSec} dtk lalu`;
            const diffMin = Math.floor(diffSec / 60);
            if (diffMin < 60) return `${diffMin} mnt lalu`;
            const diffHour = Math.floor(diffMin / 60);
            if (diffHour < 24) return `${diffHour} jam lalu`;
            return dateStr.split(' ')[1] || dateStr;
        }

        async function loadExecutiveDashboard(isAutoRefresh = false) {
            const curUser = state.currentUser || state.loggedInUser;
            if (!curUser) return;

            // Visual spinner on refresh icon if manual
            const refreshIcon = document.getElementById('exec-refresh-icon');
            if (!isAutoRefresh && refreshIcon) {
                refreshIcon.classList.add('animate-spin');
            }

            try {
                const branchId = state.execSelectedBranchId || 0;
                const startDate = state.execStartDate || new Date().toISOString().split('T')[0];
                const endDate = state.execEndDate || new Date().toISOString().split('T')[0];
                const userId = curUser.id || 0;

                const res = await fetch(`api.php?action=executive_dashboard&branch_id=${branchId}&start_date=${startDate}&end_date=${endDate}&user_id=${userId}`);
                const json = await res.json();

                if (!json.success && json.status !== 'success') {
                    if (!isAutoRefresh) alert(json.message || 'Gagal memuat dashboard eksekutif.');
                    return;
                }

                const data = json.data || json;
                const kpis = data.kpis || {};

                // 1. Update Sync Time
                const nowTime = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
                const syncEl = document.getElementById('exec-last-synced-time');
                if (syncEl) syncEl.innerText = `Sinkronisasi: ${nowTime} WIB`;

                // 2. Populate Branch Select if needed
                const branchSelect = document.getElementById('exec-branch-filter');
                const canAccessAll = json.is_super_admin !== undefined ? json.is_super_admin : (data.can_access_all_branches || canUserAccessAllBranches());
                const branchList = data.branches || (data.branch_performance ? data.branch_performance.map(b => ({ id: b.branch_id, code: b.branch_code, name: b.branch_name })) : state.branches) || [];

                if (branchSelect && branchSelect.options.length <= 1 && branchList.length > 0) {
                    branchSelect.innerHTML = '';
                    if (canAccessAll) {
                        const optAll = document.createElement('option');
                        optAll.value = '0';
                        optAll.innerText = '🌐 Semua Cabang (Konsolidasi Global)';
                        branchSelect.appendChild(optAll);
                    }
                    branchList.forEach(b => {
                        const opt = document.createElement('option');
                        opt.value = b.id;
                        opt.innerText = `🏪 ${b.name} (${b.code})`;
                        branchSelect.appendChild(opt);
                    });
                    branchSelect.value = String(state.execSelectedBranchId || (canAccessAll ? 0 : (branchList[0] ? branchList[0].id : 0) || 0));
                    if (!canAccessAll) {
                        branchSelect.disabled = true;
                        branchSelect.classList.add('opacity-80', 'cursor-not-allowed');
                    }
                }

                // 3. Update KPI Cards
                const revVal = kpis.total_revenue || 0;
                const elRev = document.getElementById('exec-kpi-revenue');
                if (elRev) elRev.innerText = formatRupiah(revVal);

                const discountVal = kpis.total_discounts !== undefined ? kpis.total_discounts : (kpis.total_discount || 0);
                const deliveryVal = kpis.total_delivery_fees !== undefined ? kpis.total_delivery_fees : (kpis.total_delivery_fee || 0);
                const elRevSub = document.getElementById('exec-kpi-revenue-sub');
                if (elRevSub) {
                    elRevSub.innerText = `Diskon: ${formatRupiah(discountVal)} • Ongkir: ${formatRupiah(deliveryVal)}`;
                }

                const txCountVal = kpis.total_transactions || 0;
                const elTx = document.getElementById('exec-kpi-transactions');
                if (elTx) elTx.innerText = `${txCountVal.toLocaleString('id-ID')} Struk`;

                const aovVal = kpis.avg_order_value !== undefined ? kpis.avg_order_value : (kpis.average_order_value || 0);
                const elAov = document.getElementById('exec-kpi-aov');
                if (elAov) elAov.innerText = `Rata-rata: ${formatRupiah(aovVal)} / struk (AOV)`;

                const marginVal = kpis.gross_margin_pct !== undefined ? kpis.gross_margin_pct : (kpis.margin_percentage || 0);
                const elMargin = document.getElementById('exec-kpi-margin-badge');
                if (elMargin) elMargin.innerText = `${marginVal}% Margin`;

                const elProfit = document.getElementById('exec-kpi-profit');
                if (elProfit) elProfit.innerText = formatRupiah(kpis.gross_profit || 0);

                const elCogs = document.getElementById('exec-kpi-cogs');
                if (elCogs) elCogs.innerText = `BOM / Modal: ${formatRupiah(kpis.total_cogs || 0)}`;

                const elBranches = document.getElementById('exec-kpi-branches');
                if (elBranches) elBranches.innerText = `${kpis.active_branches_count || 0} Cabang Aktif`;

                const elShifts = document.getElementById('exec-kpi-shifts');
                if (elShifts) elShifts.innerText = `${kpis.active_shifts_count || 0} Shift Kasir Beroperasi`;

                const elExpenses = document.getElementById('exec-kpi-expenses');
                if (elExpenses) elExpenses.innerText = formatRupiah(kpis.total_expenses || 0);

                const netCashVal = kpis.net_estimated_cash !== undefined ? kpis.net_estimated_cash : (kpis.net_cash_flow || 0);
                const elNetCash = document.getElementById('exec-kpi-net-cash');
                if (elNetCash) elNetCash.innerText = `Estimasi Kas Bersih: ${formatRupiah(netCashVal)}`;

                // 4. Update Live Stream Transactions Radar
                const txBody = document.getElementById('exec-live-transactions-body');
                const liveCountSub = document.getElementById('exec-live-count-sub');
                const recentTx = data.realtime_transactions || data.recent_transactions || [];

                if (liveCountSub) {
                    const filterName = (data.filters && data.filters.branch_name) || (data.filter && data.filter.branch_name) || 'Semua Cabang';
                    liveCountSub.innerText = `${recentTx.length} transaksi terakhir termonitor (${filterName})`;
                }

                // Chime Sound Detection for New Transactions
                if (recentTx.length > 0) {
                    const latestId = Math.max(...recentTx.map(t => Number(t.id || 0)));
                    if (state.execLastMaxSaleId > 0 && latestId > state.execLastMaxSaleId && state.execSoundEnabled) {
                        playNewTransactionBeep();
                    }
                    state.execLastMaxSaleId = Math.max(state.execLastMaxSaleId, latestId);
                }

                if (txBody) {
                    if (recentTx.length === 0) {
                        txBody.innerHTML = `
                            <tr>
                                <td colspan="6" class="py-12 text-center text-slate-400 dark:text-slate-500">
                                    <div class="flex flex-col items-center justify-center space-y-2">
                                        <span class="text-3xl">📭</span>
                                        <p class="font-bold text-xs text-slate-600 dark:text-slate-400">Belum ada aktivitas transaksi pada periode ini</p>
                                        <p class="text-[11px] text-slate-400 dark:text-slate-500">Transaksi kasir akan otomatis muncul secara live di sini saat diselesaikan.</p>
                                    </div>
                                </td>
                            </tr>
                        `;
                    } else {
                        txBody.innerHTML = recentTx.map((tx, idx) => {
                            const isNew = idx === 0 && isAutoRefresh;
                            const txDate = tx.created_at || tx.sale_date || '';
                            const relTime = tx.time_ago || formatRelativeTime(txDate);
                            const items = tx.items || [];
                            const itemsSummary = tx.items_summary || (items.map(it => `${it.product_name} (${formatDecimal(it.quantity)}x)`).join(', '));
                            const shortSummary = itemsSummary.length > 40 ? itemsSummary.substring(0, 38) + '...' : itemsSummary;
                            
                            // Badge payment
                            const pMethod = (tx.payment_method || 'CASH').toUpperCase();
                            let pBadgeClass = 'bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border-emerald-200 dark:border-emerald-800';
                            if (pMethod.includes('QRIS')) pBadgeClass = 'bg-blue-100 dark:bg-blue-950/80 text-blue-800 dark:text-blue-300 border-blue-200 dark:border-blue-800';
                            else if (pMethod.includes('TRANSFER')) pBadgeClass = 'bg-indigo-100 dark:bg-indigo-950/80 text-indigo-800 dark:text-indigo-300 border-indigo-200 dark:border-indigo-800';
                            else if (pMethod.includes('DEBIT') || pMethod.includes('EDC')) pBadgeClass = 'bg-purple-100 dark:bg-purple-950/80 text-purple-800 dark:text-purple-300 border-purple-200 dark:border-purple-800';
                            else if (pMethod.includes('TEMPO') || pMethod.includes('PIUTANG')) pBadgeClass = 'bg-amber-100 dark:bg-amber-950/80 text-amber-800 dark:text-amber-300 border-amber-200 dark:border-amber-800';

                            const isDelivery = (tx.delivery_method === 'DELIVERY') || (tx.delivery_status && tx.delivery_status !== 'PICKUP') || (Number(tx.delivery_fee || 0) > 0);
                            const totalAmount = tx.grand_total !== undefined ? tx.grand_total : (tx.final_amount !== undefined ? tx.final_amount : (tx.total_amount || 0));

                            return `
                                <tr class="hover:bg-amber-50/40 dark:hover:bg-slate-800/60 transition-colors ${isNew ? 'bg-emerald-50/60 dark:bg-emerald-950/40 animate-pulse' : ''}">
                                    <td class="py-2.5 px-3 whitespace-nowrap">
                                        <div class="flex flex-col">
                                            <span class="font-black text-slate-800 dark:text-slate-100 text-[11px]">${relTime}</span>
                                            <span class="text-[10px] text-slate-400 dark:text-slate-500 font-mono">${tx.time_formatted || (txDate.split(' ')[1] || '')}</span>
                                        </div>
                                    </td>
                                    <td class="py-2.5 px-3 whitespace-nowrap">
                                        <button type="button" onclick="openSaleDetailModal('${escapeHtml(tx.invoice_number)}')" class="font-mono font-bold text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 hover:underline flex items-center space-x-1" title="Buka Detail Nota Transaksi">
                                            <span>#${escapeHtml(tx.invoice_number)}</span>
                                            <i data-lucide="external-link" class="w-3 h-3"></i>
                                        </button>
                                        <span class="text-[10px] text-slate-400 dark:text-slate-500 block">${escapeHtml(tx.customer_name || 'Pelanggan Umum')}</span>
                                    </td>
                                    <td class="py-2.5 px-3 whitespace-nowrap">
                                        <div class="flex items-center space-x-1.5">
                                            <span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 border border-slate-200 dark:border-slate-700">${escapeHtml(tx.branch_name || '-')}</span>
                                            ${isDelivery ? '<span class="px-1 py-0.2 rounded text-[9px] font-bold bg-purple-100 dark:bg-purple-950/80 text-purple-700 dark:text-purple-300 border border-purple-200 dark:border-purple-800" title="Pesanan Dikirim Kurir">🛵 Kurir</span>' : ''}
                                        </div>
                                        <span class="text-[10px] text-slate-400 dark:text-slate-500 mt-0.5 block">Kasir: ${escapeHtml(tx.cashier_name || '-')}</span>
                                    </td>
                                    <td class="py-2.5 px-3 max-w-[220px]">
                                        <span class="text-[11px] text-slate-700 dark:text-slate-200 font-medium truncate block" title="${escapeHtml(itemsSummary)}">${escapeHtml(shortSummary || '-')}</span>
                                        <span class="text-[10px] text-slate-400 dark:text-slate-500">${tx.total_items_qty || items.length || 0} qty produk</span>
                                    </td>
                                    <td class="py-2.5 px-3 text-right whitespace-nowrap">
                                        <span class="font-black text-slate-900 dark:text-slate-100 text-xs sm:text-sm">${formatRupiah(totalAmount)}</span>
                                    </td>
                                    <td class="py-2.5 px-3 text-center whitespace-nowrap">
                                        <span class="px-2 py-0.5 rounded-full text-[10px] font-bold border ${pBadgeClass}">${escapeHtml(pMethod)}</span>
                                    </td>
                                </tr>
                            `;
                        }).join('');
                    }
                }

                // 5. Update Multi-Branch Leaderboard
                const rankingContainer = document.getElementById('exec-branch-leaderboard-container');
                const rankingCountBadge = document.getElementById('exec-branches-ranking-count');
                const branchRanking = data.branch_performance || data.branch_ranking || [];

                if (rankingCountBadge) rankingCountBadge.innerText = `${branchRanking.length} Cabang`;

                if (rankingContainer) {
                    if (branchRanking.length === 0) {
                        rankingContainer.innerHTML = `<p class="text-xs text-slate-400 dark:text-slate-500 text-center py-4">Belum ada data penjualan per cabang pada filter ini.</p>`;
                    } else {
                        const topRevenue = Math.max(...branchRanking.map(b => Number(b.revenue || b.total_revenue || 0)), 1);
                        rankingContainer.innerHTML = branchRanking.map((b, idx) => {
                            const rev = Number(b.revenue || b.total_revenue || 0);
                            const txCount = Number(b.transactions || b.total_transactions || 0);
                            const aovB = Number(b.aov || 0);
                            const pct = b.revenue_share_pct !== undefined ? Number(b.revenue_share_pct) : Math.min(100, Math.round((rev / topRevenue) * 100));
                            
                            let rankBadge = `<span class="w-6 h-6 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-black text-xs flex items-center justify-center shrink-0">#${idx + 1}</span>`;
                            if (idx === 0) rankBadge = `<span class="w-6 h-6 rounded-full bg-amber-400 text-slate-950 font-black text-xs flex items-center justify-center shrink-0 shadow-sm shadow-amber-400/40">🥇</span>`;
                            else if (idx === 1) rankBadge = `<span class="w-6 h-6 rounded-full bg-slate-300 dark:bg-slate-600 text-slate-900 dark:text-slate-100 font-black text-xs flex items-center justify-center shrink-0">🥈</span>`;
                            else if (idx === 2) rankBadge = `<span class="w-6 h-6 rounded-full bg-amber-700/40 text-amber-900 dark:text-amber-300 font-black text-xs flex items-center justify-center shrink-0">🥉</span>`;

                            return `
                                <div class="p-2.5 rounded-2xl bg-slate-50/80 dark:bg-slate-800/60 hover:bg-slate-100/80 dark:hover:bg-slate-800 transition-colors border border-slate-100 dark:border-slate-800 space-y-2">
                                    <div class="flex items-center justify-between">
                                        <div class="flex items-center space-x-2.5">
                                            ${rankBadge}
                                            <div>
                                                <h4 class="font-extrabold text-xs text-slate-800 dark:text-slate-100">${escapeHtml(b.branch_name)} <span class="text-slate-400 dark:text-slate-500 font-mono text-[10px]">(${escapeHtml(b.branch_code)})</span></h4>
                                                <p class="text-[10px] text-slate-500 dark:text-slate-400">${txCount.toLocaleString('id-ID')} transaksi &bull; AOV: ${formatRupiah(aovB)}</p>
                                            </div>
                                        </div>
                                        <span class="font-black text-xs text-slate-900 dark:text-slate-100">${formatRupiah(rev)}</span>
                                    </div>
                                    <!-- Progress bar -->
                                    <div class="w-full bg-slate-200/70 dark:bg-slate-700 h-2 rounded-full overflow-hidden">
                                        <div class="h-full bg-gradient-to-r from-amber-500 to-emerald-500 rounded-full transition-all duration-500" style="width: ${pct}%"></div>
                                    </div>
                                </div>
                            `;
                        }).join('');
                    }
                }

                // 6. Update Payment Distribution
                const paymentContainer = document.getElementById('exec-payment-methods-container');
                const pDist = data.payment_methods || data.payment_distribution || [];
                if (paymentContainer) {
                    if (pDist.length === 0) {
                        paymentContainer.innerHTML = `<p class="text-xs text-slate-400 dark:text-slate-500 text-center py-4">Belum ada data saluran pembayaran.</p>`;
                    } else {
                        const totalPayRev = pDist.reduce((acc, p) => acc + Number(p.total_amount || 0), 0) || 1;
                        paymentContainer.innerHTML = pDist.map(p => {
                            const pNominal = Number(p.total_amount || 0);
                            const pCount = Number(p.count || p.tx_count || 0);
                            const pShare = p.percentage !== undefined ? Number(p.percentage) : Math.round((pNominal / totalPayRev) * 100);
                            const pMethod = (p.payment_method || 'CASH').toUpperCase();

                            return `
                                <div class="space-y-1">
                                    <div class="flex items-center justify-between text-xs font-bold">
                                        <span class="text-slate-700 dark:text-slate-200 flex items-center space-x-1.5">
                                            <span>${escapeHtml(pMethod)}</span>
                                            <span class="text-[10px] font-normal text-slate-400 dark:text-slate-500">(${pCount} trx)</span>
                                        </span>
                                        <span class="text-slate-900 dark:text-slate-100">${formatRupiah(pNominal)} <span class="text-[10px] text-slate-400 dark:text-slate-500 font-normal">(${pShare}%)</span></span>
                                    </div>
                                    <div class="w-full bg-slate-100 dark:bg-slate-700 h-1.5 rounded-full overflow-hidden">
                                        <div class="h-full bg-indigo-600 dark:bg-indigo-500 rounded-full transition-all duration-500" style="width: ${pShare}%"></div>
                                    </div>
                                </div>
                            `;
                        }).join('');
                    }
                }

                // 7. Update Top Products Grid
                const topProdGrid = document.getElementById('exec-top-products-grid');
                const topProducts = data.top_products || [];
                if (topProdGrid) {
                    if (topProducts.length === 0) {
                        topProdGrid.innerHTML = `<div class="col-span-full text-center py-6 text-xs text-slate-400 dark:text-slate-500">Belum ada produk terjual pada periode ini.</div>`;
                    } else {
                        topProdGrid.innerHTML = topProducts.map((p, idx) => {
                            const salesVal = p.total_sales !== undefined ? p.total_sales : (p.total_revenue || 0);
                            return `
                                <div class="p-3 rounded-2xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200/80 dark:border-slate-700 hover:border-purple-300 dark:hover:border-purple-600 transition-all flex items-start space-x-3">
                                    <span class="w-7 h-7 rounded-xl bg-purple-100 dark:bg-purple-950/80 text-purple-800 dark:text-purple-300 font-black text-xs flex items-center justify-center shrink-0">#${idx + 1}</span>
                                    <div class="min-w-0 flex-1">
                                        <h4 class="font-bold text-xs text-slate-800 dark:text-slate-100 truncate" title="${escapeHtml(p.product_name)}">${escapeHtml(p.product_name)}</h4>
                                        <div class="flex items-center space-x-2 mt-1">
                                            <span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300">${formatDecimal(p.total_qty)} Terjual</span>
                                            <span class="text-[10px] text-slate-400 dark:text-slate-500 font-medium">${formatRupiah(salesVal)}</span>
                                        </div>
                                    </div>
                                </div>
                            `;
                        }).join('');
                    }
                }

                lucide.createIcons();
            } catch (err) {
                console.error('Error loading executive dashboard:', err);
                if (!isAutoRefresh) alert('Terjadi kesalahan saat memuat data dashboard eksekutif.');
            } finally {
                if (refreshIcon) {
                    setTimeout(() => { refreshIcon.classList.remove('animate-spin'); }, 400);
                }
            }
        }

        // Keyboard Shortcut: F12 for Payment Modal / Checkout, Escape to close
        window.addEventListener('keydown', (e) => {
            if (e.key === 'F12' && state.currentTab === 'pos') {
                e.preventDefault();
                const payModal = document.getElementById('pos-payment-modal');
                if (payModal && !payModal.classList.contains('hidden')) {
                    processCheckout();
                } else {
                    openPaymentModal();
                }
            } else if (e.key === 'Escape') {
                const payModal = document.getElementById('pos-payment-modal');
                if (payModal && !payModal.classList.contains('hidden')) {
                    closePaymentModal();
                }
                const custPromptModal = document.getElementById('pos-select-customer-modal');
                if (custPromptModal && !custPromptModal.classList.contains('hidden')) {
                    closeSelectCustomerModal();
                }
            }
        });

        // Tutup floating search results pelanggan jika pengguna mengklik di luar kontainer pencarian
        document.addEventListener('click', (e) => {
            const container = document.getElementById('pos-customer-search-container');
            if (container && !container.contains(e.target)) {
                closePosCustomerSearch();
                const input = document.getElementById('pos-customer-search-input');
                if (input && state.selectedCustomer && input.value !== state.selectedCustomer.name && document.activeElement !== input) {
                    input.value = state.selectedCustomer.name;
                }
            }
        });

        // ==========================================
        // 3D VOID PROCEDURAL WIREFRAME ENGINE (STARQUA AESTHETIC)
        // ==========================================
        var void3D = {
            canvas: null,
            ctx: null,
            animId: null,
            isRunning: false,
            rotX: 0.35,
            rotY: 0.45,
            targetRotX: 0.35,
            targetRotY: 0.45,
            meshRings: [],
            particles: [],
            numSteps: 90,
            tubeSteps: 8
        };

        function initVoid3DCanvas() {
            var canvas = document.getElementById('canvas-3d-void');
            if (!canvas) return;
            var ctx = canvas.getContext('2d');
            if (!ctx) return;

            void3D.canvas = canvas;
            void3D.ctx = ctx;

            // Generate Trefoil Torus Knot Curve (P=2, Q=3)
            var P = 2, Q = 3;
            var numSteps = void3D.numSteps;
            var tubeSteps = void3D.tubeSteps;
            var knotRadius = 1.85;
            var tubeRadius = 0.42;

            var curvePoints = [];
            for (var i = 0; i < numSteps; i++) {
                var t = (i / numSteps) * Math.PI * 2;
                var r = (Math.cos(Q * t) + 2.0) * (knotRadius * 0.46);
                var x = r * Math.cos(P * t);
                var y = r * Math.sin(P * t);
                var z = -Math.sin(Q * t) * 1.25;
                curvePoints.push({ x: x, y: y, z: z, t: t });
            }

            // Generate 3D Mesh Tube Rings along Frenet-like frame
            void3D.meshRings = [];
            for (var i = 0; i < numSteps; i++) {
                var curr = curvePoints[i];
                var next = curvePoints[(i + 1) % numSteps];
                var tx = next.x - curr.x;
                var ty = next.y - curr.y;
                var tz = next.z - curr.z;
                var tLen = Math.sqrt(tx * tx + ty * ty + tz * tz) || 1;
                tx /= tLen; ty /= tLen; tz /= tLen;

                var nx = -ty;
                var ny = tx;
                var nz = 0;
                var nLen = Math.sqrt(nx * nx + ny * ny + nz * nz);
                if (nLen < 0.001) {
                    nx = 1; ny = 0; nz = 0;
                } else {
                    nx /= nLen; ny /= nLen; nz /= nLen;
                }

                var bx = ty * nz - tz * ny;
                var by = tz * nx - tx * nz;
                var bz = tx * ny - ty * nx;

                var ring = [];
                for (var j = 0; j < tubeSteps; j++) {
                    var phi = (j / tubeSteps) * Math.PI * 2;
                    var cosP = Math.cos(phi) * tubeRadius;
                    var sinP = Math.sin(phi) * tubeRadius;
                    var vx = curr.x + (nx * cosP + bx * sinP);
                    var vy = curr.y + (ny * cosP + by * sinP);
                    var vz = curr.z + (nz * cosP + bz * sinP);
                    ring.push({ x: vx, y: vy, z: vz });
                }
                void3D.meshRings.push(ring);
            }

            // Ambient Dust Particles
            void3D.particles = [];
            for (var k = 0; k < 45; k++) {
                void3D.particles.push({
                    x: (Math.random() - 0.5) * 6,
                    y: (Math.random() - 0.5) * 6,
                    z: (Math.random() - 0.5) * 4,
                    size: Math.random() * 1.5 + 0.8,
                    alpha: Math.random() * 0.6 + 0.25,
                    speed: Math.random() * 0.006 + 0.003
                });
            }

            function resizeCanvas() {
                if (!void3D.canvas) return;
                var parent = void3D.canvas.parentElement;
                var w = parent ? parent.clientWidth : 600;
                var h = parent ? parent.clientHeight : 600;
                var dpr = window.devicePixelRatio || 1;
                void3D.canvas.width = Math.max(150, w) * dpr;
                void3D.canvas.height = Math.max(100, h) * dpr;
                void3D.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            }
            resizeCanvas();
            window.addEventListener('resize', resizeCanvas);

            // Interactive mouse / touch movement
            window.addEventListener('mousemove', function(e) {
                var halfW = window.innerWidth / 2;
                var halfH = window.innerHeight / 2;
                void3D.targetRotY = ((e.clientX - halfW) / halfW) * 0.75 + 0.45;
                void3D.targetRotX = -((e.clientY - halfH) / halfH) * 0.55 + 0.35;
            });

            window.addEventListener('touchmove', function(e) {
                if (e.touches && e.touches[0]) {
                    var t = e.touches[0];
                    var halfW = window.innerWidth / 2;
                    var halfH = window.innerHeight / 2;
                    void3D.targetRotY = ((t.clientX - halfW) / halfW) * 0.75 + 0.45;
                    void3D.targetRotX = -((t.clientY - halfH) / halfH) * 0.55 + 0.35;
                }
            }, { passive: true });

            startVoid3DCanvas();
        }

        function startVoid3DCanvas() {
            if (void3D.isRunning) return;
            void3D.isRunning = true;

            function loop() {
                if (!void3D.isRunning) return;
                var screen = document.getElementById('login-screen');
                if (!screen || screen.classList.contains('hidden') || screen.style.display === 'none') {
                    void3D.animId = requestAnimationFrame(loop);
                    return;
                }

                var canvas = void3D.canvas;
                var ctx = void3D.ctx;
                if (!canvas || !ctx) {
                    void3D.animId = requestAnimationFrame(loop);
                    return;
                }

                var parent = canvas.parentElement;
                var w = parent ? parent.clientWidth : 600;
                var h = parent ? parent.clientHeight : 600;
                if (w === 0 || h === 0) {
                    void3D.animId = requestAnimationFrame(loop);
                    return;
                }

                ctx.clearRect(0, 0, w, h);

                // Smooth damping rotation
                void3D.rotX += (void3D.targetRotX - void3D.rotX) * 0.045;
                void3D.rotY += (void3D.targetRotY - void3D.rotY) * 0.045;
                void3D.targetRotY += 0.007; // gentle continuous rotation
                void3D.targetRotX += 0.002;

                var cosX = Math.cos(void3D.rotX), sinX = Math.sin(void3D.rotX);
                var cosY = Math.cos(void3D.rotY), sinY = Math.sin(void3D.rotY);

                // Responsive center & FOV
                var isDesktop = (window.innerWidth >= 1024);
                var cx = isDesktop ? (w * 0.58) : (w * 0.50);
                var cy = h * 0.50;
                var fov = Math.min(w, h) * (isDesktop ? 0.85 : 0.65);
                var cameraZ = 4.3;

                function projectPoint(p) {
                    var x1 = p.x * cosY + p.z * sinY;
                    var y1 = p.y;
                    var z1 = -p.x * sinY + p.z * cosY;

                    var x2 = x1;
                    var y2 = y1 * cosX - z1 * sinX;
                    var z2 = y1 * sinX + z1 * cosX;

                    var depth = z2 + cameraZ;
                    if (depth <= 0.1) depth = 0.1;
                    var scale = fov / depth;
                    return {
                        sx: cx + x2 * scale,
                        sy: cy + y2 * scale,
                        depth: depth,
                        z: z2
                    };
                }

                // Render background floating particles
                for (var pIdx = 0; pIdx < void3D.particles.length; pIdx++) {
                    var pt = void3D.particles[pIdx];
                    pt.y -= pt.speed;
                    if (pt.y < -3) pt.y = 3;
                    var pp = projectPoint(pt);
                    if (pp.sx >= 0 && pp.sx <= w && pp.sy >= 0 && pp.sy <= h) {
                        var pAlpha = Math.max(0, Math.min(1, pt.alpha * (1 - pp.depth / 8)));
                        ctx.fillStyle = 'rgba(192, 132, 252, ' + pAlpha + ')';
                        ctx.beginPath();
                        ctx.arc(pp.sx, pp.sy, pt.size * (fov / pp.depth * 0.009), 0, Math.PI * 2);
                        ctx.fill();
                    }
                }

                // Project 3D rings
                var numSteps = void3D.numSteps;
                var tubeSteps = void3D.tubeSteps;
                var projRings = [];
                for (var rIdx = 0; rIdx < numSteps; rIdx++) {
                    var pRing = [];
                    var ring = void3D.meshRings[rIdx];
                    for (var vIdx = 0; vIdx < tubeSteps; vIdx++) {
                        pRing.push(projectPoint(ring[vIdx]));
                    }
                    projRings.push(pRing);
                }

                ctx.save();
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';

                // Draw longitudinal wireframe ribbons (Purple & Indigo glow)
                for (var vIdx = 0; vIdx < tubeSteps; vIdx++) {
                    ctx.beginPath();
                    for (var rIdx = 0; rIdx < numSteps; rIdx++) {
                        var pt = projRings[rIdx][vIdx];
                        if (rIdx === 0) ctx.moveTo(pt.sx, pt.sy);
                        else ctx.lineTo(pt.sx, pt.sy);
                    }
                    ctx.closePath();

                    if (vIdx % 2 === 0) {
                        ctx.strokeStyle = 'rgba(168, 85, 247, 0.48)'; // purple-500
                        ctx.lineWidth = 1.3;
                        ctx.shadowColor = '#a855f7';
                        ctx.shadowBlur = 9;
                    } else {
                        ctx.strokeStyle = 'rgba(99, 102, 241, 0.38)'; // indigo-500
                        ctx.lineWidth = 0.95;
                        ctx.shadowColor = '#6366f1';
                        ctx.shadowBlur = 6;
                    }
                    ctx.stroke();
                }

                // Draw cross-section rings
                for (var rIdx = 0; rIdx < numSteps; rIdx += 2) {
                    ctx.beginPath();
                    var ring = projRings[rIdx];
                    for (var vIdx = 0; vIdx < tubeSteps; vIdx++) {
                        var pt = ring[vIdx];
                        if (vIdx === 0) ctx.moveTo(pt.sx, pt.sy);
                        else ctx.lineTo(pt.sx, pt.sy);
                    }
                    ctx.closePath();
                    var avgDepth = ring[0].depth;
                    var alpha = Math.max(0.08, Math.min(0.65, 1.8 / avgDepth));
                    ctx.strokeStyle = 'rgba(192, 132, 252, ' + alpha + ')';
                    ctx.lineWidth = 1;
                    ctx.shadowBlur = 4;
                    ctx.stroke();
                }

                // Glowing node points
                for (var rIdx = 0; rIdx < numSteps; rIdx += 4) {
                    for (var vIdx = 0; vIdx < tubeSteps; vIdx += 2) {
                        var pt = projRings[rIdx][vIdx];
                        var nAlpha = Math.max(0.2, Math.min(0.9, 1.6 / pt.depth));
                        ctx.fillStyle = 'rgba(232, 121, 249, ' + nAlpha + ')';
                        ctx.shadowColor = '#e879f9';
                        ctx.shadowBlur = 6;
                        ctx.beginPath();
                        ctx.arc(pt.sx, pt.sy, 1.5, 0, Math.PI * 2);
                        ctx.fill();
                    }
                }

                ctx.restore();
                void3D.animId = requestAnimationFrame(loop);
            }

            void3D.animId = requestAnimationFrame(loop);
        }

        function stopVoid3DCanvas() {
            void3D.isRunning = false;
            if (void3D.animId) {
                cancelAnimationFrame(void3D.animId);
                void3D.animId = null;
            }
        }

        // Initialize theme UI, 3D Canvas, and session check on DOM ready
        document.addEventListener('DOMContentLoaded', () => {
            updateThemeUI();
            if (window.innerWidth >= 768 && state.sidebarCollapsed) {
                applySidebarState();
            }
            initVoid3DCanvas();
            checkAuthSession();
        });
    </script>
</body>
</html>
